import type { HwyCandidatePipelineListResult, HwyCandidatePipelineRow } from '../../../domain/hwy/hwyCandidatePipeline';
import type { HwyCandidatePipelineStage } from '../../../domain/hwy/hwyCandidatePipelineCatalog';
import { assertHwyCandidatePipelineStageAccess } from './hwyCandidatePipelineAccess.service';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { hwyLegacyImportParityReady } from './hwyLegacyImportParityState.service';
import {
  queryLegacyCandidatePipelineCount,
  queryLegacyCandidatePipelineList,
  toCandidatePipelineWhereInput,
} from './hwyLegacyParityRead.service';
import { resolveHwyLegacyOperatorGeoScope } from './hwyLegacyOperatorGeoScope.service';
import { enrichHwyMemberDirectoryListRows } from './hwyMemberDirectoryDetailDisplay';
import { attachHwyCandidatePipelineNominationRoles } from './hwyCandidatePipelineNominationRole.service';
import { attachHwyCandidatePipelineElectoralCenterPaths } from './hwyCandidatePipelineElectoralCenterDisplay.service';
import { attachHwyCandidatePipelineResponsibilityPatchPaths } from './hwyCandidatePipelineResponsibilityPatchDisplay.service';
const DEFAULT_PAGE_SIZE = 25;
const INSTALL_PAGE_SIZE = 15;
const MAX_PAGE_SIZE = 100;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const ELECTORAL_PATH_JOIN = ' | ';

const buildCandidatePipelineElectoralPath = (row: Record<string, unknown>): string | null => {
  const parts = [
    row.nakhebJoinProvinceName,
    row.nakhebJoinCircleName,
    row.nakhebJoinTamvinName,
    row.nakhebJoinEghteraName,
  ]
    .map((part) => trim(part as string))
    .filter(Boolean);
  return parts.length > 0 ? parts.join(ELECTORAL_PATH_JOIN) : null;
};

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy candidate pipeline requires SQL Server control plane.');
  }
};

const clampPage = (
  page: number | undefined,
  pageSize: number | undefined,
  stage: HwyCandidatePipelineStage,
) => {
  const defaultSize = stage === 'install' ? INSTALL_PAGE_SIZE : DEFAULT_PAGE_SIZE;
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? defaultSize));
  const safePage = Math.max(1, page ?? 1);
  return { page: safePage, pageSize: safePageSize, offset: (safePage - 1) * safePageSize };
};

const composePipelineDisplayName = (row: Record<string, unknown>): string => (
  [
    row.firstName,
    row.fatherName,
    row.grandFatherName,
    row.lastName,
  ]
    .map((part) => trim(part as string))
    .filter(Boolean)
    .join(' ')
);

const mapRow = (row: Record<string, unknown>): HwyCandidatePipelineRow => ({
  id: trim(row.id as string),
  username: row.username ? trim(row.username as string) : null,
  userId: row.userId ? trim(row.userId as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  grandFatherName: row.grandFatherName ? trim(row.grandFatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
  displayFullName: trim(row.displayFullName as string) || composePipelineDisplayName(row) || null,
  avatarUrl: row.avatarUrl ? trim(row.avatarUrl as string) : null,
  birthYear: row.birthYear != null && String(row.birthYear).trim() !== '' ? String(row.birthYear).trim() : null,
  genderCode: row.genderCode
    ? trim(row.genderCode as string)
    : row.genderId
      ? trim(row.genderId as string)
      : null,
  membershipOn: row.membershipOn ? trim(row.membershipOn as string) : null,
  trackingCode: trim(row.trackingCode as string) || trim(row.tracking_code as string) || null,
  phone1: row.phone1 ? trim(row.phone1 as string) : null,
  phone2: row.phone2 ? trim(row.phone2 as string) : null,
  electoralDivisionPath: buildCandidatePipelineElectoralPath(row),
  genderId: row.genderId ? trim(row.genderId as string) : null,
  roleOfTarshih: row.roleOfTarshih ? trim(row.roleOfTarshih as string) : null,
  areaOfTarshih: row.areaOfTarshih ? String(row.areaOfTarshih) : null,
  dateOfTarshih: row.dateOfTarshih ? trim(row.dateOfTarshih as string) : null,
  moarasshehOfTarshih: row.moarasshehOfTarshih ? trim(row.moarasshehOfTarshih as string) : null,
  passedDoratHtml: row.passedDoratHtml ? String(row.passedDoratHtml) : null,
  areaId: row.areaId ? trim(row.areaId as string) : null,
  necessaryDoratPassed: row.necessaryDoratPassed === true || row.necessaryDoratPassed === 1,
  daysFrom: row.daysFrom != null ? Number(row.daysFrom) : null,
  lastSecurityProfileCanGetMasooliat: row.lastSecurityProfileCanGetMasooliat != null
    ? Number(row.lastSecurityProfileCanGetMasooliat)
    : null,
  isApprovedRow: row.isApprovedRow != null ? Number(row.isApprovedRow) : null,
  interviewOn: row.interviewOn ? trim(row.interviewOn as string) : null,
  interviewFinalResult: row.interviewFinalResult ? trim(row.interviewFinalResult as string) : null,
  roleId: row.roleId ? trim(row.roleId as string) : null,
  passedNecessaryDorat: row.passedNecessaryDorat === true || row.passedNecessaryDorat === 1,
  interviewFinalResultTitle: row.interviewFinalResultTitle ? trim(row.interviewFinalResultTitle as string) : null,
  profilePerfect: row.profilePerfect != null ? Number(row.profilePerfect) : null,
  allImagesApproved: row.allImagesApproved === true || row.allImagesApproved === 1,
  hasOath: row.hasOath === true || row.hasOath === 1,
  ...((): Record<string, unknown> => {
    const passthrough: Record<string, unknown> = {};
    for (const key of [
      'addrProvinceId',
      'addrRegionId',
      'addrMaktabId',
      'nakhebinRegionId',
      'nakhebinMaktabId',
      'nakhebJoinEghteraId',
      'nakhebJoinProvinceId',
      'nakhebJoinCircleId',
      'nakhebJoinTamvinId',
      'createdAt',
    ] as const) {
      const raw = row[key];
      if (raw !== null && raw !== undefined && String(raw).trim() !== '') {
        passthrough[key] = trim(String(raw));
      }
    }
    return passthrough;
  })(),
});

const PIPELINE_TOTAL_COLUMN = 'pipeline_total';

const HWY_MONTADHEMIN_LIST_SCOPE = 'HWY_Members_List_AlMontadhemin';

const finalizePipelineListRows = async (
  rows: HwyCandidatePipelineRow[],
  queryLang: string,
): Promise<HwyCandidatePipelineRow[]> => {
  if (rows.length === 0) {
    return rows;
  }
  const asRecords = rows as Record<string, unknown>[];
  for (const row of asRecords) {
    delete row.electoralDivisionPath;
    delete row.electoral_division_path;
  }
  await enrichHwyMemberDirectoryListRows(asRecords, queryLang, {
    listScopeLegacy: HWY_MONTADHEMIN_LIST_SCOPE,
    includeElectoralDivisionPath: false,
    includeListMembershipOnRegistrationFallback: true,
    includeListFaceAvatarsFromRegistration: true,
  });
  await attachHwyCandidatePipelineElectoralCenterPaths(asRecords, queryLang);
  await attachHwyCandidatePipelineResponsibilityPatchPaths(asRecords, queryLang);
  await attachHwyCandidatePipelineNominationRoles(asRecords);
  return asRecords as HwyCandidatePipelineRow[];
};

const mapPipelineListResult = (
  rows: Record<string, unknown>[],
): { total: number; rows: HwyCandidatePipelineRow[] } => {
  const total = rows.length > 0 ? Number(rows[0][PIPELINE_TOTAL_COLUMN] ?? 0) : 0;
  const mappedRows = rows.map((row) => {
    const { [PIPELINE_TOTAL_COLUMN]: _total, ...rest } = row;
    return mapRow(rest);
  });
  return { total, rows: mappedRows };
};

const buildProcBase = async (
  input: {
    stage: HwyCandidatePipelineStage;
    listType?: string;
    roleId?: string;
    isApproved?: string;
    approveState?: string;
    passedOrNot?: string;
    interviewApproveState?: string;
    nakhebProvinceId?: string;
    nakhebCircleId?: string;
    nakhebTamvinId?: string;
    dateStart?: string;
    dateEnd?: string;
    username?: string;
    phone?: string;
    genderId?: string;
    actorUserName?: string;
  },
  roleNames: readonly string[],
  actorUsername?: string | null,
) => {
  const geo = await resolveHwyLegacyOperatorGeoScope(actorUsername, roleNames);
  return {
    stage: input.stage,
    list_type: trim(input.listType) || null,
    role_id: trim(input.roleId) || null,
    is_approved: trim(input.isApproved) || null,
    approve_state: trim(input.approveState) || null,
    passed_or_not: trim(input.passedOrNot) || null,
    interview_approve_state: trim(input.interviewApproveState) || null,
    scope_unrestricted: geo.unrestricted ? 1 : 0,
    nakheb_province_id: input.nakhebProvinceId ? Number(input.nakhebProvinceId) : null,
    nakheb_circle_id: input.nakhebCircleId ? Number(input.nakhebCircleId) : null,
    nakheb_tamvin_id: input.nakhebTamvinId ? Number(input.nakhebTamvinId) : null,
    date_start: trim(input.dateStart) || null,
    date_end: trim(input.dateEnd) || null,
    username: trim(input.username) || null,
    phone: trim(input.phone) || null,
    gender_id: trim(input.genderId) || null,
    actor_user_name: trim(input.actorUserName) || null,
    area_limit_id: geo.unrestricted ? null : geo.areaLimitId,
    geo_limits_csv: geo.unrestricted ? null : geo.geoLimitsCsv,
  };
};

export const listHwyCandidatePipeline = async (
  input: {
    stage: HwyCandidatePipelineStage;
    listType?: string;
    roleId?: string;
    isApproved?: string;
    approveState?: string;
    passedOrNot?: string;
    interviewApproveState?: string;
    nakhebProvinceId?: string;
    nakhebCircleId?: string;
    nakhebTamvinId?: string;
    dateStart?: string;
    dateEnd?: string;
    username?: string;
    phone?: string;
    genderId?: string;
    actorUserName?: string;
    page?: number;
    pageSize?: number;
    queryLang?: string;
  },
  roleNames: readonly string[],
  actorUsername?: string | null,
): Promise<HwyCandidatePipelineListResult> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess(input.stage, roleNames);
  await ensureHwyDbObjects();

  const { page, pageSize, offset } = clampPage(input.page, input.pageSize, input.stage);
  const queryLang = trim(input.queryLang) || 'ar';
  const procBase = await buildProcBase(input, roleNames, actorUsername);

  if (!(await hwyLegacyImportParityReady())) {
    const whereInput = toCandidatePipelineWhereInput(procBase, input.stage);
    const [total, legacyRows] = await Promise.all([
      queryLegacyCandidatePipelineCount(whereInput),
      queryLegacyCandidatePipelineList(whereInput, offset, pageSize),
    ]);
    const rows = await finalizePipelineListRows(legacyRows.map(mapRow), queryLang);
    return {
      total,
      page,
      pageSize,
      rows,
      parityDataSource: 'legacy-read' as const,
    };
  }

  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_candidate_pipeline_list', {
    ...procBase,
    offset,
    page_size: pageSize,
  });

  const { total, rows: mappedRows } = mapPipelineListResult(rows);
  const finalizedRows = await finalizePipelineListRows(mappedRows, queryLang);

  return { total, page, pageSize, rows: finalizedRows, parityDataSource: 'edge' as const };
};

export const applyHwyCandidatePipelineInstallAction = async (
  input: { memberId: string; areaId: string; action: 'approve' | 'reject'; actorUsername?: string | null },
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess('install', roleNames);
  await ensureHwyDbObjects();

  const memberId = trim(input.memberId);
  const areaId = trim(input.areaId);
  if (!memberId || !areaId) {
    throw new Error('memberId and areaId are required.');
  }

  const procName = input.action === 'approve'
    ? 'hwy_candidate_pipeline_install_approve'
    : 'hwy_candidate_pipeline_install_reject';

  await execHwyProcedure(procName, {
    member_id: Number(memberId),
    area_id: Number(areaId),
    actor: trim(input.actorUsername) || null,
  });
};

export type HwyCandidatePipelineSecurityProfileInput = {
  memberId: string;
  canGetIdentityCard: number;
  canGetIdentityCardNote?: string;
  canGetMasooliat: number;
  canGetMasooliatNote?: string;
  canBeMemberOfAammeh: number;
  canBeMemberOfAammehNote?: string;
  allowsResponsibility: number;
  allowsResponsibilityNote?: string;
  actorUsername?: string | null;
};

export const applyHwyCandidatePipelineSecurityRecord = async (
  input: HwyCandidatePipelineSecurityProfileInput,
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess('security', roleNames);
  await ensureHwyDbObjects();

  const memberId = trim(input.memberId);
  if (!memberId) {
    throw new Error('memberId is required.');
  }

  await execHwyProcedure('hwy_candidate_pipeline_security_record', {
    member_id: Number(memberId),
    can_get_identity_card: input.canGetIdentityCard,
    can_get_identity_card_note: trim(input.canGetIdentityCardNote) || null,
    can_get_masooliat: input.canGetMasooliat,
    can_get_masooliat_note: trim(input.canGetMasooliatNote) || null,
    can_be_member_of_aammeh: input.canBeMemberOfAammeh,
    can_be_member_of_aammeh_note: trim(input.canBeMemberOfAammehNote) || null,
    allows_responsibility: input.allowsResponsibility,
    allows_responsibility_note: trim(input.allowsResponsibilityNote) || null,
    actor: trim(input.actorUsername) || null,
  });
};

