import sql from 'mssql';
import { findHwyBaseInfoItemId } from './seedHwyBaseInfo';
import {
  HWY_INSTITUTES_CATALOG,
  HWY_INSTITUTES_SEED_ROWS,
  type HwyInstituteSeed,
} from './hwyInstitutesCatalog';
import {
  connectMssqlControlPlane,
  createPostgresPool,
  resolveHwyDefaultDataSource,
} from '../hwyDataSource';

const INSTITUTES: HwyInstituteSeed[] = HWY_INSTITUTES_SEED_ROWS;

const realignLegacyInstituteIdsPg = async (
  pool: ReturnType<typeof createPostgresPool>,
): Promise<void> => {
  for (const row of HWY_INSTITUTES_CATALOG) {
    if (row.legacyOrganizationId === row.id) continue;
    await pool.query(
      `
      DELETE FROM hwy_member_institutes mi
      WHERE mi.institute_id = $2
        AND EXISTS (
          SELECT 1 FROM hwy_member_institutes x
          WHERE x.member_id = mi.member_id AND x.institute_id = $1
        )
      `,
      [row.id, row.legacyOrganizationId],
    );
    await pool.query(
      `UPDATE hwy_member_institutes SET institute_id = $1 WHERE institute_id = $2`,
      [row.id, row.legacyOrganizationId],
    );
    await pool.query(
      `UPDATE hwy_member_list_defs SET institute_id = $1 WHERE institute_id = $2`,
      [row.id, row.legacyOrganizationId],
    );
    await pool.query(
      `UPDATE hwy_members SET referrer_institute_id = $1 WHERE referrer_institute_id = $2`,
      [row.id, row.legacyOrganizationId],
    );
    await pool.query(`DELETE FROM hwy_institutes WHERE id = $1`, [row.legacyOrganizationId]);
  }
};

const realignLegacyInstituteIdsMssql = async (pool: sql.ConnectionPool): Promise<void> => {
  for (const row of HWY_INSTITUTES_CATALOG) {
    if (row.legacyOrganizationId === row.id) continue;
    await pool.request()
      .input('new_id', sql.Int, row.id)
      .input('legacy_id', sql.Int, row.legacyOrganizationId)
      .query(`
        DELETE mi
        FROM dbo.hwy_member_institutes mi
        WHERE mi.institute_id = @legacy_id
          AND EXISTS (
            SELECT 1 FROM dbo.hwy_member_institutes x
            WHERE x.member_id = mi.member_id AND x.institute_id = @new_id
          );

        UPDATE dbo.hwy_member_institutes SET institute_id = @new_id WHERE institute_id = @legacy_id;
        UPDATE dbo.hwy_member_list_defs SET institute_id = @new_id WHERE institute_id = @legacy_id;
        UPDATE dbo.hwy_members SET referrer_institute_id = @new_id WHERE referrer_institute_id = @legacy_id;
        DELETE FROM dbo.hwy_institutes WHERE id = @legacy_id;
      `);
  }
};

const upsertInstitutePg = async (
  pool: ReturnType<typeof createPostgresPool>,
  row: HwyInstituteSeed,
): Promise<void> => {
  await pool.query(
    `
    INSERT INTO hwy_institutes (
      id, code, title_ar, is_active, allows_self_registration, allows_invite,
      invite_expires_after_days, hide_member_phones, has_dedicated_list
    ) VALUES ($1, $2, $3, TRUE, TRUE, $4, $5, FALSE, $6)
    ON CONFLICT (id) DO UPDATE SET
      code = EXCLUDED.code,
      title_ar = EXCLUDED.title_ar,
      allows_invite = EXCLUDED.allows_invite,
      invite_expires_after_days = EXCLUDED.invite_expires_after_days,
      has_dedicated_list = EXCLUDED.has_dedicated_list,
      updated_at = NOW()
    `,
    [row.id, row.code, row.titleAr, row.allowsInvite, row.inviteExpiresAfterDays, row.hasDedicatedList],
  );
};

const upsertInstituteMssql = async (pool: sql.ConnectionPool, row: HwyInstituteSeed): Promise<void> => {
  await pool.request()
    .input('id', sql.Int, row.id)
    .input('code', sql.NVarChar, row.code)
    .input('title_ar', sql.NVarChar, row.titleAr)
    .input('allows_invite', sql.Bit, row.allowsInvite)
    .input('invite_expires_after_days', sql.Int, row.inviteExpiresAfterDays)
    .input('has_dedicated_list', sql.Bit, row.hasDedicatedList)
    .query(`
      MERGE dbo.hwy_institutes AS t
      USING (SELECT @id AS id) AS s ON t.id = s.id
      WHEN MATCHED THEN UPDATE SET
        code = @code,
        title_ar = @title_ar,
        allows_invite = @allows_invite,
        invite_expires_after_days = @invite_expires_after_days,
        has_dedicated_list = @has_dedicated_list,
        updated_at = SYSUTCDATETIME()
      WHEN NOT MATCHED THEN INSERT (
        id, code, title_ar, is_active, allows_self_registration, allows_invite,
        invite_expires_after_days, hide_member_phones, has_dedicated_list
      ) VALUES (
        @id, @code, @title_ar, 1, 1, @allows_invite, @invite_expires_after_days, 0, @has_dedicated_list
      );
    `);
};

const upsertListDefPg = async (
  pool: ReturnType<typeof createPostgresPool>,
  params: {
    code: string;
    titleAr: string;
    listLogicId: string;
    instituteId: number | null;
    predicateRef: string | null;
    sortOrder: number;
  },
): Promise<void> => {
  await pool.query(
    `
    INSERT INTO hwy_member_list_defs (code, title_ar, list_logic_code, institute_id, predicate_ref, sort_order, is_active)
    VALUES ($1, $2, $3, $4, $5, $6, TRUE)
    ON CONFLICT (code) DO UPDATE SET
      title_ar = EXCLUDED.title_ar,
      list_logic_code = EXCLUDED.list_logic_code,
      institute_id = EXCLUDED.institute_id,
      predicate_ref = EXCLUDED.predicate_ref,
      updated_at = NOW()
    `,
    [params.code, params.titleAr, params.listLogicId, params.instituteId, params.predicateRef, params.sortOrder],
  );
};

const upsertListDefMssql = async (
  pool: sql.ConnectionPool,
  params: {
    code: string;
    titleAr: string;
    listLogicId: string;
    instituteId: number | null;
    predicateRef: string | null;
    sortOrder: number;
  },
): Promise<void> => {
  await pool.request()
    .input('code', sql.NVarChar, params.code)
    .input('title_ar', sql.NVarChar, params.titleAr)
    .input('list_logic_code', sql.NVarChar, params.listLogicId)
    .input('institute_id', sql.Int, params.instituteId)
    .input('predicate_ref', sql.NVarChar, params.predicateRef)
    .input('sort_order', sql.Int, params.sortOrder)
    .query(`
      MERGE dbo.hwy_member_list_defs AS t
      USING (SELECT @code AS code) AS s ON t.code = s.code
      WHEN MATCHED THEN UPDATE SET
        title_ar = @title_ar,
        list_logic_code = @list_logic_code,
        institute_id = @institute_id,
        predicate_ref = @predicate_ref,
        sort_order = @sort_order,
        updated_at = SYSUTCDATETIME()
      WHEN NOT MATCHED THEN INSERT (
        code, title_ar, list_logic_code, institute_id, predicate_ref, sort_order, is_active
      ) VALUES (
        @code, @title_ar, @list_logic_code, @institute_id, @predicate_ref, @sort_order, 1
      );
    `);
};

export async function seedHwyInstitutes(): Promise<number> {
  const { kind, source } = resolveHwyDefaultDataSource();
  const instituteLogicId = await findHwyBaseInfoItemId('Member List Logic', 'institute');
  const predicateLogicId = await findHwyBaseInfoItemId('Member List Logic', 'predicate');

  if (kind === 'postgresql') {
    const pool = createPostgresPool(source);
    try {
      for (const row of INSTITUTES) {
        await upsertInstitutePg(pool, row);
        if (row.hasDedicatedList) {
          await upsertListDefPg(pool, {
            code: `list_institute_${row.code}`,
            titleAr: row.titleAr,
            listLogicId: instituteLogicId,
            instituteId: row.id,
            predicateRef: null,
            sortOrder: row.id,
          });
        }
      }
      await upsertListDefPg(pool, {
        code: 'list_kashafeh',
        titleAr: 'كشافة',
        listLogicId: predicateLogicId,
        instituteId: null,
        predicateRef: 'HWY_Members_List_AlMontadhemin_Kashafeh',
        sortOrder: 9001,
      });
    await upsertListDefPg(pool, {
      code: 'list_taleb_jameee',
      titleAr: 'طلاب جامعيين خارج همم',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_AlMontadhemin_TalebJameee',
      sortOrder: 9002,
    });
    await upsertListDefPg(pool, {
      code: 'list_waited_call_center',
      titleAr: 'الطلبات قيد الانتظار',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Waited_1',
      sortOrder: 100,
    });
    await upsertListDefPg(pool, {
      code: 'list_waited_local',
      titleAr: 'بانتظار التوثيق المحلي',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Waited_2',
      sortOrder: 101,
    });
    await upsertListDefPg(pool, {
      code: 'list_image_fix_todo',
      titleAr: 'معالجة صور التسجيل',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Imagefix',
      sortOrder: 102,
    });
      await realignLegacyInstituteIdsPg(pool);
    return INSTITUTES.length;
    } finally {
      await pool.end();
    }
  }

  const pool = await connectMssqlControlPlane();
  try {
    for (const row of INSTITUTES) {
      await upsertInstituteMssql(pool, row);
      if (row.hasDedicatedList) {
        await upsertListDefMssql(pool, {
          code: `list_institute_${row.code}`,
          titleAr: row.titleAr,
          listLogicId: instituteLogicId,
          instituteId: row.id,
          predicateRef: null,
          sortOrder: row.id,
        });
      }
    }
    await upsertListDefMssql(pool, {
      code: 'list_kashafeh',
      titleAr: 'كشافة',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_AlMontadhemin_Kashafeh',
      sortOrder: 9001,
    });
    await upsertListDefMssql(pool, {
      code: 'list_taleb_jameee',
      titleAr: 'طلاب جامعيين خارج همم',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_AlMontadhemin_TalebJameee',
      sortOrder: 9002,
    });
    await upsertListDefMssql(pool, {
      code: 'list_waited_call_center',
      titleAr: 'الطلبات قيد الانتظار',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Waited_1',
      sortOrder: 100,
    });
    await upsertListDefMssql(pool, {
      code: 'list_waited_local',
      titleAr: 'بانتظار التوثيق المحلي',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Waited_2',
      sortOrder: 101,
    });
    await upsertListDefMssql(pool, {
      code: 'list_image_fix_todo',
      titleAr: 'معالجة صور التسجيل',
      listLogicId: predicateLogicId,
      instituteId: null,
      predicateRef: 'HWY_Members_List_Imagefix',
      sortOrder: 102,
    });
    await realignLegacyInstituteIdsMssql(pool);
    return INSTITUTES.length;
  } finally {
    await pool.close();
  }
}
