export const HWY_MEHANI_UNION_SYNC_PLACEHOLDER_SHORT_NAME = 'mehani_union_sync_placeholder';

export const HWY_MEHANI_UNION_DEGREE_SYNC_PLACEHOLDER_SHORT_NAME =
  'mehani_union_degree_sync_placeholder';

export const HWY_MEHANI_PROFESSIONAL_BASE_INFO_PLACEHOLDER_SHORT_NAMES = [
  HWY_MEHANI_UNION_SYNC_PLACEHOLDER_SHORT_NAME,
  HWY_MEHANI_UNION_DEGREE_SYNC_PLACEHOLDER_SHORT_NAME,
] as const;

export type HwyMehaniProfessionalBaseInfoPlaceholderShortName =
  (typeof HWY_MEHANI_PROFESSIONAL_BASE_INFO_PLACEHOLDER_SHORT_NAMES)[number];

export const isHwyMehaniProfessionalBaseInfoPlaceholderShortName = (
  shortName: string | null | undefined,
): boolean => {
  const normalized = String(shortName ?? '').trim();
  return (HWY_MEHANI_PROFESSIONAL_BASE_INFO_PLACEHOLDER_SHORT_NAMES as readonly string[]).includes(
    normalized,
  );
};
