/**
 * Read-only list/count against live MembersV2 when edge ETL/views are incomplete.
 * Never writes to legacy — ApplicationIntent ReadOnly only.
 */
import type { HwyCandidatePipelineStage } from '../../../domain/hwy/hwyCandidatePipelineCatalog';
import type { HwyCardFlowStep } from '../../../domain/hwy/hwyCardFlowCatalog';
import { legacyCandidatePipelineViewForStage } from '../../../domain/hwy/hwyCandidatePipelineViewNames';
import {
  buildHwyCandidatePipelineWhereSql,
  buildHwyCardFlowWhereSql,
  type HwyCandidatePipelineWhereInput,
  type HwyCardFlowWhereInput,
} from './hwyLegacyParitySqlBuilders';

const latestStepSubquery = (alias: string): string =>
  `(SELECT TOP 1 FS.step_id FROM dbo.hwy_member_card_printing_flow_steps FS WITH (NOLOCK) WHERE FS.member_id=${alias}.Id ORDER BY FS.step_on DESC, FS.id DESC)`;

export const queryLegacyCandidatePipelineCount = async (
  input: HwyCandidatePipelineWhereInput,
): Promise<number> => {
  const view = legacyCandidatePipelineViewForStage(input.stage);
  const where = buildHwyCandidatePipelineWhereSql(input);
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(
      `SELECT COUNT(*) AS total FROM dbo.${view} V WITH (NOLOCK) WHERE 1=1${where}`,
    );
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

export const queryLegacyCandidatePipelineList = async (
  input: HwyCandidatePipelineWhereInput,
  offset: number,
  pageSize: number,
): Promise<Record<string, unknown>[]> => {
  const view = legacyCandidatePipelineViewForStage(input.stage);
  const where = buildHwyCandidatePipelineWhereSql(input);
  let areaCol = '';
  if (input.stage === 'security') {
    areaCol = `, V.DaysFrom AS daysFrom, CAST(V.IsApproved AS INT) AS isApprovedRow, (SELECT TOP 1 SP.can_get_masooliat FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=V.Id ORDER BY SP.created_on DESC) AS lastSecurityProfileCanGetMasooliat`;
  } else if (input.stage === 'interview') {
    areaCol = `, CONVERT(VARCHAR(32), V.InterviewOn, 126) AS interviewOn, CAST(V.InterviewFinalResult AS VARCHAR(32)) AS interviewFinalResult, (SELECT TOP 1 B.Title FROM dbo.hwy_member_interviews_2022 I2022 WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation B WITH (NOLOCK) ON B.Id = I2022.final_result WHERE I2022.member_id = V.Id ORDER BY I2022.created_on DESC) AS interviewFinalResultTitle, CAST(V.RoleId AS VARCHAR(32)) AS roleId`;
  } else if (input.stage === 'courses') {
    areaCol = `, CAST(V.PassedNecessaryDorat AS BIT) AS passedNecessaryDorat`;
  } else if (input.stage === 'install') {
    areaCol = `, CAST(V.AreaId AS VARCHAR(32)) AS areaId, CAST(V.NecessaryDoratPassed AS BIT) AS necessaryDoratPassed, V.InterviewFinalResultTitle AS interviewFinalResultTitle, CAST(V.ProfilePerfect AS INT) AS profilePerfect, CAST(V.AllImagesApproved AS BIT) AS allImagesApproved, CAST(V.HasOath AS BIT) AS hasOath`;
  }

  const passedDoratCol =
    input.stage === 'courses'
      ? 'V.PassedDorat AS passedDoratHtml'
      : 'CAST(NULL AS NVARCHAR(MAX)) AS passedDoratHtml';

  const sql = `
    SELECT
      CAST(V.Id AS VARCHAR(32)) AS id,
      V.UserName AS username,
      CAST(V.UserId AS VARCHAR(32)) AS userId,
      V.FirstName AS firstName,
      V.FatherName AS fatherName,
      V.GrandFatherName AS grandFatherName,
      V.LastName AS lastName,
      V.Phone1 AS phone1,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id = V.NakhebJoinProvinceId) AS nakhebJoinProvinceName,
      (SELECT TOP 1 C.CircleName FROM dbo.HWY_H_Circles C WITH (NOLOCK) WHERE C.CircleId = V.NakhebJoinCircleId) AS nakhebJoinCircleName,
      (SELECT TOP 1 T.TamvinName FROM dbo.HWY_H_Tamvinat T WITH (NOLOCK) WHERE T.TamvinId = V.NakhebJoinTamvinId) AS nakhebJoinTamvinName,
      CAST(V.GenderId AS VARCHAR(32)) AS genderId,
      V.RoleOfTarshih AS roleOfTarshih,
      V.AreaOfTarshih AS areaOfTarshih,
      CONVERT(VARCHAR(32), V.DateOfTarshih, 126) AS dateOfTarshih,
      V.MoarasshehOfTarshih AS moarasshehOfTarshih,
      ${passedDoratCol}
      ${areaCol}
    FROM dbo.${view} V WITH (NOLOCK)
    WHERE 1=1${where}
    ORDER BY V.DateOfTarshih DESC, V.Id DESC
    OFFSET ${offset} ROWS FETCH NEXT ${pageSize} ROWS ONLY
  `;

  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(sql);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};

