export const queryLegacyCardFlowList = async (
  input: HwyCardFlowWhereInput,
  offset: number,
  pageSize: number,
): Promise<Record<string, unknown>[]> => {
  const where = buildHwyCardFlowWhereSql(input);
  const latest = latestStepSubquery('M');
  const sql = `
    SELECT
      CAST(M.Id AS VARCHAR(32)) AS id,
      M.UserName AS username,
      M.FirstName AS firstName,
      M.FatherName AS fatherName,
      M.GrandFatherName AS grandFatherName,
      M.LastName AS lastName,
      M.Phone1 AS phone1,
      CAST(M.GenderId AS VARCHAR(32)) AS genderId,
      CAST(M.CardFlowLastStatusId AS VARCHAR(32)) AS cardFlowLastStatusId,
      CONVERT(VARCHAR(32), M.CardFlowStartedOn, 126) AS cardFlowStartedOn,
      CAST(M.CardFlowVisibility AS BIT) AS cardFlowVisibility,
      CAST(${latest} AS VARCHAR(32)) AS latestStepId,
      (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=M.Id ORDER BY SP.created_on DESC) AS lastCanGetIdentityCard,
      (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=M.Id ORDER BY SP.created_on DESC) AS lastSecurityProfileCanGetIdentityCard,
      ISNULL(M.Stat_FieldsCompleted, 0) AS statFieldsCompleted,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id=M.NakhebJoinProvinceId) AS nakhebJoinProvinceName,
      (SELECT TOP 1 C.CircleName FROM dbo.HWY_H_Circles C WITH (NOLOCK) WHERE C.CircleId=M.NakhebJoinCircleId) AS nakhebJoinCircleName,
      (SELECT TOP 1 T.TamvinName FROM dbo.HWY_H_Tamvinat T WITH (NOLOCK) WHERE T.TamvinId=M.NakhebJoinTamvinId) AS nakhebJoinTamvinName
    FROM dbo.HWY_Members M WITH (NOLOCK)
    WHERE M.MembershipStatus=10851${where}
    ORDER BY M.CardFlowStartedOn DESC, M.Id DESC
    OFFSET ${offset} ROWS FETCH NEXT ${pageSize} ROWS ONLY
  `;
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(sql);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};

export const queryLegacyCardFlowPrintedHistoryCount = async (username: string | null): Promise<number> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const request = pool.request();
    const userFilter = username?.trim() || null;
    request.input('username', userFilter);
    const result = await request.query(`
      SELECT COUNT(*) AS total
      FROM dbo.hwy_member_card_printing_history H WITH (NOLOCK)
      LEFT JOIN dbo.HWY_Members M WITH (NOLOCK) ON M.Id = H.member_id
      WHERE @username IS NULL OR M.UserName LIKE N'%' + @username + N'%'
    `);
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

export const queryLegacyCardFlowPrintedHistoryList = async (
  username: string | null,
  offset: number,
  pageSize: number,
): Promise<Record<string, unknown>[]> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const request = pool.request();
    request.input('username', username?.trim() || null);
    request.input('offset', offset);
    request.input('page_size', pageSize);
    const result = await request.query(`
      SELECT
        CAST(H.id AS VARCHAR(64)) AS id,
        CAST(H.member_id AS VARCHAR(32)) AS memberId,
        H.rfid AS rfid,
        CAST(H.type_id AS VARCHAR(32)) AS typeId,
        BI.Title AS typeTitle,
        CONVERT(VARCHAR(32), H.expiration_date, 126) AS expirationDate,
        H.created_by AS createdBy,
        CONVERT(VARCHAR(32), H.created_on, 126) AS createdOn,
        M.UserName AS username,
        M.FirstName AS firstName,
        M.FatherName AS fatherName,
        M.LastName AS lastName
      FROM dbo.hwy_member_card_printing_history H WITH (NOLOCK)
      LEFT JOIN dbo.HWY_Members M WITH (NOLOCK) ON M.Id = H.member_id
      LEFT JOIN dbo.HWY_BaseInformation BI WITH (NOLOCK) ON BI.Id = H.type_id
      WHERE @username IS NULL OR M.UserName LIKE N'%' + @username + N'%'
      ORDER BY H.created_on DESC
      OFFSET @offset ROWS FETCH NEXT @page_size ROWS ONLY
    `);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};

export const queryLegacyMeetingDefinitions = async (): Promise<Record<string, unknown>[]> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(`
      SELECT CAST(bi.Id AS VARCHAR(32)) AS id, bi.Title AS title, CAST(bi.ViewOrder AS INT) AS viewOrder
      FROM dbo.HWY_BaseInformation bi WITH (NOLOCK)
      WHERE bi.ParentId = 214040
      ORDER BY bi.ViewOrder ASC, bi.Id ASC
    `);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};

export const queryLegacyMeetingInstancesCount = async (
  meetingId: number | null,
  username: string | null,
): Promise<number> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const request = pool.request();
    request.input('meeting_id', meetingId);
    request.input('username', username?.trim() || null);
    const result = await request.query(`
      SELECT COUNT(*) AS total
      FROM dbo.HWY_Meetings_Instances mi WITH (NOLOCK)
      WHERE (@meeting_id IS NULL OR mi.MeetingId = @meeting_id)
        AND (
          @username IS NULL
          OR mi.Id IN (
            SELECT H.InstanceId
            FROM dbo.HWY_Meetings_Hazerin H WITH (NOLOCK)
            INNER JOIN dbo.HWY_Members M WITH (NOLOCK) ON M.Id = H.member_id
            WHERE M.UserName LIKE N'%' + @username + N'%'
          )
        )
    `);
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

export const queryLegacyMeetingInstancesList = async (
  meetingId: number | null,
  username: string | null,
  offset: number,
  pageSize: number,
): Promise<Record<string, unknown>[]> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const request = pool.request();
    request.input('meeting_id', meetingId);
    request.input('username', username?.trim() || null);
    request.input('offset', offset);
    request.input('page_size', pageSize);
    const result = await request.query(`
      SELECT
        CAST(mi.Id AS VARCHAR(32)) AS id,
        CAST(mi.MeetingId AS VARCHAR(32)) AS meetingId,
        CAST(creator.Id AS VARCHAR(32)) AS memberId,
        CONVERT(VARCHAR(32), mi.CreatedOn, 126) AS createdOn,
        CONVERT(VARCHAR(32), mi.EventDate, 126) AS eventDate,
        NULL AS title,
        bi.Title AS meetingTitle,
        creator.UserName AS username,
        creator.FirstName AS firstName,
        creator.FatherName AS fatherName,
        creator.LastName AS lastName,
        (SELECT COUNT(*) FROM dbo.HWY_Meetings_Hazerin H WITH (NOLOCK) WHERE H.InstanceId = mi.Id) AS hazerinCount,
        (SELECT COUNT(*) FROM dbo.HWY_Meetings_Members MM WITH (NOLOCK) WHERE MM.MeetingId = mi.MeetingId AND MM.IsMemberYet = 1) AS membersYetCount,
        (SELECT COUNT(*) FROM dbo.HWY_Meetings_Members MM WITH (NOLOCK) WHERE MM.MeetingId = mi.MeetingId AND MM.IsMemberYet = 0) AS membersNotCount
      FROM dbo.HWY_Meetings_Instances mi WITH (NOLOCK)
      LEFT JOIN dbo.HWY_BaseInformation bi WITH (NOLOCK) ON bi.Id = mi.MeetingId
      LEFT JOIN dbo.HWY_Members creator WITH (NOLOCK) ON creator.UserName = mi.CreatedBy
      WHERE (@meeting_id IS NULL OR mi.MeetingId = @meeting_id)
        AND (
          @username IS NULL
          OR mi.Id IN (
            SELECT H.InstanceId
            FROM dbo.HWY_Meetings_Hazerin H WITH (NOLOCK)
            INNER JOIN dbo.HWY_Members M WITH (NOLOCK) ON M.Id = H.member_id
            WHERE M.UserName LIKE N'%' + @username + N'%'
          )
        )
      ORDER BY mi.CreatedOn DESC
      OFFSET @offset ROWS FETCH NEXT @page_size ROWS ONLY
    `);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};

export const toCandidatePipelineWhereInput = (
  procBase: Record<string, unknown>,
  stage: HwyCandidatePipelineStage,
): HwyCandidatePipelineWhereInput => ({
  stage,
  listType: procBase.list_type as string | null,
  roleId: procBase.role_id as string | null,
  isApproved: procBase.is_approved as string | null,
  approveState: procBase.approve_state as string | null,
  passedOrNot: procBase.passed_or_not as string | null,
  interviewApproveState: procBase.interview_approve_state as string | null,
  scopeUnrestricted: procBase.scope_unrestricted === 1,
  nakhebProvinceId: procBase.nakheb_province_id as number | null,
  nakhebCircleId: procBase.nakheb_circle_id as number | null,
  nakhebTamvinId: procBase.nakheb_tamvin_id as number | null,
  dateStart: procBase.date_start as string | null,
  dateEnd: procBase.date_end as string | null,
  username: procBase.username as string | null,
  phone: procBase.phone as string | null,
  genderId: procBase.gender_id as string | null,
  actorUserName: procBase.actor_user_name as string | null,
  areaLimitId: procBase.area_limit_id as number | null,
  geoLimitsCsv: procBase.geo_limits_csv as string | null,
});

