/**
 * Legacy MembersV2 parity tables copied onto the AppEndO control-plane (edge) DB.
 * Source reads use `legacy` names; edge SQL/procs use `edge` snake_case names.
 */
export const HWY_MEMBER_EDGE_PARITY_TABLES = {
  areaLimits: {
    legacy: 'HWY_Members_AreaLimits',
    edge: 'hwy_member_area_limits',
  },
  cardPrintingFlowSteps: {
    legacy: 'HWY_Members_CardPrintingFlowSteps',
    edge: 'hwy_member_card_printing_flow_steps',
  },
  cardPrintingHistory: {
    legacy: 'HWY_Members_CardPrintingHistory',
    edge: 'hwy_member_card_printing_history',
  },
  interviews2022: {
    legacy: 'HWY_Members_Interviews_2022',
    edge: 'hwy_member_interviews_2022',
  },
  interviews2022Hazerin: {
    legacy: 'HWY_Members_Interviews_2022_R_Hazerin',
    edge: 'hwy_member_interviews_2022_hazerin',
  },
  securityStatuses: {
    legacy: 'HWY_Members_SecurityStatuses',
    edge: 'hwy_member_security_statuses',
  },
  securityProfileHistory: {
    legacy: 'HWY_Members_SecurityProfile',
    edge: 'hwy_member_security_profile_history',
  },
} as const;

export type HwyMemberEdgeParityTableKey = keyof typeof HWY_MEMBER_EDGE_PARITY_TABLES;

/** Ordered list for ETL copy (legacy → edge). */
export const HWY_MEMBER_EDGE_PARITY_TABLE_ETL_ORDER: ReadonlyArray<{
  key: HwyMemberEdgeParityTableKey;
  legacy: string;
  edge: string;
}> = [
  { key: 'securityStatuses', ...HWY_MEMBER_EDGE_PARITY_TABLES.securityStatuses },
  { key: 'securityProfileHistory', ...HWY_MEMBER_EDGE_PARITY_TABLES.securityProfileHistory },
  { key: 'cardPrintingFlowSteps', ...HWY_MEMBER_EDGE_PARITY_TABLES.cardPrintingFlowSteps },
  { key: 'cardPrintingHistory', ...HWY_MEMBER_EDGE_PARITY_TABLES.cardPrintingHistory },
  { key: 'interviews2022', ...HWY_MEMBER_EDGE_PARITY_TABLES.interviews2022 },
  { key: 'interviews2022Hazerin', ...HWY_MEMBER_EDGE_PARITY_TABLES.interviews2022Hazerin },
  { key: 'areaLimits', ...HWY_MEMBER_EDGE_PARITY_TABLES.areaLimits },
];

/** `dbo.hwy_member_*` for inline SQL on the edge DB. */
export const hwyEdgeParityTableSql = (key: HwyMemberEdgeParityTableKey): string =>
  `dbo.${HWY_MEMBER_EDGE_PARITY_TABLES[key].edge}`;
