import {
  buildHwyEmployeesListLegacyWhereSql,
  buildHwyEmployeesListProcParams,
  type HwyEmployeesListSearchInput,
} from '../../../domain/hwy/hwyEmployeesListFilterMapping';

const employeeBaseWhere = `
  M.MembershipStatus=10851
  AND M.UserId IS NOT NULL
  AND (SELECT COUNT(*) FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=M.UserId AND URR.Approved=1) >= 1
`;

export const queryLegacyEmployeesListCount = async (
  input: HwyEmployeesListSearchInput,
): Promise<number> => {
  const params = buildHwyEmployeesListProcParams(input);
  const filterWhere = buildHwyEmployeesListLegacyWhereSql(params);
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(
      `SELECT COUNT(*) AS total FROM dbo.HWY_Members M WITH (NOLOCK) WHERE ${employeeBaseWhere}${filterWhere}`,
    );
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

export const queryLegacyEmployeesList = async (
  input: HwyEmployeesListSearchInput,
): Promise<Record<string, unknown>[]> => {
  const params = buildHwyEmployeesListProcParams(input);
  const filterWhere = buildHwyEmployeesListLegacyWhereSql(params);
  const sql = `
    SELECT
      CAST(M.Id AS VARCHAR(32)) AS id,
      M.UserName AS username,
      CAST(M.UserId AS VARCHAR(32)) AS userId,
      M.FirstName AS firstName,
      M.FatherName AS fatherName,
      M.GrandFatherName AS grandFatherName,
      M.LastName AS lastName,
      M.Phone1 AS phone1,
      CAST(M.GenderId AS VARCHAR(32)) AS genderId,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id = M.GenderId) AS genderIdTitle,
      ISNULL(M.Stat_FieldsCompleted, 0) AS statFieldsCompleted,
      CASE WHEN M.Oath_FileBody IS NOT NULL THEN N'yes' ELSE N'no' END AS statOath,
      (SELECT TOP 1 URR.CreatedOn FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId = M.UserId AND URR.Approved = 1 ORDER BY URR.CreatedOn DESC) AS masooliatRoleOn,
      (SELECT STRING_AGG(R.RoleName, ' , ') FROM dbo.HWY_Members ForAgg WITH (NOLOCK) LEFT JOIN dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) ON ForAgg.UserId = URR.UserId LEFT JOIN dbo.AppEnd_Roles R WITH (NOLOCK) ON URR.RoleId = R.Id WHERE ForAgg.Id = M.Id AND URR.Approved = 1) AS rolesLimits,
      (SELECT dbo.HWY_FN_Agg_AreaLimits(M.Id)) AS areasLimits,
      (SELECT STRING_AGG(Title, ' , ') FROM dbo.HWY_Members_GenderLimits WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation ON HWY_BaseInformation.Id = HWY_Members_GenderLimits.ItemId WHERE HWY_Members_GenderLimits.MemberId = M.Id) AS genderLimits,
      (SELECT STRING_AGG(Title, ' , ') FROM dbo.HWY_Members_OrgLimits WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation ON HWY_BaseInformation.Id = HWY_Members_OrgLimits.ItemId WHERE HWY_Members_OrgLimits.MemberId = M.Id) AS orgLimits,
      (SELECT STRING_AGG(Title, ' , ') FROM dbo.HWY_Members_UniLimits WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation ON HWY_BaseInformation.Id = HWY_Members_UniLimits.ItemId WHERE HWY_Members_UniLimits.MemberId = M.Id) AS uniLimits,
      (SELECT STRING_AGG(Title, ' , ') FROM dbo.HWY_Members_JobL1Limits WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation ON HWY_BaseInformation.Id = HWY_Members_JobL1Limits.ItemId WHERE HWY_Members_JobL1Limits.MemberId = M.Id) AS jobL1Limits,
      (SELECT STRING_AGG(Title, ' , ') FROM dbo.HWY_Members_EttehadLimits WITH (NOLOCK) LEFT JOIN dbo.HWY_BaseInformation ON HWY_BaseInformation.Id = HWY_Members_EttehadLimits.ItemId WHERE HWY_Members_EttehadLimits.MemberId = M.Id) AS ettehadLimits,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id = M.NakhebJoinProvinceId) AS nakhebJoinProvinceName,
      (SELECT TOP 1 C.CircleName FROM dbo.HWY_H_Circles C WITH (NOLOCK) WHERE C.CircleId = M.NakhebJoinCircleId) AS nakhebJoinCircleName,
      (SELECT TOP 1 T.TamvinName FROM dbo.HWY_H_Tamvinat T WITH (NOLOCK) WHERE T.TamvinId = M.NakhebJoinTamvinId) AS nakhebJoinTamvinName,
      (SELECT TOP 1 E.EghteraName FROM dbo.HWY_H_Eghteraat E WITH (NOLOCK) WHERE E.EghteraId = M.NakhebJoinEghteraId) AS nakhebJoinEghteraName,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id = M.EducationLevelId) AS educationLevelIdTitle,
      (SELECT TOP 1 BI.Title FROM dbo.HWY_BaseInformation BI WITH (NOLOCK) WHERE BI.Id = M.JobTypeId) AS jobTypeIdTitle,
      CONVERT(VARCHAR(32), M.MembershipOn, 126) AS membershipOn,
      CONVERT(VARCHAR(32), M.UpdatedOn, 126) AS updatedOn
    FROM dbo.HWY_Members M WITH (NOLOCK)
    WHERE ${employeeBaseWhere}${filterWhere}
    ORDER BY M.UpdatedOn DESC, M.Id DESC
    OFFSET ${params.offset} ROWS FETCH NEXT ${params.page_size} ROWS ONLY
  `;

  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(sql);
    return result.recordset as Record<string, unknown>[];
  } finally {
    await pool.close();
  }
};
