import sql from 'mssql';
import {
  legacyHwyActionKey,
  legacyHwyRoleIdToPlatformRoleName,
  type HwyLegacyControllerAction,
} from '../../src/domain/hwy/hwyMemberListLegacyAccess';

export type LegacyHwyRoleRow = {
  legacyRoleId: number;
  legacyRoleName: string;
  platformRoleName: string;
};

export const mapLegacyHwyRoleRow = (row: { Id: number; RoleName: string | null }): LegacyHwyRoleRow => {
  const legacyRoleId = Number(row.Id);
  return {
    legacyRoleId,
    legacyRoleName: String(row.RoleName ?? '').trim(),
    platformRoleName: legacyHwyRoleIdToPlatformRoleName(legacyRoleId),
  };
};

export async function fetchLegacyHwyRoles(pool: sql.ConnectionPool): Promise<LegacyHwyRoleRow[]> {
  const result = await pool.request().query(`
    SELECT Id, RoleName
    FROM dbo.AppEnd_Roles WITH (NOLOCK)
    ORDER BY Id
  `);
  return (result.recordset as Array<{ Id: number; RoleName: string | null }>).map(mapLegacyHwyRoleRow);
}

/** Role names (`HWY_R_{legacyRoleId}`) granted each legacy controller action. */
export async function fetchLegacyPlatformRolesByAction(
  pool: sql.ConnectionPool,
  actions: ReadonlyArray<HwyLegacyControllerAction>,
): Promise<Map<string, string[]>> {
  const byAction = new Map<string, string[]>();
  if (!actions.length) {
    return byAction;
  }

  const tuples = actions.map((action) => legacyHwyActionKey(action));
  const controllers = [...new Set(actions.map((action) => action.controller))];
  const request = pool.request();
  const controllerParams = controllers.map((controller, index) => {
    const param = `controller${index}`;
    request.input(param, controller);
    return `@${param}`;
  });
  const controllerIn = controllerParams.length ? controllerParams.join(', ') : "''";
  const result = await request.query(`
    SELECT a.Controller, a.Method, r.Id AS RoleId
    FROM dbo.AppEnd_Actions a WITH (NOLOCK)
    INNER JOIN dbo.AppEnd_Roles_R_Actions ra WITH (NOLOCK) ON ra.ActionId = a.Id
    INNER JOIN dbo.AppEnd_Roles r WITH (NOLOCK) ON r.Id = ra.RoleId
    WHERE a.Controller IN (${controllerIn})
  `);

  for (const row of result.recordset as Array<{ Controller: string; Method: string; RoleId: number }>) {
    const key = `${row.Controller}::${row.Method}`;
    if (!tuples.includes(key)) {
      continue;
    }
    const roleName = legacyHwyRoleIdToPlatformRoleName(Number(row.RoleId));
    const list = byAction.get(key) ?? [];
    if (!list.includes(roleName)) {
      list.push(roleName);
      byAction.set(key, list);
    }
  }

  for (const key of tuples) {
    if (!byAction.has(key)) {
      byAction.set(key, []);
    }
  }

  return byAction;
}

export async function connectLegacyReadPool(): Promise<sql.ConnectionPool> {
  const { readLegacyConn, withLegacyReadOnlyIntent } = await import('./legacyConn');
  const cfg = withLegacyReadOnlyIntent(readLegacyConn());
  return sql.connect({
    user: cfg.user,
    password: cfg.password,
    server: cfg.server,
    database: cfg.database,
    options: cfg.options,
    pool: cfg.pool,
  });
}

