import type { HwyMembershipDecisionKind, HwyMembershipStage } from './hwyMembershipDecision';

export const parseHwyMembershipStage = (raw: string): HwyMembershipStage => {
  const value = raw.trim();
  if (value === 'call_center' || value === 'local') {
    return value;
  }
  throw new Error('Membership stage is invalid.');
};

export const parseHwyMembershipDecisionKind = (raw: string): HwyMembershipDecisionKind => {
  const value = raw.trim();
  if (value === 'approve' || value === 'reject' || value === 'unreject') {
    return value;
  }
  throw new Error('Decision kind is invalid.');
};
