import { sanitizeDigitsOnlyInput } from './hwySelfRegistrationNumericInput';

/** Iraqi mobile self-reg phones: digits only, 11 chars, must start with 07. */
export const HWY_SELF_REGISTRATION_PHONE_LEN = 11;

const HWY_SELF_REGISTRATION_PHONE_PATTERN = /^07\d{9}$/;

export function sanitizeHwySelfRegistrationPhoneInput(raw: string): string {
  return sanitizeDigitsOnlyInput(raw, HWY_SELF_REGISTRATION_PHONE_LEN);
}
export function isValidHwySelfRegistrationPhone(raw: string): boolean {
  const digits = sanitizeHwySelfRegistrationPhoneInput(raw);
  if (!digits) return false;
  return HWY_SELF_REGISTRATION_PHONE_PATTERN.test(digits);
}
