import {
  buildHwyMemberListRouteAllowRoles,
  legacyHwyActionKey,
  type HwyLegacyControllerAction,
} from './hwyMemberListLegacyAccess';

/** Legacy AppEnd `HWY_Members.AddKasb` → `hwy_member_kasb_link`. */
export const HWY_MEMBER_KASB_LINK_LEGACY_ACTION: HwyLegacyControllerAction = {
  controller: 'HWY_Members',
  method: 'AddKasb',
};

export const hwyMemberKasbLinkLegacyActionKey = (): string => (
  legacyHwyActionKey(HWY_MEMBER_KASB_LINK_LEGACY_ACTION)
);

export const viewerCanManageHwyMemberKasbLinks = (
  viewerRoles: readonly string[],
  allowedPlatformRoles: readonly string[],
): boolean => {
  const viewer = new Set(
    viewerRoles.map((role) => role.trim().toUpperCase()).filter(Boolean),
  );
  if (viewer.has('ADMIN')) {
    return true;
  }
  const allowed = buildHwyMemberListRouteAllowRoles([...allowedPlatformRoles]);
  return allowed.some((role) => viewer.has(role.trim().toUpperCase()));
};
