import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type { IAiProvider } from '../../IAiProvider';
import { aiManager } from '../../AiManager';
import { CODE_EMBEDDINGS_ENABLED } from '../../../../shared/api/contracts/ai/codeEmbeddingsGate';
import { LOCAL_EMBEDDINGS_MODEL_ID, localEmbeddingsProvider } from '../../providers/LocalEmbeddingsProvider';
import {
  isCodeChunkIndexWarmed,
  listIndexedChunks,
  visitWarmedChunks,
  warmCodeChunkIndex,
} from './codeChunkIndex';
import { logger } from '../../../logging/Logger';
import type {
  WorkspaceEmbeddingsIndexState,
  WorkspaceEmbeddingsIndexStatus,
} from '../../../../shared/api/contracts/ai/workspaceEmbeddingsIndexStatus';

/**
 * Workspace vector index — the local variant of vscode-copilot-chat's
 * `workspaceChunkEmbeddingsIndex` (same architecture Cursor uses with a remote store):
 *
 * - Chunks come from the existing lexical chunker (single chunking pipeline).
 * - Each chunk is keyed by a content hash; embeddings are computed once per hash and
 *   cached on disk, so an unchanged file is never re-embedded (incremental sync).
 * - The fill runs in the BACKGROUND with a concurrency guard and per-run budget; a
 *   query never waits for indexing — it ranks whatever is already embedded and the
 *   lexical/ripgrep signals cover the rest (VS Code's tfidf fallback pattern).
 * - Vectors are L2-normalized at store time, so ranking is a plain dot product
 *   (mirrors `rankEmbeddings`/`distance` in vscode's embeddingsComputer).
 * - Any provider failure sets a cooldown so a missing/broken embeddings endpoint
 *   degrades to lexical search silently instead of hammering the API.
 */

export type WorkspaceVectorHit = {
  path: string;
  startLine: number;
  endLine: number;
  score: number;
};

type CachedEntry = {
  hash: string;
  path: string;
  startLine: number;
  endLine: number;
  vector: Float32Array;
};

type CacheFileShape = {
  version: 1;
  model: string;
  entries: Array<{ hash: string; path: string; startLine: number; endLine: number; v: string }>;
};

const CACHE_DIR = path.join('workspace', 'appendoo');
const CACHE_FILE = 'workspace-embeddings.json';
const EMBED_BATCH_SIZE = 32;
/** Max chunks embedded per fill pass — bounds cost/latency; the next pass continues. */
const MAX_CHUNKS_PER_FILL = 512;
/** After a provider failure, stay lexical-only for a while instead of retrying every query. */
const FAILURE_COOLDOWN_MS = 10 * 60 * 1000;
/** Truncate very large chunks before embedding — tail tokens add cost, not signal. */
const MAX_EMBED_CHARS = 4_000;
/** Pause between fill batches so live query embeds aren't starved during the initial build. */
const FILL_INTER_BATCH_DELAY_MS = 150;

type ProviderResolution = { provider: IAiProvider; modelKey: string } | null;

let entriesByHash = new Map<string, CachedEntry>();
let loadedForModel: string | null = null;
let fillInFlight = false;
let failureCooldownUntil = 0;
let lastFillFailureMessage: string | null = null;
let providerResolverOverride: (() => ProviderResolution) | null = null;
let codeChunkIndexWarmScheduled = false;

const resolveEmbeddingsProvider = (): ProviderResolution => {
  // Test override first so unit tests can exercise the index without flipping the gate.
  if (providerResolverOverride) return providerResolverOverride();
  if (!CODE_EMBEDDINGS_ENABLED) return null;
  try {
    const settings = aiManager.getSettings();
    if (!settings?.enabled) return null;
    // Explicit embeddingsModelId is an operator override (external API/Ollama endpoint);
    // the default is the fully in-process local model — zero external services.
    if (settings.embeddingsModelId?.trim()) {
      const { entry, provider } = aiManager.resolveModel(settings.embeddingsModelId.trim());
      if (typeof provider.embedTexts !== 'function') return null;
      return { provider, modelKey: `${entry.provider}:${entry.modelId}` };
    }
    return { provider: localEmbeddingsProvider, modelKey: `local:${LOCAL_EMBEDDINGS_MODEL_ID}` };
  } catch {
    return null;
  }
};

const cachePath = (): string => path.join(process.cwd(), CACHE_DIR, CACHE_FILE);

const vectorToBase64 = (vector: Float32Array): string => (
  Buffer.from(vector.buffer, vector.byteOffset, vector.byteLength).toString('base64')
);

const vectorFromBase64 = (encoded: string): Float32Array => {
  const buffer = Buffer.from(encoded, 'base64');
  return new Float32Array(buffer.buffer, buffer.byteOffset, buffer.byteLength / 4);
};

const normalizeVector = (values: number[]): Float32Array => {
  const vector = new Float32Array(values);
  let sumSquares = 0;
  for (let i = 0; i < vector.length; i += 1) sumSquares += vector[i] * vector[i];
  const norm = Math.sqrt(sumSquares);
  if (norm > 0) {
    for (let i = 0; i < vector.length; i += 1) vector[i] /= norm;
  }
  return vector;
};

const dotProduct = (a: Float32Array, b: Float32Array): number => {
  if (a.length !== b.length) return 0;
  let sum = 0;
  for (let i = 0; i < a.length; i += 1) sum += a[i] * b[i];
  return sum;
};

const chunkContentHash = (chunkPath: string, text: string): string => (
  createHash('sha1').update(chunkPath).update('�').update(text).digest('hex')
);

const loadCacheFromDisk = (modelKey: string): void => {
  if (loadedForModel === modelKey) return;
  entriesByHash = new Map();
  loadedForModel = modelKey;
  try {
    const raw = fs.readFileSync(cachePath(), 'utf8');
    const parsed = JSON.parse(raw) as CacheFileShape;
    if (parsed.version !== 1 || parsed.model !== modelKey) return; // Model change → full re-embed.
    for (const entry of parsed.entries) {
      entriesByHash.set(entry.hash, {
        hash: entry.hash,
        path: entry.path,
        startLine: entry.startLine,
        endLine: entry.endLine,
        vector: vectorFromBase64(entry.v),
      });
    }
  } catch {
    // Missing/corrupt cache → start empty.
  }
};

const persistCacheToDisk = (modelKey: string): void => {
  if (providerResolverOverride) return; // Tests stay in-memory — never touch runtime/.
  try {
    const dir = path.join(process.cwd(), CACHE_DIR);
    fs.mkdirSync(dir, { recursive: true });
    const shape: CacheFileShape = {
      version: 1,
      model: modelKey,
      entries: [...entriesByHash.values()].map((entry) => ({
        hash: entry.hash,
        path: entry.path,
        startLine: entry.startLine,
        endLine: entry.endLine,
        v: vectorToBase64(entry.vector),
      })),
    };
    const target = cachePath();
    const tmp = `${target}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(shape));
    fs.renameSync(tmp, target);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.warn('WorkspaceEmbeddings', `Cache persist failed: ${message}`);
  }
};

/**
 * Background fill: embed chunks whose content hash is not cached yet and evict entries
 * whose chunk disappeared. Fire-and-forget; concurrent calls coalesce.
 */
export const ensureWorkspaceEmbeddingsFill = (): void => {
  if (fillInFlight || Date.now() < failureCooldownUntil) return;
  const resolution = resolveEmbeddingsProvider();
  if (!resolution) return;

  fillInFlight = true;
  void (async () => {
    try {
      loadCacheFromDisk(resolution.modelKey);
      const chunks = listIndexedChunks();
      const liveHashes = new Set<string>();
      const missing: Array<{ hash: string; path: string; startLine: number; endLine: number; text: string }> = [];

      for (const chunk of chunks) {
        const hash = chunkContentHash(chunk.path, chunk.text);
        liveHashes.add(hash);
        if (!entriesByHash.has(hash) && missing.length < MAX_CHUNKS_PER_FILL) {
          missing.push({ hash, path: chunk.path, startLine: chunk.startLine, endLine: chunk.endLine, text: chunk.text });
        }
      }

      let evicted = 0;
      for (const hash of [...entriesByHash.keys()]) {
        if (!liveHashes.has(hash)) {
          entriesByHash.delete(hash);
          evicted += 1;
        }
      }

      if (missing.length === 0) {
        if (evicted > 0) persistCacheToDisk(resolution.modelKey);
        return;
      }

      for (let offset = 0; offset < missing.length; offset += EMBED_BATCH_SIZE) {
        // Breather between batches: the local ONNX session is shared with query
        // embedding, so give in-flight searches a scheduling window during the
        // one-time initial build instead of monopolizing the session/CPU.
        if (offset > 0) {
          await new Promise((resolve) => setTimeout(resolve, FILL_INTER_BATCH_DELAY_MS));
        }
        const batch = missing.slice(offset, offset + EMBED_BATCH_SIZE);
        const vectors = await resolution.provider.embedTexts!(
          batch.map((item) => item.text.slice(0, MAX_EMBED_CHARS)),
        );
        batch.forEach((item, index) => {
          const values = vectors[index];
          if (!values?.length) return;
          entriesByHash.set(item.hash, {
            hash: item.hash,
            path: item.path,
            startLine: item.startLine,
            endLine: item.endLine,
            vector: normalizeVector(values),
          });
        });
      }

      persistCacheToDisk(resolution.modelKey);
      logger.info('WorkspaceEmbeddings', `Indexed ${missing.length} chunks (${entriesByHash.size} total, ${evicted} evicted).`);
    } catch (error) {
      failureCooldownUntil = Date.now() + FAILURE_COOLDOWN_MS;
      const message = error instanceof Error ? error.message : String(error);
      lastFillFailureMessage = message;
      logger.warn('WorkspaceEmbeddings', `Fill failed — lexical-only for ${FAILURE_COOLDOWN_MS / 60000}min: ${message}`);
    } finally {
      fillInFlight = false;
    }
  })();
};

const countIndexedWarmedChunks = (): { totalChunks: number; indexedChunks: number } => {
  let totalChunks = 0;
  let indexedChunks = 0;
  visitWarmedChunks((chunk) => {
    totalChunks += 1;
    const hash = chunkContentHash(chunk.path, chunk.text);
    if (entriesByHash.has(hash)) indexedChunks += 1;
  });
  return { totalChunks, indexedChunks };
};

const scheduleCodeChunkIndexWarm = (): void => {
  if (codeChunkIndexWarmScheduled || isCodeChunkIndexWarmed()) return;
  codeChunkIndexWarmScheduled = true;
  setImmediate(() => {
    try {
      warmCodeChunkIndex();
    } finally {
      codeChunkIndexWarmScheduled = false;
    }
  });
};

const resolveIndexState = (
  totalChunks: number,
  indexedChunks: number,
  inCooldown: boolean,
): WorkspaceEmbeddingsIndexState => {
  if (inCooldown) return 'error';
  if (totalChunks === 0) return 'empty';
  if (indexedChunks >= totalChunks) return 'ready';
  if (fillInFlight || indexedChunks > 0) return 'indexing';
  return 'pending';
};

/** Snapshot of how much of the workspace chunk index is embedded. */
export const getWorkspaceEmbeddingsIndexStatus = (): WorkspaceEmbeddingsIndexStatus => {
  try {
    const resolution = resolveEmbeddingsProvider();
    if (!resolution) {
      return {
        state: 'unavailable',
        totalChunks: 0,
        indexedChunks: 0,
        progressPercent: null,
        isFillInFlight: false,
        error: null,
      };
    }

    loadCacheFromDisk(resolution.modelKey);

    if (!isCodeChunkIndexWarmed()) {
      scheduleCodeChunkIndexWarm();
      return {
        state: 'pending',
        totalChunks: 0,
        indexedChunks: entriesByHash.size,
        progressPercent: null,
        isFillInFlight: fillInFlight,
        error: null,
      };
    }

    const { totalChunks, indexedChunks } = countIndexedWarmedChunks();
    const inCooldown = Date.now() < failureCooldownUntil;
    const state = resolveIndexState(totalChunks, indexedChunks, inCooldown);
    const progressPercent = totalChunks > 0
      ? Math.min(100, Math.round((indexedChunks / totalChunks) * 100))
      : null;

    // Status is read-only. Never kick off fill/ONNX load from a badge poll or settings
    // fetch — that pinned multi‑GB RAM in the main Node process and made the UI feel hung.
    // Fill stays on the assistant code-search path (`searchWorkspaceEmbeddings`).

    return {
      state,
      totalChunks,
      indexedChunks,
      progressPercent,
      isFillInFlight: fillInFlight,
      error: inCooldown ? lastFillFailureMessage : null,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      state: 'error',
      totalChunks: 0,
      indexedChunks: 0,
      progressPercent: null,
      isFillInFlight: false,
      error: message,
    };
  }
};

/**
 * Vector search over whatever is already embedded. Never blocks on indexing: an empty
 * or partial index returns partial (or no) hits and triggers a background fill —
 * lexical + ripgrep signals in the hybrid merge cover the gap meanwhile.
 */
export const searchWorkspaceEmbeddings = async (
  query: string,
  scopePaths: string[] | undefined,
  maxResults: number,
): Promise<WorkspaceVectorHit[]> => {
  const trimmed = query.trim();
  if (!trimmed || Date.now() < failureCooldownUntil) return [];
  const resolution = resolveEmbeddingsProvider();
  if (!resolution) return [];

  loadCacheFromDisk(resolution.modelKey);
  ensureWorkspaceEmbeddingsFill();
  if (entriesByHash.size === 0) return [];

  let queryVector: Float32Array;
  try {
    const [values] = await resolution.provider.embedTexts!([trimmed.slice(0, MAX_EMBED_CHARS)]);
    if (!values?.length) return [];
    queryVector = normalizeVector(values);
  } catch (error) {
    failureCooldownUntil = Date.now() + FAILURE_COOLDOWN_MS;
    const message = error instanceof Error ? error.message : String(error);
    logger.warn('WorkspaceEmbeddings', `Query embed failed — lexical-only for ${FAILURE_COOLDOWN_MS / 60000}min: ${message}`);
    return [];
  }

  const scopePrefixes = scopePaths?.length
    ? scopePaths.map((scopePath) => scopePath.replace(/\\/g, '/').replace(/\/$/, ''))
    : undefined;
  const inScope = (chunkPath: string): boolean => {
    if (!scopePrefixes) return true;
    return scopePrefixes.some((prefix) => chunkPath === prefix || chunkPath.startsWith(`${prefix}/`));
  };

  const hits: WorkspaceVectorHit[] = [];
  for (const entry of entriesByHash.values()) {
    if (!inScope(entry.path)) continue;
    hits.push({
      path: entry.path,
      startLine: entry.startLine,
      endLine: entry.endLine,
      score: dotProduct(queryVector, entry.vector),
    });
  }

  return hits
    .sort((left, right) => right.score - left.score)
    .slice(0, maxResults);
};

/** Test-only — inject a fake provider and reset module state. */
export const configureWorkspaceEmbeddingsForTests = (
  resolver: (() => ProviderResolution) | null,
): void => {
  providerResolverOverride = resolver;
  entriesByHash = new Map();
  loadedForModel = resolver ? '__test__' : null;
  fillInFlight = false;
  failureCooldownUntil = 0;
  lastFillFailureMessage = null;
};

/** Test-only — wait for a background fill kicked off by ensureWorkspaceEmbeddingsFill. */
export const waitForWorkspaceEmbeddingsFillForTests = async (): Promise<void> => {
  while (fillInFlight) {
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
};
