const EASTERN_ARABIC_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
const ARABIC_INDIC_DIGITS = '٠١٢٣٤٥٦٧٨٩';

/** Map Persian / Arabic-Indic digits to ASCII 0–9 (display + input). */
export function normalizeDigitsToLatin(raw: string): string {
  return raw.replace(/[\u06F0-\u06F9\u0660-\u0669]/g, (character) => {
    const easternIndex = EASTERN_ARABIC_DIGITS.indexOf(character);
    if (easternIndex >= 0) {
      return String(easternIndex);
    }
    const arabicIndex = ARABIC_INDIC_DIGITS.indexOf(character);
    if (arabicIndex >= 0) {
      return String(arabicIndex);
    }
    return character;
  });
}

/** Strip every non-digit character from self-registration numeric fields. */
export function sanitizeDigitsOnlyInput(raw: string, maxLen?: number): string {
  const digits = normalizeDigitsToLatin(raw).replace(/\D/g, '');
  if (maxLen == null || maxLen <= 0) {
    return digits;
  }
  return digits.slice(0, maxLen);
}