import { QueryTypes } from 'sequelize';

import type { HwyGeoResponsibilityLevel } from '../../../domain/hwy/hwyGeoResponsibilityCatalog';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { formatHwyGeoElectoralPathForDisplay } from '../../../shared/lib/hwyMemberDirectoryPathDisplay';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { buildMergedCultureBundle } from '../base-info/baseInfoCultureTranslationStore';
import { computeDisplayTitlePathsForCulture } from '../base-info/baseInfoPathResolve';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';

const readStringField = (row: Record<string, unknown>, key: string): string =>
  String(row[key] ?? '').trim();

const GEO_KIND_PRIORITY: Record<string, number> = {
  region: 5,
  maktab: 4,
  circle: 3,
  ghavateh: 2,
  province: 1,
};

const LEGACY_ROLE_ID_TO_GEO_LEVEL: Record<string, HwyGeoResponsibilityLevel> = {
  '1000003': 'province',
  '1000047': 'ghavateh',
  '1000027': 'circle',
  '1000004': 'maktab',
  '1000005': 'region',
};

const isGeoResponsibilityLevel = (value: string): value is HwyGeoResponsibilityLevel => (
  value === 'province'
  || value === 'ghavateh'
  || value === 'circle'
  || value === 'maktab'
  || value === 'region'
);

const memberItemKey = (memberId: string, itemId: string): string => `${memberId}:${itemId}`;

const resolveGeoLevelFromLegacyKind = (legacyKind: string): HwyGeoResponsibilityLevel | null => {
  const kind = legacyKind.trim().toLowerCase();
  return isGeoResponsibilityLevel(kind) ? kind : null;
};

const pickLegacyKindForItemId = (
  mapRows: Array<{ legacy_id: string; legacy_kind: string }>,
  itemId: string,
): HwyGeoResponsibilityLevel | null => {
  const matches = mapRows.filter((row) => String(row.legacy_id ?? '').trim() === itemId);
  if (matches.length === 0) {
    return null;
  }
  let best: { kind: string; priority: number } | null = null;
  for (const row of matches) {
    const kind = String(row.legacy_kind ?? '').trim();
    const level = resolveGeoLevelFromLegacyKind(kind);
    if (!level) {
      continue;
    }
    const priority = GEO_KIND_PRIORITY[level] ?? 0;
    if (!best || priority > best.priority) {
      best = { kind: level, priority };
    }
  }
  return best?.kind ?? null;
};

const parseLegacyGeoIds = (raw: string | null | undefined): string[] => {
  const text = String(raw ?? '').trim();
  if (!text) {
    return [];
  }
  if (text.includes('<')) {
    return [];
  }
  return [...new Set(
    text.split(/[,،]/).map((part) => part.trim()).filter((part) => /^\d+$/.test(part)),
  )];
};

const pickBestBaseInfoIdPerLegacyId = (
  mapRows: Array<{ legacy_id: string; base_info_id: string; legacy_kind: string }>,
): Map<string, string> => {
  const best = new Map<string, { baseInfoId: string; priority: number }>();
  for (const row of mapRows) {
    const legacyId = String(row.legacy_id ?? '').trim();
    const baseInfoId = String(row.base_info_id ?? '').trim();
    const kind = String(row.legacy_kind ?? '').trim();
    if (!legacyId || !baseInfoId) {
      continue;
    }
    const priority = GEO_KIND_PRIORITY[kind] ?? 0;
    const current = best.get(legacyId);
    if (!current || priority > current.priority) {
      best.set(legacyId, { baseInfoId, priority });
    }
  }
  return new Map([...best.entries()].map(([legacyId, entry]) => [legacyId, entry.baseInfoId]));
};

const loadIqTitlePathsByBaseInfoId = async (
  baseInfoIds: string[],
): Promise<Map<string, string>> => {
  if (baseInfoIds.length === 0) {
    return new Map();
  }
  try {
    const sequelize = getControlPlaneSequelize();
    const rows = await sequelize.query<{ base_info_id: string; title_path: string | null }>(
      `SELECT CAST(bi.id AS NVARCHAR(128)) AS base_info_id,
              NULLIF(LTRIM(RTRIM(dbo.hwy_base_info_iq_title_path(bi.id))), N'') AS title_path
       FROM dbo.base_info bi WITH (NOLOCK)
       WHERE bi.id IN (:baseInfoIds)`,
      {
        replacements: { baseInfoIds },
        type: QueryTypes.SELECT,
      },
    );
    const map = new Map<string, string>();
    for (const row of rows) {
      const id = String(row.base_info_id ?? '').trim();
      const path = String(row.title_path ?? '').trim();
      if (id && path) {
        map.set(id, path);
      }
    }
    return map;
  } catch {
    return new Map();
  }
};

/** Area-limit `item_id` / legacy geo key → full iq `title_path` (AllArea / base_info / region ref). */
const loadTitlePathsByItemIdSql = async (itemIds: string[]): Promise<Map<string, string>> => {
  const ids = [...new Set(itemIds.map((id) => id.trim()).filter(Boolean))];
  if (ids.length === 0) {
    return new Map();
  }
  try {
    const sequelize = getControlPlaneSequelize();
    const rows = await sequelize.query<{ item_id: string; title_path: string | null }>(
      `SELECT CAST(ids.item_id AS VARCHAR(32)) AS item_id,
              NULLIF(LTRIM(RTRIM(COALESCE(
                dbo.hwy_base_info_iq_title_path(
                  dbo.hwy_resolve_raw_geo_to_base_info_id(CAST(ids.item_id AS NVARCHAR(128)))
                ),
                dbo.hwy_region_electoral_title_path(CAST(ids.item_id AS NVARCHAR(128)))
              ))), N'') AS title_path
       FROM (SELECT CAST(value AS VARCHAR(32)) AS item_id FROM STRING_SPLIT(:itemIdsCsv, N',')) ids`,
      { replacements: { itemIdsCsv: ids.join(',') }, type: QueryTypes.SELECT },
    );
    const map = new Map<string, string>();
    for (const row of rows) {
      const itemId = String(row.item_id ?? '').trim();
      const path = String(row.title_path ?? '').trim();
      if (itemId && path) {
        map.set(itemId, path);
      }
    }
    return map;
  } catch {
    return new Map();
  }
};

/** Legacy geo keys (e.g. NakhebJoinEghteraId) → full display title_path. */
export const resolveHwyLegacyGeoIdTitlePaths = async (
  legacyIds: string[],
  queryLang: string,
): Promise<Map<string, string>> => {
  const normalizedIds = [...new Set(legacyIds.map((id) => id.trim()).filter(Boolean))];
  const numericIds = normalizedIds
    .map((id) => Number(id))
    .filter((id) => Number.isFinite(id));
  const pathByLegacyId = new Map<string, string>();
  if (numericIds.length === 0) {
    return pathByLegacyId;
  }

  const sequelize = getControlPlaneSequelize();
  const mapRows = await sequelize.query<{ legacy_id: string; base_info_id: string; legacy_kind: string }>(
    `SELECT CAST(legacy_id AS VARCHAR(32)) AS legacy_id,
            base_info_id,
            legacy_kind
     FROM dbo.hwy_etl_geo_map WITH (NOLOCK)
     WHERE legacy_id IN (:legacyIds)`,
    { replacements: { legacyIds: numericIds }, type: QueryTypes.SELECT },
  );

  const baseInfoByLegacyId = pickBestBaseInfoIdPerLegacyId(mapRows);
  const baseInfoIds = [...new Set(baseInfoByLegacyId.values())];

  if (baseInfoIds.length > 0) {
    const iqPathById = await loadIqTitlePathsByBaseInfoId(baseInfoIds);

    const cultureId = resolveBaseInfoCultureId(queryLang);
    const bundle = buildMergedCultureBundle(cultureId);
    const titlePathById = await computeDisplayTitlePathsForCulture(baseInfoIds, cultureId, bundle);
    const enriched = await listBaseInfoEnrichmentRowsByIds(baseInfoIds, cultureId);
    const leafTitleById = new Map(
      enriched.map((item) => [String(item.id ?? '').trim(), String(item.title ?? '').trim()]),
    );

    for (const [legacyId, baseInfoId] of baseInfoByLegacyId) {
      const path = iqPathById.get(baseInfoId)?.trim()
        || titlePathById.get(baseInfoId)?.trim()
        || leafTitleById.get(baseInfoId)?.trim();
      if (path) {
        pathByLegacyId.set(legacyId, path);
      }
    }
  }

  const missingIds = normalizedIds.filter((id) => !pathByLegacyId.has(id));
  const sqlPaths = await loadTitlePathsByItemIdSql(missingIds);
  for (const [itemId, path] of sqlPaths) {
    pathByLegacyId.set(itemId, path);
  }

  return pathByLegacyId;
};

const loadNominationGeoLevelByMemberItem = async (
  memberIdToLegacyIds: Map<string, string[]>,
): Promise<Map<string, HwyGeoResponsibilityLevel>> => {
  const levelByKey = new Map<string, HwyGeoResponsibilityLevel>();
  const memberIds = [...memberIdToLegacyIds.keys()];
  const itemIds = [...new Set([...memberIdToLegacyIds.values()].flat())];
  if (memberIds.length === 0) {
    return levelByKey;
  }

  try {
    const sequelize = getControlPlaneSequelize();
    const requestRows = await sequelize.query<{
      member_id: string;
      legacy_geo_id: string;
      geo_level: string;
    }>(
      `SELECT CAST(r.member_id AS VARCHAR(32)) AS member_id,
              CAST(r.legacy_geo_id AS VARCHAR(32)) AS legacy_geo_id,
              r.geo_level
       FROM dbo.hwy_geo_responsibility_requests r WITH (NOLOCK)
       WHERE r.member_id IN (:memberIds)
         AND r.request_kind = N'nomination'
         AND r.status IN (N'submitted', N'approved')
         AND r.revoked_at IS NULL
         AND r.legacy_geo_id IS NOT NULL`,
      { replacements: { memberIds }, type: QueryTypes.SELECT },
    );
    for (const row of requestRows) {
      const memberId = String(row.member_id ?? '').trim();
      const itemId = String(row.legacy_geo_id ?? '').trim();
      const geoLevel = String(row.geo_level ?? '').trim().toLowerCase();
      if (memberId && itemId && isGeoResponsibilityLevel(geoLevel)) {
        levelByKey.set(memberItemKey(memberId, itemId), geoLevel);
      }
    }
  } catch {
    // Optional when geo request table is mid-migration.
  }

  const missingItemIds = itemIds.filter((itemId) => (
    ![...memberIdToLegacyIds.entries()].some(([memberId, ids]) => (
      ids.includes(itemId) && levelByKey.has(memberItemKey(memberId, itemId))
    ))
  ));
  if (missingItemIds.length === 0) {
    return levelByKey;
  }

  try {
    const sequelize = getControlPlaneSequelize();
    const mapRows = await sequelize.query<{ legacy_id: string; legacy_kind: string }>(
      `SELECT CAST(legacy_id AS VARCHAR(32)) AS legacy_id, legacy_kind
       FROM dbo.hwy_etl_geo_map WITH (NOLOCK)
       WHERE legacy_id IN (:itemIds)`,
      { replacements: { itemIds: missingItemIds.map((id) => Number(id)).filter(Number.isFinite) }, type: QueryTypes.SELECT },
    );
    for (const [memberId, legacyIds] of memberIdToLegacyIds) {
      for (const itemId of legacyIds) {
        const key = memberItemKey(memberId, itemId);
        if (levelByKey.has(key)) {
          continue;
        }
        const fromMap = pickLegacyKindForItemId(mapRows, itemId);
        if (fromMap) {
          levelByKey.set(key, fromMap);
        }
      }
    }
  } catch {
    // Optional when geo map is unavailable.
  }

  return levelByKey;
};

const resolvePatchGeoLevelForRow = (
  row: Record<string, unknown>,
  memberId: string,
  itemId: string,
  levelByKey: Map<string, HwyGeoResponsibilityLevel>,
): HwyGeoResponsibilityLevel => {
  const fromRequest = levelByKey.get(memberItemKey(memberId, itemId));
  if (fromRequest) {
    return fromRequest;
  }
  const roleId = readStringField(row, 'roleId');
  const fromRole = roleId ? LEGACY_ROLE_ID_TO_GEO_LEVEL[roleId] : undefined;
  if (fromRole) {
    return fromRole;
  }
  return 'region';
};

const attachFromLegacyGeoIdLists = async (
  rows: Record<string, unknown>[],
  memberIdToLegacyIds: Map<string, string[]>,
  queryLang: string,
): Promise<void> => {
  const allLegacyIds = [...new Set([...memberIdToLegacyIds.values()].flat())];
  const pathByLegacyId = await resolveHwyLegacyGeoIdTitlePaths(allLegacyIds, queryLang);
  const levelByMemberItem = await loadNominationGeoLevelByMemberItem(memberIdToLegacyIds);

  for (const row of rows) {
    const memberId = readStringField(row, 'id');
    const legacyIds = memberIdToLegacyIds.get(memberId) ?? parseLegacyGeoIds(readStringField(row, 'areaOfTarshih'));
    const paths = legacyIds
      .map((legacyId) => {
        const fullPath = pathByLegacyId.get(legacyId)?.trim();
        if (!fullPath) {
          return '';
        }
        const level = resolvePatchGeoLevelForRow(row, memberId, legacyId, levelByMemberItem);
        return formatHwyGeoElectoralPathForDisplay(fullPath, level);
      })
      .filter((path): path is string => Boolean(path));
    if (paths.length === 0) {
      continue;
    }
    row.responsibilityPatchPaths = paths;
    row.responsibilityPatchPath = paths[0] ?? null;
  }
};

/** Resolve approved nomination patch paths for candidate pipeline grids (رقعة المسؤولية). */
export async function attachHwyCandidatePipelineResponsibilityPatchPaths(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  const memberIds = [...new Set(rows.map((row) => readStringField(row, 'id')).filter(Boolean))];
  const memberIdToLegacyIds = new Map<string, string[]>();

  try {
    const sequelize = getControlPlaneSequelize();
    const limits = await sequelize.query<{ member_id: string; item_id: string }>(
      `SELECT CAST(al.member_id AS VARCHAR(32)) AS member_id,
              CAST(al.item_id AS VARCHAR(32)) AS item_id
       FROM dbo.hwy_member_area_limits al WITH (NOLOCK)
       WHERE al.member_id IN (:memberIds)
         AND (al.approved = 1 OR al.approved = 0)
       ORDER BY al.member_id, al.approved DESC, al.id`,
      { replacements: { memberIds }, type: QueryTypes.SELECT },
    );

    for (const limit of limits) {
      const memberId = String(limit.member_id ?? '').trim();
      const itemId = String(limit.item_id ?? '').trim();
      if (!memberId || !itemId) {
        continue;
      }
      const list = memberIdToLegacyIds.get(memberId) ?? [];
      list.push(itemId);
      memberIdToLegacyIds.set(memberId, list);
    }
  } catch {
    // Edge DB may be mid-migration — fall back to AreaOfTarshih id list on each row.
  }

  for (const row of rows) {
    const memberId = readStringField(row, 'id');
    if (memberIdToLegacyIds.has(memberId)) {
      continue;
    }
    const parsed = parseLegacyGeoIds(readStringField(row, 'areaOfTarshih'));
    if (parsed.length > 0) {
      memberIdToLegacyIds.set(memberId, parsed);
    }
  }

  if (memberIdToLegacyIds.size === 0) {
    return;
  }

  await attachFromLegacyGeoIdLists(rows, memberIdToLegacyIds, queryLang);
}
