import { legacyHwyRoleIdToPlatformRoleName } from './hwyMemberListLegacyAccess';
import {
  HWY_SELF_REGISTRATION_PHONE_LEN,
  isValidHwySelfRegistrationPhone,
  sanitizeHwySelfRegistrationPhoneInput,
} from './selfRegistration/hwySelfRegistrationPhone';

export type HwyMemberPhoneChangeNewPhoneIssue = 'required' | 'invalidFormat' | 'sameAsCurrent';

/** Legacy HWY_Members_PhoneChangeRequests direct-apply roles. */
export const HWY_MEMBER_PHONE_DIRECT_APPLY_LEGACY_ROLE_IDS = [1000052, 1000006] as const;

export type HwyMemberPhoneSlot = 1 | 2;

export type HwyMemberPhoneRequestKind = 'change' | 'swap';

export type HwyMemberPhoneDirectApplyViewer = {
  isAdmin: boolean;
  roleNames: readonly string[];
};

export const normalizeHwyMemberPhoneStorage = (raw: string | null | undefined): string => {
  const trimmed = String(raw ?? '').trim();
  if (trimmed === '-1') {
    return '';
  }
  const digits = sanitizeHwySelfRegistrationPhoneInput(trimmed);
  if (digits) {
    return digits;
  }
  return trimmed;
};

export const coalesceHwyMemberPhoneForStorage = (phone: string): string => (
  phone.trim() ? phone.trim() : '-1'
);

export const canApplyHwyMemberPhoneWorkflowDirectly = (
  viewer: HwyMemberPhoneDirectApplyViewer,
): boolean => {
  if (viewer.isAdmin) {
    return true;
  }
  const normalized = new Set(viewer.roleNames.map((role) => role.trim()).filter(Boolean));
  for (const legacyRoleId of HWY_MEMBER_PHONE_DIRECT_APPLY_LEGACY_ROLE_IDS) {
    if (normalized.has(String(legacyRoleId))) {
      return true;
    }
    if (normalized.has(legacyHwyRoleIdToPlatformRoleName(legacyRoleId))) {
      return true;
    }
  }
  return false;
};

/** Client-side field validation for the change dialog (Iraqi mobile: 11 digits, starts with 07). */
export function resolveHwyMemberPhoneChangeNewPhoneIssue(input: {
  phoneSlot: HwyMemberPhoneSlot;
  oldPhone: string;
  newPhoneRaw: string;
  /** When true, partial numbers (1–10 digits) count as invalid format. */
  strictIncomplete?: boolean;
}): HwyMemberPhoneChangeNewPhoneIssue | null {
  const newPhone = normalizeHwyMemberPhoneStorage(input.newPhoneRaw);
  const oldPhone = normalizeHwyMemberPhoneStorage(input.oldPhone);

  if (oldPhone && newPhone && oldPhone === newPhone) {
    return 'sameAsCurrent';
  }

  if (input.phoneSlot === 1 && !newPhone) {
    return 'required';
  }

  if (input.phoneSlot === 2 && !newPhone) {
    return null;
  }

  const digits = sanitizeHwySelfRegistrationPhoneInput(input.newPhoneRaw);
  if (digits.length >= 2 && !digits.startsWith('07')) {
    return 'invalidFormat';
  }
  if (input.strictIncomplete && digits.length > 0 && digits.length < HWY_SELF_REGISTRATION_PHONE_LEN) {
    return 'invalidFormat';
  }
  if (digits.length === HWY_SELF_REGISTRATION_PHONE_LEN && !isValidHwySelfRegistrationPhone(digits)) {
    return 'invalidFormat';
  }
  if (digits.length === HWY_SELF_REGISTRATION_PHONE_LEN && isValidHwySelfRegistrationPhone(digits)) {
    return null;
  }
  if (input.strictIncomplete && digits.length > 0) {
    return 'invalidFormat';
  }
  return null;
}

export function validateHwyMemberPhoneChangeInput(input: {
  phoneSlot: HwyMemberPhoneSlot;
  oldPhone: string;
  newPhone: string;
}): void {
  const oldPhone = normalizeHwyMemberPhoneStorage(input.oldPhone);
  const newPhone = normalizeHwyMemberPhoneStorage(input.newPhone);

  if (oldPhone && oldPhone === newPhone) {
    throw new Error('New phone matches the current number.');
  }

  if (input.phoneSlot === 2 && !newPhone && !oldPhone) {
    throw new Error('Secondary phone is already empty — delete request is not allowed.');
  }

  if (input.phoneSlot === 1) {
    if (!newPhone) {
      throw new Error('Primary phone is required.');
    }
    if (!isValidHwySelfRegistrationPhone(newPhone)) {
      throw new Error('Primary phone must be 11 digits starting with 07.');
    }
    return;
  }

  if (newPhone && !isValidHwySelfRegistrationPhone(newPhone)) {
    throw new Error('Secondary phone must be 11 digits starting with 07.');
  }
}

export function validateHwyMemberPhoneSwapEligibility(phone1: string, phone2: string): void {
  const p1 = normalizeHwyMemberPhoneStorage(phone1);
  const p2 = normalizeHwyMemberPhoneStorage(phone2);
  if (!isValidHwySelfRegistrationPhone(p1) || !isValidHwySelfRegistrationPhone(p2)) {
    throw new Error('Both phones must be filled and valid to swap.');
  }
  if (p1 === p2) {
    throw new Error('Both numbers are identical — swap is not needed.');
  }
}

export const memberCanSwapHwyPhones = (phone1: string | null | undefined, phone2: string | null | undefined): boolean => {
  try {
    validateHwyMemberPhoneSwapEligibility(phone1 ?? '', phone2 ?? '');
    return true;
  } catch {
    return false;
  }
};
