import {
  findHwyGeoResponsibilityRoleSpec,
  type HwyGeoResponsibilityLevel,
} from './hwyGeoResponsibilityCatalog';

/** Electoral tree node kinds (legacy HWY_H_* parity under base_info 100.5). */
export type HwyElectoralGeoKind = 'province' | 'ghavateh' | 'circle' | 'maktab' | 'region';

export const HWY_ELECTORAL_GEO_KINDS: HwyElectoralGeoKind[] = [
  'province',
  'ghavateh',
  'circle',
  'maktab',
  'region',
];

export type HwyGeoResponsibilityElectoralSelection = Partial<
  Record<HwyElectoralGeoKind, string>
>;

export type HwyGeoResponsibilityElectoralOption = {
  geoBaseInfoId: string;
  legacyGeoId: number | null;
  title: string;
};

export const isHwyElectoralGeoKind = (value: string): value is HwyElectoralGeoKind => (
  HWY_ELECTORAL_GEO_KINDS.includes(value as HwyElectoralGeoKind)
);

/** Full electoral chain through the responsibility leaf (grid node level). */
export const hwyGeoResponsibilityElectoralCascadeKinds = (
  level: HwyGeoResponsibilityLevel,
): HwyElectoralGeoKind[] => {
  const spec = findHwyGeoResponsibilityRoleSpec(level);
  if (!spec) {
    return [];
  }
  const leafIndex = HWY_ELECTORAL_GEO_KINDS.indexOf(spec.geoMapKind);
  if (leafIndex < 0) {
    return [];
  }
  return HWY_ELECTORAL_GEO_KINDS.slice(0, leafIndex + 1);
};

/**
 * Nomination picker filters: ancestors only (one level above the grid leaf — the leaf geo is fixed on the row).
 */
export const hwyGeoResponsibilityElectoralCascadeFilterKinds = (
  level: HwyGeoResponsibilityLevel,
): HwyElectoralGeoKind[] => {
  const steps = hwyGeoResponsibilityElectoralCascadeKinds(level);
  if (steps.length <= 1) {
    return [];
  }
  return steps.slice(0, -1);
};

/** Nomination dialog filters: province → ancestors of the list leaf (not the full chain to region). */
export const hwyGeoResponsibilityNominationElectoralFilterKinds = (
  listLevel: HwyGeoResponsibilityLevel,
): HwyElectoralGeoKind[] => hwyGeoResponsibilityElectoralCascadeFilterKinds(listLevel);

/** Member rashh picker: full electoral chain through the list leaf (e.g. province → region). */
export const hwyGeoResponsibilityMemberRashhElectoralFilterKinds = (
  listLevel: HwyGeoResponsibilityLevel,
): HwyElectoralGeoKind[] => hwyGeoResponsibilityElectoralCascadeKinds(listLevel);

/** Deepest selected ancestor for member search; falls back to the opened row geo. */
export const resolveHwyGeoResponsibilityElectoralMemberSearchGeoBaseInfoId = (
  level: HwyGeoResponsibilityLevel,
  selection: HwyGeoResponsibilityElectoralSelection,
  rowGeoBaseInfoId: string | null | undefined,
): string | null => {
  const filterKinds = hwyGeoResponsibilityElectoralCascadeFilterKinds(level);
  return resolveHwyGeoResponsibilityElectoralMemberSearchGeoBaseInfoIdForKinds(
    filterKinds,
    selection,
    rowGeoBaseInfoId,
  );
};

export const resolveHwyGeoResponsibilityNominationElectoralMemberSearchGeoBaseInfoId = (
  listLevel: HwyGeoResponsibilityLevel,
  selection: HwyGeoResponsibilityElectoralSelection,
  rowGeoBaseInfoId: string | null | undefined,
): string | null => (
  resolveHwyGeoResponsibilityElectoralMemberSearchGeoBaseInfoIdForKinds(
    hwyGeoResponsibilityNominationElectoralFilterKinds(listLevel),
    selection,
    rowGeoBaseInfoId,
  )
);

export type HwyGeoResponsibilityNominationCandidateQueryScope = {
  level: HwyGeoResponsibilityLevel;
  geoBaseInfoId: string;
};

/** Deepest electoral combo drives list query level + geo; falls back to the nominated row. */
export const resolveHwyGeoResponsibilityNominationCandidateQueryScope = (
  selection: HwyGeoResponsibilityElectoralSelection,
  rowGeoBaseInfoId: string,
  listLevel: HwyGeoResponsibilityLevel,
  options?: { filterKinds?: readonly HwyElectoralGeoKind[] },
): HwyGeoResponsibilityNominationCandidateQueryScope | null => {
  const kinds = options?.filterKinds ?? hwyGeoResponsibilityNominationElectoralFilterKinds(listLevel);
  for (let index = kinds.length - 1; index >= 0; index -= 1) {
    const kind = kinds[index]!;
    const id = selection[kind]?.trim();
    if (id) {
      return { level: kind, geoBaseInfoId: id };
    }
  }
  const pinned = rowGeoBaseInfoId.trim();
  if (pinned) {
    return { level: listLevel, geoBaseInfoId: pinned };
  }
  return null;
};

const resolveHwyGeoResponsibilityElectoralMemberSearchGeoBaseInfoIdForKinds = (
  filterKinds: readonly HwyElectoralGeoKind[],
  selection: HwyGeoResponsibilityElectoralSelection,
  rowGeoBaseInfoId: string | null | undefined,
): string | null => {
  for (let index = filterKinds.length - 1; index >= 0; index -= 1) {
    const kind = filterKinds[index]!;
    const id = selection[kind]?.trim();
    if (id) {
      return id;
    }
  }
  const pinned = rowGeoBaseInfoId?.trim();
  return pinned || null;
};

export const hwyGeoResponsibilityElectoralLeafKind = (
  level: HwyGeoResponsibilityLevel,
): HwyElectoralGeoKind | null => {
  const steps = hwyGeoResponsibilityElectoralCascadeKinds(level);
  return steps.length > 0 ? steps[steps.length - 1]! : null;
};

/** Parent base_info id for listing children of `kind` given current selection. */
export const resolveHwyGeoResponsibilityElectoralOptionsParentId = (input: {
  kind: HwyElectoralGeoKind;
  selection: HwyGeoResponsibilityElectoralSelection;
  provinceHasGhavateh: boolean;
}): string | null => {
  const { kind, selection, provinceHasGhavateh } = input;
  switch (kind) {
    case 'province':
      return null;
    case 'ghavateh':
      return selection.province?.trim() || null;
    case 'circle':
      if (provinceHasGhavateh) {
        return selection.ghavateh?.trim() || null;
      }
      return selection.province?.trim() || null;
    case 'maktab':
      return selection.circle?.trim() || null;
    case 'region':
      return selection.maktab?.trim() || null;
    default:
      return null;
  }
};

/** Whether a cascade step should render (ghavateh only when the province has sectors). */
export const isHwyGeoResponsibilityElectoralCascadeStepVisible = (input: {
  kind: HwyElectoralGeoKind;
  provinceHasGhavateh: boolean;
}): boolean => {
  if (input.kind === 'ghavateh') {
    return input.provinceHasGhavateh;
  }
  return true;
};

/** Clear downstream picks when an ancestor changes. */
export const clearHwyGeoResponsibilityElectoralSelectionFrom = (
  selection: HwyGeoResponsibilityElectoralSelection,
  fromKind: HwyElectoralGeoKind,
  cascadeKinds: readonly HwyElectoralGeoKind[],
): HwyGeoResponsibilityElectoralSelection => {
  const startIndex = cascadeKinds.indexOf(fromKind);
  if (startIndex < 0) {
    return { ...selection };
  }
  const next: HwyGeoResponsibilityElectoralSelection = { ...selection };
  for (const kind of cascadeKinds.slice(startIndex + 1)) {
    delete next[kind];
  }
  return next;
};

export const resolveHwyGeoResponsibilityElectoralLeafGeoBaseInfoId = (
  level: HwyGeoResponsibilityLevel,
  selection: HwyGeoResponsibilityElectoralSelection,
): string | null => {
  const leafKind = hwyGeoResponsibilityElectoralLeafKind(level);
  if (!leafKind) {
    return null;
  }
  const id = selection[leafKind]?.trim();
  return id || null;
};
