import { apiGet } from '../../shared/api/client';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';
import { sanitizeHwySelfRegistrationPhoneInput } from './selfRegistration/hwySelfRegistrationPhone';

export type HwyMemberSimilarMembersFilter = {
  matchFirstName: boolean;
  matchFatherName: boolean;
  matchGrandfatherName: boolean;
  matchBirthYear: boolean;
  matchPhone1: boolean;
};

/** Legacy `FindSimilars`: only `chk_Phone1` checked on first load; other criteria opt-in. */
export const HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER: HwyMemberSimilarMembersFilter = {
  matchFirstName: false,
  matchFatherName: false,
  matchGrandfatherName: false,
  matchBirthYear: false,
  matchPhone1: true,
};

function parseSimilarMembersFilterFlag(raw: string, defaultValue: boolean): boolean {
  const normalized = raw.trim().toLowerCase();
  if (normalized === '1' || normalized === 'true' || normalized === 'yes') {
    return true;
  }
  if (normalized === '0' || normalized === 'false' || normalized === 'no') {
    return false;
  }
  return defaultValue;
}

export function parseHwyMemberSimilarMembersFilter(
  query: Record<string, unknown>,
): HwyMemberSimilarMembersFilter {
  const keys = [
    'matchFirstName',
    'matchFatherName',
    'matchGrandfatherName',
    'matchBirthYear',
    'matchPhone1',
  ] as const;
  const hasAny = keys.some((key) => query[key] !== undefined && query[key] !== '');
  if (!hasAny) {
    return { ...HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER };
  }
  return {
    matchFirstName: parseSimilarMembersFilterFlag(String(query.matchFirstName ?? ''), false),
    matchFatherName: parseSimilarMembersFilterFlag(String(query.matchFatherName ?? ''), false),
    matchGrandfatherName: parseSimilarMembersFilterFlag(String(query.matchGrandfatherName ?? ''), false),
    matchBirthYear: parseSimilarMembersFilterFlag(String(query.matchBirthYear ?? ''), false),
    matchPhone1: parseSimilarMembersFilterFlag(String(query.matchPhone1 ?? ''), true),
  };
}

function appendSimilarMembersFilterParams(
  query: URLSearchParams,
  filter: HwyMemberSimilarMembersFilter,
): void {
  query.set('matchFirstName', filter.matchFirstName ? '1' : '0');
  query.set('matchFatherName', filter.matchFatherName ? '1' : '0');
  query.set('matchGrandfatherName', filter.matchGrandfatherName ? '1' : '0');
  query.set('matchBirthYear', filter.matchBirthYear ? '1' : '0');
  query.set('matchPhone1', filter.matchPhone1 ? '1' : '0');
}

export type HwyMemberSimilarMembersAnchor = {
  memberId: string;
  phone1?: string;
  phone2?: string;
  firstname?: string;
  fathername?: string;
  grandfathername?: string;
  lastname?: string;
  birthYear?: string;
  provinceTitle?: string;
  displayFullName?: string;
  username?: string;
};

export type HwyMemberSimilarMemberRow = {
  id: string;
  username?: string;
  displayFullName?: string;
  birthYear?: string;
  phone1?: string;
  phone2?: string;
  membershipStatusCode?: string;
  membershipStatusCodeTitle?: string;
  membershipStatusCodeTitleUiColor?: string;
  avatarUrl?: string;
  nakhebinId?: string;
  familyCode?: string;
  membershipOn?: string;
  electoralDivisionPath?: string;
  addrProvinceTitle?: string;
};

export type HwyMemberSimilarMembersPayload = {
  anchor: HwyMemberSimilarMembersAnchor;
  byName: HwyMemberSimilarMemberRow[];
  byFilter: HwyMemberSimilarMemberRow[];
  appliedFilter: HwyMemberSimilarMembersFilter;
};

export type HwyMemberSimilarMembersResponse = {
  success?: boolean;
  message?: string;
  data?: HwyMemberSimilarMembersPayload;
};

export function normalizeHwySimilarMemberPhone(raw: string | null | undefined): string {
  return sanitizeHwySelfRegistrationPhoneInput(String(raw ?? '')).replace(/\D/g, '');
}

export function buildHwyMemberSimilarMembersPath(
  memberId: string,
  cultureId?: string | null,
  filter: HwyMemberSimilarMembersFilter = HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER,
): string {
  const encoded = encodeURIComponent(memberId.trim());
  const lang = resolveHwyMemberDirectoryDetailLang(cultureId);
  const query = new URLSearchParams({ lang });
  appendSimilarMembersFilterParams(query, filter);
  return `/api/hwy/member-directory/${encoded}/similar-members?${query.toString()}`;
}

/** React Query key slice for similar-members filter flags. */
export function hwyMemberSimilarMembersFilterQueryKeyPart(
  filter: HwyMemberSimilarMembersFilter,
): readonly [boolean, boolean, boolean, boolean, boolean] {
  return [
    filter.matchFirstName,
    filter.matchFatherName,
    filter.matchGrandfatherName,
    filter.matchBirthYear,
    filter.matchPhone1,
  ];
}

export function hwyMemberSimilarMembersFilterFromQueryKeyPart(
  part: readonly [boolean, boolean, boolean, boolean, boolean],
): HwyMemberSimilarMembersFilter {
  return {
    matchFirstName: part[0],
    matchFatherName: part[1],
    matchGrandfatherName: part[2],
    matchBirthYear: part[3],
    matchPhone1: part[4],
  };
}

export function hasActiveHwyMemberSimilarMembersFilter(filter: HwyMemberSimilarMembersFilter): boolean {
  return (
    filter.matchFirstName
    || filter.matchFatherName
    || filter.matchGrandfatherName
    || filter.matchBirthYear
    || filter.matchPhone1
  );
}

export async function fetchHwyMemberSimilarMembers(
  memberId: string,
  cultureId?: string | null,
  filter: HwyMemberSimilarMembersFilter = HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER,
  signal?: AbortSignal,
): Promise<HwyMemberSimilarMembersPayload> {
  const { data, response } = await apiGet<HwyMemberSimilarMembersResponse>(
    buildHwyMemberSimilarMembersPath(memberId, cultureId, filter),
    signal ? { signal } : undefined,
  );
  if (!response.ok || data?.success === false || !data?.data) {
    const message = data?.message?.trim() || `Could not load similar members. (HTTP ${response.status})`;
    throw new Error(message);
  }
  return data.data;
}
