import { Op, type WhereOptions } from 'sequelize';
import { normalizeHwyHouseholdMemberId } from '../../../domain/hwy/hwyFamilyHouseholdMemberId';

export const collectNakhebinLinkedMemberIds = (
  nakhebin: ReadonlyArray<Record<string, unknown>>,
): Array<string | number> => {
  const values = new Set<string | number>();
  for (const row of nakhebin) {
    const key = normalizeHwyHouseholdMemberId(row.memberId ?? row.member_id);
    if (!key) {
      continue;
    }
    values.add(key);
    const numeric = Number(key);
    if (Number.isFinite(numeric)) {
      values.add(numeric);
    }
  }
  return [...values];
};

/** Members in this electoral family, plus any row linked from nakhebin `member_id`. */
export const buildHouseholdMemberDirectoryWhere = (
  regionId: string,
  familyCode: string,
  linkedMemberIds: ReadonlyArray<string | number>,
): WhereOptions => {
  const familyInRegion = {
    nakhebinRegionId: regionId,
    [Op.or]: [
      { family_code: familyCode },
      { familyCode },
      { nakhebin_family_code: familyCode },
      { nakhebinFamilyCode: familyCode },
    ],
  };

  if (linkedMemberIds.length === 0) {
    return familyInRegion;
  }

  return {
    [Op.or]: [
      familyInRegion,
      { id: { [Op.in]: [...linkedMemberIds] } },
    ],
  };
};
