import { Op, type WhereOptions } from 'sequelize';

import type { EdgeModelDefinition } from '../../../shared/api/contracts/data-api';
import {
  buildWhereFromFilter,
  parseFilterQuery,
  type ParsedFilter,
} from '../../services/data-api/dataApiQuery';
import { mergeWhereAnd, mergeWhereOr } from '../../services/record-policy/whereMerge';

const readTextFilterValue = (
  operators: Record<string, string> | undefined,
): string | undefined => {
  if (!operators) {
    return undefined;
  }
  const raw = operators.contains ?? operators.like ?? operators.eq;
  if (typeof raw !== 'string') {
    return undefined;
  }
  const trimmed = raw.trim();
  return trimmed.length > 0 ? trimmed : undefined;
};

const stripMembershipIdentifierFields = (parsed: ParsedFilter): ParsedFilter => {
  const next: ParsedFilter = { ...parsed };
  delete next.username;
  delete next.trackingCode;
  return next;
};

/** Handled via {@link buildHwyMontadheminInstituteFilterWhere} / list fast path — not a member view column. */
const stripMontadheminInstituteToolbarFilter = (parsed: ParsedFilter): ParsedFilter => {
  const next: ParsedFilter = { ...parsed };
  delete next.montadheminInstituteId;
  return next;
};

/**
 * When legacy toolbar binds the same membership search to username + trackingCode (OR mode),
 * both filter params carry the same value — merge into one OR clause instead of AND.
 */
export const buildHwyMemberDirectoryListLegacyFilterWhere = (
  query: Record<string, unknown>,
  allowedFilterFields: Set<string>,
  columns: EdgeModelDefinition['columns'],
): WhereOptions => {
  const parsed = stripMontadheminInstituteToolbarFilter(parseFilterQuery(query));
  const usernameValue = readTextFilterValue(parsed.username);
  const trackingValue = readTextFilterValue(parsed.trackingCode);

  let membershipIdentifierOrWhere: WhereOptions | undefined;
  let filterForBase = parsed;

  if (usernameValue && trackingValue && usernameValue === trackingValue) {
    filterForBase = stripMembershipIdentifierFields(parsed);
    membershipIdentifierOrWhere = mergeWhereOr(
      { username: { [Op.like]: `%${usernameValue}%` } },
      { trackingCode: { [Op.like]: `%${trackingValue}%` } },
    );
  }

  const baseWhere = buildWhereFromFilter(filterForBase, allowedFilterFields, columns);
  return mergeWhereAnd(baseWhere, membershipIdentifierOrWhere);
};
