/** Legacy UI / RPC naming drift → canonical `HWY_MEMBER_SEGMENT_LIST_DEFINITIONS.legacyCode`. */
export const HWY_MEMBER_LIST_SCOPE_LEGACY_ALIASES: Record<string, string> = {
  /** Legacy component `HWY_Members_List_ImageFix` vs catalog `Imagefix`. */
  HWY_Members_List_ImageFix: 'HWY_Members_List_Imagefix',
  /** Legacy RPC `Read_List_AlMontazemin_AlForat` vs catalog `AlMontadhemin`. */
  HWY_Members_List_AlMontazemin_AlForat: 'HWY_Members_List_AlMontadhemin_AlForat',
};

export const normalizeHwyMemberListScopeLegacyCode = (legacyCode: string): string => {
  const trimmed = legacyCode.trim();
  return HWY_MEMBER_LIST_SCOPE_LEGACY_ALIASES[trimmed] ?? trimmed;
};
