export type HwyMemberTarghinAdminQueue = 'pending' | 'approved' | 'rejected' | 'all';

export const HWY_MEMBER_TARGHIN_ADMIN_QUEUES: HwyMemberTarghinAdminQueue[] = [
  'pending',
  'approved',
  'rejected',
  'all',
];

export function parseHwyMemberTarghinAdminQueue(
  raw: string | null | undefined,
): HwyMemberTarghinAdminQueue {
  const value = String(raw ?? '').trim() as HwyMemberTarghinAdminQueue;
  if ((HWY_MEMBER_TARGHIN_ADMIN_QUEUES as string[]).includes(value)) {
    return value;
  }
  return 'pending';
}

