import sql from 'mssql';
import { SETTINGS_PATH } from '../../src/server/config/settingsFile';
import { readControlPlaneDatabaseSettings } from '../../src/server/db/controlPlaneDatabase';
import { connectMssqlControlPlane } from '../hwy-phase1/hwyDataSource';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));

export async function ensureHwyRegistrationStateColumns(): Promise<void> {
  const cp = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  if (cp.provider !== 'sqlserver') {
    return;
  }
  const ddl = fs.readFileSync(
    path.join(scriptDir, '../hwy-phase1/db/install/hwy_registration_state_columns.sqlserver.sql'),
    'utf8',
  );
  const pool = await connectMssqlControlPlane();
  try {
    for (const batch of ddl.split(/^\s*GO\s*$/im).map((part) => part.trim()).filter(Boolean)) {
      await pool.request().query(batch);
    }
  } finally {
    await pool.close();
  }
}
