import type {
  HwyCandidatePipelineInterviewRecord,
  HwyInterview2022HazerinMember,
} from '../../../domain/hwy/hwyCandidatePipelineInterviewCatalog';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

export const mapHwyCandidatePipelineInterviewRow = (
  row: Record<string, unknown>,
): HwyCandidatePipelineInterviewRecord => {
  let hazerin: HwyInterview2022HazerinMember[] = [];
  const rawHazerin = row.hazerinJson;
  if (typeof rawHazerin === 'string' && rawHazerin.trim()) {
    try {
      const parsed = JSON.parse(rawHazerin) as unknown;
      if (Array.isArray(parsed)) {
        hazerin = parsed.map((item) => {
          const o = item as Record<string, unknown>;
          return {
            memberId: trim(o.memberId ?? o.Id ?? o.id),
            username: o.username ? trim(o.username as string) : o.UserName ? trim(o.UserName as string) : null,
            firstName: o.firstName ? trim(o.firstName as string) : o.FirstName ? trim(o.FirstName as string) : null,
            fatherName: o.fatherName ? trim(o.fatherName as string) : o.FatherName ? trim(o.FatherName as string) : null,
            grandFatherName: o.grandFatherName
              ? trim(o.grandFatherName as string)
              : o.GrandFatherName
                ? trim(o.GrandFatherName as string)
                : null,
            lastName: o.lastName ? trim(o.lastName as string) : o.LastName ? trim(o.LastName as string) : null,
          };
        }).filter((h) => h.memberId);
      }
    } catch {
      hazerin = [];
    }
  }

  return {
    interviewId: trim(row.interviewId as string),
    memberId: trim(row.memberId as string),
    interviewOn: trim(row.interviewOn as string),
    karizma: Number(row.karizma),
    likeToLearnMore: Number(row.likeToLearnMore),
    showIsFan: Number(row.showIsFan),
    abilityToMakeTeam: Number(row.abilityToMakeTeam),
    ghodratElec: Number(row.ghodratElec),
    knowsMasoolin: Number(row.knowsMasoolin),
    isMotefaregh: row.isMotefaregh === true || row.isMotefaregh === 1,
    isMotefareghSaat: Number(row.isMotefareghSaat),
    note: trim(row.note as string),
    finalResult: Number(row.finalResult),
    finalResultTitle: row.finalResultTitle ? trim(row.finalResultTitle as string) : null,
    createdBy: row.createdBy ? trim(row.createdBy as string) : null,
    createdOn: row.createdOn ? trim(row.createdOn as string) : null,
    hazerin,
  };
};
