import { apiGet, apiPost, resolveApiMutationErrorMessage } from '../../shared/api/client';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';

export type HwyMembershipStage = 'call_center' | 'local';

export type HwyMembershipCallCenterAction = 'approve' | 'reject' | 'unreject';

export type HwyMembershipLocalAction =
  | 'approve'
  | 'reject_final'
  | 'reject_returnable'
  | 'reject_verification_bank'
  | 'unreject';

export type HwyMembershipDecisionKind = 'approve' | 'reject' | 'unreject';

export type HwyMembershipDecisionReasonOption = {
  value: string;
  label: string;
  shortName?: string | null;
};

export type HwyMembershipDecisionInput = {
  decisionReasonCode: string;
  decisionNote: string;
  /** Required for local approve — must match SMS tosigh_confirm_code on the member row. */
  tosighConfirmCode?: string;
  /** Call-center approve when a referrer exists: true = remove referrer, false = keep. */
  clearReferrer?: boolean;
  /** Call-center approve: set or replace primary referrer (archives prior referrer to deleted columns). */
  replaceReferrerUsername?: string;
  replaceReferrerRelationId?: string | number | null;
};

const stagePath = (stage: HwyMembershipStage, memberId: string): string => (
  stage === 'call_center'
    ? `/api/hwy/membership/call-center/${encodeURIComponent(memberId)}/decision`
    : `/api/hwy/membership/local/${encodeURIComponent(memberId)}/decision`
);

export function buildHwyMembershipDecisionReasonsPath(
  stage: HwyMembershipStage,
  decision: HwyMembershipDecisionKind,
  cultureId?: string | null,
): string {
  const lang = resolveHwyMemberDirectoryDetailLang(cultureId);
  return `/api/hwy/membership/decision-reasons?stage=${encodeURIComponent(stage)}&decision=${encodeURIComponent(decision)}&lang=${encodeURIComponent(lang)}`;
}

export async function fetchHwyMembershipDecisionReasonOptions(
  stage: HwyMembershipStage,
  decision: HwyMembershipDecisionKind,
  cultureId?: string | null,
): Promise<HwyMembershipDecisionReasonOption[]> {
  const { data, response } = await apiGet<{ success?: boolean; data?: HwyMembershipDecisionReasonOption[] }>(
    buildHwyMembershipDecisionReasonsPath(stage, decision, cultureId),
  );
  if (!response.ok || !data?.success) {
    throw new Error(
      resolveApiMutationErrorMessage(data, `Could not load membership decision reasons. (HTTP ${response.status})`),
    );
  }
  return data.data ?? [];
}

export async function applyHwyMembershipCallCenterDecision(
  memberId: string,
  action: HwyMembershipCallCenterAction,
  input: HwyMembershipDecisionInput,
): Promise<{ memberId: string; membershipStatusCode: string }> {
  const { data, response } = await apiPost<{
    success?: boolean;
    data?: { memberId: string; membershipStatusCode: string };
    message?: string;
  }>(stagePath('call_center', memberId), {
    action,
    decisionReasonCode: input.decisionReasonCode || null,
    decisionNote: input.decisionNote,
    ...(input.clearReferrer === undefined ? {} : { clearReferrer: input.clearReferrer }),
    ...(input.replaceReferrerUsername?.trim()
      ? {
        replaceReferrerUsername: input.replaceReferrerUsername.trim(),
        replaceReferrerRelationId: input.replaceReferrerRelationId ?? null,
      }
      : {}),
  });
  if (!response.ok || !data?.success || !data.data?.memberId) {
    throw new Error(resolveApiMutationErrorMessage(data, 'Could not save call center decision.'));
  }
  return data.data;
}

export async function applyHwyMembershipLocalDecision(
  memberId: string,
  action: HwyMembershipLocalAction,
  input: HwyMembershipDecisionInput,
): Promise<{ memberId: string; membershipStatusCode: string }> {
  const { data, response } = await apiPost<{
    success?: boolean;
    data?: { memberId: string; membershipStatusCode: string };
    message?: string;
  }>(stagePath('local', memberId), {
    action,
    decisionReasonCode: input.decisionReasonCode || null,
    decisionNote: input.decisionNote,
    ...(action === 'approve' ? { tosighConfirmCode: input.tosighConfirmCode?.trim() ?? '' } : {}),
  });
  if (!response.ok || !data?.success || !data.data?.memberId) {
    throw new Error(resolveApiMutationErrorMessage(data, 'Could not save local verification decision.'));
  }
  return data.data;
}

export type HwyMembershipStatusIdMap = Partial<Record<
  | 'pending_call_center'
  | 'pending_local'
  | 'active'
  | 'pending_cancellation'
  | 'rejected_call_center'
  | 'rejected_local'
  | 'rejected_local_verification',
  string
>>;

export function resolveHwyMembershipTarghinedStatusId(
  ids: HwyMembershipStatusIdMap | undefined,
): string | null {
  const code = ids?.pending_cancellation?.trim();
  return code || null;
}

export function resolveHwyMembershipActiveStatusId(
  ids: HwyMembershipStatusIdMap | undefined,
): string | null {
  const code = ids?.active?.trim();
  return code || null;
}

export function isHwyMemberMembershipStatusActive(
  membershipStatusCode: string | null | undefined,
  ids: HwyMembershipStatusIdMap | undefined,
): boolean {
  const activeId = resolveHwyMembershipActiveStatusId(ids);
  const code = membershipStatusCode?.trim() ?? '';
  return Boolean(activeId && code === activeId);
}

export function isHwyMemberMembershipStatusTarghined(
  membershipStatusCode: string | null | undefined,
  ids: HwyMembershipStatusIdMap | undefined,
): boolean {
  const targhinedId = resolveHwyMembershipTarghinedStatusId(ids);
  const code = membershipStatusCode?.trim() ?? '';
  return Boolean(targhinedId && code === targhinedId);
}

export function resolveHwyMembershipStageForStatusId(
  membershipStatusCode: string | null | undefined,
  ids: HwyMembershipStatusIdMap,
): HwyMembershipStage | null {
  const code = String(membershipStatusCode ?? '').trim();
  if (!code) {
    return null;
  }
  if (code === ids.pending_call_center || code === ids.rejected_call_center) {
    return 'call_center';
  }
  if (
    code === ids.pending_local
    || code === ids.rejected_local
    || code === ids.rejected_local_verification
  ) {
    return 'local';
  }
  return null;
}
