import { legacyHwyRoleIdToPlatformRoleName } from './hwyMemberListLegacyAccess';

/** Legacy `HWY_Members_List_OrgMembership` — institutes with org-initiated transfer (not every `allows_invite` row). */
export type HwyOrgMembershipTransferInstituteSpec = {
  instituteCode: string;
  legacyOrganizationId: number;
  /** Legacy AppEnd role id for «طلب نقل» (admin bypasses). */
  legacyRequestRoleId: number;
  /** Culture key for request button label (`hwy.orgMembership.request.*`). */
  requestLabelKey: string;
};

export const HWY_ORG_MEMBERSHIP_TRANSFER_PAGE_LEGACY_CODE = 'HWY_Members_List_OrgMembership';

export const HWY_ORG_MEMBERSHIP_TRANSFER_LEGACY_READ_METHOD = 'Read_List_All_OrgMembership';

