export const hwyOrgMembershipTransferRequestRoleNames = (): string[] => (
  [...new Set(
    HWY_ORG_MEMBERSHIP_TRANSFER_INSTITUTES.map(
      (row) => legacyHwyRoleIdToPlatformRoleName(row.legacyRequestRoleId),
    ),
  )]
);

export const findHwyOrgMembershipTransferInstituteByCode = (
  instituteCode: string,
): HwyOrgMembershipTransferInstituteSpec | undefined => (
  HWY_ORG_MEMBERSHIP_TRANSFER_INSTITUTES.find((row) => row.instituteCode === instituteCode)
);
