import type { HwyGeoResponsibilityLevel } from './hwyGeoResponsibilityCatalog';
import {
  resolveHwyElectoralPathSegmentGeoLevelFromSegments,
} from '../../shared/lib/hwyElectoralPathSegmentLevels';
import {
  HWY_GEO_RESPONSIBILITY_ROUTE_PREFIX,
  hwyGeoResponsibilityPathSegment,
} from './hwyGeoResponsibilityNav';

export const HWY_GEO_RESPONSIBILITY_LIST_SEARCH_PARAM = 'search';

/**
 * Member electoral `title_path` display order: province → ghavateh → circle → region → maktab
 * (matches `splitHwyElectoralBreadcrumbParts` / Studio breadcrumb order, not `HWY_ELECTORAL_GEO_KINDS` cascade order).
 */
export const resolveHwyElectoralPathSegmentGeoLevel = (
  segmentIndex: number,
  segmentCount: number,
  segments?: readonly string[],
): HwyGeoResponsibilityLevel | null => {
  if (segmentIndex < 0 || segmentIndex >= segmentCount || segmentCount === 0) {
    return null;
  }
  if (segments && segments.length === segmentCount) {
    return resolveHwyElectoralPathSegmentGeoLevelFromSegments(segments, segmentIndex);
  }
  if (segmentCount >= 5) {
    if (segmentIndex === segmentCount - 1) {
      return 'maktab';
    }
    const prefix: HwyGeoResponsibilityLevel[] = ['province', 'ghavateh', 'circle', 'region'];
    return prefix[segmentIndex] ?? null;
  }
  if (segmentCount === 4) {
    const levels: HwyGeoResponsibilityLevel[] = ['province', 'ghavateh', 'circle', 'region'];
    return levels[segmentIndex] ?? null;
  }
  if (segmentCount === 3) {
    const levels: HwyGeoResponsibilityLevel[] = ['province', 'ghavateh', 'region'];
    return levels[segmentIndex] ?? null;
  }
  if (segmentCount === 2) {
    const levels: HwyGeoResponsibilityLevel[] = ['province', 'region'];
    return levels[segmentIndex] ?? null;
  }
  return 'province';
};

export const buildHwyGeoResponsibilityListRelativePath = (
  level: HwyGeoResponsibilityLevel,
  options?: { search?: string | null },
): string => {
  const segment = hwyGeoResponsibilityPathSegment(level);
  const params = new URLSearchParams();
  const search = options?.search?.trim();
  if (search) {
    params.set(HWY_GEO_RESPONSIBILITY_LIST_SEARCH_PARAM, search);
  }
  const qs = params.toString();
  return `/${HWY_GEO_RESPONSIBILITY_ROUTE_PREFIX}/${segment}${qs ? `?${qs}` : ''}`;
};

/** Mount-agnostic list URL from the current shell pathname (portal or Studio). */
export const buildHwyGeoResponsibilityListPathFromPathname = (
  pathname: string,
  level: HwyGeoResponsibilityLevel,
  options?: { search?: string | null },
): string => {
  const base = pathname.replace(
    new RegExp(`/${HWY_GEO_RESPONSIBILITY_ROUTE_PREFIX}(?:/[^/]+)?$`, 'i'),
    '',
  );
  const relative = buildHwyGeoResponsibilityListRelativePath(level, options);
  return `${base}${relative}`;
};
