import { QueryTypes } from 'sequelize';

import type {
  HwyMemberDossierChangeLogEvent,
  HwyMemberDossierChangeLogKind,
  HwyMemberDossierChangeLogPayload,
} from '../../../domain/hwy/hwyMemberDossierChangeLog';
import { sortHwyMemberDossierChangeLogEvents } from '../../../domain/hwy/hwyMemberDossierChangeLog';
import { applyHwyMemberDossierChangeLogMemberActorFallback } from '../../../domain/hwy/hwyMemberDossierChangeLogActor';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { formatProfileDisplayName } from '../../../shared/profile/profileDisplayName';
import { formatHwyMemberDossierChangeLogRecordEventValue } from '../../../domain/hwy/hwyMemberDossierChangeLogRecordValue';
import { listRecordEvents } from '../record-events/queryRecordEvents';
import { listHwyMemberPhoneHistory } from './hwyMemberPhoneRequests.service';
import { ensureHwyMemberDossierSatellitesSchema } from './ensureHwyMemberDossierSatellitesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { attachBaseInfoTitles, resolveHwyMemberPrimaryKey } from './hwyMemberDossierSatellites.service';

type ChangeLogActorIdentity = {
  username: string | null;
  displayName: string | null;
};

const loadChangeLogActorIdentities = async (ids: number[]): Promise<Map<number, ChangeLogActorIdentity>> => {
  const identities = new Map<number, ChangeLogActorIdentity>();
  if (ids.length === 0) {
    return identities;
  }
  const sequelize = getControlPlaneSequelize();
  const placeholders = ids.map((_, index) => `:actor${index}`).join(', ');
  const replacements = Object.fromEntries(ids.map((id, index) => [`actor${index}`, id]));
  const rows = await sequelize.query<Record<string, unknown>>(
    `SELECT u.id AS id,
            u.username AS username,
            p.firstname AS firstname,
            p.lastname AS lastname,
            p.company_name AS company_name,
            p.person_type_code AS person_type_code
     FROM dbo.base_users u
     LEFT JOIN dbo.base_user_profiles p ON p.user_id = u.id
     WHERE u.id IN (${placeholders})`,
    { replacements, type: QueryTypes.SELECT },
  );
  for (const row of rows) {
    const id = Number(row.id);
    if (!Number.isFinite(id) || id <= 0) {
      continue;
    }
    identities.set(id, {
      username: String(row.username ?? '').trim() || null,
      displayName: formatProfileDisplayName({
        firstname: row.firstname as string | null,
        lastname: row.lastname as string | null,
        companyName: row.company_name as string | null,
        personTypeCode: row.person_type_code as string | null,
      }),
    });
  }
  return identities;
};

const attachChangeLogActorIdentities = async (events: HwyMemberDossierChangeLogEvent[]): Promise<void> => {
  const ids = [
    ...new Set(
      events
        .map((event) => event.actorUserId?.trim())
        .filter((id): id is string => Boolean(id))
        .map((id) => Number(id))
        .filter((id) => Number.isFinite(id) && id > 0),
    ),
  ];
  if (ids.length === 0) {
    return;
  }
  const identities = await loadChangeLogActorIdentities(ids);
  for (const event of events) {
    if (event.actorDisplayName?.trim()) {
      continue;
    }
    const raw = event.actorUserId?.trim();
    if (!raw) {
      continue;
    }
    const id = Number(raw);
    const identity = identities.get(id);
    if (!identity) {
      continue;
    }
    event.actorUsername = identity.username ?? event.actorUsername;
    event.actorDisplayName = identity.displayName ?? event.actorDisplayName;
  }
};

const readString = (row: Record<string, unknown>, key: string): string =>
  String(row[key] ?? '').trim();

const toIso = (raw: unknown): string => {
  if (raw === null || raw === undefined || raw === '') {
    return '';
  }
  const date = raw instanceof Date ? raw : new Date(String(raw));
  if (Number.isNaN(date.getTime())) {
    return '';
  }
  return date.toISOString();
};

const pushEvent = (
  bucket: HwyMemberDossierChangeLogEvent[],
  event: Omit<HwyMemberDossierChangeLogEvent, 'id'> & { id?: string },
): void => {
  const occurredAt = event.occurredAt.trim();
  if (!occurredAt) {
    return;
  }
  const sourceId = event.sourceId?.trim() || '0';
  const id = event.id?.trim() || `${event.kind}:${sourceId}:${occurredAt}`;
  bucket.push({ ...event, id, sourceId: event.sourceId?.trim() || undefined });
};

const mapRecordEventKind = (eventKind: string): HwyMemberDossierChangeLogKind => 'recordEvent';

const appendRecordEventsToChangeLog = (
  bucket: HwyMemberDossierChangeLogEvent[],
  items: Awaited<ReturnType<typeof listRecordEvents>>['items'],
  idPrefix: string,
): void => {
  for (const item of items) {
    const field = item.field?.trim();
    const from = formatHwyMemberDossierChangeLogRecordEventValue(field, item.fromValue);
    const to = formatHwyMemberDossierChangeLogRecordEventValue(field, item.toValue);
    pushEvent(bucket, {
      kind: mapRecordEventKind(item.eventKind),
      occurredAt: item.occurredAt,
      actorUserId: item.actorUserId != null ? String(item.actorUserId) : undefined,
      actorUsername: item.actorUsername ?? undefined,
      actorDisplayName: item.actorDisplayName ?? undefined,
      copyParams: {
        eventKind: item.eventKind,
        ...(field ? { field } : {}),
        ...(from ? { from } : {}),
        ...(to ? { to } : {}),
      },
      sourceTable: 'base_record_events',
      sourceId: item.id,
      id: `${idPrefix}:${item.id}`,
      detailLines: [
        { labelKey: 'hwy.memberDossier.changeLog.detail.eventKind', value: item.eventKind },
        ...(field ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.field', value: field }] : []),
        ...(from ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.fromValue', value: from }] : []),
        ...(to ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.toValue', value: to }] : []),
        ...(item.reasonCode
          ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.reasonCode', value: item.reasonCode }]
          : []),
      ],
    });
  }
};

const appendPhoneRequestEventsToChangeLog = async (
  bucket: HwyMemberDossierChangeLogEvent[],
  memberId: number,
  queryLang: string,
): Promise<void> => {
  try {
    const rows = await listHwyMemberPhoneHistory(String(memberId), queryLang);
    for (const row of rows) {
      if (row.finalResult === true) {
        continue;
      }
      const isSwap = row.requestKind === 'swap';
      const field = isSwap ? 'phone1,phone2' : `phone${row.phoneSlot ?? 1}`;
      const from = isSwap
        ? `${row.phone1Before ?? ''} ⇄ ${row.phone2Before ?? ''}`.trim()
        : (row.oldPhone ?? '');
      const to = isSwap
        ? `${row.phone2Before ?? ''} ⇄ ${row.phone1Before ?? ''}`.trim()
        : (row.newPhone ?? '');
      const status = row.finalResult == null ? 'pending' : 'rejected';
      pushEvent(bucket, {
        kind: 'recordEvent',
        occurredAt: row.requestAt,
        actorUserId: undefined,
        actorUsername: row.requestByUsername ?? undefined,
        copyParams: {
          eventKind: isSwap ? 'phone.swap.request' : 'phone.change.request',
          field,
          ...(from ? { from } : {}),
          ...(to ? { to } : {}),
          status,
        },
        sourceTable: isSwap ? 'hwy_member_phone_swap_requests' : 'hwy_member_phone_change_requests',
        sourceId: row.id,
        id: `phoneRequest:${row.id}`,
        detailLines: [
          { labelKey: 'hwy.memberDossier.changeLog.detail.phoneRequestKind', value: isSwap ? 'swap' : 'change' },
          { labelKey: 'hwy.memberDossier.changeLog.detail.phoneRequestStatus', value: status },
          ...(from ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.fromValue', value: from }] : []),
          ...(to ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.toValue', value: to }] : []),
          ...(row.requestNote
            ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.requestNote', value: row.requestNote }]
            : []),
          ...(row.finalReasonTitle
            ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalReason', value: row.finalReasonTitle }]
            : []),
          ...(row.finalNote
            ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalNote', value: row.finalNote }]
            : []),
        ],
      });
    }
  } catch {
    // Phone request tables may be unavailable on older databases.
  }
};

export async function listHwyMemberDossierChangeLog(
  memberIdRaw: string,
  queryLang = 'ar',
): Promise<HwyMemberDossierChangeLogPayload> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return { events: [] };
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
  const memberId = await resolveHwyMemberPrimaryKey(memberIdRaw);
  const events: HwyMemberDossierChangeLogEvent[] = [];

  const memberRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_member', {
    member_id: memberId,
  });
  const member = memberRows[0];
  if (!member) {
    throw new Error('Member not found.');
  }

  const cultureId = resolveBaseInfoCultureId(queryLang);
  const statusCode = readString(member, 'membershipStatusCode');
  const channelCode = readString(member, 'registrationChannelCode');
  const enrichIds = [statusCode, channelCode].filter(Boolean);
  const enriched = enrichIds.length
    ? await listBaseInfoEnrichmentRowsByIds(enrichIds, cultureId)
    : [];
  const titleById = new Map(
    enriched.map((item) => [String(item.id ?? '').trim(), String(item.title ?? item.title_canonical ?? '').trim()]),
  );

  const createdAt = toIso(member.createdAt);
  const updatedAt = toIso(member.updatedAt);
  const membershipOn = toIso(member.membershipOn);
  const statusUpdatedOn = toIso(member.membershipStatusUpdatedOn);
  const userId = readString(member, 'userId');
  const nakhebinId = readString(member, 'nakhebinId');
  const username = readString(member, 'username');
  const createdBy = readString(member, 'createdBy');
  const updatedBy = readString(member, 'updatedBy');
  const statusTitle = titleById.get(statusCode) || statusCode;
  const channelTitle = titleById.get(channelCode) || channelCode;

  pushEvent(events, {
    kind: 'member.created',
    occurredAt: createdAt,
    actorUserId: createdBy || undefined,
    copyParams: {
      ...(channelTitle ? { channelTitle } : {}),
    },
    sourceTable: 'hwy_members',
    sourceId: readString(member, 'memberId'),
    detailLines: [
      ...(username
        ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.membershipNumber', value: username }]
        : []),
      ...(channelTitle
        ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.registrationChannel', value: channelTitle }]
        : []),
      ...(userId ? [{ labelKey: 'hwy.memberDossier.field.userId', value: userId }] : []),
    ],
  });

  if (membershipOn && membershipOn.slice(0, 10) !== createdAt.slice(0, 10)) {
    pushEvent(events, {
      kind: 'member.membershipOn',
      occurredAt: membershipOn,
      actorUserId: createdBy || undefined,
      sourceTable: 'hwy_members',
      sourceId: readString(member, 'memberId'),
      detailLines: [
        {
          labelKey: 'hwy.memberDossier.changeLog.detail.membershipOn',
          value: membershipOn.slice(0, 10),
        },
      ],
    });
  }

  if (statusUpdatedOn) {
    pushEvent(events, {
      kind: 'member.statusChanged',
      occurredAt: statusUpdatedOn,
      actorUserId: updatedBy || createdBy || undefined,
      copyParams: statusTitle ? { statusTitle } : {},
      sourceTable: 'hwy_members',
      sourceId: readString(member, 'memberId'),
      detailLines: statusTitle ? [{ labelKey: 'hwy.memberDossier.field.status', value: statusTitle }] : [],
    });
  }

  if (userId) {
    pushEvent(events, {
      kind: 'member.userLinked',
      occurredAt: createdAt,
      actorUserId: createdBy || undefined,
      copyParams: { userId },
      sourceTable: 'hwy_members',
      sourceId: readString(member, 'memberId'),
      detailLines: [{ labelKey: 'hwy.memberDossier.field.userId', value: userId }],
    });
  }

  if (nakhebinId) {
    pushEvent(events, {
      kind: 'member.nakhebinLinked',
      occurredAt: createdAt,
      actorUserId: createdBy || undefined,
      copyParams: { nakhebinId },
      sourceTable: 'hwy_members',
      sourceId: readString(member, 'memberId'),
      detailLines: [{ labelKey: 'hwy.memberDossier.changeLog.detail.nakhebinId', value: nakhebinId }],
    });
  }

  if (updatedAt && updatedAt !== createdAt) {
    pushEvent(events, {
      kind: 'member.updated',
      occurredAt: updatedAt,
      actorUserId: updatedBy || undefined,
      sourceTable: 'hwy_members',
      sourceId: readString(member, 'memberId'),
      detailLines: [],
    });
  }

  const fileRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_files', {
    member_id: memberId,
  });
  const fileKindIds = [...new Set(fileRows.map((row) => readString(row, 'fileKindCode')).filter(Boolean))];
  const fileKindTitles = fileKindIds.length
    ? await listBaseInfoEnrichmentRowsByIds(fileKindIds, cultureId)
    : [];
  const fileKindTitleById = new Map(
    fileKindTitles.map((item) => [String(item.id ?? '').trim(), String(item.title ?? item.title_canonical ?? '').trim()]),
  );

  for (const row of fileRows) {
    const fileId = readString(row, 'id');
    const fileName = readString(row, 'originalFileName') || 'Attachment';
    const kindTitle = fileKindTitleById.get(readString(row, 'fileKindCode')) || readString(row, 'fileKindCode');
    const fileCreated = toIso(row.createdAt);
    const fileUpdated = toIso(row.updatedAt);
    pushEvent(events, {
      kind: 'file.added',
      occurredAt: fileCreated,
      actorUserId: readString(row, 'createdBy') || undefined,
      copyParams: {
        fileName,
        ...(kindTitle ? { kindTitle } : {}),
      },
      sourceTable: 'hwy_member_files',
      sourceId: fileId,
      detailLines: [
        { labelKey: 'hwy.memberDossier.changeLog.detail.fileName', value: fileName },
        ...(kindTitle ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.documentKind', value: kindTitle }] : []),
      ],
    });
    if (fileUpdated && fileUpdated !== fileCreated) {
      pushEvent(events, {
        kind: 'file.updated',
        occurredAt: fileUpdated,
        actorUserId: readString(row, 'updatedBy') || readString(row, 'createdBy') || undefined,
        copyParams: { fileName },
        sourceTable: 'hwy_member_files',
        sourceId: fileId,
        detailLines: [{ labelKey: 'hwy.memberDossier.changeLog.detail.fileName', value: fileName }],
      });
    }
  }

  const noteRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_notes', {
    member_id: memberId,
  });
  for (const row of noteRows) {
    const body = readString(row, 'body');
    const preview = body.length > 120 ? `${body.slice(0, 117)}…` : body;
    pushEvent(events, {
      kind: 'note.added',
      occurredAt: toIso(row.createdAt),
      actorUserId: readString(row, 'createdBy') || undefined,
      copyParams: preview ? { preview } : {},
      sourceTable: 'hwy_member_notes',
      sourceId: readString(row, 'id'),
      detailLines: body ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.note', value: body }] : [],
    });
  }

  const instituteRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_institutes', {
    member_id: memberId,
  });
  for (const row of instituteRows) {
    const instituteTitle = readString(row, 'instituteTitle') || readString(row, 'instituteId');
    const linkId = readString(row, 'id');
    pushEvent(events, {
      kind: 'institute.linked',
      occurredAt: toIso(row.createdAt),
      actorUserId: readString(row, 'createdBy') || undefined,
      copyParams: { instituteTitle },
      sourceTable: 'hwy_member_institutes',
      sourceId: linkId,
      detailLines: [{ labelKey: 'hwy.memberDossier.changeLog.detail.institute', value: instituteTitle }],
    });
    const invitedAt = toIso(row.invitedAt);
    if (invitedAt) {
      pushEvent(events, {
        kind: 'institute.invited',
        occurredAt: invitedAt,
        actorUserId: readString(row, 'invitedBy') || readString(row, 'createdBy') || undefined,
        copyParams: { instituteTitle },
        sourceTable: 'hwy_member_institutes',
        sourceId: linkId,
        detailLines: [{ labelKey: 'hwy.memberDossier.changeLog.detail.institute', value: instituteTitle }],
      });
    }
    const activatedAt = toIso(row.activatedAt);
    if (activatedAt) {
      pushEvent(events, {
        kind: 'institute.activated',
        occurredAt: activatedAt,
        actorUserId:
          readString(row, 'instituteStateUpdatedBy') || readString(row, 'createdBy') || undefined,
        copyParams: { instituteTitle },
        sourceTable: 'hwy_member_institutes',
        sourceId: linkId,
        detailLines: [{ labelKey: 'hwy.memberDossier.changeLog.detail.institute', value: instituteTitle }],
      });
    }
  }

  const targhinRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_targhin', {
    member_id: memberId,
  });
  await attachBaseInfoTitles(
    targhinRows,
    [{ codeField: 'finalReasonCode', titleField: 'finalReasonCodeTitle' }],
    queryLang,
  );
  for (const row of targhinRows) {
    const targhinId = readString(row, 'id');
    const note = readString(row, 'requestNote');
    const statusCode = readString(row, 'statusCode');
    pushEvent(events, {
      kind: 'targhin.requested',
      occurredAt: toIso(row.createdAt),
      actorUserId: readString(row, 'createdBy') || undefined,
      copyParams: {
        ...(note ? { note } : {}),
        ...(statusCode ? { statusCode } : {}),
      },
      sourceTable: 'hwy_member_targhin_requests',
      sourceId: targhinId,
      detailLines: [
        ...(note ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.requestNote', value: note }] : []),
        ...(statusCode ? [{ labelKey: 'hwy.memberDossier.field.status', value: statusCode }] : []),
      ],
    });

    const finalAt = toIso(row.finalAt);
    const finalNote = readString(row, 'finalNote');
    const finalReasonTitle = readString(row, 'finalReasonCodeTitle');
    if (statusCode === 'approved' && finalAt) {
      pushEvent(events, {
        kind: 'targhin.approved',
        occurredAt: finalAt,
        actorUserId: readString(row, 'finalBy') || undefined,
        copyParams: {
          ...(finalNote ? { note: finalNote } : {}),
          ...(finalReasonTitle ? { reason: finalReasonTitle } : {}),
        },
        sourceTable: 'hwy_member_targhin_requests',
        sourceId: targhinId,
        id: `targhin.approved:${targhinId}`,
        detailLines: [
          ...(finalReasonTitle
            ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalReason', value: finalReasonTitle }]
            : []),
          ...(finalNote ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalNote', value: finalNote }] : []),
        ],
      });
    }
    if (statusCode === 'rejected' && finalAt) {
      pushEvent(events, {
        kind: 'targhin.rejected',
        occurredAt: finalAt,
        actorUserId: readString(row, 'finalBy') || undefined,
        copyParams: {
          ...(finalNote ? { note: finalNote } : {}),
          ...(finalReasonTitle ? { reason: finalReasonTitle } : {}),
        },
        sourceTable: 'hwy_member_targhin_requests',
        sourceId: targhinId,
        id: `targhin.rejected:${targhinId}`,
        detailLines: [
          ...(finalReasonTitle
            ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalReason', value: finalReasonTitle }]
            : []),
          ...(finalNote ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.finalNote', value: finalNote }] : []),
        ],
      });
    }
  }

  const securityRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_security', {
    member_id: memberId,
  });
  for (const row of securityRows) {
    pushEvent(events, {
      kind: 'security.profileCreated',
      occurredAt: toIso(row.createdAt),
      actorUserId: readString(row, 'createdBy') || undefined,
      sourceTable: 'hwy_member_security_profile',
      sourceId: readString(row, 'id'),
      detailLines: [],
    });
  }

  const trackingRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_tracking', {
    member_id: memberId,
  });
  for (const row of trackingRows) {
    const code = readString(row, 'code');
    pushEvent(events, {
      kind: 'registration.trackingCode',
      occurredAt: toIso(row.createdAt),
      copyParams: {
        ...(code ? { code } : {}),
      },
      sourceTable: 'hwy_members',
      sourceId: readString(row, 'id'),
      detailLines: [
        ...(code ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.trackingCode', value: code }] : []),
        ...(readString(row, 'status')
          ? [{ labelKey: 'hwy.memberDossier.field.status', value: readString(row, 'status') }]
          : []),
      ],
    });
  }

  const usernameRows = await execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_change_log_username_repo', {
    member_id: memberId,
  });
  for (const row of usernameRows) {
    const reservedUsername = readString(row, 'username');
    pushEvent(events, {
      kind: 'registration.usernameReserved',
      occurredAt: toIso(row.reservedAt),
      copyParams: reservedUsername ? { username: reservedUsername } : {},
      sourceTable: 'hwy_username_repo',
      sourceId: readString(row, 'id'),
      detailLines: reservedUsername
        ? [{ labelKey: 'hwy.memberDossier.changeLog.detail.username', value: reservedUsername }]
        : [],
    });
  }

  try {
    const memberRecordEvents = await listRecordEvents(
      {
        subjectKind: 'hwy_members',
        subjectId: String(memberId),
        limit: 500,
      },
      { unmask: true },
    );
    appendRecordEventsToChangeLog(events, memberRecordEvents.items, 'recordEventMember');
  } catch {
    // Record events are optional enrichment when the table or ACL is unavailable.
  }

  if (userId) {
    try {
      const recordEvents = await listRecordEvents(
        {
          subjectKind: 'base_users',
          subjectId: userId,
          limit: 200,
        },
        { unmask: true },
      );
      appendRecordEventsToChangeLog(events, recordEvents.items, 'recordEventUser');
    } catch {
      // Record events are optional enrichment when the table or ACL is unavailable.
    }
  }

  await appendPhoneRequestEventsToChangeLog(events, memberId, queryLang);

  applyHwyMemberDossierChangeLogMemberActorFallback(events, { createdBy, updatedBy });
  await attachChangeLogActorIdentities(events);

  return { events: sortHwyMemberDossierChangeLogEvents(events) };
};
