const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const ACTIVITY_TYPE_CATEGORY = 'Activity Type';
const COURSE_TYPE_CATEGORY = 'Course Type';

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy courses/activities write requires SQL Server control plane.');
  }
  await ensureHwyCoursesActivitiesSchema();
  await ensureHwyDbObjects();
};

const resolveActorUsername = async (userId: number | null): Promise<string> => {
  if (userId == null || !Number.isFinite(userId) || userId <= 0) {
    return 'admin';
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ username: string }>(
    `SELECT username FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  return trim(rows[0]?.username) || 'admin';
};

const findBaseInfoCategoryId = async (categoryTitle: string): Promise<string> => {
  const category = await prisma().baseInfo.findFirst({
    where: { title: categoryTitle, isActive: true },
    select: { id: true },
  });
  if (!category?.id) {
    throw new Error(`Base Info category "${categoryTitle}" is not available.`);
  }
  return category.id;
};

const assertBaseInfoNode = async (code: string, categoryTitle: string): Promise<void> => {
  const id = trim(code);
  if (!/^\d+$/.test(id)) {
    throw new Error('Invalid type code.');
  }
  const row = await prisma().baseInfo.findFirst({
    where: { id, isActive: true },
    select: { id: true, title: true, parentId: true },
  });
  if (!row) {
    throw new Error('Type code not found in Base Info.');
  }
  const categoryId = await findBaseInfoCategoryId(categoryTitle);
  let cursor: string | null = row.id;
  let underCategory = false;
  for (let depth = 0; depth < 12 && cursor; depth += 1) {
    if (cursor === categoryId) {
      underCategory = true;
      break;
    }
    const parent = await prisma().baseInfo.findUnique({
      where: { id: cursor },
      select: { parentId: true },
    });
    cursor = parent?.parentId ?? null;
  }
  if (!underCategory) {
    throw new Error('Type code is not under the expected vocabulary.');
  }
};

const allocateNextId = async (table: 'hwy_activities' | 'hwy_courses'): Promise<number> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ next_id: number | string }>(
    `SELECT ISNULL(MAX(id), 0) + 1 AS next_id FROM dbo.${table} WITH (UPDLOCK, HOLDLOCK)`,
    { type: QueryTypes.SELECT },
  );
  const nextId = Number(rows[0]?.next_id);
  if (!Number.isFinite(nextId) || nextId <= 0) {
    throw new Error('Could not allocate a record id.');
  }
  return nextId;
};

export type HwyCoursesActivitiesVocabOption = {
  code: string;
  label: string;
  parentCode: string | null;
};

export async function listHwyCoursesActivitiesVocabOptions(input: {
  kind: 'activity' | 'course';
  parentCode?: string | null;
  queryLang?: string;
}): Promise<HwyCoursesActivitiesVocabOption[]> {
  const categoryTitle = input.kind === 'activity' ? ACTIVITY_TYPE_CATEGORY : COURSE_TYPE_CATEGORY;
  const categoryId = await findBaseInfoCategoryId(categoryTitle);
  const parentCode = trim(input.parentCode);
  const parentId = parentCode || categoryId;

  const rows = await prisma().baseInfo.findMany({
    where: { parentId, isActive: true },
    orderBy: [{ viewOrder: 'asc' }, { title: 'asc' }],
    select: { id: true, title: true, parentId: true },
  });

  const cultureId = trim(input.queryLang) || 'iq';
  const { listBaseInfoEnrichmentRowsByIds } = await import('../base-info/treeRepository');
  const enriched = await listBaseInfoEnrichmentRowsByIds(
    rows.map((row) => row.id),
    cultureId,
  );
  const labelById = new Map(
    enriched.map((entry) => [
      String(entry.id ?? '').trim(),
      trim(String(entry.title ?? entry.title_canonical ?? '')),
    ]),
  );

  return rows.map((row) => ({
    code: row.id,
    label: labelById.get(row.id) || row.title,
    parentCode: row.parentId,
  }));
}

export type UpsertHwyActivityDraftInput = {
  title: string;
  note?: string | null;
  activityDate?: string | null;
  activityTypeCode: string;
  activitySubtypeCode?: string | null;
  nashatLocation?: string | null;
  legacyProvinceId?: string | null;
  enableSelfAnnouncement?: boolean | null;
  requireSubmissionDeviceMetadata?: boolean | null;
  tajammoatMode?: boolean;
  nbLocationLat?: string | null;
  nbLocationLon?: string | null;
  nbMaxDistanceM?: number | null;
  nbWindowStartAt?: string | null;
  nbWindowEndAt?: string | null;
  nbLegacyProvinceId?: string | null;
  nbLegacyCircleId?: number | null;
  nbLegacyMaktabId?: number | null;
  nbLegacyRegionId?: number | null;
  nbLegacyGenderId?: number | null;
  nbAllowedRoles?: string | null;
  nbOrganizationIds?: string | null;
  nbOnlyKashafeh?: boolean | null;
  nbAllowGov?: boolean | null;
};

const readBodyField = (body: unknown, key: string): unknown =>
  body && typeof body === 'object' ? (body as Record<string, unknown>)[key] : undefined;

const readOptionalBodyBoolean = (body: unknown, key: string): boolean | null | undefined => {
  const value = readBodyField(body, key);
  if (value === undefined) {
    return undefined;
  }
  if (value === null) {
    return null;
  }
  if (typeof value === 'boolean') {
    return value;
  }
  if (value === 1 || value === '1' || value === 'true') {
    return true;
  }
  if (value === 0 || value === '0' || value === 'false') {
    return false;
  }
  return undefined;
};

const readOptionalBodyNumber = (body: unknown, key: string): number | null | undefined => {
  const value = readBodyField(body, key);
  if (value === undefined) {
    return undefined;
  }
  if (value === null || value === '') {
    return null;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

