export async function createHwyActivityDraft(
  input: UpsertHwyActivityDraftInput,
  actorUserId: number | null,
  queryLang: string,
): Promise<HwyActivityAdminDetail> {
  await assertSqlServer();
  const title = trim(input.title);
  if (!title) {
    throw new Error('Activity title is required.');
  }
  const activityTypeCode = trim(input.activityTypeCode);
  if (!activityTypeCode) {
    throw new Error('Activity type is required.');
  }
  await assertBaseInfoNode(activityTypeCode, ACTIVITY_TYPE_CATEGORY);
  const activitySubtypeCode = trim(input.activitySubtypeCode);
  if (activitySubtypeCode) {
    await assertBaseInfoNode(activitySubtypeCode, ACTIVITY_TYPE_CATEGORY);
  }
  const actor = await resolveActorUsername(actorUserId);
  const id = await allocateNextId('hwy_activities');
  await execHwyProcedure('hwy_activity_insert_draft', {
    id,
    title,
    note: trim(input.note) || null,
    activity_date: trim(input.activityDate) || null,
    activity_type_code: activityTypeCode,
    activity_subtype_code: activitySubtypeCode || null,
    status_code: HWY_ACTIVITY_STATUS_REGISTER,
    nashat_location: trim(input.nashatLocation) || null,
    enable_self_announcement: input.enableSelfAnnouncement ? 1 : 0,
    require_submission_device_metadata: input.requireSubmissionDeviceMetadata == null
      ? null
      : input.requireSubmissionDeviceMetadata ? 1 : 0,
    legacy_created_by: actor,
  });
  if (input.tajammoatMode && activityTypeCode === HWY_ACTIVITY_CENTRAL_TYPE_CODE) {
    await execHwyActivityUpdateTajammoat(Number(id), input, actor);
  }
  return readHwyActivityAdminDetail(String(id), queryLang);
}

export async function updateHwyActivityDraft(
  activityIdRaw: string,
  input: UpsertHwyActivityDraftInput,
  actorUserId: number | null,
  queryLang: string,
): Promise<HwyActivityAdminDetail> {
  await assertSqlServer();
  const activityId = Number(trim(activityIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Invalid activity id.');
  }
  const sequelize = getControlPlaneSequelize();
  const existing = await sequelize.query<{ status_code: string | null }>(
    `SELECT status_code FROM dbo.hwy_activities WHERE id = :activityId`,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  if (!existing.length) {
    throw new Error('Activity not found.');
  }
  const isTajammoatUpdate =
    Boolean(input.tajammoatMode)
    && trim(input.activityTypeCode) === HWY_ACTIVITY_CENTRAL_TYPE_CODE;
  if (!isTajammoatUpdate && trim(existing[0].status_code) !== HWY_ACTIVITY_STATUS_REGISTER) {
    throw new Error('Only draft activities can be edited.');
  }
  const title = trim(input.title);
  if (!title) {
    throw new Error('Activity title is required.');
  }
  const activityTypeCode = trim(input.activityTypeCode);
  if (!activityTypeCode) {
    throw new Error('Activity type is required.');
  }
  await assertBaseInfoNode(activityTypeCode, ACTIVITY_TYPE_CATEGORY);
  const activitySubtypeCode = trim(input.activitySubtypeCode);
  if (activitySubtypeCode) {
    await assertBaseInfoNode(activitySubtypeCode, ACTIVITY_TYPE_CATEGORY);
  }
  const actor = await resolveActorUsername(actorUserId);
  if (isTajammoatUpdate) {
    await execHwyActivityUpdateTajammoat(activityId, input, actor);
    return readHwyActivityAdminDetail(String(activityId), queryLang);
  }
  try {
    await execHwyProcedure('hwy_activity_update_draft', {
      activity_id: activityId,
      expected_status_code: HWY_ACTIVITY_STATUS_REGISTER,
      title,
      note: trim(input.note) || null,
      activity_date: trim(input.activityDate) || null,
      activity_type_code: activityTypeCode,
      activity_subtype_code: activitySubtypeCode || null,
      nashat_location: trim(input.nashatLocation) || null,
      enable_self_announcement: input.enableSelfAnnouncement ? 1 : 0,
      require_submission_device_metadata: input.requireSubmissionDeviceMetadata == null
        ? null
        : input.requireSubmissionDeviceMetadata ? 1 : 0,
      legacy_updated_by: actor,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('56000')) {
      throw new Error('Activity not found.');
    }
    if (message.includes('56001')) {
      throw new Error('Only draft activities can be edited.');
    }
    throw error;
  }
  return readHwyActivityAdminDetail(String(activityId), queryLang);
}

export type UpsertHwyCourseDraftInput = {
  courseDate?: string | null;
  courseTypeCode: string;
  courseSubtypeCode?: string | null;
  note?: string | null;
  trainerMemberId?: string | null;
  legacyProvinceId?: string | null;
};

const parseOptionalLegacyProvinceId = (raw: string | null | undefined): number | null => {
  const text = trim(raw);
  if (!text || !/^\d+$/.test(text)) {
    return null;
  }
  const value = Number(text);
  return Number.isFinite(value) ? value : null;
};

export async function createHwyCourseDraft(
  input: UpsertHwyCourseDraftInput,
  actorUserId: number | null,
  queryLang: string,
): Promise<HwyCourseAdminDetail> {
  await assertSqlServer();
  const courseTypeCode = trim(input.courseTypeCode);
  if (!courseTypeCode) {
    throw new Error('Course type is required.');
  }
  await assertBaseInfoNode(courseTypeCode, COURSE_TYPE_CATEGORY);
  const courseSubtypeCode = trim(input.courseSubtypeCode);
  if (courseSubtypeCode) {
    await assertBaseInfoNode(courseSubtypeCode, COURSE_TYPE_CATEGORY);
  }
  const trainerMemberIdRaw = trim(input.trainerMemberId);
  const trainerMemberId = trainerMemberIdRaw && /^\d+$/.test(trainerMemberIdRaw)
    ? Number(trainerMemberIdRaw)
    : null;
  const legacyProvinceId = parseOptionalLegacyProvinceId(input.legacyProvinceId);
  const actor = await resolveActorUsername(actorUserId);
  const id = await allocateNextId('hwy_courses');
  await execHwyProcedure('hwy_course_insert_draft', {
    id,
    trainer_member_id: trainerMemberId,
    legacy_province_id: legacyProvinceId,
    course_type_code: courseTypeCode,
    course_subtype_code: courseSubtypeCode || null,
    note: trim(input.note) || null,
    course_date: trim(input.courseDate) || null,
    status_code: HWY_COURSE_STATUS_DRAFT,
    legacy_created_by: actor,
  });
  return readHwyCourseAdminDetail(String(id), queryLang);
}

