import { QueryTypes } from 'sequelize';

import type { HwyMemberListFace } from '../../../domain/hwy/hwyMemberListFace';
import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatProfileDisplayName } from '../../../shared/profile/profileDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { loadLegacyHwyMemberFacesByUsernames } from './hwyLegacyMemberFaceByUsername.service';
import { isHwyLegacyPlatformAdminActorKey } from '../../../domain/hwy/hwyLegacyPlatformAdminActor';
import { resolveHwyLegacyActorUserId, resolveHwyPlatformAdminUserId } from './hwyLegacyStaffUserId';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

export const negoAuthorHasLabel = (author: HwyMemberTarghinAdminMemberFace | null | undefined): boolean => (
  Boolean(author?.displayFullName?.trim() || author?.username?.trim())
);

const mapVmRowToFace = (row: Record<string, unknown>): HwyMemberTarghinAdminMemberFace => ({
  id: trim(row.id as string | undefined),
  username: trim(row.username as string | undefined) || null,
  displayFullName: formatHwyMemberPersonDisplayName(trim(row.display_full_name as string | undefined)) || null,
  genderCode: trim(row.gender_code as string | undefined) || null,
  avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
    avatarUrl: trim(row.avatar_url as string | undefined) || null,
    hasProfileImage: row.has_profile_image === true || row.has_profile_image === 1,
    userId: row.user_id != null ? Number(row.user_id) : null,
  }),
  phone: trim(row.phone1 as string | undefined) || null,
  electoralDivisionPath: null,
});

export const loadHwyAccountUserFacesByUserIds = async (
  userIds: number[],
): Promise<Map<number, HwyMemberTarghinAdminMemberFace>> => {
  const map = new Map<number, HwyMemberTarghinAdminMemberFace>();
  const ids = [...new Set(userIds.filter((id) => Number.isFinite(id) && id > 0))];
  if (!ids.length) {
    return map;
  }
  const placeholders = ids.map((_, index) => `:uid${index}`).join(', ');
  const replacements = Object.fromEntries(ids.map((id, index) => [`uid${index}`, id]));
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      u.id AS id,
      u.username AS username,
      p.firstname AS firstname,
      p.lastname AS lastname,
      p.company_name AS company_name,
      p.person_type_code AS person_type_code
    FROM dbo.base_users u WITH (NOLOCK)
    LEFT JOIN dbo.base_user_profiles p WITH (NOLOCK) ON p.user_id = u.id
    WHERE u.id IN (${placeholders})
    `,
    { replacements, type: QueryTypes.SELECT },
  );
  for (const row of rows) {
    const id = Number(row.id);
    if (!Number.isFinite(id) || id <= 0) {
      continue;
    }
    const username = trim(row.username as string | undefined) || null;
    const displayFullName = formatHwyMemberPersonDisplayName(
      formatProfileDisplayName({
        firstname: row.firstname as string | null | undefined,
        lastname: row.lastname as string | null | undefined,
        companyName: row.company_name as string | null | undefined,
        personTypeCode: row.person_type_code as string | null | undefined,
      }) || username,
    );
    map.set(id, {
      id: `user-${id}`,
      username,
      displayFullName,
      genderCode: null,
      avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
        avatarUrl: null,
        hasProfileImage: false,
        userId: id,
      }),
      phone: null,
      electoralDivisionPath: null,
    });
  }
  return map;
};

export const loadHwyMemberFacesByPlatformUserIds = async (
  userIds: number[],
): Promise<Map<number, HwyMemberTarghinAdminMemberFace>> => {
  const map = new Map<number, HwyMemberTarghinAdminMemberFace>();
  const ids = [...new Set(userIds.filter((id) => Number.isFinite(id) && id > 0))];
  if (!ids.length) {
    return map;
  }
  const placeholders = ids.map((_, index) => `:uid${index}`).join(', ');
  const replacements = Object.fromEntries(ids.map((id, index) => [`uid${index}`, id]));
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      CAST(id AS VARCHAR(32)) AS id,
      username,
      display_full_name,
      gender_code,
      avatar_url,
      has_profile_image,
      user_id,
      phone1,
      electoral_division_path
    FROM dbo.vw_hwy_members WITH (NOLOCK)
    WHERE user_id IN (${placeholders})
    `,
    { replacements, type: QueryTypes.SELECT },
  );
  for (const row of rows) {
    const userId = row.user_id != null ? Number(row.user_id) : null;
    if (userId == null || !Number.isFinite(userId) || userId <= 0) {
      continue;
    }
    map.set(userId, {
      ...mapVmRowToFace(row),
      electoralDivisionPath: trim(row.electoral_division_path as string | undefined) || null,
    });
  }
  return map;
};

