const loadMemberFacesByUsernames = async (
  usernames: string[],
): Promise<Map<string, HwyMemberTarghinAdminMemberFace>> => {
  const map = new Map<string, HwyMemberTarghinAdminMemberFace>();
  const keys = [...new Set(usernames.map(trim).filter(Boolean))];
  if (!keys.length) {
    return map;
  }
  const placeholders = keys.map((_, index) => `:un${index}`).join(', ');
  const replacements = Object.fromEntries(keys.map((key, index) => [`un${index}`, key]));
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      CAST(id AS VARCHAR(32)) AS id,
      username,
      display_full_name,
      gender_code,
      avatar_url,
      has_profile_image,
      user_id,
      phone1
    FROM dbo.vw_hwy_members WITH (NOLOCK)
    WHERE username IN (${placeholders})
    `,
    { replacements, type: QueryTypes.SELECT },
  );
  for (const row of rows) {
    const username = trim(row.username as string | undefined);
    if (!username) {
      continue;
    }
    map.set(username, mapVmRowToFace(row));
  }
  return map;
};

export const loadMemberIdByUserId = async (userId: number): Promise<number | null> => {
  if (!Number.isFinite(userId) || userId <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number | string }>(
    `SELECT TOP 1 id FROM dbo.hwy_members WITH (NOLOCK) WHERE user_id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  const memberId = rows[0]?.id != null ? Number(rows[0].id) : null;
  return memberId != null && Number.isFinite(memberId) && memberId > 0 ? memberId : null;
};

/**
 * Full member directory face for legacy HWY actor strings (member id, username, or base_users id).
 * Prefers `vw_hwy_members` (phone, avatar, gender) over bare account chips.
 */
const loadMemberFaceViaBaseUserMemberLink = async (
  legacy: string,
): Promise<HwyMemberTarghinAdminMemberFace | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT TOP 1
      CAST(vm.id AS VARCHAR(32)) AS id,
      vm.username,
      vm.display_full_name,
      vm.gender_code,
      vm.avatar_url,
      vm.has_profile_image,
      vm.user_id,
      vm.phone1
    FROM dbo.base_users u WITH (NOLOCK)
    INNER JOIN dbo.hwy_members hm WITH (NOLOCK) ON hm.user_id = u.id
    INNER JOIN dbo.vw_hwy_members vm WITH (NOLOCK) ON vm.id = hm.id
    WHERE u.username = :legacy
       OR CAST(u.id AS VARCHAR(32)) = :legacy
       OR (
         TRY_CONVERT(BIGINT, :legacy) IS NOT NULL
         AND u.id = TRY_CONVERT(BIGINT, :legacy)
       )
    `,
    { replacements: { legacy }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    return null;
  }
  const face = mapVmRowToFace(rows[0]);
  return negoAuthorHasLabel(face) ? face : null;
};

const loadMemberFaceByLegacyActorKey = async (
  legacy: string,
): Promise<HwyMemberTarghinAdminMemberFace | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT TOP 1
      CAST(id AS VARCHAR(32)) AS id,
      username,
      display_full_name,
      gender_code,
      avatar_url,
      has_profile_image,
      user_id,
      phone1
    FROM dbo.vw_hwy_members WITH (NOLOCK)
    WHERE CAST(id AS VARCHAR(32)) = :legacy
       OR username = :legacy
       OR (
         TRY_CONVERT(BIGINT, :legacy) IS NOT NULL
         AND user_id = TRY_CONVERT(BIGINT, :legacy)
       )
    ORDER BY
      CASE
        WHEN CAST(id AS VARCHAR(32)) = :legacy THEN 0
        WHEN username = :legacy THEN 1
        ELSE 2
      END
    `,
    { replacements: { legacy }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    return null;
  }
  const face = mapVmRowToFace(rows[0]);
  return negoAuthorHasLabel(face) ? face : null;
};

export async function resolveHwyMemberListFaceForLegacyActor(
  legacyActorRaw: string | null | undefined,
): Promise<HwyMemberListFace | null> {
  const legacy = trim(legacyActorRaw);
  if (!legacy) {
    return null;
  }

  if (isHwyLegacyPlatformAdminActorKey(legacy)) {
    const adminUserId = await resolveHwyPlatformAdminUserId();
    if (adminUserId != null && adminUserId > 0) {
      const accountFaces = await loadHwyAccountUserFacesByUserIds([adminUserId]);
      const adminFace = accountFaces.get(adminUserId);
      if (adminFace && negoAuthorHasLabel(adminFace)) {
        return adminFace;
      }
    }
  }

  const byDirectory = await loadMemberFaceByLegacyActorKey(legacy);
  if (byDirectory) {
    return byDirectory;
  }

  const byUserMemberLink = await loadMemberFaceViaBaseUserMemberLink(legacy);
  if (byUserMemberLink) {
    return byUserMemberLink;
  }

  const byUsername = await loadMemberFacesByUsernames([legacy]);
  const usernameFace = byUsername.get(legacy);
  if (usernameFace && negoAuthorHasLabel(usernameFace)) {
    return usernameFace;
  }

  if (/^\d+$/.test(legacy)) {
    const memberId = Number(legacy);
    const byMember = await loadMemberFacesByMemberIds([memberId]);
    const memberFace = byMember.get(memberId);
    if (memberFace && negoAuthorHasLabel(memberFace)) {
      return memberFace;
    }
  }

  const legacyFaces = await loadLegacyHwyMemberFacesByUsernames([legacy]);
  const legacyFace = legacyFaces.get(legacy);
  if (legacyFace && negoAuthorHasLabel(legacyFace)) {
    return legacyFace;
  }

  const userId = await resolveHwyLegacyActorUserId(legacy);
  if (userId != null && userId > 0) {
    const linkedMemberId = await loadMemberIdByUserId(userId);
    if (linkedMemberId != null) {
      const linkedFaces = await loadMemberFacesByMemberIds([linkedMemberId]);
      const linkedFace = linkedFaces.get(linkedMemberId);
      if (linkedFace && negoAuthorHasLabel(linkedFace)) {
        return linkedFace;
      }
    }
    const accountFaces = await loadHwyAccountUserFacesByUserIds([userId]);
    const accountFace = accountFaces.get(userId);
    if (accountFace && negoAuthorHasLabel(accountFace)) {
      return accountFace;
    }
  }

  if (!/^\d+$/.test(legacy)) {
    return {
      id: legacy,
      username: legacy,
      displayFullName: legacy,
      genderCode: null,
      avatarUrl: null,
      phone: null,
      electoralDivisionPath: null,
    };
  }

  return {
    id: `legacy-membership-${legacy}`,
    username: legacy,
    displayFullName: legacy,
    genderCode: null,
    avatarUrl: null,
    phone: null,
    electoralDivisionPath: null,
  };
}

export async function resolveNegoNoteAuthorsBatch(
  rawRows: Array<{ id: string; createdByLegacy: string; createdByUserId: number | null; author: HwyMemberTarghinAdminMemberFace | null }>,
): Promise<Map<string, HwyMemberTarghinAdminMemberFace | null>> {
  const result = new Map<string, HwyMemberTarghinAdminMemberFace | null>();
  const legacies = [...new Set(rawRows.map((row) => trim(row.createdByLegacy)).filter(Boolean))];

  const legacyUserId = new Map<string, number | null>();
  await Promise.all(legacies.map(async (legacy) => {
    legacyUserId.set(legacy, await resolveHwyLegacyActorUserId(legacy));
  }));

  const userIds = new Set<number>();
  const memberIds = new Set<number>();
  const usernames = new Set<string>();

  for (const row of rawRows) {
    const legacy = trim(row.createdByLegacy);
    const storedUserId = row.createdByUserId;
    if (storedUserId != null && storedUserId > 0) {
      userIds.add(storedUserId);
    }
    const resolved = legacyUserId.get(legacy);
    if (resolved != null && resolved > 0) {
      userIds.add(resolved);
    }
    if (/^\d+$/.test(legacy)) {
      memberIds.add(Number(legacy));
    } else if (legacy) {
      usernames.add(legacy);
    }
  }

  const [accountFaces, memberById, memberByUsername, memberByPlatformUserId] = await Promise.all([
    loadHwyAccountUserFacesByUserIds([...userIds]),
    loadMemberFacesByMemberIds([...memberIds]),
    loadMemberFacesByUsernames([...usernames]),
    loadHwyMemberFacesByPlatformUserIds([...userIds]),
  ]);

  for (const row of rawRows) {
    if (negoAuthorHasLabel(row.author)) {
      result.set(row.id, row.author);
      continue;
    }

    const legacy = trim(row.createdByLegacy);
    const resolvedUserId = legacyUserId.get(legacy) ?? null;
    const storedUserId = row.createdByUserId;

    if (/^\d+$/.test(legacy)) {
      const memberFace = memberById.get(Number(legacy));
      if (memberFace && negoAuthorHasLabel(memberFace)) {
        result.set(row.id, memberFace);
        continue;
      }
    }

    const memberByUser = memberByUsername.get(legacy);
    if (memberByUser && negoAuthorHasLabel(memberByUser)) {
      result.set(row.id, memberByUser);
      continue;
    }

    for (const platformUserId of [resolvedUserId, storedUserId]) {
      if (platformUserId == null || platformUserId <= 0) {
        continue;
      }
      const memberVmFace = memberByPlatformUserId.get(platformUserId);
      if (memberVmFace && negoAuthorHasLabel(memberVmFace)) {
        result.set(row.id, memberVmFace);
        break;
      }
    }
    if (result.has(row.id)) {
      continue;
    }

    const accountFromResolved = resolvedUserId ? accountFaces.get(resolvedUserId) : undefined;
    if (accountFromResolved) {
      result.set(row.id, accountFromResolved);
      continue;
    }

    const accountFromStored = storedUserId ? accountFaces.get(storedUserId) : undefined;
    if (accountFromStored) {
      result.set(row.id, accountFromStored);
      continue;
    }

    if (legacy && !/^\d+$/.test(legacy)) {
      result.set(row.id, {
        id: legacy,
        username: legacy,
        displayFullName: legacy,
        genderCode: null,
        avatarUrl: null,
        phone: null,
        electoralDivisionPath: null,
      });
      continue;
    }

    result.set(row.id, row.author);
  }

  return result;
}
