/**
 * Hawiety Base Info — platform-owned Arabic (iq) display titles.
 * Used when legacy `HWY_BaseInformation.Title` is empty or on fresh seed (survives `hwy:etl:vocab` re-runs).
 */
import { persistBaseInfoLocaleTextsBulk } from '../../../src/server/domain/base-info/baseInfoCultureTranslationStore';
import { HWY_REGISTRATION_CHANNEL_IQ_TITLE_OVERRIDES } from '../../../src/domain/hwy/hwyRegistrationChannelIqTitles';
import { findHwyBaseInfoItemId } from './seedHwyBaseInfo';

export const HWY_MEMBERSHIP_STATUS_CATEGORY = 'Membership Status';
export const HWY_SECURITY_CLEARANCE_ANSWER_CATEGORY = 'Security Clearance Answer';
export const HWY_REGISTRATION_CHANNEL_CATEGORY = 'Registration Channel';

/** shortName → iq title (Membership Status). */
export const HWY_MEMBERSHIP_STATUS_IQ_TITLE_OVERRIDES: Readonly<Record<string, string>> = {
};

/** shortName → iq title (Security Clearance Answer / حالة التسجيل values). */
export const HWY_SECURITY_CLEARANCE_ANSWER_IQ_TITLE_OVERRIDES: Readonly<Record<string, string>> = {
  allowed: 'مسموح',
  denied: 'مرفوض',
  conditional: 'مشروط',
  under_review: 'قيد الدراسة',
};

export type HwyBaseInfoIqLocaleEntry = {
  baseInfoId: string;
  locales: { iq: { title: string } };
};

export async function buildHwyMembershipStatusIqOverrideEntries(): Promise<HwyBaseInfoIqLocaleEntry[]> {
  const entries: HwyBaseInfoIqLocaleEntry[] = [];
  for (const [shortName, iqTitle] of Object.entries(HWY_MEMBERSHIP_STATUS_IQ_TITLE_OVERRIDES)) {
    const title = String(iqTitle).trim();
    if (!title) {
      continue;
    }
    const baseInfoId = await findHwyBaseInfoItemId(HWY_MEMBERSHIP_STATUS_CATEGORY, shortName);
    entries.push({
      baseInfoId,
      locales: { iq: { title } },
    });
  }
  return entries;
}

export async function persistHwyMembershipStatusIqOverrides(): Promise<number> {
  const entries = await buildHwyMembershipStatusIqOverrideEntries();
  if (entries.length === 0) {
    return 0;
  }
  persistBaseInfoLocaleTextsBulk(entries);
  return entries.length;
}

