export function resolveHwyRegistrationChannelIqTitle(
  shortName: string,
  legacyArabicTitle: string,
): string {
  const fromLegacy = String(legacyArabicTitle ?? '').trim();
  if (fromLegacy) {
    return fromLegacy;
  }
  return String(HWY_REGISTRATION_CHANNEL_IQ_TITLE_OVERRIDES[shortName] ?? '').trim();
}

