import {
  findHwyBusinessRulesReferenceSection,
  HWY_BUSINESS_RULES_REFERENCE_SECTIONS,
  type HwyBusinessRulesReferenceSectionId,
} from '../../../domain/hwy/hwyBusinessRulesReferenceCatalog';
import { ensureHwyBusinessRuleDocTable, getHwyBusinessRuleDocModel } from './hwyBusinessRuleDocsSequelizeModel';

export type HwyBusinessRuleDocDto = {
  slug: string;
  navGroupId: string;
  title: string;
  introMarkdown: string | null;
  bodyMarkdown: string;
  sortOrder: number;
  updatedAt: string | null;
  updatedByUsername: string | null;
};

const toDto = (row: {
  slug: string;
  navGroupId: string;
  title: string;
  introMarkdown: string | null;
  bodyMarkdown: string;
  sortOrder: number;
  updatedAt: Date | null;
  updatedByUsername: string | null;
}): HwyBusinessRuleDocDto => ({
  slug: row.slug,
  navGroupId: row.navGroupId,
  title: row.title,
  introMarkdown: row.introMarkdown,
  bodyMarkdown: row.bodyMarkdown,
  sortOrder: row.sortOrder,
  updatedAt: row.updatedAt ? row.updatedAt.toISOString() : null,
  updatedByUsername: row.updatedByUsername,
});

export const ensureHwyBusinessRuleDocsReady = async (): Promise<void> => {
  await ensureHwyBusinessRuleDocTable();
};

export async function listHwyBusinessRuleDocs(): Promise<HwyBusinessRuleDocDto[]> {
  await ensureHwyBusinessRuleDocsReady();
  const model = getHwyBusinessRuleDocModel();
  const rows = await model.findAll({
    order: [['navGroupId', 'ASC'], ['sortOrder', 'ASC'], ['slug', 'ASC']],
  });
  return rows.map((row) => toDto(row.get({ plain: true })));
}

export async function readHwyBusinessRuleDoc(
  slug: string,
): Promise<HwyBusinessRuleDocDto | null> {
  await ensureHwyBusinessRuleDocsReady();
  const model = getHwyBusinessRuleDocModel();
  const row = await model.findByPk(slug.trim());
  if (!row) {
    return null;
  }
  return toDto(row.get({ plain: true }));
}

export async function upsertHwyBusinessRuleDoc(input: {
  slug: string;
  navGroupId: string;
  title: string;
  introMarkdown?: string | null;
  bodyMarkdown: string;
  sortOrder: number;
  updatedByUsername: string | null;
}): Promise<HwyBusinessRuleDocDto> {
  await ensureHwyBusinessRuleDocsReady();
  const model = getHwyBusinessRuleDocModel();
  const now = new Date();
  const payload = {
    slug: input.slug.trim(),
    navGroupId: input.navGroupId.trim(),
    title: input.title.trim(),
    introMarkdown: input.introMarkdown?.trim() || null,
    bodyMarkdown: input.bodyMarkdown,
    sortOrder: input.sortOrder,
    updatedAt: now,
    updatedByUsername: input.updatedByUsername,
  };
  const existing = await model.findByPk(payload.slug);
  if (existing) {
    await existing.update(payload);
    return toDto(existing.get({ plain: true }));
  }
  const created = await model.create(payload);
  return toDto(created.get({ plain: true }));
}

export async function updateHwyBusinessRuleDocMarkdown(input: {
  slug: string;
  title?: string;
  introMarkdown?: string | null;
  bodyMarkdown: string;
  updatedByUsername: string | null;
}): Promise<HwyBusinessRuleDocDto | null> {
  await ensureHwyBusinessRuleDocsReady();
  const model = getHwyBusinessRuleDocModel();
  const existing = await model.findByPk(input.slug.trim());
  if (!existing) {
    return null;
  }
  const plain = existing.get({ plain: true });
  const nextTitle = input.title?.trim() || plain.title;
  const nextIntro = input.introMarkdown !== undefined
    ? (input.introMarkdown?.trim() || null)
    : plain.introMarkdown;
  await existing.update({
    title: nextTitle,
    introMarkdown: nextIntro,
    bodyMarkdown: input.bodyMarkdown,
    updatedAt: new Date(),
    updatedByUsername: input.updatedByUsername,
  });
  return toDto(existing.get({ plain: true }));
}

export function isKnownHwyBusinessRuleDocSlug(slug: string): slug is HwyBusinessRulesReferenceSectionId {
  return Boolean(findHwyBusinessRulesReferenceSection(slug as HwyBusinessRulesReferenceSectionId));
}

let ensureCatalogRowsInflight: Promise<number> | null = null;

const isUniqueConstraintError = (error: unknown): boolean => {
  if (!error || typeof error !== 'object') {
    return false;
  }
  const name = 'name' in error ? String(error.name) : '';
  if (name === 'SequelizeUniqueConstraintError') {
    return true;
  }
  const parent = 'parent' in error ? error.parent : null;
  if (parent && typeof parent === 'object' && 'number' in parent) {
    return parent.number === 2627 || parent.number === 2601;
  }
  return false;
};

/** Idempotent catalog alignment — does not overwrite existing markdown bodies. */
async function ensureHwyBusinessRuleDocCatalogRowsInner(): Promise<number> {
  await ensureHwyBusinessRuleDocsReady();
  const model = getHwyBusinessRuleDocModel();
  let created = 0;
  for (const section of HWY_BUSINESS_RULES_REFERENCE_SECTIONS) {
    const existing = await model.findByPk(section.id);
    if (existing) {
      continue;
    }
    try {
      await model.create({
        slug: section.id,
        navGroupId: section.groupId,
        title: section.id,
        introMarkdown: null,
        bodyMarkdown: '_Content pending — run `npm run hwy:business-rules:seed` or edit in Studio._',
        sortOrder: HWY_BUSINESS_RULES_REFERENCE_SECTIONS.indexOf(section),
        updatedAt: new Date(),
        updatedByUsername: 'system',
      });
      created += 1;
    } catch (error) {
      if (!isUniqueConstraintError(error)) {
        throw error;
      }
    }
  }
  return created;
}

export async function ensureHwyBusinessRuleDocCatalogRows(): Promise<number> {
  if (!ensureCatalogRowsInflight) {
    ensureCatalogRowsInflight = ensureHwyBusinessRuleDocCatalogRowsInner().finally(() => {
      ensureCatalogRowsInflight = null;
    });
  }
  return ensureCatalogRowsInflight;
}
