import type { HwyMemberDossierGeoKind, HwyMemberDossierSelectOption } from '../../../domain/hwy/hwyMemberDossierSelectOptions';
import { isHwyMehaniProfessionalBaseInfoPlaceholderShortName } from '../../../domain/hwy/hwyMehaniProfessionalBaseInfoPlaceholders';
import { HWY_BASE_INFO_ROOT_ID } from './hwyBaseInfoRuntime';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

const GEO_KIND_SHORT_PREFIX: Record<HwyMemberDossierGeoKind, string> = {
  maktab: 'hwy-maktab-',
  region: 'hwy-region-',
  circle: 'hwy-circle-',
};

const normalizeCultureId = (cultureId: string | null | undefined): string => {
  const trimmed = String(cultureId ?? '').trim();
  return trimmed || 'iq';
};

const rowsToOptions = async (
  rows: BaseInfoDbRow[],
  cultureId: string,
): Promise<HwyMemberDossierSelectOption[]> => {
  if (rows.length === 0) {
    return [];
  }
  const mapped = await mapBaseInfoRowsForCulture(rows, cultureId, (row, context) => ({
    viewOrder: toViewOrderNumber(row.viewOrder),
    label: context.label,
    id: row.id,
  }));
  return mapped
    .map((row) => ({
      value: String(row.id ?? '').trim(),
      label: String(row.label ?? '').trim() || String(row.id ?? '').trim(),
    }))
    .filter((row) => row.value && row.label)
    .sort((a, b) => a.label.localeCompare(b.label, 'ar'));
};

const listPlatformCategoryRows = async (categoryTitle: string): Promise<BaseInfoDbRow[]> => {
  const category = await prisma().baseInfo.findFirst({
    where: {
      parentId: HWY_BASE_INFO_ROOT_ID,
      title: categoryTitle.trim(),
    },
    select: { id: true },
  });
  if (!category) {
    return [];
  }
  return prisma().baseInfo.findMany({
    where: {
      parentId: category.id,
      isActive: true,
    },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: BASE_INFO_ROW_SELECT,
  });
};

export async function listHwyMemberDossierCategorySelectOptions(
  cultureId: string | null | undefined,
  categoryTitle: string,
): Promise<HwyMemberDossierSelectOption[]> {
  const resolvedCultureId = normalizeCultureId(cultureId);
  const rows = (await listPlatformCategoryRows(categoryTitle)).filter(
    (row) => !isHwyMehaniProfessionalBaseInfoPlaceholderShortName(row.shortName),
  );
  return rowsToOptions(rows, resolvedCultureId);
}

export async function listHwyMemberDossierGenderSelectOptions(
  cultureId: string | null | undefined,
): Promise<HwyMemberDossierSelectOption[]> {
  const resolvedCultureId = resolveBaseInfoCultureId(normalizeCultureId(cultureId));
  const rows = await prisma().baseInfo.findMany({
    where: {
      parentId: '100.1',
      isActive: true,
    },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: BASE_INFO_ROW_SELECT,
  });
  return rowsToOptions(rows, resolvedCultureId);
}

export async function listHwyMemberDossierGeoKindSelectOptions(
  cultureId: string | null | undefined,
  kind: HwyMemberDossierGeoKind,
): Promise<HwyMemberDossierSelectOption[]> {
  const resolvedCultureId = normalizeCultureId(cultureId);
  const prefix = GEO_KIND_SHORT_PREFIX[kind];
  const rows = await prisma().baseInfo.findMany({
    where: {
      isActive: true,
      OR: [
        { shortName: { startsWith: prefix } },
        { metadata: { contains: `"hwyGeoKind":"${kind}"` } },
      ],
    },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    take: 500,
    select: BASE_INFO_ROW_SELECT,
  });
  return rowsToOptions(rows, resolvedCultureId);
}
