import { HWY_MEMBER_PHONE_REJECT_REASON_LEGACY_PARENT_ID } from '../../../domain/hwy/hwyMemberPhoneRejectReasons';
import { resolveHwyMemberDirectoryDetailLang } from '../../../domain/hwy/hwyMemberDirectoryDetail';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

export async function listHwyMemberPhoneRejectReasonOptions(
  cultureOrLang?: string | null,
): Promise<Array<{ value: string; label: string }>> {
  const queryLang = resolveHwyMemberDirectoryDetailLang(cultureOrLang);
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const parentId = String(HWY_MEMBER_PHONE_REJECT_REASON_LEGACY_PARENT_ID);

  const rows = await prisma().baseInfo.findMany({
    where: { parentId, isActive: true },
    select: BASE_INFO_ROW_SELECT,
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
  });

  if (rows.length === 0) {
    return [];
  }

  const mapped = await mapBaseInfoRowsForCulture(rows as BaseInfoDbRow[], cultureId, (row, context) => ({
    viewOrder: toViewOrderNumber(row.viewOrder),
    label: context.label,
    id: row.id,
  }));

  return mapped
    .map((row) => {
      const value = String(row.id ?? '').trim();
      const label = String(row.label ?? '').trim() || value;
      return { value, label };
    })
    .filter((row) => row.value && row.label)
    .sort((left, right) => left.label.localeCompare(right.label, 'ar'));
}

export async function assertHwyMemberPhoneRejectReasonCode(finalReasonCode: string): Promise<void> {
  const code = finalReasonCode.trim();
  if (!code) {
    throw new Error('Reject reason is required.');
  }
  const row = await prisma().baseInfo.findFirst({
    where: {
      id: code,
      parentId: String(HWY_MEMBER_PHONE_REJECT_REASON_LEGACY_PARENT_ID),
      isActive: true,
    },
    select: { id: true },
  });
  if (!row) {
    throw new Error('Reject reason is invalid.');
  }
}
