/**
 * Legacy→edge parity SQL batches that must ship in the Hawiety package zip
 * in this relative order (matches ensureHwyDbObjects parity segment).
 */
export const HWY_LEGACY_EDGE_PARITY_PACK_SQL_ORDER = [
  'hwy_member_stat_columns.sqlserver.sql',
  'hwy_member_pipeline_snake_columns.sqlserver.sql',
  'hwy_member_stats_recalc_support.sqlserver.sql',
  'hwy_member_passed_necessary_dorat.sqlserver.sql',
  'hwy_legacy_edge_parity_table_rename.sqlserver.sql',
  'hwy_legacy_edge_parity_column_rename.sqlserver.sql',
  'hwy_member_stats_recalc.sqlserver.sql',
  'hwy_legacy_edge_pipeline_compat.sqlserver.sql',
  'hwy_legacy_edge_area_limit_agg_functions.sqlserver.sql',
  'hwy_legacy_pipeline_views.sqlserver.sql',
  'hwy_legacy_edge_function_retire.sqlserver.sql',
] as const;

export type HwyLegacyEdgeParityPackSqlFile = (typeof HWY_LEGACY_EDGE_PARITY_PACK_SQL_ORDER)[number];

/** Ensures every parity SQL file is present and ordered for package / zip install. */
export function findLegacyEdgeParityPackSqlOrderIssues(installFileNames: readonly string[]): string[] {
  const issues: string[] = [];
  let lastIndex = -1;
  for (const fileName of HWY_LEGACY_EDGE_PARITY_PACK_SQL_ORDER) {
    const index = installFileNames.indexOf(fileName);
    if (index < 0) {
      issues.push(`MISSING_PARITY_SQL: ${fileName}`);
      continue;
    }
    if (index <= lastIndex) {
      issues.push(`PARITY_SQL_ORDER: ${fileName} must install after ${HWY_LEGACY_EDGE_PARITY_PACK_SQL_ORDER[lastIndex]}`);
    }
    lastIndex = index;
  }
  return issues;
}
