import type sql from 'mssql';

/** Stay under SQL Server 2100 parameter cap. */
export const SQL_SERVER_PARAM_BUDGET = 2000;

export function chunkByParamBudget<T>(
  items: T[],
  paramsPerItem: number,
  budget = SQL_SERVER_PARAM_BUDGET,
): T[][] {
  const size = Math.max(1, Math.floor(budget / Math.max(1, paramsPerItem)));
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    out.push(items.slice(i, i + size));
  }
  return out;
}

export type BoundParam = {
  name: string;
  type: sql.ISqlTypeFactoryWithLength | sql.ISqlTypeFactoryWithNoParams | sql.ISqlTypeFactoryWithPrecision;
  value: unknown;
};

/** Bind params for one row; returns `( @p0, @p1, … )` placeholder list. */
export function bindValuesRow(
  req: sql.Request,
  rowIndex: number,
  params: BoundParam[],
): string {
  const parts: string[] = [];
  params.forEach((p, colIndex) => {
    const key = `r${rowIndex}c${colIndex}`;
    req.input(key, p.type, p.value);
    parts.push(`@${key}`);
  });
  return `(${parts.join(', ')})`;
}
