import type { HwyMemberDirectoryPatchInput } from './hwyMemberDirectoryPatch';
import { legacyHwyRoleIdToPlatformRoleName } from './hwyMemberListLegacyAccess';

/** Legacy `HashPhones` / `HashNamesAndPhones` sentinel (HWY_Members.cs). */
export const HWY_MEMBER_IDENTITY_MASK_SENTINEL = '*****';

/** Legacy `ApprovedRestrictedOrgsCount` institute ids (HWY_Members.json). */
export const HWY_MEMBER_IDENTITY_RESTRICTED_INSTITUTE_IDS = [4, 214917, 215103] as const;

/** Call center + Hawiety technical roles bypass `HashPhonesForOthers` (legacy role ids). */
export const HWY_MEMBER_IDENTITY_ORG_PHONE_BYPASS_LEGACY_ROLE_IDS = [1000006, 1000040] as const;

const LEGACY_MALE_GENDER_ID = '10011';
const LEGACY_FEMALE_GENDER_ID = '10012';

export type HwyMemberIdentityMaskViewer = {
  isAdmin: boolean;
  roleNames: readonly string[];
  /** Legacy GenderId values (10011 / 10012). Empty = no gender restriction. */
  genderLimitLegacyIds: readonly string[];
};

export type HwyMemberIdentityInstitutePhoneContext = {
  approvedRestrictedOrgsCount: number;
  /** Legacy `OrgsMembership` aggregate when member has restricted approved org links. */
  orgsMembershipSummary: string;
};

export type HwyMemberDirectoryIdentityFieldPolicy = {
  genderMasked: boolean;
  institutePhoneMasked: boolean;
  lockedPatchFields: Array<keyof HwyMemberDirectoryPatchInput>;
  personalPhotoReadOnly: boolean;
};

export const isHwyMemberIdentityMaskSentinel = (value: unknown): boolean => (
  typeof value === 'string' && value.trim() === HWY_MEMBER_IDENTITY_MASK_SENTINEL
);

export const normalizeMemberGenderToLegacyId = (raw: unknown): string | null => {
  if (raw === null || raw === undefined) {
    return null;
  }
  const text = String(raw).trim();
  if (!text) {
    return null;
  }
  if (text === LEGACY_MALE_GENDER_ID || text.includes('100.1.1') || text.toLowerCase().includes('male')) {
    return LEGACY_MALE_GENDER_ID;
  }
  if (text === LEGACY_FEMALE_GENDER_ID || text.includes('100.1.2') || text.toLowerCase().includes('female')) {
    return LEGACY_FEMALE_GENDER_ID;
  }
  if (/^\d+$/.test(text)) {
    return text;
  }
  return text;
};

const readRowString = (row: Record<string, unknown>, ...keys: string[]): string => {
  for (const key of keys) {
    const raw = row[key];
    if (raw !== null && raw !== undefined && String(raw).trim()) {
      return String(raw).trim();
    }
  }
  return '';
};

const writeRowString = (row: Record<string, unknown>, keys: readonly string[], value: string): void => {
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(row, key)) {
      row[key] = value;
    }
  }
  const primary = keys[0];
  if (primary && !Object.prototype.hasOwnProperty.call(row, primary)) {
    row[primary] = value;
  }
};

const clearProfileImageFields = (row: Record<string, unknown>): void => {
  const nullableKeys = [
    'avatarUrl',
    'avatar_url',
    'profile_image_base64',
    'profile_image_xs_base64',
    'Picture_FileBody',
    'Picture_FileBody_xs',
  ] as const;
  const booleanKeys = [
    'hasProfileImage',
    'has_profile_image',
    'has_profile_image_xs',
    'hasProfileImageXs',
  ] as const;
  for (const key of nullableKeys) {
    if (Object.prototype.hasOwnProperty.call(row, key)) {
      row[key] = null;
    }
  }
  for (const key of booleanKeys) {
    row[key] = false;
  }
};

export const legacyHwyRoleBypassesOrgPhoneMask = (roleNames: readonly string[]): boolean => {
  const normalized = new Set(roleNames.map((role) => role.trim()).filter(Boolean));
  for (const legacyRoleId of HWY_MEMBER_IDENTITY_ORG_PHONE_BYPASS_LEGACY_ROLE_IDS) {
    if (normalized.has(String(legacyRoleId))) {
      return true;
    }
    if (normalized.has(legacyHwyRoleIdToPlatformRoleName(legacyRoleId))) {
      return true;
    }
  }
  return false;
};

/** True when legacy would run single-gender `HashPhones` (JWT GenderLimits count &lt; 2). */
export const shouldApplyGenderIdentityMask = (viewer: HwyMemberIdentityMaskViewer): boolean => (
  !viewer.isAdmin && viewer.genderLimitLegacyIds.length > 0 && viewer.genderLimitLegacyIds.length < 2
);

export const memberGenderAllowedForViewer = (
  viewer: HwyMemberIdentityMaskViewer,
  memberGenderCode: unknown,
): boolean => {
  if (viewer.isAdmin || viewer.genderLimitLegacyIds.length >= 2) {
    return true;
  }
  if (viewer.genderLimitLegacyIds.length === 0) {
    return true;
  }
  const allowedLegacy = normalizeMemberGenderToLegacyId(viewer.genderLimitLegacyIds[0]);
  if (!allowedLegacy) {
    return true;
  }
  const memberLegacy = normalizeMemberGenderToLegacyId(memberGenderCode);
  if (!memberLegacy) {
    return false;
  }
  return memberLegacy === allowedLegacy;
};

export const applyGenderIdentityMaskToMemberRow = (
  row: Record<string, unknown>,
  viewer: HwyMemberIdentityMaskViewer,
): boolean => {
  if (!shouldApplyGenderIdentityMask(viewer)) {
    return false;
  }
  const genderRaw = readRowString(row, 'genderCode', 'gender_code', 'GenderId', 'genderId');
  if (memberGenderAllowedForViewer(viewer, genderRaw)) {
    return false;
  }
  writeRowString(row, ['firstname', 'firstName', 'first_name', 'FirstName'], HWY_MEMBER_IDENTITY_MASK_SENTINEL);
  writeRowString(row, ['displayFullName', 'display_full_name'], HWY_MEMBER_IDENTITY_MASK_SENTINEL);
  for (const phoneKey of ['phone1', 'phone2', 'Phone1', 'Phone2']) {
    const current = readRowString(row, phoneKey);
    if (current) {
      writeRowString(row, [phoneKey], HWY_MEMBER_IDENTITY_MASK_SENTINEL);
    }
  }
  clearProfileImageFields(row);
  return true;
};

export const applyInstituteOwnershipPhoneMaskToMemberRow = (
  row: Record<string, unknown>,
  viewer: HwyMemberIdentityMaskViewer,
  institute: HwyMemberIdentityInstitutePhoneContext,
): boolean => {
  if (viewer.isAdmin || legacyHwyRoleBypassesOrgPhoneMask(viewer.roleNames)) {
    return false;
  }
  if (institute.approvedRestrictedOrgsCount <= 0) {
    return false;
  }
  const summary = institute.orgsMembershipSummary.trim();
  writeRowString(row, ['phone1', 'Phone1'], summary);
  writeRowString(row, ['phone2', 'Phone2'], '');
  return true;
};

export const resolveHwyMemberDirectoryIdentityFieldPolicy = (input: {
  viewer: HwyMemberIdentityMaskViewer;
  memberGenderCode: unknown;
  genderMasked: boolean;
  institutePhoneMasked: boolean;
}): HwyMemberDirectoryIdentityFieldPolicy => {
  const locked = new Set<keyof HwyMemberDirectoryPatchInput>();
  if (input.genderMasked) {
    locked.add('firstname');
    locked.add('phone1');
    locked.add('phone2');
    locked.add('genderCode');
  }
  if (input.institutePhoneMasked) {
    locked.add('phone1');
    locked.add('phone2');
  }
  return {
    genderMasked: input.genderMasked,
    institutePhoneMasked: input.institutePhoneMasked,
    lockedPatchFields: [...locked],
    personalPhotoReadOnly: input.genderMasked,
  };
};

export const stripIdentityLockedPatchFields = (
  patch: HwyMemberDirectoryPatchInput,
  lockedFields: ReadonlyArray<keyof HwyMemberDirectoryPatchInput>,
): HwyMemberDirectoryPatchInput => {
  if (lockedFields.length === 0) {
    return patch;
  }
  const locked = new Set(lockedFields);
  const next: HwyMemberDirectoryPatchInput = { ...patch };
  for (const field of locked) {
    delete next[field];
  }
  return next;
};

export const isHwyMemberDossierPatchFieldLocked = (
  field: keyof HwyMemberDirectoryPatchInput,
  policy: HwyMemberDirectoryIdentityFieldPolicy | null | undefined,
): boolean => Boolean(policy?.lockedPatchFields.includes(field));
