import {
  findHwyMemberSegmentListByLegacyCode,
  type HwyMemberSegmentListExtraColumnKey,
} from '../../../domain/hwy/hwyMemberSegmentListCatalog';
import { HWY_MEMBER_QUICK_SEARCH_LEGACY_LIST_SCOPE } from '../../../domain/hwy/hwyMemberQuickSearchCatalog';
import { isHwyMemberRejectionListLegacyScope } from '../../../domain/hwy/hwyMemberRejectionListParity';
import type { EdgeApiFieldEnrichment } from '../../../shared/api/contracts/data-api';

/** Scoped segment list columns — not always present on the published list operation. */
export const HWY_MEMBER_DIRECTORY_SEGMENT_LIST_FIELD_ENRICHMENTS: EdgeApiFieldEnrichment[] = [
  {
    id: 'hwy_enrich_education_level',
    kind: 'base_info_title',
    sourceField: 'educationLevelCode',
    joinTableSource: 'base_info',
    attachedFields: [{ sourceColumn: 'title', outputField: 'educationLevelCodeTitle' }],
    langSource: 'fixed:ar',
  },
  {
    id: 'hwy_enrich_job_type',
    kind: 'base_info_title',
    sourceField: 'jobTypeCode',
    joinTableSource: 'base_info',
    attachedFields: [{ sourceColumn: 'title', outputField: 'jobTypeCodeTitle' }],
    langSource: 'fixed:ar',
  },
  {
    id: 'hwy_enrich_registration_channel',
    kind: 'base_info_title',
    sourceField: 'registrationChannelCode',
    joinTableSource: 'base_info',
    attachedFields: [{ sourceColumn: 'title', outputField: 'registrationChannelCodeTitle' }],
    langSource: 'fixed:ar',
  },
  {
    id: 'hwy_enrich_mehani_union',
    kind: 'base_info_title',
    sourceField: 'mehaniUnionCode',
    joinTableSource: 'base_info',
    attachedFields: [{ sourceColumn: 'title', outputField: 'mehaniUnionCodeTitle' }],
    langSource: 'fixed:ar',
  },
  {
    id: 'hwy_enrich_mehani_union_degree',
    kind: 'base_info_title',
    sourceField: 'mehaniUnionDegreeCode',
    joinTableSource: 'base_info',
    attachedFields: [{ sourceColumn: 'title', outputField: 'mehaniUnionDegreeCodeTitle' }],
    langSource: 'fixed:ar',
  },
];

const EXTRA_COLUMN_ENRICHMENT_ID: Record<HwyMemberSegmentListExtraColumnKey, string | undefined> = {
  jobTypeAndPlace: 'hwy_enrich_job_type',
  jobTypeCodeTitle: 'hwy_enrich_job_type',
  educationLevelAndDetails: 'hwy_enrich_education_level',
  educationLevelCodeTitle: 'hwy_enrich_education_level',
  registrationChannelCodeTitle: 'hwy_enrich_registration_channel',
  educationBranch: undefined,
  jobPlace: undefined,
  educationEndYear: undefined,
  trackingCode: undefined,
  createdAt: undefined,
  membershipStatusUpdatedOn: undefined,
  characterCodeTitle: undefined,
  mehaniUnionCodeTitle: 'hwy_enrich_mehani_union',
  mehaniUnionDegreeCodeTitle: 'hwy_enrich_mehani_union_degree',
};

/** `hwy-members-all` — no `listScope`; grid shows status, tasjil, registration channel. */
const UNSCOPED_LIST_ENRICHMENT_IDS = new Set([
  'hwy_enrich_membership_status',
  'hwy_enrich_tasjil_state',
  'hwy_enrich_registration_channel',
]);

/** Tasjil / «مسجل» icon column — always enriched on scoped member segment lists. */
const SCOPED_LIST_BASE_ENRICHMENT_IDS = new Set(['hwy_enrich_tasjil_state']);

/** Base_info enrichments for member-directory list handler (scoped grids use catalog extras). */
export const resolveMemberDirectoryListEnrichmentIds = (
  listScopeLegacy?: string | null,
): Set<string> => {
  const trimmed = listScopeLegacy?.trim() ?? '';
  if (trimmed === HWY_MEMBER_QUICK_SEARCH_LEGACY_LIST_SCOPE) {
    return new Set([
      'hwy_enrich_tasjil_state',
      'hwy_enrich_membership_status',
      'hwy_enrich_registration_channel',
    ]);
  }
  if (!trimmed) {
    return new Set(UNSCOPED_LIST_ENRICHMENT_IDS);
  }
  const ids = new Set<string>(SCOPED_LIST_BASE_ENRICHMENT_IDS);
  if (isHwyMemberRejectionListLegacyScope(trimmed)) {
    ids.add('hwy_enrich_membership_status');
  }
  const definition = findHwyMemberSegmentListByLegacyCode(trimmed);
  if (!definition) {
    return ids;
  }
  for (const columnKey of definition.extraColumns) {
    const enrichmentId = EXTRA_COLUMN_ENRICHMENT_ID[columnKey];
    if (enrichmentId) {
      ids.add(enrichmentId);
    }
  }
  return ids;
};

export const resolveMemberDirectoryListFieldEnrichments = (
  listScopeLegacy: string | undefined | null,
  allEnrichments: readonly EdgeApiFieldEnrichment[] | undefined,
): EdgeApiFieldEnrichment[] => {
  const ids = resolveMemberDirectoryListEnrichmentIds(listScopeLegacy);
  if (ids.size === 0) {
    return [];
  }
  const merged = new Map<string, EdgeApiFieldEnrichment>();
  for (const item of allEnrichments ?? []) {
    if (ids.has(item.id)) {
      merged.set(item.id, item);
    }
  }
  for (const item of HWY_MEMBER_DIRECTORY_SEGMENT_LIST_FIELD_ENRICHMENTS) {
    if (ids.has(item.id) && !merged.has(item.id)) {
      merged.set(item.id, item);
    }
  }
  return [...merged.values()];
};
