import type { DesignerGridRichCellFields } from '../component-designer/designerGridRichCellColumns';
import {
  isHwyMemberDirectoryListFaceCaptionTrackingOnlyScope,
  type HwyMemberDirectoryListFaceCaptionMode,
} from './hwyMemberDirectoryListFaceCaptionMode';
import {
  resolveHwyAllocatedMembershipUsername,
  resolveHwyMemberRowAllocatedUsername,
} from './hwyMembershipUsername';

/**
 * Grid + dossier profile-rail caption rules — locked with:
 * - Shard `docs/standards/package-hawiety-member-face-caption.md`
 * - Barrel `hwyMemberDirectoryFaceCaptionContract.ts` · `npm run test:hwy-member-face-caption`
 * - `hwyMemberFaceCaptionListContract.test.ts` · `hwyMemberDirectoryFaceCaptionLock.test.ts`
 *
 * Dossier rail must call `resolveHwyMemberDossierProfileRailFaceCaption` / `resolveHwyMemberFaceCaption(row)` —
 * not `resolveHwyMemberFaceCaptionFromIdentity` (omits `userUsername` from detail enrich).
 */

export const HWY_MEMBER_FACE_CAPTION_USERNAME_FIELD = 'username';
export const HWY_MEMBER_FACE_CAPTION_TRACKING_FIELD = 'trackingCode';

export type HwyMemberFaceCaptionKind = 'username' | 'tracking' | 'none';

export type HwyMemberFaceCaption = {
  text: string;
  kind: HwyMemberFaceCaptionKind;
};

const readRowString = (row: Record<string, unknown>, fieldKey?: string): string => {
  const key = fieldKey?.trim();
  if (!key) {
    return '';
  }
  const raw = row[key];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

export type HwyMemberFaceCaptionIdentityInput = {
  username?: string | null;
  trackingCode?: string | null;
  /** Member pk / tracking id when username is not allocated yet. */
  memberId?: string | null;
};

const trimIdentityField = (value: string | null | undefined): string => String(value ?? '').trim();

/** Membership number under avatar: username when allocated, otherwise tracking code / member id. */
export const resolveHwyMemberFaceCaptionFromIdentity = (
  input: HwyMemberFaceCaptionIdentityInput,
): HwyMemberFaceCaption => {
  const memberId = trimIdentityField(input.memberId);
  const username = resolveHwyAllocatedMembershipUsername(input.username, memberId || null);
  if (username) {
    return { text: username, kind: 'username' };
  }
  const trackingCode = trimIdentityField(input.trackingCode) || memberId;
  if (trackingCode) {
    return { text: trackingCode, kind: 'tracking' };
  }
  return { text: '', kind: 'none' };
};

export type HwyMemberFaceCaptionResolveOptions = {
  /** Applicant / Waited / Marfoozeh lists — never show allocated username (blue). */
  trackingOnly?: boolean;
};

const resolveTrackingOnlyFaceCaption = (
  row: Record<string, unknown>,
  fields?: Pick<DesignerGridRichCellFields, 'captionFallbackField'>,
): HwyMemberFaceCaption => {
  const memberId = readRowString(row, 'id');
  const trackingCode = readRowString(
    row,
    fields?.captionFallbackField?.trim() || HWY_MEMBER_FACE_CAPTION_TRACKING_FIELD,
  ) || memberId;
  if (trackingCode) {
    return { text: trackingCode, kind: 'tracking' };
  }
  return { text: '', kind: 'none' };
};

/** Membership number under avatar: username when allocated, otherwise tracking code. */
export const resolveHwyMemberFaceCaption = (
  row: Record<string, unknown>,
  fields?: Pick<DesignerGridRichCellFields, 'captionField' | 'captionFallbackField'>,
  options?: HwyMemberFaceCaptionResolveOptions,
): HwyMemberFaceCaption => {
  if (options?.trackingOnly) {
    return resolveTrackingOnlyFaceCaption(row, fields);
  }
  const memberId = readRowString(row, 'id');
  const captionField = fields?.captionField?.trim() || HWY_MEMBER_FACE_CAPTION_USERNAME_FIELD;
  const usernameFromCaption = resolveHwyAllocatedMembershipUsername(
    readRowString(row, captionField),
    memberId || null,
  );
  const username = usernameFromCaption
    ?? resolveHwyMemberRowAllocatedUsername(row, memberId || null);
  if (username) {
    return { text: username, kind: 'username' };
  }
  const trackingCode = readRowString(
    row,
    fields?.captionFallbackField?.trim() || HWY_MEMBER_FACE_CAPTION_TRACKING_FIELD,
  ) || memberId;
  if (trackingCode) {
    return { text: trackingCode, kind: 'tracking' };
  }
  return { text: '', kind: 'none' };
};

/** List grid entry — applies scope mode (Waited / Marfoozeh → tracking only). */
export const resolveHwyMemberDirectoryListFaceCaptionForScope = (
  row: Record<string, unknown>,
  listScopeLegacy: string | null | undefined,
  fields?: Pick<DesignerGridRichCellFields, 'captionField' | 'captionFallbackField'>,
): HwyMemberFaceCaption => resolveHwyMemberFaceCaption(row, fields, {
  trackingOnly: isHwyMemberDirectoryListFaceCaptionTrackingOnlyScope(listScopeLegacy),
});

/** Alias — pass `listScopeLegacy` via `resolveHwyMemberDirectoryListFaceCaptionForScope` on directory lists. */
export const resolveHwyMemberDirectoryListFaceCaption = resolveHwyMemberFaceCaption;

export type { HwyMemberDirectoryListFaceCaptionMode };

/** Face cells that only have scalar props (geo / targhin / referrer) — same rules as list rows. */
export const resolveHwyMemberFaceCaptionFromMemberFields = (input: {
  id?: string | null;
  username?: string | null;
  userUsername?: string | null;
  trackingCode?: string | null;
}): HwyMemberFaceCaption => resolveHwyMemberFaceCaption({
  id: input.id ?? '',
  username: input.username ?? '',
  userUsername: input.userUsername ?? input.username ?? '',
  trackingCode: input.trackingCode ?? '',
});

export const HWY_MEMBER_FACE_CAPTION_USERNAME_CLASS = 'text-sky-600';
export const HWY_MEMBER_FACE_CAPTION_TRACKING_CLASS = 'text-rose-600';

export const hwyMemberFaceCaptionTextClass = (kind: HwyMemberFaceCaptionKind): string => (
  kind === 'tracking'
    ? HWY_MEMBER_FACE_CAPTION_TRACKING_CLASS
    : kind === 'username'
      ? HWY_MEMBER_FACE_CAPTION_USERNAME_CLASS
      : 'text-slate-700'
);
