import { resolveHwyMemberListScopedEditProfile } from './hwyMemberListScopedEditCatalog';

/** Legacy listScope query param on member-directory grids (`static:HWY_Members_List_*`). */
export const HWY_MEMBER_LIST_SCOPED_EDIT_GOV_LEGACY = 'HWY_Members_List_AlMontadhemin_Gov' as const;

export type HwyMemberListScopedEditChromeEntry = {
  listScopeLegacy: string;
  refreshVar: string;
};

export const parseHwyMemberDirectoryGridListScopeLegacy = (
  queryParams: Record<string, string> | undefined | null,
): string | null => {
  const raw = String(queryParams?.listScope ?? queryParams?.listDefLegacy ?? '').trim();
  if (!raw.startsWith('static:')) {
    return null;
  }
  const legacy = raw.slice('static:'.length).trim();
  return legacy.length > 0 ? legacy : null;
};

/** Member-directory grid fetches that need list-scoped edit chrome on published pages. */
export const collectHwyMemberListScopedEditChromeFromGridFetches = (
  gridListFetches: ReadonlyArray<{
    queryParams?: Record<string, string>;
    dataVar: string;
  }>,
): HwyMemberListScopedEditChromeEntry[] => {
  const entries: HwyMemberListScopedEditChromeEntry[] = [];
  for (const fetch of gridListFetches) {
    const listScopeLegacy = parseHwyMemberDirectoryGridListScopeLegacy(fetch.queryParams);
    if (!listScopeLegacy || !resolveHwyMemberListScopedEditProfile(listScopeLegacy)) {
      continue;
    }
    if (entries.some((entry) => entry.listScopeLegacy === listScopeLegacy)) {
      continue;
    }
    entries.push({
      listScopeLegacy,
      refreshVar: `refresh_${fetch.dataVar}`,
    });
  }
  return entries;
};
