import { readLegacyConn } from '../../../../scripts/hwy-etl/legacyConn';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../..');
const MAX_LOG_LINES = 4000;

type InternalRun = HwyEtlRunRecord & {
  cancelRequested: boolean;
  child: ChildProcessWithoutNullStreams | null;
};

type QueuedJob = {
  label: string;
  steps: Array<{ step: HwyEtlStepDefinition; options: HwyEtlRunOptions }>;
};

let activeRun: InternalRun | null = null;
const queue: QueuedJob[] = [];

const nowIso = (): string => new Date().toISOString();

const appendLog = (run: InternalRun, chunk: string): void => {
  const lines = chunk.split(/\r?\n/);
  for (const line of lines) {
    if (!line) continue;
    run.logTail.push(line);
  }
  if (run.logTail.length > MAX_LOG_LINES) {
    run.logTail.splice(0, run.logTail.length - MAX_LOG_LINES);
  }
};

const serializeRun = (run: InternalRun | null): HwyEtlRunRecord | null => {
  if (!run) return null;
  const { cancelRequested: _c, child: _ch, ...rest } = run;
  return rest;
};

const envFromOptions = (
  step: HwyEtlStepDefinition,
  options: HwyEtlRunOptions = {},
): Record<string, string> => {
  const normalized = applyHwyEtlSyncMode(options);
  const env: Record<string, string> = { ...process.env as Record<string, string> };

  for (const opt of step.envOptions ?? []) {
    if (opt.defaultValue !== undefined) {
      env[opt.key] = String(opt.defaultValue);
    }
  }

  const incoming = normalized.env ?? {};
  for (const [key, value] of Object.entries(incoming)) {
    if (value === undefined) continue;
    if (typeof value === 'boolean') {
      env[key] = value ? '1' : '0';
      if (key === 'HWY_ETL_WITH_NOTES' && value) {
        env.HWY_ETL_SKIP_MEMBER_NOTES = '0';
      }
      if (key === 'HWY_ETL_WITH_GEO' && value) {
        env.HWY_ETL_GEO_REPLACE = '1';
      }
      if (key === 'HWY_ETL_SKIP_ENRICHMENT' && value) {
        // run-hwy-etl-all uses argv; forward via CLI below when orchestrator-all
      }
      continue;
    }
    env[key] = String(value);
  }

  if (options.shardCount != null && Number.isFinite(options.shardCount)) {
    env.HWY_ETL_SHARD_COUNT = String(Math.max(1, Math.min(8, options.shardCount)));
  }

  return env;
};

const cliArgsFromOptions = (step: HwyEtlStepDefinition, options: HwyEtlRunOptions = {}): string[] => {
  const args = [...(step.cliArgs ?? []), ...(options.cliArgs ?? [])];
  if (step.id === 'orchestrator-all') {
    const env = options.env ?? {};
    if (env.HWY_ETL_WITH_VOCAB === true || env.HWY_ETL_WITH_VOCAB === '1') args.push('--with-vocab');
    if (env.HWY_ETL_WITH_GEO === true || env.HWY_ETL_WITH_GEO === '1') args.push('--with-geo');
    if (env.HWY_ETL_SKIP_ENRICHMENT === true || env.HWY_ETL_SKIP_ENRICHMENT === '1') {
      args.push('--core-only');
    }
    if (env.HWY_ETL_WITH_TARGHIN === true || env.HWY_ETL_WITH_TARGHIN === '1') args.push('--with-targhin');
    if (env.HWY_ETL_WITH_GEO_RESPONSIBILITY === true || env.HWY_ETL_WITH_GEO_RESPONSIBILITY === '1') {
      args.push('--with-geo-responsibility');
    }
  }
  if (step.id === 'orchestrator-enrichment') {
    const env = options.env ?? {};
    if (env.HWY_ETL_WITH_NOTES === true || env.HWY_ETL_WITH_NOTES === '1') args.push('--with-notes');
    if (env.HWY_ETL_WITH_USERNAMES === true || env.HWY_ETL_WITH_USERNAMES === '1') args.push('--with-usernames');
    if (env.HWY_ETL_WITH_COURSES_ACTIVITIES === true || env.HWY_ETL_WITH_COURSES_ACTIVITIES === '1') {
      args.push('--with-courses-activities');
    }
  }
  if (step.id === 'orchestrator-fast-full' && options.shardCount != null) {
    args.push(`--shards=${Math.max(1, Math.min(8, options.shardCount))}`);
  }
  return args;
};

const spawnStepScript = (
  step: HwyEtlStepDefinition,
  options: HwyEtlRunOptions,
  run: InternalRun,
  stepRecord: HwyEtlRunStepRecord,
): Promise<number> => new Promise((resolve, reject) => {
  const scriptPath = path.join(repoRoot, step.scriptRel);
  if (!fs.existsSync(scriptPath)) {
    reject(new Error(`Script not found: ${step.scriptRel}`));
    return;
  }

  const normalized = applyHwyEtlSyncMode(options);
  const cliArgs = cliArgsFromOptions(step, normalized);
  appendLog(run, `[etl-console] >>> ${step.title}${cliArgs.length ? ` ${cliArgs.join(' ')}` : ''}`);

  stepRecord.status = 'running';
  stepRecord.startedAt = nowIso();

  const child = spawn(process.execPath, ['--import', 'tsx', scriptPath, ...cliArgs], {
    cwd: repoRoot,
    env: envFromOptions(step, normalized),
    stdio: ['ignore', 'pipe', 'pipe'],
    shell: false,
  });

  run.child = child;

  child.stdout.on('data', (buf: Buffer) => appendLog(run, buf.toString('utf8')));
  child.stderr.on('data', (buf: Buffer) => appendLog(run, buf.toString('utf8')));
  child.on('error', (err) => {
    run.child = null;
    reject(err);
  });
  child.on('exit', (code) => {
    run.child = null;
    resolve(code ?? 1);
  });
});

const finishStep = (stepRecord: HwyEtlRunStepRecord, exitCode: number): void => {
  stepRecord.finishedAt = nowIso();
  stepRecord.exitCode = exitCode;
  stepRecord.status = exitCode === 0 ? 'succeeded' : 'failed';
};

const runJob = async (job: QueuedJob): Promise<void> => {
  const run: InternalRun = {
    id: `run-${Date.now()}`,
    label: job.label,
    status: 'running',
    startedAt: nowIso(),
    finishedAt: null,
    steps: job.steps.map(({ step }) => ({
      stepId: step.id,
      title: step.title,
      status: 'queued',
      startedAt: null,
      finishedAt: null,
      exitCode: null,
    })),
    logTail: [],
    cancelRequested: false,
    child: null,
  };

  activeRun = run;

  try {
    for (let i = 0; i < job.steps.length; i += 1) {
      if (run.cancelRequested) {
        run.status = 'cancelled';
        break;
      }

      const { step, options } = job.steps[i];
      const stepRecord = run.steps[i];
      stepRecord.status = 'running';
      stepRecord.startedAt = nowIso();
      appendLog(
        run,
        `\n[etl-console] ========== Step ${i + 1}/${job.steps.length}: ${step.title} ==========`,
      );

      const exitCode = await spawnStepScript(step, options, run, stepRecord);
      finishStep(stepRecord, exitCode);

      if (exitCode !== 0) {
        run.status = 'failed';
        appendLog(run, `[etl-console] Step failed with exit code ${exitCode}.`);
        break;
      }
    }

    if (run.status === 'running') {
      run.status = 'succeeded';
    }
  } catch (error) {
    run.status = 'failed';
    const message = error instanceof Error ? error.message : String(error);
    appendLog(run, `[etl-console] Error: ${message}`);
    const current = run.steps.find((s) => s.status === 'running');
    if (current) {
      current.status = 'failed';
      current.finishedAt = nowIso();
    }
  } finally {
    run.finishedAt = nowIso();
    activeRun = run;
    void drainQueue();
  }
};

const drainQueue = async (): Promise<void> => {
  if (activeRun && (activeRun.status === 'running' || activeRun.status === 'queued')) {
    return;
  }
  const next = queue.shift();
  if (!next) {
    return;
  }
  await runJob(next);
};

const enqueueJob = (job: QueuedJob): HwyEtlRunRecord => {
  if (activeRun?.status === 'running') {
    queue.push(job);
    return serializeRun(activeRun)!;
  }
  void runJob(job);
  return serializeRun(activeRun)!;
};

const mergeRunOptions = (
  base: HwyEtlRunOptions | undefined,
  override: HwyEtlRunOptions | undefined,
): HwyEtlRunOptions => ({
  env: { ...(base?.env ?? {}), ...(override?.env ?? {}) },
  cliArgs: [...(base?.cliArgs ?? []), ...(override?.cliArgs ?? [])],
  shardCount: override?.shardCount ?? base?.shardCount,
  syncMode: override?.syncMode ?? base?.syncMode,
});

export const getHwyEtlConsoleCatalog = () => buildHwyEtlCatalogPayload();

export async function probeHwyEtlLegacyConnection(): Promise<HwyEtlLegacyProbe> {
  const configPath = process.env.HWY_LEGACY_APPSETTINGS ?? 'C:\\Workspace\\Projects\\HawietySite\\HawietySite\\appsettings.json';
  try {
    const conn = readLegacyConn(configPath);
    return {
      ok: true,
      configPath,
      server: conn.server || null,
      database: conn.database || null,
      message: 'Legacy appsettings loaded.',
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Legacy connection unavailable.';
    return {
      ok: false,
      configPath,
      server: null,
      database: null,
      message,
    };
  }
}

const readLocalCountsRow = async (
  includeGeoMap: boolean,
): Promise<HwyEtlLocalCounts | null> => {
  await ensureControlPlaneInitialized(SETTINGS_PATH, { pushSchema: false, seedSampleData: false });
  const s = getControlPlaneSequelize();
  const geoSql = includeGeoMap
    ? '(SELECT COUNT(*) FROM dbo.hwy_etl_geo_map) AS geoMap'
    : '0 AS geoMap';
  const row = (await s.query<{
    members: number;
    linked: number;
    nakhebin: number;
    events: number;
    geoMap: number;
  }>(
    `
    SELECT
      (SELECT COUNT(*) FROM dbo.hwy_members) AS members,
      (SELECT COUNT(*) FROM dbo.hwy_members WHERE user_id IS NOT NULL) AS linked,
      (SELECT COUNT(*) FROM dbo.hwy_nakhebin) AS nakhebin,
      (SELECT COUNT(*) FROM dbo.base_record_events WHERE idempotency_key LIKE N'hwy-etl:ch:%') AS events,
      ${geoSql}
    `,
    { type: QueryTypes.SELECT },
  ))[0];
  return {
    members: Number(row?.members ?? 0),
    membersWithUser: Number(row?.linked ?? 0),
    nakhebin: Number(row?.nakhebin ?? 0),
    changeHistoryEvents: Number(row?.events ?? 0),
    geoMapRows: Number(row?.geoMap ?? 0),
  };
};

export async function readHwyEtlLocalCounts(): Promise<HwyEtlLocalCounts | null> {
  try {
    return await readLocalCountsRow(true);
  } catch {
    try {
      return await readLocalCountsRow(false);
    } catch {
      return null;
    }
  }
}

export async function getHwyEtlConsoleStatus(): Promise<HwyEtlConsoleStatusPayload> {
  const [legacy, local] = await Promise.all([
    probeHwyEtlLegacyConnection(),
    readHwyEtlLocalCounts(),
  ]);

  return {
    legacy,
    local,
    activeRun: serializeRun(activeRun),
    queueLength: queue.length,
    syncState: readHwyEtlSyncStateSummary(repoRoot),
  };
}

export function getHwyEtlActiveRun(): HwyEtlRunRecord | null {
  return serializeRun(activeRun);
}

const buildJobFromSteps = (
  label: string,
  steps: Array<{ step: HwyEtlStepDefinition; options: HwyEtlRunOptions }>,
): QueuedJob => ({ label, steps });

export function startHwyEtlConsoleRun(request: HwyEtlStartRunRequest): {
  ok: boolean;
  message?: string;
  run?: HwyEtlRunRecord;
} {
  const options = request.options ?? {};

  if (request.kind === 'step') {
    const stepId = String(request.stepId ?? '').trim();
    const step = findHwyEtlStepById(stepId);
    if (!step) {
      return { ok: false, message: `Unknown ETL step: ${stepId}` };
    }
    const run = enqueueJob(buildJobFromSteps(step.title, [{ step, options }]));
    return { ok: true, run };
  }

  if (request.kind === 'preset') {
    const presetId = String(request.presetId ?? '').trim();
    const preset = HWY_ETL_PRESETS.find((p) => p.id === presetId);
    if (!preset) {
      return { ok: false, message: `Unknown preset: ${presetId}` };
    }
    const steps = resolveHwyEtlPresetSteps(preset);
    if (!steps.length) {
      return { ok: false, message: 'Preset has no runnable steps.' };
    }
    const mergedDefault = mergeRunOptions(preset.defaultRunOptions, options);
    const job = buildJobFromSteps(
      preset.title,
      steps.map((step) => {
        const stepDefaults = preset.stepRunOptions?.[step.id];
        const stepOptions = stepDefaults
          ? mergeRunOptions(mergedDefault, mergeRunOptions(stepDefaults, options))
          : mergedDefault;
        return { step, options: stepOptions };
      }),
    );
    const run = enqueueJob(job);
    return { ok: true, run };
  }

  if (request.kind === 'pipeline') {
    const ids = request.pipelineStepIds ?? [];
    if (!ids.length) {
      return { ok: false, message: 'Select at least one step for the pipeline.' };
    }
    const resolved = ids
      .map((id) => findHwyEtlStepById(id))
      .filter((step): step is HwyEtlStepDefinition => Boolean(step));
    if (resolved.length !== ids.length) {
      return { ok: false, message: 'One or more step ids are invalid.' };
    }
    const run = enqueueJob(buildJobFromSteps(
      `Custom pipeline (${resolved.length} steps)`,
      resolved.map((step) => ({ step, options })),
    ));
    return { ok: true, run };
  }

  return { ok: false, message: 'Invalid run kind.' };
}

export function cancelHwyEtlConsoleRun(): { ok: boolean; message?: string } {
  if (!activeRun || activeRun.status !== 'running') {
    return { ok: false, message: 'No ETL run is in progress.' };
  }
  activeRun.cancelRequested = true;
  if (activeRun.child) {
    activeRun.child.kill('SIGTERM');
  }
  activeRun.status = 'cancelled';
  activeRun.finishedAt = nowIso();
  const runningStep = activeRun.steps.find((s) => s.status === 'running');
  if (runningStep) {
    runningStep.status = 'cancelled';
    runningStep.finishedAt = nowIso();
  }
  return { ok: true, message: 'Cancel requested.' };
}

/** Test helper — reset singleton runner state. */
export const resetHwyEtlConsoleRunnerForTests = (): void => {
  if (activeRun?.child) {
    activeRun.child.kill('SIGTERM');
  }
  activeRun = null;
  queue.length = 0;
};
