import { apiDelete, apiGet, apiPost, resolveApiMutationErrorMessage } from '../../shared/api/client';

type SuccessEnvelope<T> = { success?: boolean; data?: T; message?: string };

export async function hwyEnvelopeGet<T>(
  path: string,
  init?: RequestInit,
  fallback = 'Request failed.',
): Promise<T> {
  const { data, response } = await apiGet<SuccessEnvelope<T>>(path, init);
  if (!response.ok || !data?.success || data.data === undefined) {
    throw new Error(resolveApiMutationErrorMessage(data, fallback));
  }
  return data.data;
}

export async function hwyEnvelopePost(
  path: string,
  body?: unknown,
  fallback = 'Action failed.',
): Promise<void> {
  const { data, response } = await apiPost<{ success?: boolean; message?: string }>(path, body);
  if (!response.ok || data?.success === false) {
    throw new Error(resolveApiMutationErrorMessage(data, fallback));
  }
}

export async function hwyEnvelopePostData<T>(
  path: string,
  body: unknown,
  fallback = 'Action failed.',
): Promise<T> {
  const { data, response } = await apiPost<SuccessEnvelope<T>>(path, body);
  if (!response.ok || !data?.success || data.data === undefined) {
    throw new Error(resolveApiMutationErrorMessage(data, fallback));
  }
  return data.data;
}

export async function hwyEnvelopeDelete(path: string, fallback = 'Action failed.'): Promise<void> {
  const { data, response } = await apiDelete<{ success?: boolean; message?: string }>(path);
  if (!response.ok || data?.success === false) {
    throw new Error(resolveApiMutationErrorMessage(data, fallback));
  }
}
