import {
  formatDossierAddressGeoDisplay,
  type DossierAddressGeoLevel,
} from './hwyMemberDirectoryDetail';

/** Hawiety Base Info category titles for dossier edit selects (seed catalog). */
export const HWY_MEMBER_DOSSIER_SELECT_CATEGORY = {
  educationStage: 'Education Stage',
  educationUniversity: 'Education University',
  nakhebinLinkProblemReason: 'Nakhebin Link Problem Reason',
} as const;

export type HwyMemberDossierSelectOption = {
  value: string;
  label: string;
};

export type HwyMemberDossierGeoKind = 'maktab' | 'region' | 'circle';

export const HWY_MEMBER_DOSSIER_GEO_KINDS: readonly HwyMemberDossierGeoKind[] = [
  'maktab',
  'region',
  'circle',
];

export function buildHwyMemberDossierCategoryOptionsPath(
  categoryTitle: string,
  cultureId?: string | null,
): string {
  const query = new URLSearchParams({ category: categoryTitle.trim() });
  const culture = String(cultureId ?? '').trim();
  if (culture) {
    query.set('cultureId', culture);
  }
  return `/api/hwy/member-directory/select-options/category?${query.toString()}`;
}

export function buildHwyMemberDossierGeoKindOptionsPath(kind: HwyMemberDossierGeoKind): string {
  const query = new URLSearchParams({ kind });
  return `/api/hwy/member-directory/select-options/geo-kind?${query.toString()}`;
}

export function buildHwyMemberDossierGenderOptionsPath(cultureId: string): string {
  const query = new URLSearchParams({ cultureId: cultureId.trim() || 'iq' });
  return `/api/hwy/member-directory/select-options/gender?${query.toString()}`;
}

/** Edit selects: show leaf title, not full Base Info title_path breadcrumbs. */
export function formatHwyMemberDossierGeoSelectLabel(
  raw: string | null | undefined,
  level: DossierAddressGeoLevel,
): string {
  return formatDossierAddressGeoDisplay(String(raw ?? '').trim(), level);
}

export function mapHwyMemberDossierGeoSelectOptions(
  options: HwyMemberDossierSelectOption[],
  level: DossierAddressGeoLevel,
): HwyMemberDossierSelectOption[] {
  return options.map((row) => {
    const formatted = formatHwyMemberDossierGeoSelectLabel(row.label, level);
    return {
      value: row.value,
      label: formatted || row.label,
    };
  });
}

export type WithOrphanSelectOptionConfig = {
  geoLevel?: DossierAddressGeoLevel;
};

/** Ensure the current stored value stays selectable when not in the loaded list. */
export function withOrphanSelectOption(
  options: HwyMemberDossierSelectOption[],
  currentValue: string | null | undefined,
  currentLabel?: string | null,
  config?: WithOrphanSelectOptionConfig,
): HwyMemberDossierSelectOption[] {
  const value = String(currentValue ?? '').trim();
  if (!value) {
    return options;
  }
  if (options.some((row) => row.value === value)) {
    return options;
  }
  let label = currentLabel?.trim() || value;
  if (config?.geoLevel) {
    label = formatHwyMemberDossierGeoSelectLabel(label, config.geoLevel) || label;
  }
  return [{ value, label }, ...options];
}
