import { apiGet } from '../../shared/api/client';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';

export const HWY_MEMBER_DOSSIER_CHANGE_LOG_KINDS = [
  'member.created',
  'member.updated',
  'member.membershipOn',
  'member.statusChanged',
  'member.userLinked',
  'member.nakhebinLinked',
  'registration.trackingCode',
  'registration.usernameReserved',
  'file.added',
  'file.updated',
  'note.added',
  'institute.linked',
  'institute.activated',
  'institute.invited',
  'targhin.requested',
  'targhin.approved',
  'targhin.rejected',
  'security.profileCreated',
  'recordEvent',
] as const;

export type HwyMemberDossierChangeLogKind = (typeof HWY_MEMBER_DOSSIER_CHANGE_LOG_KINDS)[number];

export type HwyMemberDossierChangeLogDetailLine = {
  labelKey: string;
  value: string;
};

export type HwyMemberDossierChangeLogCopyParams = Record<string, string>;

export type HwyMemberDossierChangeLogEvent = {
  id: string;
  kind: HwyMemberDossierChangeLogKind;
  occurredAt: string;
  actorUserId?: string | null;
  actorUsername?: string | null;
  actorDisplayName?: string | null;
  copyParams?: HwyMemberDossierChangeLogCopyParams;
  sourceTable?: string;
  sourceId?: string;
  detailLines: HwyMemberDossierChangeLogDetailLine[];
};

export type HwyMemberDossierChangeLogPayload = {
  events: HwyMemberDossierChangeLogEvent[];
};

export type HwyMemberDossierChangeLogResponse = {
  success?: boolean;
  message?: string;
  data?: HwyMemberDossierChangeLogPayload;
};

export function buildHwyMemberDossierChangeLogPath(
  memberId: string,
  cultureId?: string | null,
): string {
  const encoded = encodeURIComponent(memberId.trim());
  const lang = resolveHwyMemberDirectoryDetailLang(cultureId);
  return `/api/hwy/member-directory/${encoded}/change-log?lang=${encodeURIComponent(lang)}`;
}

export async function fetchHwyMemberDossierChangeLog(
  memberId: string,
  cultureId?: string | null,
): Promise<HwyMemberDossierChangeLogPayload> {
  const { data, response } = await apiGet<HwyMemberDossierChangeLogResponse>(
    buildHwyMemberDossierChangeLogPath(memberId, cultureId),
  );
  if (!response.ok || data?.success === false || !data?.data) {
    const message = data?.message?.trim() || `Could not load change log. (HTTP ${response.status})`;
    throw new Error(message);
  }
  return data.data;
}

/** Canonical merge order: oldest first (stable id tie-break). */
export function sortHwyMemberDossierChangeLogEvents(
  events: HwyMemberDossierChangeLogEvent[],
): HwyMemberDossierChangeLogEvent[] {
  return [...events].sort((left, right) => {
    const leftMs = Date.parse(left.occurredAt);
    const rightMs = Date.parse(right.occurredAt);
    if (Number.isFinite(leftMs) && Number.isFinite(rightMs) && leftMs !== rightMs) {
      return leftMs - rightMs;
    }
    return left.id.localeCompare(right.id);
  });
}

export type HwyMemberDossierChangeLogTimelineDirection = 'newestFirst' | 'oldestFirst';

/** UI timeline: default newest at top, oldest at bottom. */
export function orderHwyMemberDossierChangeLogEventsForTimeline(
  events: ReadonlyArray<HwyMemberDossierChangeLogEvent>,
  direction: HwyMemberDossierChangeLogTimelineDirection = 'newestFirst',
): HwyMemberDossierChangeLogEvent[] {
  const sorted = sortHwyMemberDossierChangeLogEvents([...events]);
  return direction === 'newestFirst' ? sorted.reverse() : sorted;
}
