/** Sidebar segment under `geo-responsibility/{segment}`. */
export type HwyGeoResponsibilityNavSegment =
  | `candidate-pipeline-${HwyCandidatePipelineStage}`
  | 'assignment-requests'
  | 'removal-requests'
  | HwyGeoResponsibilityLevel;

export const hwyGeoResponsibilityCandidatePipelineNavSegment = (
  stage: HwyCandidatePipelineStage,
): HwyGeoResponsibilityNavSegment => `candidate-pipeline-${stage}`;

export const isHwyGeoResponsibilityCandidatePipelineSegment = (
  segment: HwyGeoResponsibilityNavSegment,
): segment is `candidate-pipeline-${HwyCandidatePipelineStage}` =>
  segment.startsWith('candidate-pipeline-');

