export const hwyGeoResponsibilityNavSegmentFromPath = (
  pathname: string,
): HwyGeoResponsibilityNavSegment => {
  const normalized = pathname.replace(/\/+$/, '');
  const pipelineMatch = normalized.match(/\/geo-responsibility\/candidate-pipeline\/([^/]+)$/i);
  const pipelineStage = hwyCandidatePipelineStageFromSegment(
    pipelineMatch?.[1] ? `candidate-pipeline/${pipelineMatch[1]}` : '',
  );
  if (pipelineStage) {
    return hwyGeoResponsibilityCandidatePipelineNavSegment(pipelineStage);
  }
  const match = normalized.match(/\/geo-responsibility(?:\/([^/]+))?$/i);
  const raw = match?.[1]?.trim().toLowerCase();
  if (!raw) {
    return HWY_GEO_RESPONSIBILITY_DEFAULT_SEGMENT;
  }
  if (raw === 'assignment-requests' || raw === 'assignment' || raw === 'assignments') {
    return hwyGeoResponsibilityCandidatePipelineNavSegment('courses');
  }
  if (raw === 'removal-requests' || raw === 'removal' || raw === 'inbox') {
    return 'removal-requests';
  }
  if (raw === 'province' || raw === 'provinces') {
    return 'province';
  }
  if (raw === 'ghavateh' || raw === 'ghateh' || raw === 'sectors') {
    return 'ghavateh';
  }
  if (raw === 'circle' || raw === 'circles') {
    return 'circle';
  }
  if (raw === 'maktab' || raw === 'tamvin' || raw === 'tamvinat') {
    return 'maktab';
  }
  if (raw === 'region' || raw === 'regions' || raw === 'eghtera' || raw === 'eghteraat') {
    return 'region';
  }
  if (isHwyGeoResponsibilityLevel(raw)) {
    return raw;
  }
  return HWY_GEO_RESPONSIBILITY_DEFAULT_SEGMENT;
};

export const hwyGeoResponsibilityPathSegment = (
  segment: HwyGeoResponsibilityNavSegment,
): string => {
  if (isHwyGeoResponsibilityCandidatePipelineSegment(segment)) {
    const stage = segment.replace('candidate-pipeline-', '') as HwyCandidatePipelineStage;
    return hwyCandidatePipelinePathSegment(stage);
  }
  return segment;
};

export const hwyGeoResponsibilityPrimaryListSegments = (): HwyGeoResponsibilityLevel[] => (
  [...HWY_GEO_RESPONSIBILITY_LEVELS]
);

/** Province / ghavateh / circle lists: load one batch (legacy lists are small enough). */
export const HWY_GEO_RESPONSIBILITY_UNPAGED_NODE_LEVELS: readonly HwyGeoResponsibilityLevel[] = [
  'province',
  'ghavateh',
  'circle',
];

export const HWY_GEO_RESPONSIBILITY_UNPAGED_NODE_LIMIT = 1000;

export const hwyGeoResponsibilityUsesUnpagedNodeList = (
  level: HwyGeoResponsibilityLevel | null,
): level is HwyGeoResponsibilityLevel => (
  level != null && (HWY_GEO_RESPONSIBILITY_UNPAGED_NODE_LEVELS as readonly string[]).includes(level)
);
