import type { HwyMemberTarghinAdminMemberFace } from './hwyMemberTarghinAdmin';

/** Hawiety admin list identity chip (targhin / geo-responsibility geometry). */
export type HwyMemberListFace = HwyMemberTarghinAdminMemberFace;

export function buildHwyMemberListFace(input: {
  id?: string | number | null;
  username?: string | null;
  displayFullName?: string | null;
  genderCode?: string | null;
  avatarUrl?: string | null;
  phone?: string | null;
  electoralDivisionPath?: string | null;
}): HwyMemberListFace | null {
  const id = String(input.id ?? '').trim();
  if (!id) {
    return null;
  }
  return {
    id,
    username: input.username?.trim() || null,
    displayFullName: input.displayFullName?.trim() || null,
    genderCode: input.genderCode?.trim() || null,
    avatarUrl: input.avatarUrl?.trim() || null,
    phone: input.phone?.trim() || null,
    electoralDivisionPath: input.electoralDivisionPath?.trim() || null,
  };
}

export function hwyMemberListFaceHasLabel(face: HwyMemberListFace | null | undefined): boolean {
  if (!face?.id) {
    return false;
  }
  return Boolean(face.displayFullName?.trim() || face.username?.trim());
}
