import type { HwySecurityOpinionCode } from './hwyCandidatePipeline';

export type HwyPipelineOpinionOption = {
  value: HwySecurityOpinionCode;
  labelEn: string;
};

/** Legacy parent 211750 — supervisory opinion codes. */
export const HWY_SECURITY_OPINION_OPTIONS: HwyPipelineOpinionOption[] = [
  { value: 211751, labelEn: 'Allowed' },
  { value: 211752, labelEn: 'Not allowed' },
  { value: 211753, labelEn: 'Unclear / pending' },
];

export type HwyInterviewFinalOption = { value: number; labelEn: string };

/** Common interview final-result base-information ids (legacy HWY_Members_Interviews_2022). */
export const HWY_INTERVIEW_FINAL_RESULT_OPTIONS: HwyInterviewFinalOption[] = [
  { value: 213609, labelEn: 'Approved (maktab and region)' },
  { value: 213610, labelEn: 'Approved (region only)' },
  { value: 213611, labelEn: 'Not approved for any responsibility' },
];

export const hwySecurityOpinionLabel = (code: number | null | undefined): string => {
  const found = HWY_SECURITY_OPINION_OPTIONS.find((o) => o.value === code);
  return found?.labelEn ?? (code != null ? String(code) : '—');
};

const HWY_CANDIDATE_PIPELINE_NOMINATION_ROLE_IDS = new Set(['1000004', '1000005']);

export const resolveHwyCandidatePipelineNominationRoleLabel = (
  row: {
    roleOfTarshih?: string | null;
    roleId?: string | null;
    isApprovedRow?: number | null;
  },
  t: (key: string, fallback: string) => string,
): string => {
  const roleId = String(row.roleId ?? '').trim();
  const approved = row.isApprovedRow === 1;
  if (roleId === '1000004') {
    return t(
      approved ? 'hwy.candidatePipeline.role.maktab' : 'hwy.candidatePipeline.role.maktabCandidate',
      approved ? 'Maktab official' : 'Maktab candidate',
    );
  }
  if (roleId === '1000005') {
    return t(
      approved ? 'hwy.candidatePipeline.role.region' : 'hwy.candidatePipeline.role.regionCandidate',
      approved ? 'Region official' : 'Region candidate',
    );
  }
  const legacy = String(row.roleOfTarshih ?? '').trim();
  if (legacy && !HWY_CANDIDATE_PIPELINE_NOMINATION_ROLE_IDS.has(legacy)) {
    return legacy;
  }
  return legacy || '—';
};

export const resolveHwyCandidatePipelineInterviewResultLabel = (
  row: {
    interviewFinalResult?: string | null;
    interviewFinalResultTitle?: string | null;
  },
  t: (key: string, fallback: string) => string,
): string => {
  const title = String(row.interviewFinalResultTitle ?? '').trim();
  if (title) {
    return title;
  }
  const raw = String(row.interviewFinalResult ?? '').trim();
  if (!raw) {
    return '—';
  }
  const code = Number(raw);
  if (Number.isFinite(code)) {
    const found = HWY_INTERVIEW_FINAL_RESULT_OPTIONS.find((o) => o.value === code);
    if (found) {
      return t(`hwy.candidatePipeline.interview.final.${found.value}`, found.labelEn);
    }
  }
  return raw;
};

/** Calendar days from nomination (`DateOfTarshih`) to today — legacy `DaysFrom` parity. */
export const resolveHwyCandidatePipelineDaysFromNomination = (
  dateOfTarshih: string | null | undefined,
): number | null => {
  const raw = String(dateOfTarshih ?? '').trim();
  if (!raw) {
    return null;
  }
  const parsed = new Date(raw);
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }
  const nominationDay = new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const days = Math.floor((today.getTime() - nominationDay.getTime()) / 86_400_000);
  return days >= 0 ? days : null;
};
