import {
  connectLegacyReadPool,
  fetchLegacyPlatformRolesByAction,
} from '../../../../scripts/hwy-etl/legacyHwyRoleAuth';
import {
  HWY_MEMBER_KASB_LINK_LEGACY_ACTION,
  hwyMemberKasbLinkLegacyActionKey,
  viewerCanManageHwyMemberKasbLinks,
} from '../../../domain/hwy/hwyMemberKasbLegacyAccess';

const ALLOW_ROLES_CACHE_MS = 30_000;
let allowRolesCache: { roles: string[]; loadedAt: number } | null = null;

const FALLBACK_KASB_LINK_ALLOW_ROLES = ['ADMIN'] as const;

async function loadLegacyKasbLinkPlatformRoles(): Promise<string[]> {
  try {
    const pool = await connectLegacyReadPool();
    try {
      const byAction = await fetchLegacyPlatformRolesByAction(pool, [HWY_MEMBER_KASB_LINK_LEGACY_ACTION]);
      return byAction.get(hwyMemberKasbLinkLegacyActionKey()) ?? [];
    } finally {
      await pool.close();
    }
  } catch {
    return [...FALLBACK_KASB_LINK_ALLOW_ROLES];
  }
}

export async function resolveHwyMemberKasbLinkAllowRoles(): Promise<string[]> {
  const now = Date.now();
  if (allowRolesCache && now - allowRolesCache.loadedAt < ALLOW_ROLES_CACHE_MS) {
    return allowRolesCache.roles;
  }
  const fromLegacy = await loadLegacyKasbLinkPlatformRoles();
  const roles = fromLegacy.length > 0 ? fromLegacy : [...FALLBACK_KASB_LINK_ALLOW_ROLES];
  allowRolesCache = { roles, loadedAt: now };
  return roles;
}

export async function assertHwyMemberKasbLinkAccess(roleNames: readonly string[]): Promise<void> {
  const allowed = await resolveHwyMemberKasbLinkAllowRoles();
  if (!viewerCanManageHwyMemberKasbLinks(roleNames, allowed)) {
    throw new Error('Forbidden.');
  }
}
