import { SETTINGS_PATH } from '../../../src/server/config/settingsFile';
import { readControlPlaneDatabaseSettings } from '../../../src/server/db/controlPlaneDatabase';
import { connectMssqlControlPlane, createPostgresPool, resolveHwyDefaultDataSource } from '../../hwy-phase1/hwyDataSource';

const GEO_FK_COLUMNS: Array<{ table: string; column: string }> = [
  { table: 'hwy_members', column: 'addr_province_id' },
  { table: 'hwy_members', column: 'addr_region_id' },
  { table: 'hwy_members', column: 'addr_circle_id' },
  { table: 'hwy_members', column: 'addr_maktab_id' },
  { table: 'hwy_members', column: 'nakhebin_link_region_id' },
  { table: 'hwy_nakhebin', column: 'region_id' },
  { table: 'hwy_nakhebin', column: 'maktab_id' },
];

/**
 * `base_info.id` values (e.g. 100.5.2.3) require string FK columns on edge `hwy_*` tables.
 */
export async function ensureHwyGeoFkColumnsAreString(): Promise<void> {
  const { kind, source } = resolveHwyDefaultDataSource();
  if (kind === 'postgresql') {
    const pool = createPostgresPool(source);
    try {
      for (const { table, column } of GEO_FK_COLUMNS) {
        const check = await pool.query<{ data_type: string }>(`
          SELECT data_type FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = $1 AND column_name = $2
        `, [table, column]);
        const dataType = check.rows[0]?.data_type;
        if (dataType === 'bigint' || dataType === 'integer') {
          await pool.query(`ALTER TABLE ${table} ALTER COLUMN ${column} TYPE VARCHAR(128) USING ${column}::varchar`);
        }
      }
    } finally {
      await pool.end();
    }
    return;
  }

  const cp = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  if (cp.provider !== 'sqlserver') {
    throw new Error('HWY geo FK migration requires SQL Server or PostgreSQL edge data source.');
  }

  const pool = await connectMssqlControlPlane();
  try {
    for (const { table, column } of GEO_FK_COLUMNS) {
      await pool.request().query(`
        IF EXISTS (
          SELECT 1 FROM sys.columns c
          JOIN sys.types t ON c.user_type_id = t.user_type_id
          WHERE c.object_id = OBJECT_ID(N'dbo.${table}')
            AND c.name = N'${column}'
            AND t.name IN (N'bigint', N'int')
        )
        BEGIN
          ALTER TABLE dbo.${table} ALTER COLUMN ${column} NVARCHAR(128) NULL;
        END
      `);
    }
  } finally {
    await pool.close();
  }
}
