import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { emitHwyMemberDirectoryPatchHistory } from '../record-events/hwyMemberHistory';
import {
  HWY_MEMBER_HISTORY_SNAPSHOT_SQL,
  hwyMemberRowToHistorySnapshot,
} from '../record-events/hwyMemberHistoryFields';
import { invalidateHwyMemberDirectoryListCache } from './hwyMemberDirectoryListCache';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const parseNakhebinId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Nakhebin id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Nakhebin id is invalid.');
  }
  return id;
};

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Nakhebin mutations require SQL Server control plane.');
  }
  await ensureHwyDbObjects();
};

const readSnapshot = async (memberId: number) => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `SELECT ${HWY_MEMBER_HISTORY_SNAPSHOT_SQL} FROM dbo.hwy_members WHERE id = :id`,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  return rows[0] ? hwyMemberRowToHistorySnapshot(rows[0]) : null;
};

const emitIfChanged = async (
  memberId: number,
  before: ReturnType<typeof hwyMemberRowToHistorySnapshot> | null,
  actorUserId: number | null,
): Promise<void> => {
  const after = await readSnapshot(memberId);
  if (before && after) {
    await emitHwyMemberDirectoryPatchHistory({
      memberId,
      before,
      after,
      actorUserId,
    });
  }
  await invalidateHwyMemberDirectoryListCache();
};

type NakhebinProcName =
  | 'hwy_member_nakhebin_link'
  | 'hwy_member_nakhebin_link_family'
  | 'hwy_member_nakhebin_link_eghtera'
  | 'hwy_member_nakhebin_link_with_problem'
  | 'hwy_member_nakhebin_clear'
  | 'hwy_member_nakhebin_change_roghe'
  | 'hwy_member_set_addr_eghtera';

const execNakhebinMutation = async (
  memberId: number,
  proc: NakhebinProcName,
  params: Record<string, unknown>,
  actorUserId: number | null,
): Promise<void> => {
  const before = await readSnapshot(memberId);
  if (proc === 'hwy_member_nakhebin_link') {
    await execHwyProcedure('hwy_member_nakhebin_link', params);
  } else if (proc === 'hwy_member_nakhebin_link_family') {
    await execHwyProcedure('hwy_member_nakhebin_link_family', params);
  } else if (proc === 'hwy_member_nakhebin_link_eghtera') {
    await execHwyProcedure('hwy_member_nakhebin_link_eghtera', params);
  } else if (proc === 'hwy_member_nakhebin_link_with_problem') {
    await execHwyProcedure('hwy_member_nakhebin_link_with_problem', params);
  } else if (proc === 'hwy_member_nakhebin_clear') {
    await execHwyProcedure('hwy_member_nakhebin_clear', params);
  } else if (proc === 'hwy_member_nakhebin_change_roghe') {
    await execHwyProcedure('hwy_member_nakhebin_change_roghe', params);
  } else {
    await execHwyProcedure('hwy_member_set_addr_eghtera', params);
  }
  await emitIfChanged(memberId, before, actorUserId);
};

export const linkHwyMemberNakhebinBallot = async (input: {
  memberIdRaw: string;
  nakhebinIdRaw: string;
  nakhebinLinkRegionId?: string | null;
  actorUserId: number | null;
}): Promise<void> => {
  await assertSqlServer();
  const memberId = parseMemberId(input.memberIdRaw);
  const nakhebinId = parseNakhebinId(input.nakhebinIdRaw);
  await execNakhebinMutation(memberId, 'hwy_member_nakhebin_link', {
    member_id: memberId,
    nakhebin_id: nakhebinId,
    nakhebin_link_region_id: input.nakhebinLinkRegionId?.trim() || null,
    actor_user_id: input.actorUserId,
  }, input.actorUserId);
};

