export const linkHwyMemberNakhebinWithProblem = async (input: {
  memberIdRaw: string;
  nakhebinIdRaw: string;
  linkTypeShort: 'family' | 'electoral_center' | 'eghtera';
  nakhebinLinkProblemReasonId: string;
  nakhebinLinkProblemNote?: string | null;
  nakhebinLinkRegionId?: string | null;
  actorUserId: number | null;
}): Promise<void> => {
  await assertSqlServer();
  const memberId = parseMemberId(input.memberIdRaw);
  const nakhebinId = parseNakhebinId(input.nakhebinIdRaw);
  const reasonId = input.nakhebinLinkProblemReasonId.trim();
  if (!reasonId) {
    throw new Error('Nakhebin link problem reason is required.');
  }
  await execNakhebinMutation(memberId, 'hwy_member_nakhebin_link_with_problem', {
    member_id: memberId,
    nakhebin_id: nakhebinId,
    link_type_short: input.linkTypeShort,
    nakhebin_link_problem_reason_id: reasonId,
    nakhebin_link_problem_note: input.nakhebinLinkProblemNote?.trim() || null,
    nakhebin_link_region_id: input.nakhebinLinkRegionId?.trim() || null,
    actor_user_id: input.actorUserId,
  }, input.actorUserId);
};

