import type { HwyGeoResponsibilityMontadheminAdminListResult } from '../../../domain/hwy/hwyGeoResponsibilityMontadheminAdmin';
import {
  hwyGeoResponsibilityCanAccessSection,
  hwyGeoResponsibilityPatchRoleNames,
} from '../../../domain/hwy/hwyGeoResponsibilityCatalog';
import {
  resolveHwyGeoResponsibilityAvatarUrl,
} from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';
import { ensureHwyGeoResponsibilitySchema } from './ensureHwyGeoResponsibilitySchema';
import { ensureHwyMemberPassedNecessaryDoratSql } from './ensureHwyMemberPassedNecessaryDoratSql';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy geo-responsibility montadhemin admin requires SQL Server control plane.');
  }
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return {
    page: safePage,
    pageSize: safePageSize,
    offset: (safePage - 1) * safePageSize,
  };
};

export const listHwyGeoResponsibilityMontadheminAdmin = async (
  input: {
    search?: string;
    page?: number;
    pageSize?: number;
  },
  roleNames: readonly string[],
): Promise<HwyGeoResponsibilityMontadheminAdminListResult> => {
  assertSqlServer();
  if (!hwyGeoResponsibilityCanAccessSection(roleNames)) {
    throw new Error('Forbidden.');
  }

  await ensureHwyGeoResponsibilitySchema();
  await ensureHwyMemberPassedNecessaryDoratSql();
  await ensureHwyDbObjects();

  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);
  const scope = await loadHwyMemberListScopeContext();
  const activeMembership = scope.membershipStatusCodes.active;
  const geoRoleNamesCsv = hwyGeoResponsibilityPatchRoleNames().join(',');

  const search = trim(input.search);
  const searchLike = search ? `%${search}%` : null;
  const procBase = {
    active_membership_code: activeMembership,
    search_like: searchLike,
  };

  const countRows = await execHwyProcedure<{ total: number | string }>(
    'hwy_geo_responsibility_montadhemin_count',
    procBase,
  );
  const total = Number(countRows[0]?.total ?? 0);

  const rows = await execHwyProcedure<{
    id: string;
    username: string | null;
    displayFullName: string | null;
    genderCode: string | null;
    avatarUrl: string | null;
    userId: string | null;
    hasProfileImage: boolean | number | null;
    electoralDivisionPath: string | null;
    passedNecessaryDorat: boolean | number | null;
    canGetResponsibilityTitle: string | null;
    canGetResponsibilityNote: string | null;
    allowsResponsibilityTitle: string | null;
    activeResponsibilityRole: string | null;
    activeResponsibilityGeoTitlePath: string | null;
  }>('hwy_geo_responsibility_montadhemin_list', {
    ...procBase,
    geo_role_names_csv: geoRoleNamesCsv,
    offset,
    page_size: pageSize,
  });

  return {
    total,
    page,
    pageSize,
    rows: rows.map((row) => ({
      id: trim(row.id),
      username: row.username ? trim(row.username) : null,
      displayFullName: formatHwyMemberPersonDisplayName(row.displayFullName) || null,
      genderCode: row.genderCode ? trim(row.genderCode) : null,
      avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
        avatarUrl: row.avatarUrl,
        hasProfileImage: row.hasProfileImage,
        userId: row.userId ? Number(row.userId) : null,
      }),
      electoralDivisionPath: row.electoralDivisionPath ? trim(row.electoralDivisionPath) : null,
      passedNecessaryDorat: row.passedNecessaryDorat === true || row.passedNecessaryDorat === 1,
      canGetResponsibilityTitle: row.canGetResponsibilityTitle ? trim(row.canGetResponsibilityTitle) : null,
      canGetResponsibilityNote: row.canGetResponsibilityNote ? trim(row.canGetResponsibilityNote) : null,
      allowsResponsibilityTitle: row.allowsResponsibilityTitle ? trim(row.allowsResponsibilityTitle) : null,
      activeResponsibilityRole: row.activeResponsibilityRole ? trim(row.activeResponsibilityRole) : null,
      activeResponsibilityGeoTitlePath: row.activeResponsibilityGeoTitlePath
        ? trim(row.activeResponsibilityGeoTitlePath)
        : null,
      profileComplete: null,
      interviewResultTitle: null,
      allDocumentsApproved: null,
      hasOath: null,
    })),
  };
};
