import type { HwyGeoResponsibilityPatchHistoryEvent } from './hwyGeoResponsibility';

/** Legacy rows with unknown EventOn are stored at this sentinel (ETL). */
export const HWY_PATCH_HISTORY_UNKNOWN_EVENT_AT = '1900-01-01T00:00:00.000Z';

const eventTimeMs = (eventOn: string): number | null => {
  const raw = String(eventOn ?? '').trim();
  if (!raw || raw.startsWith('1900-01-01')) {
    return null;
  }
  const ms = Date.parse(raw);
  return Number.isFinite(ms) ? ms : null;
};

const kindSortRank = (eventKind: HwyGeoResponsibilityPatchHistoryEvent['eventKind']): number => {
  if (eventKind === 'confirmed') {
    return 2;
  }
  if (eventKind === 'nomination') {
    return 1;
  }
  return 0;
};

const comparePatchHistoryEvents = (
  a: HwyGeoResponsibilityPatchHistoryEvent,
  b: HwyGeoResponsibilityPatchHistoryEvent,
): number => {
  const aMs = eventTimeMs(a.eventOn) ?? 0;
  const bMs = eventTimeMs(b.eventOn) ?? 0;
  if (bMs !== aMs) {
    return bMs - aMs;
  }
  return kindSortRank(b.eventKind) - kindSortRank(a.eventKind);
};

/**
 * Legacy `Read_Extra` is authoritative once ETL has legacy rows for a patch.
 * Studio rows are shown only when there is no legacy history for that geo yet.
 */
export const mergePatchHistoryEventsForLegacyParity = (
  events: HwyGeoResponsibilityPatchHistoryEvent[],
): HwyGeoResponsibilityPatchHistoryEvent[] => {
  const legacy = events.filter((event) => event.source === 'legacy');
  const studio = events.filter((event) => event.source === 'studio');
  if (legacy.length > 0) {
    return [...legacy].sort(comparePatchHistoryEvents);
  }
  return [...studio].sort(comparePatchHistoryEvents);
};
