import { sortHwyPlatformRoleDisplayLabels } from './hwyPlatformRoleDisplay';

const ROLE_TITLES_CSV_SEP = '|';

export function parseHwyTarghinExecutorRoleTitlesCsv(raw: unknown): string[] {
  const text = String(raw ?? '').trim();
  if (!text) {
    return [];
  }
  return sortHwyPlatformRoleDisplayLabels(text.split(ROLE_TITLES_CSV_SEP));
}

export function mergeHwyTarghinExecutorRoleTitleLists(
  ...lists: readonly (readonly string[])[]
): string[] {
  const merged: string[] = [];
  for (const list of lists) {
    merged.push(...list);
  }
  return sortHwyPlatformRoleDisplayLabels(merged);
}
