import { resolveListUserAvatarSrc } from '../../shared/api/contracts/users/avatar';
import type {
  HwyGeoResponsibilityNodeOfficialSlot,
  HwyGeoResponsibilitySlotMemberKind,
} from './hwyGeoResponsibility';

import { formatHwyMemberPersonDisplayName } from './hwyMemberPersonDisplayName';

export const formatHwyGeoResponsibilityMemberDisplayName = (
  raw: string | null | undefined,
): string => {
  const formatted = formatHwyMemberPersonDisplayName(raw);
  return formatted || '—';
};

export const resolveHwyGeoResponsibilityMembershipLabel = (
  username: string | null | undefined,
  memberId: string | number | null | undefined,
): string | null => {
  const trimmedUsername = username?.trim();
  if (trimmedUsername) {
    return trimmedUsername;
  }
  if (memberId == null) {
    return null;
  }
  const asText = String(memberId).trim();
  return asText.length > 0 ? asText : null;
};

const parseNumericMemberId = (value: string | null | undefined): string | null => {
  const trimmed = value?.trim() ?? '';
  if (!trimmed || !/^\d+$/.test(trimmed)) {
    return null;
  }
  return trimmed;
};

/** `hwy_members.id` for slot actions — never membership username / number label. */
export const resolveHwyGeoResponsibilitySlotMemberId = (
  kind: HwyGeoResponsibilitySlotMemberKind,
  slot: HwyGeoResponsibilityNodeOfficialSlot,
): string | null => {
  const direct = kind === 'official'
    ? slot.assigneeMemberId
    : slot.pendingMemberId;
  return parseNumericMemberId(direct);
};

export const resolveHwyGeoResponsibilityAvatarUrl = (input: {
  avatarUrl?: string | null;
  userId?: number | null;
  hasProfileImage?: boolean | null;
}): string | null => {
  const direct = input.avatarUrl?.trim();
  if (direct) {
    return direct;
  }
  const userId = Number(input.userId);
  if (!Number.isFinite(userId) || userId <= 0) {
    return null;
  }
  return resolveListUserAvatarSrc({
    id: userId,
    avatar_url: null,
    has_profile_image_xs: Boolean(input.hasProfileImage),
  });
};
