import { HWY_VOTER_CARD_FRONT_TYPE_BASE_INFO_CATEGORY } from '../../../domain/hwy/hwyMemberImageFixVoterCardType';
import { seedHwyBaseInfo } from '../../../../scripts/hwy-phase1/seed/seedHwyBaseInfo';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';

let ensurePromise: Promise<void> | null = null;

const hasVoterCardFrontTypeVocab = async (): Promise<boolean> => {
  const fishehId = await tryFindHwyBaseInfoItemIdByShortName(
    HWY_VOTER_CARD_FRONT_TYPE_BASE_INFO_CATEGORY,
    'fisheh',
  );
  return Boolean(fishehId);
};

/** Idempotent Base Info seed for ImageFix voter card type (unknown / biometric / fisheh). */
export const ensureHwyMemberImageFixEditorBaseInfo = async (): Promise<void> => {
  if (await hasVoterCardFrontTypeVocab()) {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = (async () => {
      await seedHwyBaseInfo(null);
      if (!(await hasVoterCardFrontTypeVocab())) {
        throw new Error(
          'Hawiety Base Info category "Voter Card Front Type" is missing after seed. Run Hawiety phase-1 Base Info seed.',
        );
      }
    })();
  }

  await ensurePromise;
};
