import type { ModelCtor } from 'sequelize';
import type { EdgeApiOperation, EdgeModelDefinition } from '../../../shared/api/contracts/data-api';
import type { StoredDataSource } from '../../db/dataSourcesStore';
import {
  parsePositiveInt,
  parseSearchQuery,
  buildSearchWhere,
  resolveSearchableFields,
  parseIncludeAliases,
  buildIncludeOptionsFromOperation,
  buildQueryAttributes,
  resolveReadableAttributes,
} from '../../services/data-api/dataApiQuery';
import { applyFieldEnrichments } from '../../services/data-api/dataApiFieldEnrichment';
import { resolveDataApiListIncludeCount } from '../../services/data-api/dataApiListCount';
import { enrichHwyMemberDirectoryListRows } from './hwyMemberDirectoryDetailDisplay';
import {
  applyHwyMemberDirectoryListFaceCaptionUsernames,
  HWY_MEMBER_DIRECTORY_LIST_FACE_CAPTION_ROW_FIELDS,
} from './hwyMemberDirectoryListFaceCaption';
import {
  canUseMemberDirectoryListFastPath,
  countMemberDirectoryListFastPath,
  fetchMemberDirectoryListFastPath,
} from './hwyMemberDirectoryListFastPath';
import { resolveMemberDirectoryListFieldEnrichments } from './hwyMemberDirectoryListEnrichments';
import {
  parseHwyMemberDirectoryListScopeQuery,
  resolveHwyMemberDirectoryListScopeWhere,
} from './hwyMemberDirectoryListScope.service';
import {
  findHwyMemberSegmentListByLegacyCode,
  resolveListMembershipOnRegistrationFallback,
} from '../../../domain/hwy/hwyMemberSegmentListCatalog';
import {
  HWY_MEMBER_QUICK_SEARCH_LIST_PAGE_SIZE,
  isHwyMemberQuickSearchListScope,
} from '../../../domain/hwy/hwyMemberQuickSearchCatalog';
import {
  shouldEnrichImageFixRegistrationThumbsForListScope,
  shouldEnrichListFaceAvatarsFromRegistrationForListScope,
} from '../../../domain/hwy/hwyMemberImageFixCatalog';
import { shouldEnrichMemberInstitutesSummaryForListScope } from '../../../domain/hwy/hwyMemberInstitutesGridColumn';
import { resolveHwyMemberDirectoryListOrder } from './hwyMemberDirectoryListOrder';
import { attachHwyMemberRejectionListParityFields } from './hwyMemberRejectionListParity.service';
import {
  HWY_MEMBER_REJECTION_LIST_DIRECTORY_READ_FIELDS,
  isHwyMemberRejectionListLegacyScope,
} from '../../../domain/hwy/hwyMemberRejectionListParity';
import { resolveHwyMemberDirectoryQueryLang } from './hwyMemberDirectoryQueryLang';
import { resolveFieldEnrichmentDeps } from '../../services/data-api/dataApiPublishedRuntime';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import { applyRecordPolicies } from '../../services/record-policy/applyRecordPolicies';
import { getRecordPolicyBindingOrDefault } from '../../services/record-policy/recordPolicyBindingStore';
import {
  isRecordScopeEnforcedForPolicies,
  resolveRecordPoliciesForOperation,
} from '../../services/record-policy/recordPolicyOperationScope';
import { mergeWhereAnd } from '../../services/record-policy/whereMerge';
import {
  buildHwyMemberDirectoryImageFixListFilterWhere,
  buildHwyMemberImageFixListMembershipBaseWhere,
  parseHwyMemberDirectoryImageFixListFilters,
} from './hwyMemberDirectoryImageFixListFilters.service';
import { hwyMemberImageFixListFiltersAffectQuery } from '../../../domain/hwy/hwyMemberImageFixListFilters';
import {
  buildHwyMontadheminInstituteFilterWhere,
  parseHwyMontadheminInstituteIdsFilter,
  parseHwyMontadheminInstituteMatchFilter,
} from './hwyMemberDirectoryMontadheminInstituteFilter.service';
import { buildHwyMemberDirectoryListLegacyFilterWhere } from './hwyMemberDirectoryListLegacyFilterWhere.service';
import {
  omitJoinTasjilRegisteredFilterFromWhere,
  parseHwyMemberDirectoryListJoinTasjilRegisteredFilter,
  resolveHwyMemberDirectoryListJoinTasjilFilterEqToDbCode,
} from './hwyMemberDirectoryListJoinTasjilFilter';

const DEFAULT_WHERE = {};
const MAX_PAGE_SIZE = 5000;
const DEFAULT_PAGE_SIZE = 20;
const ALLOW_FILTER = true;
const ALLOW_SORT = true;

/** Computed in SQL view via scalar UDFs — skip on list query; enrich after page fetch instead. */
const LIST_OMIT_READ_FIELDS = new Set(['electoralDivisionPath']);

export type ExecuteHwyMemberDirectoryListInput = {
  operation: EdgeApiOperation;
  model: EdgeModelDefinition;
  source: StoredDataSource;
  ModelCtor: ModelCtor;
  query: Record<string, unknown>;
  req?: { headers?: Record<string, unknown> };
  edgeModelId: string;
  session?: SessionScopeSnapshot | null;
};

export async function executeHwyMemberDirectoryList(
  input: ExecuteHwyMemberDirectoryListInput,
): Promise<Record<string, unknown>> {
  const { operation, model, source, ModelCtor, query, req, edgeModelId, session } = input;
  const sequelize = ModelCtor.sequelize;
  if (!sequelize) {
    throw new Error('Member directory list requires a Sequelize connection.');
  }

  const viewName = typeof query.view === 'string' ? query.view.trim() : undefined;
  const readableAttributes = resolveReadableAttributes(operation, model, viewName);
  const allowedFilterFields = new Set(readableAttributes ?? []);
  for (const field of ['createdAt', 'updatedAt'] as const) {
    if (model.columns.some((column) => column.field === field)) {
      allowedFilterFields.add(field);
    }
  }
  const page = parsePositiveInt(query.page, 1);
  const listScopeLegacyEarly = parseHwyMemberDirectoryListScopeQuery(query);
  const isQuickSearchList = isHwyMemberQuickSearchListScope(listScopeLegacyEarly);
  const requestedPageSize = parsePositiveInt(
    query.pageSize,
    operation.query?.defaultPageSize ?? DEFAULT_PAGE_SIZE,
  );
  const pageSize = isQuickSearchList
    ? Math.min(requestedPageSize, HWY_MEMBER_QUICK_SEARCH_LIST_PAGE_SIZE)
    : Math.min(requestedPageSize, operation.query?.maxPageSize ?? MAX_PAGE_SIZE);
  const offset = (page - 1) * pageSize;
  let filterWhere = ALLOW_FILTER
    ? buildHwyMemberDirectoryListLegacyFilterWhere(query, allowedFilterFields, model.columns)
    : {};
  const joinTasjilRegisteredShort = parseHwyMemberDirectoryListJoinTasjilRegisteredFilter(query);
  const joinTasjilRegisteredDbCode = await resolveHwyMemberDirectoryListJoinTasjilFilterEqToDbCode(query);
  if (joinTasjilRegisteredDbCode) {
    filterWhere = {
      ...filterWhere,
      nakhebinJoinTasjilStateCode: joinTasjilRegisteredDbCode,
    };
  }
  const filterWhereExcludingJoinTasjil = joinTasjilRegisteredShort
    ? omitJoinTasjilRegisteredFilterFromWhere(filterWhere)
    : filterWhere;
  const searchWhere = ALLOW_FILTER
    ? buildSearchWhere(parseSearchQuery(query), resolveSearchableFields(allowedFilterFields, model.columns, []))
    : {};
  const listScopeLegacy = parseHwyMemberDirectoryListScopeQuery(query);
  const montadheminInstituteIds = parseHwyMontadheminInstituteIdsFilter(query, listScopeLegacy);
  const montadheminInstituteMatch = parseHwyMontadheminInstituteMatchFilter(query, listScopeLegacy);
  const hasMontadheminInstituteFilter = montadheminInstituteIds.length > 0;
  const imageFixListFilters = parseHwyMemberDirectoryImageFixListFilters(query, listScopeLegacy);
  const hasImageFixListFilters = Boolean(
    imageFixListFilters && hwyMemberImageFixListFiltersAffectQuery(imageFixListFilters),
  );
  const hasStructuredFilters = Object.keys(filterWhereExcludingJoinTasjil).length > 0
    || hasImageFixListFilters;
  const listSearch = parseSearchQuery(query);
  const recordPolicyOverride = {
    bypassRecordPolicy: Boolean(operation.bypassRecordPolicy),
    recordPolicyId: operation.recordPolicyId,
  };
  const recordPolicyBinding = getRecordPolicyBindingOrDefault(model.id);
  const recordPolicies = resolveRecordPoliciesForOperation(model.id, recordPolicyOverride);
  const recordScopeConfigured = isRecordScopeEnforcedForPolicies(
    recordPolicyBinding.recordScope,
    recordPolicies,
  );
  const adminBypassesRecordScope = Boolean(
    session?.isAdmin
    && !recordPolicyBinding.forceScopeForAdmin
    && !recordPolicyOverride.bypassRecordPolicy,
  );
  let useListFastPath = Boolean(
    listScopeLegacy
    && sequelize.getDialect() === 'mssql'
    && canUseMemberDirectoryListFastPath(listScopeLegacy, hasStructuredFilters)
    && (!recordScopeConfigured || adminBypassesRecordScope || recordPolicyOverride.bypassRecordPolicy),
  );
  if (hasImageFixListFilters) {
    useListFastPath = false;
  }
  let listScopeWhere = {};
  if (listScopeLegacy && !useListFastPath) {
    if (
      imageFixListFilters?.queue === ''
      || imageFixListFilters?.queue === 'tadghigh'
    ) {
      listScopeWhere = await buildHwyMemberImageFixListMembershipBaseWhere(sequelize);
    } else {
      listScopeWhere = await resolveHwyMemberDirectoryListScopeWhere(sequelize, listScopeLegacy);
    }
    if (imageFixListFilters) {
      listScopeWhere = mergeWhereAnd(
        listScopeWhere,
        await buildHwyMemberDirectoryImageFixListFilterWhere(sequelize, imageFixListFilters),
      );
    }
    if (hasMontadheminInstituteFilter && !useListFastPath) {
      listScopeWhere = mergeWhereAnd(
        listScopeWhere,
        await buildHwyMontadheminInstituteFilterWhere(
          sequelize,
          montadheminInstituteIds,
          montadheminInstituteMatch,
        ),
      );
    }
  }
  const policyApplied = applyRecordPolicies({
    model,
    operationKind: 'list',
    session: session ?? null,
    ...recordPolicyOverride,
    baseWhere: mergeWhereAnd(
      DEFAULT_WHERE,
      listScopeWhere,
      filterWhere,
      searchWhere,
    ),
  });
  const where = policyApplied.where;
  if (policyApplied.denyAll) {
    const listCountResolved = resolveDataApiListIncludeCount(query, operation);
    const listCount = isQuickSearchList
      ? { ...listCountResolved, includeCount: false }
      : listCountResolved;
    const queryLang = resolveHwyMemberDirectoryQueryLang(query, req);
    return {
      success: true,
      data: [],
      ...(listCount.includeCount ? { count: 0 } : {}),
      meta: {
        page,
        pageSize,
        lang: queryLang,
        countMode: listCount.countMode,
        ...(listScopeLegacy ? { listScope: listScopeLegacy } : {}),
        listFetchPath: 'view',
        recordScopeEnforced: true,
      },
      source: {
        id: source.id,
        name: source.name,
        type: source.type,
      },
    };
  }
  const order = resolveHwyMemberDirectoryListOrder(
    query,
    allowedFilterFields,
    model.columns,
    ALLOW_SORT,
    listScopeLegacy,
  );
  const include = buildIncludeOptionsFromOperation(parseIncludeAliases(query, operation), operation, model);
  const segmentDef = listScopeLegacy
    ? findHwyMemberSegmentListByLegacyCode(listScopeLegacy)
    : undefined;
  const segmentSourceFields = segmentDef
    ? [...new Set(segmentDef.extraColumns.flatMap((columnKey) => {
      switch (columnKey) {
        case 'jobTypeAndPlace':
          return ['jobTypeCode', 'jobPlace'];
        case 'jobTypeCodeTitle':
          return ['jobTypeCode'];
        case 'educationLevelAndDetails':
          return ['educationLevelCode', 'educationBranch', 'educationEndYear'];
        case 'educationLevelCodeTitle':
          return ['educationLevelCode'];
        case 'registrationChannelCodeTitle':
          return ['registrationChannelCode'];
        case 'membershipStatusUpdatedOn':
          return ['membershipStatusUpdatedOn'];
        case 'trackingCode':
          return ['trackingCode'];
        case 'createdAt':
          return ['createdAt'];
        case 'educationBranch':
        case 'jobPlace':
        case 'educationEndYear':
          return [columnKey];
        case 'characterCodeTitle':
          return ['characterCode'];
        case 'mehaniUnionCodeTitle':
          return ['mehaniUnionCode'];
        case 'mehaniUnionDegreeCodeTitle':
          return ['mehaniUnionDegreeCode'];
        default:
          return [];
      }
    }))]
    : [];
  const rejectionListReadFields = isHwyMemberRejectionListLegacyScope(listScopeLegacy)
    ? [...HWY_MEMBER_REJECTION_LIST_DIRECTORY_READ_FIELDS]
    : [];
  const mergedReadable = readableAttributes
    ? [...new Set([
      ...readableAttributes.filter((field) => !LIST_OMIT_READ_FIELDS.has(field)),
      ...segmentSourceFields,
      ...rejectionListReadFields,
      ...HWY_MEMBER_DIRECTORY_LIST_FACE_CAPTION_ROW_FIELDS,
      'addrProvinceId',
      'addrMaktabId',
      'addrRegionId',
      'nakhebinMaktabId',
      'createdAt',
      'updatedAt',
    ])]
    : readableAttributes;
  const attributes = buildQueryAttributes(mergedReadable, operation.computedFields, model, sequelize.getDialect());
  const queryLang = resolveHwyMemberDirectoryQueryLang(query, req);

  const listCountResolved = resolveDataApiListIncludeCount(query, operation);
  const listCount = isQuickSearchList
    ? { ...listCountResolved, includeCount: false }
    : listCountResolved;
  const findOptions = {
    where,
    limit: pageSize,
    offset,
    attributes,
    order,
    include: include.length > 0 ? include : undefined,
    distinct: include.length > 0,
  };
  let plainRows: Record<string, unknown>[] | null = null;
  let totalCount: number | undefined;
  let listFetchPath: 'fast' | 'view' = 'view';
  const enrichmentDeps = await resolveFieldEnrichmentDeps(edgeModelId, operation);
  if (useListFastPath) {
    try {
      plainRows = await fetchMemberDirectoryListFastPath({
        sequelize,
        listScopeLegacy: listScopeLegacy!,
        attributes: mergedReadable ?? [],
        order,
        limit: pageSize,
        offset,
        search: listSearch,
        nakhebinJoinTasjilStateCode: joinTasjilRegisteredDbCode,
        montadheminInstituteIds,
        montadheminInstituteMatch,
      });
      listFetchPath = 'fast';
      if (listCount.includeCount) {
        try {
          totalCount = await countMemberDirectoryListFastPath({
            sequelize,
            listScopeLegacy: listScopeLegacy!,
            search: listSearch,
            nakhebinJoinTasjilStateCode: joinTasjilRegisteredDbCode,
            montadheminInstituteIds,
            montadheminInstituteMatch,
          });
        } catch (countError) {
          const message = countError instanceof Error ? countError.message : String(countError);
          console.warn('[hwy-member-directory-list] fast path count failed.', message);
        }
      }
    } catch (fastPathError) {
      plainRows = null;
      const message = fastPathError instanceof Error ? fastPathError.message : String(fastPathError);
      console.warn('[hwy-member-directory-list] fast path failed; using view.', message);
    }
  }
  if (plainRows === null) {
    if (listCount.includeCount) {
      const result = await ModelCtor.findAndCountAll(findOptions);
      plainRows = result.rows.map((row) => row.get({ plain: true }) as Record<string, unknown>);
      totalCount = result.count;
    } else {
      plainRows = (await ModelCtor.findAll(findOptions)).map(
        (row) => row.get({ plain: true }) as Record<string, unknown>,
      );
    }
  }
  const listFieldEnrichments = resolveMemberDirectoryListFieldEnrichments(
    listScopeLegacy,
    operation.enrichments ?? [],
  );
  const enrichedRows = await applyFieldEnrichments(
    plainRows,
    listFieldEnrichments,
    queryLang,
    enrichmentDeps,
  );
  await enrichHwyMemberDirectoryListRows(enrichedRows, queryLang, {
    includeElectoralDivisionPath: true,
    includeMemberInstitutesSummary: shouldEnrichMemberInstitutesSummaryForListScope(listScopeLegacy),
    includeListMembershipOnRegistrationFallback: resolveListMembershipOnRegistrationFallback(listScopeLegacy),
    includeImageFixRegistrationThumbs: shouldEnrichImageFixRegistrationThumbsForListScope(listScopeLegacy),
    includeListFaceAvatarsFromRegistration: shouldEnrichListFaceAvatarsFromRegistrationForListScope(listScopeLegacy),
    includeSingleViewStats: false,
    listScopeLegacy,
  });
  await applyHwyMemberIdentityFieldMasksToRows(sequelize, enrichedRows, session ?? null);
  await applyHwyMemberDirectoryListFaceCaptionUsernames(enrichedRows, { listScopeLegacy });
  if (isHwyMemberRejectionListLegacyScope(listScopeLegacy)) {
    await attachHwyMemberRejectionListParityFields(sequelize, enrichedRows, listScopeLegacy);
  }

  return {
    success: true,
    data: enrichedRows,
    ...(totalCount !== undefined ? { count: totalCount } : {}),
    meta: {
      page,
      pageSize,
      lang: queryLang,
      countMode: listCount.countMode,
      ...(listScopeLegacy ? { listScope: listScopeLegacy } : {}),
      listFetchPath,
    },
    source: {
      id: source.id,
      name: source.name,
      type: source.type,
    },
  };
}
