/** Legacy `V_NegoState` on HWY_Members_TarghinHistory_List. */
export type HwyMemberTarghinNegoStateFilter =
  | ''
  | 'in_nego'
  | 'in_nego_by_others'
  | 'in_nego_by_me'
  | 'not_in_nego';

export const HWY_MEMBER_TARGHIN_NEGO_STATE_FILTERS: HwyMemberTarghinNegoStateFilter[] = [
  '',
  'in_nego',
  'in_nego_by_others',
  'in_nego_by_me',
  'not_in_nego',
];

const LEGACY_NEGO_STATE_MAP: Record<string, HwyMemberTarghinNegoStateFilter> = {
  '': '',
  '1': 'in_nego',
  '2': 'in_nego_by_others',
  '3': 'in_nego_by_me',
  '0': 'not_in_nego',
  in_nego: 'in_nego',
  in_nego_by_others: 'in_nego_by_others',
  in_nego_by_me: 'in_nego_by_me',
  not_in_nego: 'not_in_nego',
};

export function parseHwyMemberTarghinNegoStateFilter(
  raw: string | null | undefined,
): HwyMemberTarghinNegoStateFilter {
  const key = String(raw ?? '').trim();
  return LEGACY_NEGO_STATE_MAP[key] ?? '';
}
