import { QueryTypes } from 'sequelize';



import type { HwyMemberDirectoryPatchInput } from '../../../domain/hwy/hwyMemberDirectoryPatch';

import { stripIdentityLockedPatchFields } from '../../../domain/hwy/hwyMemberIdentityFieldMask';
import { stripHwyMemberDossierNonEditablePatchFields } from '../../../domain/hwy/hwyMemberDossierEditPolicy';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

import { readControlPlaneProvider } from '../users/prismaHelpers';
import {
  emitHwyMemberDirectoryPatchHistory,
} from '../record-events/hwyMemberHistory';
import { invalidateHwyMemberDirectoryListCache } from './hwyMemberDirectoryListCache';
import {
  readHwyMemberLinkedUserId,
  syncHwyMemberDirectoryPatchToLinkedAccount,
} from './hwyMemberDirectoryPatchProfileSync';
import {
  HWY_MEMBER_HISTORY_SNAPSHOT_SQL,
  hwyMemberRowToHistorySnapshot,
} from '../record-events/hwyMemberHistoryFields';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';



const trimOptional = (value: string | null | undefined, max = 4000): string | null => {

  if (value == null) {

    return null;

  }

  const trimmed = value.trim();

  if (!trimmed) {

    return null;

  }

  return trimmed.length > max ? trimmed.slice(0, max) : trimmed;

};



const parseOptionalBigInt = (value: string | null | undefined): number | null => {

  const trimmed = trimOptional(value, 128);

  if (!trimmed || !/^\d+$/.test(trimmed)) {

    return null;

  }

  const parsed = Number(trimmed);

  return Number.isFinite(parsed) ? parsed : null;

};



const parseMemberId = (raw: string): number => {

  const trimmed = raw.trim();

  if (!/^\d+$/.test(trimmed)) {

    throw new Error('Member id is invalid.');

  }

  const id = Number(trimmed);

  if (!Number.isFinite(id) || id <= 0) {

    throw new Error('Member id is invalid.');

  }

  return id;

};



export async function patchHwyMemberDirectoryMember(

  memberIdRaw: string,

  input: HwyMemberDirectoryPatchInput,

  options?: { actorUserId?: number | null; session?: SessionScopeSnapshot | null },

): Promise<void> {

  if (readControlPlaneProvider() !== 'sqlserver') {

    throw new Error('Member dossier update requires SQL Server control plane.');

  }



  const memberId = parseMemberId(memberIdRaw);

  let patch = stripHwyMemberDossierNonEditablePatchFields(input);

  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();

  const beforeRows = await sequelize.query<Record<string, unknown>>(
    `SELECT ${HWY_MEMBER_HISTORY_SNAPSHOT_SQL} FROM dbo.hwy_members WHERE id = :id`,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  if (!beforeRows[0]) {
    throw new Error('Member not found.');
  }

  const policyRow = { ...beforeRows[0], id: memberId };
  await applyHwyMemberIdentityFieldMasksToRows(sequelize, [policyRow], options?.session ?? null, {
    attachIdentityFieldPolicy: true,
  });
  const identityPolicy = policyRow.identityFieldPolicy;
  if (identityPolicy?.lockedPatchFields.length) {
    patch = stripIdentityLockedPatchFields(patch, identityPolicy.lockedPatchFields);
    if (Object.keys(patch).length === 0) {
      throw new Error('No editable fields in this update.');
    }
  }

  const beforeSnapshot = hwyMemberRowToHistorySnapshot(beforeRows[0]);

  const now = new Date();



  const replacements = {

    id: memberId,

    first_name: trimOptional(patch.firstname, 500),

    family_name: trimOptional(patch.lastname, 500),

    father_name: trimOptional(patch.fathername, 500),

    grandfather_name: trimOptional(patch.grandfathername, 500),

    great_grandfather_name: trimOptional(patch.greatGrandfatherName, 500),

    mother_first_name: trimOptional(patch.motherFirstName, 500),

    mother_father_name: trimOptional(patch.motherFatherName, 500),

    mother_grandfather_name: trimOptional(patch.motherGrandfatherName, 500),

    nickname: trimOptional(patch.nickname, 500),

    birth_year: trimOptional(patch.birthYear, 4000),

    birth_month: trimOptional(patch.birthMonth, 4000),

    birth_day: trimOptional(patch.birthDay, 4000),

    gender_code: trimOptional(patch.genderCode, 1000),

    phone1: trimOptional(patch.phone1, 500),

    phone2: trimOptional(patch.phone2, 500),

    email: trimOptional(patch.email, 500),

    facebook_id: trimOptional(patch.facebookId, 4000),

    twitter_id: trimOptional(patch.twitterId, 4000),

    tiktok_id: trimOptional(patch.tiktokId, 4000),

    addr_province_id: trimOptional(patch.addrProvinceId, 128),

    addr_district_id: parseOptionalBigInt(patch.addrDistrictId),

    addr_subdistrict_id: parseOptionalBigInt(patch.addrSubdistrictId),

    addr_quarter_name: trimOptional(patch.addrQuarterName, 8000),

    addr_quarter_no: trimOptional(patch.addrQuarterNo, 4000),

    addr_alley_no: trimOptional(patch.addrAlleyNo, 4000),

    addr_house_no: trimOptional(patch.addrHouseNo, 4000),

    addr_nearest_landmark: trimOptional(patch.addrNearestLandmark, 8000),

    addr_most_important_place: trimOptional(patch.addrMostImportantPlace, 8000),

    addr_maktab_id: trimOptional(patch.addrMaktabId, 128),

    addr_region_id: trimOptional(patch.addrRegionId, 128),

    addr_circle_id: trimOptional(patch.addrCircleId, 128),

    education_level_code: trimOptional(patch.educationLevelCode, 1000),

    education_level_in_code: trimOptional(patch.educationLevelInCode, 1000),

    education_entry_year: trimOptional(patch.educationEntryYear, 4000),

    education_end_year: trimOptional(patch.educationEndYear, 4000),

    education_branch: trimOptional(patch.educationBranch, 8000),

    education_school: trimOptional(patch.educationSchool, 8000),

    education_university_code: trimOptional(patch.educationUniversityCode, 1000),

    education_university_faculty_code: trimOptional(patch.educationUniversityFacultyCode, 1000),

    job_type_code: trimOptional(patch.jobTypeCode, 1000),

    job_place: trimOptional(patch.jobPlace, 8000),

    updated_at: now,

  };



  try {
    await execHwyProcedure('hwy_member_directory_patch', {
      ...replacements,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('56300')) {
      throw new Error('Member not found.');
    }
    throw error;
  }

  const afterRows = await sequelize.query<Record<string, unknown>>(
    `SELECT ${HWY_MEMBER_HISTORY_SNAPSHOT_SQL} FROM dbo.hwy_members WHERE id = :id`,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  if (afterRows[0]) {
    await emitHwyMemberDirectoryPatchHistory({
      memberId,
      before: beforeSnapshot,
      after: hwyMemberRowToHistorySnapshot(afterRows[0]),
      actorUserId: options?.actorUserId ?? null,
    });
  }

  const linkedUserId = await readHwyMemberLinkedUserId(sequelize, memberId);
  if (linkedUserId != null) {
    await syncHwyMemberDirectoryPatchToLinkedAccount(sequelize, linkedUserId, patch, now);
  }

  await invalidateHwyMemberDirectoryListCache();
}

