import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;
let schemaReady = false;

const CORE_TABLES = [
  'hwy_activities',
  'hwy_activity_attendances',
  'hwy_courses',
  'hwy_course_attendances',
] as const;

const ddlPath = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../../../scripts/hwy-phase1/db/install/hwy_courses_activities.sqlserver.sql',
);

const coreCoursesActivitiesTablesPresent = async (): Promise<boolean> => {
  const sequelize = getControlPlaneSequelize();
  const inList = CORE_TABLES.map((name) => `N'${name}'`).join(', ');
  const rows = await sequelize.query<{ cnt: number | string }>(
    `SELECT COUNT(*) AS cnt FROM sys.tables WHERE name IN (${inList})`,
    { type: QueryTypes.SELECT },
  );
  return Number(rows[0]?.cnt ?? 0) === CORE_TABLES.length;
};

const applyCoursesActivitiesDdl = async (): Promise<void> => {
  const sequelize = getControlPlaneSequelize();
  const ddl = readFileSync(ddlPath, 'utf8');
  const batches = ddl
    .split(/^\s*GO\s*$/gim)
    .map((chunk) => chunk.trim())
    .filter(Boolean);
  for (const batch of batches) {
    await sequelize.query(batch, { type: QueryTypes.RAW });
  }
};

/** Idempotent DDL for Hawiety courses + activities ETL targets. */
export const ensureHwyCoursesActivitiesSchema = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }

  if (schemaReady) {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = (async () => {
      if (await coreCoursesActivitiesTablesPresent()) {
        schemaReady = true;
        return;
      }
      await applyCoursesActivitiesDdl();
      schemaReady = true;
    })().catch((error: unknown) => {
      ensurePromise = null;
      throw error;
    });
  }

  await ensurePromise;
};
