/** Every legacy filter key merged into list API bindings (scope-specific UI picks a subset). */
export const ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS = Object.keys(FIELD_DEFS) as HwyMemberDirectoryLegacyFilterFieldKey[];

export const getHwyMemberDirectoryLegacyFilterFieldDef = (
  key: HwyMemberDirectoryLegacyFilterFieldKey,
): HwyMemberDirectoryLegacyFilterFieldDef => FIELD_DEFS[key];

/** @deprecated Prefer `resolveHwyMemberDirectoryLegacyFilterFields` for UI. */
export const HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELDS: HwyMemberDirectoryLegacyFilterFieldDef[] =
  ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS.map(getHwyMemberDirectoryLegacyFilterFieldDef);

export const hwyMemberDirectoryLegacyFilterStorePath = (
  key: HwyMemberDirectoryLegacyFilterFieldKey,
): string => `${HWY_MEMBER_DIRECTORY_LEGACY_FILTER_STORE_PREFIX}.${key}`;

export const buildHwyMemberDirectoryLegacyFilterQueryParams = (): Record<string, string> => {
  const params: Record<string, string> = {};
  for (const key of ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS) {
    const field = getHwyMemberDirectoryLegacyFilterFieldDef(key);
    params[field.filterParam] = hwyMemberDirectoryLegacyFilterStorePath(field.key);
  }
  return params;
};

const normalizeListScopeToken = (raw: string | undefined): string => {
  const trimmed = raw?.trim() ?? '';
  if (trimmed.startsWith('static:')) {
    return trimmed.slice('static:'.length);
  }
  return trimmed;
};

export const isHwyMemberDirectoryListScopeQueryParams = (
  queryParams: Record<string, string> | undefined,
): boolean => {
  if (!queryParams) {
    return false;
  }
  const scope = normalizeListScopeToken(queryParams.listScope ?? queryParams.listDefLegacy);
  return scope.startsWith('HWY_Members_List');
};

export const shouldMergeHwyMemberDirectoryLegacyFilterQueryParams = (
  queryParams: Record<string, string> | undefined,
  endpoint?: string | null,
): boolean => {
  if (isHwyMemberDirectoryListScopeQueryParams(queryParams)) {
    return true;
  }
  const trimmedEndpoint = endpoint?.trim() ?? '';
  if (trimmedEndpoint.includes('/api/hwy/member-directory')) {
    return true;
  }
  if (!queryParams) {
    return false;
  }
  const searchPath = queryParams.search?.trim() ?? '';
  const dsRef = queryParams.listScope ?? queryParams.listDefLegacy ?? '';
  return searchPath.startsWith('gridToolbar.')
    && (Object.keys(queryParams).some((key) => key.startsWith('filter[membershipStatusCode]'))
      || dsRef.length > 0
      || Object.values(queryParams).some((path) => path.includes('hwymemberdirectory')));
};

export const mergeHwyMemberDirectoryLegacyFilterQueryParams = (
  queryParams: Record<string, string> | undefined,
  endpoint?: string | null,
): Record<string, string> => {
  if (!shouldMergeHwyMemberDirectoryLegacyFilterQueryParams(queryParams, endpoint)) {
    return queryParams ?? {};
  }
  return {
    ...(queryParams ?? {}),
    ...buildHwyMemberDirectoryLegacyFilterQueryParams(),
    [HWY_MEMBER_DIRECTORY_JOIN_TASJIL_REGISTERED_FILTER_QUERY_PARAM]:
      HWY_MEMBER_DIRECTORY_JOIN_TASJIL_REGISTERED_FILTER_STORE_PATH,
    [HWY_MONTADHEMIN_INSTITUTE_FILTER_QUERY_PARAM]: HWY_MONTADHEMIN_INSTITUTE_FILTER_STORE_PATH,
    [HWY_MONTADHEMIN_INSTITUTE_MATCH_QUERY_PARAM]: HWY_MONTADHEMIN_INSTITUTE_MATCH_STORE_PATH,
  };
};

export const buildClearHwyMemberDirectoryLegacyFilterStorePatches = (): Record<string, string> => ({
  ...Object.fromEntries(
    ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS.map((key) => [
      hwyMemberDirectoryLegacyFilterStorePath(key),
      '',
    ]),
  ),
  'gridToolbar.filters.membershipStatusCode': '',
  [HWY_MEMBER_DIRECTORY_JOIN_TASJIL_REGISTERED_FILTER_STORE_PATH]: '',
  [HWY_MONTADHEMIN_INSTITUTE_FILTER_STORE_PATH]: '',
  [HWY_MONTADHEMIN_INSTITUTE_MATCH_STORE_PATH]: '',
});
