import {
  ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS,
  getHwyMemberDirectoryLegacyFilterFieldDef,
  type HwyMemberDirectoryLegacyFilterFieldKey,
} from './hwyMemberDirectoryLegacyFilterModel';

export const buildHwyMemberDirectoryLegacyFilterCultureKeysEn = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const fieldKey of ALL_HWY_MEMBER_DIRECTORY_LEGACY_FILTER_FIELD_KEYS) {
    const def = getHwyMemberDirectoryLegacyFilterFieldDef(fieldKey);
    keys[def.labelKey] = def.labelFallback;
  }
  return {
    ...keys,
    'hwy.members.legacyFilter.usernameOrTrackingCode': 'Username / tracking code',
    'hwy.members.legacyFilter.membershipStatus': 'Membership status',
    'hwy.members.legacyFilter.joinTasjilState': 'Registration status',
    'hwy.members.legacyFilter.joinTasjilRegistered': 'Registered',
    'hwy.members.legacyFilter.joinTasjilUnregistered': 'Not registered',
  };
};

