/** Sync Arabic iq titles for Security Clearance Answer from legacy HWY_BaseInformation. */
export const syncHwySecurityClearanceAnswerVocabFromLegacy = async (
  legacy: ConnectionPool,
): Promise<number> => {
  const legacyRows = await loadLegacyBaseInfoCategoryRows(
    legacy,
    LEGACY_SECURITY_CLEARANCE_ANSWER_PARENT_ID,
  );
  if (legacyRows.length === 0) {
    return 0;
  }

  const entries: Array<{ baseInfoId: string; locales: { iq: { title: string } } }> = [];
  const mappedIds = new Set(Object.keys(LEGACY_CLEARANCE_ANSWER_TO_SHORT).map(Number));

  for (const row of legacyRows) {
    const legacyId = Number(row.Id);
    const shortName = LEGACY_CLEARANCE_ANSWER_TO_SHORT[legacyId];
    if (!shortName) {
      continue;
    }
    const arabicTitle = resolveHwySecurityClearanceAnswerIqTitle(shortName, String(row.Title ?? ''));
    if (!arabicTitle) {
      continue;
    }
    const baseInfoId = await findHwyBaseInfoItemId(HWY_SECURITY_CLEARANCE_ANSWER_CATEGORY, shortName);
    entries.push({
      baseInfoId,
      locales: { iq: { title: arabicTitle } },
    });
  }

  const categoryId = await findHwyBaseInfoCategoryId(HWY_SECURITY_CLEARANCE_ANSWER_CATEGORY);
  const platformItems = await prisma().baseInfo.findMany({
    where: { parentId: categoryId },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: { id: true },
  });

  for (let index = 0; index < legacyRows.length; index += 1) {
    const legacyRow = legacyRows[index];
    const legacyId = Number(legacyRow.Id);
    if (mappedIds.has(legacyId)) {
      continue;
    }
    const arabicTitle = String(legacyRow.Title ?? '').trim();
    const platformItem = platformItems[index];
    if (!arabicTitle || !platformItem) {
      continue;
    }
    entries.push({
      baseInfoId: platformItem.id,
      locales: { iq: { title: arabicTitle } },
    });
  }

  if (entries.length === 0) {
    return 0;
  }
  persistBaseInfoLocaleTextsBulk(entries);
  return entries.length;
};

