/** Legacy member `NakhebJoinTypeId` uses 111801…111805; HWY_BaseInformation leaves are 11181…11185. */
export const resolveLegacyNakhebJoinTypeLeafId = (
  raw: number | null | undefined,
): number | null => {
  if (raw == null || raw <= 0) {
    return null;
  }
  if (raw >= 111801 && raw < 111900) {
    return LEGACY_NAKHEBIN_LINK_TYPE_PARENT_ID + (raw - 111800);
  }
  return raw;
};

/** ETL: map legacy nakhebin join type id → platform code, or NULL when unknown. */
export const resolveEtlNakhebinLinkTypeCode = (
  legacyId: number | null | undefined,
  nakhebinLinkTypeByLegacyId: Map<number, string>,
): string | null => {
  const leafId = resolveLegacyNakhebJoinTypeLeafId(legacyId);
  if (leafId == null) {
    return null;
  }
  return nakhebinLinkTypeByLegacyId.get(leafId) ?? null;
};

/** Remove retired membership status leaves (e.g. pre_call_center / legacy 10858). */
export const pruneHwyMembershipStatusBaseInfoLeaves = async (): Promise<number> => {
  const categoryId = await findHwyBaseInfoCategoryId(HWY_MEMBERSHIP_STATUS_CATEGORY);
  const keepShortNames = new Set(Object.values(LEGACY_MEMBERSHIP_STATUS_TO_SHORT));
  const retiredShortNames = new Set<string>(RETIRED_HWY_MEMBERSHIP_STATUS_SHORT_NAMES);

  const children = await prisma().baseInfo.findMany({
    where: { parentId: categoryId },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: { id: true, shortName: true },
  });

  const keeperIdByShortName = new Map<string, string>();
  const deleteIds: string[] = [];

  for (const child of children) {
    const shortName = String(child.shortName ?? '').trim();
    const shouldKeep = shortName && keepShortNames.has(shortName);
    if (shouldKeep) {
      const existing = keeperIdByShortName.get(shortName);
      if (!existing) {
        keeperIdByShortName.set(shortName, child.id);
      } else {
        deleteIds.push(child.id);
      }
      continue;
    }
    if (!shortName || retiredShortNames.has(shortName) || !keepShortNames.has(shortName)) {
      deleteIds.push(child.id);
    }
  }

  if (deleteIds.length === 0) {
    return 0;
  }

  await deleteBaseInfoCultureTextForIds(deleteIds);
  for (const id of deleteIds) {
    await deleteBaseInfoNode(id);
  }
  invalidateBaseInfoOptionsCache();
  return deleteIds.length;
};

/** Remove duplicate / retired / inactive tasjil leaves — category keeps only active legacy pair. */
export const pruneHwyTasjilStateBaseInfoLeaves = async (
  clearHwyColumnRefs?: (baseInfoId: string) => Promise<void>,
): Promise<number> => {
  const categoryId = await findHwyBaseInfoCategoryId(HWY_NAKHEBIN_JOIN_TASJIL_STATE_CATEGORY);
  const keepShortNames = new Set(Object.values(LEGACY_TASJIL_STATE_TO_SHORT));
  const retiredShortNames = new Set<string>(RETIRED_HWY_TASJIL_STATE_SHORT_NAMES);

  const children = await prisma().baseInfo.findMany({
    where: { parentId: categoryId },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: { id: true, shortName: true },
  });

  const keeperIdByShortName = new Map<string, string>();
  const deleteIds: string[] = [];

  for (const child of children) {
    const shortName = String(child.shortName ?? '').trim();
    const shouldKeep = shortName && keepShortNames.has(shortName);
    if (shouldKeep) {
      const existing = keeperIdByShortName.get(shortName);
      if (!existing) {
        keeperIdByShortName.set(shortName, child.id);
      } else {
        deleteIds.push(child.id);
      }
      continue;
    }
    if (!shortName || retiredShortNames.has(shortName) || !keepShortNames.has(shortName)) {
      deleteIds.push(child.id);
    }
  }

  if (deleteIds.length === 0) {
    return 0;
  }

  if (clearHwyColumnRefs) {
    for (const id of deleteIds) {
      await clearHwyColumnRefs(id);
    }
  }

  await deleteBaseInfoCultureTextForIds(deleteIds);
  for (const id of deleteIds) {
    await deleteBaseInfoNode(id);
  }
  invalidateBaseInfoOptionsCache();
  return deleteIds.length;
};

/** Sync Arabic title + view order for the two active tasjil leaves. */
export const reconcileHwyTasjilStateFromLegacy = async (
  legacy: ConnectionPool,
  actorId: number | null = null,
): Promise<number> => {
  const legacyRows = await loadLegacyBaseInfoCategoryRows(legacy, LEGACY_TASJIL_STATE_PARENT_ID);
  const legacyById = new Map(legacyRows.map((row) => [Number(row.Id), row]));
  const actor = actorId !== null && Number.isFinite(actorId) ? BigInt(actorId) : null;
  let updated = 0;

  for (const [legacyIdStr, shortName] of Object.entries(LEGACY_TASJIL_STATE_TO_SHORT)) {
    const legacyId = Number(legacyIdStr);
    const row = legacyById.get(legacyId);
    const platformId = await findHwyBaseInfoItemId(HWY_NAKHEBIN_JOIN_TASJIL_STATE_CATEGORY, shortName);
    const legacyTitle = String(row?.Title ?? '').trim();
    const viewOrder = row?.ViewOrder != null ? Number(row.ViewOrder) : null;

    await updateBaseInfoNode([
      legacyTitle || shortName,
      shortName,
      viewOrder,
      null,
      null,
      viewOrder,
      true,
      null,
      null,
      undefined,
      actor,
      platformId,
    ]);
    updated += 1;
  }

  return updated;
};
