import { persistBaseInfoLocaleTextsBulk } from '../base-info/baseInfoCultureTranslationStore';
import { upsertBaseInfoCultureTextTitles } from '../base-info/baseInfoCultureTextSequelizeModel';
import { findHwyBaseInfoCategoryId, seedHwyBaseInfo } from '../../../../scripts/hwy-phase1/seed/seedHwyBaseInfo';
import { invalidateBaseInfoOptionsCache } from '../../services/baseInfoOptionsCache';
import {
  HWY_ACTIVITY_STATUS_CATEGORY,
  HWY_ACTIVITY_STATUS_SEED_ROWS,
  HWY_COURSE_STATUS_CATEGORY,
  HWY_COURSE_STATUS_SEED_ROWS,
  type HwyCoursesActivitiesStatusSeedRow,
} from '../../../domain/hwy/hwyCoursesActivitiesStatusCatalog';
import { prisma, readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;

/** Dev/hot-reload: re-apply iq status titles after catalog edits. */
export const resetHwyCoursesActivitiesStatusVocabEnsure = (): void => {
  ensurePromise = null;
};

const resolveCategoryId = async (categoryTitle: string): Promise<string> => {
  try {
    return await findHwyBaseInfoCategoryId(categoryTitle);
  } catch {
    await seedHwyBaseInfo(null);
    return findHwyBaseInfoCategoryId(categoryTitle);
  }
};

const upsertStatusRows = async (
  categoryTitle: string,
  rows: HwyCoursesActivitiesStatusSeedRow[],
): Promise<void> => {
  const categoryId = await resolveCategoryId(categoryTitle);
  const localeEntries: Array<{ baseInfoId: string; locales: { iq: { title: string } } }> = [];

  for (const row of rows) {
    const shortName = `legacy_status_${row.id}`;
    await prisma().baseInfo.upsert({
      where: { id: row.id },
      create: {
        id: row.id,
        parentId: categoryId,
        title: row.canonicalTitle,
        shortName,
        viewOrder: row.viewOrder,
        value: row.viewOrder,
        isActive: true,
      },
      update: {
        parentId: categoryId,
        title: row.canonicalTitle,
        shortName,
        viewOrder: row.viewOrder,
        value: row.viewOrder,
        isActive: true,
      },
    });
    localeEntries.push({ baseInfoId: row.id, locales: { iq: { title: row.iqTitle } } });
  }

  if (localeEntries.length) {
    persistBaseInfoLocaleTextsBulk(localeEntries);
    const sqlMirrorEntries = rows
      .map((row) => {
        const override = row.iqTitle.trim();
        const canonical = row.canonicalTitle.trim();
        if (!override || override === canonical) {
          return null;
        }
        return { baseInfoId: row.id, cultureId: 'iq' as const, title: override };
      })
      .filter((entry): entry is { baseInfoId: string; cultureId: 'iq'; title: string } => entry != null);
    if (sqlMirrorEntries.length) {
      await upsertBaseInfoCultureTextTitles(sqlMirrorEntries);
    }
  }
};

/** Idempotent install of legacy Dorat/Nashatat status titles into `base_info` (parity with legacy StatusId_Title joins). */
export const ensureHwyCoursesActivitiesStatusVocab = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }
  if (!ensurePromise) {
    ensurePromise = (async () => {
      await upsertStatusRows(HWY_ACTIVITY_STATUS_CATEGORY, HWY_ACTIVITY_STATUS_SEED_ROWS);
      await upsertStatusRows(HWY_COURSE_STATUS_CATEGORY, HWY_COURSE_STATUS_SEED_ROWS);
      invalidateBaseInfoOptionsCache();
    })().catch((error: unknown) => {
      ensurePromise = null;
      throw error;
    });
  }
  await ensurePromise;
};
