import { apiGet, resolveApiMutationErrorMessage } from '../../shared/api/client';
import { parseBaseInfoSemanticContent } from '../../shared/lib/baseInfoSemanticContent';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';

/** Legacy Base Info parent for targhin request reasons (`getBaseInformationByParent(212110)`). */
export const HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID = '212110';

export const HWY_MEMBER_TARGHIN_REQUEST_NOTE_MIN_LENGTH = 20;
export const HWY_MEMBER_TARGHIN_REQUEST_NOTE_MAX_LENGTH = 1024;

export type HwyMemberTarghinRequestReasonOption = {
  value: string;
  label: string;
  /** Shown to the user before they write the note. */
  userGuidance?: string;
  /** LLM rubric for semantic validation (not shown to end users). */
  semanticRubric?: string;
  /** @deprecated Use userGuidance — kept for callers still reading validationHint. */
  validationHint?: string;
};

export type HwyMemberTarghinRequestReasonOptionsResponse = {
  success?: boolean;
  data?: HwyMemberTarghinRequestReasonOption[];
};

export function buildHwyMemberTarghinRequestReasonOptionsPath(cultureId?: string | null): string {
  const lang = resolveHwyMemberDirectoryDetailLang(cultureId);
  return `/api/hwy/member-directory/targhin-request-reasons?lang=${encodeURIComponent(lang)}`;
}

/** @deprecated Use parseBaseInfoSemanticContent via API mapping. */
export function resolveHwyMemberTarghinRequestReasonValidationHint(
  rawNote: string | null | undefined,
): string {
  return parseBaseInfoSemanticContent(rawNote, null).userGuidance;
}

export function mapTarghinReasonNoteToSemanticFields(
  note: string | null | undefined,
  metadata: string | null | undefined,
): Pick<HwyMemberTarghinRequestReasonOption, 'userGuidance' | 'semanticRubric' | 'validationHint'> {
  const parsed = parseBaseInfoSemanticContent(note, metadata);
  const userGuidance = parsed.userGuidance || undefined;
  const semanticRubric = parsed.semanticRubric || undefined;
  return {
    userGuidance,
    semanticRubric,
    validationHint: userGuidance,
  };
}

export async function fetchHwyMemberTarghinRequestReasonOptions(
  cultureId?: string | null,
): Promise<HwyMemberTarghinRequestReasonOption[]> {
  const { data, response } = await apiGet<HwyMemberTarghinRequestReasonOptionsResponse>(
    buildHwyMemberTarghinRequestReasonOptionsPath(cultureId),
  );
  if (!response.ok) {
    throw new Error(
      resolveApiMutationErrorMessage(data, `Could not load targhin request reasons. (HTTP ${response.status})`),
    );
  }
  return Array.isArray(data?.data) ? data.data : [];
}
