import {

  HWY_SELF_REGISTRATION_LEGACY_REFERRER_RELATION_PARENT_ID,

  type HwySelfRegistrationReferrerRelationOption,

} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationReferrerRelation';

import {

  HWY_SELF_REGISTRATION_REFERRER_RELATION_LEGACY_FALLBACK,

  resolveReferrerRelationCultureLabelKey,

} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationReferrerRelationCatalog';

import { buildMergedCultureBundle } from '../base-info/baseInfoCultureTranslationStore';

import { listLegacyHwyBaseInformationByParent } from './hwyLegacyBaseInformationReader';



const normalizeCultureId = (cultureId: string | null | undefined): string => {

  const trimmed = String(cultureId ?? '').trim();

  return trimmed || 'iq';

};



const resolveCultureLabel = (

  cultureLabelKey: string,

  bundle: Record<string, string>,

): string => {

  const fromBundle = bundle[cultureLabelKey]?.trim();

  if (fromBundle) {

    return fromBundle;

  }

  return cultureLabelKey;

};



const legacyRowsToOptions = (

  rows: Awaited<ReturnType<typeof listLegacyHwyBaseInformationByParent>>,

  bundle: Record<string, string>,

): HwySelfRegistrationReferrerRelationOption[] => (

  rows

    .map((row) => {

      const legacyId = String(row.id);

      const cultureKey = resolveReferrerRelationCultureLabelKey(legacyId);

      const labelFromCulture = cultureKey ? resolveCultureLabel(cultureKey, bundle) : '';

      const labelFromLegacy = row.title.trim();

      const label = (labelFromCulture && !labelFromCulture.startsWith('hwy.'))

        ? labelFromCulture

        : (labelFromLegacy || labelFromCulture);

      return { legacyId, label };

    })

    .filter((item) => item.legacyId && item.label && !item.label.startsWith('hwy.'))

);



const fallbackCatalogToOptions = (

  bundle: Record<string, string>,

): HwySelfRegistrationReferrerRelationOption[] => (

  HWY_SELF_REGISTRATION_REFERRER_RELATION_LEGACY_FALLBACK.map((row) => ({

    legacyId: row.legacyId,

    label: resolveCultureLabel(row.cultureLabelKey, bundle),

  })).filter((item) => item.label && !item.label.startsWith('hwy.'))

);



export const listHwySelfRegistrationReferrerRelations = async (

  cultureId: string | null | undefined,

): Promise<HwySelfRegistrationReferrerRelationOption[]> => {

  const resolvedCultureId = normalizeCultureId(cultureId);

  const bundle = buildMergedCultureBundle(resolvedCultureId);



  const legacyRows = await listLegacyHwyBaseInformationByParent(

    HWY_SELF_REGISTRATION_LEGACY_REFERRER_RELATION_PARENT_ID,

  );



  let options: HwySelfRegistrationReferrerRelationOption[];

  if (legacyRows.length > 0) {

    options = legacyRowsToOptions(legacyRows, bundle);

  } else {

    options = fallbackCatalogToOptions(bundle);

  }



  if (options.length === 0) {

    options = fallbackCatalogToOptions(bundle);

  }



  return options;

};


