import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;

export const resetHwyMemberPhoneRequestsSchemaState = (): void => {
  ensurePromise = null;
};

const installDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../../../scripts/hwy-phase1/db/install',
);

export async function ensureHwyMemberPhoneRequestsSchema(): Promise<void> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }
  if (!ensurePromise) {
    ensurePromise = (async () => {
      const sequelize = getControlPlaneSequelize();
      const ddl = readFileSync(path.join(installDir, 'hwy_member_phone_requests.sqlserver.sql'), 'utf8');
      const batches = ddl
        .split(/^\s*GO\s*$/gim)
        .map((chunk) => chunk.trim())
        .filter(Boolean);
      for (const batch of batches) {
        await sequelize.query(batch);
      }
    })();
  }
  await ensurePromise;
}
