import { QueryTypes } from 'sequelize';

import {
  HWY_VOTER_CARD_FRONT_TYPE_BASE_INFO_CATEGORY,
  isHwyVoterCardFrontTypeShortName,
  type HwyVoterCardFrontTypeShortName,
} from '../../../domain/hwy/hwyMemberImageFixVoterCardType';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { invalidateHwyMemberDirectoryListCache } from './hwyMemberDirectoryListCache';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';
import { ensureHwyMemberImageFixEditorBaseInfo } from './ensureHwyMemberImageFixEditorBaseInfo';
import { ensureHwyMemberImageFixEditorSchema } from './ensureHwyMemberImageFixEditorSchema';
import { coerceSqlServerBitField } from './coerceSqlServerBitField';

export type HwyMemberImageFixEditorFields = {
  nakhebCardFrontCheck: boolean;
  nakhebCardFrontTypeCode: string | null;
  nakhebCardFrontTypeShortName: HwyVoterCardFrontTypeShortName | null;
};

type MemberRow = {
  nakheb_card_front_check: boolean | number | null;
  nakheb_card_front_type_code: string | null;
};

const resolveShortNameFromTypeCode = async (
  typeCode: string | null | undefined,
): Promise<HwyVoterCardFrontTypeShortName | null> => {
  const trimmed = String(typeCode ?? '').trim();
  if (!trimmed) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ short_name: string | null }>(
    `SELECT TOP (1) short_name FROM dbo.base_info WHERE id = :id`,
    { replacements: { id: trimmed }, type: QueryTypes.SELECT },
  );
  const shortName = String(rows[0]?.short_name ?? '').trim();
  return isHwyVoterCardFrontTypeShortName(shortName) ? shortName : null;
};

export const loadHwyMemberImageFixEditorFields = async (
  memberId: number,
): Promise<HwyMemberImageFixEditorFields> => {
  await ensureHwyMemberImageFixEditorSchema();
  await ensureHwyMemberImageFixEditorBaseInfo();
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<MemberRow>(
    `
    SELECT
      nakheb_card_front_check,
      nakheb_card_front_type_code
    FROM dbo.hwy_members
    WHERE id = :memberId
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  const row = rows[0];
  if (!row) {
    throw new Error('Member not found.');
  }
  const typeCode = row.nakheb_card_front_type_code?.trim() || null;
  return {
    nakhebCardFrontCheck: coerceSqlServerBitField(row.nakheb_card_front_check),
    nakhebCardFrontTypeCode: typeCode,
    nakhebCardFrontTypeShortName: await resolveShortNameFromTypeCode(typeCode),
  };
};

export const patchHwyMemberImageFixEditorFields = async (input: {
  memberId: number;
  nakhebCardFrontCheck?: boolean;
  voterCardFrontTypeShortName?: HwyVoterCardFrontTypeShortName | null;
  actorUserId: number | null;
}): Promise<void> => {
  await ensureHwyMemberImageFixEditorSchema();
  await ensureHwyMemberImageFixEditorBaseInfo();
  const sequelize = getControlPlaneSequelize();
  const sets: string[] = ['updated_at = SYSUTCDATETIME()'];
  const replacements: Record<string, unknown> = { memberId: input.memberId };

  if (input.nakhebCardFrontCheck !== undefined) {
    sets.push('nakheb_card_front_check = :nakhebCardFrontCheck');
    replacements.nakhebCardFrontCheck = input.nakhebCardFrontCheck ? 1 : 0;
  }

  if (input.voterCardFrontTypeShortName !== undefined) {
    if (input.voterCardFrontTypeShortName === null) {
      sets.push('nakheb_card_front_type_code = NULL');
    } else {
      const typeCode = await tryFindHwyBaseInfoItemIdByShortName(
        HWY_VOTER_CARD_FRONT_TYPE_BASE_INFO_CATEGORY,
        input.voterCardFrontTypeShortName,
      );
      if (!typeCode) {
        throw new Error(
          `Voter card type "${input.voterCardFrontTypeShortName}" is not configured in Base Info.`,
        );
      }
      sets.push('nakheb_card_front_type_code = :nakhebCardFrontTypeCode');
      replacements.nakhebCardFrontTypeCode = typeCode;
    }
  }

  if (input.actorUserId != null && Number.isFinite(input.actorUserId)) {
    sets.push('updated_by = :updatedBy');
    replacements.updatedBy = input.actorUserId;
  }

  if (sets.length === 1) {
    return;
  }

  await sequelize.query(
    `
    UPDATE dbo.hwy_members
    SET ${sets.join(', ')}
    WHERE id = :memberId
    `,
    { replacements, type: QueryTypes.UPDATE },
  );
  await invalidateHwyMemberDirectoryListCache();
};
