/** Per-field capture policy for Hawiety member submissions (legacy Nb* / selfie parity). */
export type HwySubmissionMetadataMode = 'off' | 'record' | 'require';

export type HwySubmissionMetadataFieldId =
  | 'nbLocationLat'
  | 'nbLocationLon'
  | 'nbDeviceOs'
  | 'nbDeviceId'
  | 'nbDeviceDatetime'
  | 'selfie';

export type HwySubmissionMetadataFieldSpec = {
  id: HwySubmissionMetadataFieldId;
  mode: HwySubmissionMetadataMode;
};

export type HwySubmissionMetadataPayload = {
  nbLocationLat?: string | null;
  nbLocationLon?: string | null;
  nbDeviceOs?: string | null;
  nbDeviceId?: string | null;
  nbDeviceDatetime?: string | null;
};

export type ParsedHwySubmissionMetadata = {
  nbLocationLat: string | null;
  nbLocationLon: string | null;
  nbDeviceOs: string | null;
  nbDeviceId: string | null;
  nbDeviceDatetime: string | null;
};

const trim = (value: unknown): string => String(value ?? '').trim();

const labelFor = (id: HwySubmissionMetadataFieldId): string => {
  switch (id) {
    case 'nbLocationLat':
      return 'Location latitude';
    case 'nbLocationLon':
      return 'Location longitude';
    case 'nbDeviceOs':
      return 'Device OS';
    case 'nbDeviceId':
      return 'Device id';
    case 'nbDeviceDatetime':
      return 'Device date/time';
    case 'selfie':
      return 'Selfie image';
    default:
      return id;
  }
};

export class HwySubmissionMetadataValidationError extends Error {
  readonly fieldId: HwySubmissionMetadataFieldId | null;

  constructor(message: string, fieldId: HwySubmissionMetadataFieldId | null = null) {
    super(message);
    this.name = 'HwySubmissionMetadataValidationError';
    this.fieldId = fieldId;
  }
}

export const parseHwySubmissionMetadataPayload = (
  raw: HwySubmissionMetadataPayload | Record<string, unknown>,
): ParsedHwySubmissionMetadata => ({
  nbLocationLat: trim(raw.nbLocationLat) || null,
  nbLocationLon: trim(raw.nbLocationLon) || null,
  nbDeviceOs: trim(raw.nbDeviceOs) || null,
  nbDeviceId: trim(raw.nbDeviceId) || null,
  nbDeviceDatetime: trim(raw.nbDeviceDatetime) || null,
});

export const assertHwySubmissionMetadata = (input: {
  fields: HwySubmissionMetadataFieldSpec[];
  payload: ParsedHwySubmissionMetadata;
  hasSelfie: boolean;
}): void => {
  const valueFor = (id: HwySubmissionMetadataFieldId): string | null => {
    switch (id) {
      case 'nbLocationLat':
        return input.payload.nbLocationLat;
      case 'nbLocationLon':
        return input.payload.nbLocationLon;
      case 'nbDeviceOs':
        return input.payload.nbDeviceOs;
      case 'nbDeviceId':
        return input.payload.nbDeviceId;
      case 'nbDeviceDatetime':
        return input.payload.nbDeviceDatetime;
      case 'selfie':
        return input.hasSelfie ? '1' : null;
      default:
        return null;
    }
  };

  for (const field of input.fields) {
    if (field.mode !== 'require') {
      continue;
    }
    const value = valueFor(field.id);
    if (!value) {
      throw new HwySubmissionMetadataValidationError(
        `${labelFor(field.id)} is required.`,
        field.id,
      );
    }
  }
};

/** API contract: which fields the client must send (legacy HWY_Members_Nashatat CreateBySelf + central Tajammoat). */
export type HwySubmissionMetadataSpecResponse = {
  fields: HwySubmissionMetadataFieldSpec[];
};
