import type { HwyMemberDossierLabels } from './hwyMemberDossierLabels';
import type { HwyMemberDossierSection } from './hwyMemberDossierRoute';

/** Profile rail sections aligned with legacy member dossier (S4 satellites + CC flows). */
export type HwyMemberDossierProfileNavId =
  | 'files'
  | 'notes'
  | 'securityProfile'
  | 'institutes'
  | 'nakhebin'
  | 'kasb'
  | 'changeLog'
  | 'targhin'
  | 'activities'
  | 'courses'
  | 'similarMembers';

export type HwyMemberDossierProfileNavItem = {
  id: HwyMemberDossierProfileNavId;
  labelProp: keyof Pick<
    HwyMemberDossierLabels,
    | 'navFiles'
    | 'navNotes'
    | 'navSecurity'
    | 'navInstitutes'
    | 'navNakhebin'
    | 'navKasb'
    | 'navChangeLog'
    | 'navTarghin'
    | 'navActivities'
    | 'navCourses'
    | 'navSimilar'
  >;
  availability: 'routed' | 'stub';
  section?: HwyMemberDossierSection;
};

export const HWY_MEMBER_DOSSIER_PROFILE_NAV_ITEMS: readonly HwyMemberDossierProfileNavItem[] = [
  { id: 'files', labelProp: 'navFiles', availability: 'routed', section: 'files' },
  { id: 'kasb', labelProp: 'navKasb', availability: 'routed', section: 'kasb' },
  { id: 'notes', labelProp: 'navNotes', availability: 'routed', section: 'notes' },
  { id: 'securityProfile', labelProp: 'navSecurity', availability: 'routed', section: 'securityProfile' },
  { id: 'institutes', labelProp: 'navInstitutes', availability: 'routed', section: 'institutes' },
  { id: 'nakhebin', labelProp: 'navNakhebin', availability: 'routed', section: 'nakhebin' },
  { id: 'activities', labelProp: 'navActivities', availability: 'routed', section: 'activities' },
  { id: 'courses', labelProp: 'navCourses', availability: 'routed', section: 'courses' },
  { id: 'targhin', labelProp: 'navTarghin', availability: 'routed', section: 'targhin' },
  { id: 'similarMembers', labelProp: 'navSimilar', availability: 'routed', section: 'similarMembers' },
  { id: 'changeLog', labelProp: 'navChangeLog', availability: 'routed', section: 'changeLog' },
];

export const HWY_MEMBER_DOSSIER_PROFILE_NAV_CHANGE_LOG_ID = 'changeLog' satisfies HwyMemberDossierProfileNavId;

export function splitHwyMemberDossierProfileNavItems(items: readonly HwyMemberDossierProfileNavItem[]): {
  main: HwyMemberDossierProfileNavItem[];
  changeLog: HwyMemberDossierProfileNavItem | null;
} {
  const changeLog = items.find((item) => item.id === HWY_MEMBER_DOSSIER_PROFILE_NAV_CHANGE_LOG_ID) ?? null;
  const main = items.filter((item) => item.id !== HWY_MEMBER_DOSSIER_PROFILE_NAV_CHANGE_LOG_ID);
  return { main, changeLog };
}

export function resolveHwyMemberDossierProfileNavLabel(
  labels: HwyMemberDossierLabels,
  item: HwyMemberDossierProfileNavItem,
): string {
  return labels[item.labelProp];
}

export function resolveHwyMemberDossierProfileNavActiveId(
  section?: HwyMemberDossierSection | null,
): HwyMemberDossierProfileNavId | null {
  if (section === 'files') {
    return 'files';
  }
  if (section === 'institutes') {
    return 'institutes';
  }
  if (section === 'nakhebin') {
    return 'nakhebin';
  }
  if (section === 'kasb') {
    return 'kasb';
  }
  if (section === 'notes') {
    return 'notes';
  }
  if (section === 'securityProfile') {
    return 'securityProfile';
  }
  if (section === 'similarMembers') {
    return 'similarMembers';
  }
  if (section === 'changeLog') {
    return 'changeLog';
  }
  if (section === 'targhin') {
    return 'targhin';
  }
  if (section === 'activities') {
    return 'activities';
  }
  if (section === 'courses') {
    return 'courses';
  }
  return null;
}

export function resolveHwyMemberDossierSectionForNavId(
  navId: HwyMemberDossierProfileNavId,
): HwyMemberDossierSection | null {
  const item = HWY_MEMBER_DOSSIER_PROFILE_NAV_ITEMS.find((entry) => entry.id === navId);
  return item?.section ?? null;
}
