import sql from 'mssql';
import { QueryTypes } from 'sequelize';

import {
  buildHwyMemberPersonDisplayNameFromParts,
} from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { resolveHwyMemberPrimaryKey } from './hwyMemberDossierSatellites.service';
import { enrichMemberRowAvatarsFromRegistrationPhotos } from './hwyMemberDirectoryListImageFixThumbs';
import { getLegacyHwyReadPool } from './legacyHwyReadPool';

export type HwyMembershipReferrerLookupRow = {
  memberId: string;
  username: string;
  firstname: string | null;
  fathername: string | null;
  grandfathername: string | null;
  lastname: string | null;
  displayFullName: string;
  genderCode: string | null;
  avatarUrl: string | null;
};

const mapRow = (row: {
  id: number;
  username: string | null;
  firstname: string | null;
  fathername: string | null;
  grandfathername: string | null;
  lastname: string | null;
  genderCode?: string | null;
  avatarUrl?: string | null;
}): HwyMembershipReferrerLookupRow | null => {
  const memberId = String(row.id ?? '').trim();
  if (!memberId) {
    return null;
  }
  const username = String(row.username ?? '').trim() || memberId;
  const displayFullName = buildHwyMemberPersonDisplayNameFromParts({
    firstname: row.firstname,
    fathername: row.fathername,
    grandfathername: row.grandfathername,
    lastname: row.lastname,
  }).trim() || username;
  return {
    memberId,
    username,
    firstname: row.firstname?.trim() || null,
    fathername: row.fathername?.trim() || null,
    grandfathername: row.grandfathername?.trim() || null,
    lastname: row.lastname?.trim() || null,
    displayFullName,
    genderCode: row.genderCode?.trim() || null,
    avatarUrl: row.avatarUrl?.trim() || null,
  };
};

const resolveReferrerLookupMemberId = async (code: string): Promise<number | null> => {
  try {
    return await resolveHwyMemberPrimaryKey(code);
  } catch {
    // Fall through — legacy membership UserName or vw_hwy_members username.
  }

  const sequelize = getControlPlaneSequelize();
  const vmRows = await sequelize.query<{ id: number }>(
    `
      SELECT TOP 1 vm.id
      FROM dbo.vw_hwy_members vm WITH (NOLOCK)
      WHERE LTRIM(RTRIM(vm.username)) = :code
    `,
    { replacements: { code }, type: QueryTypes.SELECT },
  );
  const vmId = vmRows[0]?.id != null ? Number(vmRows[0].id) : null;
  if (vmId != null && Number.isFinite(vmId) && vmId > 0) {
    return vmId;
  }

  try {
    const pool = await getLegacyHwyReadPool();
    const legacyResult = await pool.request()
      .input('code', sql.NVarChar, code)
      .query(`
        SELECT TOP 1 CAST(m.Id AS BIGINT) AS memberId
        FROM dbo.HWY_Members m WITH (NOLOCK)
        WHERE LTRIM(RTRIM(m.UserName)) = @code
      `);
    const legacyId = legacyResult.recordset[0]?.memberId != null
      ? Number(legacyResult.recordset[0].memberId)
      : null;
    if (legacyId != null && Number.isFinite(legacyId) && legacyId > 0) {
      return legacyId;
    }
  } catch {
    return null;
  }

  return null;
};

export async function lookupHwyMembershipReferrerByCode(
  codeRaw: string,
): Promise<HwyMembershipReferrerLookupRow | null> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return null;
  }
  await ensureHwyDbObjects();
  const code = String(codeRaw ?? '').trim();
  if (!code) {
    return null;
  }
  const memberId = await resolveReferrerLookupMemberId(code);
  if (memberId == null) {
    return null;
  }
  const rows = await getControlPlaneSequelize().query<{
    id: number;
    userId: number | null;
    username: string | null;
    firstname: string | null;
    fathername: string | null;
    grandfathername: string | null;
    lastname: string | null;
    genderCode: string | null;
    avatarUrl: string | null;
    hasProfileImage: boolean | number | null;
  }>(
    `
      SELECT
        m.id,
        m.user_id AS userId,
        NULLIF(
          LTRIM(RTRIM(COALESCE(
            CASE
              WHEN NULLIF(LTRIM(RTRIM(m.username)), N'') IS NOT NULL
                AND LTRIM(RTRIM(m.username)) <> CAST(m.id AS NVARCHAR(32))
                AND LEN(LTRIM(RTRIM(m.username))) = 6
                AND LTRIM(RTRIM(m.username)) NOT LIKE N'%[^0-9]%'
              THEN NULLIF(LTRIM(RTRIM(m.username)), N'')
              ELSE NULL
            END,
            CASE
              WHEN NULLIF(LTRIM(RTRIM(u.username)), N'') IS NOT NULL
                AND LTRIM(RTRIM(u.username)) <> CAST(m.id AS NVARCHAR(32))
                AND LEN(LTRIM(RTRIM(u.username))) = 6
                AND LTRIM(RTRIM(u.username)) NOT LIKE N'%[^0-9]%'
              THEN NULLIF(LTRIM(RTRIM(u.username)), N'')
              ELSE NULL
            END,
            CAST(m.id AS NVARCHAR(32))
          ))),
          N''
        ) AS username,
        COALESCE(p.firstname, m.first_name) AS firstname,
        COALESCE(p.fathername, m.father_name) AS fathername,
        COALESCE(p.grandfathername, m.grandfather_name) AS grandfathername,
        COALESCE(p.lastname, m.family_name) AS lastname,
        COALESCE(p.gender_code, m.gender_code) AS genderCode,
        CASE
          WHEN p.profile_image_body IS NOT NULL AND m.user_id IS NOT NULL
            THEN CONCAT(N'/api/users/', CAST(m.user_id AS VARCHAR(20)), N'/avatar-xs')
          ELSE NULL
        END AS avatarUrl,
        CASE WHEN p.profile_image_body IS NULL THEN CAST(0 AS bit) ELSE CAST(1 AS bit) END AS hasProfileImage
      FROM dbo.hwy_members m WITH (NOLOCK)
      LEFT JOIN dbo.base_users u WITH (NOLOCK) ON u.id = m.user_id
      LEFT JOIN dbo.base_user_profiles p WITH (NOLOCK) ON p.user_id = m.user_id
      WHERE m.id = :memberId
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  const row = rows[0];
  const mapped = row ? mapRow(row) : null;
  if (!mapped) {
    return null;
  }
  const resolvedAvatar = resolveHwyGeoResponsibilityAvatarUrl({
    avatarUrl: mapped.avatarUrl,
    userId: row.userId != null ? Number(row.userId) : null,
    hasProfileImage: row.hasProfileImage === true || row.hasProfileImage === 1,
  });
  const faceRow = { id: mapped.memberId, avatarUrl: resolvedAvatar };
  await enrichMemberRowAvatarsFromRegistrationPhotos([faceRow]);
  return {
    ...mapped,
    avatarUrl: faceRow.avatarUrl?.trim() || resolvedAvatar,
  };
}
