import { QueryTypes } from 'sequelize';

import type { HwyGeoResponsibilityLevel } from '../../../domain/hwy/hwyGeoResponsibilityCatalog';
import { normalizeHwyPlatformAdminActorFields } from '../../../domain/hwy/hwyLegacyPlatformAdminActor';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

export type HwyPatchHistoryEventKind = 'nomination' | 'confirmed' | 'removed';

export type HwyPatchHistoryEventUpsert = {
  geoLevel: HwyGeoResponsibilityLevel;
  geoBaseInfoId: string;
  legacyGeoId: number | null;
  legacySourceKey: string;
  eventKind: HwyPatchHistoryEventKind;
  eventAt: Date;
  memberId: number | null;
  memberDisplayName: string | null;
  memberUsername: string | null;
  actorDisplayName: string | null;
  actorUsername: string | null;
  source: 'legacy' | 'studio';
  requestId: string | null;
};

const PATCH_HISTORY_UPSERT_CHUNK = 80;

const isGeoLevel = (kind: string): kind is HwyGeoResponsibilityLevel => (
  kind === 'province'
  || kind === 'ghavateh'
  || kind === 'circle'
  || kind === 'maktab'
  || kind === 'region'
);

export async function upsertHwyPatchHistoryEventsBatch(events: HwyPatchHistoryEventUpsert[]): Promise<void> {
  if (events.length === 0) {
    return;
  }
  const sequelize = getControlPlaneSequelize();
  for (let offset = 0; offset < events.length; offset += PATCH_HISTORY_UPSERT_CHUNK) {
    const chunk = events.slice(offset, offset + PATCH_HISTORY_UPSERT_CHUNK);
    const replacements: Record<string, unknown> = {};
    const valueRows: string[] = [];
    chunk.forEach((event, index) => {
      const p = `e${index}`;
      replacements[`${p}_lsk`] = event.legacySourceKey;
      replacements[`${p}_gl`] = event.geoLevel;
      replacements[`${p}_geo`] = event.geoBaseInfoId;
      replacements[`${p}_lgeo`] = event.legacyGeoId;
      replacements[`${p}_kind`] = event.eventKind;
      replacements[`${p}_at`] = event.eventAt;
      replacements[`${p}_mid`] = event.memberId;
      replacements[`${p}_mdn`] = event.memberDisplayName;
      replacements[`${p}_mun`] = event.memberUsername;
      replacements[`${p}_adn`] = event.actorDisplayName;
      replacements[`${p}_aun`] = event.actorUsername;
      replacements[`${p}_src`] = event.source;
      replacements[`${p}_rid`] = event.requestId;
      valueRows.push(
        `(:${p}_lsk, :${p}_gl, :${p}_geo, :${p}_lgeo, :${p}_kind, :${p}_at, :${p}_mid, :${p}_mdn, :${p}_mun, :${p}_adn, :${p}_aun, :${p}_src, :${p}_rid)`,
      );
    });
    await sequelize.query(
      `
      MERGE dbo.hwy_geo_responsibility_patch_history_events AS t
      USING (
        SELECT * FROM (VALUES
          ${valueRows.join(',\n          ')}
        ) AS v(
          legacy_source_key, geo_level, geo_base_info_id, legacy_geo_id,
          event_kind, event_at, member_id, member_display_name, member_username,
          actor_display_name, actor_username, source, request_id
        )
      ) AS s
        ON t.legacy_source_key = s.legacy_source_key
      WHEN MATCHED THEN UPDATE SET
        geo_level = s.geo_level,
        geo_base_info_id = s.geo_base_info_id,
        legacy_geo_id = s.legacy_geo_id,
        event_kind = s.event_kind,
        event_at = s.event_at,
        member_id = s.member_id,
        member_display_name = s.member_display_name,
        member_username = s.member_username,
        actor_display_name = s.actor_display_name,
        actor_username = s.actor_username,
        source = s.source,
        request_id = s.request_id
      WHEN NOT MATCHED THEN INSERT (
        geo_level, geo_base_info_id, legacy_geo_id, legacy_source_key,
        event_kind, event_at, member_id, member_display_name, member_username,
        actor_display_name, actor_username, source, request_id
      ) VALUES (
        s.geo_level, s.geo_base_info_id, s.legacy_geo_id, s.legacy_source_key,
        s.event_kind, s.event_at, s.member_id, s.member_display_name, s.member_username,
        s.actor_display_name, s.actor_username, s.source, s.request_id
      );
      `,
      { replacements, type: QueryTypes.RAW },
    );
  }
}

type StudioRequestRow = {
  id: string;
  geo_level: string;
  geo_base_info_id: string;
  legacy_geo_id: number | null;
  member_id: string;
  status: string;
  nominated_at: Date | null;
  decided_at: Date | null;
  revoked_at: Date | null;
  memberDisplayName: string | null;
  memberUsername: string | null;
  nominatedByDisplayName: string | null;
  nominatedByUsername: string | null;
  decidedByDisplayName: string | null;
  decidedByUsername: string | null;
  revokedByDisplayName: string | null;
  revokedByUsername: string | null;
};

const normalizePatchHistoryActor = (
  actorDisplayName: string | null | undefined,
  actorUsername: string | null | undefined,
): { actorDisplayName: string | null; actorUsername: string | null } => {
  const normalized = normalizeHwyPlatformAdminActorFields({
    actorDisplayName: actorDisplayName?.trim() || null,
    actorUsername: actorUsername?.trim() || null,
  });
  return {
    actorDisplayName: normalized.actorDisplayName,
    actorUsername: normalized.actorUsername,
  };
};

const studioEventsFromRequestRow = (row: StudioRequestRow): HwyPatchHistoryEventUpsert[] => {
  if (!isGeoLevel(row.geo_level)) {
    return [];
  }
  const memberId = Number(row.member_id);
  const memberDisplayName = formatHwyMemberPersonDisplayName(row.memberDisplayName) || null;
  const base = {
    geoLevel: row.geo_level,
    geoBaseInfoId: row.geo_base_info_id,
    legacyGeoId: row.legacy_geo_id != null ? Number(row.legacy_geo_id) : null,
    memberId: Number.isFinite(memberId) ? memberId : null,
    memberDisplayName,
    memberUsername: row.memberUsername?.trim() || null,
    source: 'studio' as const,
    requestId: row.id,
  };
  const events: HwyPatchHistoryEventUpsert[] = [];
  if (row.nominated_at) {
    const actor = normalizePatchHistoryActor(row.nominatedByDisplayName, row.nominatedByUsername);
    events.push({
      ...base,
      legacySourceKey: `studio:${row.id}:nomination`,
      eventKind: 'nomination',
      eventAt: new Date(row.nominated_at),
      ...actor,
    });
  }
  if (row.status === 'approved' && row.decided_at) {
    const actor = normalizePatchHistoryActor(row.decidedByDisplayName, row.decidedByUsername);
    events.push({
      ...base,
      legacySourceKey: `studio:${row.id}:confirmed`,
      eventKind: 'confirmed',
      eventAt: new Date(row.decided_at),
      ...actor,
    });
  }
  if (row.revoked_at) {
    const actor = normalizePatchHistoryActor(row.revokedByDisplayName, row.revokedByUsername);
    events.push({
      ...base,
      legacySourceKey: `studio:${row.id}:removed`,
      eventKind: 'removed',
      eventAt: new Date(row.revoked_at),
      ...actor,
    });
  } else if (
    (row.status === 'rejected' || row.status === 'cancelled' || row.status === 'superseded')
    && row.decided_at
  ) {
    const actor = normalizePatchHistoryActor(row.decidedByDisplayName, row.decidedByUsername);
    events.push({
      ...base,
      legacySourceKey: `studio:${row.id}:removed`,
      eventKind: 'removed',
      eventAt: new Date(row.decided_at),
      ...actor,
    });
  }
  return events;
};

const STUDIO_REQUEST_HISTORY_SQL = `
  SELECT
    CAST(r.id AS VARCHAR(36)) AS id,
    r.geo_level,
    r.geo_base_info_id,
    r.legacy_geo_id,
    CAST(r.member_id AS VARCHAR(32)) AS member_id,
    r.status,
    r.nominated_at,
    r.decided_at,
    r.revoked_at,
    COALESCE(NULLIF(vm.display_full_name, N''), vm.username) AS memberDisplayName,
    vm.username AS memberUsername,
    COALESCE(NULLIF(CONCAT(np_nom.firstname, N' ', np_nom.lastname), N' '), nu.username) AS nominatedByDisplayName,
    nu.username AS nominatedByUsername,
    COALESCE(NULLIF(CONCAT(np_dec.firstname, N' ', np_dec.lastname), N' '), du.username) AS decidedByDisplayName,
    du.username AS decidedByUsername,
    COALESCE(NULLIF(CONCAT(np_rev.firstname, N' ', np_rev.lastname), N' '), ru.username) AS revokedByDisplayName,
    ru.username AS revokedByUsername
  FROM dbo.hwy_geo_responsibility_requests r
  INNER JOIN dbo.vw_hwy_members vm ON vm.id = r.member_id
  LEFT JOIN dbo.base_users nu ON nu.id = r.nominated_by
  LEFT JOIN dbo.base_user_profiles np_nom ON np_nom.user_id = nu.id
  LEFT JOIN dbo.base_users du ON du.id = r.decided_by
  LEFT JOIN dbo.base_user_profiles np_dec ON np_dec.user_id = du.id
  LEFT JOIN dbo.base_users ru ON ru.id = r.revoked_by
  LEFT JOIN dbo.base_user_profiles np_rev ON np_rev.user_id = ru.id
`;

/** Keep patch history in sync after nomination lifecycle writes (best-effort). */
export async function syncHwyGeoResponsibilityPatchHistoryForRequest(requestId: string): Promise<void> {
  const id = String(requestId ?? '').trim();
  if (!id) {
    return;
  }
  const rows = await getControlPlaneSequelize().query<StudioRequestRow>(
    `${STUDIO_REQUEST_HISTORY_SQL}
     WHERE r.id = :requestId`,
    { replacements: { requestId: id }, type: QueryTypes.SELECT },
  );
  const row = rows[0];
  if (!row) {
    return;
  }
  await upsertHwyPatchHistoryEventsBatch(studioEventsFromRequestRow(row));
}

export async function listStudioRequestRowsForPatchHistoryEtl(): Promise<StudioRequestRow[]> {
  return getControlPlaneSequelize().query<StudioRequestRow>(
    `${STUDIO_REQUEST_HISTORY_SQL}
     WHERE r.request_kind = N'nomination'`,
    { type: QueryTypes.SELECT },
  );
}

export { studioEventsFromRequestRow };
