const parseId = (raw: string, label: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error(`${label} is invalid.`);
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error(`${label} is invalid.`);
  }
  return id;
};

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Operation requires SQL Server control plane.');
  }
  await ensureHwyDbObjects();
};

export const removeHwyTarghinDirect = async (input: {
  memberIdRaw: string;
  decisionReasonCode: string;
  decisionNote: string;
  actorUserId: number | null;
  restoreMembershipStatusCode?: string | null;
}): Promise<void> => {
  await assertSqlServer();
  const memberId = parseId(input.memberIdRaw, 'Member id');
  await assertHwyMemberTarghinRemoveDirectEligibility(memberId);
  const note = input.decisionNote.trim();
  if (!note) {
    throw new Error('Decision note is required.');
  }
  await execHwyProcedure('hwy_targhin_remove_direct', {
    member_id: memberId,
    decision_reason_code: input.decisionReasonCode.trim(),
    decision_note: note,
    actor_user_id: input.actorUserId,
    membership_status_code_on_remove: input.restoreMembershipStatusCode?.trim() || null,
  });
  await invalidateHwyMemberDirectoryListCache();
};

export const respondHwyMemberInstituteInvite = async (input: {
  memberIdRaw: string;
  instituteId: number;
  accept: boolean;
  actorUserId: number | null;
}): Promise<void> => {
  await assertSqlServer();
  const memberId = parseId(input.memberIdRaw, 'Member id');
  const activeStatus = await findHwyBaseInfoItemIdByShortName('Institute Membership Status', 'active');
  const removedStatus = await findHwyBaseInfoItemIdByShortName('Institute Membership Status', 'removed');
  await execHwyProcedure('hwy_member_institute_respond_invite', {
    member_id: memberId,
    institute_id: input.instituteId,
    accept: input.accept ? 1 : 0,
    active_status_code: activeStatus,
    removed_status_code: removedStatus,
    actor_user_id: input.actorUserId,
    responded_at: new Date(),
  });
  await invalidateHwyMemberDirectoryListCache();
};

