export const linkHwyMemberKasb = async (input: {
  memberIdRaw: string;
  kasbMemberIdRaw: string;
  referrerRelationId?: number | null;
  actorUserId: number | null;
}): Promise<void> => {
  await ensureHwyDbObjects();
  await assertSqlServer();
  const memberId = await resolveHwyMemberPrimaryKey(input.memberIdRaw);
  let kasbMemberId: number;
  try {
    kasbMemberId = await resolveHwyMemberPrimaryKey(input.kasbMemberIdRaw);
  } catch {
    throw new Error('Kasb member not found.');
  }
  await execHwyProcedure('hwy_member_kasb_link', {
    member_id: memberId,
    kasb_member_id: kasbMemberId,
    referrer_relation_id: input.referrerRelationId ?? null,
    actor_user_id: input.actorUserId,
  });
  await invalidateHwyMemberDirectoryListCache();
};

