export type HwyMemberAfterCreateResult = {
  memberId: string;
  phone1: string | null;
  smsMessage: string | null;
};

export type HwyMemberRegistrationSmsDelivery = {
  payload: HwyMemberAfterCreateResult;
  smsDelivery: SendSmsResult | null;
};

export const runHwyMemberAfterCreateHook = async (input: {
  memberId: number;
  actorUserId: number | null;
  skipNoteMirror?: boolean;
  actorLabel?: string | null;
  sendSms?: boolean;
}): Promise<HwyMemberRegistrationSmsDelivery | null> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return null;
  }
  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<HwyMemberAfterCreateResult>('hwy_member_after_create', {
    member_id: input.memberId,
    actor_user_id: input.actorUserId,
    skip_note_mirror: input.skipNoteMirror ? 1 : 0,
  });
  const payload = rows[0] ?? null;
  if (!payload) {
    return null;
  }
  const smsDelivery = input.sendSms === false
    ? null
    : await deliverHwyMemberRegistrationSms({
      phone1: payload.phone1,
      smsMessage: payload.smsMessage,
      actor: input.actorLabel ?? null,
    });
  return { payload, smsDelivery };
};

/** Legacy AfterCreate_Resend parity — builds SMS payload and sends through platform SMS gateway when configured. */
export const resendHwyMemberRegistrationSms = async (input: {
  memberIdRaw: string;
  actorUserId: number | null;
  actorLabel?: string | null;
}): Promise<HwyMemberRegistrationSmsDelivery> => {
  await assertSqlServer();
  const memberId = parseId(input.memberIdRaw, 'Member id');
  const rows = await execHwyProcedure<HwyMemberAfterCreateResult>('hwy_member_after_create_resend', {
    member_id: memberId,
    actor_user_id: input.actorUserId,
  });
  const payload = rows[0];
  if (!payload?.memberId) {
    throw new Error('Member not found.');
  }
  const smsDelivery = await deliverHwyMemberRegistrationSms({
    phone1: payload.phone1,
    smsMessage: payload.smsMessage,
    actor: input.actorLabel ?? null,
  });
  return { payload, smsDelivery };
};

const syncHwyMemberOathDocumentApproveFlag = async (input: {
  memberId: number;
  approved: boolean | null;
}): Promise<void> => {
  const kind = await resolveHwyMemberFileKindBySlugOrId('oath_document');
  if (!kind?.id) {
    throw new Error('Oath document file kind is not configured.');
  }
  const sequelize = getControlPlaneSequelize();
  const approvedValue = input.approved === null ? null : input.approved ? 1 : 0;
  await sequelize.query(
    `
    UPDATE dbo.hwy_member_files
    SET is_approved = :approved,
        updated_at = SYSUTCDATETIME()
    WHERE member_id = :memberId
      AND file_kind_code = :fileKindCode
    `,
    {
      replacements: {
        approved: approvedValue,
        memberId: input.memberId,
        fileKindCode: kind.id,
      },
      type: QueryTypes.UPDATE,
    },
  );
};

export const syncHwyMemberRegistrationFileApproveFlags = async (input: {
  memberId: number;
  flags: {
    personalPhoto?: boolean | null;
    nationalCardFront?: boolean | null;
    nationalCardBack?: boolean | null;
    voterCardFront?: boolean | null;
    residenceCardFront?: boolean | null;
    oathDocument?: boolean | null;
  };
  imageFixEditor?: {
    nakhebCardFrontCheck?: boolean;
    voterCardFrontTypeShortName?: string | null;
  };
  actorUserId: number | null;
}): Promise<void> => {
  await assertSqlServer();
  const { oathDocument, ...procedureFlags } = input.flags;
  const hasProcedureFlag = Object.values(procedureFlags).some((value) => value !== undefined);
  if (hasProcedureFlag) {
    await execHwyProcedure('hwy_member_registration_files_sync_approve_flags', {
      member_id: input.memberId,
      personal_photo_approved: procedureFlags.personalPhoto ?? null,
      national_card_front_approved: procedureFlags.nationalCardFront ?? null,
      national_card_back_approved: procedureFlags.nationalCardBack ?? null,
      voter_card_front_approved: procedureFlags.voterCardFront ?? null,
      residence_card_front_approved: procedureFlags.residenceCardFront ?? null,
      actor_user_id: input.actorUserId,
    });
  }
  if (oathDocument !== undefined) {
    await syncHwyMemberOathDocumentApproveFlag({
      memberId: input.memberId,
      approved: oathDocument,
    });
  }
  if (input.imageFixEditor) {
    const { nakhebCardFrontCheck, voterCardFrontTypeShortName: typeShortNameRaw } = input.imageFixEditor;
    if (nakhebCardFrontCheck !== undefined) {
      await patchHwyMemberImageFixEditorFields({
        memberId: input.memberId,
        nakhebCardFrontCheck,
        actorUserId: input.actorUserId,
      });
    }
    if (typeShortNameRaw !== undefined) {
      const voterCardFrontTypeShortName = typeShortNameRaw === null
        || isHwyVoterCardFrontTypeShortName(typeShortNameRaw)
        ? typeShortNameRaw
        : null;
      await patchHwyMemberImageFixEditorFields({
        memberId: input.memberId,
        voterCardFrontTypeShortName,
        actorUserId: input.actorUserId,
      });
    }
  }
  await invalidateHwyMemberDirectoryListCache();
};
