import { QueryTypes } from 'sequelize';

import type {
  HwyMemberTarghinAdminMemberFace,
  HwyMemberTarghinAdminRow,
} from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyMemberTarghinAdminFaceDossierMemberId } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import {
  finalizeTarghinMemberFacesForDossier,
  loadCpMemberFacesByActorKeys,
} from './hwyMemberTarghinDossierFaceFinalize.service';
import { listHwyMemberIdsByUserIds } from './hwyMemberTarghinExecutorRoles';
import { negoAuthorHasLabel } from './hwyMemberTarghinNegoAuthorResolve';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const targhinAdminRequesterNeedsEnrichment = (row: HwyMemberTarghinAdminRow): boolean => (
  !resolveHwyMemberTarghinAdminFaceDossierMemberId(row.requester)
);

const parseRequesterAccountUserId = (face: HwyMemberTarghinAdminMemberFace | null | undefined): number | null => {
  const id = trim(face?.id);
  const match = /^user-(\d+)$/.exec(id);
  if (!match) {
    return null;
  }
  const userId = Number(match[1]);
  return Number.isFinite(userId) && userId > 0 ? userId : null;
};

/** Map platform user ids on stub requester faces to control-plane member ids. */
async function enrichTarghinAdminRequesterMemberIdsFromAccounts(
  rows: HwyMemberTarghinAdminRow[],
): Promise<void> {
  const userIdsByRow = new Map<HwyMemberTarghinAdminRow, number>();
  for (const row of rows) {
    if (resolveHwyMemberTarghinAdminFaceDossierMemberId(row.requester)) {
      continue;
    }
    const userId = parseRequesterAccountUserId(row.requester);
    if (userId != null) {
      userIdsByRow.set(row, userId);
    }
  }
  if (!userIdsByRow.size) {
    return;
  }

  const memberIdByUserId = await listHwyMemberIdsByUserIds([...userIdsByRow.values()]);
  for (const [row, userId] of userIdsByRow) {
    const memberId = memberIdByUserId.get(userId);
    if (!memberId) {
      continue;
    }
    const face = row.requester;
    if (!face) {
      continue;
    }
    row.requester = {
      ...face,
      id: String(memberId),
    };
  }
}

/** Fill missing targhin admin requester faces from `request_by_legacy` on the control plane. */
export async function attachHwyMemberTarghinAdminRequesters(
  rows: HwyMemberTarghinAdminRow[],
): Promise<void> {
  const rowsWithIds = rows.filter((row) => trim(row.id));
  if (!rowsWithIds.length) {
    await enrichTarghinAdminRequesterMemberIdsFromAccounts(rows);
    await finalizeTarghinMemberFacesForDossier(
      rows,
      (row) => row.requester,
      (row, face) => { row.requester = face; },
    );
    return;
  }

  const sequelize = getControlPlaneSequelize();
  const placeholders = rowsWithIds.map((_, index) => `:rid${index}`).join(', ');
  const replacements = Object.fromEntries(rowsWithIds.map((row, index) => [`rid${index}`, row.id]));
  const historyRows = await sequelize.query<{
    id: string;
    requestByLegacy: string | null;
  }>(
    `
    SELECT CAST(id AS VARCHAR(32)) AS id, request_by_legacy AS requestByLegacy
    FROM dbo.hwy_member_targhin_requests WITH (NOLOCK)
    WHERE id IN (${placeholders})
    `,
    { replacements, type: QueryTypes.SELECT },
  );

  const actorsByRequestId = new Map<string, string>();
  for (const row of historyRows) {
    const requestId = trim(row.id);
    const requestBy = trim(row.requestByLegacy);
    if (requestId && requestBy) {
      actorsByRequestId.set(requestId, requestBy);
    }
  }

  const uniqueActors = [...new Set(actorsByRequestId.values())];
  const faceByActor = uniqueActors.length
    ? await loadCpMemberFacesByActorKeys(uniqueActors)
    : new Map<string, HwyMemberTarghinAdminMemberFace>();

  // CP-only for admin list paint — legacy MembersV2 enrichment is multi-second to multi-minute.

  for (const row of rowsWithIds) {
    const actor = actorsByRequestId.get(row.id);
    if (!actor) {
      continue;
    }
    const face = faceByActor.get(actor);
    if (face) {
      row.requester = face;
    }
  }

  await enrichTarghinAdminRequesterMemberIdsFromAccounts(rows);
  await finalizeTarghinMemberFacesForDossier(
    rows,
    (row) => row.requester,
    (row, face) => { row.requester = face; },
  );
}
