export const hwyCandidatePipelineStageFromSegment = (
  pathnameOrStage: string,
): HwyCandidatePipelineStage | null => {
  const normalized = pathnameOrStage.replace(/\/+$/, '').trim().toLowerCase();
  const fromPath = normalized.match(/(?:^|\/)candidate-pipeline\/([^/]+)$/i)?.[1];
  const raw = (fromPath ?? normalized).trim().toLowerCase();
  if (!raw) return null;
  const found = HWY_CANDIDATE_PIPELINE_STAGES.find((s) => s.stage === raw);
  return found?.stage ?? null;
};

export const hwyCandidatePipelinePathSegment = (stage: HwyCandidatePipelineStage): string =>
  `candidate-pipeline/${stage}`;
