import { QueryTypes } from 'sequelize';

import type { HwyRegistrationChannelShortName } from '../../../domain/hwy/hwyRegistrationChannel';
import { buildHwyInstituteLogoApiPath } from '../../../domain/hwy/hwyInstituteLogoPath';
import { loadHwyInstituteLogo } from './hwyInstituteLogo.service';
import { resolveHwySelfRegistrationInstituteId } from './hwySelfRegistrationInstituteResolve.service';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';

export type HwyInstituteSelfRegistrationBrand = {
  instituteId: number;
  code: string;
  titleAr: string | null;
  logoUrl: string | null;
  note: string | null;
  allowsSelfRegistration: boolean;
  allowsInvite: boolean;
  hideMemberPhones: boolean;
  hasDedicatedList: boolean;
  inviteExpiresAfterDays: number | null;
};

type InstituteBrandRow = {
  id: number;
  code: string;
  title_ar: string | null;
  note: string | null;
  allows_self_registration: boolean | number | null;
  allows_invite: boolean | number | null;
  hide_member_phones: boolean | number | null;
  has_dedicated_list: boolean | number | null;
  invite_expires_after_days: number | null;
};

const readBool = (value: boolean | number | null | undefined): boolean =>
  value === true || value === 1;

export async function loadHwyInstituteSelfRegistrationBrand(input: {
  channel: HwyRegistrationChannelShortName;
  referrerInstituteCode?: string | null;
}): Promise<HwyInstituteSelfRegistrationBrand | null> {
  const instituteId = await resolveHwySelfRegistrationInstituteId({
    channel: input.channel,
    referrerInstituteCode: input.referrerInstituteCode,
  });
  if (instituteId == null) {
    return null;
  }

  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const table = dialect === 'mssql' ? 'dbo.hwy_institutes' : 'hwy_institutes';

  const rows = await sequelize.query<InstituteBrandRow>(
    `SELECT id,
            code,
            title_ar,
            note,
            allows_self_registration,
            allows_invite,
            hide_member_phones,
            has_dedicated_list,
            invite_expires_after_days
     FROM ${table}
     WHERE id = :instituteId AND is_active = 1`,
    {
      type: QueryTypes.SELECT,
      replacements: { instituteId },
    },
  );

  const row = rows[0];
  if (!row) {
    return null;
  }

  const storedLogo = await loadHwyInstituteLogo(row.id);
  return {
    instituteId: row.id,
    code: row.code?.trim() || input.channel,
    titleAr: row.title_ar?.trim() || null,
    logoUrl: storedLogo ? buildHwyInstituteLogoApiPath(row.id) : null,
    note: row.note?.trim() || null,
    allowsSelfRegistration: readBool(row.allows_self_registration),
    allowsInvite: readBool(row.allows_invite),
    hideMemberPhones: readBool(row.hide_member_phones),
    hasDedicatedList: readBool(row.has_dedicated_list),
    inviteExpiresAfterDays: row.invite_expires_after_days ?? null,
  };
}
