import { HWY_ACTIVITY_CENTRAL_TYPE_CODE } from './hwyCoursesActivitiesCatalog';

/** Legacy `NbOrganizationId = '0'` — members with no institute/org row. */
export const HWY_NB_ORGANIZATION_NONE_LEGACY_ID = '0';

export const parseHwyNbTargetCsv = (raw: string | null | undefined): string[] => {
  if (raw == null) {
    return [];
  }
  const parts = raw
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  return [...new Set(parts)];
};

export const joinHwyNbTargetCsv = (ids: readonly string[]): string => ids.join(',');

export type HwyNbTargetAudienceCriteria = {
  activityTypeCode: string;
  enableSelfAnnouncement: boolean;
  applyKashafeh: boolean;
  applyGov: boolean;
  nbGenderLegacyId: number | null;
  nbCircleLegacyId: number | null;
  nbProvinceLegacyIdsCsv: string;
  nbOrganizationIdsCsv: string;
  nbAllowedRolesCsv: string;
};

export const buildHwyNbTargetAudienceCriteria = (input: {
  activityTypeCode: string | null;
  enableSelfAnnouncement: boolean | null;
  nbOnlyKashafeh: boolean | null;
  nbAllowGov: boolean | null;
  nbLegacyGenderId: number | null;
  nbLegacyCircleId: number | null;
  nbLegacyProvinceId: string | null;
  nbOrganizationIds: string | null;
  nbAllowedRoles: string | null;
}): HwyNbTargetAudienceCriteria => {
  const gender = input.nbLegacyGenderId != null && input.nbLegacyGenderId > 0
    ? input.nbLegacyGenderId
    : null;
  const circle = input.nbLegacyCircleId != null && input.nbLegacyCircleId > 0
    ? input.nbLegacyCircleId
    : null;
  return {
    activityTypeCode: input.activityTypeCode?.trim() || '',
    enableSelfAnnouncement: Boolean(input.enableSelfAnnouncement),
    applyKashafeh: Boolean(input.nbOnlyKashafeh),
    applyGov: Boolean(input.nbAllowGov),
    nbGenderLegacyId: gender,
    nbCircleLegacyId: circle,
    nbProvinceLegacyIdsCsv: input.nbLegacyProvinceId?.trim() || '',
    nbOrganizationIdsCsv: input.nbOrganizationIds?.trim() || '',
    nbAllowedRolesCsv: input.nbAllowedRoles?.trim() || '',
  };
};

export const hwyNbOrganizationNoneChecked = (organizationIdsCsv: string): boolean => {
  const ids = parseHwyNbTargetCsv(organizationIdsCsv);
  return ids.length === 1 && ids[0] === HWY_NB_ORGANIZATION_NONE_LEGACY_ID;
};

export const hwyNbOrganizationTagIds = (organizationIdsCsv: string): string[] =>
  parseHwyNbTargetCsv(organizationIdsCsv).filter((id) => id !== HWY_NB_ORGANIZATION_NONE_LEGACY_ID);

export const hwyNbTargetAudienceHasAudienceSegment = (crit: HwyNbTargetAudienceCriteria): boolean =>
  crit.applyKashafeh
  || crit.applyGov
  || crit.nbOrganizationIdsCsv !== '';

export const hwyNbTargetAudienceHasDemoFilters = (crit: HwyNbTargetAudienceCriteria): boolean =>
  crit.nbGenderLegacyId != null
  || crit.nbCircleLegacyId != null
  || crit.nbProvinceLegacyIdsCsv !== ''
  || crit.nbAllowedRolesCsv !== '';

export const hwyNbTargetAudienceSegmentCount = (crit: HwyNbTargetAudienceCriteria): number =>
  (crit.applyKashafeh ? 1 : 0)
  + (crit.applyGov ? 1 : 0)
  + (crit.nbOrganizationIdsCsv !== '' ? 1 : 0);

export const hwyNbTargetAudienceEligibleForCount = (crit: HwyNbTargetAudienceCriteria): boolean => {
  if (crit.activityTypeCode !== HWY_ACTIVITY_CENTRAL_TYPE_CODE || !crit.enableSelfAnnouncement) {
    return false;
  }
  return hwyNbTargetAudienceHasAudienceSegment(crit) || hwyNbTargetAudienceHasDemoFilters(crit);
};

/** Legacy `enableSelfChanged` — clear NB filters when self-announce is turned off. */
export const emptyHwyNbTargetFields = (): {
  nbLocationLat: string;
  nbLocationLon: string;
  nbMaxDistanceM: number | null;
  nbWindowStartAt: string | null;
  nbWindowEndAt: string | null;
  nbLegacyProvinceId: string;
  nbLegacyCircleId: number | null;
  nbLegacyMaktabId: number | null;
  nbLegacyRegionId: number | null;
  nbLegacyGenderId: number | null;
  nbOrganizationIds: string;
  nbAllowedRoles: string;
  nbOnlyKashafeh: boolean;
  nbAllowGov: boolean;
} => ({
  nbLocationLat: '',
  nbLocationLon: '',
  nbMaxDistanceM: null,
  nbWindowStartAt: null,
  nbWindowEndAt: null,
  nbLegacyProvinceId: '',
  nbLegacyCircleId: null,
  nbLegacyMaktabId: null,
  nbLegacyRegionId: null,
  nbLegacyGenderId: null,
  nbOrganizationIds: '',
  nbAllowedRoles: '',
  nbOnlyKashafeh: false,
  nbAllowGov: false,
});

/** Legacy New Tajammoat date window (after 2021-03-01, not older than 1 month, not future). */
export const validateHwyCentralTajammoatActivityDate = (activityDateRaw: string): boolean => {
  const trimmed = activityDateRaw.trim();
  if (!trimmed) {
    return false;
  }
  const cur = new Date(`${trimmed}T12:00:00`);
  if (Number.isNaN(cur.getTime())) {
    return false;
  }
  const min = new Date('2021-03-01T00:00:00');
  const oneMonthAgo = new Date();
  oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);
  oneMonthAgo.setHours(0, 0, 0, 0);
  const todayEnd = new Date();
  todayEnd.setHours(23, 59, 59, 999);
  if (cur < min) {
    return false;
  }
  if (cur < oneMonthAgo) {
    return false;
  }
  if (cur > todayEnd) {
    return false;
  }
  return true;
};
