import type { ModelCtor } from 'sequelize';
import type { EdgeApiOperation, EdgeModelDefinition } from '../../../shared/api/contracts/data-api';
import type { StoredDataSource } from '../../db/dataSourcesStore';
import { resolveReadableAttributes } from '../../services/data-api/dataApiQuery';
import { applyFieldEnrichments } from '../../services/data-api/dataApiFieldEnrichment';
import {
  enrichHwyMemberDirectoryListRows,
  enrichHwyMemberDirectoryRows,
} from './hwyMemberDirectoryDetailDisplay';
import {
  fetchMemberDirectoryGetOneFastPath,
  MEMBER_DIRECTORY_VIEW_UDF_FIELDS,
} from './hwyMemberDirectoryListFastPath';
import { resolveHwyMemberDirectoryQueryLang } from './hwyMemberDirectoryQueryLang';
import { resolveFieldEnrichmentDeps } from '../../services/data-api/dataApiPublishedRuntime';
import type { WhereOptions } from 'sequelize';
import { assertLoadedRecordInScope } from '../../services/record-policy/applyRecordPolicies';
import type { RecordPolicyOperationOverride } from '../../services/record-policy/recordPolicyOperationScope';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';

export type ExecuteHwyMemberDirectoryGetOneInput = {
  operation: EdgeApiOperation;
  model: EdgeModelDefinition;
  source: StoredDataSource;
  ModelCtor: ModelCtor;
  query: Record<string, unknown>;
  params: Record<string, unknown>;
  req?: { headers?: Record<string, unknown> };
  edgeModelId: string;
  where: WhereOptions;
  session: SessionScopeSnapshot | null;
  recordPolicyOverride: RecordPolicyOperationOverride;
  policyEnforced: boolean;
};

export async function executeHwyMemberDirectoryGetOne(
  input: ExecuteHwyMemberDirectoryGetOneInput,
): Promise<Record<string, unknown>> {
  const {
    operation,
    model,
    source,
    ModelCtor,
    query,
    params,
    req,
    edgeModelId,
    where,
    session,
    recordPolicyOverride,
    policyEnforced,
  } = input;
  const sequelize = ModelCtor.sequelize;
  if (!sequelize) {
    throw new Error('Member directory getOne requires a Sequelize connection.');
  }

  const viewName = typeof query.view === 'string' ? query.view.trim() : undefined;
  const readableAttributes = resolveReadableAttributes(operation, model, viewName);
  const mergedReadable = readableAttributes
    ? [...new Set([
      ...readableAttributes.filter((field) => !MEMBER_DIRECTORY_VIEW_UDF_FIELDS.has(field)),
      'addrProvinceId',
      'addrMaktabId',
      'addrRegionId',
      'nakhebinMaktabId',
    ])]
    : readableAttributes;
  const queryLang = resolveHwyMemberDirectoryQueryLang(query, req);
  const enrichmentDeps = await resolveFieldEnrichmentDeps(edgeModelId, operation);

  let plainRow: Record<string, unknown> | null = null;
  let fetchPath: 'fast' | 'view' = 'fast';

  const memberId = String(params.pk ?? params.memberId ?? '').trim();
  if (memberId) {
    try {
      plainRow = await fetchMemberDirectoryGetOneFastPath(sequelize, memberId, mergedReadable ?? []);
      if (plainRow) {
        fetchPath = 'fast';
      }
    } catch (fastPathError) {
      const message = fastPathError instanceof Error ? fastPathError.message : String(fastPathError);
      console.warn('[hwy-member-directory-getone] fast path failed.', message);
      plainRow = null;
    }
  }

  if (!plainRow) {
    throw new Error('Record not found.');
  }

  if (plainRow && policyEnforced) {
    assertLoadedRecordInScope(model, plainRow, session, 'read', recordPolicyOverride);
  }

  let enrichedRow = plainRow;
  if (enrichedRow) {
    enrichedRow = (await applyFieldEnrichments(
      [enrichedRow],
      operation.enrichments,
      queryLang,
      enrichmentDeps,
    ))[0];
    await enrichHwyMemberDirectoryRows([enrichedRow], queryLang);
    await enrichHwyMemberDirectoryListRows([enrichedRow], queryLang, {
      includeElectoralDivisionPath: true,
      includeMemberInstitutesSummary: false,
    });
    await applyHwyMemberIdentityFieldMasksToRows(sequelize, [enrichedRow], session, {
      attachIdentityFieldPolicy: true,
    });
  }

  return {
    success: true,
    data: enrichedRow,
    meta: { lang: queryLang, fetchPath },
    source: { id: source.id, name: source.name, type: source.type },
  };
}
