/** Targhin request workflow status on `hwy_member_targhin_requests.status_code`. */
export const HWY_MEMBER_TARGHIN_REQUEST_STATUS = {
  pending: 'pending',
  approved: 'approved',
  rejected: 'rejected',
} as const;

export type HwyMemberTarghinRequestStatusCode =
  (typeof HWY_MEMBER_TARGHIN_REQUEST_STATUS)[keyof typeof HWY_MEMBER_TARGHIN_REQUEST_STATUS];

export function resolveHwyMemberTarghinRequestStatusFromLegacyFinalResult(
  finalResult: boolean | number | null | undefined,
): HwyMemberTarghinRequestStatusCode {
  if (finalResult === true || finalResult === 1) {
    return HWY_MEMBER_TARGHIN_REQUEST_STATUS.approved;
  }
  if (finalResult === false || finalResult === 0) {
    return HWY_MEMBER_TARGHIN_REQUEST_STATUS.rejected;
  }
  return HWY_MEMBER_TARGHIN_REQUEST_STATUS.pending;
}

export function isHwyMemberTarghinRequestStatusCode(value: string): value is HwyMemberTarghinRequestStatusCode {
  return (Object.values(HWY_MEMBER_TARGHIN_REQUEST_STATUS) as string[]).includes(value);
}
