import type { HwyMemberIdentityMaskViewer } from '../../../domain/hwy/hwyMemberIdentityFieldMask';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';
import { getSessionContextForUser } from '../../services/attributes/sessionContext.service';
import { resolveSessionScope } from '../../services/record-policy/sessionScope.service';
import type { Sequelize } from 'sequelize';
import { loadHwyStaffGenderLimitLegacyIds } from './hwyMemberStaffGenderLimits.service';

const GENDER_LIMIT_CONTEXT_KEYS = [
  'user.gender_limits',
  'user.hwy_gender_limits',
  'user.GenderLimits',
  'user.gender_view',
  'user.hwy.gender_view',
  'role.gender_limits',
  'role.hwy_gender_limits',
  'role.hwy.gender_view',
] as const;

const parseGenderLimitIds = (raw: unknown): string[] => {
  if (raw === null || raw === undefined) {
    return [];
  }
  if (Array.isArray(raw)) {
    const ids: string[] = [];
    for (const entry of raw) {
      if (entry === null || entry === undefined) {
        continue;
      }
      if (typeof entry === 'object' && !Array.isArray(entry)) {
        const id = (entry as { Id?: unknown; id?: unknown }).Id ?? (entry as { id?: unknown }).id;
        if (id !== null && id !== undefined && String(id).trim()) {
          ids.push(String(id).trim());
        }
        continue;
      }
      const text = String(entry).trim();
      if (text) {
        ids.push(text);
      }
    }
    return ids;
  }
  if (typeof raw === 'string') {
    const trimmed = raw.trim();
    if (!trimmed) {
      return [];
    }
    if (trimmed.startsWith('[')) {
      try {
        return parseGenderLimitIds(JSON.parse(trimmed) as unknown);
      } catch {
        return trimmed.split(/[,;|]/).map((part) => part.trim()).filter(Boolean);
      }
    }
    return trimmed.split(/[,;|]/).map((part) => part.trim()).filter(Boolean);
  }
  return [String(raw).trim()].filter(Boolean);
};

const collectGenderLimitIdsFromSession = (
  session: SessionScopeSnapshot | null | undefined,
): string[] => {
  if (!session) {
    return [];
  }
  const genderIds: string[] = [];
  for (const key of GENDER_LIMIT_CONTEXT_KEYS) {
    const raw = session.serverContext[key];
    if (raw !== undefined) {
      genderIds.push(...parseGenderLimitIds(raw));
    }
  }
  return [...new Set(genderIds.map((id) => id.trim()).filter(Boolean))];
};

export const resolveHwyMemberIdentityMaskViewer = (
  session: SessionScopeSnapshot | null | undefined,
): HwyMemberIdentityMaskViewer => {
  if (!session) {
    return { isAdmin: false, roleNames: [], genderLimitLegacyIds: [] };
  }
  return {
    isAdmin: session.isAdmin,
    roleNames: session.roles,
    genderLimitLegacyIds: collectGenderLimitIdsFromSession(session),
  };
};

/** Session attributes first; then `hwy_ref_members_gender_limits` for the viewer's linked member row. */
export async function resolveHwyMemberIdentitySessionForAuth(input: {
  userId: number | null | undefined;
  roles: readonly string[];
  isAdmin: boolean;
  email?: string | null;
}): Promise<SessionScopeSnapshot | null> {
  const actorUserId = input.userId != null ? Number(input.userId) : NaN;
  if (!Number.isFinite(actorUserId) || actorUserId <= 0) {
    return null;
  }
  const roles = input.roles.length > 0 ? [...input.roles] : ['USER'];
  const sessionContext = await getSessionContextForUser(actorUserId, roles[0]);
  return resolveSessionScope({
    userId: actorUserId,
    roles,
    isAdmin: input.isAdmin,
    email: input.email ?? null,
    serverContext: sessionContext.serverContext as Record<string, unknown>,
  });
}

export async function resolveHwyMemberIdentityMaskViewerForRequest(
  session: SessionScopeSnapshot | null | undefined,
  sequelize: Sequelize | null | undefined,
): Promise<HwyMemberIdentityMaskViewer> {
  const base = resolveHwyMemberIdentityMaskViewer(session);
  if (base.genderLimitLegacyIds.length > 0 || !session || !sequelize) {
    return base;
  }
  const fromStaffMember = await loadHwyStaffGenderLimitLegacyIds(sequelize, session.userId);
  if (fromStaffMember.length === 0) {
    return base;
  }
  return {
    ...base,
    genderLimitLegacyIds: fromStaffMember,
  };
}
