/** Binary «مسجل» grid column filter — maps to `nakhebinJoinTasjilStateCode` (not membership status LOV). */

export const HWY_MEMBER_DIRECTORY_JOIN_TASJIL_REGISTERED_FILTER_STORE_PATH =
  'gridToolbar.filters.nakhebinJoinTasjilStateCode';

export const HWY_MEMBER_DIRECTORY_JOIN_TASJIL_REGISTERED_FILTER_QUERY_PARAM =
  'filter[nakhebinJoinTasjilStateCode][eq]';

/** Active Base Info short names under tasjil state parent (legacy parity). */
export const HWY_JOIN_TASJIL_STATE_CODE_REGISTERED = 'registered_biometric';
export const HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED = 'unregistered';

export type HwyJoinTasjilRegisteredFilterOption = {
  value: string;
  labelKey: string;
  labelFallback: string;
};

export const HWY_JOIN_TASJIL_REGISTERED_FILTER_OPTIONS: readonly HwyJoinTasjilRegisteredFilterOption[] = [
  {
    value: HWY_JOIN_TASJIL_STATE_CODE_REGISTERED,
    labelKey: 'hwy.members.legacyFilter.joinTasjilRegistered',
    labelFallback: 'Registered',
  },
  {
    value: HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED,
    labelKey: 'hwy.members.legacyFilter.joinTasjilUnregistered',
    labelFallback: 'Not registered',
  },
];

export const isHwyJoinTasjilRegisteredFilterCode = (value: string): boolean => (
  value === HWY_JOIN_TASJIL_STATE_CODE_REGISTERED
  || value === HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED
);
