/** Legacy `HWY_BaseInformation` parent for Iraqi governorates (محافظة). */
export const LEGACY_PROVINCE_BASE_INFO_PARENT_ID = 10101;

export const GEO_ETL_IRAQ_SHORT_NAME = 'hwy-iraq';
export const GEO_ETL_IRAQ_TITLE = 'Iraq';

export const GEO_LEGACY_KINDS = [
  'province',
  'circle',
  'maktab',
  'region',
  'ghavateh',
] as const;

export type GeoLegacyKind = (typeof GEO_LEGACY_KINDS)[number];

export const geoMapKey = (
  kind: GeoLegacyKind,
  legacyId: number,
  legacySecondaryId = 0,
): string => `${kind}:${legacyId}:${legacySecondaryId}`;
