import type { HwyEtlRunOptions, HwyEtlSyncMode } from '../../shared/api/contracts/hwy/etlConsole';

/** Env flags that trigger delete/replace before import — off in incremental mode. */
export const HWY_ETL_REPLACE_ENV_KEYS = [
  'HWY_ETL_GEO_REPLACE',
  'HWY_ETL_REPLACE',
  'HWY_ETL_REPLACE_CHANGE_HISTORY',
  'HWY_ETL_REPLACE_SATELLITES',
  'HWY_ETL_COURSES_ACTIVITIES_REPLACE',
  'HWY_ETL_SATELLITE_CLEAR_ONLY',
] as const;

export const applyHwyEtlSyncMode = (
  options: HwyEtlRunOptions = {},
): HwyEtlRunOptions => {
  if (options.syncMode !== 'incremental') {
    return options;
  }

  const env: Record<string, string | number | boolean> = { ...(options.env ?? {}) };
  for (const key of HWY_ETL_REPLACE_ENV_KEYS) {
    env[key] = false;
  }

  return {
    ...options,
    env,
  };
};

export const resolveHwyEtlSyncMode = (options: HwyEtlRunOptions = {}): HwyEtlSyncMode => (
  options.syncMode === 'replace' ? 'replace' : 'incremental'
);

export const stepSupportsIncremental = (stepId: string): boolean => {
  if (stepId === 'reset-hwy-import-target' || stepId === 'geo-rollback') {
    return false;
  }
  if (stepId === 'orchestrator-all' || stepId === 'orchestrator-fast-full') {
    return true;
  }
  return !stepId.startsWith('probe-') && stepId !== 'diag-etl-status';
};
