import type { WhereOptions } from 'sequelize';

import {
  HWY_JOIN_TASJIL_STATE_CODE_REGISTERED,
  HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED,
  isHwyJoinTasjilRegisteredFilterCode,
} from '../../../domain/hwy/hwyMemberListLegacyFieldFilterJoinTasjilRegistered';
import { parseFilterQuery } from '../../services/data-api/dataApiQuery';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';

const NAKHEBIN_JOIN_TASJIL_STATE_CATEGORY = 'Nakhebin Join Tasjil State';

type JoinTasjilRegisteredFilterDbCodes = Partial<
  Record<typeof HWY_JOIN_TASJIL_STATE_CODE_REGISTERED | typeof HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED, string>
>;

let cachedJoinTasjilRegisteredFilterDbCodes: JoinTasjilRegisteredFilterDbCodes | null = null;

const loadJoinTasjilRegisteredFilterDbCodes = async (): Promise<JoinTasjilRegisteredFilterDbCodes> => {
  if (cachedJoinTasjilRegisteredFilterDbCodes) {
    return cachedJoinTasjilRegisteredFilterDbCodes;
  }
  const [registeredBiometric, unregistered] = await Promise.all([
    tryFindHwyBaseInfoItemIdByShortName(
      NAKHEBIN_JOIN_TASJIL_STATE_CATEGORY,
      HWY_JOIN_TASJIL_STATE_CODE_REGISTERED,
    ),
    tryFindHwyBaseInfoItemIdByShortName(
      NAKHEBIN_JOIN_TASJIL_STATE_CATEGORY,
      HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED,
    ),
  ]);
  cachedJoinTasjilRegisteredFilterDbCodes = {
    ...(registeredBiometric ? { [HWY_JOIN_TASJIL_STATE_CODE_REGISTERED]: registeredBiometric } : {}),
    ...(unregistered ? { [HWY_JOIN_TASJIL_STATE_CODE_UNREGISTERED]: unregistered } : {}),
  };
  return cachedJoinTasjilRegisteredFilterDbCodes;
};

/** UI / toolbar semantic short name from `filter[nakhebinJoinTasjilStateCode][eq]`. */
export const parseHwyMemberDirectoryListJoinTasjilRegisteredFilter = (
  query: Record<string, unknown>,
): string | undefined => {
  const eq = parseFilterQuery(query).nakhebinJoinTasjilStateCode?.eq?.trim();
  if (!eq || !isHwyJoinTasjilRegisteredFilterCode(eq)) {
    return undefined;
  }
  return eq;
};

/**
 * Member rows store platform Base Info ids in `nakhebin_join_tasjil_state_code` (ETL parity),
 * not semantic short names — map toolbar values before SQL / Sequelize where.
 */
export const resolveHwyMemberDirectoryListJoinTasjilRegisteredFilterDbCode = async (
  filterShortName: string,
): Promise<string | undefined> => {
  if (!isHwyJoinTasjilRegisteredFilterCode(filterShortName)) {
    return undefined;
  }
  const map = await loadJoinTasjilRegisteredFilterDbCodes();
  return map[filterShortName];
};

/** Resolved DB code for list query (semantic short name or already a platform id). */
export const resolveHwyMemberDirectoryListJoinTasjilFilterEqToDbCode = async (
  query: Record<string, unknown>,
): Promise<string | undefined> => {
  const eq = parseFilterQuery(query).nakhebinJoinTasjilStateCode?.eq?.trim();
  if (!eq) {
    return undefined;
  }
  if (isHwyJoinTasjilRegisteredFilterCode(eq)) {
    return resolveHwyMemberDirectoryListJoinTasjilRegisteredFilterDbCode(eq);
  }
  return eq;
};

export const omitJoinTasjilRegisteredFilterFromWhere = (where: WhereOptions): WhereOptions => {
  if (!where || typeof where !== 'object' || Array.isArray(where)) {
    return where;
  }
  const next = { ...(where as Record<string, unknown>) };
  delete next.nakhebinJoinTasjilStateCode;
  return next;
};

/** Test hook — Base Info seed changes between runs. */
export const resetHwyMemberDirectoryListJoinTasjilFilterCacheForTests = (): void => {
  cachedJoinTasjilRegisteredFilterDbCodes = null;
};
