export const HWY_MONTADHEMIN_MEMBER_LIST_LEGACY_SCOPE = 'HWY_Members_List_AlMontadhemin' as const;

export const shouldEnrichMemberInstitutesSummaryForListScope = (
  listScopeLegacy: string | null | undefined,
): boolean => listScopeLegacy?.trim() === HWY_MONTADHEMIN_MEMBER_LIST_LEGACY_SCOPE;

