import { QueryTypes } from 'sequelize';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;

const applySelfRegistrationMemberColumns = async (): Promise<void> => {
  const sequelize = getControlPlaneSequelize();
  await sequelize.query(
    `
    IF COL_LENGTH(N'dbo.hwy_members', N'registration_channel_code') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_members ADD registration_channel_code NVARCHAR(1000) NULL;
    END

    IF COL_LENGTH(N'dbo.hwy_members', N'tosigh_confirm_code') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_members ADD tosigh_confirm_code INT NULL;
    END
    `,
    { type: QueryTypes.RAW },
  );
};

/** Idempotent DDL so public self-registration submit works on older hwy_members tables. */
export const ensureHwyMembersSelfRegistrationSchema = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = applySelfRegistrationMemberColumns();
  }

  await ensurePromise;
};
