  ammah: 100,
  gov: 101,
  mehani: 102,
  hemam: 103,
  aslaa: 104,
  political_office: 105,
  exec_office: 106,
  exec_staff: 107,
  ashaaer: 108,
  shabab: 109,
  waedoon: 110,
