import type { Sequelize, WhereOptions } from 'sequelize';
import { Op } from 'sequelize';
import { HWY_MONTADHEMIN_MEMBER_LIST_LEGACY_SCOPE } from '../../../domain/hwy/hwyMemberInstitutesGridColumn';
import {
  DEFAULT_FILTER_MATCH_LOGIC,
  parseFilterMatchLogic,
  type FilterMatchLogic,
} from '../../../shared/lib/filterMatchLogic';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';

const memberInstitutesTable = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql' ? 'dbo.hwy_member_institutes' : 'hwy_member_institutes'
);

const parsePositiveIntList = (raw: unknown): number[] => {
  if (raw === null || raw === undefined || raw === '') {
    return [];
  }
  const parts = Array.isArray(raw)
    ? raw
    : String(raw).split(',');
  const ids = new Set<number>();
  for (const part of parts) {
    const n = Number(String(part).trim());
    if (Number.isFinite(n) && n > 0) {
      ids.add(n);
    }
  }
  return [...ids];
};

/** Toolbar multi-select on `hwy-members-montadhemin` — active institute membership. */
export const parseHwyMontadheminInstituteIdsFilter = (
  query: Record<string, unknown>,
  listScopeLegacy: string | null | undefined,
): number[] => {
  if (listScopeLegacy?.trim() !== HWY_MONTADHEMIN_MEMBER_LIST_LEGACY_SCOPE) {
    return [];
  }
  const nested = query.filter;
  if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
    const field = (nested as Record<string, unknown>).montadheminInstituteId;
    if (field && typeof field === 'object' && !Array.isArray(field)) {
      const fromIn = parsePositiveIntList((field as Record<string, unknown>).in);
      if (fromIn.length > 0) {
        return fromIn;
      }
    }
  }
  return parsePositiveIntList(query['filter[montadheminInstituteId][in]']);
};

/** OR = any selected institute; AND = member must belong to every selected institute (active). */
export const parseHwyMontadheminInstituteMatchFilter = (
  query: Record<string, unknown>,
  listScopeLegacy: string | null | undefined,
): FilterMatchLogic => {
  if (listScopeLegacy?.trim() !== HWY_MONTADHEMIN_MEMBER_LIST_LEGACY_SCOPE) {
    return DEFAULT_FILTER_MATCH_LOGIC;
  }
  const raw = query.montadheminInstituteMatch ?? query['montadheminInstituteMatch'];
  return parseFilterMatchLogic(raw);
};

const buildMontadheminInstituteMemberSubquery = (
  sequelize: Sequelize,
  table: string,
  instituteIds: readonly number[],
  instituteStatusCode: string,
  matchLogic: FilterMatchLogic,
  indexHint: string,
): string => {
  const idList = instituteIds.map((id) => sequelize.escape(id)).join(', ');
  const status = sequelize.escape(instituteStatusCode);
  const distinctIds = new Set(instituteIds);
  if (matchLogic === 'and' && distinctIds.size > 1) {
    return `(SELECT mi.member_id FROM ${table} mi${indexHint} WHERE mi.institute_id IN (${idList}) AND mi.status_code = ${status} GROUP BY mi.member_id HAVING COUNT(DISTINCT mi.institute_id) = ${distinctIds.size})`;
  }
  return `(SELECT DISTINCT mi.member_id FROM ${table} mi${indexHint} WHERE mi.institute_id IN (${idList}) AND mi.status_code = ${status})`;
};

/** Fast path — `AND m.id IN (...)` on dbo.hwy_members (avoids vw_hwy_members + Sequelize literal IN). */
export const buildHwyMontadheminInstituteFilterSqlClause = async (
  sequelize: Sequelize,
  instituteIds: readonly number[],
  matchLogic: FilterMatchLogic = DEFAULT_FILTER_MATCH_LOGIC,
): Promise<{ sql: string; replacements: Record<string, unknown> }> => {
  if (instituteIds.length === 0) {
    return { sql: '', replacements: {} };
  }
  const ctx = await loadHwyMemberListScopeContext();
  const table = memberInstitutesTable(sequelize);
  const indexHint = sequelize.getDialect() === 'mssql'
    ? ' WITH (INDEX(idx_hwy_member_institutes_scope))'
    : '';
  const subquery = buildMontadheminInstituteMemberSubquery(
    sequelize,
    table,
    instituteIds,
    ctx.instituteMembershipActiveCode,
    matchLogic,
    indexHint,
  );
  return {
    sql: `AND m.id IN ${subquery}`,
    replacements: {},
  };
};

export const buildHwyMontadheminInstituteFilterWhere = async (
  sequelize: Sequelize,
  instituteIds: readonly number[],
  matchLogic: FilterMatchLogic = DEFAULT_FILTER_MATCH_LOGIC,
): Promise<WhereOptions> => {
  if (instituteIds.length === 0) {
    return {};
  }
  const ctx = await loadHwyMemberListScopeContext();
  const table = memberInstitutesTable(sequelize);
  const indexHint = sequelize.getDialect() === 'mssql'
    ? ' WITH (INDEX(idx_hwy_member_institutes_scope))'
    : '';
  const memberSubquery = buildMontadheminInstituteMemberSubquery(
    sequelize,
    table,
    instituteIds,
    ctx.instituteMembershipActiveCode,
    matchLogic,
    indexHint,
  );
  return {
    id: {
      [Op.in]: sequelize.literal(memberSubquery),
    },
  };
};
