/** Appended membership decision notes use `Reason title: explanation` (see formatDecisionNote). */
export function splitHwyMembershipDecisionNoteBody(body: string): {
  reasonTitle: string;
  note: string;
} {
  const trimmed = String(body ?? '').trim();
  if (!trimmed) {
    return { reasonTitle: '', note: '' };
  }
  const colonIndex = trimmed.indexOf(': ');
  if (colonIndex > 0 && colonIndex <= 120) {
    const reasonTitle = trimmed.slice(0, colonIndex).trim();
    const note = trimmed.slice(colonIndex + 2).trim();
    if (reasonTitle && note) {
      return { reasonTitle, note };
    }
  }
  return { reasonTitle: '', note: trimmed };
}

export const HWY_MEMBERSHIP_DECISION_NOTE_SUBJECT_PRIORITY = [
  'local_verification',
  'membership',
  'call_center',
  'general',
  'security',
  'nakhebin',
] as const;

export function rankHwyMembershipDecisionNoteSubject(shortName: string | null | undefined): number {
  const normalized = String(shortName ?? '').trim();
  const index = HWY_MEMBERSHIP_DECISION_NOTE_SUBJECT_PRIORITY.indexOf(
    normalized as (typeof HWY_MEMBERSHIP_DECISION_NOTE_SUBJECT_PRIORITY)[number],
  );
  return index >= 0 ? index : HWY_MEMBERSHIP_DECISION_NOTE_SUBJECT_PRIORITY.length;
}
