import {
  connectLegacyReadPool,
  fetchLegacyPlatformRolesByAction,
} from '../../../../scripts/hwy-etl/legacyHwyRoleAuth';
import {
  buildHwyEmployeesListPortalAllowRoles,
  HWY_EMPLOYEES_LIST_LEGACY_READ,
} from '../../../domain/hwy/hwyEmployeesListLegacyAccess';

const CACHE_MS = 30_000;
let portalRolesCache: { roles: string[]; loadedAt: number } | null = null;

export async function resolveHwyEmployeesListAllowRoles(): Promise<string[]> {
  const now = Date.now();
  if (portalRolesCache && now - portalRolesCache.loadedAt < CACHE_MS) {
    return portalRolesCache.roles;
  }
  try {
    const pool = await connectLegacyReadPool();
    let byAction: Awaited<ReturnType<typeof fetchLegacyPlatformRolesByAction>>;
    try {
      byAction = await fetchLegacyPlatformRolesByAction(pool, [HWY_EMPLOYEES_LIST_LEGACY_READ]);
    } finally {
      await pool.close();
    }
    const roles = buildHwyEmployeesListPortalAllowRoles(byAction);
    portalRolesCache = { roles: roles.length > 0 ? roles : ['ADMIN'], loadedAt: now };
    return portalRolesCache.roles;
  } catch {
    return ['ADMIN'];
  }
}

export async function assertHwyEmployeesListAccess(roleNames: readonly string[]): Promise<void> {
  if (roleNames.includes('ADMIN')) return;
  const allowed = await resolveHwyEmployeesListAllowRoles();
  if (allowed.some((role) => roleNames.includes(role))) return;
  throw new Error('Forbidden.');
}
