import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';

export type HwyInstituteScopedEditConfigRow = {
  instituteCode: string;
  allowsListScopedEdit: boolean;
  showInstituteCharacterInDossier: boolean;
};

export const listHwyInstituteScopedEditConfig = async (): Promise<HwyInstituteScopedEditConfigRow[]> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    code: string;
    allows_list_scoped_edit: boolean | number;
    show_institute_character_in_dossier: boolean | number;
  }>(
    `
    SELECT
      i.code,
      i.allows_list_scoped_edit,
      i.show_institute_character_in_dossier
    FROM dbo.hwy_institutes i
    WHERE i.is_active = 1
    `,
    { type: QueryTypes.SELECT },
  );
  return rows.map((row) => ({
    instituteCode: String(row.code).trim().toLowerCase(),
    allowsListScopedEdit: Boolean(row.allows_list_scoped_edit),
    showInstituteCharacterInDossier: Boolean(row.show_institute_character_in_dossier),
  }));
};

export const loadHwyInstituteScopedEditConfigByCode = async (
  instituteCode: string,
): Promise<HwyInstituteScopedEditConfigRow | null> => {
  const normalized = instituteCode.trim().toLowerCase();
  if (!normalized) {
    return null;
  }
  const rows = await listHwyInstituteScopedEditConfig();
  return rows.find((row) => row.instituteCode === normalized) ?? null;
};
