import { QueryTypes } from 'sequelize';
import type { Sequelize } from 'sequelize';
import {
  HWY_MEMBER_IDENTITY_RESTRICTED_INSTITUTE_IDS,
  type HwyMemberIdentityInstitutePhoneContext,
} from '../../../domain/hwy/hwyMemberIdentityFieldMask';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';

export type MemberIdentityInstitutePhoneMap = Map<string, HwyMemberIdentityInstitutePhoneContext>;

const parseMemberId = (raw: unknown): string | null => {
  if (raw === null || raw === undefined) {
    return null;
  }
  const text = String(raw).trim();
  return text || null;
};

export async function loadHwyMemberIdentityInstitutePhoneMap(
  sequelize: Sequelize,
  memberIds: ReadonlyArray<string | number>,
): Promise<MemberIdentityInstitutePhoneMap> {
  const ids = [...new Set(memberIds.map((id) => String(id).trim()).filter(Boolean))];
  const result: MemberIdentityInstitutePhoneMap = new Map();
  if (ids.length === 0) {
    return result;
  }

  const scope = await loadHwyMemberListScopeContext();
  const restrictedList = HWY_MEMBER_IDENTITY_RESTRICTED_INSTITUTE_IDS.join(', ');
  const dialect = sequelize.getDialect();
  const stringAgg = dialect === 'mssql'
    ? `STRING_AGG(i.title_ar, N' , ')`
    : `STRING_AGG(i.title_ar, ' , ')`;

  const rows = await sequelize.query<{
    member_id: string | number;
    approved_restricted_orgs_count: number | string;
    orgs_membership_summary: string | null;
  }>(
    `
      SELECT
        mi.member_id,
        SUM(CASE WHEN mi.institute_id IN (${restrictedList}) THEN 1 ELSE 0 END) AS approved_restricted_orgs_count,
        ${stringAgg} AS orgs_membership_summary
      FROM ${dialect === 'mssql' ? 'dbo.hwy_member_institutes' : 'hwy_member_institutes'} mi
      INNER JOIN ${dialect === 'mssql' ? 'dbo.hwy_institutes' : 'hwy_institutes'} i
        ON i.id = mi.institute_id
      WHERE mi.member_id IN (:memberIds)
        AND mi.member_accepted = 1
        AND mi.status_code = :activeStatusCode
      GROUP BY mi.member_id
    `,
    {
      replacements: {
        memberIds: ids.map((id) => Number(id)),
        activeStatusCode: scope.instituteMembershipActiveCode,
      },
      type: QueryTypes.SELECT,
    },
  );

  for (const row of rows) {
    const memberId = parseMemberId(row.member_id);
    if (!memberId) {
      continue;
    }
    result.set(memberId, {
      approvedRestrictedOrgsCount: Number(row.approved_restricted_orgs_count ?? 0) || 0,
      orgsMembershipSummary: String(row.orgs_membership_summary ?? '').trim(),
    });
  }

  for (const id of ids) {
    if (!result.has(id)) {
      result.set(id, { approvedRestrictedOrgsCount: 0, orgsMembershipSummary: '' });
    }
  }

  return result;
}

export const readMemberIdentityInstitutePhoneContext = (
  map: MemberIdentityInstitutePhoneMap,
  memberId: unknown,
): HwyMemberIdentityInstitutePhoneContext => {
  const id = parseMemberId(memberId);
  if (!id) {
    return { approvedRestrictedOrgsCount: 0, orgsMembershipSummary: '' };
  }
  return map.get(id) ?? { approvedRestrictedOrgsCount: 0, orgsMembershipSummary: '' };
};
