/** Pure helpers for Hawiety incremental sync-changes planning. */

export type HwyEtlSyncTargetParts = {
  legacyUpdatedMemberIds: number[];
  changeHistoryMemberIds: number[];
  /** Members already known to exist locally (filters change-history noise). */
  localMemberIdSet: ReadonlySet<number>;
};

export const mergeHwyEtlSyncTargetMemberIds = (parts: HwyEtlSyncTargetParts): number[] => {
  const out = new Set<number>();
  for (const id of parts.legacyUpdatedMemberIds) {
    if (id > 0 && parts.localMemberIdSet.has(id)) out.add(id);
  }
  for (const id of parts.changeHistoryMemberIds) {
    if (id > 0 && parts.localMemberIdSet.has(id)) out.add(id);
  }
  return [...out].sort((a, b) => a - b);
};

/** Lower bound for legacy UpdatedOn queries (exclusive). */
export const resolveLegacyMemberUpdatedSince = (
  lastLegacyMemberUpdatedOn: string | null,
  overrideIso?: string | null,
): Date => {
  const raw = overrideIso?.trim() || lastLegacyMemberUpdatedOn?.trim();
  if (raw) {
    const parsed = Date.parse(raw);
    if (!Number.isNaN(parsed)) return new Date(parsed);
  }
  return new Date(0);
};

export const nextChangeHistoryCursor = (lastChangeHistoryId: number): number => (
  Math.max(0, lastChangeHistoryId)
);
