import { QueryTypes } from 'sequelize';

import type { HwyRegistrationChannelShortName } from '../../../domain/hwy/hwyRegistrationChannel';
import { isDedicatedHwyInstituteRegistrationChannel } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationInstituteChannels';
import { LEGACY_REFERRER_INSTITUTE_CODE_TO_ID } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationInstituteDefaults';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';

const resolveInstitutesTable = (dialect: string): string =>
  dialect === 'mssql' ? 'dbo.hwy_institutes' : 'hwy_institutes';

async function lookupActiveInstituteIdByCode(code: string): Promise<number | null> {
  const trimmed = code.trim();
  if (!trimmed) {
    return null;
  }
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const table = resolveInstitutesTable(sequelize.getDialect());
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM ${table} WHERE code = :code AND is_active = 1`,
    {
      type: QueryTypes.SELECT,
      replacements: { code: trimmed },
    },
  );
  const id = rows[0]?.id;
  return typeof id === 'number' && Number.isFinite(id) && id > 0 ? id : null;
}

/** Resolve target institute for a public self-registration channel (DB-backed institute code). */
export async function resolveHwySelfRegistrationInstituteId(input: {
  channel: HwyRegistrationChannelShortName;
  referrerInstituteCode?: string | null;
}): Promise<number | null> {
  const referrer = input.referrerInstituteCode?.trim();
  if (referrer) {
    const legacyId = LEGACY_REFERRER_INSTITUTE_CODE_TO_ID[referrer];
    if (legacyId != null) {
      return legacyId;
    }
    return lookupActiveInstituteIdByCode(referrer);
  }

  if (!isDedicatedHwyInstituteRegistrationChannel(input.channel)) {
    return null;
  }

  return lookupActiveInstituteIdByCode(input.channel);
}
