import {
  HWY_PRIMARY_SELF_REGISTRATION_CHANNEL,
  type HwyRegistrationChannelShortName,
} from '../hwyRegistrationChannel';

/** Channels that are not tied to a single `hwy_institutes` row by URL suffix / channel code. */
export const HWY_NON_INSTITUTE_REGISTRATION_CHANNELS = new Set<HwyRegistrationChannelShortName>([
  HWY_PRIMARY_SELF_REGISTRATION_CHANNEL,
  'mobile_app',
  'other_portal',
]);

export const isDedicatedHwyInstituteRegistrationChannel = (
  channel: HwyRegistrationChannelShortName,
): boolean => !HWY_NON_INSTITUTE_REGISTRATION_CHANNELS.has(channel);
