import { normalizeHwyHouseholdMemberId } from '../../../domain/hwy/hwyFamilyHouseholdMemberId';



const readStringField = (row: Record<string, unknown>, field: string): string => {

  const snake = field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`);

  const raw = row[field] ?? row[snake];

  if (raw === null || raw === undefined) {

    return '';

  }

  return String(raw).trim();

};



const readNakhebinMemberId = (row: Record<string, unknown>): string => (

  normalizeHwyHouseholdMemberId(row.memberId ?? row.member_id)

);



const readMemberNakhebinId = (row: Record<string, unknown>): string => (

  normalizeHwyHouseholdMemberId(row.nakhebinId ?? row.nakhebin_id)

);



/**

 * Member rows often lack `gender_code` while the linked nakhebin voter row has it.

 * Household API backfills member display fields only when the member row is empty.

 */

export const attachHouseholdMemberGenderFromLinkedNakhebin = (

  members: Record<string, unknown>[],

  nakhebin: Record<string, unknown>[],

): void => {

  if (members.length === 0 || nakhebin.length === 0) {

    return;

  }



  const nakhebinByMemberId = new Map<string, Record<string, unknown>>();

  const nakhebinById = new Map<string, Record<string, unknown>>();

  for (const row of nakhebin) {

    const id = normalizeHwyHouseholdMemberId(row.id);

    if (id) {

      nakhebinById.set(id, row);

    }

    const memberId = readNakhebinMemberId(row);

    if (memberId) {

      nakhebinByMemberId.set(memberId, row);

    }

  }



  for (const member of members) {

    if (readStringField(member, 'genderCodeTitle')) {

      continue;

    }



    const memberId = normalizeHwyHouseholdMemberId(member.id);

    let linked = memberId ? nakhebinByMemberId.get(memberId) : undefined;

    if (!linked) {

      const nakhebinId = readMemberNakhebinId(member);

      if (nakhebinId) {

        linked = nakhebinById.get(nakhebinId);

      }

    }

    if (!linked) {

      continue;

    }



    if (!readStringField(member, 'genderCode')) {

      const code = readStringField(linked, 'genderCode');

      if (code) {

        member.genderCode = code;

      }

    }

    const title = readStringField(linked, 'genderCodeTitle');

    if (title) {

      member.genderCodeTitle = title;

    }

  }

};


