import {
  pickHwyMemberStatRowValue,
  type HwyMemberStatRow,
} from '../../../domain/hwy/hwyMemberStatRecalcDisplay';
import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { execHwyProcedure } from './hwyExecDbObject';

const LEGACY_STAT_CACHE_TTL_MS = 90_000;
const legacyStatCache = new Map<number, { row: HwyMemberStatRow; at: number }>();

const LEGACY_MEMBER_STATS_SELECT = `
  SELECT
    Stat_FieldsCompleted AS statFieldsCompleted,
    Stat_Days AS statDays,
    Stat_DoratCount AS statDoratCount,
    Stat_KasbCount AS statKasbCount,
    Stat_NashatatCount AS statNashatatCount,
    Stat_Moassesat_Count AS statMoassesatCount,
    Stat_Moghabelat_2022_Count AS statInterviews2022Count,
    Stat_CardsCount AS statCardsCount,
    Stat2_HasPassedAll AS statHasPassedAll,
    Stat2_HasNotTosighOlderThanXDays AS statHasNotTosighOlderThanXDays,
    Stat_Vasaegh_Count AS statVasaeghCount,
    Stat_IsEmployee AS statIsEmployee,
    Stat_AdamTatbighCount AS statAdamTatbighCount,
    Stat_Points AS statPoints
  FROM dbo.HWY_Members WITH (NOLOCK)
  WHERE Id = @memberId
`;

/** Legacy MembersV2: full UpdateStats then read stat columns (parity with HawietySite). */
export const runLegacyMemberUpdateStatsAndRead = async (
  memberId: number,
): Promise<HwyMemberStatRow | null> => {
  try {
    const { readLegacyConn } = await import('../../../../scripts/hwy-etl/legacyConn');
    const sql = await import('mssql');
    const pool = await new sql.ConnectionPool(readLegacyConn()).connect();
    try {
      const update = await pool
        .request()
        .input('MemberId', sql.BigInt, memberId)
        .query(`
          IF OBJECT_ID(N'dbo.HWY_SP_Members_UpdateStats', N'P') IS NULL
            SELECT CAST(0 AS BIT) AS ok;
          ELSE
          BEGIN
            EXEC dbo.HWY_SP_Members_UpdateStats @MemberId = @MemberId;
            SELECT CAST(1 AS BIT) AS ok;
          END
        `);
      const ok = Boolean(update.recordset[0]?.ok);
      if (!ok) {
        return null;
      }
      const read = await pool
        .request()
        .input('MemberId', sql.BigInt, memberId)
        .query(LEGACY_MEMBER_STATS_SELECT);
      const row = read.recordset[0] as HwyMemberStatRow | undefined;
      return row ?? null;
    } finally {
      await pool.close();
    }
  } catch {
    return null;
  }
};

export const resolveLegacyMemberStatRow = async (
  memberId: number,
  refresh: boolean,
): Promise<HwyMemberStatRow | null> => {
  const cached = legacyStatCache.get(memberId);
  if (!refresh && cached && Date.now() - cached.at < LEGACY_STAT_CACHE_TTL_MS) {
    return cached.row;
  }
  const row = await runLegacyMemberUpdateStatsAndRead(memberId);
  if (row) {
    legacyStatCache.set(memberId, { row, at: Date.now() });
  }
  return row;
};

export const syncEdgeMemberStatsFromRow = async (
  memberId: number,
  row: HwyMemberStatRow,
): Promise<void> => {
  const pick = (...keys: string[]): unknown => pickHwyMemberStatRowValue(row, ...keys);
  const sequelize = getControlPlaneSequelize();
  await execHwyProcedure('hwy_member_stat_recalc_require_member', { member_id: memberId });
  await sequelize.query(
    `
    UPDATE dbo.hwy_members
    SET
      stat_fields_completed = :statFieldsCompleted,
      stat_days = :statDays,
      stat_dorat_count = :statDoratCount,
      stat_kasb_count = :statKasbCount,
      stat_nashatat_count = :statNashatatCount,
      stat_moassesat_count = :statMoassesatCount,
      stat_interviews_2022_count = :statInterviews2022Count,
      stat_cards_count = :statCardsCount,
      stat_has_passed_all = :statHasPassedAll,
      stat_has_not_tosigh_older_than_x_days = :statHasNotTosighOlderThanXDays,
      stat_vasaegh_count = :statVasaeghCount,
      stat_is_employee = :statIsEmployee,
      stat_adam_tatbigh_count = :statAdamTatbighCount,
      stat_points = :statPoints
    WHERE id = :member_id
    `,
    {
      replacements: {
        member_id: memberId,
        statFieldsCompleted: pick('statFieldsCompleted', 'Stat_FieldsCompleted'),
        statDays: pick('statDays', 'Stat_Days'),
        statDoratCount: pick('statDoratCount', 'Stat_DoratCount'),
        statKasbCount: pick('statKasbCount', 'Stat_KasbCount'),
        statNashatatCount: pick('statNashatatCount', 'Stat_NashatatCount'),
        statMoassesatCount: pick('statMoassesatCount', 'Stat_Moassesat_Count'),
        statInterviews2022Count: pick('statInterviews2022Count', 'Stat_Moghabelat_2022_Count'),
        statCardsCount: pick('statCardsCount', 'Stat_CardsCount'),
        statHasPassedAll: pick('statHasPassedAll', 'Stat2_HasPassedAll'),
        statHasNotTosighOlderThanXDays: pick(
          'statHasNotTosighOlderThanXDays',
          'Stat2_HasNotTosighOlderThanXDays',
        ),
        statVasaeghCount: pick('statVasaeghCount', 'Stat_Vasaegh_Count'),
        statIsEmployee: pick('statIsEmployee', 'Stat_IsEmployee'),
        statAdamTatbighCount: pick('statAdamTatbighCount', 'Stat_AdamTatbighCount'),
        statPoints: pick('statPoints', 'Stat_Points'),
      },
      type: QueryTypes.UPDATE,
    },
  );
};
