import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyCoursesActivitiesSchema } from './ensureHwyCoursesActivitiesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { attachBaseInfoTitles } from './hwyMemberDossierSatellites.service';

export type HwyMemberActivityAttendanceRow = {
  id: string;
  activityId: string;
  activityTitle: string | null;
  activityDate: string | null;
  activityTypeCode: string | null;
  activityTypeCodeTitle?: string;
  createdAt: string;
  selfieSizeBytes: number | null;
};

export type HwyMemberCourseAttendanceRow = {
  id: string;
  courseId: string;
  courseDate: string | null;
  courseTypeCode: string | null;
  courseTypeCodeTitle?: string;
  courseSubtypeCode: string | null;
  courseSubtypeCodeTitle?: string;
  note: string | null;
  createdAt: string;
};

export const resolveHwyMemberDirectoryMemberId = async (raw: string): Promise<number> => {
  const trimmed = raw.trim();
  if (!trimmed) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  if (/^\d+$/.test(trimmed)) {
    const id = Number(trimmed);
    if (Number.isFinite(id) && id > 0) {
      const rows = await sequelize.query<{ id: number }>(
        `SELECT id FROM dbo.hwy_members WHERE id = :id`,
        { replacements: { id }, type: QueryTypes.SELECT },
      );
      if (rows.length) {
        return rows[0].id;
      }
    }
  }
  const byUsername = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.hwy_members WHERE username = :username`,
    { replacements: { username: trimmed }, type: QueryTypes.SELECT },
  );
  if (byUsername.length) {
    return byUsername[0].id;
  }
  throw new Error('Member not found.');
};

export async function countHwyMemberActivityAndCourseAttendances(memberIdRaw: string): Promise<{
  activities: number;
  courses: number;
}> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return { activities: 0, courses: 0 };
  }
  await ensureHwyCoursesActivitiesSchema();
  try {
    await ensureHwyDbObjects();
  } catch {
    /* See hwyCoursesActivitiesAdmin.service assertSqlServer. */
  }
  const memberId = await resolveHwyMemberDirectoryMemberId(memberIdRaw);
  const rows = await execHwyProcedure<{ activities: number; courses: number }>(
    'hwy_member_attendance_counts',
    { member_id: memberId },
  );
  const row = rows[0] ?? { activities: 0, courses: 0 };
  return {
    activities: Number(row.activities) || 0,
    courses: Number(row.courses) || 0,
  };
}

export async function listHwyMemberActivityAttendances(
  memberIdRaw: string,
  limit = 50,
  offset = 0,
  queryLang = 'iq',
): Promise<HwyMemberActivityAttendanceRow[]> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  await ensureHwyCoursesActivitiesSchema();
  try {
    await ensureHwyDbObjects();
  } catch {
    /* See hwyCoursesActivitiesAdmin.service assertSqlServer. */
  }
  const memberId = await resolveHwyMemberDirectoryMemberId(memberIdRaw);
  const take = Math.max(1, Math.min(200, limit));
  const skip = Math.max(0, offset);
  const rows = await execHwyProcedure<{
    id: number | string;
    activity_id: number | string;
    activity_title: string | null;
    activity_date: Date | string | null;
    activity_type_code: string | null;
    created_at: Date | string;
    selfie_size_bytes: number | null;
  }>('hwy_member_activity_attendances_list', {
    member_id: memberId,
    offset: skip,
    page_size: take,
  });
  const mapped: HwyMemberActivityAttendanceRow[] = rows.map((row) => ({
    id: String(row.id),
    activityId: String(row.activity_id),
    activityTitle: row.activity_title?.trim() || null,
    activityDate: row.activity_date ? new Date(row.activity_date).toISOString().slice(0, 10) : null,
    activityTypeCode: row.activity_type_code?.trim() || null,
    createdAt: new Date(row.created_at).toISOString(),
    selfieSizeBytes: row.selfie_size_bytes ?? null,
  }));
  const enrichRows = mapped as unknown as Record<string, unknown>[];
  await attachBaseInfoTitles(
    enrichRows,
    [{ codeField: 'activityTypeCode', titleField: 'activityTypeCodeTitle' }],
    queryLang,
  );
  return mapped.map((row, index) => ({
    ...row,
    activityTypeCodeTitle: String(enrichRows[index]?.activityTypeCodeTitle ?? '').trim() || undefined,
  }));
}

