import type sql from 'mssql';

let poolPromise: Promise<sql.ConnectionPool> | null = null;

/** Reuse one read-only legacy HWY SQL pool per dev/prod process (targhin list hot path). */
export async function getLegacyHwyReadPool(): Promise<sql.ConnectionPool> {
  if (!poolPromise) {
    poolPromise = (async () => {
      const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
      return connectLegacyReadPool();
    })().catch((error: unknown) => {
      poolPromise = null;
      throw error;
    });
  }
  return poolPromise;
}
