/**
 * Hawiety person names: legacy SQL `display_full_name` used " / " between parts — UI uses spaces only.
 */
export type HwyMemberNamePartsForFilterAnchor = {
  firstName: string;
  fatherName: string;
  grandfatherName: string;
  familyName: string;
};

/** Wizard nakhebin/similar filter readonly rows — DB columns first, else `displayFullName` tokens. */
export function resolveHwyMemberNamePartsForFilterAnchor(input: {
  firstname?: string | null;
  fathername?: string | null;
  grandfathername?: string | null;
  lastname?: string | null;
  displayFullName?: string | null;
}): HwyMemberNamePartsForFilterAnchor {
  const display = formatHwyMemberPersonDisplayName(input.displayFullName);
  const parts = display.split(/\s+/).filter(Boolean);
  const fromDisplay: HwyMemberNamePartsForFilterAnchor = {
    firstName: parts[0] ?? '',
    fatherName: parts[1] ?? '',
    grandfatherName: parts[2] ?? '',
    familyName: parts.slice(3).join(' '),
  };
  const firstName = String(input.firstname ?? '').trim() || fromDisplay.firstName;
  const fatherName = String(input.fathername ?? '').trim() || fromDisplay.fatherName;
  const grandfatherName = String(input.grandfathername ?? '').trim() || fromDisplay.grandfatherName;
  const familyName = String(input.lastname ?? '').trim() || fromDisplay.familyName;
  return { firstName, fatherName, grandfatherName, familyName };
}

/** Join Hawiety name columns for display (referrer lookup, dossier fields). */
export function buildHwyMemberPersonDisplayNameFromParts(input: {
  firstname?: string | null;
  fathername?: string | null;
  grandfathername?: string | null;
  lastname?: string | null;
}): string {
  return formatHwyMemberPersonDisplayName(
    [input.firstname, input.fathername, input.grandfathername, input.lastname]
      .map((part) => String(part ?? '').trim())
      .filter(Boolean)
      .join(' '),
  );
}

export const formatHwyMemberPersonDisplayName = (
  raw: string | null | undefined,
): string => {
  const text = String(raw ?? '').trim();
  if (!text) {
    return '';
  }
  if (!text.includes('/')) {
    return text.replace(/\s+/g, ' ');
  }
  return text
    .split(/\s*\/\s*/)
    .map((part) => part.trim())
    .filter(Boolean)
    .join(' ');
};
