import { logger } from '../../../core/logging/Logger';

import {
  defaultHwyPlatformPortalBrand,
  HWY_PLATFORM_PORTAL_BRAND_WINDOW_TITLE,
  HWY_PLATFORM_PORTAL_SHELL_KEY,
  isPlaceholderAppEndPortalBrand,
} from '../../../domain/hwy/hwyPlatformPortalBrandDefaults';
import { normalizePortalBrand } from '../../../shared/api/contracts/platform/portalBrand';
import { findPlatformShellByKey, updatePlatformShell } from '../platform/shellRepository';

const BOOTSTRAP_ACTOR = { userId: 1, username: 'hwy-portal-brand-bootstrap' };

/** One-time hygiene: hawiety portal shell brand defaults (identity + browser tab title). */
export const ensureHawietyPortalShellBrand = async (): Promise<void> => {
  const shell = await findPlatformShellByKey(HWY_PLATFORM_PORTAL_SHELL_KEY);
  if (!shell) {
    return;
  }

  const normalized = normalizePortalBrand(shell.brand);
  const needsPlaceholderUpgrade = isPlaceholderAppEndPortalBrand(shell.brand);
  const needsWindowTitle = !normalized?.windowTitle?.trim();

  if (!needsPlaceholderUpgrade && !needsWindowTitle) {
    return;
  }

  const brand = needsPlaceholderUpgrade
    ? defaultHwyPlatformPortalBrand()
    : {
      ...normalized,
      windowTitle: HWY_PLATFORM_PORTAL_BRAND_WINDOW_TITLE,
    };

  await updatePlatformShell(
    shell.shellKey,
    {
      name: shell.name,
      entry: shell.entry,
      surface: shell.surface,
      enabled: shell.enabled,
      entryMode: shell.entryMode ?? 'shell',
      redirectToSegment: shell.redirectToSegment ?? null,
      redirectToCulture: shell.redirectToCulture ?? null,
      notFoundPageRef: shell.notFoundPageRef ?? null,
      brand,
      auth: shell.auth ?? null,
      navigationRef: shell.navigationRef ?? null,
      source: shell.source ?? 'hwy-portal-brand-bootstrap',
    },
    BOOTSTRAP_ACTOR,
  );

  logger.info(
    'Server',
    needsPlaceholderUpgrade
      ? 'Hawiety portal shell brand upgraded from AppEnd placeholder.'
      : 'Hawiety portal shell browser tab title set.',
  );
};
