export type HwyMembershipDecisionReasonShortName = keyof typeof HWY_MEMBERSHIP_DECISION_REASON_LABELS_BY_SHORT_NAME;

export type HwyMembershipDecisionReasonOptionDto = {
  value: string;
  label: string;
  shortName?: string | null;
};

export function resolveHwyMembershipDecisionReasonDisplayLabel(input: {
  cultureId: string;
  label: string;
  shortName?: string | null;
  translate?: (key: string) => string;
}): string {
  const trimmedLabel = input.label.trim();
  const shortName = input.shortName?.trim() as HwyMembershipDecisionReasonShortName | undefined;
  const meta = shortName ? HWY_MEMBERSHIP_DECISION_REASON_LABELS_BY_SHORT_NAME[shortName] : undefined;

  if (meta) {
    const fromCulture = input.translate?.(meta.cultureKey)?.trim();
    if (fromCulture && fromCulture !== meta.cultureKey) {
      return fromCulture;
    }
    if (resolveBaseInfoCultureId(input.cultureId) === 'iq') {
      return meta.iq;
    }
    return meta.en;
  }

  const resolvedCulture = resolveBaseInfoCultureId(input.cultureId);
  if (trimmedLabel) {
    return resolveBaseInfoIqCanonicalTitle(resolvedCulture, trimmedLabel) ?? trimmedLabel;
  }
  return input.label;
}

/** English culture keys for Hawiety package sync (`buildHwyCultureKeysEn`). */
export const buildHwyMembershipDecisionReasonCultureKeysEn = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const meta of Object.values(HWY_MEMBERSHIP_DECISION_REASON_LABELS_BY_SHORT_NAME)) {
    keys[meta.cultureKey] = meta.en;
  }
  return keys;
};

/** Iraqi Arabic overlay entries (`keys.iq.json`). */
export const buildHwyMembershipDecisionReasonCultureKeysIq = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const meta of Object.values(HWY_MEMBERSHIP_DECISION_REASON_LABELS_BY_SHORT_NAME)) {
    keys[meta.cultureKey] = meta.iq;
  }
  return keys;
};
