import { LATIN_SLUG_RE, sanitizeLatinSlugInput, validateLatinSlug } from '../../../lib/latinSlug';
import {
  FILE_HUB_AUTH_METHODS,
  FILE_HUB_ENTRY_TYPES,
  FILE_HUB_PROTOCOLS,
  type FileHubAuthMethod,
  type FileHubEntryType,
  type FileHubProtocol,
} from './types';

export const FILE_HUB_DEFAULT_PORTS: Record<FileHubProtocol, number> = {
  sftp: 22,
  ftp: 21,
  ftps: 21,
};

export const FILE_HUB_MIN_PORT = 1;
export const FILE_HUB_MAX_PORT = 65535;
export const FILE_HUB_MAX_NAME_LENGTH = 80;
export const FILE_HUB_MAX_NOTE_LENGTH = 240;
export const FILE_HUB_MAX_TAGS = 16;
export const FILE_HUB_MAX_TAG_LENGTH = 32;
export const FILE_HUB_MAX_PATH_LENGTH = 1024;
export const FILE_HUB_MAX_ENTRY_NAME_LENGTH = 255;

const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)$/;
const HOSTNAME_RE = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])\.?$/i;
const IPV6_RE = /^(?:[0-9a-f]{0,4}:){2,7}[0-9a-f]{0,4}$/i;
const USERNAME_RE = /^[A-Za-z0-9._@\\-]{1,64}$/;
const CONTROL_CHARS_RE = /[\u0000-\u001f\u007f]/;

export function stripHostBrackets(host: string): string {
  const trimmed = host.trim();
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    return trimmed.slice(1, -1).trim();
  }
  return trimmed;
}

export function isWellFormedFileHubHost(host: string): boolean {
  const normalized = stripHostBrackets(host);
  if (!normalized || CONTROL_CHARS_RE.test(normalized)) {
    return false;
  }
  if (IPV4_RE.test(normalized) || IPV6_RE.test(normalized)) {
    return true;
  }
  return HOSTNAME_RE.test(normalized);
}

export function isWellFormedFileHubUsername(username: string): boolean {
  const trimmed = username.trim();
  return USERNAME_RE.test(trimmed) && !CONTROL_CHARS_RE.test(trimmed);
}

export function parseFileHubPort(value: unknown): number | null {
  const numeric = typeof value === 'number' ? value : Number(String(value ?? '').trim());
  if (!Number.isInteger(numeric) || numeric < FILE_HUB_MIN_PORT || numeric > FILE_HUB_MAX_PORT) {
    return null;
  }
  return numeric;
}

export function parseFileHubProtocol(value: unknown): FileHubProtocol | null {
  return typeof value === 'string' && (FILE_HUB_PROTOCOLS as readonly string[]).includes(value)
    ? value as FileHubProtocol
    : null;
}

export function parseFileHubAuthMethod(value: unknown): FileHubAuthMethod | null {
  return typeof value === 'string' && (FILE_HUB_AUTH_METHODS as readonly string[]).includes(value)
    ? value as FileHubAuthMethod
    : null;
}

export function parseFileHubEntryType(value: unknown): FileHubEntryType | null {
  return typeof value === 'string' && (FILE_HUB_ENTRY_TYPES as readonly string[]).includes(value)
    ? value as FileHubEntryType
    : null;
}

export function sanitizeFileHubDisplayName(raw: string): string {
  return raw.replace(CONTROL_CHARS_RE, '').trim().slice(0, FILE_HUB_MAX_NAME_LENGTH);
}

export function sanitizeFileHubNote(raw: string): string {
  return raw.replace(CONTROL_CHARS_RE, '').trim().slice(0, FILE_HUB_MAX_NOTE_LENGTH);
}

export function sanitizeFileHubTags(raw: unknown): string[] {
  if (!Array.isArray(raw)) {
    return [];
  }
  const seen = new Set<string>();
  const tags: string[] = [];
  for (const item of raw) {
    if (typeof item !== 'string') {
      continue;
    }
    const tag = item.replace(CONTROL_CHARS_RE, '').trim().slice(0, FILE_HUB_MAX_TAG_LENGTH);
    const key = tag.toLowerCase();
    if (!tag || seen.has(key)) {
      continue;
    }
    seen.add(key);
    tags.push(tag);
    if (tags.length >= FILE_HUB_MAX_TAGS) {
      break;
    }
  }
  return tags;
}

export function sanitizeFileHubConnectionKey(raw: string): string {
  return sanitizeLatinSlugInput(raw).slice(0, 64);
}

export function validateFileHubConnectionKey(value: string): string | null {
  const trimmed = value.trim();
  const slugError = validateLatinSlug(trimmed, { required: true, fieldLabel: 'Key' });
  if (slugError) {
    return slugError;
  }
  if (trimmed.length > 64) {
    return 'Key must be 64 characters or fewer.';
  }
  if (!LATIN_SLUG_RE.test(trimmed)) {
    return 'Key must use lowercase letters, numbers, dash, dot, and underscore only.';
  }
  return null;
}

export function validateFileHubHost(host: string): string | null {
  const normalized = stripHostBrackets(host);
  if (!normalized) {
    return 'Host is required.';
  }
  if (!isWellFormedFileHubHost(normalized)) {
    return 'Host must be a valid hostname or IP address.';
  }
  return null;
}

export function validateFileHubUsername(username: string): string | null {
  const trimmed = username.trim();
  if (!trimmed) {
    return 'Username is required.';
  }
  if (!isWellFormedFileHubUsername(trimmed)) {
    return 'Username may only contain letters, numbers, dot, underscore, at, and dash.';
  }
  return null;
}

export function validateFileHubDisplayName(name: string): string | null {
  const trimmed = sanitizeFileHubDisplayName(name);
  if (!trimmed) {
    return 'Name is required.';
  }
  return null;
}

export function protocolAllowsPrivateKey(protocol: FileHubProtocol): boolean {
  return protocol === 'sftp';
}

export function resolveFileHubAuthMethod(
  protocol: FileHubProtocol,
  requested: FileHubAuthMethod | null,
): FileHubAuthMethod {
  if (!protocolAllowsPrivateKey(protocol)) {
    return 'password';
  }
  return requested ?? 'password';
}

/** Normalize a remote POSIX path and reject traversal / control characters. */
export function sanitizeRemotePath(raw: unknown): string | null {
  if (typeof raw !== 'string') {
    return null;
  }
  if (raw.includes('\0') || CONTROL_CHARS_RE.test(raw)) {
    return null;
  }
  const trimmed = raw.replace(/\\/g, '/').trim();
  if (!trimmed) {
    return '/';
  }
  if (trimmed.length > FILE_HUB_MAX_PATH_LENGTH) {
    return null;
  }
  if (trimmed.includes('://') || /^[A-Za-z]:/.test(trimmed)) {
    return null;
  }

  const isAbsolute = trimmed.startsWith('/');
  const parts = trimmed.split('/');
  const stack: string[] = [];
  for (const part of parts) {
    if (!part || part === '.') {
      continue;
    }
    if (part === '..') {
      if (stack.length === 0) {
        if (isAbsolute) {
          continue;
        }
        return null;
      }
      stack.pop();
      continue;
    }
    if (part.length > FILE_HUB_MAX_ENTRY_NAME_LENGTH) {
      return null;
    }
    stack.push(part);
  }

  if (!isAbsolute) {
    return null;
  }
  return stack.length === 0 ? '/' : `/${stack.join('/')}`;
}

export function sanitizeRemoteEntryName(raw: unknown): string | null {
  if (typeof raw !== 'string') {
    return null;
  }
  const name = raw.replace(/\\/g, '/').replace(CONTROL_CHARS_RE, '').trim();
  if (!name || name === '.' || name === '..' || name.includes('/') || name.includes('\0')) {
    return null;
  }
  if (name.length > FILE_HUB_MAX_ENTRY_NAME_LENGTH) {
    return null;
  }
  return name;
}

export function joinRemotePath(directory: string, name: string): string | null {
  const base = sanitizeRemotePath(directory);
  const entry = sanitizeRemoteEntryName(name);
  if (!base || !entry) {
    return null;
  }
  if (base === '/') {
    return `/${entry}`;
  }
  return sanitizeRemotePath(`${base}/${entry}`);
}

export function parentRemotePath(remotePath: string): string {
  const sanitized = sanitizeRemotePath(remotePath) ?? '/';
  if (sanitized === '/') {
    return '/';
  }
  const index = sanitized.lastIndexOf('/');
  return index <= 0 ? '/' : sanitized.slice(0, index);
}

export function basenameRemotePath(remotePath: string): string {
  const sanitized = sanitizeRemotePath(remotePath) ?? '/';
  if (sanitized === '/') {
    return '';
  }
  return sanitized.slice(sanitized.lastIndexOf('/') + 1);
}

export function sanitizeInitialPath(raw: unknown): string {
  if (typeof raw !== 'string' || !raw.trim()) {
    return '';
  }
  const sanitized = sanitizeRemotePath(raw.trim());
  return sanitized && sanitized !== '/' ? sanitized : sanitized === '/' ? '/' : '';
}
