import { QueryTypes } from 'sequelize';

import type { HwyMemberListScopedEditPatchBody } from '../../../domain/hwy/hwyMemberListScopedEditClient';
import {
  resolveHwyMemberListScopedEditProfileForListScope,
  type HwyMemberListScopedEditKind,
} from '../../../domain/hwy/hwyMemberListScopedEditCatalog';
import { listHwyInstituteScopedEditConfig } from './hwyInstituteScopedEditConfig.service';
import { resolveHwyMemberListInstituteId } from '../../../domain/hwy/hwyMemberInstituteCodes';
import type { HwyMemberDirectoryPatchInput } from '../../../domain/hwy/hwyMemberDirectoryPatch';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';
import { patchHwyMemberDirectoryMember } from './hwyMemberDirectoryPatch.service';
import { invalidateHwyMemberDirectoryListCache } from './hwyMemberDirectoryListCache';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { attachBaseInfoTitles } from './hwyMemberDossierSatellites.service';
import { resolveActiveHwyBaseInfoLeafCode } from './hwyMemberMehaniBaseInfoCodes';

const trimOptional = (value: string | null | undefined, max = 4000): string | null => {
  if (value == null) {
    return null;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  return trimmed.length > max ? trimmed.slice(0, max) : trimmed;
};

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

let scopedEditAllowsCache: { loadedAt: number; codes: Set<string> } | null = null;
const SCOPED_EDIT_ALLOWS_CACHE_MS = 30_000;

const loadInstituteAllowsScopedEditSet = async (): Promise<Set<string>> => {
  const now = Date.now();
  if (scopedEditAllowsCache && now - scopedEditAllowsCache.loadedAt < SCOPED_EDIT_ALLOWS_CACHE_MS) {
    return scopedEditAllowsCache.codes;
  }
  const configRows = await listHwyInstituteScopedEditConfig();
  const codes = new Set(
    configRows.filter((row) => row.allowsListScopedEdit).map((row) => row.instituteCode),
  );
  scopedEditAllowsCache = { loadedAt: now, codes };
  return codes;
};

const resolveListScopedEditProfile = async (listScopeLegacy: string) => {
  const allowsScopedEdit = await loadInstituteAllowsScopedEditSet();
  return resolveHwyMemberListScopedEditProfileForListScope(listScopeLegacy, allowsScopedEdit);
};

export type HwyMemberListScopedEditLoadResult = {
  kind: HwyMemberListScopedEditKind;
  instituteCode: string | null;
  member: {
    id: string;
    displayFullName?: string | null;
    username?: string | null;
    jobTypeCode?: string | null;
    jobTypeCodeTitle?: string | null;
    jobPlace?: string | null;
    mehaniUnionCode?: string | null;
    mehaniUnionCodeTitle?: string | null;
    mehaniUnionDegreeCode?: string | null;
    mehaniUnionDegreeCodeTitle?: string | null;
    mehaniMembershipExpiresOn?: string | null;
  };
  characterCode?: string | null;
  characterCodeTitle?: string | null;
};

export async function loadHwyMemberListScopedEditFields(input: {
  memberIdRaw: string;
  listScopeLegacy: string;
  queryLang: string;
}): Promise<HwyMemberListScopedEditLoadResult> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('List scoped edit requires SQL Server control plane.');
  }
  const profile = await resolveListScopedEditProfile(input.listScopeLegacy);
  if (!profile) {
    throw new Error('List scoped edit is not available for this list.');
  }
  const memberId = parseMemberId(input.memberIdRaw);
  const sequelize = getControlPlaneSequelize();
  const memberRows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      CAST(m.id AS VARCHAR(32)) AS id,
      m.username,
      m.job_type_code AS jobTypeCode,
      m.job_place AS jobPlace,
      m.mehani_union_code AS mehaniUnionCode,
      m.mehani_union_degree_code AS mehaniUnionDegreeCode,
      CONVERT(VARCHAR(10), m.mehani_membership_expires_on, 23) AS mehaniMembershipExpiresOn,
      TRIM(CONCAT(
        COALESCE(m.first_name, N''), N' ',
        COALESCE(m.father_name, N''), N' ',
        COALESCE(m.grandfather_name, N''), N' ',
        COALESCE(m.family_name, N'')
      )) AS displayFullName
    FROM dbo.hwy_members m
    WHERE m.id = :memberId
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  const memberRow = memberRows[0];
  if (!memberRow) {
    throw new Error('Member not found.');
  }

  let characterCode: string | null = null;
  let characterCodeTitle: string | null = null;
  if (profile.kind === 'institute_character') {
    const instituteCode = profile.instituteCode?.trim();
    const instituteId = instituteCode ? resolveHwyMemberListInstituteId(instituteCode) : null;
    if (instituteId == null) {
      throw new Error('Institute is not configured for this list.');
    }
    const linkRows = await sequelize.query<{ characterCode: string | null }>(
      `
      SELECT TOP (1) mi.character_code AS characterCode
      FROM dbo.hwy_member_institutes mi
      WHERE mi.member_id = :memberId AND mi.institute_id = :instituteId
      ORDER BY mi.id DESC
      `,
      {
        replacements: { memberId, instituteId },
        type: QueryTypes.SELECT,
      },
    );
    characterCode = trimOptional(linkRows[0]?.characterCode ?? null, 128);
    if (characterCode) {
      const cultureId = resolveBaseInfoCultureId(input.queryLang);
      const enriched = await listBaseInfoEnrichmentRowsByIds([characterCode], cultureId);
      const title = enriched[0]?.title ?? enriched[0]?.title_canonical;
      characterCodeTitle = trimOptional(typeof title === 'string' ? title : null, 512);
    }
  }

  const enrichedMember: Record<string, unknown> = { ...memberRow };
  await attachBaseInfoTitles(
    [enrichedMember],
    [
      { codeField: 'jobTypeCode', titleField: 'jobTypeCodeTitle' },
      { codeField: 'mehaniUnionCode', titleField: 'mehaniUnionCodeTitle' },
      { codeField: 'mehaniUnionDegreeCode', titleField: 'mehaniUnionDegreeCodeTitle' },
    ],
    input.queryLang,
  );

  const rawJobTypeCode = trimOptional(String(enrichedMember.jobTypeCode ?? ''), 128);
  const rawMehaniUnionCode = trimOptional(String(enrichedMember.mehaniUnionCode ?? ''), 1000);
  const rawMehaniUnionDegreeCode = trimOptional(String(enrichedMember.mehaniUnionDegreeCode ?? ''), 1000);

  const [jobTypeCode, mehaniUnionCode, mehaniUnionDegreeCode] = await Promise.all([
    resolveActiveHwyBaseInfoLeafCode(rawJobTypeCode),
    resolveActiveHwyBaseInfoLeafCode(rawMehaniUnionCode),
    resolveActiveHwyBaseInfoLeafCode(rawMehaniUnionDegreeCode),
  ]);

  const jobTypeCodeTitle = jobTypeCode
    ? trimOptional(String(enrichedMember.jobTypeCodeTitle ?? ''), 512)
    : null;
  const mehaniUnionCodeTitle = mehaniUnionCode
    ? trimOptional(String(enrichedMember.mehaniUnionCodeTitle ?? ''), 512)
    : null;
  const mehaniUnionDegreeCodeTitle = mehaniUnionDegreeCode
    ? trimOptional(String(enrichedMember.mehaniUnionDegreeCodeTitle ?? ''), 512)
    : null;

  return {
    kind: profile.kind,
    instituteCode: profile.instituteCode ?? null,
    member: {
      id: String(memberRow.id ?? memberId),
      displayFullName: trimOptional(String(memberRow.displayFullName ?? ''), 512),
      username: trimOptional(String(memberRow.username ?? ''), 128),
      jobTypeCode,
      jobTypeCodeTitle,
      jobPlace: trimOptional(String(memberRow.jobPlace ?? ''), 512),
      mehaniUnionCode,
      mehaniUnionCodeTitle,
      mehaniUnionDegreeCode,
      mehaniUnionDegreeCodeTitle,
      mehaniMembershipExpiresOn: trimOptional(String(enrichedMember.mehaniMembershipExpiresOn ?? ''), 32),
    },
    characterCode,
    characterCodeTitle,
  };
}

export async function patchHwyMemberListScopedEditFields(input: {
  memberIdRaw: string;
  listScopeLegacy: string;
  body: HwyMemberListScopedEditPatchBody;
  actorUserId?: number | null;
  session?: SessionScopeSnapshot | null;
}): Promise<void> {
  const profile = await resolveListScopedEditProfile(input.listScopeLegacy);
  if (!profile) {
    throw new Error('List scoped edit is not available for this list.');
  }
  if (profile.kind !== input.body.kind) {
    throw new Error('Edit kind does not match this list.');
  }

  const memberIdRaw = input.memberIdRaw.trim();

  if (profile.kind === 'gov_employment' && input.body.kind === 'gov_employment') {
    const patch: HwyMemberDirectoryPatchInput = {};
    if (Object.prototype.hasOwnProperty.call(input.body, 'jobTypeCode')) {
      patch.jobTypeCode = await resolveActiveHwyBaseInfoLeafCode(input.body.jobTypeCode ?? null);
    }
    if (Object.prototype.hasOwnProperty.call(input.body, 'jobPlace')) {
      patch.jobPlace = input.body.jobPlace ?? null;
    }
    if (Object.keys(patch).length === 0) {
      throw new Error('No editable fields in this update.');
    }
    await patchHwyMemberDirectoryMember(memberIdRaw, patch, {
      actorUserId: input.actorUserId ?? null,
      session: input.session ?? null,
    });
    invalidateHwyMemberDirectoryListCache();
    return;
  }

  if (profile.kind === 'mehani_professional' && input.body.kind === 'mehani_professional') {
    const memberId = parseMemberId(memberIdRaw);
    const sequelize = getControlPlaneSequelize();
    const assignments: string[] = [];
    const replacements: Record<string, unknown> = {
      memberId,
      updatedAt: new Date(),
      updatedBy: input.actorUserId ?? null,
    };
    if (Object.prototype.hasOwnProperty.call(input.body, 'mehaniUnionCode')) {
      assignments.push('mehani_union_code = :mehaniUnionCode');
      replacements.mehaniUnionCode = await resolveActiveHwyBaseInfoLeafCode(
        trimOptional(input.body.mehaniUnionCode ?? null, 1000),
      );
    }
    if (Object.prototype.hasOwnProperty.call(input.body, 'mehaniUnionDegreeCode')) {
      assignments.push('mehani_union_degree_code = :mehaniUnionDegreeCode');
      replacements.mehaniUnionDegreeCode = await resolveActiveHwyBaseInfoLeafCode(
        trimOptional(input.body.mehaniUnionDegreeCode ?? null, 1000),
      );
    }
    if (Object.prototype.hasOwnProperty.call(input.body, 'mehaniMembershipExpiresOn')) {
      assignments.push('mehani_membership_expires_on = :mehaniMembershipExpiresOn');
      const expiryRaw = trimOptional(input.body.mehaniMembershipExpiresOn ?? null, 32);
      replacements.mehaniMembershipExpiresOn = expiryRaw;
    }
    if (Object.prototype.hasOwnProperty.call(input.body, 'jobTypeCode')) {
      assignments.push('job_type_code = :jobTypeCode');
      replacements.jobTypeCode = await resolveActiveHwyBaseInfoLeafCode(
        trimOptional(input.body.jobTypeCode ?? null, 1000),
      );
    }
    if (Object.prototype.hasOwnProperty.call(input.body, 'jobPlace')) {
      assignments.push('job_place = :jobPlace');
      replacements.jobPlace = trimOptional(input.body.jobPlace ?? null, 8000);
    }
    if (assignments.length === 0) {
      throw new Error('No editable fields in this update.');
    }
    await sequelize.query(
      `
      UPDATE dbo.hwy_members
      SET ${assignments.join(',\n          ')},
          updated_at = :updatedAt,
          updated_by = :updatedBy
      WHERE id = :memberId
      `,
      { replacements, type: QueryTypes.UPDATE },
    );
    invalidateHwyMemberDirectoryListCache();
    return;
  }

  if (profile.kind === 'institute_character' && input.body.kind === 'institute_character') {
    if (readControlPlaneProvider() !== 'sqlserver') {
      throw new Error('List scoped edit requires SQL Server control plane.');
    }
    const instituteCode = profile.instituteCode?.trim();
    const instituteId = instituteCode ? resolveHwyMemberListInstituteId(instituteCode) : null;
    if (instituteId == null) {
      throw new Error('Institute is not configured for this list.');
    }
    const memberId = parseMemberId(memberIdRaw);
    const characterCode = trimOptional(input.body.characterCode ?? null, 128);
    const sequelize = getControlPlaneSequelize();
    const now = new Date();
    const linkRows = await sequelize.query<{ linkId: number }>(
      `
      SELECT TOP (1) mi.id AS linkId
      FROM dbo.hwy_member_institutes mi
      WHERE mi.member_id = :memberId AND mi.institute_id = :instituteId
      ORDER BY mi.id DESC
      `,
      { replacements: { memberId, instituteId }, type: QueryTypes.SELECT },
    );
    if (!linkRows[0]?.linkId) {
      throw new Error('Institute membership link not found for this member.');
    }
    await sequelize.query(
      `
      UPDATE dbo.hwy_member_institutes
      SET character_code = :characterCode,
          updated_at = :updatedAt,
          updated_by = :updatedBy
      WHERE id = :linkId
      `,
      {
        replacements: {
          characterCode,
          linkId: linkRows[0].linkId,
          updatedAt: now,
          updatedBy: input.actorUserId ?? null,
        },
        type: QueryTypes.UPDATE,
      },
    );
    invalidateHwyMemberDirectoryListCache();
  }
}
