import sql from 'mssql';
import {
  legacyBitToNvarchar,
  resolveLegacyMemberUsername,
} from './legacyMaps';
import { resolveEtlTasjilStateCode } from './hwyEtlBaseVocab';
import { resolveLegacyMemberFamilyCode } from './legacyMemberFamilyCode';
import { resolveLegacyMembershipOnDate } from './legacyMembershipOn';
import { resolveGeoBaseInfoId } from './geo/geoMapStore';
import type { SampleVocab } from './resolveSampleVocab';
import { bindValuesRow, chunkByParamBudget, type BoundParam } from './sqlBulkHelpers';

const nv = (v: unknown): string | null => (v == null || v === '' ? null : String(v));

const mapGender = (
  legacyId: number | null | undefined,
  genderByLegacyId: Map<number, string>,
): string | null => {
  if (legacyId == null) return null;
  return genderByLegacyId.get(legacyId) ?? null;
};

const mapTasjilState = (
  legacyId: number | null | undefined,
  vocab: SampleVocab,
): string | null => resolveEtlTasjilStateCode(legacyId, vocab.tasjilStateByLegacyId);

const mapRegistrationChannel = (
  legacyDeviceOsTypeId: number | null | undefined,
  vocab: SampleVocab,
): string | null => {
  if (legacyDeviceOsTypeId == null || Number.isNaN(legacyDeviceOsTypeId)) {
    return null;
  }
  return vocab.registrationChannelByLegacyDeviceOsId.get(legacyDeviceOsTypeId) ?? null;
};

const mapNakhebinLinkType = (
  legacyJoinTypeId: number | null | undefined,
  vocab: SampleVocab,
): string | null => {
  if (legacyJoinTypeId == null || legacyJoinTypeId <= 0) {
    return null;
  }
  return vocab.nakhebinLinkTypeByLegacyId.get(legacyJoinTypeId) ?? null;
};

export type LegacyMemberRow = {
  Id: number;
  NakhebId: number | null;
  FirstName: string | null;
  FatherName: string | null;
  GrandFatherName: string | null;
  LastName: string | null;
  NickName: string | null;
  GenderId: number | null;
  BirthYear: string | number | null;
  BirthMonth: string | number | null;
  BirthDay: string | number | null;
  NationalCode: string | null;
  Phone1: string | null;
  Phone2: string | null;
  Email: string | null;
  FacebookId: string | null;
  TikTokId: string | null;
  FamilyCode: string | null;
  AddrStateId: number | null;
  AddrCityId: number | null;
  AddrNahiehId: number | null;
  AddrMahallehName: string | null;
  AddrMahallehNumber: string | null;
  AddrZoghaghNumber: string | null;
  AddrDaarNumber: string | null;
  AddrAghrabLocation: string | null;
  AddrMostImportantPlace: string | null;
  AddrEghteraId: number | null;
  UserName: string | number | null;
  TrackingCode: string | number | null;
  MembershipStatus: number;
  MembershipOn: Date | null;
  MoarrefUserName: string | null;
  SecondMoarrefUserName: string | null;
  VotedOn2021: boolean | number | null;
  VotedOn2023: boolean | number | null;
  VotedOn2025: boolean | number | null;
  CreatedOn: Date | null;
  UpdatedOn: Date | null;
  NakhebJoinTasjilStateId: number | null;
  NakhebJoinTypeId: number | null;
  DeviceOsTypeId: number | null;
};

const MEMBER_INSERT_COLUMNS = 43;

export function memberRowToParams(
  r: LegacyMemberRow,
  membershipStatusCode: string,
  genderByLegacyId: Map<number, string>,
  geoMap: Map<string, string>,
  nakhebinFamilyById: Map<number, string>,
  vocab: SampleVocab,
): BoundParam[] {
  const createdAt = r.CreatedOn ? new Date(r.CreatedOn) : new Date();
  const membershipOn = resolveLegacyMembershipOnDate(r) ?? null;
  const updatedAt = r.UpdatedOn ? new Date(r.UpdatedOn) : createdAt;
  const useFastUsername = process.env.HWY_ETL_FAST === '1' && process.env.HWY_ETL_MEMBER_UPSERT !== '1';
  const membershipUsername = useFastUsername
    ? String(r.Id)
    : resolveLegacyMemberUsername({
      memberId: Number(r.Id),
      userName: r.UserName,
      trackingCode: r.TrackingCode,
    });
  const nakhebinFamily = r.NakhebId != null && r.NakhebId > 0
    ? nakhebinFamilyById.get(r.NakhebId)
    : undefined;
  const familyCode = resolveLegacyMemberFamilyCode(r.FamilyCode, nakhebinFamily);

  return [
    { name: 'id', type: sql.BigInt, value: r.Id },
    { name: 'user_id', type: sql.BigInt, value: null },
    { name: 'username', type: sql.NVarChar(4000), value: membershipUsername },
    { name: 'first_name', type: sql.NVarChar(sql.MAX), value: r.FirstName },
    { name: 'father_name', type: sql.NVarChar(sql.MAX), value: r.FatherName },
    { name: 'grandfather_name', type: sql.NVarChar(sql.MAX), value: r.GrandFatherName },
    { name: 'family_name', type: sql.NVarChar(sql.MAX), value: r.LastName },
    { name: 'nickname', type: sql.NVarChar(sql.MAX), value: r.NickName },
    { name: 'gender_code', type: sql.NVarChar(1000), value: mapGender(r.GenderId, genderByLegacyId) },
    { name: 'birth_year', type: sql.NVarChar(4000), value: nv(r.BirthYear) },
    { name: 'birth_month', type: sql.NVarChar(4000), value: nv(r.BirthMonth) },
    { name: 'birth_day', type: sql.NVarChar(4000), value: nv(r.BirthDay) },
    { name: 'national_id', type: sql.NVarChar(4000), value: nv(r.NationalCode) },
    { name: 'phone1', type: sql.NVarChar(4000), value: nv(r.Phone1) },
    { name: 'phone2', type: sql.NVarChar(4000), value: nv(r.Phone2) },
    { name: 'email', type: sql.NVarChar(4000), value: nv(r.Email) },
    { name: 'facebook_id', type: sql.NVarChar(4000), value: nv(r.FacebookId) },
    { name: 'tiktok_id', type: sql.NVarChar(4000), value: nv(r.TikTokId) },
    { name: 'addr_province_id', type: sql.NVarChar(128), value: resolveGeoBaseInfoId(geoMap, 'province', r.AddrStateId) },
    { name: 'addr_district_id', type: sql.BigInt, value: r.AddrCityId ?? null },
    { name: 'addr_subdistrict_id', type: sql.BigInt, value: r.AddrNahiehId ?? null },
    { name: 'addr_quarter_name', type: sql.NVarChar(sql.MAX), value: r.AddrMahallehName },
    { name: 'addr_quarter_no', type: sql.NVarChar(4000), value: nv(r.AddrMahallehNumber) },
    { name: 'addr_alley_no', type: sql.NVarChar(4000), value: nv(r.AddrZoghaghNumber) },
    { name: 'addr_house_no', type: sql.NVarChar(4000), value: nv(r.AddrDaarNumber) },
    { name: 'addr_nearest_landmark', type: sql.NVarChar(sql.MAX), value: r.AddrAghrabLocation },
    { name: 'addr_most_important_place', type: sql.NVarChar(sql.MAX), value: r.AddrMostImportantPlace },
    { name: 'addr_region_id', type: sql.NVarChar(128), value: resolveGeoBaseInfoId(geoMap, 'region', r.AddrEghteraId) },
    { name: 'nakhebin_id', type: sql.BigInt, value: r.NakhebId ?? null },
    { name: 'nakhebin_link_type_code', type: sql.NVarChar(1000), value: mapNakhebinLinkType(r.NakhebJoinTypeId, vocab) },
    { name: 'nakhebin_join_tasjil_state_code', type: sql.NVarChar(1000), value: mapTasjilState(r.NakhebJoinTasjilStateId, vocab) },
    { name: 'family_code', type: sql.NVarChar(4000), value: familyCode },
    { name: 'voted_on_2021', type: sql.NVarChar(4000), value: legacyBitToNvarchar(r.VotedOn2021) },
    { name: 'voted_on_2023', type: sql.NVarChar(4000), value: legacyBitToNvarchar(r.VotedOn2023) },
    { name: 'voted_on_2025', type: sql.NVarChar(4000), value: legacyBitToNvarchar(r.VotedOn2025) },
    { name: 'membership_status_code', type: sql.NVarChar(1000), value: membershipStatusCode },
    { name: 'registration_channel_code', type: sql.NVarChar(1000), value: mapRegistrationChannel(r.DeviceOsTypeId, vocab) },
    { name: 'membership_on', type: sql.Date, value: membershipOn },
    { name: 'referrer_username', type: sql.NVarChar(4000), value: nv(r.MoarrefUserName) },
    { name: 'second_referrer_username', type: sql.NVarChar(4000), value: nv(r.SecondMoarrefUserName) },
    { name: 'created_at', type: sql.DateTime2, value: createdAt },
    { name: 'updated_at', type: sql.DateTime2, value: updatedAt },
  ];
}

