/** Multi-row INSERT (user_id always NULL). */
export async function insertMembersBulk(
  local: sql.ConnectionPool,
  rows: Array<{
    member: LegacyMemberRow;
    membershipStatusCode: string;
    genderByLegacyId: Map<number, string>;
    geoMap: Map<string, string>;
    nakhebinFamilyById: Map<number, string>;
    vocab: SampleVocab;
  }>,
): Promise<number> {
  if (!rows.length) return 0;
  let inserted = 0;
  for (const slice of chunkByParamBudget(rows, MEMBER_INSERT_COLUMNS)) {
    const req = local.request();
    const valueRows: string[] = [];
    slice.forEach((entry, rowIndex) => {
      const params = memberRowToParams(
        entry.member,
        entry.membershipStatusCode,
        entry.genderByLegacyId,
        entry.geoMap,
        entry.nakhebinFamilyById,
        entry.vocab,
      );
      valueRows.push(bindValuesRow(req, rowIndex, params));
    });
    await req.query(`${INSERT_SQL_PREFIX} ${valueRows.join(',\n')};`);
    inserted += slice.length;
  }
  return inserted;
}

/** Upsert member rows; preserves existing user_id on match. */
export async function upsertMembersBulk(
  local: sql.ConnectionPool,
  rows: Array<{
    member: LegacyMemberRow;
    membershipStatusCode: string;
    genderByLegacyId: Map<number, string>;
    geoMap: Map<string, string>;
    nakhebinFamilyById: Map<number, string>;
    vocab: SampleVocab;
  }>,
): Promise<number> {
  if (!rows.length) return 0;
  let affected = 0;
  for (const slice of chunkByParamBudget(rows, MEMBER_INSERT_COLUMNS)) {
    const req = local.request();
    const valueRows: string[] = [];
    slice.forEach((entry, rowIndex) => {
      const params = memberRowToParams(
        entry.member,
        entry.membershipStatusCode,
        entry.genderByLegacyId,
        entry.geoMap,
        entry.nakhebinFamilyById,
        entry.vocab,
      );
      valueRows.push(bindValuesRow(req, rowIndex, params));
    });
    await req.query(`${MERGE_SQL_PREFIX} ${valueRows.join(',\n')} ${MERGE_SQL_SUFFIX}`);
    affected += slice.length;
  }
  return affected;
}
