import { formatRecordEventValue } from '../../shared/lib/formatRecordEventValue';
import { normalizeHwyMemberPhoneStorage } from './hwyMemberPhoneRequestRules';

const PHONE_HISTORY_FIELDS = new Set(['phone1', 'phone2']);

/** Format decrypted/plain record-event values for member dossier change log. */
export function formatHwyMemberDossierChangeLogRecordEventValue(
  field: string | null | undefined,
  value: unknown,
): string {
  const formatted = formatRecordEventValue(value);
  if (formatted === '••••') {
    return '';
  }
  if (!field || !PHONE_HISTORY_FIELDS.has(field.trim())) {
    return formatted === '—' ? '' : formatted;
  }
  if (formatted === '—' || !formatted.trim()) {
    return '';
  }
  return normalizeHwyMemberPhoneStorage(formatted);
}
