import sql from 'mssql';
import type { HwyMemberDossierSelectOption } from '../../../domain/hwy/hwyMemberDossierSelectOptions';
import {
  resolveHwyMemberInstituteCharacterVocab,
  type HwyMemberInstituteCharacterVocab,
} from '../../../domain/hwy/hwyMemberInstituteCharacterVocab';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';
import { findHwyBaseInfoCategoryId } from '../../../../scripts/hwy-phase1/seed/seedHwyBaseInfo';
import { listLegacyHwyBaseInformationByParent } from './hwyLegacyBaseInformationReader';

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

const rowsToOptions = async (
  rows: BaseInfoDbRow[],
  cultureId: string,
): Promise<HwyMemberDossierSelectOption[]> => {
  if (rows.length === 0) {
    return [];
  }
  const mapped = await mapBaseInfoRowsForCulture(rows, cultureId, (row, context) => ({
    viewOrder: toViewOrderNumber(row.viewOrder),
    label: context.label,
    id: row.id,
  }));
  return mapped
    .map((row) => ({
      value: String(row.id ?? '').trim(),
      label: String(row.label ?? '').trim() || String(row.id ?? '').trim(),
    }))
    .filter((row) => row.value && row.label)
    .sort((a, b) => a.label.localeCompare(b.label, 'ar'));
};

const listActiveBaseInfoDescendants = async (rootId: string): Promise<BaseInfoDbRow[]> => {
  const collected: BaseInfoDbRow[] = [];
  let frontier = [rootId];
  const seen = new Set<string>(frontier);

  while (frontier.length > 0) {
    const children = await prisma().baseInfo.findMany({
      where: { parentId: { in: frontier }, isActive: true },
      orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
      select: BASE_INFO_ROW_SELECT,
    });
    const next: string[] = [];
    for (const row of children) {
      collected.push(row as BaseInfoDbRow);
      const id = String(row.id ?? '').trim();
      if (id && !seen.has(id)) {
        seen.add(id);
        next.push(id);
      }
    }
    frontier = next;
  }

  return collected;
};

const listPlatformCharacterOptions = async (
  vocab: HwyMemberInstituteCharacterVocab,
  cultureId: string,
): Promise<HwyMemberDossierSelectOption[]> => {
  const categoryId = await findHwyBaseInfoCategoryId(vocab.platformCategoryTitle);
  if (categoryId) {
    const underCategory = await listActiveBaseInfoDescendants(categoryId);
    if (underCategory.length > 0) {
      return rowsToOptions(underCategory, cultureId);
    }
  }

  const underLegacyParent = await listActiveBaseInfoDescendants(String(vocab.legacyBaseInfoParentId));
  return rowsToOptions(underLegacyParent, cultureId);
};

const listLegacyCharacterOptions = async (
  vocab: HwyMemberInstituteCharacterVocab,
): Promise<HwyMemberDossierSelectOption[]> => {
  try {
    const { readLegacyConn, withLegacyReadOnlyIntent } = await import('../../../../scripts/hwy-etl/legacyConn');
    const { loadLegacyBaseInfoDescendantRows } = await import('../../../../scripts/hwy-etl/hwyEtlBaseVocab');
    const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();
    try {
      const rows = await loadLegacyBaseInfoDescendantRows(pool, vocab.legacyBaseInfoParentId);
      return rows
        .filter((row) => row.IsActive === true || row.IsActive === 1)
        .map((row) => ({
          value: String(row.Id),
          label: String(row.Title ?? '').trim() || String(row.Id),
        }))
        .filter((row) => row.value && row.label)
        .sort((a, b) => a.label.localeCompare(b.label, 'ar'));
    } finally {
      await pool.close();
    }
  } catch {
    const legacyRows = await listLegacyHwyBaseInformationByParent(vocab.legacyBaseInfoParentId);
    return legacyRows.map((row) => ({
      value: String(row.id),
      label: row.title.trim(),
    }));
  }
};

export async function listHwyMemberInstituteCharacterSelectOptions(
  instituteCode: string,
  cultureId = 'iq',
): Promise<HwyMemberDossierSelectOption[]> {
  const vocab = resolveHwyMemberInstituteCharacterVocab(instituteCode);
  if (!vocab) {
    return [];
  }

  const platformOptions = await listPlatformCharacterOptions(vocab, cultureId);
  if (platformOptions.length > 0) {
    return platformOptions;
  }

  return listLegacyCharacterOptions(vocab);
}
