import { QueryTypes } from 'sequelize';

import { isHwyMemberDossierProfileRailJoinedMember } from '../../../domain/hwy/hwyMemberDossierProfileRailFaceCaption';
import { resolveHwyMemberFaceCaption } from '../../../domain/hwy/hwyMemberFaceCaptionDisplay';
import { resolveHwyAllocatedMembershipUsername } from '../../../domain/hwy/hwyMembershipUsername';
import type { HwyMemberDirectoryDetail } from '../../../domain/hwy/hwyMemberDirectoryDetail';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { loadHwyMembershipStatusIdMapForClient } from './hwyMemberMembershipStatusIds.service';

const LEGACY_BATCH = 40;

const readMemberId = (row: Record<string, unknown>): number | null => {
  const raw = row.id ?? row.memberId ?? row.member_id;
  if (raw == null || raw === '') {
    return null;
  }
  const numeric = Number(raw);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
};

const readUserId = (row: Record<string, unknown>): number | null => {
  const raw = row.userId ?? row.user_id;
  if (raw == null || raw === '') {
    return null;
  }
  const numeric = Number(raw);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
};

/** Detail getOne only — raw base_users.username for joined dossier rails (after list face-caption pipeline). */
export async function attachHwyMemberDossierProfileRailLoginUsername(
  rows: Record<string, unknown>[],
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  const membershipStatusIds = await loadHwyMembershipStatusIdMapForClient();
  const lookupUserIds: number[] = [];

  for (const row of rows) {
    const member = row as HwyMemberDirectoryDetail;
    if (resolveHwyMemberFaceCaption(row).kind === 'username') {
      continue;
    }
    if (!isHwyMemberDossierProfileRailJoinedMember(member.membershipStatusCode, membershipStatusIds)) {
      continue;
    }
    const userId = readUserId(row);
    if (userId) {
      lookupUserIds.push(userId);
    }
  }

  const uniqueUserIds = [...new Set(lookupUserIds)];
  if (uniqueUserIds.length === 0) {
    return;
  }

  let sequelize;
  try {
    sequelize = getControlPlaneSequelize();
  } catch {
    return;
  }

  const dialect = sequelize.getDialect();
  const usersTable = dialect === 'mssql' ? 'dbo.base_users' : 'base_users';
  const q = (name: string) => (dialect === 'mssql' ? `[${name}]` : `"${name}"`);
  const usernameByUserId = new Map<number, string>();

  for (let offset = 0; offset < uniqueUserIds.length; offset += LEGACY_BATCH) {
    const batch = uniqueUserIds.slice(offset, offset + LEGACY_BATCH);
    const replacements: Record<string, number> = {};
    const params = batch.map((id, index) => {
      const key = `uid${index}`;
      replacements[key] = id;
      return `:${key}`;
    });
    const sqlText = `
      SELECT CAST(u.${q('id')} AS BIGINT) AS userId, u.${q('username')} AS username
      FROM ${usersTable} u
      WHERE u.${q('id')} IN (${params.join(', ')})`;
    const result = await sequelize.query<{ userId: number; username: unknown }>(sqlText, {
      type: QueryTypes.SELECT,
      replacements,
    });
    for (const entry of result) {
      const userId = Number(entry.userId);
      const username = entry.username == null ? '' : String(entry.username).trim();
      if (userId > 0 && username) {
        usernameByUserId.set(userId, username);
      }
    }
  }

  if (usernameByUserId.size === 0) {
    return;
  }

  for (const row of rows) {
    const member = row as HwyMemberDirectoryDetail;
    if (resolveHwyMemberFaceCaption(row).kind === 'username') {
      continue;
    }
    if (!isHwyMemberDossierProfileRailJoinedMember(member.membershipStatusCode, membershipStatusIds)) {
      continue;
    }
    const memberId = readMemberId(row);
    if (!memberId) {
      continue;
    }
    const userId = readUserId(row);
    if (!userId) {
      continue;
    }
    const platformUsername = usernameByUserId.get(userId);
    const allocated = resolveHwyAllocatedMembershipUsername(platformUsername ?? '', memberId);
    if (allocated) {
      row.username = allocated;
    }
  }
}
