import { HWY_MEMBER_IMAGE_FIX_TODO_FILE_KIND_SLUGS } from './hwyMemberImageFixListScope';
import { normalizeHwyMemberListScopeLegacyCode } from './hwyMemberListScopeLegacyAliases';

/** Designer grids bind `listScope=static:HWY_Members_List_*`; normalize before scope checks. */
export const normalizeMemberDirectoryListScopeLegacyParam = (
  listScopeLegacy: string | null | undefined,
): string => {
  let scope = listScopeLegacy?.trim() ?? '';
  if (scope.startsWith('static:')) {
    scope = scope.slice('static:'.length).trim();
  }
  return scope ? normalizeHwyMemberListScopeLegacyCode(scope) : '';
};

/** Legacy list thumbnail column order (`HWY_Members_List_ImageFix.html` #images_ItemTemplates). */
export const HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS = [
  'voter_card_front',
  'national_card_front',
  'national_card_back',
  'personal_photo',
  'oath_document',
  'residence_card_front',
] as const;

export type HwyMemberImageFixThumbKindSlug = (typeof HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS)[number];

export const HWY_MEMBER_IMAGE_FIX_LIST_LEGACY_SCOPE = 'HWY_Members_List_Imagefix' as const;

export const isHwyMemberImageFixListScope = (
  listScopeLegacy: string | null | undefined,
): boolean => normalizeMemberDirectoryListScopeLegacyParam(listScopeLegacy)
  === HWY_MEMBER_IMAGE_FIX_LIST_LEGACY_SCOPE;

export const shouldEnrichImageFixRegistrationThumbsForListScope = (
  listScopeLegacy: string | null | undefined,
): boolean => isHwyMemberImageFixListScope(listScopeLegacy);

/** Montadhemin / segment lists: server fills list face from registration personal photo when profile avatar is empty. */
export const shouldEnrichListFaceAvatarsFromRegistrationForListScope = (
  listScopeLegacy: string | null | undefined,
): boolean => {
  const scope = normalizeMemberDirectoryListScopeLegacyParam(listScopeLegacy);
  if (isHwyMemberImageFixListScope(scope)) {
    return false;
  }
  if (!scope) {
    return true;
  }
  return scope.startsWith('HWY_Members_List_');
};

/** Queue predicate kinds (may differ from display order). */
export const HWY_MEMBER_IMAGE_FIX_QUEUE_KIND_SLUGS = HWY_MEMBER_IMAGE_FIX_TODO_FILE_KIND_SLUGS;

export type HwyMemberImageFixThumbSlot = {
  kindSlug: HwyMemberImageFixThumbKindSlug;
  fileId?: string | null;
  previewUrl?: string | null;
  isApproved?: boolean;
  hasBlob?: boolean;
};

export type HwyMemberImageFixThumbRow = {
  slots: HwyMemberImageFixThumbSlot[];
};

/** Registration blobs used for list face when profile avatar is empty (legacy Picture parity). */
export const HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS = [
  'personal_photo',
  'national_card_front',
  'voter_card_front',
] as const satisfies ReadonlyArray<HwyMemberImageFixThumbKindSlug>;

/** List face avatar: platform profile image, else first registration thumb with blob. */
export const resolveHwyMemberImageFixListFaceAvatarUrl = (
  existingAvatarUrl: string | null | undefined,
  slots: ReadonlyArray<HwyMemberImageFixThumbSlot> | null | undefined,
): string | null => {
  const existing = String(existingAvatarUrl ?? '').trim();
  if (existing) {
    return existing;
  }
  if (!slots?.length) {
    return null;
  }
  for (const kindSlug of HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS) {
    const slot = slots.find((item) => item.kindSlug === kindSlug);
    if (slot?.previewUrl && slot.hasBlob) {
      return slot.previewUrl;
    }
  }
  return null;
};

const readMemberDirectoryFaceImageUrlDirect = (
  row: Record<string, unknown>,
  imageUrlField: string,
): string => {
  const keys = [
    imageUrlField,
    'avatarUrl',
    'avatar_url',
    'list_avatar_preview',
  ].map((key) => key?.trim()).filter(Boolean);
  const seen = new Set<string>();
  for (const key of keys) {
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    const value = String(row[key] ?? '').trim();
    if (value) {
      return value;
    }
  }
  return '';
};

export type ResolveMemberDirectoryFaceImageUrlOptions = {
  /** When false, do not derive face URL from `registrationImageFixThumbs` (montadhemin uses server `avatarUrl` only). */
  allowRegistrationPersonalPhotoFallback?: boolean;
};

export const resolveMemberDirectoryFaceImageUrl = (
  row: Record<string, unknown>,
  imageUrlField = 'avatarUrl',
  options?: ResolveMemberDirectoryFaceImageUrlOptions,
): string => {
  const fieldKey = imageUrlField?.trim() || 'avatarUrl';
  const direct = readMemberDirectoryFaceImageUrlDirect(row, fieldKey);
  if (direct) {
    return direct;
  }
  if (options?.allowRegistrationPersonalPhotoFallback === false) {
    return '';
  }
  const thumbRow = readHwyMemberImageFixThumbRow(row);
  return resolveHwyMemberImageFixListFaceAvatarUrl(null, thumbRow?.slots) ?? '';
};

/** Allow grid face cell to resolve from `registrationImageFixThumbs` when `avatarUrl` is still empty. */
export const shouldAllowRegistrationPersonalPhotoInListFaceColumn = (
  listScopeLegacy: string | null | undefined,
): boolean => {
  if (isHwyMemberImageFixListScope(listScopeLegacy)) {
    return true;
  }
  return shouldEnrichListFaceAvatarsFromRegistrationForListScope(listScopeLegacy);
};

/** Keep list row face URL on both keys — designer grids default to `avatar_url`. */
export const mirrorMemberDirectoryListFaceAvatarUrlFields = (
  row: Record<string, unknown>,
  avatarUrl: string | null | undefined,
): void => {
  const url = String(avatarUrl ?? '').trim();
  if (!url) {
    return;
  }
  row.avatarUrl = url;
  row.avatar_url = url;
};

export const readHwyMemberImageFixThumbRow = (
  row: Record<string, unknown>,
): HwyMemberImageFixThumbRow | null => {
  const raw = row.registrationImageFixThumbs;
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const slots = (raw as HwyMemberImageFixThumbRow).slots;
  if (!Array.isArray(slots)) {
    return null;
  }
  return { slots };
};
