/** Env keys for sync-changes orchestrator (console + scripts). */

export const HWY_ETL_SYNC_LOOKBACK_HOURS = 'HWY_ETL_SYNC_LOOKBACK_HOURS';
export const HWY_ETL_SYNC_SKIP_DOMAIN = 'HWY_ETL_SYNC_SKIP_DOMAIN';
export const HWY_ETL_SYNC_INCLUDE_DOMAIN = 'HWY_ETL_SYNC_INCLUDE_DOMAIN';
export const HWY_ETL_MEMBER_UPDATED_SINCE = 'HWY_ETL_MEMBER_UPDATED_SINCE';

export type HwyEtlSyncPlanInput = {
  lookbackHours: number;
  explicitUpdatedSinceIso?: string | null;
  skipDomainModules?: boolean;
  includeDomainModules?: boolean;
};

export const parseSyncLookbackHours = (value: unknown): number => {
  const n = Number(value ?? 0);
  if (!Number.isFinite(n) || n < 0) return 0;
  return Math.min(168, Math.round(n));
};

export const resolveSyncMemberUpdatedSince = (input: {
  lastLegacyMemberUpdatedOn: string | null;
  lookbackHours: number;
  explicitUpdatedSinceIso?: string | null;
  forceLookback?: boolean;
  now?: Date;
}): Date => {
  const now = input.now ?? new Date();
  const watermark = input.lastLegacyMemberUpdatedOn?.trim();
  const watermarkMs = watermark ? Date.parse(watermark) : Number.NaN;
  const fromWatermark = Number.isNaN(watermarkMs) ? new Date(0) : new Date(watermarkMs);

  const explicit = input.explicitUpdatedSinceIso?.trim();
  let base = fromWatermark;
  if (explicit) {
    const explicitMs = Date.parse(explicit);
    if (!Number.isNaN(explicitMs)) {
      base = new Date(Math.max(base.getTime(), explicitMs));
    }
  }

  if (input.lookbackHours > 0) {
    const fromHours = new Date(now.getTime() - input.lookbackHours * 3_600_000);
    if (input.forceLookback || !watermark) {
      return fromHours > base ? fromHours : base;
    }
    return fromHours > base ? fromHours : base;
  }

  return base;
};

export const shouldRunSyncDomainModules = (input: {
  env: Record<string, string | number | boolean | undefined>;
  targetMemberCount: number;
  newMemberCount: number;
}): boolean => {
  const skip = input.env[HWY_ETL_SYNC_SKIP_DOMAIN];
  if (skip === true || skip === '1' || skip === 1) return false;
  const include = input.env[HWY_ETL_SYNC_INCLUDE_DOMAIN];
  if (include === true || include === '1' || include === 1) return true;
  return input.targetMemberCount > 0 || input.newMemberCount > 0;
};

export const syncPlanInputFromRunOptions = (
  options: { env?: Record<string, string | number | boolean> } = {},
): HwyEtlSyncPlanInput => ({
  lookbackHours: parseSyncLookbackHours(options.env?.[HWY_ETL_SYNC_LOOKBACK_HOURS]),
  explicitUpdatedSinceIso:
    options.env?.[HWY_ETL_MEMBER_UPDATED_SINCE] != null
      ? String(options.env[HWY_ETL_MEMBER_UPDATED_SINCE])
      : null,
  skipDomainModules:
    options.env?.[HWY_ETL_SYNC_SKIP_DOMAIN] === true
    || options.env?.[HWY_ETL_SYNC_SKIP_DOMAIN] === '1',
  includeDomainModules:
    options.env?.[HWY_ETL_SYNC_INCLUDE_DOMAIN] === true
    || options.env?.[HWY_ETL_SYNC_INCLUDE_DOMAIN] === '1',
});
