/**
 * Self-registration gateway (replaces legacy `HWY_Members.DeviceOsTypeId`).
 * Values are Base Info shortNames under category "Registration Channel" (Hawiety root 220).
 */

export const HWY_REGISTRATION_CHANNEL_SHORT_NAMES = [
  'general_web',
  'mobile_app',
  'gov',
  'hemam',
  'mehani',
  'shabab',
  'nokhab',
  'protectors',
  'alforat',
  'other_portal',
  /** Studio staff panel create (not a public URL channel). */
  'studio_staff',
] as const;

export type HwyRegistrationChannelShortName = (typeof HWY_REGISTRATION_CHANNEL_SHORT_NAMES)[number];

/** Official Hawiety membership — `/self-registration` from login (no URL suffix). */
export const HWY_PRIMARY_SELF_REGISTRATION_CHANNEL: HwyRegistrationChannelShortName = 'general_web';

/** Legacy static page path on hawiety.com (culture prefix added by host when applicable). */
export const HWY_PRIMARY_SELF_REGISTRATION_PUBLIC_PATH = '/self-registration';

/**
 * Legacy public paths → channel shortName.
 * Only `HWY_PRIMARY_SELF_REGISTRATION_PUBLIC_PATH` is linked from the main login footer.
 */
export const LEGACY_SELF_REGISTRATION_PUBLIC_PATH_TO_CHANNEL: Readonly<
  Record<string, HwyRegistrationChannelShortName>
> = {
  [HWY_PRIMARY_SELF_REGISTRATION_PUBLIC_PATH]: 'general_web',
  '/self-registration-gov': 'gov',
  '/self-registration-hemam': 'hemam',
  '/self-registration-mehani': 'mehani',
  '/self-registration-shabab': 'shabab',
  '/self-registration-nokhab': 'nokhab',
  '/self-registration-protectors': 'protectors',
  '/self-registration-alforat': 'alforat',
  '/other-registration': 'other_portal',
};

/** Legacy `DeviceOsTypeId` → V2 channel shortName (ETL + parity only). */
export const LEGACY_DEVICE_OS_TYPE_ID_TO_REGISTRATION_CHANNEL: Readonly<Record<number, HwyRegistrationChannelShortName>> = {
  112301: 'general_web',
  112304: 'mobile_app',
  215002: 'gov',
  214928: 'hemam',
  214934: 'mehani',
  214959: 'shabab',
  215093: 'nokhab',
  215074: 'protectors',
  215120: 'alforat',
  213991: 'other_portal',
  /** Reserved for V2 staff create — not used by legacy public self-reg URLs. */
  112305: 'studio_staff',
};

/** Registration channels that must never be accepted from public self-registration HTTP API. */
export const HWY_STAFF_ONLY_REGISTRATION_CHANNELS = new Set<HwyRegistrationChannelShortName>([
  'studio_staff',
]);

export const resolveRegistrationChannelFromLegacyDeviceOsTypeId = (
  legacyDeviceOsTypeId: number | null | undefined,
): HwyRegistrationChannelShortName | null => {
  if (legacyDeviceOsTypeId == null || Number.isNaN(legacyDeviceOsTypeId)) return null;
  return LEGACY_DEVICE_OS_TYPE_ID_TO_REGISTRATION_CHANNEL[legacyDeviceOsTypeId] ?? null;
};
