import {
  buildHwyMemberListRouteAllowRoles,
  legacyHwyActionKey,
  type HwyLegacyControllerAction,
} from './hwyMemberListLegacyAccess';
import { HWY_MEETINGS_MANAGEMENT_PAGE_KEY } from './hwyMeetingsNav';

export const HWY_MEETINGS_MANAGEMENT_LEGACY_READ: HwyLegacyControllerAction = {
  controller: 'HWY_BaseInformation',
  method: 'Read_Meetings',
};

export const resolveHwyMeetingsManagementPageLegacyReadAction = (
  pageKey: string,
): HwyLegacyControllerAction | null =>
  pageKey === HWY_MEETINGS_MANAGEMENT_PAGE_KEY ? HWY_MEETINGS_MANAGEMENT_LEGACY_READ : null;

export const buildHwyMeetingsManagementPortalAllowRoles = (
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const roles = rolesByAction.get(legacyHwyActionKey(HWY_MEETINGS_MANAGEMENT_LEGACY_READ)) ?? [];
  return buildHwyMemberListRouteAllowRoles(roles);
};
