/** Legacy `MembershipOn` with `CreatedOn` fallback (matches legacy list behavior when date unset). */
export const resolveLegacyMembershipOnDate = (row: {
  MembershipOn?: Date | string | null;
  CreatedOn?: Date | string | null;
}): Date | null => {
  if (row.MembershipOn) {
    const fromMembership = new Date(row.MembershipOn);
    if (!Number.isNaN(fromMembership.getTime())) {
      return fromMembership;
    }
  }
  if (row.CreatedOn) {
    const fromCreated = new Date(row.CreatedOn);
    if (!Number.isNaN(fromCreated.getTime())) {
      return fromCreated;
    }
  }
  return null;
};
