import type {
  HwyMemberNakhebinEghteraRegionListPayload,
  HwyMemberNakhebinEghteraRegionRow,
} from '../../../domain/hwy/hwyMemberNakhebinEghteraRegions';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';

const readRowString = (row: Record<string, unknown>, key: string): string => {
  const raw = row[key];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

const clampPage = (raw: unknown, fallback: number): number => {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed < 1) {
    return fallback;
  }
  return Math.floor(parsed);
};

const clampPageSize = (raw: unknown, fallback: number): number => {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed < 1) {
    return fallback;
  }
  return Math.min(500, Math.floor(parsed));
};

export async function listHwyMemberNakhebinEghteraRegions(input: {
  provinceId?: string | null;
  ancestorGeoId?: string | null;
  search?: string | null;
  page?: number;
  pageSize?: number;
}): Promise<HwyMemberNakhebinEghteraRegionListPayload> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Region list is not available in this environment.');
  }
  await ensureHwyDbObjects();
  const page = clampPage(input.page, 1);
  const pageSize = clampPageSize(input.pageSize, 30);
  const offset = (page - 1) * pageSize;
  const search = String(input.search ?? '').trim();
  const searchLike = search ? `%${search}%` : null;
  const provinceRaw = String(input.provinceId ?? '').trim() || null;
  const ancestorRaw = String(input.ancestorGeoId ?? '').trim() || null;

  const rows = await execHwyProcedure<Record<string, unknown>>(
    'hwy_member_nakhebin_eghtera_region_list',
    {
      province_raw: provinceRaw,
      ancestor_raw: ancestorRaw,
      search_like: searchLike,
      offset,
      page_size: pageSize,
    },
  );

  const mapped: HwyMemberNakhebinEghteraRegionRow[] = rows.map((row) => ({
    geoBaseInfoId: readRowString(row, 'geoBaseInfoId'),
    legacyGeoId: readRowString(row, 'legacyGeoId') || undefined,
    title: readRowString(row, 'title'),
    titlePath: readRowString(row, 'titlePath') || undefined,
  })).filter((row) => row.geoBaseInfoId && row.title);

  return { rows: mapped };
}
