import type { HwyMemberTarghinMembersListResult } from '../../../domain/hwy/hwyMemberTarghinMembersList';
import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { resolveHwyMemberDirectoryDetailLang } from '../../../domain/hwy/hwyMemberDirectoryDetail';
import { HWY_MEMBER_TARGHIN_REQUEST_STATUS } from '../../../domain/hwy/hwyMemberTarghinRequestStatus';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { findHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';
import { attachBaseInfoTitles } from './hwyMemberDossierSatellites.service';
import { ensureHwyMemberDossierSatellitesSchema } from './ensureHwyMemberDossierSatellitesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import {
  listHwyMemberTarghinExecutorRoleTitlesByMemberId,
  listHwyMemberTarghinExecutorRoleTitlesByUserId,
  parseHwyTarghinExecutorMemberId,
} from './hwyMemberTarghinExecutorRoles';
import { resolveTarghinRowFaceDossierMemberId } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { attachHwyTarghinMembersListExecutors } from './hwyMemberTarghinMembersListExecutorAttach.service';
import { readHwyProcedureRowUserId, readHwyProcedureRowValue } from './hwyProcedureRowRead';
import {
  mergeHwyTarghinExecutorRoleTitleLists,
  parseHwyTarghinExecutorRoleTitlesCsv,
} from '../../../domain/hwy/hwyTarghinExecutorRoleTitles';

const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Targhined member list requires SQL Server control plane.');
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return {
    page: safePage,
    pageSize: safePageSize,
    offset: (safePage - 1) * safePageSize,
  };
};

type RawRow = Record<string, unknown>;

const mapFace = (row: RawRow, prefix: string): HwyMemberTarghinAdminMemberFace => {
  const id = trim(row[`${prefix}Id`] as string | undefined);
  return {
    id,
    username: trim(row[`${prefix}Username`] as string | undefined) || null,
    displayFullName: formatHwyMemberPersonDisplayName(
      trim(row[`${prefix}DisplayFullName`] as string | undefined),
    ) || null,
    genderCode: trim(row[`${prefix}GenderCode`] as string | undefined) || null,
    avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
      avatarUrl: trim(row[`${prefix}AvatarUrl`] as string | undefined) || null,
      hasProfileImage: row[`${prefix}HasProfileImage`] === true || row[`${prefix}HasProfileImage`] === 1,
      userId: row[`${prefix}UserId`] != null ? Number(row[`${prefix}UserId`]) : null,
    }),
    phone: trim(row[`${prefix}Phone`] as string | undefined) || null,
    electoralDivisionPath: trim(row[`${prefix}ElectoralDivisionPath`] as string | undefined) || null,
  };
};

export const listHwyMemberTarghinMembers = async (
  input: {
    search?: string;
    page?: number;
    pageSize?: number;
  },
  queryLang = 'ar',
): Promise<HwyMemberTarghinMembersListResult> => {
  await assertSqlServer();
  const targhinStatusCode = await findHwyBaseInfoItemIdByShortName(
    'Membership Status',
    'pending_cancellation',
  );
  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);
  const search = trim(input.search);
  const searchLike = search ? `%${search}%` : null;

  const countRows = await execHwyProcedure<{ total: number | string }>('hwy_targhin_members_count', {
    targhin_status_code: targhinStatusCode,
    search_like: searchLike,
  });
  const total = Number(countRows[0]?.total ?? 0);

  const rows = await execHwyProcedure<RawRow>('hwy_targhin_members_list', {
    targhin_status_code: targhinStatusCode,
    approved_status: HWY_MEMBER_TARGHIN_REQUEST_STATUS.approved,
    search_like: searchLike,
    offset,
    page_size: pageSize,
  });

  const lang = resolveHwyMemberDirectoryDetailLang(queryLang);
  await attachBaseInfoTitles(
    rows,
    [
      { codeField: 'latestRequestReasonCode', titleField: 'latestRequestReasonCodeTitle' },
      { codeField: 'latestFinalReasonCode', titleField: 'latestFinalReasonCodeTitle' },
    ],
    lang,
  );

  const mappedRows = rows.map((row) => {
    const member = mapFace(row, 'member');
    const executorId = trim(row.executorId as string | undefined);
    const executorMemberId = parseHwyTarghinExecutorMemberId(executorId);
    return {
      memberId: member.id,
      member,
      membershipStatusUpdatedOn: row.membershipStatusUpdatedOn
        ? String(row.membershipStatusUpdatedOn)
        : null,
      membershipOn: row.membershipOn ? String(row.membershipOn) : null,
      latestRequestReasonCodeTitle: trim(row.latestRequestReasonCodeTitle as string | undefined) || undefined,
      latestRequestNote: trim(row.latestRequestNote as string | undefined) || null,
      latestFinalReasonCodeTitle: trim(row.latestFinalReasonCodeTitle as string | undefined) || undefined,
      latestFinalNote: trim(row.latestFinalNote as string | undefined) || null,
      latestFinalAt: row.latestFinalAt ? String(row.latestFinalAt) : null,
      latestProcessNegoNote: trim(row.latestProcessNegoNote as string | undefined) || null,
      executor: executorId || trim(row.executorUsername as string | undefined)
        ? mapFace(row, 'executor')
        : null,
      executorMemberId,
      executorAccountUserId: readHwyProcedureRowUserId(
        row,
        'executorAccountUserId',
        'executorUserId',
      ),
      executorRoleTitlesFromProc: parseHwyTarghinExecutorRoleTitlesCsv(
        readHwyProcedureRowValue(row, 'executorRoleTitlesCsv'),
      ),
    };
  }).filter((row) => row.memberId);

  const legacyRoleTitlesByUsername = await attachHwyTarghinMembersListExecutors(mappedRows);

  const roleTitlesByMemberId = await listHwyMemberTarghinExecutorRoleTitlesByMemberId(
    mappedRows
      .filter((row) => row.executorRoleTitlesFromProc.length === 0)
      .map((row) => {
        if (row.executorMemberId != null) {
          return row.executorMemberId;
        }
        const executorId = trim(row.executor?.id);
        return parseHwyTarghinExecutorMemberId(executorId);
      })
      .filter((id): id is number => id != null),
  );

  const resolveExecutorAccountUserId = (row: (typeof mappedRows)[number]): number | null => {
    if (row.executorAccountUserId != null && row.executorAccountUserId > 0) {
      return row.executorAccountUserId;
    }
    const faceId = trim(row.executor?.id);
    const userPrefix = faceId.startsWith('user-') ? faceId.slice('user-'.length) : '';
    if (/^\d+$/.test(userPrefix)) {
      return Number(userPrefix);
    }
    return null;
  };

  const accountUserIdsNeedingRoles = mappedRows
    .filter((row) => {
      const accountUserId = resolveExecutorAccountUserId(row);
      if (accountUserId == null) {
        return false;
      }
      const procTitles = row.executorRoleTitlesFromProc;
      const memberTitles = row.executorMemberId != null
        ? roleTitlesByMemberId.get(row.executorMemberId) ?? []
        : [];
      return procTitles.length === 0 && memberTitles.length === 0;
    })
    .map((row) => resolveExecutorAccountUserId(row)!)
    .filter((id): id is number => id != null);

  const roleTitlesByAccountUserId = await listHwyMemberTarghinExecutorRoleTitlesByUserId(
    accountUserIdsNeedingRoles,
  );

  return {
    total,
    page,
    pageSize,
    rows: mappedRows.map(({
      executorMemberId,
      executorAccountUserId,
      executorRoleTitlesFromProc,
      ...row
    }) => {
      const resolvedAccountUserId = executorAccountUserId != null && executorAccountUserId > 0
        ? executorAccountUserId
        : resolveExecutorAccountUserId({
          ...row,
          executorMemberId,
          executorAccountUserId,
          executorRoleTitlesFromProc,
        });
      const executorRoleTitles = mergeHwyTarghinExecutorRoleTitleLists(
        executorRoleTitlesFromProc,
        executorMemberId != null ? roleTitlesByMemberId.get(executorMemberId) ?? [] : [],
        resolvedAccountUserId != null ? roleTitlesByAccountUserId.get(resolvedAccountUserId) ?? [] : [],
        row.executor?.username?.trim()
          ? legacyRoleTitlesByUsername.get(row.executor.username.trim()) ?? []
          : [],
      );
      return {
        ...row,
        executorRoleTitles,
        executorMemberId: resolveTarghinRowFaceDossierMemberId(row.executorMemberId, row.executor) || null,
      };
    }),
  };
};
