import {
  HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT,
  isHwyMemberOtherAttachmentKindSlug,
} from './hwyMemberFileKindCatalog';

/** Registration slots replace the single row per kind; other attachments always append. */
export function hwyMemberFileUploadReplacesExistingRow(kindSlug: string | null | undefined): boolean {
  return !isHwyMemberOtherAttachmentKindSlug(kindSlug);
}

export type HwyMemberFileUploadKindContext = {
  kindSlug: string | null | undefined;
  kindSlugOrIdRaw: string | null | undefined;
  resolvedKindId: string;
  otherAttachmentKindId: string | null | undefined;
};

/** False when uploads must insert a new row (multi other attachments). */
export function hwyMemberFileUploadReplacesExistingRowForKind(ctx: HwyMemberFileUploadKindContext): boolean {
  if (isHwyMemberOtherAttachmentKindSlug(ctx.kindSlug)) {
    return false;
  }
  if (isHwyMemberOtherAttachmentKindSlug(ctx.kindSlugOrIdRaw)) {
    return false;
  }
  const otherId = ctx.otherAttachmentKindId?.trim();
  if (otherId && ctx.resolvedKindId.trim() === otherId) {
    return false;
  }
  return true;
}

export { HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT };