import { DataTypes, type Model, type ModelStatic, type Sequelize } from 'sequelize';
import { getControlPlaneSequelize, controlPlaneSequelizeSyncOptions } from '../../db/controlPlaneSequelize';

export type HwyBusinessRuleDocRow = {
  slug: string;
  navGroupId: string;
  title: string;
  introMarkdown: string | null;
  bodyMarkdown: string;
  sortOrder: number;
  updatedAt: Date | null;
  updatedByUsername: string | null;
};

export type HwyBusinessRuleDocModel = Model<HwyBusinessRuleDocRow, Partial<HwyBusinessRuleDocRow>> & HwyBusinessRuleDocRow;

let cachedModel: ModelStatic<HwyBusinessRuleDocModel> | null = null;

export const getHwyBusinessRuleDocModel = (
  sequelize: Sequelize = getControlPlaneSequelize(),
): ModelStatic<HwyBusinessRuleDocModel> => {
  if (cachedModel && cachedModel.sequelize === sequelize) {
    return cachedModel;
  }
  cachedModel = sequelize.define<HwyBusinessRuleDocModel>(
    'BaseHwyBusinessRuleDoc',
    {
      slug: { type: DataTypes.STRING(64), primaryKey: true },
      navGroupId: { type: DataTypes.STRING(64), allowNull: false, field: 'nav_group_id' },
      title: { type: DataTypes.STRING(500), allowNull: false },
      introMarkdown: { type: DataTypes.TEXT, allowNull: true, field: 'intro_markdown' },
      bodyMarkdown: { type: DataTypes.TEXT, allowNull: false, field: 'body_markdown' },
      sortOrder: { type: DataTypes.INTEGER, allowNull: false, defaultValue: 0, field: 'sort_order' },
      updatedAt: { type: DataTypes.DATE, allowNull: true, field: 'updated_at' },
      updatedByUsername: { type: DataTypes.STRING(128), allowNull: true, field: 'updated_by_username' },
    },
    {
      tableName: 'base_hwy_business_rule_docs',
      timestamps: false,
    },
  );
  return cachedModel;
};

export const ensureHwyBusinessRuleDocTable = async (): Promise<void> => {
  const sequelize = getControlPlaneSequelize();
  const model = getHwyBusinessRuleDocModel(sequelize);
  await model.sync(controlPlaneSequelizeSyncOptions(sequelize));
};
