import { SETTINGS_PATH } from '../../config/settingsFile';
import { readControlPlaneDatabaseSettings } from '../../db/controlPlaneDatabase';
import { prisma } from '../users/prismaHelpers';

const HWY_ETL_GEO_MAP_TABLE = 'hwy_etl_geo_map';

const qualifiedGeoMapTable = (): string => {
  const { provider } = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  return provider === 'sqlserver' ? `dbo.${HWY_ETL_GEO_MAP_TABLE}` : HWY_ETL_GEO_MAP_TABLE;
};

type GeoMapRow = {
  legacy_kind: string;
  legacy_id: bigint | number;
  legacy_secondary_id: bigint | number;
  base_info_id: string;
};

let cachedMap: Map<string, string> | null = null;
let cachedAtMs = 0;
const CACHE_TTL_MS = 300_000;

export const loadHwyEtlGeoBaseInfoIdMap = async (): Promise<Map<string, string>> => {
  const now = Date.now();
  if (cachedMap && now - cachedAtMs < CACHE_TTL_MS) {
    return cachedMap;
  }

  const table = qualifiedGeoMapTable();
  try {
    const rows = await prisma().$queryRawUnsafe<GeoMapRow[]>(
      `SELECT legacy_kind, legacy_id, legacy_secondary_id, base_info_id FROM ${table}`,
    );

    const map = new Map<string, string>();
    for (const row of rows) {
      const kind = String(row.legacy_kind ?? '').trim();
      const legacyId = Number(row.legacy_id);
      const secondary = Number(row.legacy_secondary_id);
      const baseInfoId = String(row.base_info_id ?? '').trim();
      if (!kind || !Number.isFinite(legacyId) || !baseInfoId) {
        continue;
      }
      map.set(`${kind}:${legacyId}:${secondary}`, baseInfoId);
    }

    cachedMap = map;
    cachedAtMs = now;
    return map;
  } catch {
    cachedMap = cachedMap ?? new Map();
    cachedAtMs = now;
    return cachedMap;
  }
};

export const resolveHwyEtlGeoBaseInfoId = (
  map: Map<string, string>,
  kind: 'region' | 'maktab' | 'ghavateh' | 'province' | 'circle',
  legacyId: string,
  legacySecondaryId = 0,
): string | null => {
  const trimmed = legacyId.trim();
  if (!trimmed) {
    return null;
  }
  const numeric = Number(trimmed);
  if (!Number.isFinite(numeric)) {
    return null;
  }
  return map.get(`${kind}:${Math.trunc(numeric)}:${Math.trunc(legacySecondaryId)}`) ?? null;
};
