export const HWY_INTERVIEW_2022_NOTE_MIN_LENGTH = 50;
export const HWY_INTERVIEW_2022_NOTE_MAX_LENGTH = 2048;
export const HWY_INTERVIEW_2022_HOURS_MIN = 1;
export const HWY_INTERVIEW_2022_HOURS_MAX = 24;

