export type HwyCandidatePipelineInterviewRecord = {
  interviewId: string;
  memberId: string;
  interviewOn: string;
  karizma: number;
  likeToLearnMore: number;
  showIsFan: number;
  abilityToMakeTeam: number;
  ghodratElec: number;
  knowsMasoolin: number;
  isMotefaregh: boolean;
  isMotefareghSaat: number;
  note: string;
  finalResult: number;
  finalResultTitle: string | null;
  createdBy: string | null;
  createdOn: string | null;
  hazerin: HwyInterview2022HazerinMember[];
};

export type HwyInterview2022HazerinMember = {
  memberId: string;
  username: string | null;
  firstName: string | null;
  fatherName: string | null;
  grandFatherName: string | null;
  lastName: string | null;
};

export type HwyCandidatePipelineInterviewCreatePayload = {
  memberId: string;
  interviewOn: string;
  karizma: number;
  likeToLearnMore: number;
  showIsFan: number;
  abilityToMakeTeam: number;
  ghodratElec: number;
  knowsMasoolin: number;
  isMotefaregh: boolean;
  isMotefareghSaat: number;
  note: string;
  finalResult: number;
  hazerinMemberIds: string[];
};

export const isHwyInterview2022ScoreAnswered = (scoreId: number | null | undefined): boolean => (
  scoreId != null
  && Number.isFinite(scoreId)
  && scoreId !== HWY_INTERVIEW_2022_SCORE_UNSET_ID
);

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

/** Shared client/server validation for legacy HWY_Members_Interviews_2022.Create rules. */
export const validateHwyCandidatePipelineInterviewCreate = (
  input: HwyCandidatePipelineInterviewCreatePayload,
  hazerinRoleIdsByMember: Map<string, number[]>,
  validFinalResults: ReadonlySet<number>,
): void => {
  if (!trim(input.memberId)) {
    throw new Error('memberId is required.');
  }
  if (!trim(input.interviewOn)) {
    throw new Error('interviewOn is required.');
  }
  if (!validFinalResults.has(input.finalResult)) {
    throw new Error('Invalid interview final result.');
  }

  for (const { field } of HWY_INTERVIEW_2022_SCORE_FIELDS) {
    const score = input[field];
    if (!isHwyInterview2022ScoreAnswered(score)) {
      throw new Error(`Interview score "${field}" is required.`);
    }
  }

  if (input.isMotefaregh == null) {
    throw new Error('Weekend availability (IsMotefaregh) is required.');
  }

  const hours = Number(input.isMotefareghSaat);
  if (!Number.isFinite(hours) || hours < HWY_INTERVIEW_2022_HOURS_MIN || hours > HWY_INTERVIEW_2022_HOURS_MAX) {
    throw new Error(`Daily availability hours must be between ${HWY_INTERVIEW_2022_HOURS_MIN} and ${HWY_INTERVIEW_2022_HOURS_MAX}.`);
  }

  const note = trim(input.note);
  if (note.length < HWY_INTERVIEW_2022_NOTE_MIN_LENGTH) {
    throw new Error(`Interview note must be at least ${HWY_INTERVIEW_2022_NOTE_MIN_LENGTH} characters.`);
  }
  if (note.length > HWY_INTERVIEW_2022_NOTE_MAX_LENGTH) {
    throw new Error(`Interview note must be at most ${HWY_INTERVIEW_2022_NOTE_MAX_LENGTH} characters.`);
  }

  const hazerIds = [...new Set(input.hazerinMemberIds.map((id) => trim(id)).filter(Boolean))];
  if (hazerIds.length === 0) {
    throw new Error('At least one committee member (hazer) is required.');
  }

  const committeeRoleIds = new Set<number>();
  for (const hazerId of hazerIds) {
    const roles = hazerinRoleIdsByMember.get(hazerId) ?? [];
    roles.forEach((r) => committeeRoleIds.add(r));
  }
  if (!committeeRoleIds.has(HWY_INTERVIEW_2022_REQUIRED_HAZER_ROLE_ID)) {
    throw new Error('The committee must include a supervisory office representative (role 1000037).');
  }
};
