import type { HwyRegistrationChannelShortName } from '../hwyRegistrationChannel';

/**
 * Default `hwy_institutes.id` when a channel always targets one institute (legacy dedicated URLs).
 * `general_web` has no default — institute comes from optional referrer institute code on submit.
 *
 * Server-side resolution uses `hwy_institutes.code` from the database (see
 * `hwySelfRegistrationInstituteResolve.service.ts`). This map is legacy referrer codes only.
 */
export const LEGACY_REFERRER_INSTITUTE_CODE_TO_ID: Readonly<Record<string, number>> = {
  '001': 100,
  '002': 101,
  '003': 102,
  '004': 103,
  '006': 104,
  '213951': 105,
  '213952': 106,
  '214050': 107,
  '214916': 108,
  '214917': 109,
  '215064': 110,
  '215075': 111,
  '215103': 112,
  '215109': 113,
};

/** @deprecated Use server `resolveHwySelfRegistrationInstituteId` (DB-backed). Referrer legacy codes only. */
export const resolveInstituteIdForSelfRegistration = (input: {
  channel: HwyRegistrationChannelShortName;
  referrerInstituteCode?: string | null;
}): number | null => {
  const code = input.referrerInstituteCode?.trim();
  if (code) {
    return LEGACY_REFERRER_INSTITUTE_CODE_TO_ID[code] ?? null;
  }
  return null;
};
