import { resolveDataApiLang } from '../../services/data-api/dataApiFieldEnrichment';

export function isHwyMemberDirectoryDataApiOperation(operation: {
  pathPattern?: string | null;
}): boolean {
  const pattern = String(operation.pathPattern || '').trim();
  return pattern.startsWith('/api/hwy/member-directory');
}

export function isHwyNakhebinListDataApiOperation(operation: {
  pathPattern?: string | null;
}): boolean {
  const pattern = String(operation.pathPattern || '').trim();
  return pattern === '/api/hwy/nakhebin';
}

export function resolveHwyPortalDataApiQueryLang(
  operation: { pathPattern?: string | null },
  query: Record<string, unknown>,
  req?: { headers?: Record<string, unknown> },
): string | null {
  if (isHwyMemberDirectoryDataApiOperation(operation) || isHwyNakhebinListDataApiOperation(operation)) {
    return resolveHwyMemberDirectoryQueryLang(query, req);
  }
  return null;
}

/** Member directory grid often omits `lang`; infer from Studio mount culture in Referer. */
export function resolveHwyMemberDirectoryQueryLang(
  query: Record<string, unknown>,
  req?: { headers?: Record<string, unknown> },
): string {
  const direct = typeof query.lang === 'string' ? query.lang.trim() : '';
  if (direct) {
    return direct;
  }
  const referer = typeof req?.headers?.referer === 'string' ? req.headers.referer : '';
  const cultureMatch = /\/(us|ir|iq)(?:\/|$)/i.exec(referer);
  if (cultureMatch?.[1]?.toLowerCase() === 'iq') {
    return 'ar';
  }
  if (cultureMatch?.[1]?.toLowerCase() === 'ir') {
    return 'fa';
  }
  if (cultureMatch?.[1]?.toLowerCase() === 'us') {
    return 'en';
  }
  const fromQueryDefault = resolveDataApiLang(query);
  if (fromQueryDefault !== 'en') {
    return fromQueryDefault;
  }
  // Hawiety member directory: Arabic membership status labels (legacy iq bundle).
  return 'ar';
}
