import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createEdgeDbQueryExecutor } from '../../src/core/database/EdgeDbRouter';
import { SETTINGS_PATH } from '../../src/server/config/settingsFile';
import { getDataSourcesFromSettings } from '../../src/server/db/dataSourcesStore';
import { readControlPlaneDatabaseSettings } from '../../src/server/db/controlPlaneDatabase';
import { ensureControlPlaneInitialized } from '../../src/server/db/controlPlaneInit';
import { EdgeModelService } from '../../src/server/services/data-api/edgeModelService';
import { listEdgeModels } from '../../src/server/services/data-api/edgeModelStore';
import { resetEdgeSequelizeFactoryCache } from '../../src/server/services/data-api/sequelize/edgeSequelizeFactory';
import { connectMssqlControlPlane, resolveHwyDefaultDataSource } from '../hwy-phase1/hwyDataSource';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));

export async function ensureHwyNakhebinPhoneColumns(): Promise<void> {
  const cp = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  if (cp.provider !== 'sqlserver') {
    return;
  }

  const ddl = fs.readFileSync(
    path.join(scriptDir, '../hwy-phase1/db/install/hwy_nakhebin_phone_columns.sqlserver.sql'),
    'utf8',
  );
  const pool = await connectMssqlControlPlane();
  try {
    for (const batch of ddl.split(/^\s*GO\s*$/im).map((part) => part.trim()).filter(Boolean)) {
      await pool.request().query(batch);
    }
  } finally {
    await pool.close();
  }

  await ensureControlPlaneInitialized(SETTINGS_PATH, { pushSchema: false, seedSampleData: false });

  const { source } = resolveHwyDefaultDataSource();
  const getDataSources = () => getDataSourcesFromSettings(SETTINGS_PATH);
  const edgeModelService = new EdgeModelService({
    settingsPath: SETTINGS_PATH,
    edgeDbQuery: createEdgeDbQueryExecutor({ getDataSources }),
    getDataSources,
  });
  const nakhebin = listEdgeModels().find(
    (model) => model.dataSourceId === source.id && model.objectName === 'hwy_nakhebin',
  );
  if (nakhebin) {
    await edgeModelService.refreshModel(nakhebin.id);
    await resetEdgeSequelizeFactoryCache();
  }
}
