import {

  DEFAULT_PORTAL_ABOUT_BODY,

  DEFAULT_PORTAL_ABOUT_TITLE,

  DEFAULT_PORTAL_LOGO_URL,

  DEFAULT_PORTAL_TITLE,

  normalizePortalBrand,

  type PortalBrand,

} from '../../shared/api/contracts/platform/portalBrand';



/** Default hawiety shell seed in Settings → Portals when no custom logo is uploaded yet. */

export const HWY_PLATFORM_PORTAL_BRAND_LOGO_URL = '/assets/hawiety/mark-blue.png';



export const HWY_PLATFORM_PORTAL_SHELL_KEY = 'hawiety';



/** Portal Settings title (English catalog); public chrome uses culture `hwy.selfReg.portal.tagline`. */

export const HWY_PLATFORM_PORTAL_BRAND_TITLE_EN = 'Hawiety electronic identity system';

export const HWY_PLATFORM_PORTAL_BRAND_WINDOW_TITLE = 'هویتی';

export const defaultHwyPlatformPortalBrand = (): PortalBrand => ({

  logoUrl: HWY_PLATFORM_PORTAL_BRAND_LOGO_URL,

  title: HWY_PLATFORM_PORTAL_BRAND_TITLE_EN,

  windowTitle: HWY_PLATFORM_PORTAL_BRAND_WINDOW_TITLE,

  aboutTitle: HWY_PLATFORM_PORTAL_BRAND_TITLE_EN,

  aboutBody:

    'Official Hawiety membership registration and public identity flows for the National Wisdom Movement.',

});



export const isAppEndPlaceholderPortalTitle = (title: string | null | undefined): boolean => {

  const trimmed = title?.trim();

  if (!trimmed) {

    return true;

  }

  return trimmed === DEFAULT_PORTAL_TITLE || trimmed === 'AppEnd' || trimmed === 'AppEndO';

};



export const isAppEndPlaceholderPortalAboutTitle = (title: string | null | undefined): boolean => {

  const trimmed = title?.trim();

  if (!trimmed) {

    return true;

  }

  return trimmed === DEFAULT_PORTAL_ABOUT_TITLE;

};



export const isAppEndPlaceholderPortalAboutBody = (body: string | null | undefined): boolean => {

  const trimmed = body?.trim();

  if (!trimmed) {

    return true;

  }

  return trimmed === DEFAULT_PORTAL_ABOUT_BODY;

};



/** True when the shell still has the generic AppEnd placeholder from an old seed. */

export const isPlaceholderAppEndPortalBrand = (brand: PortalBrand | null | undefined): boolean => {

  const normalized = normalizePortalBrand(brand);

  if (!normalized) {

    return true;

  }

  const logo = normalized.logoUrl?.trim() || '';

  if (!logo || logo === DEFAULT_PORTAL_LOGO_URL) {

    return true;

  }

  return (

    isAppEndPlaceholderPortalTitle(normalized.title)

    || isAppEndPlaceholderPortalAboutTitle(normalized.aboutTitle)

  );

};


