const resolveMemberDirectoryListScopeDefinition = (
  listScopeLegacy: string,
): HwyMemberSegmentListDefinition | null => {
  const normalized = normalizeHwyMemberListScopeLegacyCode(listScopeLegacy.trim());
  if (normalized === 'HWY_Members_List_All') {
    return HWY_MEMBERS_LIST_ALL_DEFINITION;
  }
  if (normalized === HWY_MEMBER_QUICK_SEARCH_DEFINITION.legacyCode) {
    return HWY_MEMBER_QUICK_SEARCH_DEFINITION;
  }
  return findHwyMemberSegmentListByLegacyCode(listScopeLegacy) ?? null;
};

const camelToSnake = (field: string): string => (
  field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`)
);

/** Data API / vw_hwy_members field names that differ from dbo.hwy_members column names. */
const MEMBER_PHYSICAL_COLUMN_BY_VIEW_FIELD: Readonly<Record<string, string>> = {
  fathername: 'father_name',
  grandfathername: 'grandfather_name',
  firstname: 'first_name',
  lastname: 'family_name',
  nationalcode: 'national_id',
};

/** SQL result aliases must match vw_hwy_members (mapMemberDirectoryFastPathRowKeysToCamel → API keys). */
const MEMBER_DIRECTORY_OUTPUT_ALIAS_BY_PHYSICAL: Readonly<Record<string, string>> = {
  father_name: 'fathername',
  grandfather_name: 'grandfathername',
  first_name: 'firstname',
  family_name: 'lastname',
  national_id: 'national_code',
};

const resolveMemberPhysicalColumn = (field: string): string | null => {
  const snake = camelToSnake(field);
  const physical = MEMBER_PHYSICAL_COLUMN_BY_VIEW_FIELD[snake] ?? snake;
  if (physical === 'id' || !HWY_MEMBERS_PHYSICAL_COLUMNS.has(physical)) {
    return null;
  }
  return physical;
};

const resolveMemberDirectoryOutputAlias = (field: string, physicalCol: string): string => (
  MEMBER_DIRECTORY_OUTPUT_ALIAS_BY_PHYSICAL[physicalCol] ?? camelToSnake(field)
);

const normalizeAttrKey = (field: string): string => camelToSnake(field.replace(/-/g, '_'));

const MEMBER_VOTE_PARTICIPATION_FIELDS = new Set([
  'voted_on_2021',
  'voted_on_2023',
  'voted_on_2025',
]);

/** Data API uses camelCase (`votedOn2021`); normalizeAttrKey yields `voted_on2021` (no underscore before year). */
const VOTE_PARTICIPATION_CAMEL_FIELDS = new Set(['votedOn2021', 'votedOn2023', 'votedOn2025']);

const attributesIncludeVoteParticipation = (attributes: string[]): boolean => (
  attributes.some((field) => {
    const trimmed = field.trim();
    if (VOTE_PARTICIPATION_CAMEL_FIELDS.has(trimmed)) {
      return true;
    }
    return MEMBER_VOTE_PARTICIPATION_FIELDS.has(normalizeAttrKey(trimmed));
  })
);

const voteParticipationSelectExpression = (
  sequelize: Sequelize,
  year: '2021' | '2023' | '2025',
): string => {
  const dialect = sequelize.getDialect();
  const col = `voted_on_${year}`;
  const q = (name: string) => (dialect === 'mssql' ? `[${name}]` : `"${name}"`);
  const empty = dialect === 'mssql' ? "N''" : "''";
  const trimMember = `NULLIF(LTRIM(RTRIM(m.${q(col)})), ${empty})`;
  const trimNakhebin = `NULLIF(LTRIM(RTRIM(n.${q(col)})), ${empty})`;
  const trimLinked = `NULLIF(LTRIM(RTRIM(nb_member.${q(col)})), ${empty})`;
  return `COALESCE(${trimMember}, ${trimNakhebin}, ${trimLinked}) AS ${q(col)}`;
};

const memberLinkedNakhebinApplyClause = (nakhebinTable: string): string => `
OUTER APPLY (
  SELECT TOP (1) voted_on_2021, voted_on_2023, voted_on_2025
  FROM ${nakhebinTable} nb
  WHERE nb.member_id = m.id
  ORDER BY nb.id DESC
) nb_member`.trim();

type JoinNeeds = {
  users: boolean;
  profiles: boolean;
  nakhebin: boolean;
  memberLinkedNakhebin: boolean;
  tracking: boolean;
};

const resolveJoinNeeds = (attributes: string[]): JoinNeeds => {
  const keys = new Set(attributes.map(normalizeAttrKey));
  const needsProfiles = [
    'display_full_name',
    'has_profile_image',
    'avatar_url',
    'phone1',
    'firstname',
    'lastname',
    'fathername',
    'grandfathername',
    'nickname',
    'national_code',
    'birth_year',
    'birth_month',
    'birth_day',
    'gender_code',
    'person_type_code',
  ].some((key) => keys.has(key));
  const needsUsers = true;
  const needsNakhebin = [
    'nakhebin_family_code',
    'nakhebin_region_id',
    'nakhebin_maktab_id',
    'nakhebin_id',
    ...MEMBER_VOTE_PARTICIPATION_FIELDS,
  ].some((key) => keys.has(key)) || attributesIncludeVoteParticipation(attributes);
  const needsTracking = keys.has('tracking_code') || keys.has('trackingCode');
  const needsMemberLinkedNakhebin = attributesIncludeVoteParticipation(attributes);
  return {
    users: needsUsers,
    profiles: needsProfiles,
    nakhebin: needsNakhebin,
    memberLinkedNakhebin: needsMemberLinkedNakhebin,
    tracking: needsTracking,
  };
};

const memberSelectExpressions = (
  sequelize: Sequelize,
  attributes: string[],
  joinNeeds: JoinNeeds,
): string[] => {
  const dialect = sequelize.getDialect();
  const q = (name: string) => (dialect === 'mssql' ? `[${name}]` : `"${name}"`);
  const m = 'm';
  const exprs = new Set<string>();
  exprs.add(`${m}.${q('id')} AS ${q('id')}`);

  const addMemberCol = (field: string) => {
    const physical = resolveMemberPhysicalColumn(field);
    if (!physical) {
      return;
    }
    const alias = resolveMemberDirectoryOutputAlias(field, physical);
    exprs.add(`${m}.${q(physical)} AS ${q(alias)}`);
  };

  for (const field of attributes) {
    if (field === 'displayFullName' || field === 'display_full_name') {
      if (joinNeeds.profiles) {
        exprs.add(`${dialect === 'mssql'
          ? `CONCAT_WS(N' ', NULLIF(LTRIM(RTRIM(COALESCE(p.firstname, m.first_name))), N''), NULLIF(LTRIM(RTRIM(COALESCE(p.fathername, m.father_name))), N''), NULLIF(LTRIM(RTRIM(COALESCE(p.grandfathername, m.grandfather_name))), N''), NULLIF(LTRIM(RTRIM(COALESCE(p.lastname, m.family_name))), N''))`
          : `CONCAT_WS(' ', NULLIF(TRIM(COALESCE(p.firstname, m.first_name)), ''), NULLIF(TRIM(COALESCE(p.fathername, m.father_name)), ''), NULLIF(TRIM(COALESCE(p.grandfathername, m.grandfather_name)), ''), NULLIF(TRIM(COALESCE(p.lastname, m.family_name)), ''))`
        } AS ${q('display_full_name')}`);
      }
      continue;
    }
    if (field === 'hasProfileImage' || field === 'has_profile_image') {
      if (joinNeeds.profiles) {
        exprs.add(`${dialect === 'mssql'
          ? `CASE WHEN p.profile_image_body IS NULL THEN CAST(0 AS bit) ELSE CAST(1 AS bit) END`
          : `CASE WHEN p.profile_image_body IS NULL THEN false ELSE true END`
        } AS ${q('has_profile_image')}`);
      }
      continue;
    }
    if (field === 'avatarUrl' || field === 'avatar_url') {
      if (joinNeeds.profiles) {
        exprs.add(`${dialect === 'mssql'
          ? `CASE WHEN p.profile_image_body IS NOT NULL AND m.user_id IS NOT NULL THEN CONCAT(N'/api/users/', CAST(m.user_id AS VARCHAR(20)), N'/avatar-xs') ELSE NULL END`
          : `CASE WHEN p.profile_image_body IS NOT NULL AND m.user_id IS NOT NULL THEN '/api/users/' || m.user_id || '/avatar-xs' ELSE NULL END`
        } AS ${q('avatar_url')}`);
      }
      continue;
    }
    if (field === 'username') {
      const empty = dialect === 'mssql' ? "N''" : "''";
      if (joinNeeds.users) {
        const memberIdText = dialect === 'mssql'
          ? `CAST(${m}.${q('id')} AS VARCHAR(32))`
          : `CAST(${m}.${q('id')} AS TEXT)`;
        const allocatedFromColumn = (columnExpr: string): string => {
          const trimmed = `NULLIF(LTRIM(RTRIM(${columnExpr})), ${empty})`;
          if (dialect === 'mssql') {
            return `CASE
              WHEN ${trimmed} IS NOT NULL
                AND ${trimmed} <> ${memberIdText}
                AND LOWER(${trimmed}) <> N'm' + ${memberIdText}
                AND LOWER(${trimmed}) <> N'hwy-m-' + ${memberIdText}
                AND LEN(${trimmed}) = 6
                AND ${trimmed} NOT LIKE N'%[^0-9]%'
              THEN ${trimmed}
              ELSE NULL
            END`;
          }
          return `CASE
            WHEN ${trimmed} IS NOT NULL
              AND ${trimmed} <> ${memberIdText}
              AND LOWER(${trimmed}) <> 'm' || ${memberIdText}
              AND LOWER(${trimmed}) <> 'hwy-m-' || ${memberIdText}
              AND char_length(${trimmed}) = 6
              AND ${trimmed} ~ '^[0-9]+$'
            THEN ${trimmed}
            ELSE NULL
          END`;
        };
        const allocatedMemberUsername = allocatedFromColumn(`${m}.${q('username')}`);
        const allocatedUserUsername = allocatedFromColumn(`u.${q('username')}`);
        exprs.add(
          `NULLIF(LTRIM(RTRIM(COALESCE(${allocatedMemberUsername}, ${allocatedUserUsername}))), ${empty}) AS ${q('username')}`,
        );
      } else {
        exprs.add(`NULLIF(LTRIM(RTRIM(${m}.${q('username')})), ${empty}) AS ${q('username')}`);
      }
      continue;
    }
    if (field === 'phone1') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.phone, ${m}.${q('phone1')}) AS ${q('phone1')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'nationalCode' || field === 'national_code') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.national_code, ${m}.${q('national_id')}) AS ${q('national_code')}`);
      } else {
        addMemberCol('nationalCode');
      }
      continue;
    }
    if (field === 'birthYear' || field === 'birth_year') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.birth_year, ${m}.${q('birth_year')}) AS ${q('birth_year')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'genderCode' || field === 'gender_code') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.gender_code, ${m}.${q('gender_code')}) AS ${q('gender_code')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'trackingCode' || field === 'tracking_code') {
      if (joinNeeds.tracking) {
        exprs.add(`CAST(m.id AS NVARCHAR(32)) AS ${q('tracking_code')}`);
      }
      continue;
    }
    if (field === 'nakhebinFamilyCode' || field === 'nakhebin_family_code') {
      exprs.add(`n.family_code AS ${q('nakhebin_family_code')}`);
      continue;
    }
    if (field === 'nakhebinRegionId' || field === 'nakhebin_region_id') {
      exprs.add(`n.region_id AS ${q('nakhebin_region_id')}`);
      continue;
    }
    if (field === 'nakhebinMaktabId' || field === 'nakhebin_maktab_id') {
      exprs.add(`n.maktab_id AS ${q('nakhebin_maktab_id')}`);
      continue;
    }
    if (
      field === 'votedOn2021' || field === 'voted_on_2021'
      || field === 'votedOn2023' || field === 'voted_on_2023'
      || field === 'votedOn2025' || field === 'voted_on_2025'
    ) {
      const year = field.includes('2021') ? '2021' : field.includes('2023') ? '2023' : '2025';
      exprs.add(voteParticipationSelectExpression(sequelize, year));
      continue;
    }
    if (field === 'firstname' || field === 'lastname') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q(field === 'firstname' ? 'firstname' : 'lastname')}, ${m}.${q(field === 'firstname' ? 'first_name' : 'family_name')}) AS ${q(camelToSnake(field))}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'fathername' || field === 'father_name') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q('fathername')}, ${m}.${q('father_name')}) AS ${q('fathername')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'grandfathername' || field === 'grandfather_name') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q('grandfathername')}, ${m}.${q('grandfather_name')}) AS ${q('grandfathername')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'nickname') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q('nickname')}, ${m}.${q('nickname')}) AS ${q('nickname')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'birthMonth' || field === 'birth_month') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q('birth_month')}, ${m}.${q('birth_month')}) AS ${q('birth_month')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'birthDay' || field === 'birth_day') {
      if (joinNeeds.profiles) {
        exprs.add(`COALESCE(p.${q('birth_day')}, ${m}.${q('birth_day')}) AS ${q('birth_day')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'personTypeCode' || field === 'person_type_code') {
      if (joinNeeds.profiles) {
        const defaultPersonType = dialect === 'mssql' ? "N'100.2.1'" : "'100.2.1'";
        exprs.add(`COALESCE(p.${q('person_type_code')}, ${defaultPersonType}) AS ${q('person_type_code')}`);
      }
      continue;
    }
    if (field === 'email') {
      if (joinNeeds.users) {
        exprs.add(`COALESCE(u.${q('email')}, ${m}.${q('email')}) AS ${q('email')}`);
      } else {
        addMemberCol(field);
      }
      continue;
    }
    if (field === 'userMobile' || field === 'user_mobile') {
      if (joinNeeds.users) {
        exprs.add(`u.${q('mobile')} AS ${q('user_mobile')}`);
      }
      continue;
    }
    if (field === 'userLocked' || field === 'user_locked') {
      if (joinNeeds.users) {
        exprs.add(`u.${q('locked')} AS ${q('user_locked')}`);
      }
      continue;
    }
    if (field === 'lastLoginAt' || field === 'last_login_at') {
      if (joinNeeds.users) {
        exprs.add(`u.${q('last_login_at')} AS ${q('last_login_at')}`);
      }
      continue;
    }
    addMemberCol(field);
  }

  const userIdAlias = `${q('user_id')}`;
  if (![...exprs].some((expr) => expr.includes(userIdAlias))) {
    exprs.add(`${m}.${q('user_id')} AS ${userIdAlias}`);
  }

  return [...exprs];
};

const buildOrderClause = (sequelize: Sequelize, order: Order | undefined, joinNeeds: JoinNeeds): string => {
  if (!order || order.length === 0) {
    return 'm.updated_at DESC, m.id ASC';
  }
  const parts: string[] = [];
  for (const item of order) {
    if (!Array.isArray(item)) {
      continue;
    }
    const [field, dir] = item;
    if (typeof field !== 'string') {
      continue;
    }
    const col = camelToSnake(field);
    const direction = String(dir ?? 'ASC').toUpperCase() === 'DESC' ? 'DESC' : 'ASC';
    if ((col === 'lastname' || col === 'firstname') && joinNeeds.profiles) {
      parts.push(`COALESCE(p.${col}, m.${col === 'lastname' ? 'family_name' : 'first_name'}) ${direction}`);
      continue;
    }
    parts.push(`m.${col} ${direction}`);
  }
  if (parts.length === 0) {
    return 'm.updated_at DESC, m.id ASC';
  }
  return parts.join(', ');
};

export const mapMemberDirectoryFastPathRowKeysToCamel = (
  row: Record<string, unknown>,
): Record<string, unknown> => {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    out[toCamelCaseField(key)] = value;
  }
  return out;
};

export const canUseMemberDirectoryListFastPath = (
  listScopeLegacy: string | null,
  hasStructuredFilters: boolean,
): boolean => {
  if (!listScopeLegacy || hasStructuredFilters) {
    return false;
  }
  const definition = resolveMemberDirectoryListScopeDefinition(listScopeLegacy);
  if (!definition) {
    return false;
  }
  return SCOPE_FAST_TYPES.has(definition.scope.type);
};

type ScopeQueryPlan = {
  fromSql: string;
  whereSql: string;
  replacements: Record<string, unknown>;
};

const buildJoinTasjilRegisteredClause = (
  nakhebinJoinTasjilStateCode: string | undefined,
): { sql: string; replacements: Record<string, unknown> } => {
  const code = nakhebinJoinTasjilStateCode?.trim() ?? '';
  if (!code) {
    return { sql: '', replacements: {} };
  }
  return {
    sql: 'AND m.nakhebin_join_tasjil_state_code = :nakhebinJoinTasjilStateCode',
    replacements: { nakhebinJoinTasjilStateCode: code },
  };
};

const buildSearchClause = (sequelize: Sequelize, search: string | undefined): {
  sql: string;
  replacements: Record<string, unknown>;
} => {
  const trimmed = search?.trim() ?? '';
  if (!trimmed) {
    return { sql: '', replacements: {} };
  }
  const dialect = sequelize.getDialect();
  const idCast = dialect === 'mssql' ? 'CAST(m.id AS NVARCHAR(32))' : 'CAST(m.id AS TEXT)';
  const sql = `AND (
    m.phone1 LIKE :searchLike OR m.phone2 LIKE :searchLike OR m.username LIKE :searchLike
    OR m.first_name LIKE :searchLike OR m.family_name LIKE :searchLike OR m.national_id LIKE :searchLike
    OR ${idCast} LIKE :searchLike
  )`;
  return { sql, replacements: { searchLike: `%${trimmed}%` } };
};

const resolveScopeQueryPlan = async (
  sequelize: Sequelize,
  scope: HwyMemberListScopeKind,
): Promise<ScopeQueryPlan> => {
  const ctx = await loadHwyMemberListScopeContext();
  const dialect = sequelize.getDialect();
  const membersTable = dialect === 'mssql' ? 'dbo.hwy_members' : 'hwy_members';
  const institutesTable = dialect === 'mssql' ? 'dbo.hwy_member_institutes' : 'hwy_member_institutes';
  const indexHint = dialect === 'mssql' ? ' WITH (INDEX(idx_hwy_member_institutes_scope))' : '';

  switch (scope.type) {
    case 'membership_status':
      return {
        fromSql: `FROM ${membersTable} m`,
        whereSql: 'WHERE m.membership_status_code = :membershipStatusCode',
        replacements: { membershipStatusCode: ctx.membershipStatusCodes[scope.status] },
      };
    case 'active_institute': {
      const instituteId = await resolveHwyMemberListInstituteIdForScope(sequelize, scope.instituteCode);
      const channelSql = scope.excludeOtherPortalChannel
        ? `AND COALESCE(m.registration_channel_code, N'') <> :otherPortalChannelCode`
        : '';
      const otherPortalChannelCode = scope.excludeOtherPortalChannel
        ? await tryFindHwyBaseInfoItemIdByShortName('Registration Channel', 'other_portal')
        : null;
      return {
        fromSql: `FROM ${institutesTable} mi${indexHint}
INNER JOIN ${membersTable} m ON m.id = mi.member_id
  AND m.membership_status_code = :membershipStatusCode`,
        whereSql: `WHERE mi.institute_id = :instituteId ${channelSql}`,
        replacements: {
          instituteId,
          membershipStatusCode: ctx.membershipStatusCodes.active,
          ...(otherPortalChannelCode ? { otherPortalChannelCode } : {}),
        },
      };
    }
    case 'pending_local_institute': {
      const instituteId = await resolveHwyMemberListInstituteIdForScope(sequelize, scope.instituteCode);
      if (instituteId == null) {
        throw new Error(`Unknown institute: ${scope.instituteCode}`);
      }
      return {
        fromSql: `FROM ${institutesTable} mi${indexHint}
INNER JOIN ${membersTable} m ON m.id = mi.member_id
  AND m.membership_status_code = :membershipStatusCode`,
        whereSql: 'WHERE mi.institute_id = :instituteId AND mi.status_code = :instituteMemberStatus',
        replacements: {
          instituteId,
          instituteMemberStatus: ctx.instituteMembershipActiveCode,
          membershipStatusCode: ctx.membershipStatusCodes.pending_local,
        },
      };
    }
    case 'directory_unrestricted':
      return {
        fromSql: `FROM ${membersTable} m`,
        whereSql: 'WHERE 1 = 1',
        replacements: {},
      };
    case 'under_18_active': {
      const birthYearPredicate = dialect === 'mssql'
        ? 'TRY_CAST(m.birth_year AS INT) > YEAR(GETDATE()) - 18'
        : `CAST(NULLIF(TRIM(CAST(m.birth_year AS TEXT)), '') AS INT) > EXTRACT(YEAR FROM CURRENT_DATE)::INT - 18`;
      return {
        fromSql: `FROM ${membersTable} m`,
        whereSql: `WHERE m.membership_status_code = :membershipStatusCode AND ${birthYearPredicate}`,
        replacements: { membershipStatusCode: ctx.membershipStatusCodes.active },
      };
    }
    case 'registration_image_fix_todo': {
      const filesTable = dialect === 'mssql' ? 'dbo.hwy_member_files' : 'hwy_member_files';
      const [otherPortalChannelCode, fileKindCodes] = await Promise.all([
        tryFindHwyBaseInfoItemIdByShortName('Registration Channel', 'other_portal'),
        loadImageFixTodoFileKindCodes(),
      ]);
      if (fileKindCodes.length === 0) {
        return {
          fromSql: `FROM ${membersTable} m`,
          whereSql: 'WHERE 1 = 0',
          replacements: {},
        };
      }
      const kindIn = fileKindCodes.map((_, index) => `:fileKind${index}`).join(', ');
      const kindReplacements = Object.fromEntries(
        fileKindCodes.map((code, index) => [`fileKind${index}`, code]),
      );
      const channelSql = otherPortalChannelCode
        ? `AND COALESCE(m.registration_channel_code, N'') <> :otherPortalChannelCode`
        : '';
      const contentPredicate = dialect === 'mssql'
        ? `ISNULL(f.is_approved, 0) = 0
      AND (
        (f.content IS NOT NULL AND DATALENGTH(f.content) > 0)
        OR (f.thumbnail_content IS NOT NULL AND DATALENGTH(f.thumbnail_content) > 0)
        OR ISNULL(f.size_bytes, 0) > 0
      )`
        : `COALESCE(f.is_approved, FALSE) IS NOT TRUE
      AND (
        (f.content IS NOT NULL AND octet_length(f.content) > 0)
        OR (f.thumbnail_content IS NOT NULL AND octet_length(f.thumbnail_content) > 0)
        OR COALESCE(f.size_bytes, 0) > 0
      )`;
      const auditPendingFilter = dialect === 'mssql'
        ? 'AND COALESCE(m.nakheb_card_front_check, 0) = 0'
        : 'AND COALESCE(m.nakheb_card_front_check, FALSE) IS NOT TRUE';
      return {
        fromSql: `FROM ${membersTable} m`,
        whereSql: `WHERE m.membership_status_code IN (:activeStatusCode, :pendingLocalStatusCode)
  ${channelSql}
  ${auditPendingFilter}
  AND EXISTS (
    SELECT 1 FROM ${filesTable} f
    WHERE f.member_id = m.id
      AND ${contentPredicate}
      AND f.file_kind_code IN (${kindIn})
  )`,
        replacements: {
          activeStatusCode: ctx.membershipStatusCodes.active,
          pendingLocalStatusCode: ctx.membershipStatusCodes.pending_local,
          ...(otherPortalChannelCode ? { otherPortalChannelCode } : {}),
          ...kindReplacements,
        },
      };
    }
    default:
      throw new Error('Scope not supported on fast path.');
  }
};

export const fetchMemberDirectoryListFastPath = async (
  input: MemberDirectoryListFastPathInput,
): Promise<Record<string, unknown>[]> => {
  const definition = resolveMemberDirectoryListScopeDefinition(input.listScopeLegacy);
  if (!definition || !SCOPE_FAST_TYPES.has(definition.scope.type)) {
    throw new Error('Member directory list fast path is not available for this scope.');
  }

  const { sequelize, attributes, order, limit, offset } = input;
  const dialect = sequelize.getDialect();
  const usersTable = dialect === 'mssql' ? 'dbo.base_users' : 'base_users';
  const profilesTable = dialect === 'mssql' ? 'dbo.base_user_profiles' : 'base_user_profiles';
  const nakhebinTable = dialect === 'mssql' ? 'dbo.hwy_nakhebin' : 'hwy_nakhebin';
  const joinNeeds = resolveJoinNeeds(attributes);
  const { fromSql, whereSql, replacements } = await resolveScopeQueryPlan(sequelize, definition.scope);
  const { sql: searchSql, replacements: searchReplacements } = buildSearchClause(sequelize, input.search);
  const { sql: joinTasjilSql, replacements: joinTasjilReplacements } = buildJoinTasjilRegisteredClause(
    input.nakhebinJoinTasjilStateCode,
  );
  const { sql: montadheminInstituteSql, replacements: montadheminInstituteReplacements } =
    await buildHwyMontadheminInstituteFilterSqlClause(
      sequelize,
      input.montadheminInstituteIds ?? [],
      input.montadheminInstituteMatch,
    );
  const selectList = memberSelectExpressions(sequelize, attributes, joinNeeds).join(',\n  ');
  const orderBy = buildOrderClause(sequelize, order, joinNeeds);

  const joinClauses: string[] = [];
  if (joinNeeds.users) {
    joinClauses.push(`LEFT JOIN ${usersTable} u ON u.id = m.user_id`);
  }
  if (joinNeeds.profiles) {
    joinClauses.push(`LEFT JOIN ${profilesTable} p ON p.user_id = m.user_id`);
  }
  if (joinNeeds.nakhebin) {
    joinClauses.push(`LEFT JOIN ${nakhebinTable} n ON n.id = m.nakhebin_id`);
  }
  if (joinNeeds.memberLinkedNakhebin) {
    joinClauses.push(memberLinkedNakhebinApplyClause(nakhebinTable));
  }
  const sql = `
SELECT ${selectList}
${fromSql}
${joinClauses.join('\n')}
${whereSql}
${searchSql}
${joinTasjilSql}
${montadheminInstituteSql}
ORDER BY ${orderBy}
OFFSET :offset ROWS FETCH NEXT :limit ROWS ONLY`;

  const rows = await sequelize.query<Record<string, unknown>>(sql, {
    type: QueryTypes.SELECT,
    replacements: {
      ...replacements,
      ...searchReplacements,
      ...joinTasjilReplacements,
      ...montadheminInstituteReplacements,
      offset,
      limit,
    },
  });

  return rows.map(mapMemberDirectoryFastPathRowKeysToCamel);
};

export const countMemberDirectoryListFastPath = async (
  input: Pick<
    MemberDirectoryListFastPathInput,
    | 'sequelize'
    | 'listScopeLegacy'
    | 'search'
    | 'nakhebinJoinTasjilStateCode'
    | 'montadheminInstituteIds'
    | 'montadheminInstituteMatch'
  >,
): Promise<number> => {
  const definition = resolveMemberDirectoryListScopeDefinition(input.listScopeLegacy);
  if (!definition || !SCOPE_FAST_TYPES.has(definition.scope.type)) {
    throw new Error('Member directory list fast path count is not available for this scope.');
  }

  const { sequelize } = input;
  const { fromSql, whereSql, replacements } = await resolveScopeQueryPlan(sequelize, definition.scope);
  const { sql: searchSql, replacements: searchReplacements } = buildSearchClause(sequelize, input.search);
  const { sql: joinTasjilSql, replacements: joinTasjilReplacements } = buildJoinTasjilRegisteredClause(
    input.nakhebinJoinTasjilStateCode,
  );
  const { sql: montadheminInstituteSql, replacements: montadheminInstituteReplacements } =
    await buildHwyMontadheminInstituteFilterSqlClause(
      sequelize,
      input.montadheminInstituteIds ?? [],
      input.montadheminInstituteMatch,
    );
  const instituteScoped = definition.scope.type === 'active_institute'
    || definition.scope.type === 'pending_local_institute';
  const countExpr = instituteScoped ? 'COUNT(DISTINCT m.id)' : 'COUNT(*)';
  const sql = `
SELECT ${countExpr} AS cnt
${fromSql}
${whereSql}
${searchSql}
${joinTasjilSql}
${montadheminInstituteSql}`;

  const rows = await sequelize.query<{ cnt: number | string }>(sql, {
    type: QueryTypes.SELECT,
    replacements: {
      ...replacements,
      ...searchReplacements,
      ...joinTasjilReplacements,
      ...montadheminInstituteReplacements,
    },
  });
  const raw = rows[0]?.cnt;
  const parsed = typeof raw === 'number' ? raw : Number(raw);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : 0;
};

export const resolveFastPathDefinition = (
  listScopeLegacy: string,
): HwyMemberSegmentListDefinition | undefined => (
  resolveMemberDirectoryListScopeDefinition(listScopeLegacy) ?? undefined
);

/** View scalar UDFs — resolved in JS after fetch (see list fast path). */
export const MEMBER_DIRECTORY_VIEW_UDF_FIELDS = new Set([
  'electoralDivisionPath',
]);

export const canUseMemberDirectoryGetOneFastPath = (sequelize: Sequelize): boolean => (
  sequelize.getDialect() === 'mssql'
);

/** Single-row fetch by primary key — avoids vw_hwy_members UDFs that timeout getOne. */
export const fetchMemberDirectoryGetOneFastPath = async (
  sequelize: Sequelize,
  memberId: string,
  attributes: string[],
): Promise<Record<string, unknown> | null> => {
  if (!canUseMemberDirectoryGetOneFastPath(sequelize)) {
    return null;
  }
  const trimmedId = memberId.trim();
  if (!trimmedId) {
    return null;
  }

  const usersTable = 'dbo.base_users';
  const profilesTable = 'dbo.base_user_profiles';
  const nakhebinTable = 'dbo.hwy_nakhebin';
  const membersTable = 'dbo.hwy_members';

  const attrsForSelect = [
    ...new Set([
      ...attributes.filter((field) => !MEMBER_DIRECTORY_VIEW_UDF_FIELDS.has(field)),
      'addrProvinceId',
      'addrMaktabId',
      'addrRegionId',
      'nakhebinRegionId',
      'nakhebinMaktabId',
      'nakhebinId',
    ]),
  ];
  const joinNeeds = resolveJoinNeeds(attrsForSelect);
  const selectList = memberSelectExpressions(sequelize, attrsForSelect, joinNeeds).join(',\n  ');

  const joinClauses: string[] = [];
  if (joinNeeds.users) {
    joinClauses.push(`LEFT JOIN ${usersTable} u ON u.id = m.user_id`);
  }
  if (joinNeeds.profiles) {
    joinClauses.push(`LEFT JOIN ${profilesTable} p ON p.user_id = m.user_id`);
  }
  if (joinNeeds.nakhebin) {
    joinClauses.push(`LEFT JOIN ${nakhebinTable} n ON n.id = m.nakhebin_id`);
  }
  if (joinNeeds.memberLinkedNakhebin) {
    joinClauses.push(memberLinkedNakhebinApplyClause(nakhebinTable));
  }

  const sql = `
SELECT ${selectList}
FROM ${membersTable} m
${joinClauses.join('\n')}
WHERE m.username = :lookup
   OR CAST(m.id AS NVARCHAR(32)) = :lookup`;

  const rows = await sequelize.query<Record<string, unknown>>(sql, {
    type: QueryTypes.SELECT,
    replacements: { lookup: trimmedId },
  });
  const row = rows[0];
  return row ? mapMemberDirectoryFastPathRowKeysToCamel(row) : null;
};
