import { QueryTypes } from 'sequelize';

import { canDeleteHwyMemberFileRow } from '../../../domain/hwy/hwyMemberDossierEditPolicy';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { resolveHwyMemberFileKindSlugById } from './hwyMemberFileKindResolve.service';

const parseFileId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('File id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('File id is invalid.');
  }
  return id;
};

export async function deleteHwyMemberDossierFile(fileIdRaw: string): Promise<void> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Member file delete requires SQL Server control plane.');
  }

  const fileId = parseFileId(fileIdRaw);
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();

  const rows = await sequelize.query<{ fileKindCode: string }>(
    `
    SELECT file_kind_code AS fileKindCode
    FROM dbo.hwy_member_files
    WHERE id = :fileId
    `,
    { replacements: { fileId }, type: QueryTypes.SELECT },
  );
  const fileKindCode = String(rows[0]?.fileKindCode ?? '').trim();
  if (!fileKindCode) {
    throw new Error('File not found.');
  }

  const slug = await resolveHwyMemberFileKindSlugById(fileKindCode);
  if (!canDeleteHwyMemberFileRow({ fileKindSlug: slug })) {
    throw new Error('This document cannot be removed from the dossier.');
  }

  const deleted = await execHwyProcedure<{ deleted: number }>('hwy_member_file_delete', {
    file_id: fileId,
  });

  if (!deleted[0]?.deleted) {
    throw new Error('File not found.');
  }
}
