import type {
  HwyMemberNakhebinJoinCandidateFilter,
  HwyMemberNakhebinJoinCandidateRow,
  HwyMemberNakhebinJoinCandidatesPayload,
} from '../../../domain/hwy/hwyMemberNakhebinJoinCandidates';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const readRowString = (row: Record<string, unknown>, key: string): string => {
  const raw = row[key];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

const parseFilterFlag = (raw: string | null | undefined, fallback: boolean): boolean => {
  const value = String(raw ?? '').trim();
  if (value === '1' || value.toLowerCase() === 'true') {
    return true;
  }
  if (value === '0' || value.toLowerCase() === 'false') {
    return false;
  }
  return fallback;
};

export async function listHwyMemberNakhebinJoinCandidates(
  memberIdRaw: string,
  filterInput: HwyMemberNakhebinJoinCandidateFilter,
  scopeRegionGeoId?: string | null,
): Promise<HwyMemberNakhebinJoinCandidatesPayload> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Nakhebin join search is not available in this environment.');
  }
  const memberId = parseMemberId(memberIdRaw);
  await ensureHwyDbObjects();
  const scopeRegion = String(scopeRegionGeoId ?? '').trim() || null;
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_member_nakhebin_join_candidates', {
    member_id: memberId,
    match_first_name: filterInput.matchFirstName ? 1 : 0,
    match_father_name: filterInput.matchFatherName ? 1 : 0,
    match_grandfather_name: filterInput.matchGrandfatherName ? 1 : 0,
    match_birth_year: filterInput.matchBirthYear ? 1 : 0,
    match_family_code: filterInput.matchFamilyCode ? 1 : 0,
    scope_region_geo_id: scopeRegion,
    row_limit: 100,
  });
  const mapped: HwyMemberNakhebinJoinCandidateRow[] = rows.map((row) => ({
    id: readRowString(row, 'id'),
    firstName: readRowString(row, 'firstName') || undefined,
    fatherName: readRowString(row, 'fatherName') || undefined,
    grandfatherName: readRowString(row, 'grandfatherName') || undefined,
    familyName: readRowString(row, 'familyName') || undefined,
    birthYear: readRowString(row, 'birthYear') || undefined,
    familyCode: readRowString(row, 'familyCode') || undefined,
    linkedMemberId: readRowString(row, 'linkedMemberId') || undefined,
  }));
  return {
    rows: mapped,
    appliedFilter: filterInput,
  };
}

export function parseHwyMemberNakhebinJoinCandidateFilter(query: Record<string, unknown>): HwyMemberNakhebinJoinCandidateFilter {
  return {
    matchFirstName: parseFilterFlag(String(query.matchFirstName ?? ''), true),
    matchFatherName: parseFilterFlag(String(query.matchFatherName ?? ''), true),
    matchGrandfatherName: parseFilterFlag(String(query.matchGrandfatherName ?? ''), true),
    matchBirthYear: parseFilterFlag(String(query.matchBirthYear ?? ''), false),
    matchFamilyCode: parseFilterFlag(String(query.matchFamilyCode ?? ''), false),
  };
}
