import type { HwyGeoResponsibilityLevel } from './hwyGeoResponsibilityCatalog';
import { resolveSecurityClearanceStatusTone } from './hwyMemberDossierSecurityClearancePresentation';

export type HwyGeoResponsibilityGenderSlot = 'male' | 'female' | 'unknown';

export type HwyGeoResponsibilityNominationBlockedReason =
  | 'has_responsibility'
  | 'official_at_node'
  | 'no_user'
  | 'clearance_denied'
  | 'member_gender_unknown';

export type HwyGeoResponsibilityNominationCandidateRow = {
  id: string;
  username: string | null;
  displayFullName: string | null;
  genderCode: string | null;
  birthYear: string | null;
  avatarUrl: string | null;
  electoralDivisionPath: string | null;
  selectable: boolean;
  blockedReason: HwyGeoResponsibilityNominationBlockedReason | null;
  activeRoleName: string | null;
  activeGeoBaseInfoId: string | null;
  activeGeoTitle: string | null;
  /** Full electoral title path for the active responsibility geo (when assigned). */
  activeGeoTitlePath: string | null;
  canGetResponsibilityTitle: string | null;
  canGetResponsibilityNote: string | null;
  allowsResponsibilityTitle: string | null;
  hasOtherResponsibility: boolean;
};

export type HwyGeoResponsibilityNominationCandidateListResult = {
  rows: HwyGeoResponsibilityNominationCandidateRow[];
  total: number;
  page: number;
  pageSize: number;
  geoBaseInfoId: string;
  level: HwyGeoResponsibilityLevel;
  geoTitle: string | null;
};

export const resolveHwyGeoResponsibilityGenderSlot = (
  genderCode: string | null | undefined,
): HwyGeoResponsibilityGenderSlot => {
  const code = String(genderCode ?? '').trim();
  if (!code) {
    return 'unknown';
  }
  if (
    code === '100.1.1'
    || code.includes('10011')
    || code.toLowerCase().includes('male')
    || code.includes('ذكر')
  ) {
    return 'male';
  }
  if (
    code === '100.1.2'
    || code.includes('10012')
    || code.toLowerCase().includes('female')
    || code.includes('انث')
    || code.includes('أنث')
  ) {
    return 'female';
  }
  return 'unknown';
};

export const isHwyGeoResponsibilityGenderSlot = (
  value: string,
): value is HwyGeoResponsibilityGenderSlot => (
  value === 'male' || value === 'female' || value === 'unknown'
);

export const resolveHwyGeoResponsibilityNominationSelectable = (input: {
  userId: string | null;
  activeRoleName: string | null;
  activeGeoBaseInfoId: string | null;
  nodeGeoBaseInfoId: string;
  genderCode: string | null;
  canGetResponsibilityTitle: string | null;
}): { selectable: boolean; blockedReason: HwyGeoResponsibilityNominationBlockedReason | null } => {
  if (!input.userId) {
    return { selectable: false, blockedReason: 'no_user' };
  }
  if (
    input.activeRoleName
    && input.activeGeoBaseInfoId
    && input.activeGeoBaseInfoId === input.nodeGeoBaseInfoId
  ) {
    return { selectable: false, blockedReason: 'official_at_node' };
  }
  if (input.activeRoleName) {
    return { selectable: false, blockedReason: 'has_responsibility' };
  }
  const memberSlot = resolveHwyGeoResponsibilityGenderSlot(input.genderCode);
  if (memberSlot !== 'male' && memberSlot !== 'female') {
    return { selectable: false, blockedReason: 'member_gender_unknown' };
  }
  const clearanceTone = resolveSecurityClearanceStatusTone(input.canGetResponsibilityTitle ?? '');
  if (clearanceTone === 'danger') {
    return { selectable: false, blockedReason: 'clearance_denied' };
  }
  return { selectable: true, blockedReason: null };
};
