import { sanitizeDigitsOnlyInput } from './hwySelfRegistrationNumericInput';
import { isValidHwySelfRegistrationPhone } from './hwySelfRegistrationPhone';

/** Legacy `data-validation-min` on BirthYear (HWY_Members_New self-registration). */
export const HWY_SELF_REGISTRATION_BIRTH_YEAR_MIN = 1919;

export const HWY_SELF_REGISTRATION_REFERRER_USERNAME_LEN = 6;
export const HWY_SELF_REGISTRATION_INSTITUTE_CODE_LEN = 3;
/** Unified Iraqi national ID number (digits only). */
export const HWY_SELF_REGISTRATION_NATIONAL_ID_LEN = 12;

export function isValidHwySelfRegistrationNationalId(raw: string): boolean {
  const trimmed = raw.trim();
  if (!trimmed) {
    return true;
  }
  const digits = sanitizeDigitsOnlyInput(trimmed);
  return digits.length === HWY_SELF_REGISTRATION_NATIONAL_ID_LEN;
}

export function isValidHwySelfRegistrationBirthYear(
  raw: string,
  now: Date = new Date(),
): boolean {
  const digits = sanitizeDigitsOnlyInput(raw);
  if (digits.length !== 4) {
    return false;
  }
  const year = Number(digits);
  if (!Number.isFinite(year)) {
    return false;
  }
  const maxYear = now.getFullYear();
  return year >= HWY_SELF_REGISTRATION_BIRTH_YEAR_MIN && year <= maxYear;
}

/** Optional 4-digit year fields (education) — same numeric envelope as birth year when filled. */
export function isValidHwySelfRegistrationOptionalYear(raw: string, now: Date = new Date()): boolean {
  const trimmed = raw.trim();
  if (!trimmed) {
    return true;
  }
  return isValidHwySelfRegistrationBirthYear(trimmed, now);
}

export function isValidHwySelfRegistrationReferrerUsername(raw: string): boolean {
  const trimmed = raw.trim();
  if (!trimmed) {
    return true;
  }
  const digits = sanitizeDigitsOnlyInput(trimmed);
  return digits.length === HWY_SELF_REGISTRATION_REFERRER_USERNAME_LEN;
}

export function isCompleteHwySelfRegistrationReferrerUsername(raw: string): boolean {
  const digits = sanitizeDigitsOnlyInput(raw);
  return digits.length === HWY_SELF_REGISTRATION_REFERRER_USERNAME_LEN;
}

export function isValidHwySelfRegistrationInstituteCode(raw: string): boolean {
  const trimmed = raw.trim();
  if (!trimmed) {
    return true;
  }
  const digits = sanitizeDigitsOnlyInput(trimmed);
  return digits.length === HWY_SELF_REGISTRATION_INSTITUTE_CODE_LEN;
}

export function isValidHwySelfRegistrationEmail(raw: string): boolean {
  const trimmed = raw.trim();
  if (!trimmed) {
    return true;
  }
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
}

export { isValidHwySelfRegistrationPhone };
