import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

const readStringField = (row: Record<string, unknown>, key: string): string =>
  String(row[key] ?? '').trim();

type UrrRow = {
  member_id: string;
  role_id: string;
  is_approved: number | null;
  role_name: string | null;
};

/** Backfill nomination role fields when pipeline views return empty `RoleOfTarshih`. */
export async function attachHwyCandidatePipelineNominationRoles(
  rows: Record<string, unknown>[],
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  const memberIds = [
    ...new Set(
      rows
        .filter((row) => {
          const memberId = readStringField(row, 'id');
          if (!memberId) {
            return false;
          }
          return !readStringField(row, 'roleId') || !readStringField(row, 'roleOfTarshih');
        })
        .map((row) => readStringField(row, 'id')),
    ),
  ];
  if (memberIds.length === 0) {
    return;
  }

  let urrRows: UrrRow[] = [];
  try {
    const sequelize = getControlPlaneSequelize();
    urrRows = await sequelize.query<UrrRow>(
      `SELECT CAST(m.Id AS VARCHAR(32)) AS member_id,
              CAST(ur.RoleId AS VARCHAR(32)) AS role_id,
              CAST(ur.Approved AS INT) AS is_approved,
              R.RoleName AS role_name
       FROM dbo.HWY_Members m WITH (NOLOCK)
       INNER JOIN dbo.AppEnd_Users_R_Roles ur WITH (NOLOCK)
         ON ur.UserId = m.UserId AND ur.RoleId IN (1000004, 1000005)
       LEFT JOIN dbo.AppEnd_Roles R WITH (NOLOCK) ON R.Id = ur.RoleId
       WHERE m.Id IN (:memberIds)`,
      { replacements: { memberIds }, type: QueryTypes.SELECT },
    );
  } catch {
    return;
  }

  const byMember = new Map<string, UrrRow[]>();
  for (const row of urrRows) {
    const memberId = String(row.member_id ?? '').trim();
    if (!memberId) {
      continue;
    }
    const list = byMember.get(memberId) ?? [];
    list.push(row);
    byMember.set(memberId, list);
  }

  for (const row of rows) {
    const memberId = readStringField(row, 'id');
    const assignments = byMember.get(memberId);
    if (!assignments?.length) {
      continue;
    }
    const existingRoleId = readStringField(row, 'roleId');
    const match = existingRoleId
      ? assignments.find((item) => String(item.role_id).trim() === existingRoleId)
      : assignments[0];
    const picked = match ?? assignments[0]!;
    if (!readStringField(row, 'roleId')) {
      row.roleId = String(picked.role_id).trim();
    }
    if (row.isApprovedRow == null && picked.is_approved != null) {
      row.isApprovedRow = Number(picked.is_approved);
    }
    if (!readStringField(row, 'roleOfTarshih')) {
      const roleName = String(picked.role_name ?? '').trim();
      if (roleName) {
        row.roleOfTarshih = roleName;
      }
    }
  }
}
