import type {
  HwyCardFlowAction,
  HwyCardFlowListResult,
  HwyCardFlowPrintedHistoryRow,
  HwyCardFlowRow,
} from '../../../domain/hwy/hwyCardFlow';
import type { HwyCardFlowStep } from '../../../domain/hwy/hwyCardFlowCatalog';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { assertHwyCardFlowStepAccess } from './hwyCardFlowAccess.service';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { hwyLegacyImportParityReady } from './hwyLegacyImportParityState.service';
import {
  queryLegacyCardFlowCount,
  queryLegacyCardFlowList,
  queryLegacyCardFlowPrintedHistoryCount,
  queryLegacyCardFlowPrintedHistoryList,
  toCardFlowWhereInput,
} from './hwyLegacyParityRead.service';
import { resolveHwyLegacyOperatorGeoScope } from './hwyLegacyOperatorGeoScope.service';

const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;

const trim = (v: string | null | undefined): string => String(v ?? '').trim();

/** Legacy HawietySite: `CalculateCanStartPrintingFlow` → `HWY_SP_Members_CalcStats2`. */
const execLegacyCardFlowRecalcCanStart = async (): Promise<void> => {
  const { readLegacyConn } = await import('../../../../scripts/hwy-etl/legacyConn');
  const sql = await import('mssql');
  const pool = await new sql.ConnectionPool(readLegacyConn()).connect();
  try {
    await pool.request().query('EXEC dbo.HWY_SP_Members_CalcStats2 NULL');
  } finally {
    await pool.close();
  }
};

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy card flow requires SQL Server control plane.');
  }
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return { page: safePage, pageSize: safePageSize, offset: (safePage - 1) * safePageSize };
};

const mapRow = (row: Record<string, unknown>): HwyCardFlowRow => ({
  id: trim(row.id as string),
  username: row.username ? trim(row.username as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  grandFatherName: row.grandFatherName ? trim(row.grandFatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
  phone1: row.phone1 ? trim(row.phone1 as string) : null,
  genderId: row.genderId ? trim(row.genderId as string) : null,
  cardFlowLastStatusId: row.cardFlowLastStatusId ? trim(row.cardFlowLastStatusId as string) : null,
  cardFlowStartedOn: row.cardFlowStartedOn ? trim(row.cardFlowStartedOn as string) : null,
  cardFlowVisibility: row.cardFlowVisibility === true || row.cardFlowVisibility === 1,
  latestStepId: row.latestStepId ? trim(row.latestStepId as string) : null,
  lastCanGetIdentityCard: row.lastCanGetIdentityCard != null ? Number(row.lastCanGetIdentityCard) : null,
  nakhebJoinProvinceName: row.nakhebJoinProvinceName ? trim(row.nakhebJoinProvinceName as string) : null,
  nakhebJoinCircleName: row.nakhebJoinCircleName ? trim(row.nakhebJoinCircleName as string) : null,
  nakhebJoinTamvinName: row.nakhebJoinTamvinName ? trim(row.nakhebJoinTamvinName as string) : null,
  lastSecurityProfileCanGetIdentityCard:
    row.lastSecurityProfileCanGetIdentityCard != null
      ? Number(row.lastSecurityProfileCanGetIdentityCard)
      : row.lastCanGetIdentityCard != null
        ? Number(row.lastCanGetIdentityCard)
        : null,
  statFieldsCompleted: row.statFieldsCompleted != null ? Number(row.statFieldsCompleted) : null,
});

const mapHistoryRow = (row: Record<string, unknown>): HwyCardFlowPrintedHistoryRow => ({
  id: trim(row.id as string),
  memberId: row.memberId ? trim(row.memberId as string) : null,
  rfid: row.rfid ? trim(row.rfid as string) : null,
  typeId: row.typeId ? trim(row.typeId as string) : null,
  typeTitle: row.typeTitle ? trim(row.typeTitle as string) : null,
  expirationDate: row.expirationDate ? trim(row.expirationDate as string) : null,
  createdBy: row.createdBy ? trim(row.createdBy as string) : null,
  createdOn: row.createdOn ? trim(row.createdOn as string) : null,
  username: row.username ? trim(row.username as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
});

const buildListProcBase = async (
  input: {
    step: HwyCardFlowStep;
    listType?: string;
    visibility?: string;
    roleId?: string;
    username?: string;
    phone?: string;
    nakhebProvinceId?: string;
    nakhebCircleId?: string;
    nakhebTamvinId?: string;
  },
  roleNames: readonly string[],
  actorUsername?: string | null,
) => {
  const geo = await resolveHwyLegacyOperatorGeoScope(actorUsername, roleNames);
  return {
    step: input.step,
    list_type: trim(input.listType) || null,
    visibility: trim(input.visibility) || null,
    role_id: trim(input.roleId) || null,
    username: trim(input.username) || null,
    phone: trim(input.phone) || null,
    scope_unrestricted: geo.unrestricted ? 1 : 0,
    area_limit_id: geo.unrestricted ? null : geo.areaLimitId,
    geo_limits_csv: geo.unrestricted ? null : geo.geoLimitsCsv,
    gender_limits_csv: null,
    nakheb_province_id: input.nakhebProvinceId ? Number(input.nakhebProvinceId) : null,
    nakheb_circle_id: input.nakhebCircleId ? Number(input.nakhebCircleId) : null,
    nakheb_tamvin_id: input.nakhebTamvinId ? Number(input.nakhebTamvinId) : null,
  };
};

export const listHwyCardFlow = async (
  input: {
    step: HwyCardFlowStep;
    listType?: string;
    visibility?: string;
    roleId?: string;
    username?: string;
    phone?: string;
    nakhebProvinceId?: string;
    nakhebCircleId?: string;
    nakhebTamvinId?: string;
    page?: number;
    pageSize?: number;
  },
  roleNames: readonly string[],
  actorUsername?: string | null,
): Promise<HwyCardFlowListResult> => {
  assertSqlServer();
  await assertHwyCardFlowStepAccess(input.step, roleNames);
  await ensureHwyDbObjects();
  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);

  const edgeReady = await hwyLegacyImportParityReady();

  if (input.step === 'printed-history') {
    const username = trim(input.username) || null;
    if (!edgeReady) {
      const total = await queryLegacyCardFlowPrintedHistoryCount(username);
      const legacyRows = await queryLegacyCardFlowPrintedHistoryList(username, offset, pageSize);
      return {
        total,
        page,
        pageSize,
        rows: legacyRows.map(mapHistoryRow),
        parityDataSource: 'legacy-read' as const,
      };
    }
    const procBase = { username };
    const countRows = await execHwyProcedure<{ total: number | string }>(
      'hwy_card_flow_printed_history_count',
      procBase,
    );
    const total = Number(countRows[0]?.total ?? 0);
    const rows = await execHwyProcedure<Record<string, unknown>>('hwy_card_flow_printed_history_list', {
      ...procBase,
      offset,
      page_size: pageSize,
    });
    return {
      total,
      page,
      pageSize,
      rows: rows.map(mapHistoryRow),
      parityDataSource: 'edge' as const,
    };
  }

  const procBase = await buildListProcBase(input, roleNames, actorUsername);
  if (!edgeReady) {
    const whereInput = toCardFlowWhereInput(procBase, input.step);
    const total = await queryLegacyCardFlowCount(whereInput);
    const legacyRows = await queryLegacyCardFlowList(whereInput, offset, pageSize);
    return {
      total,
      page,
      pageSize,
      rows: legacyRows.map(mapRow),
      parityDataSource: 'legacy-read' as const,
    };
  }
  const countRows = await execHwyProcedure<{ total: number | string }>('hwy_card_flow_count', procBase);
  const total = Number(countRows[0]?.total ?? 0);
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_card_flow_list', {
    ...procBase,
    offset,
    page_size: pageSize,
  });
  return { total, page, pageSize, rows: rows.map(mapRow), parityDataSource: 'edge' as const };
};

export const applyHwyCardFlowStep = async (
  input: {
    step: HwyCardFlowStep;
    action: HwyCardFlowAction;
    memberId?: string;
    reasonId?: string;
    note?: string;
    actorUsername?: string | null;
  },
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  if (input.action === 'recalc-can-start') {
    await assertHwyCardFlowStepAccess('start', roleNames);
  } else {
    await assertHwyCardFlowStepAccess(input.step, roleNames);
  }
  await ensureHwyDbObjects();

  const memberId = trim(input.memberId);
  if (input.action !== 'recalc-can-start' && !memberId) {
    throw new Error('memberId is required.');
  }

  if (input.action === 'recalc-can-start') {
    const edgeReady = await hwyLegacyImportParityReady();
    if (!edgeReady) {
      await execLegacyCardFlowRecalcCanStart();
      return;
    }
  }

  await execHwyProcedure('hwy_card_flow_apply_step', {
    step: input.step,
    action: input.action,
    member_id: memberId ? Number(memberId) : null,
    actor: trim(input.actorUsername) || null,
    reason_id: input.reasonId ? Number(input.reasonId) : null,
    note: trim(input.note) || null,
  });
};

export type HwyCardFlowSecurityProfileInput = {
  memberId: string;
  canGetIdentityCard: number;
  canGetIdentityCardNote?: string;
  canGetMasooliat: number;
  canGetMasooliatNote?: string;
  canBeMemberOfAammeh: number;
  canBeMemberOfAammehNote?: string;
  allowsResponsibility: number;
  allowsResponsibilityNote?: string;
  actorUsername?: string | null;
};

export const applyHwyCardFlowSecurityRecord = async (
  input: HwyCardFlowSecurityProfileInput,
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertHwyCardFlowStepAccess('security', roleNames);
  await ensureHwyDbObjects();

  const memberId = trim(input.memberId);
  if (!memberId) {
    throw new Error('memberId is required.');
  }

  await execHwyProcedure('hwy_candidate_pipeline_security_record', {
    member_id: Number(memberId),
    can_get_identity_card: input.canGetIdentityCard,
    can_get_identity_card_note: trim(input.canGetIdentityCardNote) || null,
    can_get_masooliat: input.canGetMasooliat,
    can_get_masooliat_note: trim(input.canGetMasooliatNote) || null,
    can_be_member_of_aammeh: input.canBeMemberOfAammeh,
    can_be_member_of_aammeh_note: trim(input.canBeMemberOfAammehNote) || null,
    allows_responsibility: input.allowsResponsibility,
    allows_responsibility_note: trim(input.allowsResponsibilityNote) || null,
    actor: trim(input.actorUsername) || null,
  });
};
