/**
 * Member satellite import from legacy SQL (institutes, files, notes, security profiles, …).
 * Out of product scope — not imported here: legacy HWY_Members_Medals, member points/rasids tables.
 */
import sql from 'mssql';
import { resolveHwyInstituteIdFromLegacyOrganization, resolveLegacyMemberUsername } from './legacyMaps';
import type { SampleVocab } from './resolveSampleVocab';

const MAX_FILE_BYTES = Number(process.env.HWY_ETL_MAX_FILE_BYTES ?? 1_500_000) || 1_500_000;
/** 0 = all notes per member (full ETL). Default 3 keeps sample imports small. */
const NOTES_PER_MEMBER = Number(process.env.HWY_ETL_NOTES_PER_MEMBER ?? 3);
const fullEtl = process.env.HWY_ETL_FULL === '1' || process.argv.includes('--full');
const MEMBER_CHUNK = Math.max(
  10,
  Number(process.env.HWY_ETL_MEMBER_CHUNK ?? (fullEtl ? 900 : 80)) || (fullEtl ? 900 : 80),
);
const FILE_MEMBER_CHUNK = Math.max(5, Number(process.env.HWY_ETL_FILE_MEMBER_CHUNK ?? 40) || 40);
/** SQL Server ~2100 params; institute MERGE uses 9 params per row. */
const INSTITUTE_MERGE_CHUNK = Math.max(10, Number(process.env.HWY_ETL_INSTITUTE_MERGE_CHUNK ?? 40) || 40);

export type LoadMemberSatellitesOptions = {
  /** New members on a fresh page — satellites cannot exist yet (skips DELETE). */
  skipClear?: boolean;
  /** Skip legacy member file blobs (registration slots + mehani other attachment). */
  skipMemberFiles?: boolean;
  skipMemberNotes?: boolean;
  skipSecurityProfiles?: boolean;
  /** Skip tracking-code + username-repo backfill (much faster institute-only passes). */
  skipTrackingAndUsernames?: boolean;
};

export type SatelliteCounts = {
  memberInstitutes: number;
  memberFiles: number;
  memberNotes: number;
  securityProfiles: number;
  trackingCodes: number;
  usernameRepo: number;
};

const mapClearance = (
  legacyId: number | null | undefined,
  vocab: SampleVocab,
): string | null => {
  if (legacyId == null) return null;
  return vocab.clearanceAnswerByLegacyId.get(legacyId) ?? null;
};

const chunk = <T>(items: T[], size: number): T[][] => {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
};

const bindMemberIdIn = (
  req: sql.Request,
  memberIds: number[],
  prefix = 'm',
): string => memberIds.map((id, i) => {
  req.input(`${prefix}${i}`, sql.BigInt, id);
  return `@${prefix}${i}`;
}).join(', ');

async function loadLocalInstituteIds(local: sql.ConnectionPool): Promise<Set<number>> {
  const rows = (await local.request().query('SELECT id FROM dbo.hwy_institutes')).recordset as { id: number }[];
  return new Set(rows.map((r) => Number(r.id)));
}

const INSTITUTE_CHARACTER_COLUMN_BY_ID: Record<number, 'AshaaerCharacter' | 'NokhabCharacter' | 'ShababCharacter'> = {
  108: 'AshaaerCharacter',
  112: 'NokhabCharacter',
  109: 'ShababCharacter',
};

const loadLegacyMemberCharacterCodes = async (
  legacy: sql.ConnectionPool,
  memberIds: number[],
): Promise<Map<number, { AshaaerCharacter: number | null; NokhabCharacter: number | null; ShababCharacter: number | null }>> => {
  const map = new Map<number, { AshaaerCharacter: number | null; NokhabCharacter: number | null; ShababCharacter: number | null }>();
  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const rows = (await req.query(`
      SELECT Id, AshaaerCharacter, NokhabCharacter, ShababCharacter
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id IN (${inList})
    `)).recordset as Array<{
      Id: number;
      AshaaerCharacter: number | null;
      NokhabCharacter: number | null;
      ShababCharacter: number | null;
    }>;
    for (const row of rows) {
      map.set(Number(row.Id), {
        AshaaerCharacter: row.AshaaerCharacter,
        NokhabCharacter: row.NokhabCharacter,
        ShababCharacter: row.ShababCharacter,
      });
    }
  }
  return map;
};

export async function importMemberInstitutes(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  instituteIds: Set<number>,
  vocab: SampleVocab,
): Promise<number> {
  let count = 0;
  const characterByMember = await loadLegacyMemberCharacterCodes(legacy, memberIds);
  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const rows = (await req.query(`
      SELECT MemberId, OrganizationId, ApprovedByMember, RequestedByOrganization, ByAdmin,
             CreatedOn, UpdatedOn
      FROM dbo.HWY_Members_Organizations WITH (NOLOCK)
      WHERE MemberId IN (${inList})
    `)).recordset as Array<{
      MemberId: number;
      OrganizationId: number;
      ApprovedByMember: boolean | number | null;
      RequestedByOrganization: boolean | number | null;
      ByAdmin: boolean | number | null;
      CreatedOn: Date | null;
      UpdatedOn: Date | null;
    }>;

    type InstituteMergeRow = {
      memberId: number;
      instituteId: number;
      statusCode: string;
      joinPathCode: string;
      memberAccepted: boolean;
      characterCode: string | null;
      activatedAt: Date | null;
      createdAt: Date;
      updatedAt: Date;
    };

    const pending: InstituteMergeRow[] = [];
    for (const r of rows) {
      const instituteId = resolveHwyInstituteIdFromLegacyOrganization(Number(r.OrganizationId));
      if (instituteId == null || !instituteIds.has(instituteId)) continue;

      const approved = r.ApprovedByMember === true || r.ApprovedByMember === 1;
      const statusCode = approved ? vocab.instituteStatus.active : vocab.instituteStatus.pendingInvite;
      const byAdmin = r.ByAdmin === true || r.ByAdmin === 1;
      const requested = r.RequestedByOrganization === true || r.RequestedByOrganization === 1;
      const joinPathCode = byAdmin
        ? vocab.joinPath.admin
        : requested
          ? vocab.joinPath.invite
          : vocab.joinPath.selfRegistration;

      const createdAt = r.CreatedOn ? new Date(r.CreatedOn) : new Date();
      const updatedAt = r.UpdatedOn ? new Date(r.UpdatedOn) : createdAt;

      const characterColumn = INSTITUTE_CHARACTER_COLUMN_BY_ID[instituteId];
      let characterCode: string | null = null;
      if (characterColumn) {
        const memberCharacter = characterByMember.get(Number(r.MemberId));
        const legacyCharacterId = memberCharacter?.[characterColumn];
        if (legacyCharacterId != null && Number(legacyCharacterId) > 0) {
          characterCode = String(legacyCharacterId);
        }
      }

      pending.push({
        memberId: Number(r.MemberId),
        instituteId,
        statusCode,
        joinPathCode,
        memberAccepted: approved,
        characterCode,
        activatedAt: approved ? updatedAt : null,
        createdAt,
        updatedAt,
      });
    }

    for (let start = 0; start < pending.length; start += INSTITUTE_MERGE_CHUNK) {
      const slice = pending.slice(start, start + INSTITUTE_MERGE_CHUNK);
      const req = local.request();
      const valueRows: string[] = [];
      slice.forEach((entry, index) => {
        req.input(`mid_${index}`, sql.BigInt, entry.memberId);
        req.input(`iid_${index}`, sql.Int, entry.instituteId);
        req.input(`st_${index}`, sql.NVarChar(1000), entry.statusCode);
        req.input(`jp_${index}`, sql.NVarChar(1000), entry.joinPathCode);
        req.input(`acc_${index}`, sql.Bit, entry.memberAccepted ? 1 : 0);
        req.input(`ch_${index}`, sql.NVarChar(128), entry.characterCode);
        req.input(`act_${index}`, sql.DateTime2, entry.activatedAt);
        req.input(`cr_${index}`, sql.DateTime2, entry.createdAt);
        req.input(`up_${index}`, sql.DateTime2, entry.updatedAt);
        valueRows.push(
          `(@mid_${index}, @iid_${index}, @st_${index}, @jp_${index}, @acc_${index}, @ch_${index}, @act_${index}, @cr_${index}, @up_${index})`,
        );
      });
      await req.query(`
        MERGE dbo.hwy_member_institutes AS t
        USING (VALUES ${valueRows.join(',\n')}) AS s(
          member_id, institute_id, status_code, join_path_code, member_accepted,
          character_code, activated_at, created_at, updated_at
        )
        ON t.member_id = s.member_id AND t.institute_id = s.institute_id
        WHEN MATCHED THEN UPDATE SET
          status_code = s.status_code,
          join_path_code = s.join_path_code,
          member_accepted = s.member_accepted,
          character_code = COALESCE(s.character_code, t.character_code),
          activated_at = COALESCE(s.activated_at, t.activated_at),
          updated_at = s.updated_at
        WHEN NOT MATCHED THEN INSERT (
          member_id, institute_id, status_code, join_path_code, member_accepted,
          character_code, activated_at, created_at, updated_at
        ) VALUES (
          s.member_id, s.institute_id, s.status_code, s.join_path_code, s.member_accepted,
          s.character_code, s.activated_at, s.created_at, s.updated_at
        );
      `);
      count += slice.length;
    }
  }
  return count;
}

type FileSpec = {
  kindCode: string;
  body: Buffer | null;
  bodyXs: Buffer | null;
  fileName: string | null;
  mime: string | null;
  size: number | null;
  approved: boolean | number | null;
};

type LegacyMemberFileColumnGroup = {
  kindCode: string;
  base: string;
  approvedKey?: string;
};

/** Legacy `HWY_Members` blob columns → AppEndO Member File Kind codes. */
const LEGACY_MEMBER_FILE_COLUMN_GROUPS: readonly LegacyMemberFileColumnGroup[] = [
  { kindCode: 'personalPhoto', base: 'Picture', approvedKey: 'Picture_Approved' },
  { kindCode: 'nationalCardFront', base: 'NationalCard_Front', approvedKey: 'NationalCard_Front_Approved' },
  { kindCode: 'nationalCardBack', base: 'NationalCard_Behind', approvedKey: 'NationalCard_Behind_Approved' },
  { kindCode: 'voterCardFront', base: 'NakhebCard_Front', approvedKey: 'NakhebCard_Front_Approved' },
  { kindCode: 'residenceCardFront', base: 'MaskanCard_Front', approvedKey: 'MaskanCard_Front_Approved' },
  { kindCode: 'oathDocument', base: 'Oath', approvedKey: 'Oath_Approved' },
  { kindCode: 'secondNationalityDocument', base: 'SecondNationalityPicture' },
  { kindCode: 'otherAttachment', base: 'Mehani' },
];

const legacyMemberFileSelectColumns = (): string => {
  const cols = new Set<string>(['Id']);
  for (const group of LEGACY_MEMBER_FILE_COLUMN_GROUPS) {
    cols.add(`${group.base}_FileBody`);
    cols.add(`${group.base}_FileBody_xs`);
    cols.add(`${group.base}_FileName`);
    cols.add(`${group.base}_FileMime`);
    cols.add(`${group.base}_FileSize`);
    if (group.approvedKey) {
      cols.add(group.approvedKey);
    }
  }
  return [...cols].join(',\n        ');
};

const readLegacyMemberFileSpecs = (
  row: Record<string, unknown>,
  vocab: SampleVocab,
): FileSpec[] => {
  const specs: FileSpec[] = [];
  for (const group of LEGACY_MEMBER_FILE_COLUMN_GROUPS) {
    const kindCode = vocab.fileKind[group.kindCode as keyof SampleVocab['fileKind']];
    if (!kindCode) continue;
    specs.push({
      kindCode,
      body: row[`${group.base}_FileBody`] as Buffer | null,
      bodyXs: row[`${group.base}_FileBody_xs`] as Buffer | null,
      fileName: row[`${group.base}_FileName`] as string | null,
      mime: row[`${group.base}_FileMime`] as string | null,
      size: row[`${group.base}_FileSize`] as number | null,
      approved: group.approvedKey ? row[group.approvedKey] as boolean | number | null : null,
    });
  }
  return specs;
};

async function upsertMemberFileRow(
  local: sql.ConnectionPool,
  memberId: number,
  spec: FileSpec,
): Promise<boolean> {
  const legacyHadBlob = Boolean(spec.body && spec.body.length > 0);
  const legacyHadThumb = Boolean(spec.bodyXs && spec.bodyXs.length > 0);
  let content = spec.body;
  if (content && content.length > MAX_FILE_BYTES) {
    content = null;
  }
  const thumb = spec.bodyXs && spec.bodyXs.length <= MAX_FILE_BYTES ? spec.bodyXs : null;
  const pendingUnapproved = spec.approved !== true && spec.approved !== 1;
  const legacySize = Math.max(
    Number(spec.size ?? 0) || 0,
    legacyHadBlob ? spec.body!.length : 0,
    legacyHadThumb ? spec.bodyXs!.length : 0,
  );
  /** Legacy Imagefix Todo keys off column blobs; keep a queue row even when blobs are skipped for size. */
  const queueMarker = pendingUnapproved && (legacyHadBlob || legacyHadThumb || legacySize > 0);
  if (!content && !thumb && !queueMarker) return false;

  await local.request()
    .input('member_id', sql.BigInt, memberId)
    .input('file_kind_code', sql.NVarChar(1000), spec.kindCode)
    .query(`
      DELETE FROM dbo.hwy_member_files
      WHERE member_id = @member_id AND file_kind_code = @file_kind_code
    `);

  await local.request()
    .input('member_id', sql.BigInt, memberId)
    .input('file_kind_code', sql.NVarChar(1000), spec.kindCode)
    .input('original_file_name', sql.NVarChar(sql.MAX), spec.fileName)
    .input('mime', sql.NVarChar(4000), spec.mime != null ? String(spec.mime).slice(0, 4000) : null)
    .input('size_bytes', sql.BigInt, spec.size ?? legacySize ?? (content?.length ?? thumb?.length ?? null))
    .input('content', sql.VarBinary(sql.MAX), content)
    .input('thumbnail_content', sql.VarBinary(sql.MAX), thumb)
    .input('is_approved', sql.Bit, spec.approved === true || spec.approved === 1 ? 1 : spec.approved === false || spec.approved === 0 ? 0 : null)
    .query(`
      INSERT INTO dbo.hwy_member_files (
        member_id, file_kind_code, original_file_name, mime, size_bytes,
        content, thumbnail_content, is_approved, created_at, updated_at
      ) VALUES (
        @member_id, @file_kind_code, @original_file_name, @mime, @size_bytes,
        @content, @thumbnail_content, @is_approved, SYSUTCDATETIME(), SYSUTCDATETIME()
      )
    `);
  return true;
}

async function importMemberFiles(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  vocab: SampleVocab,
  skipMemberFiles: boolean,
): Promise<number> {
  if (skipMemberFiles) return 0;
  let count = 0;
  for (const ids of chunk(memberIds, FILE_MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const rows = (await req.query(`
      SELECT ${legacyMemberFileSelectColumns()}
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id IN (${inList})
    `)).recordset as Array<Record<string, unknown>>;

    for (const r of rows) {
      const memberId = Number(r.Id);
      const specs = readLegacyMemberFileSpecs(r, vocab);

      for (const spec of specs) {
        if (await upsertMemberFileRow(local, memberId, spec)) {
          count += 1;
        }
      }
    }
  }
  return count;
}

/** Re-import registration file blobs for members already in dbo.hwy_members (idempotent per kind). */
export async function reloadMemberFilesFromLegacy(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  vocab: SampleVocab,
): Promise<number> {
  return importMemberFiles(legacy, local, memberIds, vocab, false);
}

const noteSubjectFallback = (legacySubjectId: number, vocab: SampleVocab): string => {
  if (legacySubjectId === 211501) return vocab.noteSubject.membership;
  if (legacySubjectId === 211502) return vocab.noteSubject.callCenter;
  return vocab.noteSubject.general;
};

async function importMemberNotes(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  vocab: SampleVocab,
): Promise<number> {
  let count = 0;
  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const notesSql = NOTES_PER_MEMBER > 0
      ? `
      SELECT MemberId, Note, NoteSubject, CreatedOn
      FROM (
        SELECT MemberId, Note, NoteSubject, CreatedOn,
          ROW_NUMBER() OVER (PARTITION BY MemberId ORDER BY CreatedOn DESC) AS rn
        FROM dbo.HWY_Members_Notes WITH (NOLOCK)
        WHERE MemberId IN (${inList}) AND Note IS NOT NULL AND LTRIM(RTRIM(Note)) <> ''
      ) x
      WHERE rn <= ${NOTES_PER_MEMBER}
    `
      : `
      SELECT MemberId, Note, NoteSubject, CreatedOn
      FROM dbo.HWY_Members_Notes WITH (NOLOCK)
      WHERE MemberId IN (${inList}) AND Note IS NOT NULL AND LTRIM(RTRIM(Note)) <> ''
    `;
    const rows = (await req.query(notesSql)).recordset as Array<{
      MemberId: number;
      Note: string;
      NoteSubject: number;
      CreatedOn: Date;
    }>;

    for (const noteSlice of chunk(rows, 250)) {
      if (!noteSlice.length) continue;
      const noteReq = local.request();
      const noteValues: string[] = [];
      noteSlice.forEach((r, rowIndex) => {
        const subjectCode = noteSubjectFallback(Number(r.NoteSubject), vocab);
        noteReq.input(`nm${rowIndex}`, sql.BigInt, r.MemberId);
        noteReq.input(`nb${rowIndex}`, sql.NVarChar(sql.MAX), r.Note);
        noteReq.input(`ns${rowIndex}`, sql.NVarChar(1000), subjectCode);
        noteReq.input(`nc${rowIndex}`, sql.DateTime2, r.CreatedOn ? new Date(r.CreatedOn) : new Date());
        noteValues.push(`(@nm${rowIndex}, @nb${rowIndex}, @ns${rowIndex}, @nc${rowIndex})`);
      });
      await noteReq.query(`
        INSERT INTO dbo.hwy_member_notes (member_id, body, subject_code, created_at)
        VALUES ${noteValues.join(',\n')}
      `);
      count += noteSlice.length;
    }
  }
  return count;
}

async function importSecurityProfiles(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  vocab: SampleVocab,
): Promise<number> {
  let count = 0;
  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const rows = (await req.query(`
      SELECT MemberId, CanGetIdentityCard, CanGetIdentityCard_Note,
             CanGetMasooliat, CanGetMasooliat_Note,
             CanBeMemberOfAammeh, CanBeMemberOfAammeh_Note,
             AllowsResponsibility, AllowsResponsibility_Note, CreatedOn
      FROM (
        SELECT *, ROW_NUMBER() OVER (PARTITION BY MemberId ORDER BY CreatedOn DESC) AS rn
        FROM dbo.HWY_Members_SecurityProfile WITH (NOLOCK)
        WHERE MemberId IN (${inList})
      ) x WHERE rn = 1
    `)).recordset as Array<{
      MemberId: number;
      CanGetIdentityCard: number;
      CanGetIdentityCard_Note: string | null;
      CanGetMasooliat: number;
      CanGetMasooliat_Note: string | null;
      CanBeMemberOfAammeh: number;
      CanBeMemberOfAammeh_Note: string | null;
      AllowsResponsibility: number;
      AllowsResponsibility_Note: string | null;
      CreatedOn: Date;
    }>;

    for (const r of rows) {
      const cardCode = mapClearance(r.CanGetIdentityCard, vocab);
      if (r.CanGetIdentityCard != null && !cardCode) {
        console.warn(
          `[hwy:etl] unmapped CanGetIdentityCard legacy id ${r.CanGetIdentityCard} for member ${r.MemberId}`,
        );
      }
      const respCode = mapClearance(r.CanGetMasooliat, vocab);
      const bodyCode = mapClearance(r.CanBeMemberOfAammeh, vocab);
      const allowCode = mapClearance(r.AllowsResponsibility, vocab);
      if (!cardCode && !respCode && !bodyCode && !allowCode) continue;

      await local.request()
        .input('member_id', sql.BigInt, r.MemberId)
        .input('can_get_identity_card_code', sql.NVarChar(1000), cardCode)
        .input('can_get_identity_card_note', sql.NVarChar(sql.MAX), r.CanGetIdentityCard_Note)
        .input('can_get_responsibility_code', sql.NVarChar(1000), respCode)
        .input('can_get_responsibility_note', sql.NVarChar(sql.MAX), r.CanGetMasooliat_Note)
        .input('can_join_general_body_code', sql.NVarChar(1000), bodyCode)
        .input('can_join_general_body_note', sql.NVarChar(sql.MAX), r.CanBeMemberOfAammeh_Note)
        .input('allows_responsibility_code', sql.NVarChar(1000), allowCode)
        .input('allows_responsibility_note', sql.NVarChar(sql.MAX), r.AllowsResponsibility_Note)
        .input('created_at', sql.DateTime2, r.CreatedOn ? new Date(r.CreatedOn) : new Date())
        .query(`
          INSERT INTO dbo.hwy_member_security_profile (
            member_id,
            can_get_identity_card_code, can_get_identity_card_note,
            can_get_responsibility_code, can_get_responsibility_note,
            can_join_general_body_code, can_join_general_body_note,
            allows_responsibility_code, allows_responsibility_note,
            created_at
          ) VALUES (
            @member_id,
            @can_get_identity_card_code, @can_get_identity_card_note,
            @can_get_responsibility_code, @can_get_responsibility_note,
            @can_join_general_body_code, @can_join_general_body_note,
            @allows_responsibility_code, @allows_responsibility_note,
            @created_at
          )
        `);
      count += 1;
    }
  }
  return count;
}

async function importTrackingAndUsernames(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
): Promise<{ trackingCodes: number; usernameRepo: number }> {
  let trackingCodes = 0;
  let usernameRepo = 0;

  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = legacy.request();
    const inList = bindMemberIdIn(req, ids);
    const rows = (await req.query(`
      SELECT Id, UserName, TrackingCode
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id IN (${inList})
    `)).recordset as Array<{ Id: number; UserName: string | null; TrackingCode: string | null }>;

    for (const r of rows) {
      const username = resolveLegacyMemberUsername({
        memberId: Number(r.Id),
        userName: r.UserName,
        trackingCode: r.TrackingCode,
      });
      if (username) {
        await local.request()
          .input('username', sql.NVarChar(4000), username)
          .input('member_id', sql.BigInt, r.Id)
          .query(`
            MERGE dbo.hwy_username_repo AS t
            USING (SELECT @username AS username) AS s ON t.username = s.username
            WHEN MATCHED THEN UPDATE SET member_id = @member_id, released_at = NULL
            WHEN NOT MATCHED THEN INSERT (username, member_id, reserved_at) VALUES (@username, @member_id, SYSUTCDATETIME());
          `);
        await local.request()
          .input('username', sql.NVarChar(4000), username)
          .input('id', sql.BigInt, r.Id)
          .query('UPDATE dbo.hwy_members SET username = @username, updated_at = SYSUTCDATETIME() WHERE id = @id');
        usernameRepo += 1;
      }

    }
  }

  return { trackingCodes, usernameRepo };
}

async function clearSatellitesForMembers(local: sql.ConnectionPool, memberIds: number[]): Promise<void> {
  for (const ids of chunk(memberIds, MEMBER_CHUNK)) {
    const req = local.request();
    const inList = bindMemberIdIn(req, ids, 'c');
    await req.query(`
      DELETE FROM dbo.hwy_member_security_profile WHERE member_id IN (${inList});
      DELETE FROM dbo.hwy_member_notes WHERE member_id IN (${inList});
      DELETE FROM dbo.hwy_member_files WHERE member_id IN (${inList});
      DELETE FROM dbo.hwy_member_institutes WHERE member_id IN (${inList});
    `);
  }
}

export async function loadMemberSatellites(
  legacy: sql.ConnectionPool,
  local: sql.ConnectionPool,
  memberIds: number[],
  vocab: SampleVocab,
  options?: LoadMemberSatellitesOptions,
): Promise<SatelliteCounts> {
  const imported = [...new Set(memberIds)].filter((id) => id > 0);
  if (!imported.length) {
    return {
      memberInstitutes: 0,
      memberFiles: 0,
      memberNotes: 0,
      securityProfiles: 0,
      trackingCodes: 0,
      usernameRepo: 0,
    };
  }

  if (!options?.skipClear) {
    await clearSatellitesForMembers(local, imported);
  }
  const instituteIds = await loadLocalInstituteIds(local);
  const memberInstitutes = await importMemberInstitutes(legacy, local, imported, instituteIds, vocab);
  const memberFiles = await importMemberFiles(
    legacy,
    local,
    imported,
    vocab,
    Boolean(options?.skipMemberFiles),
  );
  const memberNotes = options?.skipMemberNotes
    ? 0
    : await importMemberNotes(legacy, local, imported, vocab);
  const securityProfiles = options?.skipSecurityProfiles
    ? 0
    : await importSecurityProfiles(legacy, local, imported, vocab);
  const tracking = options?.skipTrackingAndUsernames
    ? { trackingCodes: 0, usernameRepo: 0 }
    : await importTrackingAndUsernames(legacy, local, imported);

  return {
    memberInstitutes,
    memberFiles,
    memberNotes,
    securityProfiles,
    trackingCodes: tracking.trackingCodes,
    usernameRepo: tracking.usernameRepo,
  };
}
