import type { HwyMemberDirectoryPatchInput } from './hwyMemberDirectoryPatch';
import { pickHwyMemberDirectoryPatchInput } from './hwyMemberDirectoryPatch';
import type { HwyMemberDirectoryIdentityFieldPolicy } from './hwyMemberIdentityFieldMask';
import {
  isHwyMemberDossierPatchFieldLocked,
  stripIdentityLockedPatchFields,
} from './hwyMemberIdentityFieldMask';
import type { HwyMemberDossierSection } from './hwyMemberDossierRoute';
import {
  HWY_MEMBER_DOSSIER_PROFILE_NAV_ITEMS,
  type HwyMemberDossierProfileNavId,
  type HwyMemberDossierProfileNavItem,
} from './hwyMemberDossierProfileNav';
import {
  isHwyMemberOtherAttachmentKindSlug,
  type HwyMemberFileEditGroup,
  resolveHwyMemberFileEditGroup,
} from './hwyMemberFileKindCatalog';

/** Nested edit URLs may open only these satellites; institute membership is workflow-managed. */
export const HWY_MEMBER_DOSSIER_EDIT_MODE_SECTIONS = ['files', 'kasb'] as const satisfies readonly HwyMemberDossierSection[];

/** Profile rail satellites available in edit mode (basic data is the default route). */
export const HWY_MEMBER_DOSSIER_EDIT_PROFILE_NAV_ITEM_IDS = ['files', 'kasb'] as const satisfies readonly HwyMemberDossierProfileNavId[];

export function listHwyMemberDossierEditProfileNavItems(): readonly HwyMemberDossierProfileNavItem[] {
  return HWY_MEMBER_DOSSIER_EDIT_PROFILE_NAV_ITEM_IDS.map((id) => {
    const item = HWY_MEMBER_DOSSIER_PROFILE_NAV_ITEMS.find((entry) => entry.id === id);
    if (!item) {
      throw new Error(`Missing dossier edit nav item: ${id}`);
    }
    return item;
  });
}

export function isHwyMemberDossierSectionEditableInEditMode(
  section: HwyMemberDossierSection | null | undefined,
): boolean {
  if (!section) {
    return true;
  }
  return (HWY_MEMBER_DOSSIER_EDIT_MODE_SECTIONS as readonly string[]).includes(section);
}

/**
 * Member dossier edit rules (V2). Public `note` on `hwy_members` is read-only here;
 * staff notes use `hwy_member_notes`. Registration vs other file kinds split for delegated access.
 */
export const HWY_MEMBER_DOSSIER_NEVER_EDITABLE_MEMBER_FIELDS = ['note', 'phone1', 'phone2'] as const;

export type HwyMemberDossierNeverEditableMemberField =
  (typeof HWY_MEMBER_DOSSIER_NEVER_EDITABLE_MEMBER_FIELDS)[number];

export type HwyMemberDossierFileEditCapabilities = {
  canEditRegistrationDocuments: boolean;
  canEditOtherAttachments: boolean;
};

export const HWY_MEMBER_DOSSIER_FILE_EDIT_CAPABILITIES_ADMIN: HwyMemberDossierFileEditCapabilities = {
  canEditRegistrationDocuments: true,
  canEditOtherAttachments: true,
};

export function isHwyMemberDossierMemberFieldEditable(
  field: keyof HwyMemberDirectoryPatchInput,
): boolean {
  return !(HWY_MEMBER_DOSSIER_NEVER_EDITABLE_MEMBER_FIELDS as readonly string[]).includes(field);
}

export function stripHwyMemberDossierNonEditablePatchFields(
  input: HwyMemberDirectoryPatchInput,
): HwyMemberDirectoryPatchInput {
  const picked = pickHwyMemberDirectoryPatchInput(input);
  for (const field of HWY_MEMBER_DOSSIER_NEVER_EDITABLE_MEMBER_FIELDS) {
    delete picked[field];
  }
  return picked;
}

export function stripHwyMemberDossierIdentityLockedPatchFields(
  input: HwyMemberDirectoryPatchInput,
  policy: HwyMemberDirectoryIdentityFieldPolicy | null | undefined,
): HwyMemberDirectoryPatchInput {
  const picked = stripHwyMemberDossierNonEditablePatchFields(input);
  if (!policy?.lockedPatchFields.length) {
    return picked;
  }
  return stripIdentityLockedPatchFields(picked, policy.lockedPatchFields);
}

export function isHwyMemberDossierPatchFieldEditableForPolicy(
  field: keyof HwyMemberDirectoryPatchInput,
  policy: HwyMemberDirectoryIdentityFieldPolicy | null | undefined,
): boolean {
  if (!isHwyMemberDossierMemberFieldEditable(field)) {
    return false;
  }
  return !isHwyMemberDossierPatchFieldLocked(field, policy);
}

export function canEditHwyMemberFileGroup(
  group: HwyMemberFileEditGroup,
  capabilities: HwyMemberDossierFileEditCapabilities = HWY_MEMBER_DOSSIER_FILE_EDIT_CAPABILITIES_ADMIN,
): boolean {
  if (group === 'registration') {
    return capabilities.canEditRegistrationDocuments;
  }
  return capabilities.canEditOtherAttachments;
}

export function canEditHwyMemberFileKindSlug(
  slug: string | null | undefined,
  capabilities: HwyMemberDossierFileEditCapabilities = HWY_MEMBER_DOSSIER_FILE_EDIT_CAPABILITIES_ADMIN,
): boolean {
  const group = resolveHwyMemberFileEditGroup(slug);
  if (!group) {
    return false;
  }
  return canEditHwyMemberFileGroup(group, capabilities);
}

export function canDeleteHwyMemberFileRow(input: {
  fileKindSlug: string | null | undefined;
  capabilities?: HwyMemberDossierFileEditCapabilities;
}): boolean {
  const slug = input.fileKindSlug;
  if (isHwyMemberOtherAttachmentKindSlug(slug)) {
    return canEditHwyMemberFileGroup('other', input.capabilities);
  }
  return false;
}
