import fs from 'node:fs';
import path from 'node:path';

export type HwyEtlSyncStateSummary = {
  lastSuccessfulSyncAt: string | null;
  lastLegacyMemberUpdatedOn: string | null;
  lastChangeHistoryId: number;
};

const emptySummary = (): HwyEtlSyncStateSummary => ({
  lastSuccessfulSyncAt: null,
  lastLegacyMemberUpdatedOn: null,
  lastChangeHistoryId: 0,
});

export const resolveHwyEtlSyncStateFilePath = (repoRoot: string): string => (
  path.join(repoRoot, 'packages-storage', 'hwy-etl-sync-state.json')
);

export const readHwyEtlSyncStateSummary = (repoRoot: string): HwyEtlSyncStateSummary => {
  const filePath = resolveHwyEtlSyncStateFilePath(repoRoot);
  if (!fs.existsSync(filePath)) return emptySummary();
  try {
    const raw = JSON.parse(fs.readFileSync(filePath, 'utf8')) as Partial<HwyEtlSyncStateSummary>;
    return {
      lastSuccessfulSyncAt: raw.lastSuccessfulSyncAt ?? null,
      lastLegacyMemberUpdatedOn: raw.lastLegacyMemberUpdatedOn ?? null,
      lastChangeHistoryId: Math.max(0, Number(raw.lastChangeHistoryId ?? 0) || 0),
    };
  } catch {
    return emptySummary();
  }
};
