const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;

type HwyDetailAuditActorVmPrefix = 'creator' | 'updater';

const mapAuditActorMemberFaceFromDetailRow = (
  row: Record<string, unknown>,
  prefix: HwyDetailAuditActorVmPrefix,
): HwyMemberListFace | null => {
  const face = mapHwyMemberListFaceFromVmFields({
    id: row[`${prefix}_member_id`],
    displayFullName: row[`${prefix}_display_name`],
    username: row[`${prefix}_username`],
    avatarUrl: row[`${prefix}_avatar_url`],
    userId: row[`${prefix}_user_id`],
    genderCode: row[`${prefix}_gender_code`],
    phone: row[`${prefix}_phone1`],
    hasProfileImage: row[`${prefix}_has_profile_image`],
  });
  return face && hwyMemberListFaceHasLabel(face) ? face : null;
};

const resolveDetailAuditActor = async (
  row: Record<string, unknown>,
  prefix: HwyDetailAuditActorVmPrefix,
  legacyActor: string | null,
): Promise<HwyMemberListFace | null> =>
  mapAuditActorMemberFaceFromDetailRow(row, prefix)
  ?? (await resolveHwyMemberListFaceForLegacyActor(legacyActor));

const mergeAuditActorMemberMedia = (
  target: HwyMemberListFace,
  loaded: HwyMemberListFace,
): void => {
  target.avatarUrl = loaded.avatarUrl?.trim() || target.avatarUrl?.trim() || null;
  target.genderCode = loaded.genderCode?.trim() || target.genderCode?.trim() || null;
  if (!target.displayFullName?.trim()) {
    target.displayFullName = loaded.displayFullName;
  }
};

const scoreAuditListFace = (face: HwyMemberListFace | null | undefined): number => {
  if (!face?.id || !hwyMemberListFaceHasLabel(face)) {
    return 0;
  }
  let score = 1;
  if (face.avatarUrl?.trim()) {
    score += 20;
  }
  if (/^\d+$/.test(face.id.trim())) {
    score += 8;
  }
  if (/^legacy-membership-/.test(face.id.trim())) {
    score += 4;
  }
  if (/^user-\d+$/.test(face.id.trim())) {
    score += 2;
  }
  return score;
};

const pickRicherAuditListFace = (
  current: HwyMemberListFace | null,
  resolved: HwyMemberListFace | null,
): HwyMemberListFace | null => {
  const currentScore = scoreAuditListFace(current);
  const resolvedScore = scoreAuditListFace(resolved);
  if (resolvedScore > currentScore) {
    return resolved;
  }
  if (currentScore > 0) {
    return current;
  }
  return resolved;
};

const enrichActivityAuditFaceAvatars = async (
  faces: HwyMemberListFace[],
): Promise<void> => {
  if (!faces.length) {
    return;
  }

  const memberIds = new Set<number>();
  const faceMemberPairs: Array<{ face: HwyMemberListFace; memberId: string }> = [];
  const platformUserIds = new Set<number>();

  for (const face of faces) {
    const id = trim(face.id);
    if (/^\d+$/.test(id)) {
      memberIds.add(Number(id));
      faceMemberPairs.push({ face, memberId: id });
      continue;
    }
    const legacyMembership = /^legacy-membership-(\d+)$/.exec(id);
    if (legacyMembership) {
      const memberId = legacyMembership[1];
      memberIds.add(Number(memberId));
      faceMemberPairs.push({ face, memberId });
      continue;
    }
    const userMatch = /^user-(\d+)$/.exec(id);
    if (userMatch) {
      platformUserIds.add(Number(userMatch[1]));
    }
  }

  if (platformUserIds.size) {
    await Promise.all([...platformUserIds].map(async (userId) => {
      const memberId = await loadMemberIdByUserId(userId);
      if (memberId == null) {
        return;
      }
      memberIds.add(memberId);
      for (const face of faces) {
        if (face.id.trim() === `user-${userId}`) {
          faceMemberPairs.push({ face, memberId: String(memberId) });
        }
      }
    }));
  }

  if (memberIds.size) {
    const loadedByMemberId = await loadMemberFacesByMemberIds([...memberIds]);
    for (const { face, memberId } of faceMemberPairs) {
      const loaded = loadedByMemberId.get(Number(memberId));
      if (loaded) {
        mergeAuditActorMemberMedia(face, loaded);
      }
    }
    const registrationPhotoTargets = faceMemberPairs.map(({ face, memberId }) => ({
      memberId,
      avatarUrl: face.avatarUrl,
    }));
    await enrichMemberDirectoryFaceAvatarsByMemberId(registrationPhotoTargets);
    for (let index = 0; index < faceMemberPairs.length; index += 1) {
      const url = registrationPhotoTargets[index]?.avatarUrl;
      if (url?.trim()) {
        faceMemberPairs[index].face.avatarUrl = url.trim();
      }
    }
  }

  for (const face of faces) {
    if (face.avatarUrl?.trim()) {
      continue;
    }
    const userMatch = /^user-(\d+)$/.exec(face.id.trim());
    if (!userMatch) {
      continue;
    }
    face.avatarUrl = resolveHwyGeoResponsibilityAvatarUrl({
      userId: Number(userMatch[1]),
      hasProfileImage: true,
    });
  }
};

const enrichActivityListAuditActors = async (rows: HwyActivityAdminRow[]): Promise<void> => {
  if (!rows.length) {
    return;
  }
  const legacyCache = new Map<string, HwyMemberListFace | null>();
  const resolveLegacyCached = async (
    legacyRaw: string | null | undefined,
  ): Promise<HwyMemberListFace | null> => {
    const legacy = trim(legacyRaw ?? '');
    if (!legacy) {
      return null;
    }
    if (legacyCache.has(legacy)) {
      return legacyCache.get(legacy) ?? null;
    }
    const face = await resolveHwyMemberListFaceForLegacyActor(legacy);
    legacyCache.set(legacy, face);
    return face;
  };

  await Promise.all(rows.map(async (row) => {
    const resolvedCreate = await resolveLegacyCached(row.legacyCreatedBy);
    const resolvedUpdate = await resolveLegacyCached(row.legacyUpdatedBy);
    row.createdBy = pickRicherAuditListFace(row.createdBy, resolvedCreate);
    row.updatedBy = pickRicherAuditListFace(row.updatedBy, resolvedUpdate);
  }));

  const platformUserIds = new Set<number>();
  for (const row of rows) {
    for (const face of [row.createdBy, row.updatedBy]) {
      const match = face?.id ? /^user-(\d+)$/.exec(face.id.trim()) : null;
      if (match) {
        platformUserIds.add(Number(match[1]));
      }
    }
  }
  if (platformUserIds.size) {
    const memberFaceByUserId = await loadHwyMemberFacesByPlatformUserIds([...platformUserIds]);
    const preferMemberLinkedAuditFace = (
      face: HwyMemberListFace | null,
    ): HwyMemberListFace | null => {
      if (!face?.id) {
        return face;
      }
      const match = /^user-(\d+)$/.exec(face.id.trim());
      if (!match) {
        return face;
      }
      const memberFace = memberFaceByUserId.get(Number(match[1]));
      if (memberFace && hwyMemberListFaceHasLabel(memberFace)) {
        return memberFace;
      }
      const strippedUsername = String(face.username ?? '').replace(/^user-/i, '').trim();
      if (strippedUsername && strippedUsername !== face.username) {
        return { ...face, username: strippedUsername };
      }
      return face;
    };
    for (const row of rows) {
      row.createdBy = preferMemberLinkedAuditFace(row.createdBy);
      row.updatedBy = preferMemberLinkedAuditFace(row.updatedBy);
    }
  }

  const auditFaces: HwyMemberListFace[] = [];
  for (const row of rows) {
    if (row.createdBy) {
      auditFaces.push(row.createdBy);
    }
    if (row.updatedBy) {
      auditFaces.push(row.updatedBy);
    }
  }
  await enrichActivityAuditFaceAvatars(auditFaces);
};

const enrichAttendanceRowsCreatedBy = async <
  T extends { id: string; legacyCreatedBy: string | null; createdBy: HwyMemberListFace | null },
>(
  rows: T[],
): Promise<T[]> => {
  if (!rows.length) {
    return rows;
  }
  const authorByAttendanceId = await resolveNegoNoteAuthorsBatch(
    rows.map((row) => ({
      id: row.id,
      createdByLegacy: row.legacyCreatedBy ?? '',
      createdByUserId: null,
      author: null,
    })),
  );
  return rows.map((row) => ({
    ...row,
    createdBy: authorByAttendanceId.get(row.id) ?? null,
  }));
};

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const resolveLegacyGeoNodeTitle = async (
  legacyId: number | null | undefined,
  kind: 'province' | 'circle',
  queryLang: string,
): Promise<string | null> => {
  if (legacyId == null || !Number.isFinite(legacyId)) {
    return null;
  }
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const ref = String(Math.trunc(legacyId));
  const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
  const baseInfoId = resolveHwyEtlGeoBaseInfoId(geoMap, kind, ref, 0) ?? ref;
  const enriched = await listBaseInfoEnrichmentRowsByIds([baseInfoId], cultureId);
  const match = enriched[0];
  if (!match) {
    return null;
  }
  const path = trim(String(match.title_path ?? match.title ?? match.title_canonical ?? ''));
  return leafTitleFromGeoPath(path) || path || null;
};

const attachCoursesActivitiesDetailGeoTitles = async (
  detail: {
    legacyProvinceId: number | null;
    legacyRegionProvinceId?: number | null;
    legacyRegionCircleId?: number | null;
    legacyProvinceTitle?: string | null;
    legacyRegionProvinceTitle?: string | null;
    legacyRegionCircleTitle?: string | null;
  },
  queryLang: string,
): Promise<void> => {
  detail.legacyProvinceTitle = await resolveLegacyGeoNodeTitle(detail.legacyProvinceId, 'province', queryLang);
  if (detail.legacyRegionProvinceId != null) {
    detail.legacyRegionProvinceTitle = await resolveLegacyGeoNodeTitle(
      detail.legacyRegionProvinceId,
      'province',
      queryLang,
    );
  }
  if (detail.legacyRegionCircleId != null) {
    detail.legacyRegionCircleTitle = await resolveLegacyGeoNodeTitle(
      detail.legacyRegionCircleId,
      'circle',
      queryLang,
    );
  }
};

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy courses/activities admin requires SQL Server control plane.');
  }
  await ensureHwyCoursesActivitiesSchema();
  await ensureHwyCoursesActivitiesStatusVocab();
  try {
    await ensureHwyDbObjects();
  } catch {
    /* Parity-only install batches (pipeline/card/meetings) must not block courses/activities lists. */
  }
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return {
    page: safePage,
    pageSize: safePageSize,
    offset: (safePage - 1) * safePageSize,
  };
};

const enrichActivityRows = async (rows: HwyActivityAdminRow[], queryLang: string): Promise<void> => {
  const enrichRows = rows as unknown as Record<string, unknown>[];
  await attachBaseInfoTitles(
    enrichRows,
    [
      { codeField: 'activityTypeCode', titleField: 'activityTypeCodeTitle' },
      { codeField: 'activitySubtypeCode', titleField: 'activitySubtypeCodeTitle' },
      { codeField: 'statusCode', titleField: 'statusCodeTitle' },
    ],
    queryLang,
  );
  for (let index = 0; index < rows.length; index += 1) {
    const source = enrichRows[index];
    rows[index].activityTypeCodeTitle = trim(String(source?.activityTypeCodeTitle ?? '')) || undefined;
    rows[index].activitySubtypeCodeTitle = trim(String(source?.activitySubtypeCodeTitle ?? '')) || undefined;
    rows[index].statusCodeTitle = resolveHwyCoursesActivitiesStatusLocalizedTitle(
      rows[index].statusCode,
      queryLang,
      source?.statusCodeTitle,
    );
  }
};

