export async function readHwyActivityFileContent(fileIdRaw: string): Promise<{
  mime: string;
  fileName: string;
  buffer: Buffer;
}> {
  await assertSqlServer();
  const fileId = trim(fileIdRaw);
  if (!fileId) {
    throw new Error('File not found.');
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    original_file_name: string;
    mime: string | null;
    content: Buffer | null;
    thumbnail_content: Buffer | null;
  }>(
    `SELECT original_file_name, mime, content, thumbnail_content FROM dbo.hwy_activity_files WHERE id = :fileId`,
    { replacements: { fileId }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    throw new Error('File not found.');
  }
  const row = rows[0];
  const buffer = row.content ?? row.thumbnail_content;
  if (!buffer?.length) {
    throw new Error('File content is not available on this server.');
  }
  return {
    mime: row.mime?.trim() || 'application/octet-stream',
    fileName: row.original_file_name?.trim() || 'activity-file',
    buffer,
  };
}

