export async function listHwyTajammoatOrganizationPickerOptions(): Promise<{ id: string; label: string }[]> {
  await assertSqlServer();
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: string; label: string }>(
    `
    SELECT CAST(id AS VARCHAR(32)) AS id, title_ar AS label
    FROM dbo.hwy_institutes
    WHERE is_active = 1
    ORDER BY title_ar, id
    `,
    { type: QueryTypes.SELECT },
  );
  return rows
    .map((row) => ({ id: trim(String(row.id)), label: trim(String(row.label)) }))
    .filter((row) => row.id && row.label);
}
