import { QueryTypes } from 'sequelize';

import {
  assertHwyActivitySelfAnnouncementAllowed,
  resolveHwyActivitySelfAnnouncementMetadataPolicy,
} from '../../../domain/hwy/hwyActivitySelfAnnouncementPolicy';
import type { HwySubmissionMetadataSpecResponse } from '../../../domain/hwy/hwySubmissionMetadata';
import {
  assertHwySubmissionMetadata,
  parseHwySubmissionMetadataPayload,
} from '../../../domain/hwy/hwySubmissionMetadata';
import { enrichHwySubmissionMetadataFromClientClaimed } from '../../../domain/hwy/hwySubmissionMetadataFromClient';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyCoursesActivitiesSchema } from './ensureHwyCoursesActivitiesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

type ActivityPolicyRow = {
  activity_type_code: string | null;
  status_code: string | null;
  enable_self_announcement: boolean | number | null;
  activity_date: Date | string | null;
  nb_window_start_at: Date | string | null;
  nb_window_end_at: Date | string | null;
  require_submission_device_metadata: boolean | number | null;
};

const readActivityPolicyRow = async (activityId: number): Promise<ActivityPolicyRow | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<ActivityPolicyRow>(
    `
    SELECT
      activity_type_code,
      status_code,
      enable_self_announcement,
      activity_date,
      nb_window_start_at,
      nb_window_end_at,
      require_submission_device_metadata
    FROM dbo.hwy_activities
    WHERE id = :activityId
    `,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  return rows[0] ?? null;
};

const toPolicyInput = (row: ActivityPolicyRow) => ({
  activityTypeCode: trim(row.activity_type_code) || null,
  statusCode: trim(row.status_code) || null,
  enableSelfAnnouncement: row.enable_self_announcement === true
    || row.enable_self_announcement === 1
    || row.enable_self_announcement === '1',
  activityDate: row.activity_date
    ? new Date(row.activity_date as string | Date).toISOString().slice(0, 10)
    : null,
  nbWindowStartAt: row.nb_window_start_at
    ? new Date(row.nb_window_start_at as string | Date).toISOString()
    : null,
  nbWindowEndAt: row.nb_window_end_at
    ? new Date(row.nb_window_end_at as string | Date).toISOString()
    : null,
  requireSubmissionDeviceMetadata: row.require_submission_device_metadata == null
    ? null
    : row.require_submission_device_metadata === true
      || row.require_submission_device_metadata === 1
      || row.require_submission_device_metadata === '1',
});

export const resolveHwyMemberIdForUser = async (userId: number): Promise<number | null> => {
  if (!Number.isFinite(userId) || userId <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number | string }>(
    `SELECT TOP 1 id FROM dbo.hwy_members WHERE user_id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  const id = Number(rows[0]?.id);
  return Number.isFinite(id) && id > 0 ? id : null;
};

export async function readHwyActivitySelfAnnouncementSpec(
  activityIdRaw: string,
): Promise<HwySubmissionMetadataSpecResponse> {
  await ensureHwyCoursesActivitiesSchema();
  if (readControlPlaneProvider() !== 'sqlserver') {
    return { fields: [] };
  }
  const activityId = Number(trim(activityIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Activity not found.');
  }
  const row = await readActivityPolicyRow(activityId);
  if (!row) {
    throw new Error('Activity not found.');
  }
  return resolveHwyActivitySelfAnnouncementMetadataPolicy(toPolicyInput(row));
}

const resolveActorUsername = async (userId: number): Promise<string> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ username: string }>(
    `SELECT username FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  return trim(rows[0]?.username) || 'member';
};

export async function submitHwyActivitySelfAnnouncement(input: {
  activityIdRaw: string;
  userId: number;
  metadata: Record<string, unknown>;
  clientClaimed?: Record<string, unknown>;
  selfie: {
    buffer: Buffer;
    originalName: string;
    mime: string;
  };
}): Promise<{ attendanceId: string }> {
  await ensureHwyCoursesActivitiesSchema();
  await ensureHwyDbObjects();
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Self-announcement requires SQL Server control plane.');
  }
  const activityId = Number(trim(input.activityIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Activity not found.');
  }
  const memberId = await resolveHwyMemberIdForUser(input.userId);
  if (memberId == null) {
    throw new Error('No Hawiety member profile is linked to this account.');
  }

  const row = await readActivityPolicyRow(activityId);
  if (!row) {
    throw new Error('Activity not found.');
  }
  const policyInput = toPolicyInput(row);
  assertHwyActivitySelfAnnouncementAllowed(policyInput);
  const spec = resolveHwyActivitySelfAnnouncementMetadataPolicy(policyInput);
  const parsed = enrichHwySubmissionMetadataFromClientClaimed(
    parseHwySubmissionMetadataPayload(input.metadata),
    input.clientClaimed ?? {},
  );
  assertHwySubmissionMetadata({
    fields: spec.fields,
    payload: parsed,
    hasSelfie: input.selfie.buffer.length > 0,
  });

  const sequelize = getControlPlaneSequelize();
  const idRows = await sequelize.query<{ next_id: number | string }>(
    `SELECT ISNULL(MAX(id), 0) + 1 AS next_id FROM dbo.hwy_activity_attendances WITH (UPDLOCK, HOLDLOCK)`,
    { type: QueryTypes.SELECT },
  );
  const attendanceId = Number(idRows[0]?.next_id);
  if (!Number.isFinite(attendanceId) || attendanceId <= 0) {
    throw new Error('Could not allocate an attendance id.');
  }

  const selfieName = trim(input.selfie.originalName).slice(0, 128) || 'selfie.jpg';
  const selfieMime = trim(input.selfie.mime).slice(0, 32) || 'image/jpeg';
  const legacyCreatedBy = await resolveActorUsername(input.userId);

  try {
    await execHwyProcedure('hwy_activity_self_announce', {
      attendance_id: attendanceId,
      member_id: memberId,
      activity_id: activityId,
      nb_location_lat: parsed.nbLocationLat,
      nb_location_lon: parsed.nbLocationLon,
      selfie_file_name: selfieName,
      selfie_mime: selfieMime,
      selfie_size_bytes: input.selfie.buffer.length,
      selfie_content: input.selfie.buffer,
      nb_device_os: parsed.nbDeviceOs,
      nb_device_id: parsed.nbDeviceId,
      nb_device_datetime: parsed.nbDeviceDatetime,
      legacy_created_by: legacyCreatedBy,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('55201')) {
      throw new Error('You are already registered for this activity.');
    }
    throw error;
  }

  return { attendanceId: String(attendanceId) };
}
