import {
  HWY_SELF_REGISTRATION_LEGACY_EDUCATION_LEVEL_PARENT_ID,
  HWY_SELF_REGISTRATION_LEGACY_JOB_TYPE_PARENT_ID,
  type HwySelfRegistrationVocabOption,
} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationEducationJobVocab';
import {
  HWY_SELF_REGISTRATION_EDUCATION_LEVEL_ETL_CATEGORY_TITLE,
  HWY_SELF_REGISTRATION_JOB_TYPE_ETL_CATEGORY_TITLE,
  resolveEducationJobVocabFallback,
  type HwySelfRegistrationVocabFallbackRow,
} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationEducationJobVocabCatalog';
import { buildMergedCultureBundle } from '../base-info/baseInfoCultureTranslationStore';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';
import { HWY_BASE_INFO_ROOT_ID } from './hwyBaseInfoRuntime';
import { listLegacyHwyBaseInformationByParent } from './hwyLegacyBaseInformationReader';

const normalizeCultureId = (cultureId: string | null | undefined): string => {
  const trimmed = String(cultureId ?? '').trim();
  return trimmed || 'iq';
};

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

type PlatformBaseInfoRow = BaseInfoDbRow;

const sortLegacyRows = (
  rows: Awaited<ReturnType<typeof listLegacyHwyBaseInformationByParent>>,
) => (
  [...rows].sort((a, b) => {
    const orderA = a.viewOrder ?? 0;
    const orderB = b.viewOrder ?? 0;
    if (orderA !== orderB) {
      return orderA - orderB;
    }
    return a.id - b.id;
  })
);

const resolveCultureLabel = (
  cultureLabelKey: string,
  bundle: Record<string, string>,
): string => bundle[cultureLabelKey]?.trim() || cultureLabelKey;

const fallbackRowsToOptions = (
  rows: HwySelfRegistrationVocabFallbackRow[],
  bundle: Record<string, string>,
): HwySelfRegistrationVocabOption[] => (
  rows.map((row) => ({
    value: row.legacyId,
    label: resolveCultureLabel(row.cultureLabelKey, bundle),
  }))
);

const legacyDbRowsToOptions = (
  rows: Awaited<ReturnType<typeof listLegacyHwyBaseInformationByParent>>,
  legacyParentId: number,
  cultureId: string,
  bundle: Record<string, string>,
): HwySelfRegistrationVocabOption[] => {
  const fallbackByLegacyId = new Map(
    resolveEducationJobVocabFallback(legacyParentId).map((row) => [row.legacyId, row]),
  );

  return sortLegacyRows(rows)
    .map((row) => {
      const legacyId = String(row.id);
      const fallback = fallbackByLegacyId.get(legacyId);
      const labelFromLegacy = row.title.trim();
      const label = labelFromLegacy
        || (fallback ? resolveCultureLabel(fallback.cultureLabelKey, bundle) : '');
      return { value: legacyId, label };
    })
    .filter((item) => item.value && item.label);
};

const listPlatformCategoryRows = async (categoryTitle: string): Promise<PlatformBaseInfoRow[]> => {
  try {
    const category = await prisma().baseInfo.findFirst({
      where: {
        parentId: HWY_BASE_INFO_ROOT_ID,
        title: categoryTitle,
      },
      select: { id: true },
    });
    if (!category) {
      return [];
    }
    return prisma().baseInfo.findMany({
      where: {
        parentId: category.id,
        isActive: true,
      },
      orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
      select: BASE_INFO_ROW_SELECT,
    });
  } catch {
    return [];
  }
};

const enrichLabelsFromPlatformCulture = async (
  options: HwySelfRegistrationVocabOption[],
  cultureId: string,
  categoryTitle: string,
  legacyParentId: number,
): Promise<HwySelfRegistrationVocabOption[]> => {
  if (options.length === 0) {
    return options;
  }

  const platformRows = await listPlatformCategoryRows(categoryTitle);
  if (platformRows.length === 0) {
    return options;
  }

  try {
    const mapped = await mapBaseInfoRowsForCulture(platformRows, cultureId, (row, context) => ({
      viewOrder: toViewOrderNumber(row.viewOrder),
      label: context.label,
    }));

    const labelByViewOrder = new Map<number, string>();
    for (const item of mapped) {
      const order = typeof item.viewOrder === 'number' ? item.viewOrder : null;
      const label = String(item.label ?? '').trim();
      if (order != null && Number.isFinite(order) && label) {
        labelByViewOrder.set(order, label);
      }
    }

    const fallbackByLegacyId = new Map(
      resolveEducationJobVocabFallback(legacyParentId).map((row) => [row.legacyId, row.viewOrder]),
    );

    return options.map((option) => {
      const viewOrder = fallbackByLegacyId.get(option.value);
      if (viewOrder == null) {
        return option;
      }
      const platformLabel = labelByViewOrder.get(viewOrder);
      return platformLabel ? { ...option, label: platformLabel } : option;
    });
  } catch {
    return options;
  }
};

const listCategoryVocabOptions = async (
  cultureId: string,
  categoryTitle: string,
  legacyParentId: number,
): Promise<HwySelfRegistrationVocabOption[]> => {
  const bundle = buildMergedCultureBundle(cultureId);
  const fallbackRows = resolveEducationJobVocabFallback(legacyParentId);

  const legacyRows = await listLegacyHwyBaseInformationByParent(legacyParentId);
  let options: HwySelfRegistrationVocabOption[];
  if (legacyRows.length > 0) {
    options = legacyDbRowsToOptions(legacyRows, legacyParentId, cultureId, bundle);
  } else {
    options = fallbackRowsToOptions(fallbackRows, bundle);
  }

  if (options.length === 0) {
    options = fallbackRowsToOptions(fallbackRows, bundle);
  }

  return enrichLabelsFromPlatformCulture(options, cultureId, categoryTitle, legacyParentId);
};

export const listHwySelfRegistrationEducationLevelOptions = async (
  cultureId: string | null | undefined,
): Promise<HwySelfRegistrationVocabOption[]> => {
  const resolvedCultureId = normalizeCultureId(cultureId);
  try {
    return await listCategoryVocabOptions(
      resolvedCultureId,
      HWY_SELF_REGISTRATION_EDUCATION_LEVEL_ETL_CATEGORY_TITLE,
      HWY_SELF_REGISTRATION_LEGACY_EDUCATION_LEVEL_PARENT_ID,
    );
  } catch {
    const bundle = buildMergedCultureBundle(resolvedCultureId);
    return fallbackRowsToOptions(
      resolveEducationJobVocabFallback(HWY_SELF_REGISTRATION_LEGACY_EDUCATION_LEVEL_PARENT_ID),
      bundle,
    );
  }
};

export const listHwySelfRegistrationJobTypeOptions = async (
  cultureId: string | null | undefined,
): Promise<HwySelfRegistrationVocabOption[]> => {
  const resolvedCultureId = normalizeCultureId(cultureId);
  try {
    return await listCategoryVocabOptions(
      resolvedCultureId,
      HWY_SELF_REGISTRATION_JOB_TYPE_ETL_CATEGORY_TITLE,
      HWY_SELF_REGISTRATION_LEGACY_JOB_TYPE_PARENT_ID,
    );
  } catch {
    const bundle = buildMergedCultureBundle(resolvedCultureId);
    return fallbackRowsToOptions(
      resolveEducationJobVocabFallback(HWY_SELF_REGISTRATION_LEGACY_JOB_TYPE_PARENT_ID),
      bundle,
    );
  }
};

const pairLegacyTitlesToPlatformRows = (
  legacyRows: Awaited<ReturnType<typeof listLegacyHwyBaseInformationByParent>>,
  platformRows: PlatformBaseInfoRow[],
): { platformRow: PlatformBaseInfoRow; legacyTitle: string }[] => {
  if (legacyRows.length === 0 || platformRows.length === 0) {
    return [];
  }

  const legacySorted = sortLegacyRows(legacyRows);
  const platformByTitle = new Map(
    platformRows.map((row) => [String(row.title ?? '').trim().toLowerCase(), row]),
  );
  const usedPlatformIds = new Set<string>();
  const pairs: { platformRow: PlatformBaseInfoRow; legacyTitle: string }[] = [];

  for (const legacyRow of legacySorted) {
    const titleKey = legacyRow.title.trim().toLowerCase();
    let platformRow = platformByTitle.get(titleKey);
    if (!platformRow || usedPlatformIds.has(platformRow.id)) {
      platformRow = platformRows.find((row) => !usedPlatformIds.has(row.id));
    }
    if (!platformRow) {
      continue;
    }
    usedPlatformIds.add(platformRow.id);
    pairs.push({ platformRow, legacyTitle: legacyRow.title });
  }

  return pairs;
};

const resolvePlatformBaseInfoId = async (raw: string): Promise<string | null> => {
  try {
    const row = await prisma().baseInfo.findUnique({
      where: { id: raw },
      select: { id: true, isActive: true },
    });
    if (row?.isActive) {
      return row.id;
    }
  } catch {
    // ignore
  }
  return null;
};

const resolveLegacyVocabIdToPlatformBaseInfoId = async (
  legacyIdRaw: string,
  categoryTitle: string,
  legacyParentId: number,
): Promise<string | null> => {
  if (!/^\d+$/.test(legacyIdRaw)) {
    return null;
  }
  const legacyId = Number(legacyIdRaw);
  if (!Number.isFinite(legacyId) || legacyId <= 0) {
    return null;
  }

  const legacyRows = await listLegacyHwyBaseInformationByParent(legacyParentId);
  const legacyRow = legacyRows.find((row) => row.id === legacyId);
  const fallbackRow = resolveEducationJobVocabFallback(legacyParentId)
    .find((row) => row.legacyId === legacyIdRaw);

  if (!legacyRow && !fallbackRow) {
    return null;
  }

  try {
    const platformRows = await listPlatformCategoryRows(categoryTitle);
    if (platformRows.length === 0) {
      return null;
    }

    if (legacyRows.length > 0) {
      const pairs = pairLegacyTitlesToPlatformRows(legacyRows, platformRows);
      const targetTitle = legacyRow?.title.trim()
        ?? (fallbackRow ? resolveCultureLabel(fallbackRow.cultureLabelKey, buildMergedCultureBundle('iq')) : '');
      const match = pairs.find((pair) => pair.legacyTitle.trim() === targetTitle);
      if (match) {
        return match.platformRow.id;
      }
    }

    if (fallbackRow) {
      const index = resolveEducationJobVocabFallback(legacyParentId)
        .findIndex((row) => row.legacyId === legacyIdRaw);
      if (index >= 0 && index < platformRows.length) {
        return platformRows[index]?.id ?? null;
      }
    }
  } catch {
    return null;
  }

  return null;
};

const resolveVocabSelectionToBaseInfoFk = async (
  raw: string | null | undefined,
  categoryTitle: string,
  legacyParentId: number,
): Promise<string | null> => {
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) {
    return null;
  }

  const platformId = await resolvePlatformBaseInfoId(trimmed);
  if (platformId) {
    return platformId;
  }

  return resolveLegacyVocabIdToPlatformBaseInfoId(trimmed, categoryTitle, legacyParentId);
};

export const resolveHwySelfRegistrationEducationLevelCode = async (
  raw: string | null | undefined,
): Promise<string | null> => resolveVocabSelectionToBaseInfoFk(
  raw,
  HWY_SELF_REGISTRATION_EDUCATION_LEVEL_ETL_CATEGORY_TITLE,
  HWY_SELF_REGISTRATION_LEGACY_EDUCATION_LEVEL_PARENT_ID,
);

export const resolveHwySelfRegistrationJobTypeCode = async (
  raw: string | null | undefined,
): Promise<string | null> => resolveVocabSelectionToBaseInfoFk(
  raw,
  HWY_SELF_REGISTRATION_JOB_TYPE_ETL_CATEGORY_TITLE,
  HWY_SELF_REGISTRATION_LEGACY_JOB_TYPE_PARENT_ID,
);

export const resolveOptionalHwyMemberBaseInfoFk = async (
  raw: string | null | undefined,
): Promise<string | null> => {
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) {
    return null;
  }
  const row = await resolvePlatformBaseInfoId(trimmed);
  if (!row) {
    throw new Error('Selected vocabulary value is invalid.');
  }
  return row;
};
