import { QueryTypes } from 'sequelize';
import type { HwyOrgMembershipTransferInstituteSpec } from '../../../domain/hwy/hwyOrgMembershipTransferCatalog';
import {
  HWY_ORG_MEMBERSHIP_TRANSFER_INSTITUTES,
  findHwyOrgMembershipTransferInstituteByCode,
} from '../../../domain/hwy/hwyOrgMembershipTransferCatalog';
import type {
  HwyOrgMembershipTransferConfig,
  HwyOrgMembershipTransferInstituteLink,
  HwyOrgMembershipTransferMemberRow,
  HwyOrgMembershipTransferSearchInput,
  HwyOrgMembershipTransferSearchResult,
} from '../../../domain/hwy/hwyOrgMembershipTransfer';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { findHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';
import { resolveHwyBaseInfoItemId } from './hwyBaseInfoRuntime';
import { enrichHwyMemberDirectoryListRows } from './hwyMemberDirectoryDetailDisplay';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;

type ResolvedTransferInstitute = HwyOrgMembershipTransferInstituteSpec & {
  instituteId: number;
  instituteTitle: string;
};

const trim = (value: string | undefined): string => value?.trim() ?? '';

const loadResolvedTransferInstitutes = async (): Promise<ResolvedTransferInstitute[]> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  const sequelize = getControlPlaneSequelize();
  const codes = HWY_ORG_MEMBERSHIP_TRANSFER_INSTITUTES.map((row) => row.instituteCode);
  const rows = await sequelize.query<{ id: number; code: string; title_ar: string | null }>(
    `
    SELECT id, code, title_ar
    FROM dbo.hwy_institutes
    WHERE code IN (:codes) AND is_active = 1
    `,
    { replacements: { codes }, type: QueryTypes.SELECT },
  );
  const byCode = new Map(rows.map((row) => [String(row.code), row]));
  const resolved: ResolvedTransferInstitute[] = [];
  for (const spec of HWY_ORG_MEMBERSHIP_TRANSFER_INSTITUTES) {
    const row = byCode.get(spec.instituteCode);
    if (!row?.id) {
      continue;
    }
    resolved.push({
      ...spec,
      instituteId: Number(row.id),
      instituteTitle: String(row.title_ar ?? spec.instituteCode).trim() || spec.instituteCode,
    });
  }
  return resolved;
};

const userCanRequestForInstitute = (
  roleNames: readonly string[],
  spec: ResolvedTransferInstitute,
): boolean => (
  roleNames.includes('ADMIN')
  || roleNames.includes(`HWY_R_${spec.legacyRequestRoleId}`)
);

export const readHwyOrgMembershipTransferConfig = async (
  roleNames: readonly string[],
): Promise<HwyOrgMembershipTransferConfig> => {
  const institutes = await loadResolvedTransferInstitutes();
  return {
    institutes: institutes.map((row) => ({
      instituteId: row.instituteId,
      instituteCode: row.instituteCode,
      instituteTitle: row.instituteTitle,
      requestLabelKey: row.requestLabelKey,
      canRequest: userCanRequestForInstitute(roleNames, row),
    })),
  };
};

type InstituteMembershipRow = {
  memberId: string;
  instituteId: number;
  joinPathCode: string | null;
  memberAccepted: boolean | number | null;
};

const loadInstituteMembershipByMemberIds = async (
  memberIds: readonly string[],
  instituteIds: readonly number[],
): Promise<Map<string, InstituteMembershipRow[]>> => {
  const map = new Map<string, InstituteMembershipRow[]>();
  if (memberIds.length === 0 || instituteIds.length === 0 || readControlPlaneProvider() !== 'sqlserver') {
    return map;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<InstituteMembershipRow>(
    `
    SELECT
      CAST(mi.member_id AS VARCHAR(32)) AS memberId,
      mi.institute_id AS instituteId,
      mi.join_path_code AS joinPathCode,
      mi.member_accepted AS memberAccepted
    FROM dbo.hwy_member_institutes mi
    WHERE mi.member_id IN (:memberIds)
      AND mi.institute_id IN (:instituteIds)
    `,
    {
      replacements: { memberIds: [...memberIds], instituteIds: [...instituteIds] },
      type: QueryTypes.SELECT,
    },
  );
  for (const row of rows) {
    const memberId = trim(row.memberId);
    if (!memberId) {
      continue;
    }
    const bucket = map.get(memberId) ?? [];
    bucket.push(row);
    map.set(memberId, bucket);
  }
  return map;
};

const buildMemberDisplayFullName = (row: Record<string, unknown>): string | null => {
  const parts = [
    row.firstName,
    row.fatherName,
    row.grandfatherName,
    row.familyName,
  ]
    .map((part) => trim(String(part ?? '')))
    .filter(Boolean);
  return parts.length > 0 ? parts.join(' ') : null;
};

const buildNakhebinPatchSummary = (row: Record<string, unknown>): string | null => {
  const line1 = trim(String(row.electoralDivisionLine1 ?? row.electoralDivisionPath ?? ''));
  const line2 = trim(String(row.electoralDivisionLine2 ?? ''));
  const joined = [line1, line2].filter(Boolean).join(' / ');
  return joined || null;
};

const buildInstituteLinks = (
  memberId: string,
  institutes: ResolvedTransferInstitute[],
  membershipByMember: Map<string, InstituteMembershipRow[]>,
  inviteJoinPathCode: string,
  roleNames: readonly string[],
): HwyOrgMembershipTransferInstituteLink[] => {
  const memberships = membershipByMember.get(memberId) ?? [];
  const byInstituteId = new Map(memberships.map((row) => [Number(row.instituteId), row]));
  return institutes.map((institute) => {
    const membership = byInstituteId.get(institute.instituteId);
    const hasRecord = membership != null;
    const approvedByMember = membership?.memberAccepted === true || membership?.memberAccepted === 1;
    const requestedByOrganization = hasRecord
      && trim(membership?.joinPathCode ?? '') === inviteJoinPathCode;
    const canRequest = userCanRequestForInstitute(roleNames, institute) && !requestedByOrganization;
    const canRollback = hasRecord && userCanRequestForInstitute(roleNames, institute);
    return {
      instituteId: institute.instituteId,
      instituteCode: institute.instituteCode,
      instituteTitle: institute.instituteTitle,
      requestLabelKey: institute.requestLabelKey,
      hasRecord,
      requestedByOrganization,
      approvedByMember,
      canRequest,
      canRollback,
    };
  });
};

export const searchHwyOrgMembershipTransferMembers = async (
  input: HwyOrgMembershipTransferSearchInput,
  roleNames: readonly string[],
  queryLang = 'ar',
  session: SessionScopeSnapshot | null | undefined = null,
): Promise<HwyOrgMembershipTransferSearchResult> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return { rows: [], total: 0, page: 1, pageSize: DEFAULT_PAGE_SIZE };
  }
  const page = Math.max(1, Number(input.page) || 1);
  const pageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, Number(input.pageSize) || DEFAULT_PAGE_SIZE));
  const offset = (page - 1) * pageSize;

  const hasSearchCriteria = [
    input.username,
    input.trackingCode,
    input.phone,
    input.genderCode,
    input.firstName,
    input.fatherName,
    input.grandfatherName,
    input.familyName,
    input.birthYear,
  ].some((value) => trim(value));

  const ctx = await loadHwyMemberListScopeContext();
  const otherPortalCode = await findHwyBaseInfoItemIdByShortName('Registration Channel', 'other_portal');
  const inviteJoinPathCode = await resolveHwyBaseInfoItemId('Institute Join Path', 'invite');

  const institutes = await loadResolvedTransferInstitutes();
  await ensureHwyDbObjects();

  const likeOrNull = (value: string): string | null => (value ? `%${value}%` : null);
  const eqOrNull = (value: string): string | null => (value || null);

  let rawRows: Record<string, unknown>[];
  let total: number;
  let browseMode = false;
  let effectivePage = page;
  let effectivePageSize = pageSize;

  if (!hasSearchCriteria) {
    browseMode = true;
    effectivePageSize = Math.min(pageSize, 20);
    effectivePage = 1;
    if (page > 1) {
      return {
        rows: [],
        total: 0,
        page,
        pageSize: effectivePageSize,
        browseMode: true,
      };
    }
    rawRows = await execHwyProcedure<Record<string, unknown>>('hwy_org_membership_transfer_members_browse', {
      active_status_code: ctx.membershipStatusCodes.active,
      other_portal_code: otherPortalCode,
      browse_page_size: effectivePageSize,
    });
    total = rawRows.length;
  } else {
    rawRows = await execHwyProcedure<Record<string, unknown>>('hwy_org_membership_transfer_members_search', {
      active_status_code: ctx.membershipStatusCodes.active,
      other_portal_code: otherPortalCode,
      offset,
      page_size: pageSize,
      username: eqOrNull(trim(input.username)),
      tracking_code: eqOrNull(trim(input.trackingCode)),
      gender_code: eqOrNull(trim(input.genderCode)),
      birth_year: eqOrNull(trim(input.birthYear)),
      phone: eqOrNull(trim(input.phone)),
      first_name_like: likeOrNull(trim(input.firstName)),
      father_name_like: likeOrNull(trim(input.fatherName)),
      grandfather_name_like: likeOrNull(trim(input.grandfatherName)),
      family_name_like: likeOrNull(trim(input.familyName)),
    });
    total = Number(rawRows[0]?.__total ?? 0);
  }

  await enrichHwyMemberDirectoryListRows(rawRows, queryLang, {
    includeElectoralDivisionPath: true,
    includeListFaceAvatarsFromRegistration: true,
  });

  const sequelize = getControlPlaneSequelize();
  await applyHwyMemberIdentityFieldMasksToRows(sequelize, rawRows, session ?? null);

  const memberIds = rawRows.map((row) => trim(String(row.id ?? ''))).filter(Boolean);
  const instituteIds = institutes.map((row) => row.instituteId);
  const membershipByMember = await loadInstituteMembershipByMemberIds(memberIds, instituteIds);

  const rows: HwyOrgMembershipTransferMemberRow[] = rawRows.map((row) => {
    const memberId = trim(String(row.id ?? ''));
    return {
      id: memberId,
      username: row.username != null ? String(row.username) : null,
      displayFullName: formatHwyMemberPersonDisplayName(
        row.displayFullName != null
          ? String(row.displayFullName)
          : buildMemberDisplayFullName(row),
      ) || null,
      avatarUrl: row.avatarUrl != null ? String(row.avatarUrl) : null,
      genderCode: row.genderCode != null ? String(row.genderCode) : null,
      birthYear: row.birthYear != null ? String(row.birthYear) : null,
      phone1: row.phone1 != null ? String(row.phone1) : null,
      phone2: row.phone2 != null ? String(row.phone2) : null,
      membershipOn: row.membershipOn != null ? String(row.membershipOn) : null,
      nakhebinPatchSummary: buildNakhebinPatchSummary(row),
      institutes: buildInstituteLinks(
        memberId,
        institutes,
        membershipByMember,
        inviteJoinPathCode,
        roleNames,
      ),
    };
  });

  return {
    rows,
    total,
    page: effectivePage,
    pageSize: effectivePageSize,
    browseMode: browseMode || undefined,
  };
};

const resolveInstituteForMutation = async (
  instituteCode: string,
): Promise<ResolvedTransferInstitute> => {
  const spec = findHwyOrgMembershipTransferInstituteByCode(instituteCode);
  if (!spec) {
    throw new Error('Unknown institute.');
  }
  const institutes = await loadResolvedTransferInstitutes();
  const resolved = institutes.find((row) => row.instituteCode === instituteCode);
  if (!resolved) {
    throw new Error('Institute is not available for transfer.');
  }
  return resolved;
};

export const requestHwyOrgMembershipTransferForMember = async (input: {
  memberId: string;
  instituteCode: string;
  actorUserId: number | null;
  roleNames: readonly string[];
}): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Org membership transfer requires SQL Server.');
  }
  const institute = await resolveInstituteForMutation(input.instituteCode);
  if (!userCanRequestForInstitute(input.roleNames, institute)) {
    throw new Error('Forbidden.');
  }
  const memberId = trim(input.memberId);
  if (!memberId) {
    throw new Error('Member id is required.');
  }

  const pendingStatus = await resolveHwyBaseInfoItemId('Institute Membership Status', 'pending_invite');
  const inviteJoinPath = await resolveHwyBaseInfoItemId('Institute Join Path', 'invite');
  const now = new Date();
  await ensureHwyDbObjects();

  await execHwyProcedure('hwy_org_membership_transfer_request', {
    member_id: Number(memberId),
    institute_id: institute.instituteId,
    status_code: pendingStatus,
    join_path_code: inviteJoinPath,
    invited_by: input.actorUserId,
    invited_at: now,
    created_at: now,
    updated_at: now,
  });
};

export const rollbackHwyOrgMembershipTransferForMember = async (input: {
  memberId: string;
  instituteCode: string;
  roleNames: readonly string[];
}): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Org membership transfer requires SQL Server.');
  }
  const institute = await resolveInstituteForMutation(input.instituteCode);
  if (!userCanRequestForInstitute(input.roleNames, institute)) {
    throw new Error('Forbidden.');
  }
  const memberId = trim(input.memberId);
  if (!memberId) {
    throw new Error('Member id is required.');
  }
  await ensureHwyDbObjects();
  await execHwyProcedure('hwy_org_membership_transfer_rollback', {
    member_id: Number(memberId),
    institute_id: institute.instituteId,
  });
};
