import type { HwyMemberRejectionListLegacyScope } from '../../../domain/hwy/hwyMemberRejectionListParity';
import { HWY_MEMBER_REJECTION_LIST_LEGACY_SCOPES } from '../../../domain/hwy/hwyMemberRejectionListParity';

export type LegacyRejectionListStatusRow = {
  member_id: string;
  status_note: string | null;
  change_reason_id: number | null;
  change_reason_title: string | null;
  status_updated_on: Date | string | null;
  note_by_call_center: string | null;
  latest_note: string | null;
  updated_by_username: string | null;
  updated_by_staff_member_id: string | null;
  updated_by_display_name: string | null;
  updated_by_phone: string | null;
  updated_by_roles: string | null;
};

const trimNote = (value: string | null | undefined): string => String(value ?? '').trim();

const bindMemberIdIn = (
  req: import('mssql').Request,
  memberIds: string[],
  prefix: string,
): string => {
  memberIds.forEach((id, index) => {
    const numeric = Number(id);
    if (Number.isFinite(numeric) && String(numeric) === String(id).trim()) {
      req.input(`${prefix}${index}`, numeric);
    } else {
      req.input(`${prefix}${index}`, id);
    }
  });
  return memberIds.map((_, index) => `@${prefix}${index}`).join(', ');
};

export async function queryLegacyRejectionListStatusFields(
  memberIds: string[],
): Promise<Map<string, LegacyRejectionListStatusRow>> {
  const ids = [...new Set(memberIds.map((id) => String(id).trim()).filter(Boolean))];
  const result = new Map<string, LegacyRejectionListStatusRow>();
  if (ids.length === 0) {
    return result;
  }

  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const req = pool.request();
    const inList = bindMemberIdIn(req, ids, 'mid');
    const rows = (await req.query(`
      SELECT
        CAST(m.Id AS VARCHAR(32)) AS member_id,
        NULLIF(LTRIM(RTRIM(CAST(m.MembershipStatus_Note AS NVARCHAR(MAX)))), N'') AS status_note,
        m.MembershipStatus_ChangeReasonId AS change_reason_id,
        NULLIF(LTRIM(RTRIM(CAST(cr.Title AS NVARCHAR(MAX)))), N'') AS change_reason_title,
        m.MembershipStatus_UpdatedOn AS status_updated_on,
        (
          SELECT TOP 1 NULLIF(LTRIM(RTRIM(CAST(n.Note AS NVARCHAR(MAX)))), N'')
          FROM dbo.HWY_Members_Notes n WITH (NOLOCK)
          WHERE n.MemberId = m.Id
            AND EXISTS (
              SELECT 1
              FROM dbo.AppEnd_Users_R_Roles r WITH (NOLOCK)
              INNER JOIN dbo.AppEnd_Users u WITH (NOLOCK) ON u.Id = r.UserId
              WHERE u.UserName = n.CreatedBy
                AND r.RoleId = 1000006
            )
          ORDER BY n.CreatedOn DESC
        ) AS note_by_call_center,
        (
          SELECT TOP 1 NULLIF(LTRIM(RTRIM(CAST(n2.Note AS NVARCHAR(MAX)))), N'')
          FROM dbo.HWY_Members_Notes n2 WITH (NOLOCK)
          WHERE n2.MemberId = m.Id
            AND NULLIF(LTRIM(RTRIM(CAST(n2.Note AS NVARCHAR(MAX)))), N'') IS NOT NULL
          ORDER BY n2.CreatedOn DESC
        ) AS latest_note,
        NULLIF(LTRIM(RTRIM(CAST(m.MembershipStatus_UpdatedBy AS NVARCHAR(4000)))), N'') AS updated_by_username,
        CAST(COALESCE(staff_un.Id, staff_id.Id, staff_uid.Id) AS VARCHAR(32)) AS updated_by_staff_member_id,
        NULLIF(LTRIM(RTRIM(CONCAT_WS(N' ',
          NULLIF(LTRIM(RTRIM(COALESCE(
            CAST(staff_un.FirstName AS NVARCHAR(4000)),
            CAST(staff_id.FirstName AS NVARCHAR(4000)),
            CAST(staff_uid.FirstName AS NVARCHAR(4000)),
            N''
          ))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(
            CAST(staff_un.FatherName AS NVARCHAR(4000)),
            CAST(staff_id.FatherName AS NVARCHAR(4000)),
            CAST(staff_uid.FatherName AS NVARCHAR(4000)),
            N''
          ))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(
            CAST(staff_un.GrandFatherName AS NVARCHAR(4000)),
            CAST(staff_id.GrandFatherName AS NVARCHAR(4000)),
            CAST(staff_uid.GrandFatherName AS NVARCHAR(4000)),
            N''
          ))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(
            CAST(staff_un.LastName AS NVARCHAR(4000)),
            CAST(staff_id.LastName AS NVARCHAR(4000)),
            CAST(staff_uid.LastName AS NVARCHAR(4000)),
            N''
          ))), N'')
        ))), N'') AS updated_by_display_name,
        NULLIF(LTRIM(RTRIM(COALESCE(
          CAST(staff_un.Phone1 AS NVARCHAR(4000)),
          CAST(staff_id.Phone1 AS NVARCHAR(4000)),
          CAST(staff_uid.Phone1 AS NVARCHAR(4000)),
          N''
        ))), N'') AS updated_by_phone,
        CAST(NULL AS NVARCHAR(MAX)) AS updated_by_roles
      FROM dbo.HWY_Members m WITH (NOLOCK)
      LEFT JOIN dbo.hwy_ref_base_information cr WITH (NOLOCK) ON cr.id = m.MembershipStatus_ChangeReasonId
      LEFT JOIN dbo.HWY_VW_Members_NoAdmin staff_un WITH (NOLOCK)
        ON staff_un.UserName = m.MembershipStatus_UpdatedBy
      LEFT JOIN dbo.HWY_Members staff_id WITH (NOLOCK)
        ON CAST(staff_id.Id AS VARCHAR(32)) = CAST(m.MembershipStatus_UpdatedBy AS VARCHAR(32))
      LEFT JOIN dbo.AppEnd_Users au WITH (NOLOCK)
        ON CAST(au.Id AS VARCHAR(32)) = CAST(m.MembershipStatus_UpdatedBy AS VARCHAR(32))
      LEFT JOIN dbo.HWY_Members staff_uid WITH (NOLOCK)
        ON staff_uid.UserId = au.Id
      WHERE m.Id IN (${inList})
    `)).recordset as LegacyRejectionListStatusRow[];

    for (const row of rows) {
      const memberId = trimNote(row.member_id);
      if (memberId) {
        result.set(memberId, row);
      }
    }
    return result;
  } finally {
    await pool.close();
  }
}

const REGION_RETURN_BADGE = 'معاد من مسؤول المنطقة';

export function applyLegacyRejectionListStatusFieldsToRow(
  row: Record<string, unknown>,
  legacy: LegacyRejectionListStatusRow,
  listScopeLegacy: HwyMemberRejectionListLegacyScope,
): void {
  const isLocalManage = listScopeLegacy === HWY_MEMBER_REJECTION_LIST_LEGACY_SCOPES.localManage;
  const statusNote = trimNote(legacy.status_note);
  const changeReasonTitle = trimNote(legacy.change_reason_title);
  const callCenterNote = trimNote(legacy.note_by_call_center);
  const latestNote = trimNote(legacy.latest_note);
  const hasChangeReasonId = legacy.change_reason_id != null && Number(legacy.change_reason_id) > 0;

  if (!String(row.membershipStatusUpdatedOn ?? '').trim() && legacy.status_updated_on) {
    row.membershipStatusUpdatedOn = legacy.status_updated_on;
  }

  if (!trimNote(String(row.membershipStatusNoteByCallCenter ?? '')) && callCenterNote) {
    row.membershipStatusNoteByCallCenter = callCenterNote;
  }
  if (!trimNote(String(row.membershipLatestNote ?? '')) && latestNote) {
    row.membershipLatestNote = latestNote;
  }

  const cpNote = trimNote(String(row.membershipStatusDecisionNote ?? ''));
  const cpReason = trimNote(String(row.membershipStatusDecisionReasonTitle ?? ''));

  if (hasChangeReasonId) {
    if (isLocalManage) {
      row.membershipStatusLegacyHasChangeReason = true;
      row.membershipStatusReturnedFromRegionBadge = REGION_RETURN_BADGE;
    }
    if (changeReasonTitle) {
      row.membershipStatusDecisionReasonTitle = changeReasonTitle;
    }
    if (statusNote && (!cpNote || statusNote.length >= cpNote.length)) {
      row.membershipStatusDecisionNote = statusNote;
    } else if (!cpNote && statusNote) {
      row.membershipStatusDecisionNote = statusNote;
    }
  } else if (!cpNote && !cpReason) {
    if (callCenterNote) {
      row.membershipStatusDecisionNote = callCenterNote;
    } else if (statusNote) {
      row.membershipStatusDecisionNote = statusNote;
    } else if (latestNote) {
      row.membershipStatusDecisionNote = latestNote;
    }
  } else if (!cpNote && statusNote) {
    row.membershipStatusDecisionNote = statusNote;
  }

  if (!trimNote(String(row.membershipStatusDecisionPreviousNote ?? '')) && latestNote
    && latestNote !== trimNote(String(row.membershipStatusDecisionNote ?? ''))
    && latestNote !== callCenterNote) {
    row.membershipStatusDecisionPreviousNote = latestNote;
  }

  const legacyLogin = trimNote(legacy.updated_by_username);
  const legacyDisplay = trimNote(legacy.updated_by_display_name);
  const legacyPhone = trimNote(legacy.updated_by_phone);
  const legacyStaffId = trimNote(legacy.updated_by_staff_member_id);
  const legacyRoles = trimNote(legacy.updated_by_roles);

  if (!trimNote(String(row.membershipStatusUpdatedByDisplayName ?? '')) && legacyDisplay) {
    row.membershipStatusUpdatedByDisplayName = legacyDisplay;
  } else if (!trimNote(String(row.membershipStatusUpdatedByDisplayName ?? '')) && legacyLogin) {
    row.membershipStatusUpdatedByDisplayName = legacyLogin;
  }
  if (!trimNote(String(row.membershipStatusUpdatedByLogin ?? '')) && legacyLogin) {
    row.membershipStatusUpdatedByLogin = legacyLogin;
  }
  if (!trimNote(String(row.membershipStatusUpdatedByPhone ?? '')) && legacyPhone) {
    row.membershipStatusUpdatedByPhone = legacyPhone;
  }
  if (!trimNote(String(row.membershipStatusUpdatedByStaffMemberId ?? '')) && legacyStaffId) {
    row.membershipStatusUpdatedByStaffMemberId = legacyStaffId;
  }
  if (!trimNote(String(row.membershipStatusUpdatedByRoles ?? '')) && legacyRoles) {
    row.membershipStatusUpdatedByRoles = legacyRoles;
  }
}

export async function attachLegacyRejectionListStatusFields(
  rows: Record<string, unknown>[],
  listScopeLegacy: HwyMemberRejectionListLegacyScope,
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  try {
    const memberIds = rows.map((row) => String(row.id ?? row.memberId ?? '').trim()).filter(Boolean);
    const legacyByMember = await queryLegacyRejectionListStatusFields(memberIds);
    for (const row of rows) {
      const memberId = String(row.id ?? row.memberId ?? '').trim();
      const legacy = legacyByMember.get(memberId);
      if (legacy) {
        applyLegacyRejectionListStatusFieldsToRow(row, legacy, listScopeLegacy);
      }
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.warn('[hwy-member-rejection-list] legacy status parity read failed.', message);
  }
}
