import fs from 'node:fs';
import path from 'node:path';

const LIST_FUNCTION_ID = 'vw-hwy-members.hwy-member-directory-list';
const GETONE_FUNCTION_ID = 'vw-hwy-members.hwy-member-directory-getone';
export const HWY_MEMBER_DIRECTORY_DATA_API_TIMEOUT_MS = 15_000;
const LIST_TIMEOUT_MS = HWY_MEMBER_DIRECTORY_DATA_API_TIMEOUT_MS;
const GETONE_TIMEOUT_MS = HWY_MEMBER_DIRECTORY_DATA_API_TIMEOUT_MS;
const LIST_CACHE_TTL_MS = 300_000;

/** Bump when list row shape / face-caption pipeline changes (invalidates built-in GET cache keys). */
export const HWY_MEMBER_DIRECTORY_LIST_BUILTIN_CACHE_GENERATION = 'rejection-list-rejected-by-v1';

const workspacePath = (...segments: string[]): string => (
  path.join(process.cwd(), ...segments)
);

const pinMemberDirectoryFunctionRuntime = (
  metadataRelativePath: string,
  timeoutMs: number,
  options?: { cacheTtlMs?: number; cacheByUser?: boolean },
): void => {
  const metadataPath = workspacePath(metadataRelativePath);
  if (!fs.existsSync(metadataPath)) {
    return;
  }
  const raw = JSON.parse(fs.readFileSync(metadataPath, 'utf8')) as Record<string, unknown>;
  raw.useGlobalConfig = false;
  raw.timeoutMs = timeoutMs;
  if (options?.cacheTtlMs != null) {
    raw.cacheTtlMs = options.cacheTtlMs;
  }
  if (options?.cacheByUser != null) {
    raw.cacheByUser = options.cacheByUser;
  }
  fs.writeFileSync(metadataPath, `${JSON.stringify(raw, null, 2)}\n`, 'utf8');
};

/** Member-directory list + dossier getOne exceed the 1.5s global server-function timeout. */
export function ensureHwyMemberDirectoryListRuntime(): void {
  pinMemberDirectoryFunctionRuntime(
    'workspace/server-functions/custom/vw-hwy-members.hwy-member-directory-list.metadata.json',
    LIST_TIMEOUT_MS,
    { cacheTtlMs: LIST_CACHE_TTL_MS, cacheByUser: true },
  );
  pinMemberDirectoryFunctionRuntime(
    'workspace/server-functions/custom/vw-hwy-members.hwy-member-directory-getone.metadata.json',
    GETONE_TIMEOUT_MS,
  );

  const edgeApiPath = workspacePath('workspace/edge-apis/ea_a140003600ded4e4.json');
  if (fs.existsSync(edgeApiPath)) {
    const edge = JSON.parse(fs.readFileSync(edgeApiPath, 'utf8')) as {
      runtime?: Record<string, unknown>;
    };
    edge.runtime = {
      ...edge.runtime,
      useGlobalConfig: false,
      timeoutMs: LIST_TIMEOUT_MS,
    };
    fs.writeFileSync(edgeApiPath, `${JSON.stringify(edge, null, 2)}\n`, 'utf8');
  }

  const indexPath = workspacePath('workspace/server-functions/index.json');
  if (fs.existsSync(indexPath)) {
    const index = JSON.parse(fs.readFileSync(indexPath, 'utf8')) as { updatedAt?: string };
    index.updatedAt = new Date().toISOString();
    fs.writeFileSync(indexPath, `${JSON.stringify(index, null, 2)}\n`, 'utf8');
  }
}

export const isHwyMemberDirectoryListFunctionId = (functionId: string): boolean => (
  functionId === LIST_FUNCTION_ID
);

export const isHwyMemberDirectoryGetOneFunctionId = (functionId: string): boolean => (
  functionId === GETONE_FUNCTION_ID
);

export const isHwyMemberDirectoryManagedFunctionId = (functionId: string): boolean => (
  isHwyMemberDirectoryListFunctionId(functionId) || isHwyMemberDirectoryGetOneFunctionId(functionId)
);
