/** Base Info category for legacy `NakhebCard_Front_TypeId` (parent 213925). */
export const HWY_VOTER_CARD_FRONT_TYPE_BASE_INFO_CATEGORY = 'Voter Card Front Type';

export const HWY_VOTER_CARD_FRONT_TYPE_SHORT_NAMES = [
  'unknown',
  'biometric',
  'fisheh',
] as const;

export type HwyVoterCardFrontTypeShortName = (typeof HWY_VOTER_CARD_FRONT_TYPE_SHORT_NAMES)[number];

export const isHwyVoterCardFrontTypeShortName = (
  value: string | null | undefined,
): value is HwyVoterCardFrontTypeShortName => (
  HWY_VOTER_CARD_FRONT_TYPE_SHORT_NAMES.includes(value as HwyVoterCardFrontTypeShortName)
);

/** Legacy Approve All default when voter front blob exists. */
export const HWY_VOTER_CARD_FRONT_TYPE_APPROVE_ALL_DEFAULT: HwyVoterCardFrontTypeShortName = 'biometric';
