import { QueryTypes } from 'sequelize';

import type { HwyGeoResponsibilityLevel } from '../../../domain/hwy/hwyGeoResponsibilityCatalog';
import type { HwyGeoResponsibilityCenterStats } from '../../../domain/hwy/hwyGeoResponsibility';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

const LEGACY_MEMBERSHIP_MONTADHEMIN = 10851;
const LEGACY_MEMBERSHIP_TOSIGH = 10853;
const LEGACY_GENDER_MALE = 10011;
const LEGACY_GENDER_FEMALE = 10012;

export type LegacyGeoPatchCenterStats = Pick<
  HwyGeoResponsibilityCenterStats,
  'montadheminCount' | 'tosighMaleCount' | 'tosighFemaleCount' | 'nakhebinCount' | 'totalMembers'
>;

const toCount = (value: unknown): number => {
  const parsed = Number(value ?? 0);
  return Number.isFinite(parsed) ? parsed : 0;
};

const legacyMemberFilterSql = (level: HwyGeoResponsibilityLevel, legacyGeoId: number): string => {
  const id = legacyGeoId;
  switch (level) {
    case 'province':
      return `M.NakhebJoinProvinceId = ${id}`;
    case 'ghavateh':
      return `M.NakhebJoinCircleId IN (
        SELECT GRC.CircleId FROM dbo.HWY_H_Ghavateh_R_Circles GRC WITH (NOLOCK)
        WHERE GRC.GhatehId = ${id}
      )`;
    case 'circle':
      return `M.NakhebJoinCircleId = ${id}`;
    case 'maktab':
      return `M.NakhebJoinTamvinId = ${id}`;
    case 'region':
      return `M.NakhebJoinEghteraId = ${id}`;
    default:
      return '1 = 0';
  }
};

const legacyNakhebinSql = (level: HwyGeoResponsibilityLevel, legacyGeoId: number): string => {
  const id = legacyGeoId;
  switch (level) {
    case 'province':
      return `
        COALESCE((
          SELECT TOP 1 H.Stat_NakhebinCount
          FROM dbo.HWY_H_Mohafezat H WITH (NOLOCK)
          WHERE H.HWY_StateId = ${id}
        ), (
          SELECT COUNT(*) FROM dbo.HWY_Nakhebin N WITH (NOLOCK)
          WHERE N.HWY_StateId = ${id}
        ))
      `;
    case 'ghavateh':
      return `
        COALESCE((
          SELECT TOP 1 H.Stat_NakhebinCount
          FROM dbo.HWY_H_Ghavateh H WITH (NOLOCK)
          WHERE H.GhatehId = ${id}
        ), (
          SELECT COUNT(*) FROM dbo.HWY_Nakhebin N WITH (NOLOCK)
          WHERE N.CircleId IN (
            SELECT GRC.CircleId FROM dbo.HWY_H_Ghavateh_R_Circles GRC WITH (NOLOCK)
            WHERE GRC.GhatehId = ${id}
          )
        ))
      `;
    case 'circle':
      return `
        COALESCE((
          SELECT TOP 1 H.stat_nakhebin_count
          FROM dbo.hwy_ref_h_circles H WITH (NOLOCK)
          WHERE H.circle_id = ${id}
        ), (
          SELECT COUNT(*) FROM dbo.HWY_Nakhebin N WITH (NOLOCK)
          WHERE N.CircleId = ${id}
        ))
      `;
    case 'maktab':
      return `
        COALESCE((
          SELECT TOP 1 H.stat_nakhebin_count
          FROM dbo.hwy_ref_h_tamvinat H WITH (NOLOCK)
          WHERE H.tamvin_id = ${id}
        ), (
          SELECT COUNT(*) FROM dbo.HWY_Nakhebin N WITH (NOLOCK)
          WHERE N.VRC_ID = ${id}
        ))
      `;
    case 'region':
      return `
        COALESCE((
          SELECT TOP 1 H.Stat_NakhebinCount
          FROM dbo.HWY_H_Eghteraat H WITH (NOLOCK)
          WHERE H.EghteraId = ${id}
        ), (
          SELECT COUNT(*) FROM dbo.HWY_Nakhebin N WITH (NOLOCK)
          WHERE N.PCNO = ${id}
        ))
      `;
    default:
      return '0';
  }
};

const legacyStatsSql = (level: HwyGeoResponsibilityLevel, legacyGeoId: number): string => {
  const memberGeo = legacyMemberFilterSql(level, legacyGeoId);
  const nakhebinExpr = legacyNakhebinSql(level, legacyGeoId);
  return `
    SELECT
      (
        SELECT COUNT(*)
        FROM dbo.HWY_Members M WITH (NOLOCK)
        WHERE M.MembershipStatus = ${LEGACY_MEMBERSHIP_MONTADHEMIN}
          AND ${memberGeo}
      ) AS montadheminCount,
      (
        SELECT COUNT(*)
        FROM dbo.HWY_Members M WITH (NOLOCK)
        WHERE M.MembershipStatus = ${LEGACY_MEMBERSHIP_TOSIGH}
          AND M.GenderId = ${LEGACY_GENDER_MALE}
          AND ${memberGeo}
      ) AS tosighMaleCount,
      (
        SELECT COUNT(*)
        FROM dbo.HWY_Members M WITH (NOLOCK)
        WHERE M.MembershipStatus = ${LEGACY_MEMBERSHIP_TOSIGH}
          AND M.GenderId = ${LEGACY_GENDER_FEMALE}
          AND ${memberGeo}
      ) AS tosighFemaleCount,
      (${nakhebinExpr}) AS nakhebinCount
  `;
};

export const controlPlaneHasLegacyHwyMembersTable = async (): Promise<boolean> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ object_id: number | null }>(
    `SELECT OBJECT_ID(N'dbo.HWY_Members', N'U') AS object_id`,
    { type: QueryTypes.SELECT },
  );
  return rows[0]?.object_id != null;
};

export const readLegacyGeoPatchCenterStats = async (input: {
  level: HwyGeoResponsibilityLevel;
  legacyGeoId: number;
}): Promise<LegacyGeoPatchCenterStats | null> => {
  if (!Number.isFinite(input.legacyGeoId) || input.legacyGeoId <= 0) {
    return null;
  }

  const runQuery = async (sql: string): Promise<LegacyGeoPatchCenterStats | null> => {
    const rows = await getControlPlaneSequelize().query<{
      montadheminCount: number | string;
      tosighMaleCount: number | string;
      tosighFemaleCount: number | string;
      nakhebinCount: number | string;
    }>(sql, { type: QueryTypes.SELECT });
    const row = rows[0];
    if (!row) {
      return null;
    }
    const montadheminCount = toCount(row.montadheminCount);
    return {
      montadheminCount,
      tosighMaleCount: toCount(row.tosighMaleCount),
      tosighFemaleCount: toCount(row.tosighFemaleCount),
      nakhebinCount: toCount(row.nakhebinCount),
      totalMembers: montadheminCount,
    };
  };

  const sql = legacyStatsSql(input.level, input.legacyGeoId);

  if (await controlPlaneHasLegacyHwyMembersTable()) {
    try {
      return await runQuery(sql);
    } catch {
      /* fall through to legacy pool */
    }
  }

  try {
    const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
    const pool = await connectLegacyReadPool();
    try {
      const result = await pool.request().query(sql);
      const row = result.recordset[0] as {
        montadheminCount: number | string;
        tosighMaleCount: number | string;
        tosighFemaleCount: number | string;
        nakhebinCount: number | string;
      } | undefined;
      if (!row) {
        return null;
      }
      const montadheminCount = toCount(row.montadheminCount);
      return {
        montadheminCount,
        tosighMaleCount: toCount(row.tosighMaleCount),
        tosighFemaleCount: toCount(row.tosighFemaleCount),
        nakhebinCount: toCount(row.nakhebinCount),
        totalMembers: montadheminCount,
      };
    } finally {
      await pool.close();
    }
  } catch {
    return null;
  }
};

export const resolveLegacyGeoIdForPatch = async (input: {
  level: HwyGeoResponsibilityLevel;
  geoBaseInfoId: string;
  legacyGeoId?: number | null;
}): Promise<number | null> => {
  if (input.legacyGeoId != null && Number.isFinite(input.legacyGeoId) && input.legacyGeoId > 0) {
    return input.legacyGeoId;
  }
  const kindByLevel: Record<HwyGeoResponsibilityLevel, string> = {
    province: 'province',
    ghavateh: 'ghavateh',
    circle: 'circle',
    maktab: 'maktab',
    region: 'region',
  };
  const legacyKind = kindByLevel[input.level];
  const rows = await getControlPlaneSequelize().query<{ legacy_id: number }>(
    `
    SELECT TOP 1 legacy_id
    FROM dbo.hwy_etl_geo_map
    WHERE base_info_id = :geoBaseInfoId
      AND legacy_kind = :legacyKind
    ORDER BY legacy_id ASC
    `,
    {
      replacements: { geoBaseInfoId: input.geoBaseInfoId, legacyKind },
      type: QueryTypes.SELECT,
    },
  );
  const legacyId = Number(rows[0]?.legacy_id);
  return Number.isFinite(legacyId) && legacyId > 0 ? legacyId : null;
};
