import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyCoursesActivitiesSchema } from './ensureHwyCoursesActivitiesSchema';
import { readHwyActivityAttendanceSelfieContent } from './hwyCoursesActivitiesAdmin.service';
import { resolveHwyMemberDirectoryMemberId } from './hwyMemberCoursesActivities.service';

export type HwyMemberNbSelfieHistoryRow = {
  sourceKind: 'Nashatat' | 'Payment';
  sourceTitle: string;
  recordId: string;
  detailTitle: string;
  eventDateTime: string;
  previewPath: string | null;
};

/** Activity attendances with selfie (legacy `Read_NbSelfiHistory_ByMemberId` Nashatat branch). Payment not ported yet. */
export async function listHwyMemberNbSelfieHistory(memberIdRaw: string): Promise<HwyMemberNbSelfieHistoryRow[]> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  await ensureHwyCoursesActivitiesSchema();
  const memberId = await resolveHwyMemberDirectoryMemberId(memberIdRaw);
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    id: number | string;
    activity_title: string | null;
    nb_device_datetime: string | null;
    created_at: Date | string;
    has_selfie: number;
  }>(
    `
    SELECT
      att.id,
      act.title AS activity_title,
      att.nb_device_datetime,
      att.created_at,
      CASE
        WHEN ISNULL(att.selfie_size_bytes, 0) > 0
          AND att.selfie_content IS NOT NULL
          AND DATALENGTH(att.selfie_content) > 0
        THEN 1
        ELSE 0
      END AS has_selfie
    FROM dbo.hwy_activity_attendances att
    INNER JOIN dbo.hwy_activities act ON act.id = att.activity_id
    WHERE att.member_id = :memberId
      AND ISNULL(att.selfie_size_bytes, 0) > 0
    ORDER BY
      COALESCE(TRY_CONVERT(DATETIME2, att.nb_device_datetime), att.created_at) DESC,
      att.id DESC
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );

  return rows
    .filter((row) => Number(row.has_selfie) === 1)
    .map((row) => {
      const recordId = String(row.id);
      return {
        sourceKind: 'Nashatat' as const,
        sourceTitle: 'Nashatat',
        recordId,
        detailTitle: row.activity_title?.trim() || '',
        eventDateTime: row.nb_device_datetime?.trim()
          || (row.created_at ? new Date(row.created_at).toISOString() : ''),
        previewPath: `/api/hwy/member-directory/${memberId}/activity-attendances/${encodeURIComponent(recordId)}/selfie`,
      };
    });
}

export async function readHwyMemberDirectoryActivityAttendanceSelfie(
  memberIdRaw: string,
  attendanceIdRaw: string,
): Promise<{ mime: string; fileName: string; buffer: Buffer }> {
  const memberId = await resolveHwyMemberDirectoryMemberId(memberIdRaw);
  const attendanceId = Number(String(attendanceIdRaw).trim());
  if (!Number.isFinite(attendanceId) || attendanceId <= 0) {
    throw new Error('Attendance not found.');
  }
  const sequelize = getControlPlaneSequelize();
  const ownerRows = await sequelize.query<{ member_id: number }>(
    `SELECT member_id FROM dbo.hwy_activity_attendances WHERE id = :attendanceId`,
    { replacements: { attendanceId }, type: QueryTypes.SELECT },
  );
  if (!ownerRows.length || Number(ownerRows[0].member_id) !== memberId) {
    throw new Error('Attendance not found.');
  }
  return readHwyActivityAttendanceSelfieContent(attendanceIdRaw);
}
