import { execHwyProcedure } from './hwyExecDbObject';

export type HwyLegacyOperatorGeoScope = {
  areaLimitId: number | null;
  geoLimitsCsv: string | null;
};

export const resolveHwyLegacyOperatorGeoScope = async (
  operatorUsername: string | null | undefined,
  roleNames: readonly string[],
): Promise<{ unrestricted: boolean } & HwyLegacyOperatorGeoScope> => {
  if (roleNames.includes('ADMIN')) {
    return { unrestricted: true, areaLimitId: null, geoLimitsCsv: null };
  }
  const username = String(operatorUsername ?? '').trim();
  if (!username) {
    return { unrestricted: false, areaLimitId: null, geoLimitsCsv: null };
  }

  const rows = await execHwyProcedure<{
    area_limit_id: number | string | null;
    geo_limits_csv: string | null;
  }>('hwy_legacy_operator_geo_scope', { username });

  const row = rows[0];
  return {
    unrestricted: false,
    areaLimitId: row?.area_limit_id != null ? Number(row.area_limit_id) : null,
    geoLimitsCsv: row?.geo_limits_csv ? String(row.geo_limits_csv) : null,
  };
};
