import { QueryTypes } from 'sequelize';

import {
  formatHwyMemberStatRecalcStepDisplayValue,
  type HwyMemberStatRow,
} from '../../../domain/hwy/hwyMemberStatRecalcDisplay';
import { hwyMemberStatRecalcStepById, type HwyMemberStatRecalcStepId } from '../../../domain/hwy/hwyMemberStatsRecalcCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import {
  resolveLegacyMemberStatRow,
  syncEdgeMemberStatsFromRow,
} from './hwyMemberStatsRecalcLegacy.service';

export type HwyMemberStatRecalcStepOutcome = {
  displayValue: string;
};

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Member stats recalc requires SQL Server control plane.');
  }
};

const readMemberStatRow = async (memberId: number): Promise<HwyMemberStatRow | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<HwyMemberStatRow>(
    `
    SELECT
      stat_fields_completed AS statFieldsCompleted,
      stat_days AS statDays,
      stat_dorat_count AS statDoratCount,
      stat_kasb_count AS statKasbCount,
      stat_nashatat_count AS statNashatatCount,
      stat_moassesat_count AS statMoassesatCount,
      stat_interviews_2022_count AS statInterviews2022Count,
      stat_cards_count AS statCardsCount,
      stat_has_passed_all AS statHasPassedAll,
      stat_has_not_tosigh_older_than_x_days AS statHasNotTosighOlderThanXDays,
      stat_vasaegh_count AS statVasaeghCount,
      stat_is_employee AS statIsEmployee,
      stat_adam_tatbigh_count AS statAdamTatbighCount,
      stat_points AS statPoints
    FROM dbo.hwy_members WITH (NOLOCK)
    WHERE id = :member_id
    `,
    { replacements: { member_id: memberId }, type: QueryTypes.SELECT },
  );
  return rows[0] ?? null;
};

export const runHwyMemberStatRecalcStep = async (
  memberId: string,
  stepId: HwyMemberStatRecalcStepId,
): Promise<HwyMemberStatRecalcStepOutcome> => {
  assertSqlServer();
  const step = hwyMemberStatRecalcStepById(stepId);
  if (!step) {
    throw new Error('Unknown stats recalc step.');
  }
  const numericId = Number(String(memberId ?? '').trim());
  if (!Number.isFinite(numericId) || numericId <= 0) {
    throw new Error('memberId is required.');
  }
  await ensureHwyDbObjects();

  if (stepId === 'profile_fields') {
    const legacyRow = await resolveLegacyMemberStatRow(numericId, true);
    if (legacyRow) {
      try {
        await syncEdgeMemberStatsFromRow(numericId, legacyRow);
      } catch (syncError) {
        console.warn(
          '[HWY member stats recalc] Legacy stat sync to edge failed; continuing with edge step SP.',
          syncError instanceof Error ? syncError.message : syncError,
        );
      }
    }
  }

  try {
    await execHwyProcedure(step.procedure, { member_id: numericId });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (/could not find stored procedure.*hwy_member_stat/i.test(message)) {
      throw new Error(
        'Member stats procedures are not installed on the control-plane database. Run npm run hwy:db-objects -- --force, then try again.',
        { cause: error },
      );
    }
    throw error;
  }

  const row = await readMemberStatRow(numericId);

  try {
    return {
      displayValue: formatHwyMemberStatRecalcStepDisplayValue(stepId, row),
    };
  } catch (readError) {
    const readMessage = readError instanceof Error ? readError.message : String(readError);
    throw new Error(`Stats were updated but could not be read back: ${readMessage}`, { cause: readError });
  }
};
