import type { HwyMemberSegmentListDefinition } from './hwyMemberSegmentListCatalog';
import {
  findHwyMemberSegmentListByLegacyCode,
  findHwyMemberSegmentListByPageName,
} from './hwyMemberSegmentListCatalog';
import {
  resolveHwyMemberInstituteCharacterVocab,
  type HwyMemberInstituteCharacterVocab,
} from './hwyMemberInstituteCharacterVocab';

/** Legacy list-only edit forms (`HWY_Members_Edit_By*` / `HWY_Members_Job_Edit`). */
export type HwyMemberListScopedEditKind = 'gov_employment' | 'mehani_professional' | 'institute_character';

export type HwyMemberListScopedEditProfile = {
  kind: HwyMemberListScopedEditKind;
  /** Grid column keys that open the scoped editor (legacy: click job / character cell). */
  triggerColumnKeys: readonly string[];
  /** Required when `kind` is `institute_character`. */
  instituteCode?: string;
  /** Per-institute character LOV + labels (legacy Edit_By* / list column headers). */
  instituteCharacterVocab?: HwyMemberInstituteCharacterVocab;
};

const GOV_EMPLOYMENT_TRIGGERS = ['jobTypeAndPlace'] as const;
const MEHANI_PROFESSIONAL_TRIGGERS = ['jobTypeAndPlace'] as const;
const CHARACTER_TRIGGERS = ['characterCodeTitle'] as const;

/** Per-segment list scoped edit (legacy `Update_By*` / `Update_Job` on list grids). */
export const HWY_MEMBER_LIST_SCOPED_EDIT_BY_LEGACY_CODE: Record<string, HwyMemberListScopedEditProfile> = {
  HWY_Members_List_AlMontadhemin_Gov: {
    kind: 'gov_employment',
    triggerColumnKeys: GOV_EMPLOYMENT_TRIGGERS,
  },
  HWY_Members_List_AlMontadhemin_Mehani: {
    kind: 'mehani_professional',
    instituteCode: 'mehani',
    triggerColumnKeys: MEHANI_PROFESSIONAL_TRIGGERS,
  },
  HWY_Members_List_Waited_2_Mehani: {
    kind: 'mehani_professional',
    instituteCode: 'mehani',
    triggerColumnKeys: MEHANI_PROFESSIONAL_TRIGGERS,
  },
  HWY_Members_List_AlMontadhemin_Ashaaer: {
    kind: 'institute_character',
    instituteCode: 'ashaaer',
    instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab('ashaaer') ?? undefined,
    triggerColumnKeys: CHARACTER_TRIGGERS,
  },
  HWY_Members_List_AlMontadhemin_Nokhab: {
    kind: 'institute_character',
    instituteCode: 'nokhab',
    instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab('nokhab') ?? undefined,
    triggerColumnKeys: CHARACTER_TRIGGERS,
  },
  HWY_Members_List_AlMontadhemin_Shabab: {
    kind: 'institute_character',
    instituteCode: 'shabab',
    instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab('shabab') ?? undefined,
    triggerColumnKeys: CHARACTER_TRIGGERS,
  },
  HWY_Members_List_Waited_2_Nokhab: {
    kind: 'institute_character',
    instituteCode: 'nokhab',
    instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab('nokhab') ?? undefined,
    triggerColumnKeys: CHARACTER_TRIGGERS,
  },
  HWY_Members_List_Waited_2_Shabab: {
    kind: 'institute_character',
    instituteCode: 'shabab',
    instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab('shabab') ?? undefined,
    triggerColumnKeys: CHARACTER_TRIGGERS,
  },
};

export const buildInstituteCharacterScopedEditProfile = (
  instituteCode: string,
): HwyMemberListScopedEditProfile => ({
  kind: 'institute_character',
  instituteCode,
  instituteCharacterVocab: resolveHwyMemberInstituteCharacterVocab(instituteCode) ?? undefined,
  triggerColumnKeys: CHARACTER_TRIGGERS,
});

export const resolveHwyMemberListScopedEditProfile = (
  listScopeLegacy: string | null | undefined,
): HwyMemberListScopedEditProfile | null => {
  const trimmed = String(listScopeLegacy ?? '').trim();
  if (!trimmed) {
    return null;
  }
  return HWY_MEMBER_LIST_SCOPED_EDIT_BY_LEGACY_CODE[trimmed] ?? null;
};

/** Institute-config driven scoped edit (legacy Update_By* on institute member lists). */
export const resolveHwyMemberListScopedEditProfileForListScope = (
  listScopeLegacy: string | null | undefined,
  instituteAllowsScopedEdit: ReadonlySet<string> | null | undefined,
): HwyMemberListScopedEditProfile | null => {
  const staticProfile = resolveHwyMemberListScopedEditProfile(listScopeLegacy);
  if (staticProfile) {
    return staticProfile;
  }
  const trimmed = String(listScopeLegacy ?? '').trim();
  if (!trimmed || !instituteAllowsScopedEdit?.size) {
    return null;
  }
  const definition = findHwyMemberSegmentListByLegacyCode(trimmed);
  const scope = definition?.scope;
  if (!scope || (scope.type !== 'active_institute' && scope.type !== 'pending_local_institute')) {
    return null;
  }
  const instituteCode = scope.instituteCode.trim().toLowerCase();
  if (!instituteAllowsScopedEdit.has(instituteCode)) {
    return null;
  }
  return buildInstituteCharacterScopedEditProfile(instituteCode);
};

export const segmentListHasScopedEdit = (
  definition: Pick<HwyMemberSegmentListDefinition, 'legacyCode'> | undefined,
): boolean => (
  definition != null && Boolean(HWY_MEMBER_LIST_SCOPED_EDIT_BY_LEGACY_CODE[definition.legacyCode])
);

export const listScopeLegacyNeedsInstituteCharacterColumn = (
  listScopeLegacy: string | null | undefined,
): boolean => {
  const profile = resolveHwyMemberListScopedEditProfile(listScopeLegacy);
  return profile?.kind === 'institute_character';
};

export const columnKeyTriggersListScopedEdit = (
  listScopeLegacy: string | null | undefined,
  columnKey: string,
): boolean => {
  const profile = resolveHwyMemberListScopedEditProfile(listScopeLegacy);
  if (!profile) {
    return false;
  }
  const key = columnKey.trim();
  return profile.triggerColumnKeys.some((trigger) => trigger === key);
};

export const findHwyMemberListScopedEditProfileForPage = (
  pageName: string,
): HwyMemberListScopedEditProfile | null => {
  const definition = findHwyMemberSegmentListByPageName(pageName);
  if (!definition) {
    return null;
  }
  return resolveHwyMemberListScopedEditProfile(definition.legacyCode);
};
