import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

/**
 * Legacy targhin nego uses `#CurrentUserName` / `$UserName$` — usually membership username,
 * sometimes numeric member id string when staff maps that way.
 */
export async function resolveHwyTarghinNegoActorLegacyUsername(
  actorUserId: number | null | undefined,
): Promise<string> {
  if (actorUserId == null || !Number.isFinite(actorUserId) || actorUserId <= 0) {
    return '';
  }
  const sequelize = getControlPlaneSequelize();
  const memberRows = await sequelize.query<{ username: string | null }>(
    `
    SELECT TOP 1 username
    FROM dbo.vw_hwy_members WITH (NOLOCK)
    WHERE user_id = :actorUserId
    `,
    { replacements: { actorUserId }, type: QueryTypes.SELECT },
  );
  const memberUsername = trim(memberRows[0]?.username);
  if (memberUsername) {
    return memberUsername;
  }
  const userRows = await sequelize.query<{ username: string | null }>(
    `SELECT username FROM dbo.base_users WHERE id = :actorUserId`,
    { replacements: { actorUserId }, type: QueryTypes.SELECT },
  );
  const baseUsername = trim(userRows[0]?.username);
  if (baseUsername) {
    return baseUsername;
  }
  return '';
}
