import { formatProfileDisplayName } from '../../shared/profile/profileDisplayName';

/** Single platform admin account (legacy had multiple staff labels for the same role). */
export const HWY_PLATFORM_ADMIN_USERNAME = 'admin';

export const HWY_PLATFORM_ADMIN_DISPLAY_NAME = formatProfileDisplayName({
  firstname: 'System',
  lastname: 'Administrator',
  companyName: null,
  personTypeCode: null,
}) || 'System Administrator';

const normalizeActorToken = (value: string): string => (
  value.trim().toLowerCase().replace(/[\s_.-]+/g, '')
);

const normalizeDisplayKey = (value: string): string => (
  value.trim().toLowerCase().replace(/\s*-\s*/g, ' ').replace(/\s+/g, ' ')
);

/** Legacy AppEnd staff username / actor key (admin, sys admin, …). */
export const isHwyLegacyPlatformAdminActorKey = (
  raw: string | number | null | undefined,
): boolean => {
  const token = normalizeActorToken(String(raw ?? ''));
  if (!token) {
    return false;
  }
  return token === 'admin' || token === 'sysadmin';
};

/** Legacy person-line labels that mean the platform admin, not a separate member. */
export const isHwyLegacyPlatformAdminActorDisplayName = (
  raw: string | null | undefined,
): boolean => {
  const key = normalizeDisplayKey(String(raw ?? ''));
  if (!key) {
    return false;
  }
  if (key === normalizeDisplayKey(HWY_PLATFORM_ADMIN_DISPLAY_NAME)) {
    return true;
  }
  return key === 'admin admin' || key === 'sys admin';
};

export const isHwyLegacyPlatformAdminActor = (input: {
  actorUsername?: string | null;
  actorDisplayName?: string | null;
  legacyActorKey?: string | null;
}): boolean => (
  isHwyLegacyPlatformAdminActorKey(input.actorUsername)
  || isHwyLegacyPlatformAdminActorKey(input.legacyActorKey)
  || isHwyLegacyPlatformAdminActorDisplayName(input.actorDisplayName)
);

/** Collapse legacy staff keys to the platform admin username for ETL storage. */
export const normalizeHwyLegacyPlatformAdminActorKey = (
  raw: string | number | null | undefined,
): string | null => {
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) {
    return null;
  }
  if (isHwyLegacyPlatformAdminActorKey(trimmed)) {
    return HWY_PLATFORM_ADMIN_USERNAME;
  }
  return trimmed;
};

export const normalizeHwyPlatformAdminActorFields = <T extends {
  actorDisplayName?: string | null;
  actorUsername?: string | null;
}>(fields: T): T => {
  if (!isHwyLegacyPlatformAdminActor(fields)) {
    return fields;
  }
  return {
    ...fields,
    actorUsername: HWY_PLATFORM_ADMIN_USERNAME,
    actorDisplayName: HWY_PLATFORM_ADMIN_DISPLAY_NAME,
  };
};
