import {
  connectLegacyReadPool,
  fetchLegacyPlatformRolesByAction,
} from '../../../../scripts/hwy-etl/legacyHwyRoleAuth';
import {
  buildHwyCandidatePipelinePortalAllowRoles,
  buildHwyCandidatePipelineStageAllowRoles,
  HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ,
} from '../../../domain/hwy/hwyCandidatePipelineLegacyAccess';
import type { HwyCandidatePipelineStage } from '../../../domain/hwy/hwyCandidatePipelineCatalog';
import { legacyHwyActionKey } from '../../../domain/hwy/hwyMemberListLegacyAccess';

const CACHE_MS = 30_000;
let portalRolesCache: { roles: string[]; loadedAt: number } | null = null;

const loadRolesByAction = async () => {
  const pool = await connectLegacyReadPool();
  try {
    return await fetchLegacyPlatformRolesByAction(
      pool,
      Object.values(HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ),
    );
  } finally {
    await pool.close();
  }
};

export async function resolveHwyCandidatePipelinePortalAllowRoles(): Promise<string[]> {
  const now = Date.now();
  if (portalRolesCache && now - portalRolesCache.loadedAt < CACHE_MS) {
    return portalRolesCache.roles;
  }
  try {
    const byAction = await loadRolesByAction();
    const roles = buildHwyCandidatePipelinePortalAllowRoles(byAction);
    portalRolesCache = { roles: roles.length > 0 ? roles : ['ADMIN'], loadedAt: now };
    return portalRolesCache.roles;
  } catch {
    return ['ADMIN'];
  }
}

export async function assertHwyCandidatePipelineStageAccess(
  stage: HwyCandidatePipelineStage,
  roleNames: readonly string[],
): Promise<void> {
  if (roleNames.includes('ADMIN')) return;
  try {
    const byAction = await loadRolesByAction();
    const allowed = buildHwyCandidatePipelineStageAllowRoles(stage, byAction);
    if (allowed.some((role) => roleNames.includes(role))) return;
  } catch {
    /* fall through */
  }
  const portal = await resolveHwyCandidatePipelinePortalAllowRoles();
  if (portal.some((role) => roleNames.includes(role))) return;
  throw new Error('Forbidden.');
}

export const hwyCandidatePipelineLegacyActionKeys = (): string[] =>
  Object.values(HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ).map((action) => legacyHwyActionKey(action));
