import { legacyHwyRoleIdToPlatformRoleName } from './hwyMemberListLegacyAccess';

/** Geographic levels for area-officials admin (legacy tree parity). */
export type HwyGeoResponsibilityLevel =
  | 'province'
  | 'ghavateh'
  | 'circle'
  | 'maktab'
  | 'region';

export type HwyGeoResponsibilityRoleSpec = {
  level: HwyGeoResponsibilityLevel;
  /** ETL map `legacy_kind` for listing nodes. */
  geoMapKind: 'province' | 'ghavateh' | 'circle' | 'maktab' | 'region';
  /** Platform role granted on approval. */
  roleName: string;
  legacyRoleId: number;
  /** Roles that may submit nominations at this level (ADMIN always allowed). */
  legacyNominateRoleIds: number[];
  /** Roles that may approve nominations (ADMIN always allowed). */
  legacyApproveRoleIds: number[];
  labelKey: string;
};

export const HWY_GEO_RESPONSIBILITY_LEVELS: HwyGeoResponsibilityLevel[] = [
  'province',
  'ghavateh',
  'circle',
  'maktab',
  'region',
];

const APPROVER_ROLE_IDS = [1000047, 1000040, 1000013] as const;

export const HWY_GEO_RESPONSIBILITY_ROLES: HwyGeoResponsibilityRoleSpec[] = [
  {
    level: 'province',
    geoMapKind: 'province',
    legacyRoleId: 1000003,
    roleName: legacyHwyRoleIdToPlatformRoleName(1000003),
    legacyNominateRoleIds: [1000003, 1000000, 1000001, ...APPROVER_ROLE_IDS],
    legacyApproveRoleIds: [...APPROVER_ROLE_IDS],
    labelKey: 'hwy.geoResponsibility.level.province',
  },
  {
    level: 'ghavateh',
    geoMapKind: 'ghavateh',
    legacyRoleId: 1000047,
    roleName: legacyHwyRoleIdToPlatformRoleName(1000047),
    legacyNominateRoleIds: [1000047, ...APPROVER_ROLE_IDS],
    legacyApproveRoleIds: [...APPROVER_ROLE_IDS],
    labelKey: 'hwy.geoResponsibility.level.ghavateh',
  },
  {
    level: 'circle',
    geoMapKind: 'circle',
    legacyRoleId: 1000027,
    roleName: legacyHwyRoleIdToPlatformRoleName(1000027),
    legacyNominateRoleIds: [1000027, ...APPROVER_ROLE_IDS],
    legacyApproveRoleIds: [...APPROVER_ROLE_IDS],
    labelKey: 'hwy.geoResponsibility.level.circle',
  },
  {
    level: 'maktab',
    geoMapKind: 'maktab',
    legacyRoleId: 1000004,
    roleName: legacyHwyRoleIdToPlatformRoleName(1000004),
    legacyNominateRoleIds: [1000004, ...APPROVER_ROLE_IDS],
    legacyApproveRoleIds: [...APPROVER_ROLE_IDS],
    labelKey: 'hwy.geoResponsibility.level.maktab',
  },
  {
    level: 'region',
    geoMapKind: 'region',
    legacyRoleId: 1000005,
    roleName: legacyHwyRoleIdToPlatformRoleName(1000005),
    legacyNominateRoleIds: [1000005, ...APPROVER_ROLE_IDS],
    legacyApproveRoleIds: [...APPROVER_ROLE_IDS],
    labelKey: 'hwy.geoResponsibility.level.region',
  },
];

export const findHwyGeoResponsibilityRoleSpec = (
  level: HwyGeoResponsibilityLevel,
): HwyGeoResponsibilityRoleSpec | undefined => (
  HWY_GEO_RESPONSIBILITY_ROLES.find((row) => row.level === level)
);

export const findHwyGeoResponsibilityRoleSpecByRoleName = (
  roleName: string,
): HwyGeoResponsibilityRoleSpec | undefined => {
  const trimmed = String(roleName ?? '').trim();
  if (!trimmed) {
    return undefined;
  }
  return HWY_GEO_RESPONSIBILITY_ROLES.find((row) => row.roleName === trimmed);
};

export const hwyGeoResponsibilityPatchRoleNames = (): string[] => (
  HWY_GEO_RESPONSIBILITY_ROLES.map((row) => row.roleName)
);

export const hwyGeoResponsibilityNominateRoleNames = (): string[] => {
  const ids = new Set<number>();
  for (const spec of HWY_GEO_RESPONSIBILITY_ROLES) {
    for (const id of spec.legacyNominateRoleIds) {
      ids.add(id);
    }
  }
  return [...ids].map((id) => legacyHwyRoleIdToPlatformRoleName(id));
};

export const hwyGeoResponsibilityApproveRoleNames = (): string[] => {
  const ids = new Set<number>();
  for (const spec of HWY_GEO_RESPONSIBILITY_ROLES) {
    for (const id of spec.legacyApproveRoleIds) {
      ids.add(id);
    }
  }
  return [...ids].map((id) => legacyHwyRoleIdToPlatformRoleName(id));
};

export const hwyGeoResponsibilityAllGateRoleNames = (): string[] => {
  const set = new Set<string>([
    ...hwyGeoResponsibilityNominateRoleNames(),
    ...hwyGeoResponsibilityApproveRoleNames(),
  ]);
  return [...set];
};

/** Anyone who may open the geo-responsibility route binding (read lists). */
export const hwyGeoResponsibilityCanAccessSection = (
  roleNames: readonly string[],
): boolean => {
  if (roleNames.includes('ADMIN')) {
    return true;
  }
  const gate = hwyGeoResponsibilityAllGateRoleNames();
  return roleNames.some((role) => gate.includes(role));
};

export const isHwyGeoResponsibilityLevel = (
  value: string,
): value is HwyGeoResponsibilityLevel => (
  HWY_GEO_RESPONSIBILITY_LEVELS.includes(value as HwyGeoResponsibilityLevel)
);

