const trimLegacyText = (value: unknown, max?: number): string | null => {
  if (value == null) return null;
  const s = String(value).trim();
  if (!s) return null;
  return max && s.length > max ? s.slice(0, max) : s;
};

/**
 * Legacy membership number: assigned `UserName` when active; pending rows use `TrackingCode`.
 * Matches Hawiety list column «رقم الانتماء» — never synthesize `m{memberId}`.
 */
export const resolveLegacyMemberUsername = (input: {
  memberId: number;
  userName?: unknown;
  trackingCode?: unknown;
}): string | null => {
  const fromUserName = trimLegacyText(input.userName, 1000);
  if (fromUserName) return fromUserName;
  const fromTracking = trimLegacyText(input.trackingCode, 1000);
  if (fromTracking) return fromTracking;
  return null;
};

