import { resolveGeoPlaceholderDisplayTitle } from '../../../shared/lib/baseInfoGeoPlaceholderTitle';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { applyHwyNakhebinVoterNameDisplayLines } from '../../../shared/lib/hwyNakhebinVoterDisplay';
import { computeDisplayTitlePathsForCulture } from '../base-info/baseInfoPathResolve';
import { buildMergedCultureBundle } from '../base-info/baseInfoCultureTranslationStore';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { prisma } from '../users/prismaHelpers';
import {
  loadHwyEtlGeoBaseInfoIdMap,
  resolveHwyEtlGeoBaseInfoId,
} from './hwyEtlGeoMapRepository';
import { resolveHwyLegacyGenderBaseInfoId } from './hwyLegacyVocabMaps';
import { attachNakhebinRegisteredCaseTitles } from './hwyFamilyHouseholdMemberCardStatus';
import { attachNakhebinLinkedMemberDisplay } from './hwyNakhebinLinkedMemberDisplay';

const HWY_REGION_SHORT_PREFIX = 'hwy-region-';

const readStringField = (row: Record<string, unknown>, field: string): string => {
  const snake = field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`);
  const raw = row[field] ?? row[snake];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

const isHierarchicalBaseInfoId = (value: string): boolean => /^\d+(?:\.\d+)+$/.test(value);

const resolveRegionBaseInfoIdsBatch = async (
  regionRefs: string[],
  geoMap: Map<string, string>,
): Promise<Map<string, string>> => {
  const resolved = new Map<string, string>();
  const hierarchicalIds: string[] = [];
  const shortNameLookups: string[] = [];

  for (const regionRef of regionRefs) {
    if (!regionRef) {
      continue;
    }
    if (isHierarchicalBaseInfoId(regionRef)) {
      hierarchicalIds.push(regionRef);
      continue;
    }
    const fromEtl = resolveHwyEtlGeoBaseInfoId(geoMap, 'region', regionRef, 0);
    if (fromEtl) {
      resolved.set(regionRef, fromEtl);
      continue;
    }
    shortNameLookups.push(`${HWY_REGION_SHORT_PREFIX}${regionRef}`);
  }

  if (hierarchicalIds.length > 0) {
    const existing = await prisma().baseInfo.findMany({
      where: { id: { in: hierarchicalIds } },
      select: { id: true },
    });
    const existingSet = new Set(existing.map((row) => row.id));
    for (const id of hierarchicalIds) {
      if (existingSet.has(id)) {
        resolved.set(id, id);
      }
    }
  }

  if (shortNameLookups.length > 0) {
    const byShortName = await prisma().baseInfo.findMany({
      where: { shortName: { in: shortNameLookups } },
      select: { id: true, shortName: true },
    });
    const idByShortName = new Map(
      byShortName.map((row) => [String(row.shortName ?? '').trim(), String(row.id ?? '').trim()]),
    );
    for (const regionRef of regionRefs) {
      if (resolved.has(regionRef) || !regionRef || isHierarchicalBaseInfoId(regionRef)) {
        continue;
      }
      const shortName = `${HWY_REGION_SHORT_PREFIX}${regionRef}`;
      const id = idByShortName.get(shortName);
      if (id) {
        resolved.set(regionRef, id);
      }
    }
  }

  return resolved;
};

const attachGenderTitles = async (
  rows: Record<string, unknown>[],
  cultureId: string,
): Promise<void> => {
  const resolvedIds = new Map<string, string>();
  for (const row of rows) {
    const raw = readStringField(row, 'genderCode');
    if (!raw) {
      continue;
    }
    const baseInfoId = resolveHwyLegacyGenderBaseInfoId(raw) ?? raw;
    resolvedIds.set(raw, baseInfoId);
  }

  const uniqueIds = [...new Set(resolvedIds.values())].filter(Boolean);
  const titleById = new Map<string, string>();
  if (uniqueIds.length > 0) {
    const enriched = await listBaseInfoEnrichmentRowsByIds(uniqueIds, cultureId);
    for (const item of enriched) {
      const id = String(item.id ?? '').trim();
      const title = String(item.title ?? '').trim();
      if (id && title) {
        titleById.set(id, title);
      }
    }
  }

  for (const row of rows) {
    const raw = readStringField(row, 'genderCode');
    if (!raw) {
      continue;
    }
    const baseInfoId = resolvedIds.get(raw) ?? raw;
    const title = titleById.get(baseInfoId);
    if (title) {
      row.genderCodeTitle = title;
      continue;
    }
    row.genderCodeTitle = raw;
  }
};

export const attachHwyRegionElectoralPathsByRegionId = async (
  rows: Record<string, unknown>[],
  cultureId: string,
  geoMap: Map<string, string>,
): Promise<void> => {
  const uniqueRefs = [...new Set(rows.map((row) => readStringField(row, 'regionId')).filter(Boolean))];
  const refToBaseInfoId = await resolveRegionBaseInfoIdsBatch(uniqueRefs, geoMap);

  const baseInfoIds = [...new Set(refToBaseInfoId.values())];
  const bundle = buildMergedCultureBundle(cultureId);
  const titlePathById = baseInfoIds.length > 0
    ? await computeDisplayTitlePathsForCulture(baseInfoIds, cultureId, bundle)
    : new Map<string, string>();

  const enriched = baseInfoIds.length > 0
    ? await listBaseInfoEnrichmentRowsByIds(baseInfoIds, cultureId)
    : [];
  const labelById = new Map<string, string>();
  for (const row of enriched) {
    const id = String(row.id ?? '').trim();
    const label = String(row.title ?? '').trim();
    if (id && label) {
      labelById.set(id, label);
    }
  }

  for (const row of rows) {
    const ref = readStringField(row, 'regionId');
    if (!ref) {
      continue;
    }

    const baseInfoId = refToBaseInfoId.get(ref);
    if (baseInfoId) {
      const path = titlePathById.get(baseInfoId)?.trim()
        || labelById.get(baseInfoId)?.trim();
      if (path) {
        row.electoralDivisionPath = path;
        continue;
      }
    }

    const placeholder = resolveGeoPlaceholderDisplayTitle(
      cultureId,
      `${HWY_REGION_SHORT_PREFIX}${ref}`,
    );
    if (placeholder) {
      row.electoralDivisionPath = placeholder;
      continue;
    }

    row.electoralDivisionPath = ref;
  }
};

/** Resolves `genderCode` → `genderCodeTitle` for nakhebin or member-directory rows. */
export async function enrichHwyGenderCodeTitles(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  const cultureId = resolveBaseInfoCultureId(queryLang);
  await attachGenderTitles(rows, cultureId);
}

/** Base Info labels for nakhebin list (gender title + region electoral path). */
export async function enrichHwyNakhebinListRows(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
  for (const row of rows) {
    applyHwyNakhebinVoterNameDisplayLines(row);
  }
  await enrichHwyGenderCodeTitles(rows, queryLang);
  await attachHwyRegionElectoralPathsByRegionId(rows, cultureId, geoMap);
  await attachNakhebinRegisteredCaseTitles(rows, queryLang);
  await attachNakhebinLinkedMemberDisplay(rows);
}

/** @deprecated Use enrichHwyNakhebinListRows */
export async function attachHwyNakhebinElectoralDivisionPaths(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  await enrichHwyNakhebinListRows(rows, queryLang);
}
