import { QueryTypes } from 'sequelize';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG } from '../../../domain/hwy/hwyMemberFileKindCatalog';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';

export type HwyMemberSingleViewStatsRow = {
  statNashatatCount: number;
  statDoratCount: number;
  statMoassesatCount: number;
  statVasaeghCount: number;
  statAdamTatbighCount: number;
  statFieldsCompleted: number;
};

const emptyStats = (): HwyMemberSingleViewStatsRow => ({
  statNashatatCount: 0,
  statDoratCount: 0,
  statMoassesatCount: 0,
  statVasaeghCount: 0,
  statAdamTatbighCount: 0,
  statFieldsCompleted: 0,
});

const readCount = (value: unknown): number => {
  const n = Number(value ?? 0);
  return Number.isFinite(n) && n > 0 ? n : 0;
};

/** Batch stats for legacy SingleView grid columns (display-only; no dossier actions). */
export async function loadHwyMemberSingleViewStatsByMemberId(
  memberIds: readonly string[],
): Promise<Map<string, HwyMemberSingleViewStatsRow>> {
  const result = new Map<string, HwyMemberSingleViewStatsRow>();
  if (memberIds.length === 0 || readControlPlaneProvider() !== 'sqlserver') {
    return result;
  }

  const numericIds = memberIds
    .map((id) => Number(id.trim()))
    .filter((id) => Number.isFinite(id) && id > 0);
  if (numericIds.length === 0) {
    return result;
  }

  const profilePhotoKindId = await tryFindHwyBaseInfoItemIdByShortName(
    'Member File Kind',
    HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG,
  );
  const profilePhotoKindCode = profilePhotoKindId ? String(profilePhotoKindId) : null;

  const sequelize = getControlPlaneSequelize();
  const profileKindFilter = profilePhotoKindCode
    ? `AND ISNULL(bk.short_name, N'') <> :profilePhotoKindSlug`
    : '';
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      CAST(m.id AS VARCHAR(32)) AS memberId,
      (SELECT COUNT(*) FROM dbo.hwy_activity_attendances a WHERE a.member_id = m.id) AS statNashatatCount,
      (SELECT COUNT(*) FROM dbo.hwy_course_attendances c WHERE c.member_id = m.id) AS statDoratCount,
      (
        SELECT COUNT(*)
        FROM dbo.hwy_member_institutes mi
        WHERE mi.member_id = m.id
          AND NOT (
            ISNULL(mi.member_accepted, 0) = 0
            AND mi.join_path_code IN (
              SELECT bi.id
              FROM dbo.base_info bi
              INNER JOIN dbo.base_info cat ON cat.id = bi.parent_id
              WHERE cat.title = N'Institute Join Path' AND bi.short_name = N'invite'
            )
          )
      ) AS statMoassesatCount,
      (
        SELECT COUNT(*)
        FROM dbo.hwy_member_files f
        LEFT JOIN dbo.base_info bk ON bk.id = f.file_kind_code
        WHERE f.member_id = m.id
          ${profileKindFilter}
      ) AS statVasaeghCount
    FROM dbo.hwy_members m
    WHERE m.id IN (:memberIds)
    `,
    {
      replacements: {
        memberIds: numericIds,
        ...(profilePhotoKindCode
          ? { profilePhotoKindSlug: HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG }
          : {}),
      },
      type: QueryTypes.SELECT,
    },
  );

  for (const row of rows) {
    const memberId = String(row.memberId ?? '').trim();
    if (!memberId) {
      continue;
    }
    result.set(memberId, {
      ...emptyStats(),
      statNashatatCount: readCount(row.statNashatatCount),
      statDoratCount: readCount(row.statDoratCount),
      statMoassesatCount: readCount(row.statMoassesatCount),
      statVasaeghCount: readCount(row.statVasaeghCount),
    });
  }
  for (const id of memberIds) {
    const key = id.trim();
    if (key && !result.has(key)) {
      result.set(key, emptyStats());
    }
  }
  return result;
}

export async function attachHwyMemberSingleViewStatsToListRows(
  rows: Record<string, unknown>[],
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  const memberIds = rows
    .map((row) => String(row.id ?? '').trim())
    .filter(Boolean);
  const statsByMember = await loadHwyMemberSingleViewStatsByMemberId(memberIds);
  for (const row of rows) {
    const memberId = String(row.id ?? '').trim();
    const stats = statsByMember.get(memberId) ?? emptyStats();
    Object.assign(row, stats);
  }
}
