import type { ParsedHwySubmissionMetadata } from './hwySubmissionMetadata';

const trim = (value: unknown): string => String(value ?? '').trim();

/** Map platform `X-AppEndO-Client` claimed fields onto legacy Nb* attendance columns when omitted. */
export const enrichHwySubmissionMetadataFromClientClaimed = (
  payload: ParsedHwySubmissionMetadata,
  claimed: Record<string, unknown>,
): ParsedHwySubmissionMetadata => {
  const next: ParsedHwySubmissionMetadata = { ...payload };

  if (!next.nbDeviceOs) {
    const osName = trim(claimed.osName);
    const osVersion = trim(claimed.osVersion);
    if (osName && osVersion) {
      next.nbDeviceOs = `${osName} ${osVersion}`.slice(0, 128);
    } else if (osName) {
      next.nbDeviceOs = osName.slice(0, 128);
    } else if (typeof claimed.ext === 'object' && claimed.ext != null) {
      const ua = trim((claimed.ext as Record<string, unknown>).userAgent);
      if (ua) {
        next.nbDeviceOs = ua.slice(0, 128);
      }
    }
  }

  if (!next.nbDeviceId) {
    next.nbDeviceId = trim(claimed.installId) || trim(claimed.vendorId) || null;
    if (next.nbDeviceId) {
      next.nbDeviceId = next.nbDeviceId.slice(0, 128);
    }
  }

  if (!next.nbDeviceDatetime) {
    const clientAt = trim(claimed.clientOccurredAt);
    next.nbDeviceDatetime = clientAt ? clientAt.slice(0, 32) : null;
  }

  const location = claimed.location;
  if (location && typeof location === 'object' && !Array.isArray(location)) {
    const loc = location as Record<string, unknown>;
    if (!next.nbLocationLat && loc.lat != null) {
      next.nbLocationLat = trim(loc.lat).slice(0, 128);
    }
    if (!next.nbLocationLon && loc.lng != null) {
      next.nbLocationLon = trim(loc.lng).slice(0, 128);
    }
  }

  return next;
};
