import type { HwyMemberDossierChangeLogEvent } from './hwyMemberDossierChangeLog';
import type { HwyMemberDossierLabels } from './hwyMemberDossierLabels';

export type HwyMemberDossierChangeLogMemberActorFallback = {
  createdBy?: string | null;
  updatedBy?: string | null;
};

const hasChangeLogActorIdentity = (event: Pick<HwyMemberDossierChangeLogEvent, 'actorUserId' | 'actorDisplayName'>): boolean =>
  Boolean(event.actorUserId?.trim() || event.actorDisplayName?.trim());

/** Fill missing actorUserId from member audit columns and event kind (before identity lookup). */
export function applyHwyMemberDossierChangeLogMemberActorFallback(
  events: HwyMemberDossierChangeLogEvent[],
  memberActors: HwyMemberDossierChangeLogMemberActorFallback,
): void {
  const createdBy = memberActors.createdBy?.trim() || '';
  const updatedBy = memberActors.updatedBy?.trim() || '';

  for (const event of events) {
    if (hasChangeLogActorIdentity(event)) {
      continue;
    }

    if (event.kind === 'member.updated' || event.kind === 'member.statusChanged' || event.kind === 'file.updated') {
      if (updatedBy) {
        event.actorUserId = updatedBy;
      } else if (createdBy) {
        event.actorUserId = createdBy;
      }
      continue;
    }

    if (createdBy) {
      event.actorUserId = createdBy;
    } else if (updatedBy) {
      event.actorUserId = updatedBy;
    }
  }
}

export function resolveHwyMemberDossierChangeLogActorLabel(
  event: Pick<HwyMemberDossierChangeLogEvent, 'actorDisplayName' | 'actorUsername' | 'actorUserId'>,
  labels: Pick<HwyMemberDossierLabels, 'changeLogActorSystem' | 'emptyValue'>,
): string {
  const displayName = event.actorDisplayName?.trim();
  if (displayName) {
    return displayName;
  }
  const username = event.actorUsername?.trim();
  if (username) {
    return username;
  }
  const userId = event.actorUserId?.trim();
  if (userId) {
    return `#${userId}`;
  }
  return labels.changeLogActorSystem;
}
