const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;
const FINAL_NOTE_MAX_LENGTH = 1024;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Targhin request administration requires SQL Server control plane.');
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return {
    page: safePage,
    pageSize: safePageSize,
    offset: (safePage - 1) * safePageSize,
  };
};

type RawTarghinAdminRow = Record<string, unknown>;

const mapMemberFace = (row: RawTarghinAdminRow, prefix: string): HwyMemberTarghinAdminRow['member'] => {
  const id = trim(row[`${prefix}Id`] as string | undefined);
  if (!id) {
    return {
      id: '',
      username: null,
      displayFullName: null,
      genderCode: null,
      avatarUrl: null,
      phone: null,
      electoralDivisionPath: null,
    };
  }
  return {
    id,
    username: trim(row[`${prefix}Username`] as string | undefined) || null,
    displayFullName: formatHwyMemberPersonDisplayName(
      trim(row[`${prefix}DisplayFullName`] as string | undefined),
    ) || null,
    genderCode: trim(row[`${prefix}GenderCode`] as string | undefined) || null,
    avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
      avatarUrl: trim(row[`${prefix}AvatarUrl`] as string | undefined) || null,
      hasProfileImage: row[`${prefix}HasProfileImage`] === true || row[`${prefix}HasProfileImage`] === 1,
      userId: row[`${prefix}UserId`] != null ? Number(row[`${prefix}UserId`]) : null,
    }),
    phone: trim(row[`${prefix}Phone`] as string | undefined) || null,
    electoralDivisionPath: trim(row[`${prefix}ElectoralDivisionPath`] as string | undefined) || null,
  };
};

const mapRequesterFace = (row: RawTarghinAdminRow): HwyMemberTarghinAdminRow['requester'] => {
  const fromMember = mapMemberFace(row, 'requester');
  if (fromMember.id) {
    return fromMember;
  }
  const accountUserId = trim(row.requesterAccountUserId as string | undefined);
  const accountUsername = trim(row.requesterAccountUsername as string | undefined);
  if (!accountUserId && !accountUsername) {
    return null;
  }
  return {
    id: accountUserId ? `user-${accountUserId}` : accountUsername,
    username: accountUsername || null,
    displayFullName: accountUsername || null,
    genderCode: null,
    avatarUrl: accountUserId
      ? resolveHwyGeoResponsibilityAvatarUrl({
        avatarUrl: null,
        hasProfileImage: false,
        userId: Number(accountUserId),
      })
      : null,
    phone: null,
    electoralDivisionPath: null,
  };
};

const mapAdminRow = (
  row: RawTarghinAdminRow,
  viewerNegoActorLegacy: string,
): HwyMemberTarghinAdminRow => {
  const member = mapMemberFace(row, 'member');
  const deciderId = trim(row.deciderId as string | undefined);
  const lastNegoNoteWriterLegacy = trim(row.lastNegoNoteWriterLegacy as string | undefined) || null;
  return {
    id: trim(row.id as string | undefined),
    memberId: member.id,
    member,
    requestReasonCode: trim(row.requestReasonCode as string | undefined) || null,
    requestReasonCodeTitle: trim(row.requestReasonCodeTitle as string | undefined) || undefined,
    requestNote: trim(row.requestNote as string | undefined) || null,
    createdAt: String(row.createdAt ?? ''),
    statusCode: trim(row.statusCode as string | undefined),
    requester: mapRequesterFace(row),
    requesterMemberId: null,
    finalReasonCode: trim(row.finalReasonCode as string | undefined) || null,
    finalReasonCodeTitle: trim(row.finalReasonCodeTitle as string | undefined) || undefined,
    finalNote: trim(row.finalNote as string | undefined) || null,
    finalAt: row.finalAt ? String(row.finalAt) : null,
    decider: deciderId ? mapMemberFace(row, 'decider') : null,
    deciderMemberId: null,
    lastNegoNote: trim(row.lastNegoNote as string | undefined) || null,
    lastNegoNoteWriterLegacy,
    lastNegoNoteIsByViewer: Boolean(
      lastNegoNoteWriterLegacy
      && viewerNegoActorLegacy
      && lastNegoNoteWriterLegacy === viewerNegoActorLegacy,
    ),
    negoNoteCount: Math.max(
      0,
      Number(
        row.negoNoteCount
        ?? row.NegoNoteCount
        ?? (row as { negonotecount?: unknown }).negonotecount
        ?? 0,
      ),
    ),
  };
};

export const listHwyMemberTarghinAdmin = async (
  input: {
    queue?: HwyMemberTarghinAdminQueue;
    negoState?: HwyMemberTarghinNegoStateFilter;
    search?: string;
    page?: number;
    pageSize?: number;
    actorUserId?: number | null;
  },
  queryLang = 'ar',
): Promise<HwyMemberTarghinAdminListResult> => {
  await assertSqlServer();
  const queue = input.queue ?? 'pending';
  const negoState = input.negoState ?? '';
  const viewerNegoActorLegacy = await resolveHwyTarghinNegoActorLegacyUsername(input.actorUserId ?? null);
  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);
  const statusCode = queue === 'pending'
    ? HWY_MEMBER_TARGHIN_REQUEST_STATUS.pending
    : queue === 'approved'
      ? HWY_MEMBER_TARGHIN_REQUEST_STATUS.approved
      : queue === 'rejected'
        ? HWY_MEMBER_TARGHIN_REQUEST_STATUS.rejected
        : null;
  const search = trim(input.search);
  const procArgs = {
    status_code: statusCode,
    nego_state: negoState || null,
    search_like: search ? `%${search}%` : null,
    nego_actor_legacy: viewerNegoActorLegacy || null,
  };

  const countRows = await execHwyProcedure<{ total: number | string }>('hwy_targhin_admin_count', procArgs);
  const total = Number(countRows[0]?.total ?? 0);

  const rawRows = await execHwyProcedure<RawTarghinAdminRow>('hwy_targhin_admin_list', {
    ...procArgs,
    offset,
    page_size: pageSize,
  });

  const lang = resolveHwyMemberDirectoryDetailLang(queryLang);
  await attachBaseInfoTitles(
    rawRows,
    [
      { codeField: 'requestReasonCode', titleField: 'requestReasonCodeTitle' },
      { codeField: 'finalReasonCode', titleField: 'finalReasonCodeTitle' },
    ],
    lang,
  );

  const mapped = rawRows.map((row) => mapAdminRow(row, viewerNegoActorLegacy)).filter((row) => row.id && row.memberId);
  const faceEnrich = mapped.map((row) => ({
    memberId: row.memberId,
    avatarUrl: row.member.avatarUrl,
  }));
  await enrichMemberDirectoryFaceAvatarsByMemberId(faceEnrich);
  for (let i = 0; i < mapped.length; i += 1) {
    const url = faceEnrich[i]?.avatarUrl;
    if (url) {
      mapped[i]!.member.avatarUrl = url;
    }
  }

  await attachHwyMemberTarghinAdminRequesters(mapped);

  const linkedFacesNeedDossierResolve = mapped.some(
    (row) => (
      (row.requester && !resolveHwyMemberTarghinAdminFaceDossierMemberId(row.requester))
      || (row.decider && !resolveHwyMemberTarghinAdminFaceDossierMemberId(row.decider))
    ),
  );
  if (linkedFacesNeedDossierResolve) {
    await finalizeTarghinMemberFacesForDossier(
      mapped,
      (row) => row.decider,
      (row, face) => { row.decider = face; },
    );

    await hydrateTarghinFacesForDossierLinks(
      mapped.flatMap((row) => [row.requester, row.decider]),
    );
  }

  const requesterFaceEnrich = mapped
    .map((row) => row.requester)
    .filter((face): face is NonNullable<typeof face> => Boolean(
      face && resolveHwyMemberTarghinAdminFaceDossierMemberId(face),
    ))
    .map((face) => ({
      memberId: resolveHwyMemberTarghinAdminFaceDossierMemberId(face)!,
      avatarUrl: face.avatarUrl,
    }));
  if (requesterFaceEnrich.length) {
    await enrichMemberDirectoryFaceAvatarsByMemberId(requesterFaceEnrich);
    const avatarByMemberId = new Map(
      requesterFaceEnrich
        .filter((item) => item.avatarUrl)
        .map((item) => [item.memberId, item.avatarUrl!] as const),
    );
    for (const row of mapped) {
      const face = row.requester;
      if (!face?.id) {
        continue;
      }
      const requesterMemberId = resolveHwyMemberTarghinAdminFaceDossierMemberId(face);
      const url = requesterMemberId ? avatarByMemberId.get(requesterMemberId) : undefined;
      if (url) {
        face.avatarUrl = url;
      }
    }
  }

  const rows = mapped.map((row) => ({
    ...row,
    requesterMemberId: resolveTarghinRowFaceDossierMemberId(null, row.requester) || null,
    deciderMemberId: resolveTarghinRowFaceDossierMemberId(null, row.decider) || null,
  }));

  return {
    total,
    page,
    pageSize,
    rows,
  };
};

const resolveActorUserId = async (actorUserId: number | null): Promise<number | null> => {
  if (actorUserId == null || !Number.isFinite(actorUserId) || actorUserId <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId: actorUserId }, type: QueryTypes.SELECT },
  );
  return rows.length ? actorUserId : null;
};

export const decideHwyMemberTarghinRequest = async (input: {
  requestId: string;
  decision: HwyMemberTarghinDecisionKind;
  finalReasonCode: string;
  finalNote: string;
  actorUserId: number | null;
}): Promise<{ requestId: string; memberId: string; statusCode: string }> => {
  await assertSqlServer();
  const requestId = trim(input.requestId);
  if (!requestId) {
    throw new Error('Request id is required.');
  }
  const finalReasonCode = await assertHwyMemberTarghinFinalReasonCode(input.decision, input.finalReasonCode);
  const finalNote = trim(input.finalNote);
  if (!finalNote) {
    throw new Error('Decision note is required.');
  }
  if (finalNote.length > FINAL_NOTE_MAX_LENGTH) {
    throw new Error(`Decision note must be at most ${FINAL_NOTE_MAX_LENGTH} characters.`);
  }

  const statusCode = input.decision === 'approve'
    ? HWY_MEMBER_TARGHIN_REQUEST_STATUS.approved
    : HWY_MEMBER_TARGHIN_REQUEST_STATUS.rejected;
  const actorUserId = await resolveActorUserId(input.actorUserId);
  const membershipStatusOnApprove = input.decision === 'approve'
    ? await findHwyBaseInfoItemIdByShortName('Membership Status', 'pending_cancellation')
    : null;

  try {
    const rows = await execHwyProcedure<{
      requestId: string;
      memberId: string;
      statusCode: string;
    }>('hwy_targhin_decide_request', {
      request_id: Number(requestId),
      status_code: statusCode,
      final_reason_code: finalReasonCode,
      final_note: finalNote,
      actor_user_id: actorUserId,
      membership_status_code_on_approve: membershipStatusOnApprove,
    });
    const row = rows[0];
    if (!row?.requestId) {
      throw new Error('Could not save targhin decision.');
    }
    return {
      requestId: String(row.requestId),
      memberId: String(row.memberId),
      statusCode: String(row.statusCode),
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('51000') || message.includes('not found')) {
      throw new Error('Targhin request not found.');
    }
    if (message.includes('51001') || message.includes('51002') || message.includes('not pending')) {
      throw new Error('Targhin request is not pending.');
    }
    throw error;
  }
};

export const decideHwyMemberTarghinRequestsBulk = async (input: {
  requestIds: readonly string[];
  decision: HwyMemberTarghinDecisionKind;
  finalReasonCode: string;
  finalNote: string;
  actorUserId: number | null;
}): Promise<Array<{ requestId: string; memberId: string; statusCode: string }>> => {
  const uniqueIds = [...new Set(input.requestIds.map((id) => trim(id)).filter(Boolean))];
  if (uniqueIds.length === 0) {
    throw new Error('Select at least one targhin request.');
  }
  const results: Array<{ requestId: string; memberId: string; statusCode: string }> = [];
  for (const requestId of uniqueIds) {
    results.push(await decideHwyMemberTarghinRequest({
      requestId,
      decision: input.decision,
      finalReasonCode: input.finalReasonCode,
      finalNote: input.finalNote,
      actorUserId: input.actorUserId,
    }));
  }
  return results;
};

