import sql from 'mssql';

import {
  buildHwyNbTargetAudienceCriteria,
  hwyNbOrganizationNoneChecked,
  hwyNbTargetAudienceEligibleForCount,
  hwyNbTargetAudienceHasDemoFilters,
  hwyNbTargetAudienceSegmentCount,
  type HwyNbTargetAudienceCriteria,
} from '../../../domain/hwy/hwyActivityNbTargetAudience';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { QueryTypes } from 'sequelize';

const NB_ACTIVE_MEMBER_SQL = 'Mem.MembershipStatus=10851';

const NB_KASHAFEH_CORE_SQL = `
  ISNULL(Mem.DeviceOsTypeId,0)<>213991
  AND ISNUMERIC(Mem.BirthYear)=1
  AND Mem.BirthYear>YEAR(GETDATE())-18
`.trim();

const NB_GOV_CORE_SQL = `
  ISNULL(Mem.DeviceOsTypeId,0)<>213991
  AND Mem.JobTypeId IN (10881,10883,10884)
`.trim();

const NB_ORGANIZATION_MEMBER_MATCH_SQL = `
dbo.CheckStringIntersection(@NbOrganizationId, (SELECT STRING_AGG(CAST(O.OrganizationId AS VARCHAR(20)), ',') FROM dbo.HWY_Members_Organizations O WITH (NOLOCK) WHERE O.MemberId=Mem.Id), ',')=1
OR (','+REPLACE(@NbOrganizationId,' ','')+',' LIKE '%,0,%' AND NOT EXISTS (SELECT 1 FROM dbo.HWY_Members_Organizations O WITH (NOLOCK) WHERE O.MemberId=Mem.Id))
`.trim();

const NB_NO_ORGANIZATION_AFFILIATION_SQL = `
NOT EXISTS (SELECT 1 FROM dbo.HWY_Members_Organizations O WITH (NOLOCK) WHERE O.MemberId=Mem.Id)
`.trim();

type ActivityNbRow = {
  activity_type_code: string | null;
  enable_self_announcement: boolean | number | null;
  nb_only_kashafeh: boolean | number | null;
  nb_allow_gov: boolean | number | null;
  nb_legacy_gender_id: number | null;
  nb_legacy_circle_id: number | null;
  nb_legacy_province_id: string | null;
  nb_organization_ids: string | null;
  nb_allowed_roles: string | null;
};

const readSqlBit = (value: unknown): boolean => {
  if (value === true || value === 1) {
    return true;
  }
  if (value === false || value === 0 || value == null) {
    return false;
  }
  return String(value).trim() === '1';
};

const loadActivityNbRow = async (activityId: number): Promise<ActivityNbRow | null> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<ActivityNbRow>(
    `
    SELECT
      activity_type_code,
      enable_self_announcement,
      nb_only_kashafeh,
      nb_allow_gov,
      nb_legacy_gender_id,
      nb_legacy_circle_id,
      nb_legacy_province_id,
      nb_organization_ids,
      nb_allowed_roles
    FROM dbo.hwy_activities
    WHERE id = :activityId
    `,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  return rows[0] ?? null;
};

const appendAudienceSegmentOr = (sqlParts: string[], crit: HwyNbTargetAudienceCriteria): void => {
  sqlParts.push(' AND (');
  const branches: string[] = [];
  if (crit.applyKashafeh) {
    branches.push(`(${NB_KASHAFEH_CORE_SQL})`);
  }
  if (crit.applyGov) {
    branches.push(`(${NB_GOV_CORE_SQL})`);
  }
  if (crit.nbOrganizationIdsCsv !== '') {
    branches.push(`(${NB_ORGANIZATION_MEMBER_MATCH_SQL})`);
  }
  sqlParts.push(branches.length > 0 ? branches.join(' OR ') : '1=1');
  sqlParts.push(')');
};

const appendDemoFilters = (sqlParts: string[], crit: HwyNbTargetAudienceCriteria): void => {
  if (crit.nbGenderLegacyId != null) {
    sqlParts.push(' AND Mem.GenderId=@NbGenderId');
  }
  if (crit.nbCircleLegacyId != null) {
    sqlParts.push(' AND Mem.NakhebJoinCircleId=@NbCircleId');
  }
  if (crit.nbProvinceLegacyIdsCsv !== '') {
    sqlParts.push(
      " AND dbo.CheckStringIntersection(@NbProvinceId, CAST(Mem.NakhebJoinProvinceId AS VARCHAR(20)), ',')=1",
    );
  }
  if (crit.nbAllowedRolesCsv !== '') {
    sqlParts.push(
      " AND dbo.CheckStringIntersection(@NbAllowedRoles, (SELECT STRING_AGG(CAST(URR.RoleId AS VARCHAR(20)), ',') FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=Mem.UserId), ',')=1",
    );
  }
};

const bindDemoParams = (request: sql.Request, crit: HwyNbTargetAudienceCriteria): void => {
  if (crit.nbGenderLegacyId != null) {
    request.input('NbGenderId', sql.Int, crit.nbGenderLegacyId);
  }
  if (crit.nbCircleLegacyId != null) {
    request.input('NbCircleId', sql.Int, crit.nbCircleLegacyId);
  }
  if (crit.nbProvinceLegacyIdsCsv !== '') {
    request.input('NbProvinceId', sql.NVarChar(128), crit.nbProvinceLegacyIdsCsv);
  }
  if (crit.nbAllowedRolesCsv !== '') {
    request.input('NbAllowedRoles', sql.NVarChar(128), crit.nbAllowedRolesCsv);
  }
  if (crit.nbOrganizationIdsCsv !== '') {
    request.input('NbOrganizationId', sql.NVarChar(128), crit.nbOrganizationIdsCsv);
  }
};

const countFromLegacyMembersSql = async (crit: HwyNbTargetAudienceCriteria): Promise<number> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const sqlParts = [
      'SELECT COUNT(*) AS total FROM dbo.HWY_Members Mem WITH (NOLOCK) WHERE ',
      NB_ACTIVE_MEMBER_SQL,
    ];
    if (hwyNbOrganizationNoneChecked(crit.nbOrganizationIdsCsv)) {
      sqlParts.push(` AND (${NB_NO_ORGANIZATION_AFFILIATION_SQL})`);
    }
    appendAudienceSegmentOr(sqlParts, crit);
    appendDemoFilters(sqlParts, crit);
    const request = pool.request();
    bindDemoParams(request, crit);
    const result = await request.query(sqlParts.join(''));
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

/** Legacy `HWY_Nashatat.CountNbTargetAudience` against live member tables. */
export async function countHwyActivityNbTargetAudience(activityIdRaw: string): Promise<number> {
  const activityId = Number(String(activityIdRaw).trim());
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Invalid activity id.');
  }
  const row = await loadActivityNbRow(activityId);
  if (!row) {
    throw new Error('Activity not found.');
  }
  const crit = buildHwyNbTargetAudienceCriteria({
    activityTypeCode: row.activity_type_code,
    enableSelfAnnouncement: readSqlBit(row.enable_self_announcement),
    nbOnlyKashafeh: readSqlBit(row.nb_only_kashafeh),
    nbAllowGov: readSqlBit(row.nb_allow_gov),
    nbLegacyGenderId: row.nb_legacy_gender_id,
    nbLegacyCircleId: row.nb_legacy_circle_id,
    nbLegacyProvinceId: row.nb_legacy_province_id,
    nbOrganizationIds: row.nb_organization_ids,
    nbAllowedRoles: row.nb_allowed_roles,
  });
  if (!hwyNbTargetAudienceEligibleForCount(crit)) {
    return 0;
  }

  const segmentCount = hwyNbTargetAudienceSegmentCount(crit);
  const hasDemo = hwyNbTargetAudienceHasDemoFilters(crit);
  const orgNoneOnly = hwyNbOrganizationNoneChecked(crit.nbOrganizationIdsCsv);

  if (
    !hasDemo
    && segmentCount === 1
    && !orgNoneOnly
    && crit.nbOrganizationIdsCsv === ''
  ) {
    if (crit.applyGov && !crit.applyKashafeh) {
      return countGovListDefault(crit);
    }
    if (crit.applyKashafeh && !crit.applyGov) {
      return countKashafehListDefault(crit);
    }
  }

  return countFromLegacyMembersSql(crit);
}

const countGovListDefault = async (_crit: HwyNbTargetAudienceCriteria): Promise<number> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(`
      SELECT COUNT(*) AS total
      FROM dbo.HWY_Members M WITH (NOLOCK)
      WHERE M.MembershipStatus=10851
        AND (${NB_GOV_CORE_SQL.replaceAll('Mem.', 'M.')})
    `);
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};

const countKashafehListDefault = async (_crit: HwyNbTargetAudienceCriteria): Promise<number> => {
  const { connectLegacyReadPool } = await import('../../../../scripts/hwy-etl/legacyHwyRoleAuth');
  const pool = await connectLegacyReadPool();
  try {
    const result = await pool.request().query(`
      SELECT COUNT(*) AS total
      FROM dbo.HWY_Members M WITH (NOLOCK)
      WHERE M.MembershipStatus=10851
        AND (${NB_KASHAFEH_CORE_SQL.replaceAll('Mem.', 'M.')})
    `);
    return Number((result.recordset[0] as { total: number }).total ?? 0);
  } finally {
    await pool.close();
  }
};
