export type HwyMemberListScopeKind =
  | { type: 'membership_status'; status: 'pending_call_center' | 'pending_local' | 'active' | 'rejected_call_center' | 'rejected_local' | 'rejected_local_verification' }
  | { type: 'active_institute'; instituteCode: string; excludeOtherPortalChannel?: boolean }
  | { type: 'pending_local_institute'; instituteCode: string }
  | { type: 'under_18_active' }
  | { type: 'university_outside_hemam' }
  /** Legacy `Read_List_Imagefix` default queue (`V_List=Todo`): pending file approval. */
  | { type: 'registration_image_fix_todo' }
  /** Quick member search (`Read_List_SingleView`) — all membership states, no list-scope filter. */
  | { type: 'directory_unrestricted' };

