export const findHwyMemberSegmentListByLegacyCode = (
  legacyCode: string,
): HwyMemberSegmentListDefinition | undefined => {
  const normalized = normalizeHwyMemberListScopeLegacyCode(legacyCode);
  return HWY_MEMBER_SEGMENT_LIST_DEFINITIONS.find((entry) => entry.legacyCode === normalized);
};

/** Active-member segment lists show `membership_on`. Queue / rejection lists use `createdAt` instead. */
export const segmentListShouldShowMembershipOnColumn = (
  scope: HwyMemberListScopeKind,
): boolean => {
  switch (scope.type) {
    case 'active_institute':
    case 'under_18_active':
    case 'university_outside_hemam':
    case 'registration_image_fix_todo':
      return true;
    case 'directory_unrestricted':
      return true;
    case 'pending_local_institute':
      return false;
    case 'membership_status':
      return scope.status === 'active';
    default:
      return true;
  }
};

export const segmentListDefaultSortField = (
  scope: HwyMemberListScopeKind,
): 'updatedAt' | 'membershipStatusUpdatedOn' => (
  scope.type === 'registration_image_fix_todo' ? 'membershipStatusUpdatedOn' : 'updatedAt'
);

export const resolveListMembershipOnRegistrationFallback = (
  listScopeLegacy: string | null | undefined,
): boolean => {
  if (!listScopeLegacy?.trim()) {
    return true;
  }
  const definition = findHwyMemberSegmentListByLegacyCode(listScopeLegacy.trim());
  if (!definition) {
    return true;
  }
  return segmentListShouldShowMembershipOnColumn(definition.scope);
};

/** Applicant / queue grids (Waited, Marfoozeh, …) — `createdAt`, no montadhemin-only columns. */
export const isHwyMemberApplicantQueueGridColumnKeys = (
  columnKeys: readonly string[],
): boolean => {
  const keys = new Set(columnKeys);
  return keys.has('createdAt') && !keys.has('membershipOn');
};

/** Legacy list columns removed from member-directory UIs (data may remain in DB). */
export const HWY_MEMBER_DIRECTORY_SUPPRESSED_GRID_COLUMN_KEYS = new Set([
  'gradeCodeTitle',
  'loyaltyCodeTitle',
  /** Shown on the member face card second line (`hwyMemberDirectoryFaceMetaLine`). */
  'membershipOn',
]);

export const shouldHideHwyMemberDirectoryGridColumn = (columnKey: string): boolean => (
  HWY_MEMBER_DIRECTORY_SUPPRESSED_GRID_COLUMN_KEYS.has(columnKey)
);

export const shouldHideMembershipOnColumnOnMemberDirectoryGrid = (_input: {
  columnKeys: readonly string[];
  listScopeLegacy?: string | null;
}): boolean => true;

/** Registered icon + family-record columns — not on membership queue / rejection lists. */
export const shouldHideMemberDirectoryQueueFamilyUiColumns = (
  listScopeLegacy?: string | null,
): boolean => {
  const scope = listScopeLegacy?.trim();
  if (!scope) {
    return false;
  }
  const definition = findHwyMemberSegmentListByLegacyCode(scope);
  if (!definition) {
    return false;
  }
  switch (definition.scope.type) {
    case 'registration_image_fix_todo':
      return false;
    case 'membership_status':
      return definition.scope.status !== 'active';
    case 'pending_local_institute':
      return true;
    default:
      return false;
  }
};

export const shouldHideMemberRegisteredIconColumnOnMemberDirectoryGrid = (input: {
  listScopeLegacy?: string | null;
}): boolean => shouldHideMemberDirectoryQueueFamilyUiColumns(input.listScopeLegacy);

export const shouldHideMemberNakhebinFamilyRecordColumnOnMemberDirectoryGrid = (input: {
  listScopeLegacy?: string | null;
}): boolean => shouldHideMemberDirectoryQueueFamilyUiColumns(input.listScopeLegacy);

/** Membership status workflow lists — tracking code is on the member face card. */
export const shouldHideMemberDirectoryTrackingCodeColumn = (input: {
  listScopeLegacy?: string | null;
}): boolean => shouldHideMemberDirectoryQueueFamilyUiColumns(input.listScopeLegacy);

export const parseHwyMemberDirectoryListScopeFromDesignerQueryParam = (
  raw: string | undefined | null,
): string | null => {
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) {
    return null;
  }
  if (trimmed.startsWith('static:')) {
    const legacy = trimmed.slice('static:'.length).trim();
    return legacy.length > 0 ? legacy : null;
  }
  return null;
};

export const findHwyMemberSegmentListByPageName = (
  pageName: string,
): HwyMemberSegmentListDefinition | undefined => (
  HWY_MEMBER_SEGMENT_LIST_DEFINITIONS.find((entry) => entry.pageName === pageName)
);

