import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;

const applyImageFixEditorMemberColumns = async (): Promise<void> => {
  const sequelize = getControlPlaneSequelize();
  await sequelize.query(
    `
    IF COL_LENGTH(N'dbo.hwy_members', N'pictures_reviewed') IS NOT NULL
    BEGIN
      DECLARE @dfPicturesReviewed NVARCHAR(256);
      SELECT @dfPicturesReviewed = dc.name
      FROM sys.default_constraints dc
      INNER JOIN sys.columns c
        ON c.default_object_id = dc.object_id
      WHERE dc.parent_object_id = OBJECT_ID(N'dbo.hwy_members')
        AND c.name = N'pictures_reviewed';
      IF @dfPicturesReviewed IS NOT NULL
      BEGIN
        DECLARE @dropPicturesReviewedDf NVARCHAR(512) = N'ALTER TABLE dbo.hwy_members DROP CONSTRAINT '
          + QUOTENAME(@dfPicturesReviewed);
        EXEC sp_executesql @dropPicturesReviewedDf;
      END
      ALTER TABLE dbo.hwy_members DROP COLUMN pictures_reviewed;
    END

    IF COL_LENGTH(N'dbo.hwy_members', N'nakheb_card_front_check') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_members ADD nakheb_card_front_check BIT NOT NULL
        CONSTRAINT DF_hwy_members_nakheb_card_front_check DEFAULT (0);
    END

    IF COL_LENGTH(N'dbo.hwy_members', N'nakheb_card_front_type_code') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_members ADD nakheb_card_front_type_code NVARCHAR(1000) NULL;
    END
    `,
    { type: QueryTypes.RAW },
  );
};

/** Idempotent DDL for ImageFix editor (`NakhebCard_Front_Check` / `TypeId` parity). */
export const ensureHwyMemberImageFixEditorSchema = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = applyImageFixEditorMemberColumns().catch((error) => {
      ensurePromise = null;
      throw error;
    });
  }

  await ensurePromise;
};
