import type { Order } from 'sequelize';
import type { EdgeModelDefinition } from '../../../shared/api/contracts/data-api';
import { parseSortQuery } from '../../services/data-api/dataApiQuery';
import { HWY_MEMBER_DIRECTORY_DEFAULT_SORT_FIELD } from '../../../domain/hwy/hwyMemberDirectoryListSort';

const parseSortDir = (raw: unknown): 'ASC' | 'DESC' => (
  String(raw ?? '').trim().toLowerCase() === 'asc' ? 'ASC' : 'DESC'
);

/** Grid sort keys that map to persisted code columns on scoped member lists. */
const SCOPED_LIST_SORT_FIELD_ALIASES: Record<string, string> = {
  displayFullName: 'membershipOn',
  display_full_name: 'membershipOn',
  electoralDivisionPath: 'membershipOn',
  membershipStatusCodeTitle: 'membershipStatusCode',
  jobTypeCodeTitle: 'jobTypeCode',
  jobTypeAndPlace: 'jobTypeCode',
  mehaniUnionCodeTitle: 'mehaniUnionCode',
  mehaniUnionDegreeCodeTitle: 'mehaniUnionDegreeCode',
  educationLevelAndDetails: 'educationLevelCode',
  educationLevelCodeTitle: 'educationLevelCode',
};

/**
 * Sorting on computed `displayFullName` forces SQL Server to materialize/sort the whole
 * scoped set from vw_hwy_members. Default list order is `updatedAt` DESC.
 * All-people lists remap display name to lastname/firstname.
 */
export const resolveHwyMemberDirectoryListOrder = (
  query: Record<string, unknown>,
  allowedFilterFields: Set<string>,
  columns: EdgeModelDefinition['columns'],
  allowSort: boolean,
  listScopeLegacy?: string | null,
): Order | undefined => {
  if (!allowSort) {
    return undefined;
  }
  const rawSort = typeof query.sort === 'string' ? query.sort.trim() : '';
  const sortBy = typeof query.sortBy === 'string' ? query.sortBy.trim() : '';

  if (!sortBy && !rawSort && allowedFilterFields.has(HWY_MEMBER_DIRECTORY_DEFAULT_SORT_FIELD)) {
    return [[HWY_MEMBER_DIRECTORY_DEFAULT_SORT_FIELD, 'DESC'], ['id', 'ASC']];
  }

  if (listScopeLegacy) {
    const aliased = sortBy ? SCOPED_LIST_SORT_FIELD_ALIASES[sortBy] : undefined;
    if (aliased && allowedFilterFields.has(aliased)) {
      return parseSortQuery(
        { ...query, sortBy: aliased },
        allowedFilterFields,
        columns,
      );
    }
  }

  if (sortBy === 'displayFullName' || sortBy === 'display_full_name') {
    const dir = parseSortDir(query.sortDir);
    const order: Order = [];
    if (allowedFilterFields.has('lastname')) {
      order.push(['lastname', dir]);
    }
    if (allowedFilterFields.has('firstname')) {
      order.push(['firstname', dir]);
    }
    if (allowedFilterFields.has('id')) {
      order.push(['id', 'ASC']);
    }
    if (order.length > 0) {
      return order;
    }
  }
  return parseSortQuery(query, allowedFilterFields, columns);
};
