import { resolveListUserAvatarSrc } from '../../shared/api/contracts/users/avatar';

const readTrimmed = (row: Record<string, unknown>, ...keys: string[]): string => {
  for (const key of keys) {
    const raw = row[key];
    if (raw == null) {
      continue;
    }
    const text = String(raw).trim();
    if (text.length > 0) {
      return text;
    }
  }
  return '';
};

const readProfileImageFlag = (row: Record<string, unknown>): boolean => {
  const raw = row.has_profile_image_xs
    ?? row.hasProfileImage
    ?? row.has_profile_image;
  if (typeof raw === 'boolean') {
    return raw;
  }
  if (typeof raw === 'number') {
    return raw !== 0;
  }
  if (typeof raw === 'string') {
    const normalized = raw.trim().toLowerCase();
    return normalized === '1' || normalized === 'true' || normalized === 'yes';
  }
  return false;
};

/** Member-directory list resolves avatar URLs; raw rows often omit `avatarUrl`. */
export const resolveHwyHouseholdMemberAvatarUrl = (
  row: Record<string, unknown> | null | undefined,
): string => {
  if (!row) {
    return '';
  }

  const direct = readTrimmed(row, 'avatarUrl', 'avatar_url');
  if (direct) {
    return direct;
  }

  const userId = Number(row.userId ?? row.user_id);
  if (!Number.isFinite(userId) || userId <= 0) {
    return '';
  }

  const profileSizeRaw = row.profileImageSize ?? row.profile_image_size;
  const profileSize = profileSizeRaw == null ? null : Number(profileSizeRaw);
  const hasImage = readProfileImageFlag(row)
    || (Number.isFinite(profileSize) && profileSize > 0);

  const src = resolveListUserAvatarSrc({
    id: userId,
    has_profile_image_xs: hasImage,
    avatar_url: readTrimmed(row, 'avatar_url', 'avatarUrl') || null,
    profile_image_size: Number.isFinite(profileSize) ? profileSize : null,
  });

  return src ?? '';
};

export const attachHwyHouseholdMemberAvatarUrl = (row: Record<string, unknown>): void => {
  const resolved = resolveHwyHouseholdMemberAvatarUrl(row);
  if (resolved) {
    row.avatarUrl = resolved;
  }
};
