/** Locked Member File Kind slugs (`Member File Kind` Base Info catalog). */
export const HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT = 'other_attachment';

/** Browser `accept` for member dossier “other attachments” (multi-row). */
export const HWY_MEMBER_OTHER_ATTACHMENT_ACCEPT =
  'image/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.zip,.rar,.7z,.txt,.mp4,.webm,.mp3,.wav';

/** Profile avatar slot — edited on the dossier profile rail, not in the documents grid. */
export const HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG = 'personal_photo' as const satisfies HwyMemberRegistrationFileKindSlug;

export const HWY_MEMBER_REGISTRATION_FILE_KIND_SLUGS = [
  'personal_photo',
  'national_card_front',
  'national_card_back',
  'voter_card_front',
  'residence_card_front',
  'oath_document',
  'second_nationality_document',
] as const;

export type HwyMemberRegistrationFileKindSlug = (typeof HWY_MEMBER_REGISTRATION_FILE_KIND_SLUGS)[number];

export function isHwyMemberDossierProfilePhotoKindSlug(slug: string | null | undefined): boolean {
  return String(slug ?? '').trim() === HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG;
}

export type HwyMemberFileKindUploadShape = 'circle' | 'rectangle';

const REGISTRATION_SHAPE_BY_SLUG: Record<HwyMemberRegistrationFileKindSlug, HwyMemberFileKindUploadShape> = {
  personal_photo: 'circle',
  national_card_front: 'rectangle',
  national_card_back: 'rectangle',
  voter_card_front: 'rectangle',
  residence_card_front: 'rectangle',
  oath_document: 'rectangle',
  second_nationality_document: 'rectangle',
};

export function resolveHwyMemberFileKindUploadShape(
  slug: string | null | undefined,
): HwyMemberFileKindUploadShape {
  const key = String(slug ?? '').trim() as HwyMemberRegistrationFileKindSlug;
  return REGISTRATION_SHAPE_BY_SLUG[key] ?? 'rectangle';
}

export function isHwyMemberRegistrationFileKindSlug(slug: string | null | undefined): slug is HwyMemberRegistrationFileKindSlug {
  const trimmed = String(slug ?? '').trim();
  return (HWY_MEMBER_REGISTRATION_FILE_KIND_SLUGS as readonly string[]).includes(trimmed);
}

export function isHwyMemberOtherAttachmentKindSlug(slug: string | null | undefined): boolean {
  return String(slug ?? '').trim().toLowerCase() === HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT;
}

export type HwyMemberFileEditGroup = 'registration' | 'other';

export function resolveHwyMemberFileEditGroup(slug: string | null | undefined): HwyMemberFileEditGroup | null {
  if (isHwyMemberRegistrationFileKindSlug(slug)) {
    return 'registration';
  }
  if (isHwyMemberOtherAttachmentKindSlug(slug)) {
    return 'other';
  }
  return null;
}
