/** Sent on region submit when the operator explicitly removed the logo (empty base64 alone means unchanged). */
export const HWY_INSTITUTE_LOGO_CLEAR_FIELD = 'logoContentClear';

export const isHwyInstituteLogoClearRequested = (payload: Record<string, unknown>): boolean => {
  const raw = payload[HWY_INSTITUTE_LOGO_CLEAR_FIELD];
  if (raw === true || raw === 1) {
    return true;
  }
  if (typeof raw === 'string') {
    const trimmed = raw.trim().toLowerCase();
    return trimmed === '1' || trimmed === 'true' || trimmed === 'yes';
  }
  return false;
};
