import { QueryTypes } from 'sequelize';

import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyMemberTarghinAdminFaceDossierMemberId } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { HWY_MEMBER_TARGHIN_REQUEST_STATUS } from '../../../domain/hwy/hwyMemberTarghinRequestStatus';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { negoAuthorHasLabel } from './hwyMemberTarghinNegoAuthorResolve';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const mapVmRowToFace = (row: Record<string, unknown>): HwyMemberTarghinAdminMemberFace => ({
  id: trim(row.id as string | undefined),
  username: trim(row.username as string | undefined) || null,
  displayFullName: formatHwyMemberPersonDisplayName(trim(row.display_full_name as string | undefined)) || null,
  genderCode: trim(row.gender_code as string | undefined) || null,
  avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
    avatarUrl: trim(row.avatar_url as string | undefined) || null,
    hasProfileImage: row.has_profile_image === true || row.has_profile_image === 1,
    userId: row.user_id != null ? Number(row.user_id) : null,
  }),
  phone: trim(row.phone1 as string | undefined) || null,
  electoralDivisionPath: trim(row.electoral_division_path as string | undefined) || null,
});

async function loadExecutorFacesByLegacyKeysFromControlPlane(
  legacyKeys: readonly string[],
): Promise<{ faces: Map<string, HwyMemberTarghinAdminMemberFace>; stillMissingKeys: string[] }> {
  const keys = [...new Set(legacyKeys.map(trim).filter(Boolean))];
  const result = new Map<string, HwyMemberTarghinAdminMemberFace>();
  if (!keys.length) {
    return { faces: result, stillMissingKeys: [] };
  }

  const numericIds = keys.filter((key) => /^\d+$/.test(key)).map(Number);
  const sequelize = getControlPlaneSequelize();

  if (numericIds.length) {
    const idPlaceholders = numericIds.map((_, index) => `:eid${index}`).join(', ');
    const idReplacements = Object.fromEntries(numericIds.map((id, index) => [`eid${index}`, id]));
    const byIdRows = await sequelize.query<Record<string, unknown>>(
      `
      SELECT
        CAST(id AS VARCHAR(32)) AS id,
        username,
        display_full_name,
        gender_code,
        avatar_url,
        has_profile_image,
        user_id,
        phone1,
        electoral_division_path
      FROM dbo.vw_hwy_members WITH (NOLOCK)
      WHERE id IN (${idPlaceholders})
      `,
      { replacements: idReplacements, type: QueryTypes.SELECT },
    );
    for (const row of byIdRows) {
      const face = mapVmRowToFace(row);
      if (!negoAuthorHasLabel(face)) {
        continue;
      }
      result.set(String(row.id).trim(), face);
      if (face.username?.trim()) {
        result.set(face.username.trim(), face);
      }
    }
  }

  const usernameKeys = keys.filter((key) => !result.has(key));
  if (usernameKeys.length) {
    const unPlaceholders = usernameKeys.map((_, index) => `:eun${index}`).join(', ');
    const unReplacements = Object.fromEntries(usernameKeys.map((key, index) => [`eun${index}`, key]));
    const byUsernameRows = await sequelize.query<Record<string, unknown>>(
      `
      SELECT
        CAST(id AS VARCHAR(32)) AS id,
        username,
        display_full_name,
        gender_code,
        avatar_url,
        has_profile_image,
        user_id,
        phone1,
        electoral_division_path
      FROM dbo.vw_hwy_members WITH (NOLOCK)
      WHERE username IN (${unPlaceholders})
      `,
      { replacements: unReplacements, type: QueryTypes.SELECT },
    );
    for (const row of byUsernameRows) {
      const face = mapVmRowToFace(row);
      if (!negoAuthorHasLabel(face)) {
        continue;
      }
      const username = face.username?.trim();
      if (username) {
        result.set(username, face);
      }
      result.set(String(row.id).trim(), face);
    }
  }

  return { faces: result, stillMissingKeys: keys.filter((key) => !result.has(key)) };
}

const parseMemberId = (memberId: string): number | null => {
  const trimmed = String(memberId ?? '').trim();
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  const id = Number(trimmed);
  return Number.isFinite(id) && id > 0 ? id : null;
};

async function loadFinalByLegacyFromControlPlane(
  memberIds: readonly string[],
): Promise<Map<string, string>> {
  const numericIds = [...new Set(
    memberIds
      .map(parseMemberId)
      .filter((id): id is number => id != null),
  )];
  const result = new Map<string, string>();
  if (!numericIds.length) {
    return result;
  }

  const placeholders = numericIds.map((_, index) => `:mid${index}`).join(', ');
  const replacements: Record<string, unknown> = Object.fromEntries(
    numericIds.map((id, index) => [`mid${index}`, id]),
  );
  replacements.approved_status = HWY_MEMBER_TARGHIN_REQUEST_STATUS.approved;

  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ member_id: number | string; final_by_legacy: string | null }>(
    `
    SELECT member_id, final_by_legacy
    FROM (
      SELECT
        t.member_id,
        NULLIF(LTRIM(RTRIM(t.final_by_legacy)), N'') AS final_by_legacy,
        ROW_NUMBER() OVER (
          PARTITION BY t.member_id
          ORDER BY
            CASE WHEN t.status_code = :approved_status THEN 0 ELSE 1 END,
            COALESCE(t.final_at, t.created_at) DESC,
            t.id DESC
        ) AS rn
      FROM dbo.hwy_member_targhin_requests t WITH (NOLOCK)
      WHERE t.member_id IN (${placeholders})
    ) ranked
    WHERE rn = 1
      AND final_by_legacy IS NOT NULL
    `,
    { replacements, type: QueryTypes.SELECT },
  );

  for (const row of rows) {
    const memberId = String(row.member_id ?? '').trim();
    const legacy = String(row.final_by_legacy ?? '').trim();
    if (memberId && legacy) {
      result.set(memberId, legacy);
    }
  }
  return result;
}

/** Resolve المنفّذ — legacy FinalBy is usually a membership id, not base_users.id. */
export async function attachHwyTarghinMembersListExecutors<
  TRow extends {
    memberId: string;
    executor: HwyMemberTarghinAdminMemberFace | null;
  },
>(
  rows: TRow[],
): Promise<Map<string, string[]>> {
  const legacyRoleTitlesByUsername = new Map<string, string[]>();
  const needsAttach = rows.filter((row) => {
    const executor = row.executor;
    if (
      executor
      && negoAuthorHasLabel(executor)
      && resolveHwyMemberTarghinAdminFaceDossierMemberId(executor)
    ) {
      return false;
    }
    return !negoAuthorHasLabel(executor);
  });
  if (!needsAttach.length) {
    return legacyRoleTitlesByUsername;
  }

  const finalByLegacyByMemberId = await loadFinalByLegacyFromControlPlane(
    needsAttach.map((row) => row.memberId),
  );

  const legacyActors = [...new Set(finalByLegacyByMemberId.values())];
  const { faces: facesByLegacy } = await loadExecutorFacesByLegacyKeysFromControlPlane(
    legacyActors,
  );

  // CP-only: legacy MembersV2 round-trips are too slow for list paint (multi-minute timeouts).

  for (const row of needsAttach) {
    const legacy = finalByLegacyByMemberId.get(row.memberId);
    if (!legacy) {
      continue;
    }
    const face = facesByLegacy.get(legacy);
    if (face && negoAuthorHasLabel(face)) {
      row.executor = face;
    }
  }

  return legacyRoleTitlesByUsername;
}
