import type {
  HwyMemberTarghinDecisionKind,
  HwyMemberTarghinFinalReasonOption,
} from '../../../domain/hwy/hwyMemberTarghinFinalReasons';
import { resolveHwyMemberTarghinFinalReasonLegacyParentId } from '../../../domain/hwy/hwyMemberTarghinFinalReasons';
import { resolveHwyMemberDirectoryDetailLang } from '../../../domain/hwy/hwyMemberDirectoryDetail';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';
import { syncHwyMemberTarghinFinalReasonsFromLegacy } from './hwyMemberTarghinFinalReasonsLegacySync';
import { listLegacyHwyMemberTarghinRequestReasonRows } from './hwyMemberTarghinRequestReasonsLegacySync';

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

const mapRowsToOptions = async (
  rows: BaseInfoDbRow[],
  cultureId: string,
): Promise<HwyMemberTarghinFinalReasonOption[]> => {
  const mapped = await mapBaseInfoRowsForCulture(rows as BaseInfoDbRow[], cultureId, (row, context) => ({
    viewOrder: toViewOrderNumber(row.viewOrder),
    label: context.label,
    id: row.id,
  }));

  return mapped
    .map((row) => {
      const value = String(row.id ?? '').trim();
      const label = String(row.label ?? '').trim() || value;
      return { value, label };
    })
    .filter((row) => row.value && row.label)
    .sort((left, right) => left.label.localeCompare(right.label, 'ar'));
};

export async function listHwyMemberTarghinFinalReasonOptions(
  decision: HwyMemberTarghinDecisionKind,
  cultureOrLang?: string | null,
): Promise<HwyMemberTarghinFinalReasonOption[]> {
  const queryLang = resolveHwyMemberDirectoryDetailLang(cultureOrLang);
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const parentId = resolveHwyMemberTarghinFinalReasonLegacyParentId(decision);

  let rows = await prisma().baseInfo.findMany({
    where: { parentId, isActive: true },
    select: BASE_INFO_ROW_SELECT,
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
  });

  if (rows.length === 0) {
    await syncHwyMemberTarghinFinalReasonsFromLegacy();
    rows = await prisma().baseInfo.findMany({
      where: { parentId, isActive: true },
      select: BASE_INFO_ROW_SELECT,
      orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    });
  }

  if (rows.length === 0) {
    const legacyRows = await listLegacyHwyMemberTarghinRequestReasonRows(Number(parentId));
    return legacyRows.map((row) => ({
      value: String(row.id),
      label: row.title,
    }));
  }

  return mapRowsToOptions(rows as BaseInfoDbRow[], cultureId);
}

export async function assertHwyMemberTarghinFinalReasonCode(
  decision: HwyMemberTarghinDecisionKind,
  finalReasonCodeRaw: string,
): Promise<string> {
  const finalReasonCode = finalReasonCodeRaw.trim();
  if (!finalReasonCode) {
    throw new Error('Decision reason is required.');
  }
  const parentId = resolveHwyMemberTarghinFinalReasonLegacyParentId(decision);
  let row = await prisma().baseInfo.findFirst({
    where: { id: finalReasonCode, parentId, isActive: true },
    select: { id: true },
  });
  if (!row) {
    await syncHwyMemberTarghinFinalReasonsFromLegacy();
    row = await prisma().baseInfo.findFirst({
      where: { id: finalReasonCode, parentId, isActive: true },
      select: { id: true },
    });
  }
  if (!row) {
    throw new Error('Decision reason is invalid.');
  }
  return finalReasonCode;
}
