import {
  insertBaseInfoNode,
  updateBaseInfoNode,
} from '../../../src/server/domain/base-info/treeRepository';
import { prisma } from '../../../src/server/domain/users/prismaHelpers';
import { invalidateBaseInfoOptionsCache } from '../../../src/server/services/baseInfoOptionsCache';
import {
  HWY_BASE_INFO_CATEGORIES,
  HWY_BASE_INFO_ROOT_TITLE,
  type HwyBaseInfoCategorySeed,
  type HwyBaseInfoItemSeed,
} from './hwyBaseInfoCatalog';
import {
  persistHwyMembershipStatusIqOverrides,
  persistHwyRegistrationChannelIqOverrides,
  persistHwySecurityClearanceAnswerIqOverrides,
} from './hwyBaseInfoCultureIqOverrides';
import { persistHwyMembershipStatusUiColors } from './hwyMembershipStatusUiColors';

/** Stable Hawiety Base Info root id (opt-in package; not controlPlaneSeed). */
export const HWY_BASE_INFO_ROOT_ID = '220';

export type HwyBaseInfoSeedResult = {
  rootId: string;
  categories: Array<{
    title: string;
    id: string;
    itemCount: number;
  }>;
};

const findRootByTitle = async (title: string) => (
  prisma().baseInfo.findFirst({
    where: {
      parentId: null,
      title,
    },
    select: { id: true },
  })
);

const findChildByTitle = async (parentId: string, title: string) => (
  prisma().baseInfo.findFirst({
    where: {
      parentId,
      title,
    },
    select: { id: true },
  })
);

const findChildByShortName = async (parentId: string, shortName: string) => (
  prisma().baseInfo.findFirst({
    where: { parentId, shortName },
    select: { id: true },
  })
);

const toActor = (actorId: number | null) => (
  actorId !== null && Number.isFinite(actorId) ? BigInt(actorId) : null
);

const hwyBaseInfoUiHtml = (lucideIcon?: string) => (
  lucideIcon ? `<i data-lucide="${lucideIcon}"></i>` : null
);

const upsertNode = async (input: {
  parentId: string | null;
  title: string;
  shortName?: string | null;
  viewOrder: number;
  value: number;
  uiHtml?: string | null;
  existingId?: string | null;
  isActive?: boolean;
  actorId: number | null;
}): Promise<string> => {
  const {
    parentId,
    title,
    shortName = null,
    viewOrder,
    value,
    uiHtml = null,
    existingId,
    isActive = true,
    actorId,
  } = input;

  if (existingId) {
    await updateBaseInfoNode([
      title,
      shortName,
      viewOrder,
      null,
      null,
      value,
      isActive,
      null,
      uiHtml,
      undefined,
      actorId,
      existingId,
    ]);
    return existingId;
  }

  const inserted = await insertBaseInfoNode([
    parentId,
    3,
    title,
    shortName,
    viewOrder,
    null,
    null,
    value,
    isActive,
    null,
    uiHtml,
    undefined,
    actorId,
  ]);

  const id = inserted?.id;
  if (!id) {
    throw new Error(`Failed to create Base Info node "${title}".`);
  }
  return id;
};

const ensureHwyRoot = async (actorId: number | null): Promise<string> => {
  const actor = toActor(actorId);
  const existingByTitle = await findRootByTitle(HWY_BASE_INFO_ROOT_TITLE);
  if (existingByTitle) {
    await upsertNode({
      parentId: null,
      title: HWY_BASE_INFO_ROOT_TITLE,
      viewOrder: 220,
      value: 1,
      uiHtml: null,
      existingId: existingByTitle.id,
      actorId,
    });
    return existingByTitle.id;
  }

  const existingFixed = await prisma().baseInfo.findUnique({
    where: { id: HWY_BASE_INFO_ROOT_ID },
    select: { id: true },
  });
  if (existingFixed) {
    await upsertNode({
      parentId: null,
      title: HWY_BASE_INFO_ROOT_TITLE,
      viewOrder: 220,
      value: 1,
      uiHtml: null,
      existingId: existingFixed.id,
      actorId,
    });
    return existingFixed.id;
  }

  await prisma().baseInfo.create({
    data: {
      id: HWY_BASE_INFO_ROOT_ID,
      parentId: null,
      title: HWY_BASE_INFO_ROOT_TITLE,
      viewOrder: 220,
      value: 1,
      isActive: true,
      createdBy: actor,
      updatedBy: actor,
    },
  });
  return HWY_BASE_INFO_ROOT_ID;
};

const seedCategory = async (
  rootId: string,
  category: HwyBaseInfoCategorySeed,
  actorId: number | null,
): Promise<{ id: string; itemCount: number }> => {
  const existingCategory = await findChildByTitle(rootId, category.title);
  const categoryId = await upsertNode({
    parentId: rootId,
    title: category.title,
    viewOrder: category.viewOrder,
    value: category.value,
    existingId: existingCategory?.id ?? null,
    actorId,
  });

  for (const entry of category.items) {
    await seedItem(categoryId, entry, actorId);
  }

  return { id: categoryId, itemCount: category.items.length };
};

const seedItem = async (
  categoryId: string,
  entry: HwyBaseInfoItemSeed,
  actorId: number | null,
): Promise<string> => {
  const existing = await findChildByShortName(categoryId, entry.shortName)
    ?? await findChildByTitle(categoryId, entry.title);

  return upsertNode({
    parentId: categoryId,
    title: entry.title,
    shortName: entry.shortName,
    viewOrder: entry.viewOrder,
    value: entry.value,
    uiHtml: hwyBaseInfoUiHtml(entry.lucideIcon),
    existingId: existing?.id ?? null,
    isActive: entry.isActive ?? true,
    actorId,
  });
};

export async function seedHwyBaseInfo(actorId: number | null = null): Promise<HwyBaseInfoSeedResult> {
  const rootId = await ensureHwyRoot(actorId);

  const categories: HwyBaseInfoSeedResult['categories'] = [];
  for (const category of HWY_BASE_INFO_CATEGORIES) {
    const seeded = await seedCategory(rootId, category, actorId);
    categories.push({
      title: category.title,
      id: seeded.id,
      itemCount: seeded.itemCount,
    });
  }

  await persistHwyMembershipStatusIqOverrides();
  await persistHwyMembershipStatusUiColors();
  await persistHwySecurityClearanceAnswerIqOverrides();
  await persistHwyRegistrationChannelIqOverrides();

  invalidateBaseInfoOptionsCache();
  return { rootId, categories };
}

export async function unseedHwyBaseInfo(): Promise<{ deletedRootId: string | null }> {
  const root = await findRootByTitle(HWY_BASE_INFO_ROOT_TITLE)
    ?? await prisma().baseInfo.findUnique({
      where: { id: HWY_BASE_INFO_ROOT_ID },
      select: { id: true },
    });
  if (!root) {
    return { deletedRootId: null };
  }

  const nodes = await prisma().baseInfo.findMany({
    where: {
      OR: [
        { id: root.id },
        { id: { startsWith: `${root.id}.` } },
      ],
    },
    select: { id: true },
  });
  const deepestFirst = [...nodes].sort((a, b) => b.id.length - a.id.length);
  for (const row of deepestFirst) {
    await prisma().baseInfo.delete({ where: { id: row.id } });
  }

  invalidateBaseInfoOptionsCache();
  return { deletedRootId: root.id };
}

export async function findHwyBaseInfoCategoryId(categoryTitle: string): Promise<string> {
  const root = await findRootByTitle(HWY_BASE_INFO_ROOT_TITLE)
    ?? await prisma().baseInfo.findUnique({
      where: { id: HWY_BASE_INFO_ROOT_ID },
      select: { id: true },
    });
  if (!root) {
    throw new Error('Hawiety Base Info root missing.');
  }
  const category = await findChildByTitle(root.id, categoryTitle);
  if (!category) {
    throw new Error(`Hawiety Base Info category "${categoryTitle}" missing.`);
  }
  return category.id;
}

export async function findHwyBaseInfoItemId(
  categoryTitle: string,
  shortName: string,
): Promise<string> {
  const categoryId = await findHwyBaseInfoCategoryId(categoryTitle);
  const item = await findChildByShortName(categoryId, shortName);
  if (!item) {
    throw new Error(`Hawiety Base Info item "${shortName}" missing under "${categoryTitle}".`);
  }
  return item.id;
}
