import { QueryTypes } from 'sequelize';

import { resolveHwyMemberListInstituteId } from '../../../domain/hwy/hwyMemberInstituteCodes';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

type InstituteCharacterRow = {
  memberId: string;
  characterCode: string;
};

export async function attachListInstituteCharacterFields(
  rows: Record<string, unknown>[],
  instituteCode: string,
  queryLang: string,
): Promise<void> {
  if (rows.length === 0 || readControlPlaneProvider() !== 'sqlserver') {
    return;
  }
  const instituteId = resolveHwyMemberListInstituteId(instituteCode.trim());
  if (instituteId == null) {
    return;
  }
  const memberIds = rows
    .map((row) => String(row.id ?? '').trim())
    .filter((id) => id.length > 0);
  if (memberIds.length === 0) {
    return;
  }
  const sequelize = getControlPlaneSequelize();
  const queryRows = await sequelize.query<InstituteCharacterRow>(
    `
    SELECT
      CAST(mi.member_id AS VARCHAR(32)) AS memberId,
      mi.character_code AS characterCode
    FROM dbo.hwy_member_institutes mi
    WHERE mi.member_id IN (:memberIds)
      AND mi.institute_id = :instituteId
    `,
    {
      replacements: { memberIds, instituteId },
      type: QueryTypes.SELECT,
    },
  );
  const codeByMember = new Map<string, string>();
  for (const row of queryRows) {
    const memberId = row.memberId.trim();
    const code = String(row.characterCode ?? '').trim();
    if (memberId && code) {
      codeByMember.set(memberId, code);
    }
  }
  if (codeByMember.size === 0) {
    return;
  }
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const enriched = await listBaseInfoEnrichmentRowsByIds([...new Set(codeByMember.values())], cultureId);
  const titleById = new Map(
    enriched.map((item) => [
      String(item.id ?? '').trim(),
      String(item.title ?? item.title_canonical ?? '').trim(),
    ]),
  );
  for (const row of rows) {
    const memberId = String(row.id ?? '').trim();
    const characterCode = codeByMember.get(memberId);
    if (!characterCode) {
      continue;
    }
    row.characterCode = characterCode;
    row.characterCodeTitle = titleById.get(characterCode) || characterCode;
  }
}
