import {
  clearNonAllocatedHwyMemberDirectoryUsernameFields,
  normalizeHwyMemberDirectoryRowsForFaceCaption,
} from '../../../domain/hwy/hwyMembershipUsername';
import { isHwyMemberDirectoryListFaceCaptionTrackingOnlyScope } from '../../../domain/hwy/hwyMemberDirectoryListFaceCaptionMode';
import {
  attachLegacyMembershipUsernamesToMemberDirectoryRows,
  attachLegacyTrackingCodesToMemberDirectoryRows,
} from './hwyLegacyMembershipUsernameByMemberId.service';

/** Member-directory list GET must project these fields so legacy / CP username attach can run. */
export const HWY_MEMBER_DIRECTORY_LIST_FACE_CAPTION_ROW_FIELDS = [
  'userId',
  'username',
  'trackingCode',
] as const;

export type ApplyHwyMemberDirectoryListFaceCaptionOptions = {
  listScopeLegacy?: string | null;
};

/**
 * Locked pipeline for membership number under list avatars (all `HWY_Members_List_*` scopes +
 * All People). Every member-directory list fetch must run this before the grid client sees rows.
 *
 * Display contract (UI: `resolveHwyMemberDirectoryListFaceCaptionForScope`):
 * - Registered lists: six-digit username → blue; else tracking → red.
 * - Applicant queues (Waited / Marfoozeh / pending institute): tracking only → red (never blue).
 */
export async function applyHwyMemberDirectoryListFaceCaptionUsernames(
  rows: Record<string, unknown>[],
  options: ApplyHwyMemberDirectoryListFaceCaptionOptions = {},
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  const trackingOnly = isHwyMemberDirectoryListFaceCaptionTrackingOnlyScope(options.listScopeLegacy);
  if (trackingOnly) {
    clearNonAllocatedHwyMemberDirectoryUsernameFields(rows);
    for (const row of rows) {
      row.username = '';
      if (Object.prototype.hasOwnProperty.call(row, 'userUsername')) {
        row.userUsername = '';
      }
    }
    await attachLegacyTrackingCodesToMemberDirectoryRows(rows);
    return;
  }
  await attachLegacyMembershipUsernamesToMemberDirectoryRows(rows);
  normalizeHwyMemberDirectoryRowsForFaceCaption(rows);
}
