import sql from 'mssql';
import { Pool } from 'pg';
import { SETTINGS_PATH } from '../../src/server/config/settingsFile';
import { getDataSourcesFromSettings, type StoredDataSource } from '../../src/server/db/dataSourcesStore';
import { readControlPlaneDatabaseSettings } from '../../src/server/db/controlPlaneDatabase';
import { buildMssqlConfigFromControlPlaneUrl } from '../../src/server/db/mssqlControlPlaneConfig';

export type HwyDataSourceKind = 'postgresql' | 'sqlserver';

export type ResolvedHwyDataSource = {
  kind: HwyDataSourceKind;
  source: StoredDataSource;
};

export const resolveHwyDefaultDataSource = (): ResolvedHwyDataSource => {
  const sources = getDataSourcesFromSettings(SETTINGS_PATH);
  const source = sources.find((item) => item.isDefault) ?? sources[0];
  if (!source) {
    throw new Error('HWY requires a default data source.');
  }
  if (source.type === 'PostgreSQL') {
    return { kind: 'postgresql', source };
  }
  if (source.type === 'SQL Server') {
    return { kind: 'sqlserver', source };
  }
  throw new Error(`HWY requires PostgreSQL or SQL Server (got ${source.type}).`);
};

export const createPostgresPool = (source: StoredDataSource): Pool => new Pool({
  host: source.host || 'localhost',
  port: Number(source.port) || 5432,
  user: source.username || 'postgres',
  password: source.password || '',
  database: source.database || 'AppEnd',
});

export const connectMssqlControlPlane = async (): Promise<sql.ConnectionPool> => {
  const settings = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  if (settings.provider !== 'sqlserver') {
    throw new Error(`HWY SQL Server path requires sqlserver control plane (got ${settings.provider}).`);
  }
  return sql.connect(buildMssqlConfigFromControlPlaneUrl(settings.url));
};
