/**
 * Set-based platform link: no legacy SQL. Synthetic username/email per member; profiles from hwy_members.
 * Run repair-legacy-usernames + migrate-sample (legacy mode) later for real membership numbers / photos.
 *
 *   set HWY_ETL_PLATFORM_USERS_MODE=bulk && npm run hwy:etl:platform-users
 */
import sql from 'mssql';
import { connectMssqlControlPlane } from '../hwy-phase1/hwyDataSource';
import { HWY_INDIVIDUAL_PERSON_TYPE_CODE } from './legacyMaps';

const PAGE = Math.max(500, Number(process.env.HWY_ETL_PLATFORM_USER_PAGE ?? 15000) || 15000);
const TURBO = process.env.HWY_ETL_PLATFORM_BULK_TURBO !== '0';
const DISABLED_HASH = '$2b$10$abcdefghijklmnopqrstuuDISABLEDACCOUNTPLACEHOLDER12';

const bulkUsername = (memberId: number): string => `hwy-m-${memberId}`;
const bulkEmail = (memberId: number): string => `member-${memberId}@sample.hawiety.local`;

export async function migrateBulkPlatformUsers(
  memberIds?: number[],
  options?: { closePools?: boolean },
): Promise<{ linked: number; createdUsers: number; createdProfiles: number }> {
  const local = await connectMssqlControlPlane();
  let linked = 0;
  let createdUsers = 0;
  let createdProfiles = 0;

  const idFilter = memberIds?.length
    ? `AND m.id IN (${memberIds.map((_, i) => `@mid${i}`).join(', ')})`
    : '';

  try {
    const countReq = local.request();
    memberIds?.forEach((id, i) => countReq.input(`mid${i}`, sql.BigInt, id));
    const pendingSql = `
      SELECT COUNT(*) AS c FROM dbo.hwy_members m
      WHERE (
        m.user_id IS NULL
        OR NOT EXISTS (SELECT 1 FROM dbo.base_user_profiles p WHERE p.user_id = m.user_id)
      ) ${idFilter}
    `;
    const totalPending = Number((await countReq.query(pendingSql)).recordset[0].c);
    console.log(`[hwy:etl:platform-users:bulk] pending: ${totalPending} | turbo=${TURBO && !memberIds?.length}`);

    if (TURBO && !memberIds?.length && totalPending > 0) {
      const tx = new sql.Transaction(local);
      await tx.begin();
      const txReq = () => new sql.Request(tx);
      try {
        const ins = await txReq()
          .input('hash', sql.NVarChar(1000), DISABLED_HASH)
          .query(`
            INSERT INTO dbo.base_users (username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
            SELECT
              N'hwy-m-' + CAST(m.id AS nvarchar(20)),
              N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local',
              @hash, 0, 0, 0, m.phone1, SYSUTCDATETIME(), SYSUTCDATETIME()
            FROM dbo.hwy_members m
            WHERE m.user_id IS NULL
              AND NOT EXISTS (
                SELECT 1 FROM dbo.base_users u
                WHERE u.email = N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local'
              );
            SELECT @@ROWCOUNT AS inserted;
          `);
        createdUsers = Number((ins.recordset[0] as { inserted: number }).inserted ?? 0);

        const link = await txReq().query(`
            UPDATE m SET user_id = u.id, updated_at = SYSUTCDATETIME()
            FROM dbo.hwy_members m
            INNER JOIN dbo.base_users u
              ON u.email = N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local'
            WHERE m.user_id IS NULL;
            SELECT @@ROWCOUNT AS linked;
          `);
        linked = Number((link.recordset[0] as { linked: number }).linked ?? 0);

        const prof = await txReq()
          .input('ptype', sql.NVarChar(1000), HWY_INDIVIDUAL_PERSON_TYPE_CODE)
          .query(`
            MERGE dbo.base_user_profiles AS t
            USING (
              SELECT m.user_id, m.first_name AS fn, m.family_name AS ln, m.father_name AS fan,
                m.grandfather_name AS gfn, m.nickname AS nick, m.national_id AS nat,
                CAST(m.birth_year AS nvarchar(32)) AS birth_y, CAST(m.birth_month AS nvarchar(32)) AS bm,
                CAST(m.birth_day AS nvarchar(32)) AS bd, m.gender_code AS gen, m.phone1 AS phone
              FROM dbo.hwy_members m WHERE m.user_id IS NOT NULL
            ) AS s ON t.user_id = s.user_id
            WHEN MATCHED THEN UPDATE SET
              firstname = s.fn, lastname = s.ln, fathername = s.fan, grandfathername = s.gfn,
              nickname = s.nick, national_code = s.nat, birth_year = s.birth_y, birth_month = s.bm, birth_day = s.bd,
              gender_code = s.gen, person_type_code = @ptype, phone = s.phone, updated_at = SYSUTCDATETIME()
            WHEN NOT MATCHED THEN INSERT (
              user_id, firstname, lastname, fathername, grandfathername, nickname, national_code,
              birth_year, birth_month, birth_day, gender_code, person_type_code, phone, created_at, updated_at
            ) VALUES (
              s.user_id, s.fn, s.ln, s.fan, s.gfn, s.nick, s.nat, s.birth_y, s.bm, s.bd, s.gen, @ptype, s.phone,
              SYSUTCDATETIME(), SYSUTCDATETIME()
            );
            SELECT @@ROWCOUNT AS merged;
          `);
        createdProfiles = Number((prof.recordset[0] as { merged: number }).merged ?? 0);
        await tx.commit();
        console.log(`[hwy:etl:platform-users:bulk] turbo done | linked ${linked} | users +${createdUsers}`);
        return { linked, createdUsers, createdProfiles };
      } catch (err) {
        await tx.rollback();
        throw err;
      }
    }

    let lastId = 0;
    while (true) {
      const pageReq = local.request()
        .input('lastId', sql.BigInt, lastId)
        .input('take', sql.Int, PAGE)
        .input('hash', sql.NVarChar(1000), DISABLED_HASH)
        .input('ptype', sql.NVarChar(1000), HWY_INDIVIDUAL_PERSON_TYPE_CODE);
      memberIds?.forEach((id, i) => pageReq.input(`mid${i}`, sql.BigInt, id));

      const batch = (await pageReq.query(`
        SELECT TOP (@take) m.id
        FROM dbo.hwy_members m
        WHERE m.id > @lastId ${idFilter}
          AND (
            m.user_id IS NULL
            OR NOT EXISTS (SELECT 1 FROM dbo.base_user_profiles p WHERE p.user_id = m.user_id)
          )
        ORDER BY m.id
      `)).recordset as Array<{ id: number }>;
      if (!batch.length) break;

      const minId = Number(batch[0].id);
      const maxId = Number(batch[batch.length - 1].id);
      const tx = new sql.Transaction(local);
      await tx.begin();
      const txReq = () => new sql.Request(tx);

      try {
        const ins = await txReq()
          .input('minId', sql.BigInt, minId)
          .input('maxId', sql.BigInt, maxId)
          .input('hash', sql.NVarChar(1000), DISABLED_HASH)
          .query(`
            INSERT INTO dbo.base_users (username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
            SELECT
              N'hwy-m-' + CAST(m.id AS nvarchar(20)),
              N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local',
              @hash,
              0, 0, 0,
              m.phone1,
              SYSUTCDATETIME(), SYSUTCDATETIME()
            FROM dbo.hwy_members m
            WHERE m.user_id IS NULL
              AND m.id >= @minId AND m.id <= @maxId
              AND NOT EXISTS (
                SELECT 1 FROM dbo.base_users u
                WHERE u.email = N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local'
              );
            SELECT @@ROWCOUNT AS inserted;
          `);
        const insertedUsers = Number((ins.recordset[0] as { inserted: number }).inserted ?? 0);
        createdUsers += insertedUsers;

        const link = await txReq()
          .input('minId', sql.BigInt, minId)
          .input('maxId', sql.BigInt, maxId)
          .query(`
            UPDATE m SET
              user_id = u.id,
              updated_at = SYSUTCDATETIME()
            FROM dbo.hwy_members m
            INNER JOIN dbo.base_users u
              ON u.email = N'member-' + CAST(m.id AS nvarchar(20)) + N'@sample.hawiety.local'
            WHERE m.user_id IS NULL
              AND m.id >= @minId AND m.id <= @maxId;
            SELECT @@ROWCOUNT AS linked;
          `);
        const linkedBatch = Number((link.recordset[0] as { linked: number }).linked ?? 0);
        linked += linkedBatch;

        const prof = await txReq()
          .input('minId', sql.BigInt, minId)
          .input('maxId', sql.BigInt, maxId)
          .input('ptype', sql.NVarChar(1000), HWY_INDIVIDUAL_PERSON_TYPE_CODE)
          .query(`
            MERGE dbo.base_user_profiles AS t
            USING (
              SELECT
                m.user_id,
                m.first_name AS fn,
                m.family_name AS ln,
                m.father_name AS fan,
                m.grandfather_name AS gfn,
                m.nickname AS nick,
                m.national_id AS nat,
                CAST(m.birth_year AS nvarchar(32)) AS birth_y,
                CAST(m.birth_month AS nvarchar(32)) AS bm,
                CAST(m.birth_day AS nvarchar(32)) AS bd,
                m.gender_code AS gen,
                m.phone1 AS phone
              FROM dbo.hwy_members m
              WHERE m.user_id IS NOT NULL
                AND m.id >= @minId AND m.id <= @maxId
            ) AS s ON t.user_id = s.user_id
            WHEN MATCHED THEN UPDATE SET
              firstname = s.fn, lastname = s.ln, fathername = s.fan, grandfathername = s.gfn,
              nickname = s.nick, national_code = s.nat,
              birth_year = s.birth_y, birth_month = s.bm, birth_day = s.bd,
              gender_code = s.gen, person_type_code = @ptype, phone = s.phone,
              updated_at = SYSUTCDATETIME()
            WHEN NOT MATCHED THEN INSERT (
              user_id, firstname, lastname, fathername, grandfathername, nickname, national_code,
              birth_year, birth_month, birth_day, gender_code, person_type_code, phone,
              created_at, updated_at
            ) VALUES (
              s.user_id, s.fn, s.ln, s.fan, s.gfn, s.nick, s.nat,
              s.birth_y, s.bm, s.bd, s.gen, @ptype, s.phone,
              SYSUTCDATETIME(), SYSUTCDATETIME()
            );
            SELECT @@ROWCOUNT AS merged;
          `);
        createdProfiles += Number((prof.recordset[0] as { merged: number }).merged ?? 0);

        await tx.commit();
      } catch (err) {
        await tx.rollback();
        throw err;
      }

      lastId = maxId;
      console.log(
        `[hwy:etl:platform-users:bulk] through id ${lastId} | linked total ${linked} | users +${createdUsers} profiles touched ${createdProfiles}`,
      );
    }

    return { linked, createdUsers, createdProfiles };
  } finally {
    if (options?.closePools !== false) {
      await local.close();
    }
  }
}

export { bulkUsername, bulkEmail };
