import { migrateBulkPlatformUsers } from './migrate-platform-users-bulk';
import { migrateSamplePlatformUsers } from './migrate-sample-platform-users';

export type PlatformUsersMode = 'bulk' | 'legacy';

/** Bulk = synthetic platform identity from local hwy_members only (minutes). Legacy = per-member legacy fetch (hours). */
export function resolvePlatformUsersMode(): PlatformUsersMode {
  const explicit = process.env.HWY_ETL_PLATFORM_USERS_MODE?.trim().toLowerCase();
  if (explicit === 'bulk' || explicit === 'legacy') return explicit;
  if (process.env.HWY_ETL_FULL === '1') return 'bulk';
  return 'legacy';
}

export async function migratePlatformUsers(
  memberIds?: number[],
  options?: { closePools?: boolean },
): Promise<{ linked: number; createdUsers: number; createdProfiles: number; mode: PlatformUsersMode }> {
  const mode = resolvePlatformUsersMode();
  if (mode === 'bulk') {
    const result = await migrateBulkPlatformUsers(memberIds, options);
    return { ...result, mode };
  }
  const result = await migrateSamplePlatformUsers(memberIds, options);
  return { ...result, mode };
}
