import {
  HWY_INTERVIEW_2022_HAZER_ALLOWED_ROLE_IDS,
  HWY_INTERVIEW_2022_SCORE_PARENT_ID,
  validateHwyCandidatePipelineInterviewCreate,
  type HwyCandidatePipelineInterviewCreatePayload,
  type HwyCandidatePipelineInterviewRecord,
  type HwyInterview2022HazerinMember,
} from '../../../domain/hwy/hwyCandidatePipelineInterviewCatalog';
import { HWY_INTERVIEW_FINAL_RESULT_OPTIONS } from '../../../domain/hwy/hwyCandidatePipelineUiConstants';
import { assertHwyCandidatePipelineStageAccess } from './hwyCandidatePipelineAccess.service';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { listLegacyHwyBaseInformationByParent } from './hwyLegacyBaseInformationReader';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { QueryTypes } from 'sequelize';
import { mapHwyCandidatePipelineInterviewRow } from './hwyCandidatePipelineInterviewMapper';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy candidate pipeline requires SQL Server control plane.');
  }
};

const validFinalResults = new Set(HWY_INTERVIEW_FINAL_RESULT_OPTIONS.map((o) => o.value));

export const listHwyInterview2022ScoreOptions = async (
  roleNames: readonly string[],
): Promise<{ id: string; title: string }[]> => {
  await assertHwyCandidatePipelineStageAccess('interview', roleNames);
  const rows = await listLegacyHwyBaseInformationByParent(HWY_INTERVIEW_2022_SCORE_PARENT_ID);
  return rows
    .map((row) => ({ id: String(row.id), title: row.title }))
    .sort((a, b) => Number(a.id) - Number(b.id));
};

export const getHwyCandidatePipelineInterviewLast = async (
  memberId: string,
  roleNames: readonly string[],
): Promise<HwyCandidatePipelineInterviewRecord | null> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess('interview', roleNames);
  await ensureHwyDbObjects();

  const id = trim(memberId);
  if (!id) {
    throw new Error('memberId is required.');
  }

  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_candidate_pipeline_interview_last', {
    member_id: Number(id),
  });
  const row = rows[0];
  if (!row?.interviewId) {
    return null;
  }
  return mapHwyCandidatePipelineInterviewRow(row);
};

export type HwyInterview2022HazerinLookupResult = {
  member: HwyInterview2022HazerinMember;
  roleIds: number[];
};

export const lookupHwyInterview2022HazerinMember = async (
  username: string,
  actorUsername: string | null | undefined,
  roleNames: readonly string[],
): Promise<HwyInterview2022HazerinLookupResult> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess('interview', roleNames);

  const uname = trim(username);
  if (!/^\d{6}$/.test(uname)) {
    throw new Error('Membership number must be exactly 6 digits.');
  }
  const actor = trim(actorUsername);
  if (actor && actor === uname) {
    throw new Error('You are already the interview operator; do not add your own membership number.');
  }

  const sequelize = getControlPlaneSequelize();
  const memberRows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT TOP 1
      CAST(M.Id AS VARCHAR(32)) AS memberId,
      M.UserName AS username,
      M.FirstName AS firstName,
      M.FatherName AS fatherName,
      M.GrandFatherName AS grandFatherName,
      M.LastName AS lastName,
      M.UserId AS userId
    FROM dbo.HWY_Members M WITH (NOLOCK)
    WHERE M.UserName = :username
    `,
    { replacements: { username: uname }, type: QueryTypes.SELECT },
  );
  const memberRow = memberRows[0];
  if (!memberRow?.memberId) {
    throw new Error('Membership number was not found.');
  }

  const userId = memberRow.userId != null ? String(memberRow.userId) : '';
  let roleIds: number[] = [];
  if (userId) {
    const roleRows = await sequelize.query<Record<string, unknown>>(
      `
      SELECT URR.RoleId AS roleId
      FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK)
      WHERE URR.UserId = :userId
      `,
      { replacements: { userId: Number(userId) }, type: QueryTypes.SELECT },
    );
    roleIds = roleRows.map((r) => Number(r.roleId)).filter((n) => Number.isFinite(n));
  }

  const allowed = HWY_INTERVIEW_2022_HAZER_ALLOWED_ROLE_IDS;
  if (!roleIds.some((id) => allowed.includes(id))) {
    throw new Error(
      'This member cannot join the committee — allowed roles are organization, electoral office, supervisory office, or Hawiety system roles.',
    );
  }

  return {
    member: {
      memberId: trim(memberRow.memberId as string),
      username: memberRow.username ? trim(memberRow.username as string) : null,
      firstName: memberRow.firstName ? trim(memberRow.firstName as string) : null,
      fatherName: memberRow.fatherName ? trim(memberRow.fatherName as string) : null,
      grandFatherName: memberRow.grandFatherName ? trim(memberRow.grandFatherName as string) : null,
      lastName: memberRow.lastName ? trim(memberRow.lastName as string) : null,
    },
    roleIds,
  };
};

export const applyHwyCandidatePipelineInterviewCreateFull = async (
  input: HwyCandidatePipelineInterviewCreatePayload,
  actorUsername: string | null | undefined,
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertHwyCandidatePipelineStageAccess('interview', roleNames);
  await ensureHwyDbObjects();

  const hazerinRoleIdsByMember = new Map<string, number[]>();
  const uniqueHazerIds = [...new Set(input.hazerinMemberIds.map((id) => trim(id)).filter(Boolean))];
  for (const hazerId of uniqueHazerIds) {
    const memberRows = await getControlPlaneSequelize().query<Record<string, unknown>>(
      `SELECT TOP 1 UserName AS username FROM dbo.HWY_Members WITH (NOLOCK) WHERE Id = :id`,
      { replacements: { id: Number(hazerId) }, type: QueryTypes.SELECT },
    );
    const username = memberRows[0]?.username ? trim(memberRows[0].username as string) : '';
    if (!username) {
      throw new Error(`Committee member ${hazerId} was not found.`);
    }
    const lookup = await lookupHwyInterview2022HazerinMember(username, actorUsername, roleNames);
    hazerinRoleIdsByMember.set(hazerId, lookup.roleIds);
  }

  validateHwyCandidatePipelineInterviewCreate(input, hazerinRoleIdsByMember, validFinalResults);

  const hazerinJson = JSON.stringify(uniqueHazerIds.map((id) => ({ hazer_id: Number(id) })));

  await execHwyProcedure('hwy_candidate_pipeline_interview_create', {
    member_id: Number(trim(input.memberId)),
    interview_on: trim(input.interviewOn),
    karizma: input.karizma,
    like_to_learn_more: input.likeToLearnMore,
    show_is_fan: input.showIsFan,
    ability_to_make_team: input.abilityToMakeTeam,
    ghodrat_elec: input.ghodratElec,
    knows_masoolin: input.knowsMasoolin,
    is_motefaregh: input.isMotefaregh ? 1 : 0,
    is_motefaregh_saat: input.isMotefareghSaat,
    note: trim(input.note),
    final_result: input.finalResult,
    hazerin_json: hazerinJson,
    actor: trim(actorUsername) || null,
  });

  await execHwyProcedure('hwy_member_stat_recalc_interviews_2022_count', {
    member_id: Number(trim(input.memberId)),
  });
};
