import { QueryTypes } from 'sequelize';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';

export type MemberInstituteListRow = {
  memberId: string;
  instituteTitle: string;
};

/** One institute title per line for grid cells. */
export const buildMemberInstitutesSummaryByMemberId = (
  rows: readonly MemberInstituteListRow[],
): Map<string, string> => {
  const titlesByMember = new Map<string, string[]>();
  for (const row of rows) {
    const memberId = row.memberId.trim();
    const title = row.instituteTitle.trim();
    if (!memberId || !title) {
      continue;
    }
    const existing = titlesByMember.get(memberId) ?? [];
    if (!existing.includes(title)) {
      existing.push(title);
    }
    titlesByMember.set(memberId, existing);
  }
  const summaryByMember = new Map<string, string>();
  for (const [memberId, titles] of titlesByMember) {
    summaryByMember.set(memberId, titles.join('\n'));
  }
  return summaryByMember;
};

export async function loadActiveMemberInstituteTitlesForList(
  memberIds: readonly string[],
): Promise<Map<string, string>> {
  if (memberIds.length === 0 || readControlPlaneProvider() !== 'sqlserver') {
    return new Map();
  }
  const ctx = await loadHwyMemberListScopeContext();
  const sequelize = getControlPlaneSequelize();
  const queryRows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
      CAST(mi.member_id AS VARCHAR(32)) AS memberId,
      i.title_ar AS instituteTitle
    FROM dbo.hwy_member_institutes mi
    INNER JOIN dbo.hwy_institutes i ON i.id = mi.institute_id
    WHERE mi.member_id IN (:memberIds)
      AND mi.status_code = :activeStatus
    ORDER BY mi.member_id, i.title_ar, mi.institute_id
    `,
    {
      replacements: {
        memberIds: [...memberIds],
        activeStatus: ctx.instituteMembershipActiveCode,
      },
      type: QueryTypes.SELECT,
    },
  );
  const mapped = queryRows.map((row) => ({
    memberId: String(row.memberId ?? '').trim(),
    instituteTitle: String(row.instituteTitle ?? '').trim(),
  }));
  return buildMemberInstitutesSummaryByMemberId(mapped);
}
