import { QueryTypes, type Transaction } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

export type HwyProcedureReplacements = Record<string, unknown>;

/** Execute a dbo.hwy_* stored procedure with named parameters (Sequelize → mssql). */
export async function execHwyProcedure<T extends Record<string, unknown>>(
  procedureName: string,
  replacements: HwyProcedureReplacements,
  options?: { transaction?: Transaction },
): Promise<T[]> {
  const keys = Object.keys(replacements);
  const argList = keys.map((key) => `@${key} = :${key}`).join(', ');
  const sql = argList.length
    ? `EXEC dbo.${procedureName} ${argList}`
    : `EXEC dbo.${procedureName}`;
  const sequelize = getControlPlaneSequelize();
  return sequelize.query<T>(sql, {
    replacements,
    type: QueryTypes.SELECT,
    transaction: options?.transaction,
  });
}
