import { SETTINGS_PATH } from '../../../src/server/config/settingsFile';
import { readControlPlaneDatabaseSettings } from '../../../src/server/db/controlPlaneDatabase';
import { prisma } from '../../../src/server/domain/users/prismaHelpers';
import type { GeoLegacyKind } from './constants';
import { HWY_ETL_GEO_MAP_TABLE } from './ensureGeoMapTable';

const assertKind = (kind: GeoLegacyKind): void => {
  if (!/^[a-z]+$/.test(kind)) {
    throw new Error(`Invalid geo legacy kind: ${kind}`);
  }
};

export async function upsertGeoMapRow(input: {
  kind: GeoLegacyKind;
  legacyId: number;
  legacySecondaryId: number;
  baseInfoId: string;
  legacyHwyStateId?: number | null;
  importBatch: string;
}): Promise<void> {
  assertKind(input.kind);
  const legacyId = Math.trunc(input.legacyId);
  const legacySecondaryId = Math.trunc(input.legacySecondaryId);
  const baseInfoId = input.baseInfoId.replace(/'/g, "''");
  const importBatch = input.importBatch.replace(/'/g, "''");
  const stateId = input.legacyHwyStateId == null ? 'NULL' : String(Math.trunc(input.legacyHwyStateId));

  const { provider } = readControlPlaneDatabaseSettings(SETTINGS_PATH);

  if (provider === 'sqlserver') {
    await prisma().$executeRawUnsafe(`
      DELETE FROM dbo.${HWY_ETL_GEO_MAP_TABLE}
      WHERE legacy_kind = N'${input.kind}'
        AND legacy_id = ${legacyId}
        AND legacy_secondary_id = ${legacySecondaryId};

      INSERT INTO dbo.${HWY_ETL_GEO_MAP_TABLE} (
        legacy_kind, legacy_id, legacy_secondary_id, base_info_id, legacy_hwy_state_id, import_batch
      ) VALUES (
        N'${input.kind}', ${legacyId}, ${legacySecondaryId}, N'${baseInfoId}', ${stateId}, N'${importBatch}'
      );
    `);
    return;
  }

  await prisma().$executeRawUnsafe(`
    INSERT INTO ${HWY_ETL_GEO_MAP_TABLE} (
      legacy_kind, legacy_id, legacy_secondary_id, base_info_id, legacy_hwy_state_id, import_batch
    ) VALUES (
      '${input.kind}', ${legacyId}, ${legacySecondaryId}, '${baseInfoId}', ${stateId === 'NULL' ? 'NULL' : stateId}, '${importBatch}'
    )
    ON CONFLICT (legacy_kind, legacy_id, legacy_secondary_id)
    DO UPDATE SET
      base_info_id = EXCLUDED.base_info_id,
      legacy_hwy_state_id = EXCLUDED.legacy_hwy_state_id,
      import_batch = EXCLUDED.import_batch
  `);
}

/** Load full map into memory for sample ETL. */
export async function loadGeoBaseInfoIdMap(): Promise<Map<string, string>> {
  const rows = await prisma().$queryRawUnsafe<Array<{
    legacy_kind: string;
    legacy_id: bigint | number;
    legacy_secondary_id: bigint | number;
    base_info_id: string;
  }>>(`SELECT legacy_kind, legacy_id, legacy_secondary_id, base_info_id FROM ${HWY_ETL_GEO_MAP_TABLE}`);

  const map = new Map<string, string>();
  for (const row of rows) {
    const kind = String(row.legacy_kind);
    const legacyId = Number(row.legacy_id);
    const secondary = Number(row.legacy_secondary_id);
    map.set(`${kind}:${legacyId}:${secondary}`, String(row.base_info_id));
  }
  return map;
}

export function resolveGeoBaseInfoId(
  map: Map<string, string>,
  kind: GeoLegacyKind,
  legacyId: number | null | undefined,
  legacySecondaryId = 0,
): string | null {
  if (legacyId == null || !Number.isFinite(legacyId)) return null;
  return map.get(`${kind}:${legacyId}:${legacySecondaryId}`) ?? null;
}
