import { readControlPlaneProvider } from '../users/prismaHelpers';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import type { HwyMemberListFace } from '../../../domain/hwy/hwyMemberListFace';
import { mapHwyMemberListFaceFromVmFields } from './hwyMemberListFaceMap';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

export type HwyMemberPickerRow = HwyMemberListFace;

const MAX_LIMIT = 25;

export async function searchHwyMemberPicker(input: {
  qRaw: string;
  limit?: number;
  /** Reserved for purpose-specific filters (nomination gates vs open pick). */
  purpose?: string;
  session?: SessionScopeSnapshot | null;
}): Promise<HwyMemberPickerRow[]> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  await ensureHwyDbObjects();
  const q = trim(input.qRaw);
  if (q.length < 1) {
    return [];
  }
  const limit = Math.min(MAX_LIMIT, Math.max(1, Number(input.limit) || 15));
  const safeQ = q.replace(/[%_\[\]]/g, '');
  const likeQ = `%${safeQ}%`;
  const prefixQ = `${safeQ}%`;
  const exactQ = q;

  const rows = await execHwyProcedure<{
    id: string | number;
    username: string | null;
    display_full_name: string | null;
    avatar_url: string | null;
    user_id: number | string | null;
    gender_code: string | null;
    phone1: string | null;
    has_profile_image: boolean | number | null;
  }>('hwy_member_picker_search', {
    limit,
    like_q: likeQ,
    prefix_q: prefixQ,
    exact_q: exactQ,
  });

  const maskedRows: Record<string, unknown>[] = rows.map((row) => ({
    id: row.id,
    username: row.username,
    displayFullName: row.display_full_name,
    avatarUrl: row.avatar_url,
    userId: row.user_id,
    genderCode: row.gender_code,
    phone1: row.phone1,
    hasProfileImage: row.has_profile_image,
  }));
  await applyHwyMemberIdentityFieldMasksToRows(
    getControlPlaneSequelize(),
    maskedRows,
    input.session ?? null,
  );

  return maskedRows
    .map((row) => mapHwyMemberListFaceFromVmFields({
      id: row.id as string | number,
      username: row.username as string | null,
      displayFullName: row.displayFullName as string | null,
      avatarUrl: row.avatarUrl as string | null,
      userId: row.userId as number | string | null,
      genderCode: row.genderCode as string | null,
      phone: row.phone1 as string | null,
      hasProfileImage: row.hasProfileImage as boolean | number | null,
    }))
    .filter((face): face is HwyMemberPickerRow => face != null);
}
