import type { HwyMemberStatRecalcStepId } from './hwyMemberStatsRecalcCatalog';

const asInt = (value: unknown): number | null => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const n = Number(value);
  return Number.isFinite(n) ? Math.trunc(n) : null;
};

const asBit = (value: unknown): 0 | 1 | null => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  if (value === true || value === 1 || value === '1') {
    return 1;
  }
  if (value === false || value === 0 || value === '0') {
    return 0;
  }
  return null;
};

const formatCount = (value: unknown): string => {
  const n = asInt(value);
  return n === null ? '—' : String(n);
};

export type HwyMemberStatRow = Record<string, unknown>;

export const pickHwyMemberStatRowValue = (row: HwyMemberStatRow, ...keys: string[]): unknown => {
  for (const key of keys) {
    if (key in row && row[key] !== undefined) {
      return row[key];
    }
    const lower = key.toLowerCase();
    for (const [entryKey, entryValue] of Object.entries(row)) {
      if (entryKey.toLowerCase() === lower && entryValue !== undefined) {
        return entryValue;
      }
    }
  }
  return undefined;
};

export const formatHwyMemberStatRecalcStepDisplayValue = (
  stepId: HwyMemberStatRecalcStepId,
  row: HwyMemberStatRow | null | undefined,
): string => {
  if (!row) {
    return '—';
  }
  const pick = (...keys: string[]): unknown => pickHwyMemberStatRowValue(row, ...keys);

  switch (stepId) {
    case 'profile_fields': {
      const n = asInt(pick('statFieldsCompleted', 'Stat_FieldsCompleted'));
      return n === null ? '—' : `${n}%`;
    }
    case 'membership_days':
      return formatCount(pick('statDays', 'Stat_Days'));
    case 'dorat_count':
      return formatCount(pick('statDoratCount', 'Stat_DoratCount'));
    case 'kasb_count':
      return formatCount(pick('statKasbCount', 'Stat_KasbCount'));
    case 'nashatat_count':
      return formatCount(pick('statNashatatCount', 'Stat_NashatatCount'));
    case 'moassesat_count':
      return formatCount(pick('statMoassesatCount', 'Stat_Moassesat_Count'));
    case 'interviews_2022_count':
      return formatCount(pick('statInterviews2022Count', 'Stat_Moghabelat_2022_Count'));
    case 'cards_count':
      return formatCount(pick('statCardsCount', 'Stat_CardsCount'));
    case 'has_passed_all':
      return formatCount(asBit(pick('statHasPassedAll', 'Stat2_HasPassedAll', 'Stat_HasPassedAll')));
    case 'has_not_tosigh_older_than_x_days':
      return formatCount(
        asBit(
          pick(
            'statHasNotTosighOlderThanXDays',
            'Stat2_HasNotTosighOlderThanXDays',
            'Stat_HasNotTosighOlderThanXDays',
          ),
        ),
      );
    case 'document_assets':
      return formatCount(pick('statVasaeghCount', 'Stat_Vasaegh_Count'));
    case 'employee_flag':
      return formatCount(asBit(pick('statIsEmployee', 'Stat_IsEmployee')));
    case 'area_mismatch_count':
      return formatCount(pick('statAdamTatbighCount', 'Stat_AdamTatbighCount'));
    case 'points':
      return formatCount(pick('statPoints', 'Stat_Points'));
    default:
      return '—';
  }
};
