import {
  buildHwyMemberListRouteAllowRoles,
  legacyHwyActionKey,
  type HwyLegacyControllerAction,
} from './hwyMemberListLegacyAccess';
import {
  HWY_CANDIDATE_PIPELINE_STAGES,
  type HwyCandidatePipelineStage,
} from './hwyCandidatePipelineCatalog';

const readMembers = (method: string): HwyLegacyControllerAction => ({
  controller: 'HWY_Members',
  method,
});

export const HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ: Record<
  HwyCandidatePipelineStage,
  HwyLegacyControllerAction
> = {
  security: readMembers('Read_Employees_SecurityStatuses'),
  interview: readMembers('Read_Employees_InterviewManagement'),
  courses: readMembers('Read_Employees_PassedNecessaryDoratManagement'),
  install: readMembers('Read_Employees_ToApproveResponsibility'),
};

export const HWY_CANDIDATE_PIPELINE_STAGE_TO_PAGE_KEY: Record<HwyCandidatePipelineStage, string> =
  Object.fromEntries(
    HWY_CANDIDATE_PIPELINE_STAGES.map((def) => [def.stage, def.pageKey]),
  ) as Record<HwyCandidatePipelineStage, string>;

export const resolveHwyCandidatePipelinePageLegacyReadAction = (
  pageKey: string,
): HwyLegacyControllerAction | null => {
  const stage = HWY_CANDIDATE_PIPELINE_STAGES.find((def) => def.pageKey === pageKey);
  return stage ? HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ[stage.stage] : null;
};

export const resolveHwyCandidatePipelineStageLegacyReadAction = (
  stage: HwyCandidatePipelineStage,
): HwyLegacyControllerAction => HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ[stage];

export const buildHwyCandidatePipelinePortalAllowRoles = (
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const merged = new Set<string>();
  for (const action of Object.values(HWY_CANDIDATE_PIPELINE_STAGE_LEGACY_READ)) {
    for (const role of rolesByAction.get(legacyHwyActionKey(action)) ?? []) {
      merged.add(role);
    }
  }
  return buildHwyMemberListRouteAllowRoles([...merged]);
};

export const buildHwyCandidatePipelineStageAllowRoles = (
  stage: HwyCandidatePipelineStage,
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const action = resolveHwyCandidatePipelineStageLegacyReadAction(stage);
  const roles = rolesByAction.get(legacyHwyActionKey(action)) ?? [];
  return buildHwyMemberListRouteAllowRoles(roles);
};
