export type HwyMemberListScopeContext = {
  membershipStatusCodes: Record<
    | 'pending_call_center'
    | 'pending_local'
    | 'active'
    | 'rejected_call_center'
    | 'rejected_local'
    | 'rejected_local_verification',
    string
  >;
  instituteMembershipActiveCode: string;
};

let cachedScopeContext: HwyMemberListScopeContext | null = null;

const MEMBERSHIP_STATUS_SPECS = [
  ['pending_call_center', 'pending_call_center'],
  ['pending_local', 'pending_local'],
  ['active', 'active'],
  ['rejected_call_center', 'rejected_call_center'],
  ['rejected_local', 'rejected_local'],
  ['rejected_local_verification', 'rejected_local_verification'],
] as const;

export const loadHwyMemberListScopeContext = async (): Promise<HwyMemberListScopeContext> => {
  if (cachedScopeContext) {
    return cachedScopeContext;
  }
  const membershipEntries = await Promise.all(
    MEMBERSHIP_STATUS_SPECS.map(async ([key, shortName]) => {
      const id = await findHwyBaseInfoItemIdByShortName('Membership Status', shortName);
      return [key, id] as const;
    }),
  );
  const instituteMembershipActive = await findHwyBaseInfoItemIdByShortName(
    'Institute Membership Status',
    'active',
  );
  cachedScopeContext = {
    membershipStatusCodes: Object.fromEntries(membershipEntries) as HwyMemberListScopeContext['membershipStatusCodes'],
    instituteMembershipActiveCode: instituteMembershipActive,
  };
  return cachedScopeContext;
};

export const parseHwyMemberDirectoryListScopeQuery = (
  query: Record<string, unknown>,
): string | null => {
  const raw = query.listScope ?? query.listDefLegacy;
  if (typeof raw !== 'string') {
    return null;
  }
  let trimmed = raw.trim();
  if (trimmed.length === 0) {
    return null;
  }
  if (trimmed.startsWith('static:')) {
    trimmed = trimmed.slice('static:'.length).trim();
    if (!trimmed) {
      return null;
    }
  }
  return normalizeHwyMemberListScopeLegacyCode(trimmed);
};

const memberInstitutesTable = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql' ? 'dbo.hwy_member_institutes' : 'hwy_member_institutes'
);

/** Semi-join via IN (uses idx on institute_id + status_code) — faster than correlated EXISTS on the view. */
const instituteMemberIdInSubquery = (
  sequelize: Sequelize,
  instituteId: number,
  instituteStatusCode: string,
): ReturnType<typeof sequelize.literal> => {
  const table = memberInstitutesTable(sequelize);
  const indexHint = sequelize.getDialect() === 'mssql'
    ? ' WITH (INDEX(idx_hwy_member_institutes_scope))'
    : '';
  return sequelize.literal(
    `(SELECT mi.member_id FROM ${table} mi${indexHint}
      WHERE mi.institute_id = ${instituteId}
        AND mi.status_code = ${sequelize.escape(instituteStatusCode)})`,
  );
};

const instituteMemberIdsAtInstituteSubquery = (
  sequelize: Sequelize,
  instituteId: number,
): ReturnType<typeof sequelize.literal> => {
  const table = memberInstitutesTable(sequelize);
  return sequelize.literal(
    `(SELECT mi.member_id FROM ${table} mi WHERE mi.institute_id = ${instituteId})`,
  );
};

/** Legacy `EducationLevelId=10862` on `Read_List_AlMontazemin_TalebJameee` (title «طلاب جامعيون»). */
const LEGACY_TALEB_JAMEEE_EDUCATION_LEVEL_ID = 10862;

const hemamApprovedMemberIdsSubquery = (
  sequelize: Sequelize,
  instituteId: number,
): ReturnType<typeof sequelize.literal> => {
  const table = memberInstitutesTable(sequelize);
  const accepted = sequelize.getDialect() === 'mssql' ? 'mi.member_accepted = 1' : 'mi.member_accepted IS TRUE';
  return sequelize.literal(
    `(SELECT mi.member_id FROM ${table} mi WHERE mi.institute_id = ${instituteId} AND ${accepted})`,
  );
};

const platformUserIdsWithRolesSubquery = (sequelize: Sequelize): ReturnType<typeof sequelize.literal> => {
  const table = sequelize.getDialect() === 'mssql' ? 'dbo.base_user_roles' : 'base_user_roles';
  return sequelize.literal(`(SELECT ur.user_id FROM ${table} ur WHERE ur.user_id IS NOT NULL)`);
};

const membersTable = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql' ? 'dbo.hwy_members' : 'hwy_members'
);

const memberFilesTable = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql' ? 'dbo.hwy_member_files' : 'hwy_member_files'
);

export const loadImageFixTodoFileKindCodes = async (): Promise<string[]> => {
  const ids = await Promise.all(
    HWY_MEMBER_IMAGE_FIX_TODO_FILE_KIND_SLUGS.map((slug) => (
      tryFindHwyBaseInfoItemIdByShortName('Member File Kind', slug)
    )),
  );
  return ids.map((id) => String(id ?? '').trim()).filter(Boolean);
};

/** Semi-join on dbo.hwy_members (legacy Todo queue — avoids correlated EXISTS on the view). */
export const imageFixTodoMemberIdsSubquery = (
  sequelize: Sequelize,
  membershipStatusCodes: readonly string[],
  otherPortalChannelCode: string | null,
  fileKindCodes: readonly string[],
): ReturnType<typeof sequelize.literal> => {
  if (membershipStatusCodes.length === 0 || fileKindCodes.length === 0) {
    return sequelize.literal('(SELECT NULL WHERE 1 = 0)');
  }
  const members = membersTable(sequelize);
  const files = memberFilesTable(sequelize);
  const statusIn = membershipStatusCodes.map((code) => sequelize.escape(code)).join(', ');
  const kindIn = fileKindCodes.map((code) => sequelize.escape(code)).join(', ');
  const channelFilter = otherPortalChannelCode
    ? `AND COALESCE(m.registration_channel_code, N'') <> ${sequelize.escape(otherPortalChannelCode)}`
    : '';
  const contentPredicate = sequelize.getDialect() === 'mssql'
    ? `ISNULL(f.is_approved, 0) = 0
          AND (
            (f.content IS NOT NULL AND DATALENGTH(f.content) > 0)
            OR (f.thumbnail_content IS NOT NULL AND DATALENGTH(f.thumbnail_content) > 0)
            OR ISNULL(f.size_bytes, 0) > 0
          )`
    : `COALESCE(f.is_approved, FALSE) IS NOT TRUE
          AND (
            (f.content IS NOT NULL AND octet_length(f.content) > 0)
            OR (f.thumbnail_content IS NOT NULL AND octet_length(f.thumbnail_content) > 0)
            OR COALESCE(f.size_bytes, 0) > 0
          )`;
  const auditPendingFilter = sequelize.getDialect() === 'mssql'
    ? 'AND COALESCE(m.nakheb_card_front_check, 0) = 0'
    : 'AND COALESCE(m.nakheb_card_front_check, FALSE) IS NOT TRUE';
  return sequelize.literal(`(
    SELECT m.id FROM ${members} m
    WHERE m.membership_status_code IN (${statusIn})
      ${channelFilter}
      ${auditPendingFilter}
      AND EXISTS (
        SELECT 1 FROM ${files} f
        WHERE f.member_id = m.id
          AND ${contentPredicate}
          AND f.file_kind_code IN (${kindIn})
      )
  )`);
};

export const buildHwyMemberDirectoryListScopeWhere = async (
  sequelize: Sequelize,
  scopeKind: HwyMemberListScopeKind,
): Promise<WhereOptions> => {
  const ctx = await loadHwyMemberListScopeContext();
  switch (scopeKind.type) {
    case 'membership_status':
      return { membershipStatusCode: ctx.membershipStatusCodes[scopeKind.status] };
    case 'active_institute': {
      const instituteId = await resolveHwyMemberListInstituteIdForScope(sequelize, scopeKind.instituteCode);
      const where: WhereOptions = {
        membershipStatusCode: ctx.membershipStatusCodes.active,
        id: {
          [Op.in]: instituteMemberIdsAtInstituteSubquery(sequelize, instituteId),
        },
      };
      if (scopeKind.excludeOtherPortalChannel) {
        const otherPortalChannelCode = await tryFindHwyBaseInfoItemIdByShortName(
          'Registration Channel',
          'other_portal',
        );
        if (otherPortalChannelCode) {
          const regCol = sequelize.getDialect() === 'mssql'
            ? '[VwHwyMembers].[registration_channel_code]'
            : '"VwHwyMembers"."registration_channel_code"';
          return {
            ...where,
            [Op.and]: [
              sequelize.literal(
                `COALESCE(${regCol}, N'') <> ${sequelize.escape(otherPortalChannelCode)}`,
              ),
            ],
          };
        }
      }
      return where;
    }
    case 'pending_local_institute': {
      const instituteId = await resolveHwyMemberListInstituteIdForScope(sequelize, scopeKind.instituteCode);
      return {
        membershipStatusCode: ctx.membershipStatusCodes.pending_local,
        id: {
          [Op.in]: instituteMemberIdInSubquery(
            sequelize,
            instituteId,
            ctx.instituteMembershipActiveCode,
          ),
        },
      };
    }
    case 'under_18_active':
      return {
        membershipStatusCode: ctx.membershipStatusCodes.active,
        [Op.and]: [
          sequelize.literal(
            sequelize.getDialect() === 'mssql'
              ? 'TRY_CAST([VwHwyMembers].[birth_year] AS INT) > YEAR(GETDATE()) - 18'
              : 'CAST(NULLIF(TRIM(CAST("VwHwyMembers"."birth_year" AS TEXT)), \'\') AS INT) > EXTRACT(YEAR FROM CURRENT_DATE)::INT - 18',
          ),
        ],
      };
    case 'university_outside_hemam': {
      const hemamId = resolveHwyMemberListInstituteId('hemam');
      const [educationLevelCode, otherPortalChannelCode] = await Promise.all([
        findHwyBaseInfoItemIdByLegacyCategoryLeafId('Education Level', LEGACY_TALEB_JAMEEE_EDUCATION_LEVEL_ID),
        findHwyBaseInfoItemIdByShortName('Registration Channel', 'other_portal'),
      ]);
      const regCol = sequelize.getDialect() === 'mssql'
        ? '[VwHwyMembers].[registration_channel_code]'
        : '"VwHwyMembers"."registration_channel_code"';
      const where: WhereOptions = {
        membershipStatusCode: ctx.membershipStatusCodes.active,
        educationLevelCode,
        [Op.and]: [
          sequelize.literal(
            `COALESCE(${regCol}, N'') <> ${sequelize.escape(otherPortalChannelCode)}`,
          ),
          {
            userId: {
              [Op.notIn]: platformUserIdsWithRolesSubquery(sequelize),
            },
          },
        ],
      };
      if (hemamId != null) {
        (where as Record<string, unknown>).id = {
          [Op.notIn]: hemamApprovedMemberIdsSubquery(sequelize, hemamId),
        };
      }
      return where;
    }
    case 'directory_unrestricted':
      return {};
    case 'registration_image_fix_todo': {
      const [otherPortalChannelCode, fileKindCodes] = await Promise.all([
        tryFindHwyBaseInfoItemIdByShortName('Registration Channel', 'other_portal'),
        loadImageFixTodoFileKindCodes(),
      ]);
      return {
        id: {
          [Op.in]: imageFixTodoMemberIdsSubquery(
            sequelize,
            [ctx.membershipStatusCodes.active, ctx.membershipStatusCodes.pending_local],
            otherPortalChannelCode,
            fileKindCodes,
          ),
        },
      };
    }
    default:
      return {};
  }
};

export const resolveHwyMemberDirectoryListScopeWhere = async (
  sequelize: Sequelize,
  listScopeLegacyCode: string | null,
): Promise<WhereOptions> => {
  if (!listScopeLegacyCode) {
    return {};
  }
  const normalizedScope = normalizeHwyMemberListScopeLegacyCode(listScopeLegacyCode.trim());
  if (normalizedScope === 'HWY_Members_List_All') {
    return buildHwyMemberDirectoryListScopeWhere(sequelize, { type: 'directory_unrestricted' });
  }
  const definition = findHwyMemberSegmentListByLegacyCode(listScopeLegacyCode);
  if (!definition) {
    throw new Error(`Unknown Hawiety member list scope: ${listScopeLegacyCode}`);
  }
  return buildHwyMemberDirectoryListScopeWhere(sequelize, definition.scope);
};
