export type SecurityClearanceStatusTone = 'success' | 'warning' | 'danger' | 'neutral';

export const HWY_SECURITY_CLEARANCE_STATUS_LABEL_KEYS = {
  allowed: 'hwy.securityClearance.status.allowed',
  denied: 'hwy.securityClearance.status.denied',
  pending: 'hwy.securityClearance.status.pending',
  unclear: 'hwy.securityClearance.status.unclear',
} as const;

export type HwySecurityClearanceStatusLabelBucket =
  keyof typeof HWY_SECURITY_CLEARANCE_STATUS_LABEL_KEYS | 'passthrough';

const HWY_SECURITY_CLEARANCE_STATUS_LABEL_FALLBACKS: Record<
  keyof typeof HWY_SECURITY_CLEARANCE_STATUS_LABEL_KEYS,
  string
> = {
  allowed: 'Allowed',
  denied: 'Denied',
  pending: 'Under review',
  unclear: 'Unclear',
};

const isMostlyLatinCatalogText = (text: string): boolean =>
  /^[\x00-\x7F\s.,!?()/\\-]+$/.test(text);

/** Map localized clearance answer titles to semantic status hues (small surfaces only). */
export function resolveSecurityClearanceStatusTone(statusTitle: string): SecurityClearanceStatusTone {
  const normalized = statusTitle.trim().toLowerCase();
  if (!normalized || normalized === '—' || normalized === '-') {
    return 'neutral';
  }
  if (/مسموح|allowed|yes|نعم|موافق|permit/.test(normalized)) {
    return 'success';
  }
  if (/قيد|study|pending|await|مراج|under review/.test(normalized)) {
    return 'warning';
  }
  if (/ممنو|denied|reject|refus|no\b|لا|مرفوض|forbid/.test(normalized)) {
    return 'danger';
  }
  return 'neutral';
}

export const SECURITY_CLEARANCE_STATUS_BADGE_CLASS: Record<SecurityClearanceStatusTone, string> = {
  success: 'border-emerald-200 bg-emerald-50 text-emerald-800',
  warning: 'border-amber-200 bg-amber-50 text-amber-900',
  danger: 'border-rose-200 bg-rose-50 text-rose-800',
  neutral: 'border-slate-200 bg-slate-50 text-slate-700',
};

/** Map legacy/base_info English titles to culture keys; keep Arabic titles as-is. */
export function resolveHwySecurityClearanceStatusLabelBucket(
  rawTitle: string | null | undefined,
): HwySecurityClearanceStatusLabelBucket {
  const trimmed = rawTitle?.trim() ?? '';
  if (!trimmed) {
    return 'unclear';
  }
  const tone = resolveSecurityClearanceStatusTone(trimmed);
  if (tone === 'success') {
    return 'allowed';
  }
  if (tone === 'danger') {
    return 'denied';
  }
  if (tone === 'warning') {
    return 'pending';
  }
  if (isMostlyLatinCatalogText(trimmed)) {
    return 'unclear';
  }
  return 'passthrough';
}

export function formatHwySecurityClearanceStatusLabel(
  rawTitle: string | null | undefined,
  t: (key: string, fallback: string) => string,
): string {
  const trimmed = rawTitle?.trim() ?? '';
  const bucket = resolveHwySecurityClearanceStatusLabelBucket(rawTitle);
  if (bucket === 'passthrough') {
    return trimmed;
  }
  return t(
    HWY_SECURITY_CLEARANCE_STATUS_LABEL_KEYS[bucket],
    HWY_SECURITY_CLEARANCE_STATUS_LABEL_FALLBACKS[bucket],
  );
}
