import { insertBaseInfoNode } from '../base-info/treeRepository';
import { prisma } from '../users/prismaHelpers';
import { invalidateBaseInfoOptionsCache } from '../../services/baseInfoOptionsCache';
import { HWY_BASE_INFO_ROOT_ID } from './hwyBaseInfoRuntime';

const REGISTRATION_CHANNEL_CATEGORY_TITLE = 'Registration Channel';
const STUDIO_STAFF_SHORT_NAME = 'studio_staff';

let ensurePromise: Promise<void> | null = null;

const findRegistrationChannelCategoryId = async (): Promise<string | null> => {
  const row = await prisma().baseInfo.findFirst({
    where: { parentId: HWY_BASE_INFO_ROOT_ID, title: REGISTRATION_CHANNEL_CATEGORY_TITLE },
    select: { id: true },
  });
  return row?.id ?? null;
};

/** Idempotent: ensures `studio_staff` exists under Registration Channel (V2 staff create). */
export const ensureHwyRegistrationChannelStudioStaff = async (): Promise<void> => {
  if (!ensurePromise) {
    ensurePromise = (async () => {
      const categoryId = await findRegistrationChannelCategoryId();
      if (!categoryId) {
        return;
      }
      const existing = await prisma().baseInfo.findFirst({
        where: { parentId: categoryId, shortName: STUDIO_STAFF_SHORT_NAME },
        select: { id: true },
      });
      if (existing?.id) {
        return;
      }
      await insertBaseInfoNode([
        categoryId,
        3,
        'Studio staff create',
        STUDIO_STAFF_SHORT_NAME,
        11,
        null,
        JSON.stringify({ lucideIcon: 'UserPlus' }),
        11,
        true,
        null,
        null,
        null,
        null,
      ]);
      invalidateBaseInfoOptionsCache();
    })();
  }
  await ensurePromise;
};
