import fs from 'node:fs';

const DEFAULT_LEGACY_SETTINGS = 'C:\\Workspace\\Projects\\HawietySite\\HawietySite\\appsettings.json';

export type LegacySqlConfig = {
  server: string;
  database: string;
  user: string;
  password: string;
  options: {
    encrypt: boolean;
    trustServerCertificate: boolean;
    enableArithAbort: boolean;
    /** Tedious connect timeout (ms). Default driver value is 15s — too short for remote legacy. */
    connectTimeout: number;
    requestTimeout: number;
    /** SQL Server ApplicationIntent=ReadOnly — legacy production must never be written. */
    readOnlyIntent: boolean;
  };
  pool: { max: number; min: number; idleTimeoutMillis: number };
};

const pick = (cs: string, re: RegExp): string => ((cs.match(re) || [])[1] ?? '').trim();

export const readLegacyConn = (configPath = process.env.HWY_LEGACY_APPSETTINGS ?? DEFAULT_LEGACY_SETTINGS): LegacySqlConfig => {
  if (!fs.existsSync(configPath)) {
    throw new Error(`Legacy appsettings not found: ${configPath}`);
  }
  const raw = fs.readFileSync(configPath, 'utf8').replace(/^\uFEFF/, '');
  const cfg = JSON.parse(raw) as {
    DataBases?: { AppDB?: { ConnectionString?: string } };
    Databases?: { AppDB?: { ConnectionString?: string } };
  };
  const cs = cfg.DataBases?.AppDB?.ConnectionString ?? cfg.Databases?.AppDB?.ConnectionString ?? '';
  if (!cs) {
    throw new Error('MembersV2 connection string missing in legacy appsettings (AppDB).');
  }
  const trust = /TrustServerCertificate\s*=\s*Yes/i.test(cs);
  return {
    server: pick(cs, /Data Source=([^;]+)/i),
    database: pick(cs, /Initial Catalog=([^;]+)/i),
    user: pick(cs, /User ID=([^;]+)/i),
    password: pick(cs, /Password=([^;]+)/i),
    options: {
      encrypt: trust || /Encrypt\s*=\s*True/i.test(cs),
      trustServerCertificate: true,
      enableArithAbort: true,
      connectTimeout: Math.max(
        15_000,
        Number(process.env.HWY_ETL_LEGACY_CONNECT_TIMEOUT_MS ?? 120_000) || 120_000,
      ),
      requestTimeout: 600_000,
      /** Always read-only — legacy MembersV2 must never receive writes from AppEndO. */
      readOnlyIntent: true,
    },
    pool: { max: 5, min: 0, idleTimeoutMillis: 30_000 },
  };
};

/** Force ApplicationIntent=ReadOnly even if a caller spreads a stale config object. */
export const withLegacyReadOnlyIntent = <T extends LegacySqlConfig>(cfg: T): T => ({
  ...cfg,
  options: { ...cfg.options, readOnlyIntent: true },
});
