export const buildHwyMontadheminInstituteFilterOptionKeysEn = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const def of HWY_MEMBER_SEGMENT_LIST_DEFINITIONS) {
    if (def.scope.type !== 'active_institute') {
      continue;
    }
    const labelKey = hwyMontadheminInstituteFilterOptionLabelKey(def.scope.instituteCode);
    keys[labelKey] = def.titleEn.replace(/^Registered — /, '');
  }
  return keys;
};

export const buildHwyMontadheminInstituteFilterOptionKeysIq = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const def of HWY_MEMBER_SEGMENT_LIST_DEFINITIONS) {
    if (def.scope.type !== 'active_institute') {
      continue;
    }
    const labelKey = hwyMontadheminInstituteFilterOptionLabelKey(def.scope.instituteCode);
    const iq = HWY_MEMBER_SEGMENT_NAV_TITLE_IQ_BY_LEGACY_CODE[def.legacyCode];
    keys[labelKey] = iq ?? def.titleEn.replace(/^Registered — /, '');
  }
  return keys;
};

