import { Op } from 'sequelize';
import type { Sequelize, WhereOptions } from 'sequelize';

import {
  HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEY_TO_KIND_SLUG,
  HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS,
  readHwyMemberImageFixListFiltersFromQuery,
  type HwyMemberImageFixListFilterState,
} from '../../../domain/hwy/hwyMemberImageFixListFilters';
import { normalizeHwyMemberListScopeLegacyCode } from '../../../domain/hwy/hwyMemberListScopeLegacyAliases';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';
import { resolveHwyMemberFileKindBySlugOrId } from './hwyMemberFileKindResolve.service';
import { ensureHwyMemberImageFixEditorSchema } from './ensureHwyMemberImageFixEditorSchema';

const IMAGE_FIX_LIST_SCOPE = 'HWY_Members_List_Imagefix';

const platformUserIdsWithRolesSubquery = (sequelize: Sequelize): ReturnType<typeof sequelize.literal> => {
  const table = sequelize.getDialect() === 'mssql' ? 'dbo.base_user_roles' : 'base_user_roles';
  return sequelize.literal(`(SELECT ur.user_id FROM ${table} ur WHERE ur.user_id IS NOT NULL)`);
};

const memberFilesTable = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql' ? 'dbo.hwy_member_files' : 'hwy_member_files'
);

const memberFileHasContentPredicate = (sequelize: Sequelize): string => (
  sequelize.getDialect() === 'mssql'
    ? `(
      ISNULL(f.size_bytes, 0) > 0
      OR (f.content IS NOT NULL AND DATALENGTH(f.content) > 0)
      OR (f.thumbnail_content IS NOT NULL AND DATALENGTH(f.thumbnail_content) > 0)
    )`
    : `(
      COALESCE(f.size_bytes, 0) > 0
      OR (f.content IS NOT NULL AND octet_length(f.content) > 0)
      OR (f.thumbnail_content IS NOT NULL AND octet_length(f.thumbnail_content) > 0)
    )`
);

export const parseHwyMemberDirectoryImageFixListFilters = (
  query: Record<string, unknown>,
  listScopeLegacy: string | null,
): HwyMemberImageFixListFilterState | null => {
  if (normalizeHwyMemberListScopeLegacyCode(listScopeLegacy ?? '') !== IMAGE_FIX_LIST_SCOPE) {
    return null;
  }
  return readHwyMemberImageFixListFiltersFromQuery(query);
};

export async function buildHwyMemberImageFixListMembershipBaseWhere(
  sequelize: Sequelize,
): Promise<WhereOptions> {
  const ctx = await loadHwyMemberListScopeContext();
  const otherPortalChannelCode = await tryFindHwyBaseInfoItemIdByShortName(
    'Registration Channel',
    'other_portal',
  );
  const regCol = sequelize.getDialect() === 'mssql'
    ? '[VwHwyMembers].[registration_channel_code]'
    : '"VwHwyMembers"."registration_channel_code"';
  const andParts: WhereOptions[] = [
    {
      membershipStatusCode: {
        [Op.in]: [
          ctx.membershipStatusCodes.active,
          ctx.membershipStatusCodes.pending_local,
        ],
      },
    },
  ];
  if (otherPortalChannelCode) {
    andParts.push(
      sequelize.literal(
        `COALESCE(${regCol}, N'') <> ${sequelize.escape(otherPortalChannelCode)}`,
      ),
    );
  }
  return { [Op.and]: andParts };
}

async function resolveFileKindCode(kindSlug: string): Promise<string | null> {
  const resolved = await resolveHwyMemberFileKindBySlugOrId(kindSlug);
  const id = resolved?.id?.trim();
  return id || null;
}

function buildDocFilterWhere(
  sequelize: Sequelize,
  mode: string,
  fileKindCode: string,
): WhereOptions | null {
  const files = memberFilesTable(sequelize);
  const content = memberFileHasContentPredicate(sequelize);
  const kindEscaped = sequelize.escape(fileKindCode);
  const approvedSql = sequelize.getDialect() === 'mssql'
    ? 'ISNULL(f.is_approved, 0) = 1'
    : 'COALESCE(f.is_approved, FALSE) IS TRUE';
  const notApprovedSql = sequelize.getDialect() === 'mssql'
    ? 'ISNULL(f.is_approved, 0) = 0'
    : 'COALESCE(f.is_approved, FALSE) IS NOT TRUE';

  const memberIdsWithFile = (extraFilePredicate: string) => sequelize.literal(`(
    SELECT f.member_id FROM ${files} f
    WHERE f.file_kind_code = ${kindEscaped}
      AND ${content}
      ${extraFilePredicate}
  )`);

  switch (mode) {
    case 'isNull':
      return {
        id: {
          [Op.notIn]: memberIdsWithFile(''),
        },
      };
    case 'isNotNull':
      return {
        id: {
          [Op.in]: memberIdsWithFile(''),
        },
      };
    case 'approved':
      return {
        id: {
          [Op.in]: memberIdsWithFile(`AND ${approvedSql}`),
        },
      };
    case 'notNullNotApproved':
      return {
        id: {
          [Op.in]: memberIdsWithFile(`AND ${notApprovedSql}`),
        },
      };
    default:
      return null;
  }
}

export async function buildHwyMemberDirectoryImageFixListFilterWhere(
  sequelize: Sequelize,
  filters: HwyMemberImageFixListFilterState,
): Promise<WhereOptions> {
  await ensureHwyMemberImageFixEditorSchema();
  const andParts: WhereOptions[] = [];

  if (filters.roled === 'hasRole') {
    andParts.push({
      userId: {
        [Op.in]: platformUserIdsWithRolesSubquery(sequelize),
      },
    });
  } else if (filters.roled === 'noRole') {
    andParts.push({
      [Op.or]: [
        { userId: null },
        {
          userId: {
            [Op.notIn]: platformUserIdsWithRolesSubquery(sequelize),
          },
        },
      ],
    });
  }

  const membersTable = sequelize.getDialect() === 'mssql' ? 'dbo.hwy_members' : 'hwy_members';
  const emptyTypePredicate = sequelize.getDialect() === 'mssql'
    ? `NULLIF(LTRIM(RTRIM(COALESCE(nakheb_card_front_type_code, N''))), N'') IS NULL`
    : `NULLIF(TRIM(COALESCE(nakheb_card_front_type_code, '')), '') IS NULL`;

  if (filters.nakhebCardType === 'isNull') {
    andParts.push({
      id: {
        [Op.in]: sequelize.literal(`(SELECT id FROM ${membersTable} WHERE ${emptyTypePredicate})`),
      },
    });
  } else if (filters.nakhebCardType === 'isNotNull') {
    andParts.push({
      id: {
        [Op.in]: sequelize.literal(`(SELECT id FROM ${membersTable} WHERE NOT (${emptyTypePredicate}))`),
      },
    });
  }

  for (const docKey of HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS) {
    const mode = filters.doc[docKey];
    if (!mode) {
      continue;
    }
    const kindSlug = HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEY_TO_KIND_SLUG[docKey];
    const kindCode = await resolveFileKindCode(kindSlug);
    if (!kindCode) {
      continue;
    }
    const docWhere = buildDocFilterWhere(sequelize, mode, kindCode);
    if (docWhere) {
      andParts.push(docWhere);
    }
  }

  if (filters.queue === 'tadghigh') {
    andParts.push({
      id: {
        [Op.in]: sequelize.literal(
          `(SELECT id FROM ${membersTable} WHERE COALESCE(nakheb_card_front_check, 0) = 1)`,
        ),
      },
    });
  }

  if (andParts.length === 0) {
    return {};
  }
  return { [Op.and]: andParts };
}
