export type HwyGeoResponsibilityRequestQueue = 'removal';

export const listHwyGeoResponsibilityRequests = async (
  input: {
    status?: HwyGeoResponsibilityRequestStatus;
    level?: HwyGeoResponsibilityLevel;
    queue?: HwyGeoResponsibilityRequestQueue;
    page?: number;
    pageSize?: number;
  },
  roleNames: readonly string[],
): Promise<HwyGeoResponsibilityRequestListResult> => {
  await ensureGeoResponsibilitySqlServerReady();
  const status = input.status ?? SUBMITTED_STATUS;
  if (status === SUBMITTED_STATUS && !hwyGeoResponsibilityCanAccessSection(roleNames)) {
    throw new Error('Forbidden.');
  }
  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);
  const procArgs = {
    status,
    geo_level: input.level ?? null,
    official_removal_only: input.queue === 'removal' ? 1 : 0,
  };
  const countRows = await execHwyProcedure<{ total: number }>('hwy_geo_responsibility_requests_count', procArgs);
  const total = Number(countRows[0]?.total ?? 0);

  const rows = await execHwyProcedure<{
    id: string;
    status: string;
    geo_level: string;
    geo_base_info_id: string;
    geoTitle: string | null;
    geoTitlePath: string | null;
    member_id: string;
    memberDisplayName: string | null;
    memberUsername: string | null;
    memberPhone: string | null;
    memberAvatarUrl: string | null;
    memberUserId: number | null;
    memberHasProfileImage: boolean | number | null;
    memberGenderCode: string | null;
    role_name: string;
    nominated_at: Date;
    nominatedByDisplayName: string | null;
    nominatedByUsername: string | null;
    decision_note: string | null;
    request_kind: string;
  }>('hwy_geo_responsibility_requests_list', {
    ...procArgs,
    offset,
    page_size: pageSize,
  });

  const mappedRows = rows.map((row) => ({
    id: trim(row.id),
    status: row.status as HwyGeoResponsibilityRequestStatus,
    level: row.geo_level as HwyGeoResponsibilityLevel,
    geoBaseInfoId: trim(row.geo_base_info_id),
    geoTitle: row.geoTitle ? trim(row.geoTitle) : null,
    memberId: trim(row.member_id),
    memberDisplayName: formatHwyMemberPersonDisplayName(row.memberDisplayName) || null,
    memberUsername: row.memberUsername ? trim(row.memberUsername) : null,
    memberPhone: row.memberPhone ? trim(row.memberPhone) : null,
    geoTitlePath: row.geoTitlePath ? trim(row.geoTitlePath) : null,
    memberAvatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
      avatarUrl: row.memberAvatarUrl ? trim(row.memberAvatarUrl) : null,
      userId: Number(row.memberUserId),
      hasProfileImage: row.memberHasProfileImage === true || row.memberHasProfileImage === 1,
    }),
    memberGenderCode: row.memberGenderCode ? trim(row.memberGenderCode) : null,
    roleName: trim(row.role_name),
    nominatedAt: row.nominated_at ? new Date(row.nominated_at).toISOString() : null,
    nominatedByDisplayName: row.nominatedByDisplayName ? trim(row.nominatedByDisplayName) : null,
    nominatedByUsername: row.nominatedByUsername ? trim(row.nominatedByUsername) : null,
    decisionNote: row.decision_note ? trim(row.decision_note) : null,
    requestKind: isHwyGeoResponsibilityRequestKind(trim(row.request_kind))
      ? trim(row.request_kind)
      : HWY_GEO_RESPONSIBILITY_REQUEST_KIND_NOMINATION,
    isOfficialRemovalRequest: isHwyGeoResponsibilityOfficialRemovalRequestKind(row.request_kind),
  }));

  const faceEnrich = mappedRows.map((row) => ({
    memberId: row.memberId,
    avatarUrl: row.memberAvatarUrl,
  }));
  await enrichMemberDirectoryFaceAvatarsByMemberId(faceEnrich);
  for (let i = 0; i < mappedRows.length; i += 1) {
    const url = faceEnrich[i]?.avatarUrl?.trim();
    if (url) {
      mappedRows[i]!.memberAvatarUrl = url;
    }
  }

  return {
    rows: mappedRows,
    total,
    page,
    pageSize,
  };
};

const ensureMemberEligible = (member: HwyGeoResponsibilityMemberLookup) => {
  if (!member.userId) {
    throw new Error('Member has no linked user account. Complete employee setup first.');
  }
};

export const submitHwyGeoResponsibilityNomination = async (input: {
  memberId: string;
  geoBaseInfoId: string;
  level: HwyGeoResponsibilityLevel;
  actorUserId: number | null;
  roleNames: readonly string[];
}): Promise<{ requestId: string }> => {
  await ensureGeoResponsibilitySqlServerReady();
  if (!canNominateLevel(input.roleNames, input.level)) {
    throw new Error('Forbidden.');
  }
  const spec = findHwyGeoResponsibilityRoleSpec(input.level);
  if (!spec) {
    throw new Error('Invalid level.');
  }
  const memberId = trim(input.memberId);
  const geoBaseInfoId = trim(input.geoBaseInfoId);
  if (!memberId || !geoBaseInfoId) {
    throw new Error('Member and geographic node are required.');
  }

  const sequelize = getControlPlaneSequelize();
  const mapRows = await sequelize.query<{ legacy_id: number }>(
    `
    SELECT TOP 1 legacy_id
    FROM dbo.hwy_etl_geo_map
    WHERE base_info_id = :geoBaseInfoId AND legacy_kind = :kind
    `,
    {
      replacements: { geoBaseInfoId, kind: spec.geoMapKind },
      type: QueryTypes.SELECT,
    },
  );
  if (!mapRows[0]) {
    throw new Error('Geographic node is not mapped for this responsibility level.');
  }

  const memberRows = await sequelize.query<{
    id: string;
    user_id: string | null;
    gender_code: string | null;
  }>(
    `
    SELECT CAST(id AS VARCHAR(32)) AS id, CAST(user_id AS VARCHAR(32)) AS user_id, gender_code
    FROM dbo.hwy_members WHERE id = :memberId
    `,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  const memberRow = memberRows[0];
  if (!memberRow) {
    throw new Error('Member not found.');
  }
  const memberLookup: HwyGeoResponsibilityMemberLookup = {
    id: trim(memberRow.id) || memberId,
    userId: memberRow.user_id ? trim(memberRow.user_id) : null,
    username: null,
    displayFullName: null,
    genderCode: memberRow.gender_code ? trim(memberRow.gender_code) : null,
    canGetResponsibilityCode: null,
  };
  ensureMemberEligible(memberLookup);

  const activeRows = await sequelize.query<{ role_name: string; geo_base_info_id: string }>(
    `
    SELECT TOP 1 r.role_name, r.geo_base_info_id
    FROM dbo.hwy_geo_responsibility_requests r
    WHERE r.member_id = :memberId
      AND r.status = N'approved'
      AND r.revoked_at IS NULL
      AND ${hwyGeoResponsibilitySqlActiveNominationAssignment('r')}
    ORDER BY COALESCE(r.decided_at, r.nominated_at) DESC
    `,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  const clearanceRows = await sequelize.query<{ can_get_title: string | null }>(
    `
    SELECT TOP 1 COALESCE(NULLIF(bi.title_ar, N''), bi.title_en) AS can_get_title
    FROM dbo.hwy_member_security_profile sp
    LEFT JOIN dbo.base_info bi ON bi.id = sp.can_get_responsibility_code
    WHERE sp.member_id = :memberId
    ORDER BY sp.id DESC
    `,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  const nominationGate = resolveHwyGeoResponsibilityNominationSelectable({
    userId: memberLookup.userId,
    activeRoleName: activeRows[0]?.role_name ? trim(activeRows[0].role_name) : null,
    activeGeoBaseInfoId: activeRows[0]?.geo_base_info_id ? trim(activeRows[0].geo_base_info_id) : null,
    nodeGeoBaseInfoId: geoBaseInfoId,
    genderCode: memberLookup.genderCode,
    canGetResponsibilityTitle: clearanceRows[0]?.can_get_title
      ? trim(clearanceRows[0].can_get_title)
      : null,
  });
  if (!nominationGate.selectable) {
    if (nominationGate.blockedReason === 'official_at_node') {
      throw new Error('Member is already the assigned official for this patch.');
    }
    if (nominationGate.blockedReason === 'has_responsibility') {
      throw new Error('Member already holds an active area responsibility.');
    }
    if (nominationGate.blockedReason === 'member_gender_unknown') {
      throw new Error('Member gender is required before nomination.');
    }
    if (nominationGate.blockedReason === 'clearance_denied') {
      throw new Error('Member is not cleared for responsibility.');
    }
    throw new Error('Member is not eligible for nomination.');
  }

  const montadheminScope = await loadHwyMemberListScopeContext();
  const montadheminRows = await sequelize.query<{ id: string }>(
    `
    SELECT CAST(id AS VARCHAR(32)) AS id
    FROM dbo.hwy_members hm
    WHERE hm.id = :memberId
      AND hm.membership_status_code = :montadheminMembershipStatusCode
    `,
    {
      replacements: {
        memberId: Number(memberId),
        montadheminMembershipStatusCode: montadheminScope.membershipStatusCodes.active,
      },
      type: QueryTypes.SELECT,
    },
  );
  if (!montadheminRows[0]) {
    throw new Error('Member is not an active registered member (Montadhemin).');
  }
  // Electoral join vs responsibility geo mismatch is informational only (main list badge) — not a submit blocker.

  const nominatedBy = input.actorUserId;
  if (nominatedBy == null || !Number.isFinite(nominatedBy)) {
    throw new Error('Authenticated user required.');
  }

  const memberPending = await sequelize.query<{ id: string }>(
    `
    SELECT TOP 1 CAST(id AS NVARCHAR(36)) AS id
    FROM dbo.hwy_geo_responsibility_requests
    WHERE member_id = :memberId
      AND status = N'submitted'
      AND request_kind = N'${HWY_GEO_RESPONSIBILITY_REQUEST_KIND_NOMINATION}'
    `,
    {
      replacements: { memberId: Number(memberId) },
      type: QueryTypes.SELECT,
    },
  );
  if (memberPending[0]) {
    throw new Error('Member already has a pending nomination request.');
  }

  const inserted = await execHwyProcedure<{ requestId: string }>('hwy_geo_responsibility_submit_nomination', {
    member_id: Number(memberId),
    user_id: Number(memberLookup.userId),
    geo_level: input.level,
    geo_base_info_id: geoBaseInfoId,
    legacy_geo_id: Number(mapRows[0].legacy_id),
    role_name: spec.roleName,
    nominated_by: nominatedBy,
  });
  const requestId = trim(inserted[0]?.requestId);
  if (!requestId) {
    throw new Error('Could not create nomination request.');
  }
  bestEffortSyncGeoResponsibilityPatchHistory(requestId);
  return { requestId };
};

