type GeoResponsibilityOfficialResolution =
  | { source: 'request'; holdingRequestId: string }
  | { source: 'scope' };

/** Same rules as node list: active approved request, else scope+role when no request row yet. */
const resolveActiveGeoResponsibilityOfficialForMember = async (input: {
  sequelize: ReturnType<typeof getControlPlaneSequelize>;
  geoBaseInfoId: string;
  level: HwyGeoResponsibilityLevel;
  roleName: string;
  memberId: number;
}): Promise<GeoResponsibilityOfficialResolution | null> => {
  const officialRequest = await readActiveGeoResponsibilityOfficialRequest({
    sequelize: input.sequelize,
    geoBaseInfoId: input.geoBaseInfoId,
    roleName: input.roleName,
    memberId: input.memberId,
  });
  if (officialRequest) {
    return { source: 'request', holdingRequestId: officialRequest.id };
  }

  const scopeRows = await input.sequelize.query<{ id: number }>(
    `
    SELECT TOP 1 m.id
    FROM dbo.base_scope_memberships sm
    INNER JOIN dbo.base_user_roles ur ON ur.user_id = sm.user_id AND ur.role_name = :roleName
    INNER JOIN dbo.hwy_members m ON m.user_id = sm.user_id
    WHERE sm.dimension_key = N'geo'
      AND sm.node_id = :geoBaseInfoId
      AND m.id = :memberId
      AND NOT EXISTS (
        SELECT 1
        FROM dbo.hwy_geo_responsibility_requests ar
        INNER JOIN dbo.hwy_members am ON am.id = ar.member_id
        INNER JOIN dbo.hwy_members rm ON rm.id = :memberId
        WHERE ar.geo_base_info_id = :geoBaseInfoId
          AND ar.role_name = :roleName
          AND ar.geo_level = :level
          AND ar.status = N'approved'
          AND ar.revoked_at IS NULL
          AND ${hwyGeoResponsibilitySqlActiveNominationAssignment('ar')}
          AND ${hwyGeoResponsibilityMembersSameGenderPartitionSql('am', 'rm')}
      )
    `,
    {
      replacements: {
        roleName: input.roleName,
        geoBaseInfoId: input.geoBaseInfoId,
        memberId: input.memberId,
        level: input.level,
      },
      type: QueryTypes.SELECT,
    },
  );
  if (scopeRows[0]?.id != null) {
    return { source: 'scope' };
  }
  return null;
};

