export const readHwyGeoResponsibilityAssigneePendingRemovalRequestId = async (input: {
  memberId: string;
  geoBaseInfoId: string;
  level: HwyGeoResponsibilityLevel;
}): Promise<{ requestId: string | null }> => {
  await ensureGeoResponsibilitySqlServerReady();
  const spec = findHwyGeoResponsibilityRoleSpec(input.level);
  const memberId = trim(input.memberId);
  const geoBaseInfoId = trim(input.geoBaseInfoId);
  if (!spec || !memberId || !geoBaseInfoId) {
    return { requestId: null };
  }
  const numericMemberId = Number(memberId);
  if (!Number.isFinite(numericMemberId) || numericMemberId <= 0) {
    return { requestId: null };
  }
  const sequelize = getControlPlaneSequelize();
  const requestId = await findSubmittedHwyGeoResponsibilityOfficialRemovalRequestId({
    sequelize,
    memberId: numericMemberId,
    geoBaseInfoId,
    level: input.level,
    roleName: spec.roleName,
  });
  return { requestId };
};

