export const submitHwyGeoResponsibilityOfficialRemovalRequest = async (input: {
  memberId: string;
  geoBaseInfoId: string;
  level: HwyGeoResponsibilityLevel;
  actorUserId: number | null;
  roleNames: readonly string[];
}): Promise<{ requestId: string }> => {
  await ensureGeoResponsibilitySqlServerReady();
  if (!canNominateLevel(input.roleNames, input.level)) {
    throw new Error('Forbidden.');
  }
  const memberId = trim(input.memberId);
  const geoBaseInfoId = trim(input.geoBaseInfoId);
  const spec = findHwyGeoResponsibilityRoleSpec(input.level);
  if (!spec || !memberId || !geoBaseInfoId) {
    throw new Error('Invalid removal request.');
  }
  const nominatedBy = input.actorUserId;
  if (nominatedBy == null || !Number.isFinite(nominatedBy)) {
    throw new Error('Authenticated user required.');
  }
  const sequelize = getControlPlaneSequelize();
  const memberRows = await sequelize.query<{ user_id: number | null; gender_code: string | null }>(
    `
    SELECT CAST(user_id AS VARCHAR(32)) AS user_id, gender_code
    FROM dbo.hwy_members
    WHERE id = :memberId
    `,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  const memberRow = memberRows[0];
  if (!memberRow) {
    throw new Error('Member not found.');
  }
  const memberGenderSlot = resolveHwyGeoResponsibilityGenderSlot(
    memberRow.gender_code ? trim(memberRow.gender_code) : null,
  );
  if (memberGenderSlot !== 'male' && memberGenderSlot !== 'female') {
    throw new Error('Member gender is required.');
  }
  const official = await resolveActiveGeoResponsibilityOfficialForMember({
    sequelize,
    geoBaseInfoId,
    level: input.level,
    roleName: spec.roleName,
    memberId: Number(memberId),
  });
  if (!official) {
    throw new Error('Member is not the active official for this patch.');
  }
  const pendingDuplicate = await sequelize.query<{ id: string }>(
    `
    SELECT TOP 1 CAST(id AS NVARCHAR(36)) AS id
    FROM dbo.hwy_geo_responsibility_requests
    WHERE member_id = :memberId
      AND geo_base_info_id = :geoBaseInfoId
      AND role_name = :roleName
      AND status = N'submitted'
      AND request_kind = N'${HWY_GEO_RESPONSIBILITY_REQUEST_KIND_OFFICIAL_REMOVAL}'
    `,
    {
      replacements: {
        memberId: Number(memberId),
        geoBaseInfoId,
        roleName: spec.roleName,
      },
      type: QueryTypes.SELECT,
    },
  );
  if (pendingDuplicate[0]) {
    throw new Error('A removal request is already pending for this official.');
  }
  const mapRows = await sequelize.query<{ legacy_id: number }>(
    `
    SELECT TOP 1 legacy_id
    FROM dbo.hwy_etl_geo_map
    WHERE base_info_id = :geoBaseInfoId AND legacy_kind = :kind
    `,
    {
      replacements: { geoBaseInfoId, kind: spec.geoMapKind },
      type: QueryTypes.SELECT,
    },
  );
  if (!mapRows[0]) {
    throw new Error('Geographic node not found.');
  }
  const inserted = await execHwyProcedure<{ requestId: string }>(
    'hwy_geo_responsibility_submit_official_removal',
    {
      member_id: Number(memberId),
      user_id: memberRow.user_id != null ? Number(memberRow.user_id) : null,
      geo_level: input.level,
      geo_base_info_id: geoBaseInfoId,
      legacy_geo_id: Number(mapRows[0].legacy_id),
      role_name: spec.roleName,
      nominated_by: nominatedBy,
    },
  );
  const requestId = trim(inserted[0]?.requestId);
  if (!requestId) {
    throw new Error('Could not create removal request.');
  }
  return { requestId };
};

export const approveHwyGeoResponsibilityRequest = async (input: {
  requestId: string;
  actorUserId: number | null;
  roleNames: readonly string[];
}): Promise<void> => {
  await ensureGeoResponsibilitySqlServerReady();
  const requestId = trim(input.requestId);
  if (!requestId) {
    throw new Error('Request id is required.');
  }
  const actorUserId = input.actorUserId;
  if (actorUserId == null || !Number.isFinite(actorUserId)) {
    throw new Error('Authenticated user required.');
  }

  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    id: string;
    member_id: number;
    user_id: number | null;
    geo_level: string;
    geo_base_info_id: string;
    role_name: string;
    status: string;
    request_kind: string;
  }>(
    `
    SELECT TOP 1
      CAST(id AS NVARCHAR(36)) AS id,
      member_id,
      user_id,
      geo_level,
      geo_base_info_id,
      role_name,
      status,
      request_kind
    FROM dbo.hwy_geo_responsibility_requests
    WHERE id = :requestId
    `,
    { replacements: { requestId }, type: QueryTypes.SELECT },
  );
  const row = rows[0];
  if (!row || row.status !== SUBMITTED_STATUS) {
    throw new Error('Pending request not found.');
  }
  const level = row.geo_level as HwyGeoResponsibilityLevel;
  if (!canApproveLevel(input.roleNames, level)) {
    throw new Error('Forbidden.');
  }
  if (row.user_id == null) {
    throw new Error('Member has no linked user account.');
  }

  const geoBaseInfoId = trim(row.geo_base_info_id);
  const roleName = trim(row.role_name);
  const requestKind = trim(row.request_kind);

  if (isHwyGeoResponsibilityOfficialRemovalRequestKind(requestKind)) {
    const officialForMember = await resolveActiveGeoResponsibilityOfficialForMember({
      sequelize,
      geoBaseInfoId,
      level,
      roleName,
      memberId: Number(row.member_id),
    });
    if (!officialForMember) {
      throw new Error('Member is not the active official for this patch.');
    }
    if (officialForMember.source === 'request') {
      await applyApprovedOfficialRemoval({
        requestId,
        holdingRequestId: officialForMember.holdingRequestId,
        userId: Number(row.user_id),
        geoBaseInfoId,
        roleName,
        actorUserId,
      });
      bestEffortSyncGeoResponsibilityPatchHistory(requestId);
      bestEffortSyncGeoResponsibilityPatchHistory(officialForMember.holdingRequestId);
      return;
    }
    await applyApprovedScopeOnlyOfficialRemoval({
      requestId,
      userId: Number(row.user_id),
      geoBaseInfoId,
      roleName,
      actorUserId,
    });
    bestEffortSyncGeoResponsibilityPatchHistory(requestId);
    return;
  }

  await applyApprovedNomination({
    requestId,
    memberId: Number(row.member_id),
    userId: Number(row.user_id),
    geoLevel: level,
    geoBaseInfoId,
    roleName,
    actorUserId,
  });
  bestEffortSyncGeoResponsibilityPatchHistory(requestId);
};

export const rejectHwyGeoResponsibilityRequest = async (input: {
  requestId: string;
  note?: string | null;
  actorUserId: number | null;
  roleNames: readonly string[];
}): Promise<void> => {
  await ensureGeoResponsibilitySqlServerReady();
  const requestId = trim(input.requestId);
  const actorUserId = input.actorUserId;
  if (actorUserId == null || !Number.isFinite(actorUserId)) {
    throw new Error('Authenticated user required.');
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ geo_level: string; status: string }>(
    `
    SELECT TOP 1 geo_level, status
    FROM dbo.hwy_geo_responsibility_requests
    WHERE id = :requestId
    `,
    { replacements: { requestId }, type: QueryTypes.SELECT },
  );
  const row = rows[0];
  if (!row || row.status !== SUBMITTED_STATUS) {
    throw new Error('Pending request not found.');
  }
  if (!canApproveLevel(input.roleNames, row.geo_level as HwyGeoResponsibilityLevel)) {
    throw new Error('Forbidden.');
  }
  try {
    await execHwyProcedure('hwy_geo_responsibility_reject_request', {
      request_id: requestId,
      actor_user_id: actorUserId,
      note: trim(input.note) || null,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('53000') || message.includes('Pending request not found')) {
      throw new Error('Pending request not found.');
    }
    throw error;
  }
  bestEffortSyncGeoResponsibilityPatchHistory(requestId);
};

