import type { HwyCandidatePipelineStage } from './hwyCandidatePipelineCatalog';

/** Edge control-plane views (snake_case dbo names). */
export const HWY_EDGE_CANDIDATE_PIPELINE_VIEW: Readonly<Record<HwyCandidatePipelineStage, string>> = {
  security: 'vw_hwy_candidate_pipeline_security',
  interview: 'vw_hwy_candidate_pipeline_interview',
  courses: 'vw_hwy_candidate_pipeline_courses',
  install: 'vw_hwy_candidate_pipeline_install',
};

/** MembersV2 legacy DB still exposes these view names (read-only parity). */
export const HWY_LEGACY_CANDIDATE_PIPELINE_VIEW: Readonly<Record<HwyCandidatePipelineStage, string>> = {
  security: 'HWY_VW_Employees_SecurityStatuses',
  interview: 'HWY_VW_Employees_InterviewManagement',
  courses: 'HWY_VW_Employees_PassedNecessaryDoratManagement',
  install: 'HWY_VW_Employees_ToApproveResponsibility',
};

export const HWY_EDGE_CANDIDATE_PIPELINE_VIEW_NAMES = Object.values(HWY_EDGE_CANDIDATE_PIPELINE_VIEW);

export const HWY_LEGACY_CANDIDATE_PIPELINE_VIEW_NAMES = Object.values(HWY_LEGACY_CANDIDATE_PIPELINE_VIEW);

export const edgeCandidatePipelineViewForStage = (
  stage: HwyCandidatePipelineStage,
): string => HWY_EDGE_CANDIDATE_PIPELINE_VIEW[stage];

export const legacyCandidatePipelineViewForStage = (
  stage: HwyCandidatePipelineStage,
): string => HWY_LEGACY_CANDIDATE_PIPELINE_VIEW[stage];
