import {
  buildHwyMemberListRouteAllowRoles,
  legacyHwyActionKey,
  type HwyLegacyControllerAction,
} from './hwyMemberListLegacyAccess';
import { HWY_EMPLOYEES_LIST_PAGE_KEY } from './hwyEmployeesList';

export const HWY_EMPLOYEES_LIST_LEGACY_COMPONENT = 'HWY_Employees_List';

export const HWY_EMPLOYEES_LIST_LEGACY_READ: HwyLegacyControllerAction = {
  controller: 'HWY_Members',
  method: 'Read_Employees',
};

export const resolveHwyEmployeesListPageLegacyReadAction = (
  pageKey: string,
): HwyLegacyControllerAction | null =>
  pageKey === HWY_EMPLOYEES_LIST_PAGE_KEY ? HWY_EMPLOYEES_LIST_LEGACY_READ : null;

export const buildHwyEmployeesListPortalAllowRoles = (
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const roles = rolesByAction.get(legacyHwyActionKey(HWY_EMPLOYEES_LIST_LEGACY_READ)) ?? [];
  return buildHwyMemberListRouteAllowRoles(roles);
};
