import {
  buildHwyMemberListRouteAllowRoles,
  legacyHwyActionKey,
  type HwyLegacyControllerAction,
} from './hwyMemberListLegacyAccess';
import type { HwyCardFlowStep } from './hwyCardFlowCatalog';

const readAction = (method: string): HwyLegacyControllerAction => ({
  controller: 'HWY_Members',
  method,
});

export const HWY_CARD_FLOW_PAGE_LEGACY_READ: Record<string, HwyLegacyControllerAction> = {
  'hwy-card-flow-start': readAction('Read_Members_CardFlowStart'),
  'hwy-card-flow-security': readAction('Read_Members_CardFlowSecurityCheck'),
  'hwy-card-flow-central': readAction('Read_Members_CardFlowDubleCheck'),
  'hwy-card-flow-province': readAction('Read_Members_CardFlowProvinceCheck'),
  'hwy-card-flow-print': readAction('Read_Members_CardFlowToPrint'),
  'hwy-card-flow-province-delivery': readAction('Read_Members_CardFlowProvinceDelivery'),
  'hwy-card-flow-member-delivery': readAction('Read_Members_CardFlowMemberDelivery'),
  'hwy-card-flow-printed-history': { controller: 'HWY_Members_CardPrintingHistory', method: 'Read_List' },
};

export const HWY_CARD_FLOW_STEP_TO_PAGE_KEY: Record<HwyCardFlowStep, string> = {
  start: 'hwy-card-flow-start',
  security: 'hwy-card-flow-security',
  central: 'hwy-card-flow-central',
  province: 'hwy-card-flow-province',
  print: 'hwy-card-flow-print',
  'province-delivery': 'hwy-card-flow-province-delivery',
  'member-delivery': 'hwy-card-flow-member-delivery',
  'printed-history': 'hwy-card-flow-printed-history',
};

export const resolveHwyCardFlowPageLegacyReadAction = (
  pageKey: string,
): HwyLegacyControllerAction | null => HWY_CARD_FLOW_PAGE_LEGACY_READ[pageKey] ?? null;

export const buildHwyCardFlowPortalAllowRoles = (
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const merged = new Set<string>();
  for (const action of Object.values(HWY_CARD_FLOW_PAGE_LEGACY_READ)) {
    for (const role of rolesByAction.get(legacyHwyActionKey(action)) ?? []) {
      merged.add(role);
    }
  }
  return buildHwyMemberListRouteAllowRoles([...merged]);
};

export const buildHwyCardFlowStepAllowRoles = (
  step: HwyCardFlowStep,
  rolesByAction: ReadonlyMap<string, string[]>,
): string[] => {
  const pageKey = HWY_CARD_FLOW_STEP_TO_PAGE_KEY[step];
  const action = resolveHwyCardFlowPageLegacyReadAction(pageKey);
  if (!action) {
    return buildHwyMemberListRouteAllowRoles([]);
  }
  const roles = rolesByAction.get(legacyHwyActionKey(action)) ?? [];
  return buildHwyMemberListRouteAllowRoles(roles);
};
