/** SQL predicates on `hwy_members` gender_code (alias must match `memberAlias`). */
export const hwyGeoResponsibilityMemberIsMaleSql = (memberAlias: string): string => `
  (
    ${memberAlias}.gender_code = N'100.1.1'
    OR ${memberAlias}.gender_code LIKE N'%10011%'
    OR LOWER(COALESCE(${memberAlias}.gender_code, N'')) LIKE N'%male%'
    OR ${memberAlias}.gender_code LIKE N'%ذكر%'
  )
`;

export const hwyGeoResponsibilityMemberIsFemaleSql = (memberAlias: string): string => `
  (
    ${memberAlias}.gender_code = N'100.1.2'
    OR ${memberAlias}.gender_code LIKE N'%10012%'
    OR LOWER(COALESCE(${memberAlias}.gender_code, N'')) LIKE N'%female%'
    OR ${memberAlias}.gender_code LIKE N'%انث%'
    OR ${memberAlias}.gender_code LIKE N'%أنث%'
  )
`;

/** Same-gender partition for supersede/revoke (two member aliases). */
export const hwyGeoResponsibilityMembersSameGenderPartitionSql = (
  leftAlias: string,
  rightAlias: string,
): string => `
  (
    (${hwyGeoResponsibilityMemberIsMaleSql(leftAlias)} AND ${hwyGeoResponsibilityMemberIsMaleSql(rightAlias)})
    OR (${hwyGeoResponsibilityMemberIsFemaleSql(leftAlias)} AND ${hwyGeoResponsibilityMemberIsFemaleSql(rightAlias)})
  )
`;
