import { QueryTypes, type Sequelize } from 'sequelize';
import { resolveHwyMemberListInstituteId } from '../../../domain/hwy/hwyMemberInstituteCodes';

const instituteIdByCodeCache = new Map<string, number>();

/** Prefer `hwy_institutes.id` from edge DB (ETL/seed); fall back to catalog id when row missing. */
export const resolveHwyMemberListInstituteIdForScope = async (
  sequelize: Sequelize,
  instituteCode: string,
): Promise<number> => {
  const catalogId = resolveHwyMemberListInstituteId(instituteCode);
  if (catalogId == null) {
    throw new Error(`Unknown institute code for list scope: ${instituteCode}`);
  }
  const cached = instituteIdByCodeCache.get(instituteCode);
  if (cached != null) {
    return cached;
  }
  const table = sequelize.getDialect() === 'mssql' ? 'dbo.hwy_institutes' : 'hwy_institutes';
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM ${table} WHERE code = ${sequelize.escape(instituteCode)}`,
    { type: QueryTypes.SELECT },
  );
  const resolved = rows[0]?.id ?? catalogId;
  instituteIdByCodeCache.set(instituteCode, resolved);
  return resolved;
};
