import sql from 'mssql';
import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../src/server/db/controlPlaneSequelize';
import type { LegacyMemberRow } from './memberBulkInsert';

/** Legacy Pictures_Reviewed intentionally omitted — dead field (not used by ImageFix list/save). */
export const LEGACY_MEMBER_SELECT = `
  Id, NakhebId, UserName, TrackingCode, FirstName, FatherName, GrandFatherName, LastName, NickName,
  GenderId, BirthYear, BirthMonth, BirthDay, NationalCode,
  Phone1, Phone2, Email, FacebookId, TikTokId,
  FamilyCode, AddrStateId, AddrCityId, AddrNahiehId,
  AddrMahallehName, AddrMahallehNumber, AddrZoghaghNumber, AddrDaarNumber,
  AddrAghrabLocation, AddrMostImportantPlace, AddrEghteraId,
  MembershipStatus, MembershipOn, MoarrefUserName, SecondMoarrefUserName,
  VotedOn2021, VotedOn2023, VotedOn2025, NakhebJoinTasjilStateId, NakhebJoinTypeId, DeviceOsTypeId, CreatedOn, UpdatedOn
`;

const LEGACY_MEMBER_FILTER = 'ISNULL(DeviceOsTypeId, 0) != 213991';

const chunkIds = (ids: number[], size: number): number[][] => {
  const out: number[][] = [];
  for (let i = 0; i < ids.length; i += size) out.push(ids.slice(i, i + size));
  return out;
};

export async function localMaxHwyMemberId(): Promise<number> {
  const row = (await getControlPlaneSequelize().query<{ maxId: number | null }>(
    'SELECT MAX(id) AS maxId FROM dbo.hwy_members',
    { type: QueryTypes.SELECT },
  ))[0];
  return Math.max(0, Number(row?.maxId ?? 0));
}

export async function filterIdsExistingInHwyMembers(memberIds: number[]): Promise<number[]> {
  const unique = [...new Set(memberIds.filter((id) => id > 0))];
  if (!unique.length) return [];
  const existing: number[] = [];
  for (const batch of chunkIds(unique, 400)) {
    const replacements: Record<string, number> = {};
    const placeholders: string[] = [];
    batch.forEach((id, i) => {
      replacements[`mid${i}`] = id;
      placeholders.push(`:mid${i}`);
    });
    const rows = await getControlPlaneSequelize().query<{ id: number }>(
      `SELECT id FROM dbo.hwy_members WHERE id IN (${placeholders.join(', ')})`,
      { replacements, type: QueryTypes.SELECT },
    );
    existing.push(...rows.map((r) => Number(r.id)));
  }
  return existing;
}

export async function legacyMaxMemberUpdatedOnUpTo(
  legacy: sql.ConnectionPool,
  maxMemberId: number,
): Promise<string | null> {
  if (maxMemberId <= 0) return null;
  const row = (await legacy.request()
    .input('maxId', sql.Int, maxMemberId)
    .query(`
      SELECT MAX(UpdatedOn) AS maxUpdated
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id <= @maxId AND ${LEGACY_MEMBER_FILTER}
    `)).recordset[0] as { maxUpdated: Date | null };
  if (!row?.maxUpdated) return null;
  return new Date(row.maxUpdated).toISOString();
}

export async function legacyMaxChangeHistoryId(legacy: sql.ConnectionPool): Promise<number> {
  const row = (await legacy.request().query(`
    SELECT MAX(Id) AS maxId FROM dbo.HWY_Members_ChangeHistory WITH (NOLOCK)
  `)).recordset[0] as { maxId: number | null };
  return Math.max(0, Number(row?.maxId ?? 0));
}

export async function queryLegacyMemberIdsUpdatedSince(
  legacy: sql.ConnectionPool,
  updatedSince: Date,
  existingMaxMemberId: number,
): Promise<number[]> {
  const ids: number[] = [];
  let lastId = 0;
  const batch = Math.max(500, Number(process.env.HWY_ETL_MEMBER_DELTA_BATCH ?? 5000) || 5000);
  while (true) {
    const rows = (await legacy.request()
      .input('since', sql.DateTime2, updatedSince)
      .input('maxId', sql.Int, existingMaxMemberId)
      .input('lastId', sql.Int, lastId)
      .input('take', sql.Int, batch)
      .query(`
        SELECT TOP (@take) Id
        FROM dbo.HWY_Members WITH (NOLOCK)
        WHERE Id > @lastId
          AND Id <= @maxId
          AND ${LEGACY_MEMBER_FILTER}
          AND UpdatedOn > @since
        ORDER BY Id
      `)).recordset as Array<{ Id: number }>;
    if (!rows.length) break;
    for (const row of rows) ids.push(Number(row.Id));
    lastId = Number(rows[rows.length - 1].Id);
  }
  return ids;
}

export async function queryChangeHistoryMemberIdsSince(
  legacy: sql.ConnectionPool,
  afterChangeHistoryId: number,
): Promise<number[]> {
  const batch = Math.max(500, Number(process.env.HWY_ETL_CHANGE_HISTORY_MEMBER_BATCH ?? 8000) || 8000);
  const memberIds = new Set<number>();
  let lastId = afterChangeHistoryId;
  while (true) {
    const rows = (await legacy.request()
      .input('lastId', sql.Int, lastId)
      .input('take', sql.Int, batch)
      .query(`
        SELECT TOP (@take) Id, MemberId
        FROM dbo.HWY_Members_ChangeHistory WITH (NOLOCK)
        WHERE Id > @lastId
        ORDER BY Id
      `)).recordset as Array<{ Id: number; MemberId: number }>;
    if (!rows.length) break;
    for (const row of rows) {
      if (row.MemberId > 0) memberIds.add(Number(row.MemberId));
    }
    lastId = Number(rows[rows.length - 1].Id);
  }
  return [...memberIds];
}

export async function fetchLegacyMembersByIds(
  legacy: sql.ConnectionPool,
  memberIds: number[],
): Promise<LegacyMemberRow[]> {
  const unique = [...new Set(memberIds.filter((id) => id > 0))].sort((a, b) => a - b);
  if (!unique.length) return [];
  const out: LegacyMemberRow[] = [];
  for (const batch of chunkIds(unique, 400)) {
    const req = legacy.request();
    const placeholders: string[] = [];
    batch.forEach((id, i) => {
      req.input(`mid${i}`, sql.Int, id);
      placeholders.push(`@mid${i}`);
    });
    const rows = (await req.query(`
      SELECT ${LEGACY_MEMBER_SELECT}
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id IN (${placeholders.join(', ')})
        AND ${LEGACY_MEMBER_FILTER}
    `)).recordset as LegacyMemberRow[];
    out.push(...rows);
  }
  return out;
}

export async function maxLegacyMemberUpdatedOn(
  legacy: sql.ConnectionPool,
  memberIds: number[],
): Promise<string | null> {
  if (!memberIds.length) return null;
  let max: Date | null = null;
  for (const batch of chunkIds([...new Set(memberIds)], 400)) {
    const req = legacy.request();
    const placeholders: string[] = [];
    batch.forEach((id, i) => {
      req.input(`mid${i}`, sql.Int, id);
      placeholders.push(`@mid${i}`);
    });
    const row = (await req.query(`
      SELECT MAX(UpdatedOn) AS maxUpdated
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id IN (${placeholders.join(', ')})
    `)).recordset[0] as { maxUpdated: Date | null };
    if (row?.maxUpdated) {
      const d = new Date(row.maxUpdated);
      if (!max || d > max) max = d;
    }
  }
  return max ? max.toISOString() : null;
}
