import type { Request } from 'express';

import {
  APPENDO_CLIENT_HEADER,
  CLIENT_CONTEXT_BODY_KEY,
  CLIENT_CONTEXT_ENVELOPE_MAX_BYTES,
} from '../../../shared/api/contracts/client-context';

const readHeader = (req: Request, name: string): string | undefined => {
  const value = req.headers[name.toLowerCase()] ?? req.headers[name];
  if (Array.isArray(value)) {
    return value[0];
  }
  return typeof value === 'string' ? value : undefined;
};

export const readClientClaimedFromRequest = (req: Request): Record<string, unknown> => {
  const headerRaw = readHeader(req, APPENDO_CLIENT_HEADER);
  let envelope: Record<string, unknown> = {};
  if (headerRaw?.trim()) {
    if (Buffer.byteLength(headerRaw, 'utf8') > CLIENT_CONTEXT_ENVELOPE_MAX_BYTES) {
      return {};
    }
    try {
      const parsed = JSON.parse(headerRaw) as unknown;
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        envelope = parsed as Record<string, unknown>;
      }
    } catch {
      return {};
    }
  } else if (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) {
    const nested = (req.body as Record<string, unknown>)[CLIENT_CONTEXT_BODY_KEY];
    if (typeof nested === 'string' && nested.trim()) {
      try {
        const parsed = JSON.parse(nested) as unknown;
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          envelope = parsed as Record<string, unknown>;
        }
      } catch {
        return {};
      }
    } else if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
      envelope = nested as Record<string, unknown>;
    }
  }

  if (envelope.claimed && typeof envelope.claimed === 'object' && !Array.isArray(envelope.claimed)) {
    return envelope.claimed as Record<string, unknown>;
  }
  return envelope;
};
