const attachHwyMemberDirectoryDisplayFullName = (rows: Record<string, unknown>[]): void => {
  for (const row of rows) {
    const raw = readStringField(row, 'displayFullName');
    if (!raw) {
      continue;
    }
    const formatted = formatHwyMemberPersonDisplayName(raw);
    if (!formatted) {
      continue;
    }
    row.displayFullName = formatted;
    if (Object.prototype.hasOwnProperty.call(row, 'display_full_name')) {
      row.display_full_name = formatted;
    }
  }
};

const readStringField = (row: Record<string, unknown>, field: string): string => {
  const snake = field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`);
  const raw = row[field] ?? row[snake];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

type CodedFieldSpec = {
  sourceField: string;
  titleField: string;
  preferTitlePath?: boolean;
  resolveBaseInfoId?: (raw: string) => string | null;
};

