type GeoLegacyKind = 'province' | 'region' | 'maktab' | 'ghavateh' | 'circle';

const GEO_LEGACY_KIND_BY_SOURCE_FIELD: Partial<Record<string, GeoLegacyKind>> = {
  addrProvinceId: 'province',
  addrDistrictId: 'ghavateh',
  addrSubdistrictId: 'ghavateh',
  addrMaktabId: 'maktab',
  addrRegionId: 'region',
  addrCircleId: 'circle',
  nakhebinRegionId: 'region',
  nakhebinMaktabId: 'maktab',
  nakhebinLinkRegionId: 'region',
};

const isHierarchicalBaseInfoId = (value: string): boolean => /^\d+(?:\.\d+)+$/.test(value);

const LEGACY_HWY_ADDRESS_TITLE_FIELDS: ReadonlyArray<{ sourceField: string; titleField: string }> = [
  { sourceField: 'addrDistrictId', titleField: 'addrDistrictTitle' },
  { sourceField: 'addrSubdistrictId', titleField: 'addrSubdistrictTitle' },
];

const resolveMemberDirectoryGeoDisplayTitle = (
  spec: CodedFieldSpec,
  plainTitle: string,
  pathTitle: string,
): string => {
  const plain = plainTitle.trim();
  const path = pathTitle.trim();

  if (spec.sourceField === 'addrProvinceId') {
    if (plain) {
      return plain;
    }
    if (path) {
      return resolveHwyElectoralProvinceTitle(path) || leafTitleFromGeoPath(path);
    }
    return '';
  }

  if (spec.sourceField.startsWith('addr')) {
    if (plain) {
      return plain;
    }
    if (path) {
      return leafTitleFromGeoPath(path);
    }
    return '';
  }

  if (spec.preferTitlePath && path) {
    return path;
  }
  return plain || path;
};

const resolveBaseInfoLookupId = (
  raw: string,
  spec: CodedFieldSpec,
  geoMap: Map<string, string>,
): string | null => {
  if (!raw) {
    return null;
  }
  if (spec.resolveBaseInfoId) {
    return spec.resolveBaseInfoId(raw) ?? raw;
  }
  if (isHierarchicalBaseInfoId(raw)) {
    return raw;
  }
  const geoKind = GEO_LEGACY_KIND_BY_SOURCE_FIELD[spec.sourceField];
  if (geoKind && /^\d+$/.test(raw)) {
    const mapped = resolveHwyEtlGeoBaseInfoId(geoMap, geoKind, raw, 0);
    if (mapped) {
      return mapped;
    }
  }
  if (/^\d+$/.test(raw)) {
    return raw;
  }
  return raw;
};

/** Electoral region for list path resolve (nakhebin link → member address → link override). */
export const resolveMemberDirectoryListElectoralRegionRef = (
  row: Record<string, unknown>,
): string => (
  readStringField(row, 'nakhebinRegionId')
  || readStringField(row, 'addrRegionId')
  || readStringField(row, 'nakhebinLinkRegionId')
);

const resolveMemberDirectoryListElectoralMaktabRef = (
  row: Record<string, unknown>,
): string => (
  readStringField(row, 'addrMaktabId')
  || readStringField(row, 'nakhebinMaktabId')
);

const attachListElectoralMaktabSummaries = async (
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> => {
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
  const maktabRefToBaseInfoId = new Map<string, string>();
  for (const ref of [
    ...new Set(rows.map((row) => resolveMemberDirectoryListElectoralMaktabRef(row)).filter(Boolean)),
  ]) {
    const mapped = resolveHwyEtlGeoBaseInfoId(geoMap, 'maktab', ref, 0)
      ?? (/^\d+(?:\.\d+)+$/.test(ref) ? ref : null);
    if (mapped) {
      maktabRefToBaseInfoId.set(ref, mapped);
    }
  }
  const baseInfoIds = [...new Set(maktabRefToBaseInfoId.values())];
  if (baseInfoIds.length === 0) {
    return;
  }
  const enriched = await listBaseInfoEnrichmentRowsByIds(baseInfoIds, cultureId);
  const titleById = new Map(
    enriched.map((item) => [String(item.id ?? '').trim(), String(item.title ?? '').trim()]),
  );
  for (const row of rows) {
    if (readStringField(row, 'electoralDivisionPath')) {
      continue;
    }
    const ref = resolveMemberDirectoryListElectoralMaktabRef(row);
    const baseInfoId = maktabRefToBaseInfoId.get(ref);
    if (!baseInfoId) {
      continue;
    }
    const maktabTitle = titleById.get(baseInfoId);
    if (maktabTitle) {
      row.electoralDivisionPath = maktabTitle;
    }
  }
};

const ADDR_PROVINCE_TITLE_SPEC: CodedFieldSpec = {
  sourceField: 'addrProvinceId',
  titleField: 'addrProvinceTitle',
  preferTitlePath: true,
};

/** Batch-resolve `addrProvinceTitle` for list rows (electoral column fallback when nakhebin path is empty). */
export const attachListAddrProvinceTitles = async (
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> => {
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
  const provinceRefToBaseInfoId = new Map<string, string>();
  for (const ref of [...new Set(rows.map((row) => readStringField(row, 'addrProvinceId')).filter(Boolean))]) {
    const mapped = resolveHwyEtlGeoBaseInfoId(geoMap, 'province', ref, 0)
      ?? (/^\d+(?:\.\d+)+$/.test(ref) ? ref : null);
    if (mapped) {
      provinceRefToBaseInfoId.set(ref, mapped);
    }
  }
  const baseInfoIds = [...new Set(provinceRefToBaseInfoId.values())];
  if (baseInfoIds.length === 0) {
    return;
  }
  const enriched = await listBaseInfoEnrichmentRowsByIds(baseInfoIds, cultureId);
  const titleById = new Map(
    enriched.map((item) => [String(item.id ?? '').trim(), item]),
  );
  for (const row of rows) {
    if (readStringField(row, 'addrProvinceTitle')) {
      continue;
    }
    const ref = readStringField(row, 'addrProvinceId');
    const baseInfoId = provinceRefToBaseInfoId.get(ref);
    if (!baseInfoId) {
      continue;
    }
    const match = titleById.get(baseInfoId);
    if (!match) {
      continue;
    }
    const plain = String(match.title ?? match.title_canonical ?? '').trim();
    const path = String(match.title_path ?? '').trim();
    const title = resolveMemberDirectoryGeoDisplayTitle(ADDR_PROVINCE_TITLE_SPEC, plain, path);
    if (title) {
      row.addrProvinceTitle = title;
    }
  }
};

/** When legacy `MembershipOn` is null, show registration date (`created_at`) in list grids. */
const attachListMembershipOnFallback = (rows: Record<string, unknown>[]): void => {
  for (const row of rows) {
    if (readStringField(row, 'membershipOn')) {
      continue;
    }
    const created = readStringField(row, 'createdAt') || readStringField(row, 'created_at');
    if (!created) {
      continue;
    }
    row.membershipOn = created.length >= 10 ? created.slice(0, 10) : created;
  }
};

const attachListMemberInstituteSummaries = async (
  rows: Record<string, unknown>[],
): Promise<void> => {
  const memberIds = [
    ...new Set(rows.map((row) => readStringField(row, 'id')).filter(Boolean)),
  ];
  if (memberIds.length === 0) {
    return;
  }
  const summaryByMember = await loadActiveMemberInstituteTitlesForList(memberIds);
  if (summaryByMember.size === 0) {
    return;
  }
  for (const row of rows) {
    const memberId = readStringField(row, 'id');
    const summary = summaryByMember.get(memberId);
    if (summary) {
      row.memberInstitutesSummary = summary;
    }
  }
};

export type EnrichHwyMemberDirectoryListRowsOptions = {
  /** Full electoral path is expensive (Base Info path resolve). List grids fall back to `addrProvinceTitle`. */
  includeElectoralDivisionPath?: boolean;
  /** Active institute memberships — one title per line in `memberInstitutesSummary`. */
  includeMemberInstitutesSummary?: boolean;
  /**
   * When true, empty `membership_on` is filled from `created_at` for list display (legacy parity on active lists).
   * Off on Waited / rejected queues so «membership date» is not confused with registration date.
   */
  includeListMembershipOnRegistrationFallback?: boolean;
  /** Six registration thumbnails + approve state for ImageFix list rows. */
  includeImageFixRegistrationThumbs?: boolean;
  /** List face column: `/api/hwy/member-files/...` from registration personal photo when profile avatar is empty. */
  includeListFaceAvatarsFromRegistration?: boolean;
  /** Legacy list scope (`HWY_Members_List_*`) for list-only field enrichment. */
  listScopeLegacy?: string | null;
  /** Legacy SingleView stat columns (`Read_List_SingleView`). */
  includeSingleViewStats?: boolean;
};

/** Lightweight list enrichment — batch geo display after SQL page fetch (avoids view UDFs on full scans). */
export async function enrichHwyMemberDirectoryListRows(
  rows: Record<string, unknown>[],
  queryLang: string,
  options: EnrichHwyMemberDirectoryListRowsOptions = {},
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  attachHwyMemberDirectoryDisplayFullName(rows);
  await applyHwyMemberDirectoryListFaceCaptionUsernames(rows, {
    listScopeLegacy: options.listScopeLegacy,
  });
  if (options.includeListMembershipOnRegistrationFallback !== false) {
    attachListMembershipOnFallback(rows);
  }
  await enrichHwyGenderCodeTitles(rows, queryLang);
  if (options.includeElectoralDivisionPath) {
    for (const row of rows) {
      if (!readStringField(row, 'regionId')) {
        const regionRef = resolveMemberDirectoryListElectoralRegionRef(row);
        if (regionRef) {
          row.regionId = regionRef;
        }
      }
    }
    const cultureId = resolveBaseInfoCultureId(queryLang);
    const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
    await attachHwyRegionElectoralPathsByRegionId(rows, cultureId, geoMap);
  }
  await attachListElectoralMaktabSummaries(rows, queryLang);
  await attachListAddrProvinceTitles(rows, queryLang);
  if (options.includeMemberInstitutesSummary) {
    await attachListMemberInstituteSummaries(rows);
  }
  const includeListFaceAvatarsFromRegistration = options.includeListFaceAvatarsFromRegistration
    ?? shouldEnrichListFaceAvatarsFromRegistrationForListScope(options.listScopeLegacy);
  if (options.includeImageFixRegistrationThumbs) {
    await attachImageFixRegistrationThumbsToMemberDirectoryRows(rows, {
      mirrorRegistrationPersonalPhotoToListFace: true,
    });
  } else if (includeListFaceAvatarsFromRegistration) {
    await attachImageFixRegistrationThumbsToMemberDirectoryRows(rows, {
      mirrorRegistrationPersonalPhotoToListFace: true,
    });
  }
  if (options.includeSingleViewStats) {
    await attachHwyMemberSingleViewStatsToListRows(rows);
  }
  if (!options.includeImageFixRegistrationThumbs) {
    if (includeListFaceAvatarsFromRegistration) {
      slimRegistrationImageFixThumbsForListFaceOnly(rows);
    } else {
      for (const row of rows) {
        delete row.registrationImageFixThumbs;
      }
    }
  }
  const scopedEdit = resolveHwyMemberListScopedEditProfile(options.listScopeLegacy);
  if (scopedEdit?.kind === 'institute_character' && scopedEdit.instituteCode) {
    await attachListInstituteCharacterFields(rows, scopedEdit.instituteCode, queryLang);
  }
}

/** Resolve coded member-directory fields to Base Info titles (detail + getOne). */
export async function enrichHwyMemberDirectoryRows(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  attachHwyMemberDirectoryDisplayFullName(rows);
  await applyHwyMemberDirectoryListFaceCaptionUsernames(rows);
  await attachHwyMemberDossierProfileRailLoginUsername(rows);
  await enrichHwyGenderCodeTitles(rows, queryLang);

  const geoMap = await loadHwyEtlGeoBaseInfoIdMap();
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const lookupIds = new Set<string>();

  for (const row of rows) {
    for (const spec of MEMBER_DIRECTORY_CODED_FIELDS) {
      const raw = readStringField(row, spec.sourceField);
      const id = resolveBaseInfoLookupId(raw, spec, geoMap);
      if (id) {
        lookupIds.add(id);
      }
    }
  }

  if (lookupIds.size === 0) {
    return;
  }

  const enriched = await listBaseInfoEnrichmentRowsByIds([...lookupIds], cultureId);
  const byId = new Map(enriched.map((item) => [String(item.id ?? '').trim(), item]));

  for (const row of rows) {
    for (const spec of MEMBER_DIRECTORY_CODED_FIELDS) {
      if (readStringField(row, spec.titleField)) {
        continue;
      }
      const raw = readStringField(row, spec.sourceField);
      const id = resolveBaseInfoLookupId(raw, spec, geoMap);
      if (!id) {
        continue;
      }
      const match = byId.get(id);
      if (!match) {
        continue;
      }
      const pathTitle = String(match.title_path ?? '').trim();
      const plainTitle = String(match.title ?? match.title_canonical ?? '').trim();
      const resolved = resolveMemberDirectoryGeoDisplayTitle(spec, plainTitle, pathTitle);
      if (resolved) {
        row[spec.titleField] = resolved;
      }
    }
  }

  const legacyLookupIds: number[] = [];
  for (const row of rows) {
    for (const spec of LEGACY_HWY_ADDRESS_TITLE_FIELDS) {
      if (readStringField(row, spec.titleField)) {
        continue;
      }
      const raw = readStringField(row, spec.sourceField);
      if (/^\d+$/.test(raw)) {
        legacyLookupIds.push(Number(raw));
      }
    }
  }

  if (legacyLookupIds.length === 0) {
    return;
  }

  const legacyTitles = await getLegacyHwyBaseInformationTitlesByIds(legacyLookupIds);
  if (legacyTitles.size === 0) {
    return;
  }

  for (const row of rows) {
    for (const spec of LEGACY_HWY_ADDRESS_TITLE_FIELDS) {
      if (readStringField(row, spec.titleField)) {
        continue;
      }
      const raw = readStringField(row, spec.sourceField);
      if (!/^\d+$/.test(raw)) {
        continue;
      }
      const title = legacyTitles.get(Number(raw));
      if (title) {
        row[spec.titleField] = title;
      }
    }
  }
}
