/** Legacy Hawiety `GenderId` → platform Base Info id (matches `scripts/hwy-etl/legacyMaps.ts`). */
export const HWY_LEGACY_GENDER_ID_TO_BASE_INFO: Readonly<Record<number, string>> = {
  10011: '100.1.1',
  10012: '100.1.2',
};

export const resolveHwyLegacyGenderBaseInfoId = (raw: string): string | null => {
  const trimmed = raw.trim();
  if (!trimmed) {
    return null;
  }
  if (/^\d+\.\d+/.test(trimmed)) {
    return trimmed;
  }
  const legacyId = Number(trimmed);
  if (Number.isFinite(legacyId)) {
    return HWY_LEGACY_GENDER_ID_TO_BASE_INFO[legacyId] ?? null;
  }
  return trimmed;
};
