import type { DesignerDataGridColumn } from '../component-designer/designerDataGridColumns';
import { HWY_MEMBER_SEGMENT_LIST_COLUMN_LABEL_KEYS } from './hwyMemberSegmentListCatalog';

export const HWY_MEMBER_DIRECTORY_DEFAULT_SORT_FIELD = 'updatedAt';

export const HWY_MEMBERS_ALL_PAGE_NAME = 'hwy-members-all';

export const HWY_MEMBER_IMAGE_FIX_PAGE_NAME = 'hwy-members-image-fix';

export type HwyMemberDirectoryFooterSortOption = {
  value: string;
  label: string;
  labelTranslationKey?: string;
};

const HWY_MEMBER_DIRECTORY_FOOTER_SORT_STATUS_OPTION: HwyMemberDirectoryFooterSortOption = {
  value: 'membershipStatusCodeTitle',
  label: 'Status',
  labelTranslationKey: 'hwy.members.column.status',
};

/** Shared footer sort fields for segment / queue member lists (no status). */
export const HWY_MEMBER_DIRECTORY_SCOPED_FOOTER_SORT_OPTIONS: ReadonlyArray<HwyMemberDirectoryFooterSortOption> = [
  {
    value: 'updatedAt',
    label: 'Modified on',
    labelTranslationKey: 'hwy.members.column.updatedAt',
  },
  {
    value: 'createdAt',
    label: 'Created on',
    labelTranslationKey: HWY_MEMBER_SEGMENT_LIST_COLUMN_LABEL_KEYS.createdAt,
  },
  {
    value: 'membershipOn',
    label: 'Membership on',
    labelTranslationKey: 'hwy.members.column.membershipOn',
  },
  {
    value: 'displayFullName',
    label: 'Member',
    labelTranslationKey: 'hwy.members.column.member',
  },
  {
    value: 'electoralDivisionPath',
    label: 'Electoral division',
    labelTranslationKey: 'hwy.members.column.electoralDivision',
  },
];

const HWY_MEMBER_DIRECTORY_FOOTER_SORT_MEMBERSHIP_STATUS_UPDATED_OPTION: HwyMemberDirectoryFooterSortOption = {
  value: 'membershipStatusUpdatedOn',
  label: 'Status updated on',
  labelTranslationKey: HWY_MEMBER_SEGMENT_LIST_COLUMN_LABEL_KEYS.membershipStatusUpdatedOn,
};

/** ImageFix default sort (`MembershipStatus_UpdatedOn` DESC in legacy). */
export const HWY_MEMBER_IMAGE_FIX_FOOTER_SORT_OPTIONS: ReadonlyArray<HwyMemberDirectoryFooterSortOption> = [
  HWY_MEMBER_DIRECTORY_FOOTER_SORT_MEMBERSHIP_STATUS_UPDATED_OPTION,
  ...HWY_MEMBER_DIRECTORY_SCOPED_FOOTER_SORT_OPTIONS,
];

/** `hwy-members-all` only — includes status sort. */
export const HWY_MEMBER_DIRECTORY_ALL_PEOPLE_FOOTER_SORT_OPTIONS: ReadonlyArray<HwyMemberDirectoryFooterSortOption> = [
  ...HWY_MEMBER_DIRECTORY_SCOPED_FOOTER_SORT_OPTIONS,
  HWY_MEMBER_DIRECTORY_FOOTER_SORT_STATUS_OPTION,
];

/** @deprecated Use scoped or all-people lists explicitly. */
export const HWY_MEMBER_DIRECTORY_CANONICAL_FOOTER_SORT_OPTIONS = HWY_MEMBER_DIRECTORY_ALL_PEOPLE_FOOTER_SORT_OPTIONS;

export const resolveHwyMemberDirectoryFooterSortOptions = (
  pageName: string,
): HwyMemberDirectoryFooterSortOption[] => {
  if (pageName === HWY_MEMBERS_ALL_PAGE_NAME) {
    return [...HWY_MEMBER_DIRECTORY_ALL_PEOPLE_FOOTER_SORT_OPTIONS];
  }
  if (pageName === HWY_MEMBER_IMAGE_FIX_PAGE_NAME) {
    return [...HWY_MEMBER_IMAGE_FIX_FOOTER_SORT_OPTIONS];
  }
  return [...HWY_MEMBER_DIRECTORY_SCOPED_FOOTER_SORT_OPTIONS];
};

export const buildHwyMemberDirectoryFooterSortOptions = (
  pageNameOrColumns?: string | readonly DesignerDataGridColumn[],
): HwyMemberDirectoryFooterSortOption[] => {
  if (typeof pageNameOrColumns === 'string') {
    return resolveHwyMemberDirectoryFooterSortOptions(pageNameOrColumns);
  }
  return [...HWY_MEMBER_DIRECTORY_SCOPED_FOOTER_SORT_OPTIONS];
};
