import { prisma } from '../../../src/server/domain/users/prismaHelpers';
import {
  HWY_MEMBERSHIP_STATUS_UI_COLOR_BY_SHORT_NAME,
} from '../../../src/domain/hwy/hwyMembershipStatusUiColors';
import { invalidateBaseInfoOptionsCache } from '../../../src/server/services/baseInfoOptionsCache';
import { findHwyBaseInfoItemId } from './seedHwyBaseInfo';

export const HWY_MEMBERSHIP_STATUS_CATEGORY = 'Membership Status';

export async function persistHwyMembershipStatusUiColors(): Promise<number> {
  let count = 0;
  for (const [shortName, uiColor] of Object.entries(HWY_MEMBERSHIP_STATUS_UI_COLOR_BY_SHORT_NAME)) {
    const id = await findHwyBaseInfoItemId(HWY_MEMBERSHIP_STATUS_CATEGORY, shortName);
    await prisma().baseInfo.update({
      where: { id },
      data: { uiColor },
    });
    count += 1;
  }
  invalidateBaseInfoOptionsCache();
  return count;
}
