import type { EdgeModelDefinition } from '../../../shared/api/contracts/data-api';
import { unwrapDataApiWriteRequestBody } from '../../services/data-api/dataApiRequestBody';
import {
  applyHwyInstituteLogoPayloadFields,
  loadHwyInstituteLogoFlags,
  resolveHwyInstituteLogoUrlForClient,
} from './hwyInstituteLogo.service';

export const HWY_INSTITUTES_OBJECT_NAME = 'hwy_institutes';

const LOGO_PAYLOAD_KEYS = ['logoContentBase64', 'logoContentType', 'logoContentClear'] as const;

/** Managed-function proxy may nest the JSON body under `body` while mirroring fields at the top level. */
export const mergeHwyInstitutesDataApiRequestBody = (raw: unknown): Record<string, unknown> =>
  unwrapDataApiWriteRequestBody(raw);

export const isHwyInstitutesEdgeModel = (model: EdgeModelDefinition): boolean =>
  model.objectName === HWY_INSTITUTES_OBJECT_NAME;

export const stripHwyInstituteLogoFieldsFromSequelizePayload = (
  payload: Record<string, unknown>,
): void => {
  for (const key of LOGO_PAYLOAD_KEYS) {
    delete payload[key];
  }
};

export async function applyHwyInstitutesLogoFromDataApiBody(
  instituteId: number,
  rawBody: unknown,
): Promise<void> {
  if (!Number.isFinite(instituteId) || instituteId <= 0) {
    return;
  }
  await applyHwyInstituteLogoPayloadFields(instituteId, mergeHwyInstitutesDataApiRequestBody(rawBody));
}

export async function attachHwyInstituteLogoUrlsToRows(
  rows: Array<Record<string, unknown>>,
): Promise<Array<Record<string, unknown>>> {
  const logoFlags = await loadHwyInstituteLogoFlags(
    rows.map((row) => Number(row.id)).filter((id) => Number.isFinite(id) && id > 0),
  );
  return rows.map((row) => {
    const id = Number(row.id);
    const hasLogo = Number.isFinite(id) && logoFlags.has(id);
    return {
      ...row,
      logoUrl: resolveHwyInstituteLogoUrlForClient(id, hasLogo),
    };
  });
}

export async function attachHwyInstituteLogoUrlToRow(
  row: Record<string, unknown> | null,
): Promise<Record<string, unknown> | null> {
  if (!row) {
    return null;
  }
  const [withLogo] = await attachHwyInstituteLogoUrlsToRows([row]);
  return withLogo ?? null;
}
