import { HWY_SELF_REGISTRATION_EDUCATION_LEVEL_LEGACY_FALLBACK } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationEducationJobVocabCatalog';
import { prisma } from '../users/prismaHelpers';

const HWY_BASE_INFO_ROOT_ID = '220';
/** Must match `HWY_BASE_INFO_ROOT_TITLE` in `scripts/hwy-phase1/seed/hwyBaseInfoCatalog.ts`. */
const HWY_BASE_INFO_ROOT_TITLE = 'Hawiety';

let cachedRootId: string | null = null;
const categoryIdByTitle = new Map<string, string>();

const findRootId = async (): Promise<string> => {
  if (cachedRootId) {
    return cachedRootId;
  }
  const root = await prisma().baseInfo.findFirst({
    where: { parentId: null, title: HWY_BASE_INFO_ROOT_TITLE },
    select: { id: true },
  })
  ?? await prisma().baseInfo.findUnique({
    where: { id: HWY_BASE_INFO_ROOT_ID },
    select: { id: true },
  });
  if (!root?.id) {
    throw new Error('Hawiety Base Info root missing.');
  }
  cachedRootId = root.id;
  return cachedRootId;
};

const findCategoryId = async (categoryTitle: string): Promise<string> => {
  const cached = categoryIdByTitle.get(categoryTitle);
  if (cached) {
    return cached;
  }
  const rootId = await findRootId();
  const category = await prisma().baseInfo.findFirst({
    where: { parentId: rootId, title: categoryTitle },
    select: { id: true },
  });
  if (!category?.id) {
    throw new Error(`Hawiety Base Info category "${categoryTitle}" missing.`);
  }
  categoryIdByTitle.set(categoryTitle, category.id);
  return category.id;
};

export const findHwyBaseInfoItemIdByShortName = async (
  categoryTitle: string,
  shortName: string,
): Promise<string> => {
  const categoryId = await findCategoryId(categoryTitle);
  const item = await prisma().baseInfo.findFirst({
    where: { parentId: categoryId, shortName },
    select: { id: true },
  });
  if (!item) {
    throw new Error(`Hawiety Base Info item "${shortName}" missing under "${categoryTitle}".`);
  }
  return item.id;
};

export const tryFindHwyBaseInfoItemIdByShortName = async (
  categoryTitle: string,
  shortName: string,
): Promise<string | null> => {
  try {
    return await findHwyBaseInfoItemIdByShortName(categoryTitle, shortName);
  } catch {
    return null;
  }
};

const legacyCategoryLeafShortName = (categoryTitle: string, legacyLeafId: number): string => (
  `legacy_${categoryTitle.replace(/\s+/g, '_').toLowerCase()}_${legacyLeafId}`
);

/** Platform `base_info.id` for a legacy `HWY_BaseInformation` leaf (ETL view-order sync). */
export const findHwyBaseInfoItemIdByLegacyCategoryLeafId = async (
  categoryTitle: string,
  legacyLeafId: number,
): Promise<string> => {
  const categoryId = await findCategoryId(categoryTitle);
  const byShortName = await prisma().baseInfo.findFirst({
    where: { parentId: categoryId, shortName: legacyCategoryLeafShortName(categoryTitle, legacyLeafId) },
    select: { id: true },
  });
  if (byShortName?.id) {
    return byShortName.id;
  }
  if (categoryTitle === 'Education Level') {
    const legacyIndex = HWY_SELF_REGISTRATION_EDUCATION_LEVEL_LEGACY_FALLBACK.findIndex(
      (row) => row.legacyId === String(legacyLeafId),
    );
    if (legacyIndex >= 0) {
      const platformItems = await prisma().baseInfo.findMany({
        where: { parentId: categoryId },
        orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
        select: { id: true },
      });
      const pairedId = platformItems[legacyIndex]?.id;
      if (pairedId) {
        return pairedId;
      }
    }
  }
  throw new Error(
    `Hawiety Base Info legacy leaf ${legacyLeafId} missing under "${categoryTitle}" `
    + `(expected shortName ${legacyCategoryLeafShortName(categoryTitle, legacyLeafId)} or view-order pair).`,
  );
};
