import {
  findHwyMemberSegmentListByLegacyCode,
  type HwyMemberListScopeKind,
} from './hwyMemberSegmentListCatalog';

/** Bump when contract tests or policy change (see shard package-hawiety-member-face-caption). */
export const HWY_MEMBER_DIRECTORY_FACE_CAPTION_CONTRACT_VERSION = 1;

/**
 * Locked face-caption modes for Hawiety member-directory lists.
 *
 * - **membership_username** (default): six-digit allocated username → blue; else tracking → red.
 * - **tracking_only** (applicant / queue lists): always tracking code → red; never blue username.
 *
 * Business rule: allocated membership username means the person is not on Waited / Marfoozeh queues.
 * Tests: `hwyMemberDirectoryListFaceCaptionMode.test.ts` · `hwyMemberFaceCaptionListContract.test.ts`
 */
export type HwyMemberDirectoryListFaceCaptionMode = 'membership_username' | 'tracking_only';

const scopeUsesTrackingOnlyFaceCaption = (scope: HwyMemberListScopeKind): boolean => {
  switch (scope.type) {
    case 'membership_status':
      return scope.status !== 'active';
    case 'pending_local_institute':
      return true;
    default:
      return false;
  }
};

export const isHwyMemberDirectoryListFaceCaptionTrackingOnlyScope = (
  listScopeLegacy: string | null | undefined,
): boolean => (
  resolveHwyMemberDirectoryListFaceCaptionMode(listScopeLegacy) === 'tracking_only'
);

export const resolveHwyMemberDirectoryListFaceCaptionMode = (
  listScopeLegacy: string | null | undefined,
): HwyMemberDirectoryListFaceCaptionMode => {
  const scope = listScopeLegacy?.trim();
  if (!scope) {
    return 'membership_username';
  }
  const definition = findHwyMemberSegmentListByLegacyCode(scope);
  if (!definition) {
    return 'membership_username';
  }
  return scopeUsesTrackingOnlyFaceCaption(definition.scope)
    ? 'tracking_only'
    : 'membership_username';
};
