import { QueryTypes } from 'sequelize';

import {
  isHwyMemberOtherAttachmentKindSlug,
  resolveHwyMemberFileKindUploadShape,
} from '../../../domain/hwy/hwyMemberFileKindCatalog';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

const MEMBER_FILE_KIND_CATEGORY_TITLE = 'Member File Kind';
const HWY_BASE_INFO_ROOT_ID = '220';

export type ResolvedHwyMemberFileKind = {
  id: string;
  shortName: string;
};

export async function resolveHwyMemberFileKindBySlugOrId(
  slugOrId: string,
): Promise<ResolvedHwyMemberFileKind | null> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return null;
  }
  const raw = slugOrId.trim();
  if (!raw) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();

  const byId = await sequelize.query<{ id: string; shortName: string }>(
    `
    SELECT CAST(c.id AS NVARCHAR(32)) AS id, c.short_name AS shortName
    FROM dbo.base_info c
    INNER JOIN dbo.base_info cat ON cat.id = c.parent_id
    WHERE cat.title = :categoryTitle
      AND cat.parent_id = :rootId
      AND c.id = :raw
    `,
    {
      replacements: { raw, categoryTitle: MEMBER_FILE_KIND_CATEGORY_TITLE, rootId: HWY_BASE_INFO_ROOT_ID },
      type: QueryTypes.SELECT,
    },
  );
  if (byId[0]?.id) {
    return byId[0];
  }

  const bySlug = await sequelize.query<{ id: string; shortName: string }>(
    `
    SELECT CAST(c.id AS NVARCHAR(32)) AS id, c.short_name AS shortName
    FROM dbo.base_info c
    INNER JOIN dbo.base_info cat ON cat.id = c.parent_id
    WHERE cat.title = :categoryTitle
      AND cat.parent_id = :rootId
      AND c.short_name = :raw
    `,
    {
      replacements: { raw, categoryTitle: MEMBER_FILE_KIND_CATEGORY_TITLE, rootId: HWY_BASE_INFO_ROOT_ID },
      type: QueryTypes.SELECT,
    },
  );
  return bySlug[0] ?? null;
}

export type HwyMemberDossierRegistrationFileSlot = {
  fileKindCode: string;
  fileKindSlug: string;
  fileKindCodeTitle?: string;
  existingFileId?: string;
  shape: 'circle' | 'rectangle';
};

export async function listHwyMemberDossierRegistrationFileSlots(
  memberId: number,
  queryLang: string,
): Promise<HwyMemberDossierRegistrationFileSlot[]> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  const sequelize = getControlPlaneSequelize();

  const kindRows = await sequelize.query<{
    id: string;
    shortName: string;
    viewOrder: number;
    titleCanonical: string;
  }>(
    `
    SELECT
      CAST(c.id AS NVARCHAR(32)) AS id,
      c.short_name AS shortName,
      c.view_order AS viewOrder,
      c.title AS titleCanonical
    FROM dbo.base_info c
    INNER JOIN dbo.base_info cat ON cat.id = c.parent_id
    WHERE cat.title = :categoryTitle
      AND cat.parent_id = :rootId
      AND c.short_name <> 'other_attachment'
    ORDER BY c.view_order, c.id
    `,
    {
      replacements: {
        categoryTitle: MEMBER_FILE_KIND_CATEGORY_TITLE,
        rootId: HWY_BASE_INFO_ROOT_ID,
      },
      type: QueryTypes.SELECT,
    },
  );

  const fileRows = await sequelize.query<{ id: string; fileKindCode: string }>(
    `
    SELECT CAST(f.id AS NVARCHAR(32)) AS id, f.file_kind_code AS fileKindCode
    FROM dbo.hwy_member_files f
    WHERE f.member_id = :memberId
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );

  const fileByKind = new Map<string, string>();
  for (const row of fileRows) {
    const kind = String(row.fileKindCode ?? '').trim();
    if (kind && !fileByKind.has(kind)) {
      fileByKind.set(kind, String(row.id));
    }
  }

  const cultureId = resolveBaseInfoCultureId(queryLang);
  const enriched = await listBaseInfoEnrichmentRowsByIds(
    kindRows.map((row) => row.id),
    cultureId,
  );
  const titleById = new Map(
    enriched.map((item) => [String(item.id ?? '').trim(), String(item.title ?? item.title_canonical ?? '').trim()]),
  );

  return kindRows.map((row) => ({
    fileKindCode: row.id,
    fileKindSlug: row.shortName,
    fileKindCodeTitle: titleById.get(row.id) || row.titleCanonical,
    existingFileId: fileByKind.get(row.id),
    shape: resolveHwyMemberFileKindUploadShape(row.shortName),
  }));
}

export async function resolveHwyMemberFileKindSlugById(
  fileKindCode: string,
): Promise<string | null> {
  const resolved = await resolveHwyMemberFileKindBySlugOrId(fileKindCode);
  return resolved?.shortName ?? null;
}

export function isHwyMemberFileKindMultiRowSlug(slug: string | null | undefined): boolean {
  return isHwyMemberOtherAttachmentKindSlug(slug);
}
