import { QueryTypes } from 'sequelize';

import type { HwyMemberDossierProfileNavCounts } from '../../../domain/hwy/hwyMemberDossierProfileNavCounts';
import { HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG } from '../../../domain/hwy/hwyMemberFileKindCatalog';
import {
  HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER,
} from '../../../domain/hwy/hwyMemberSimilarMembers';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyMemberDossierSatellitesSchema } from './ensureHwyMemberDossierSatellitesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { countHwyMemberActivityAndCourseAttendances } from './hwyMemberCoursesActivities.service';
import { listHwyMemberDossierChangeLog } from './hwyMemberDossierChangeLog.service';
import { listHwyMemberSimilarMembers } from './hwyMemberSimilarMembers.service';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

const emptyCounts = (): HwyMemberDossierProfileNavCounts => ({
  files: 0,
  notes: 0,
  securityProfile: 0,
  institutes: 0,
  kasb: 0,
  similarMembers: 0,
  targhin: 0,
  changeLog: 0,
  activities: 0,
  courses: 0,
});

const resolveMemberPrimaryKey = async (raw: string): Promise<number> => {
  const trimmed = raw.trim();
  if (!trimmed) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  if (/^\d+$/.test(trimmed)) {
    const id = Number(trimmed);
    if (Number.isFinite(id) && id > 0) {
      const byId = await sequelize.query<{ id: number }>(
        `SELECT id FROM dbo.hwy_members WHERE id = :id`,
        { replacements: { id }, type: QueryTypes.SELECT },
      );
      if (byId.length) {
        return byId[0].id;
      }
    }
  }
  const byUsername = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.hwy_members WHERE username = :username`,
    { replacements: { username: trimmed }, type: QueryTypes.SELECT },
  );
  if (byUsername.length) {
    return byUsername[0].id;
  }
  throw new Error('Member not found.');
};

const readCount = (row: Record<string, unknown>, key: string): number => {
  const value = Number(row[key] ?? 0);
  return Number.isFinite(value) && value > 0 ? value : 0;
};

const countSimilarMembersDistinct = async (
  memberIdRaw: string,
  queryLang: string,
  session: SessionScopeSnapshot | null,
): Promise<number> => {
  try {
    const payload = await listHwyMemberSimilarMembers(
      memberIdRaw,
      HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER,
      queryLang,
      session,
    );
    const ids = new Set<string>();
    for (const row of payload.byName) {
      const id = row.id?.trim();
      if (id) {
        ids.add(id);
      }
    }
    for (const row of payload.byFilter) {
      const id = row.id?.trim();
      if (id) {
        ids.add(id);
      }
    }
    return ids.size;
  } catch {
    return 0;
  }
};

export async function getHwyMemberDossierProfileNavCounts(
  memberIdRaw: string,
  queryLang = 'ar',
  session: SessionScopeSnapshot | null = null,
): Promise<HwyMemberDossierProfileNavCounts> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return emptyCounts();
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
  const memberId = await resolveMemberPrimaryKey(memberIdRaw);

  const [countRow, similarMembers, changeLogPayload, coursesActivities] = await Promise.all([
    execHwyProcedure<Record<string, unknown>>('hwy_member_dossier_nav_counts', {
      member_id: memberId,
      profile_photo_kind_slug: HWY_MEMBER_DOSSIER_PROFILE_PHOTO_KIND_SLUG,
    }),
    countSimilarMembersDistinct(memberIdRaw, queryLang, session),
    listHwyMemberDossierChangeLog(memberIdRaw, queryLang).catch(() => ({ events: [] })),
    countHwyMemberActivityAndCourseAttendances(memberIdRaw).catch(() => ({ activities: 0, courses: 0 })),
  ]);

  const row = countRow[0] ?? {};
  return {
    files: readCount(row, 'files'),
    notes: readCount(row, 'notes'),
    securityProfile: readCount(row, 'securityProfile'),
    institutes: readCount(row, 'institutes'),
    kasb: readCount(row, 'kasb'),
    similarMembers,
    targhin: readCount(row, 'targhin'),
    changeLog: changeLogPayload.events?.length ?? 0,
    activities: coursesActivities.activities,
    courses: coursesActivities.courses,
  };
}
