import type { HwyMemberDirectoryDetail } from './hwyMemberDirectoryDetail';
import {
  isHwyMemberMembershipStatusActive,
  isHwyMemberMembershipStatusTarghined,
  type HwyMembershipStatusIdMap,
} from './hwyMembershipDecision';
import {
  resolveHwyMemberFaceCaption,
  type HwyMemberFaceCaption,
} from './hwyMemberFaceCaptionDisplay';

/**
 * Locked dossier profile-rail caption — same rules as member-directory list avatars
 * (`hwyMemberFaceCaptionListContract.test.ts`):
 * - Six-digit allocated membership username → `username` (blue).
 * - Otherwise tracking code, else member id → `tracking` (red).
 *
 * Do not add status branches or non-six-digit username promotion here.
 * Detail getOne enrichment (`attachHwyMemberDossierProfileRailLoginUsername`) fills
 * `username` on the row before the client renders.
 *
 * Tests: `hwyMemberDossierProfileRailFaceCaption.test.ts`
 */

/** Active or targhined — server may attach allocated login username on detail getOne. */
export function isHwyMemberDossierProfileRailJoinedMember(
  membershipStatusCode: string | null | undefined,
  membershipStatusIds: HwyMembershipStatusIdMap | undefined,
): boolean {
  return (
    isHwyMemberMembershipStatusActive(membershipStatusCode, membershipStatusIds)
    || isHwyMemberMembershipStatusTarghined(membershipStatusCode, membershipStatusIds)
  );
}

/** Profile rail under avatar — delegate to shared face caption (includes `userUsername` row fields). */
export function resolveHwyMemberDossierProfileRailFaceCaption(
  member: HwyMemberDirectoryDetail,
): HwyMemberFaceCaption {
  return resolveHwyMemberFaceCaption(member as Record<string, unknown>);
}
