import { QueryTypes } from 'sequelize';

import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyMemberDossierSatellitesSchema } from './ensureHwyMemberDossierSatellitesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { formatProfileDisplayName } from '../../../shared/profile/profileDisplayName';
import { resolveNegoNoteAuthorsBatch } from './hwyMemberTarghinNegoAuthorResolve';
import { resolveHwyTarghinNegoActorLegacyUsername } from './hwyMemberTarghinNegoActor';

const NOTE_MAX_LENGTH = 4000;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Targhin negotiation notes require SQL Server control plane.');
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
};

export type HwyMemberTarghinNegoNoteRow = {
  id: string;
  memberId: string;
  note: string;
  createdAt: string;
  createdByLegacy: string;
  author: HwyMemberTarghinAdminMemberFace | null;
};

type RawNegoRow = Record<string, unknown>;

const mapAuthorFace = (row: RawNegoRow): HwyMemberTarghinAdminMemberFace | null => {
  const memberAuthorId = trim(row.authorId as string | undefined);
  const memberDisplay = trim(row.authorDisplayFullName as string | undefined);
  const memberUsername = trim(row.authorUsername as string | undefined);
  const accountUserId = row.createdByUserId != null ? Number(row.createdByUserId) : null;
  const accountUsername = trim(row.accountUsername as string | undefined);
  const accountDisplay = formatProfileDisplayName({
    firstname: row.accountFirstname as string | null | undefined,
    lastname: row.accountLastname as string | null | undefined,
    companyName: row.accountCompanyName as string | null | undefined,
    personTypeCode: row.accountPersonTypeCode as string | null | undefined,
  });

  if (memberAuthorId && (memberDisplay || memberUsername)) {
    return {
      id: memberAuthorId,
      username: memberUsername || null,
      displayFullName: formatHwyMemberPersonDisplayName(memberDisplay) || memberUsername || null,
      genderCode: trim(row.authorGenderCode as string | undefined) || null,
      avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
        avatarUrl: trim(row.authorAvatarUrl as string | undefined) || null,
        hasProfileImage: row.authorHasProfileImage === true || row.authorHasProfileImage === 1,
        userId: row.authorUserId != null ? Number(row.authorUserId) : null,
      }),
      phone: trim(row.authorPhone as string | undefined) || null,
      electoralDivisionPath: null,
    };
  }

  if (
    accountUserId
    && Number.isFinite(accountUserId)
    && accountUserId > 0
    && (accountUsername || accountDisplay)
  ) {
    return {
      id: `user-${accountUserId}`,
      username: accountUsername || null,
      displayFullName: formatHwyMemberPersonDisplayName(accountDisplay) || accountUsername || null,
      genderCode: null,
      avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
        avatarUrl: null,
        hasProfileImage: false,
        userId: accountUserId,
      }),
      phone: null,
      electoralDivisionPath: null,
    };
  }

  const legacy = trim(row.createdByLegacy as string | undefined);
  if (legacy && !/^\d+$/.test(legacy)) {
    return {
      id: legacy,
      username: legacy,
      displayFullName: legacy,
      genderCode: null,
      avatarUrl: null,
      phone: null,
      electoralDivisionPath: null,
    };
  }

  return null;
};

export const listHwyMemberTarghinNegoNotes = async (
  memberIdRaw: string,
): Promise<HwyMemberTarghinNegoNoteRow[]> => {
  await assertSqlServer();
  const memberId = trim(memberIdRaw);
  if (!memberId) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<RawNegoRow>(
    `
    SELECT
      CAST(n.id AS VARCHAR(32)) AS id,
      CAST(n.member_id AS VARCHAR(32)) AS memberId,
      n.note AS note,
      n.created_at AS createdAt,
      n.created_by_legacy AS createdByLegacy,
      CAST(n.created_by_user_id AS VARCHAR(32)) AS createdByUserId,
      bu.username AS accountUsername,
      bp.firstname AS accountFirstname,
      bp.lastname AS accountLastname,
      bp.company_name AS accountCompanyName,
      bp.person_type_code AS accountPersonTypeCode,
      CAST(vm.id AS VARCHAR(32)) AS authorId,
      vm.username AS authorUsername,
      vm.display_full_name AS authorDisplayFullName,
      vm.gender_code AS authorGenderCode,
      vm.avatar_url AS authorAvatarUrl,
      vm.has_profile_image AS authorHasProfileImage,
      CAST(vm.user_id AS VARCHAR(32)) AS authorUserId,
      vm.phone1 AS authorPhone
    FROM dbo.hwy_member_targhin_nego_notes n WITH (NOLOCK)
    LEFT JOIN dbo.base_users bu WITH (NOLOCK)
      ON bu.id = COALESCE(
        n.created_by_user_id,
        TRY_CAST(NULLIF(n.created_by_legacy, '') AS BIGINT)
      )
    LEFT JOIN dbo.base_user_profiles bp WITH (NOLOCK) ON bp.user_id = bu.id
    LEFT JOIN dbo.vw_hwy_members vm WITH (NOLOCK)
      ON (n.created_by_user_id IS NOT NULL AND vm.user_id = n.created_by_user_id)
      OR vm.username = n.created_by_legacy
      OR CAST(vm.id AS VARCHAR(32)) = n.created_by_legacy
      OR (bu.id IS NOT NULL AND vm.user_id = bu.id)
    WHERE n.member_id = :memberId
    ORDER BY n.created_at DESC, n.id DESC
    `,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  const mapped = rows.map((row) => {
    const createdByUserIdRaw = row.createdByUserId ?? (row as { createdbyuserid?: unknown }).createdbyuserid;
    const createdByUserId = createdByUserIdRaw != null ? Number(createdByUserIdRaw) : null;
    const author = mapAuthorFace(row);
    return {
      id: trim(row.id as string | undefined),
      memberId: trim(row.memberId as string | undefined),
      note: trim(row.note as string | undefined),
      createdAt: String(row.createdAt ?? ''),
      createdByLegacy: trim(row.createdByLegacy as string | undefined),
      createdByUserId: Number.isFinite(createdByUserId) && createdByUserId! > 0 ? createdByUserId! : null,
      author,
    };
  });

  const authorByNoteId = await resolveNegoNoteAuthorsBatch(
    mapped.map((row) => ({
      id: row.id,
      createdByLegacy: row.createdByLegacy,
      createdByUserId: row.createdByUserId,
      author: row.author,
    })),
  );

  return mapped.map(({ createdByUserId: _omit, ...row }) => ({
    ...row,
    author: authorByNoteId.get(row.id) ?? row.author,
  }));
};

export const createHwyMemberTarghinNegoNote = async (input: {
  memberId: string;
  note: string;
  actorUserId: number | null;
}): Promise<HwyMemberTarghinNegoNoteRow> => {
  await assertSqlServer();
  const memberId = trim(input.memberId);
  const note = trim(input.note);
  if (!memberId) {
    throw new Error('Member id is required.');
  }
  if (!note) {
    throw new Error('Note is required.');
  }
  if (note.length > NOTE_MAX_LENGTH) {
    throw new Error(`Note must be at most ${NOTE_MAX_LENGTH} characters.`);
  }

  const memberExists = await getControlPlaneSequelize().query<{ id: number }>(
    `SELECT id FROM dbo.hwy_members WHERE id = :memberId`,
    { replacements: { memberId: Number(memberId) }, type: QueryTypes.SELECT },
  );
  if (!memberExists.length) {
    throw new Error('Member not found.');
  }

  const createdByLegacy = await resolveHwyTarghinNegoActorLegacyUsername(input.actorUserId);
  if (!createdByLegacy) {
    throw new Error('Could not resolve actor for negotiation note.');
  }

  const inserted = await execHwyProcedure<{ id: number | string }>('hwy_targhin_nego_note_insert', {
    member_id: Number(memberId),
    note,
    created_by_legacy: createdByLegacy,
    created_by_user_id: input.actorUserId,
  });
  const id = String(inserted[0]?.id ?? '').trim();
  const rows = await listHwyMemberTarghinNegoNotes(memberId);
  const created = rows.find((row) => row.id === id);
  if (!created) {
    throw new Error('Could not load created negotiation note.');
  }
  return created;
};
