import { seedHwyBaseInfo } from '../../../../scripts/hwy-phase1/seed/seedHwyBaseInfo';
import { prisma } from '../users/prismaHelpers';
import { HWY_BASE_INFO_ROOT_ID } from './hwyBaseInfoRuntime';

const REGISTRATION_CHANNEL_CATEGORY_TITLE = 'Registration Channel';

let ensurePromise: Promise<void> | null = null;

const hasRegistrationChannelCategory = async (): Promise<boolean> => {
  const row = await prisma().baseInfo.findFirst({
    where: {
      parentId: HWY_BASE_INFO_ROOT_ID,
      title: REGISTRATION_CHANNEL_CATEGORY_TITLE,
    },
    select: { id: true },
  });
  return Boolean(row);
};

/**
 * Idempotent Hawiety Base Info seed for public self-registration submit
 * (Registration Channel, membership status, institute join path, etc.).
 */
export const ensureHwySelfRegistrationBaseInfo = async (): Promise<void> => {
  if (await hasRegistrationChannelCategory()) {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = (async () => {
      await seedHwyBaseInfo(null);
      if (!(await hasRegistrationChannelCategory())) {
        throw new Error(
          'Hawiety Base Info category "Registration Channel" is still missing after seed. Run npm run hwy:phase1.',
        );
      }
    })();
  }

  await ensurePromise;
};
