import { hwyEnvelopeGet, hwyEnvelopePost } from './hwyEnvelopeApi';
import type { HwyEmployeesListSearchInput } from './hwyEmployeesListFilterMapping';

export const HWY_EMPLOYEES_LIST_PAGE_KEY = 'hwy-employees-list';

export const HWY_EMPLOYEES_LIST_ROUTE_SEGMENT = 'employees-list';

export const HWY_EMPLOYEES_LIST_LEGACY_HINT = 'HWY_Employees_List';

export type HwyEmployeesListRow = {
  id: string;
  username: string | null;
  userId: string | null;
  firstName: string | null;
  fatherName: string | null;
  grandFatherName: string | null;
  lastName: string | null;
  displayFullName: string | null;
  avatarUrl: string | null;
  birthYear: string | null;
  genderCode: string | null;
  trackingCode: string | null;
  phone1: string | null;
  genderId: string | null;
  genderIdTitle: string | null;
  statFieldsCompleted: number | null;
  statOath: string | null;
  masooliatRoleOn: string | null;
  rolesLimits: string | null;
  areasLimits: string | null;
  genderLimits: string | null;
  orgLimits: string | null;
  uniLimits: string | null;
  jobL1Limits: string | null;
  ettehadLimits: string | null;
  nakhebJoinProvinceName: string | null;
  nakhebJoinCircleName: string | null;
  nakhebJoinTamvinName: string | null;
  nakhebJoinEghteraName: string | null;
  educationLevelIdTitle: string | null;
  jobTypeIdTitle: string | null;
  membershipOn: string | null;
  updatedOn: string | null;
};

export type HwyEmployeesListResult = {
  total: number;
  page: number;
  pageSize: number;
  rows: HwyEmployeesListRow[];
  parityDataSource?: 'edge' | 'legacy-read';
};

const buildQueryString = (input: HwyEmployeesListSearchInput): string => {
  const params = new URLSearchParams();
  const set = (key: string, value: string | undefined) => {
    const trimmed = String(value ?? '').trim();
    if (trimmed) params.set(key, trimmed);
  };
  set('username', input.username);
  set('phone', input.phone);
  set('firstName', input.firstName);
  set('fatherName', input.fatherName);
  set('grandFatherName', input.grandFatherName);
  set('lastName', input.lastName);
  set('genderId', input.genderId);
  set('roleId', input.roleId);
  set('vProvinceId', input.vProvinceId);
  set('vCircleId', input.vCircleId);
  set('vTamvinId', input.vTamvinId);
  set('vHasGhasam', input.vHasGhasam);
  set('vAreaHasProblem', input.vAreaHasProblem);
  set('vFieldsCompleted', input.vFieldsCompleted);
  if (input.page != null) params.set('page', String(input.page));
  if (input.pageSize != null) params.set('pageSize', String(input.pageSize));
  const qs = params.toString();
  return qs ? `?${qs}` : '';
};

export const listHwyEmployees = async (
  input: HwyEmployeesListSearchInput,
): Promise<HwyEmployeesListResult> =>
  hwyEnvelopeGet<HwyEmployeesListResult>(
    `/api/hwy/employees-list${buildQueryString(input)}`,
    undefined,
    'Could not load employees.',
  );

export const removeHwyEmployeeRoles = async (memberId: string): Promise<void> => {
  await hwyEnvelopePost(
    `/api/hwy/employees-list/${encodeURIComponent(memberId)}/remove`,
    {},
    'Could not remove employee roles.',
  );
};
