import { QueryTypes } from 'sequelize';

import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyMemberTarghinAdminFaceDossierMemberId } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { negoAuthorHasLabel } from './hwyMemberTarghinNegoAuthorResolve';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const mapVmRowToFace = (row: Record<string, unknown>): HwyMemberTarghinAdminMemberFace => ({
  id: trim(row.id as string | undefined),
  username: trim(row.username as string | undefined) || null,
  displayFullName: formatHwyMemberPersonDisplayName(trim(row.display_full_name as string | undefined)) || null,
  genderCode: trim(row.gender_code as string | undefined) || null,
  avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
    avatarUrl: trim(row.avatar_url as string | undefined) || null,
    hasProfileImage: row.has_profile_image === true || row.has_profile_image === 1,
    userId: row.user_id != null ? Number(row.user_id) : null,
  }),
  phone: trim(row.phone1 as string | undefined) || null,
  electoralDivisionPath: trim(row.electoral_division_path as string | undefined) || null,
});

const collectLookupKeysFromFace = (face: HwyMemberTarghinAdminMemberFace): string[] => {
  const keys: string[] = [];
  const id = trim(face.id);
  if (id) {
    keys.push(id);
  }
  const username = trim(face.username);
  if (username) {
    keys.push(username);
  }
  const legacyPrefix = 'legacy-membership-';
  if (id.startsWith(legacyPrefix)) {
    keys.push(id.slice(legacyPrefix.length).trim());
  }
  return keys.filter(Boolean);
};

/** Legacy actor keys are often membership usernames — match CP row by id OR username. */
export async function loadCpMemberFacesByActorKeys(
  actorKeys: readonly string[],
): Promise<Map<string, HwyMemberTarghinAdminMemberFace>> {
  const keys = [...new Set(actorKeys.map(trim).filter(Boolean))];
  const result = new Map<string, HwyMemberTarghinAdminMemberFace>();
  if (!keys.length) {
    return result;
  }

  const sequelize = getControlPlaneSequelize();
  const numericKeys = keys.filter((key) => /^\d+$/.test(key));
  const textKeys = keys.filter((key) => !/^\d+$/.test(key));

  if (numericKeys.length) {
    const idPlaceholders = numericKeys.map((_, index) => `:nid${index}`).join(', ');
    const usernamePlaceholders = numericKeys.map((_, index) => `:nun${index}`).join(', ');
    const replacements = Object.fromEntries([
      ...numericKeys.map((key, index) => [`nid${index}`, Number(key)] as const),
      ...numericKeys.map((key, index) => [`nun${index}`, key] as const),
    ]);
    const rows = await sequelize.query<Record<string, unknown>>(
      `
      SELECT CAST(id AS VARCHAR(32)) AS id, username, display_full_name, gender_code,
        avatar_url, has_profile_image, user_id, phone1, electoral_division_path
      FROM dbo.vw_hwy_members WITH (NOLOCK)
      WHERE id IN (${idPlaceholders})
         OR username IN (${usernamePlaceholders})
      `,
      { replacements, type: QueryTypes.SELECT },
    );
    for (const row of rows) {
      const face = mapVmRowToFace(row);
      if (!negoAuthorHasLabel(face)) {
        continue;
      }
      const memberId = trim(row.id as string | undefined);
      const username = trim(row.username as string | undefined);
      for (const key of keys) {
        if (key === memberId || key === username) {
          result.set(key, face);
        }
      }
    }
  }

  if (textKeys.length) {
    const unPlaceholders = textKeys.map((_, index) => `:tun${index}`).join(', ');
    const unReplacements = Object.fromEntries(textKeys.map((key, index) => [`tun${index}`, key]));
    const rows = await sequelize.query<Record<string, unknown>>(
      `
      SELECT CAST(id AS VARCHAR(32)) AS id, username, display_full_name, gender_code,
        avatar_url, has_profile_image, user_id, phone1, electoral_division_path
      FROM dbo.vw_hwy_members WITH (NOLOCK)
      WHERE username IN (${unPlaceholders})
      `,
      { replacements: unReplacements, type: QueryTypes.SELECT },
    );
    for (const row of rows) {
      const face = mapVmRowToFace(row);
      if (!negoAuthorHasLabel(face)) {
        continue;
      }
      const username = trim(row.username as string | undefined);
      if (username) {
        result.set(username, face);
      }
      result.set(trim(row.id as string | undefined), face);
    }
  }

  return result;
}

export async function finalizeTarghinMemberFaceForDossier(
  face: HwyMemberTarghinAdminMemberFace | null | undefined,
): Promise<HwyMemberTarghinAdminMemberFace | null | undefined> {
  if (!face) {
    return face;
  }
  const lookupKeys = collectLookupKeysFromFace(face);
  if (!lookupKeys.length) {
    return face;
  }
  const cpFaceByKey = await loadCpMemberFacesByActorKeys(lookupKeys);
  for (const key of lookupKeys) {
    const cpFace = cpFaceByKey.get(key);
    if (cpFace?.id && /^\d+$/.test(cpFace.id)) {
      return cpFace;
    }
  }
  return face;
}

const mergeCpFaceOntoTarghinFace = (
  target: HwyMemberTarghinAdminMemberFace,
  cpFace: HwyMemberTarghinAdminMemberFace,
): void => {
  target.id = cpFace.id;
  target.username = cpFace.username ?? target.username;
  target.displayFullName = cpFace.displayFullName ?? target.displayFullName;
  target.genderCode = cpFace.genderCode ?? target.genderCode;
  target.avatarUrl = cpFace.avatarUrl ?? target.avatarUrl;
  target.phone = cpFace.phone ?? target.phone;
  target.electoralDivisionPath = cpFace.electoralDivisionPath ?? target.electoralDivisionPath;
};

/** Second pass: map legacy / stub faces to CP rows by membership username (dossier link ids). */
export async function hydrateTarghinFacesForDossierLinks(
  faces: readonly (HwyMemberTarghinAdminMemberFace | null | undefined)[],
): Promise<void> {
  const pending = faces.filter(
    (face): face is HwyMemberTarghinAdminMemberFace => Boolean(
      face && !resolveHwyMemberTarghinAdminFaceDossierMemberId(face),
    ),
  );
  if (!pending.length) {
    return;
  }

  const lookupKeys = new Set<string>();
  for (const face of pending) {
    for (const key of collectLookupKeysFromFace(face)) {
      lookupKeys.add(key);
    }
  }

  if (lookupKeys.size) {
    const cpFaceByKey = await loadCpMemberFacesByActorKeys([...lookupKeys]);
    for (const face of pending) {
      if (resolveHwyMemberTarghinAdminFaceDossierMemberId(face)) {
        continue;
      }
      for (const key of collectLookupKeysFromFace(face)) {
        const cpFace = cpFaceByKey.get(key);
        if (cpFace?.id && /^\d+$/.test(cpFace.id)) {
          mergeCpFaceOntoTarghinFace(face, cpFace);
          break;
        }
      }
    }
  }

  const stillPending = pending.filter(
    (face) => !resolveHwyMemberTarghinAdminFaceDossierMemberId(face),
  );
  if (!stillPending.length) {
    return;
  }

  // Legacy MembersV2 username → member id mapping is skipped on list hot paths (see targhin services).
}

export async function finalizeTarghinMemberFacesForDossier<T>(
  rows: T[],
  readFace: (row: T) => HwyMemberTarghinAdminMemberFace | null | undefined,
  writeFace: (row: T, face: HwyMemberTarghinAdminMemberFace) => void,
): Promise<void> {
  const lookupKeys = new Set<string>();
  for (const row of rows) {
    const face = readFace(row);
    if (!face || resolveHwyMemberTarghinAdminFaceDossierMemberId(face)) {
      continue;
    }
    for (const key of collectLookupKeysFromFace(face)) {
      lookupKeys.add(key);
    }
  }
  if (!lookupKeys.size) {
    return;
  }

  const cpFaceByKey = await loadCpMemberFacesByActorKeys([...lookupKeys]);
  for (const row of rows) {
    const face = readFace(row);
    if (!face || resolveHwyMemberTarghinAdminFaceDossierMemberId(face)) {
      continue;
    }
    for (const key of collectLookupKeysFromFace(face)) {
      const cpFace = cpFaceByKey.get(key);
      if (cpFace?.id && /^\d+$/.test(cpFace.id)) {
        writeFace(row, cpFace);
        break;
      }
    }
  }
}
