/**
 * Referrer relation (`MoarrefRelationId`) — legacy parent 11180.
 * Same node as ETL «Nakhebin Link Type» (`scripts/hwy-etl/legacyMaps.ts` → view-order title sync).
 */

export const HWY_SELF_REGISTRATION_REFERRER_RELATION_ETL_CATEGORY_TITLE = 'Nakhebin Link Type' as const;

export type HwySelfRegistrationReferrerRelationFallbackRow = {
  legacyId: string;
  viewOrder: number;
  cultureLabelKey: string;
};

/** Active legacy leaves under parent 11180 — snapshot when legacy SQL is unavailable. */
export const HWY_SELF_REGISTRATION_REFERRER_RELATION_LEGACY_FALLBACK: HwySelfRegistrationReferrerRelationFallbackRow[] = [
  { legacyId: '11181', viewOrder: 1, cultureLabelKey: 'hwy.selfReg.referrerRelation.option.11181' },
  { legacyId: '11182', viewOrder: 2, cultureLabelKey: 'hwy.selfReg.referrerRelation.option.11182' },
  { legacyId: '11183', viewOrder: 3, cultureLabelKey: 'hwy.selfReg.referrerRelation.option.11183' },
  { legacyId: '11184', viewOrder: 4, cultureLabelKey: 'hwy.selfReg.referrerRelation.option.11184' },
  { legacyId: '11185', viewOrder: 5, cultureLabelKey: 'hwy.selfReg.referrerRelation.option.11185' },
];

const REFERRER_RELATION_CULTURE_KEY_BY_LEGACY_ID = new Map(
  HWY_SELF_REGISTRATION_REFERRER_RELATION_LEGACY_FALLBACK.map((row) => [row.legacyId, row.cultureLabelKey]),
);

export const resolveReferrerRelationCultureLabelKey = (legacyId: string): string | undefined => (
  REFERRER_RELATION_CULTURE_KEY_BY_LEGACY_ID.get(String(legacyId).trim())
);

/** Public self-reg UI — always prefer Hawiety culture keys over legacy English / wrong Base Info category. */
export const resolveReferrerRelationSegmentLabel = (
  legacyId: string,
  translate: (key: string) => string,
  apiLabel?: string | null,
): string => {
  const cultureKey = resolveReferrerRelationCultureLabelKey(legacyId);
  if (cultureKey) {
    const translated = translate(cultureKey).trim();
    if (translated && translated !== cultureKey) {
      return translated;
    }
  }

  const fallback = apiLabel?.trim();
  if (fallback && !fallback.startsWith('hwy.')) {
    return fallback;
  }

  return cultureKey ? translate(cultureKey) : (fallback ?? '');
};
