const trim = (value: unknown, max = 1000): string | null => {
  if (value == null) {
    return null;
  }
  const text = String(value).trim();
  if (!text) {
    return null;
  }
  return text.length > max ? text.slice(0, max) : text;
};

/** Legacy row: assigned `UserName` only — never promote `TrackingCode` into username. */
export const resolveLegacyMembershipUsernameFromLegacyRow = (input: {
  memberId: number;
  userName?: unknown;
  trackingCode?: unknown;
}): string | null => trim(input.userName);
