import { resolveHwyMemberDirectoryFamilyCode } from '../../shared/lib/hwyMemberDirectoryFamilyCode';
import {
  resolveHwyElectoralProvinceTitle,
  splitHwyElectoralDivisionPath,
} from '../../shared/lib/hwyMemberDirectoryPathDisplay';
import { resolveHwyHouseholdRegisteredVisual } from './hwyHouseholdRegisteredDisplay';
import type { DesignerDocument } from '../component-designer/types';
import type { DesignerDataGridColumn } from '../component-designer/designerDataGridColumns';
import type { DesignerGridRowActionBehavior } from '../component-designer/designerGridActionColumns';
import {
  APP_TABLE_GRID_PALETTE_ITEM_ID,
  parseDesignerAppTableGridColumns,
} from '../component-designer/designerDataGridColumns';
import { DESIGNER_PALETTE_ITEM_ID_PROP } from '../component-designer/propRegistry';

export const HWY_FAMILY_HOUSEHOLD_CELL_CLICK_KIND = 'hwy-family-household' as const;

export type HwyFamilyHouseholdCellClickKind = typeof HWY_FAMILY_HOUSEHOLD_CELL_CLICK_KIND;

export const HWY_FAMILY_HOUSEHOLD_CELL_CLICK_BEHAVIOR: DesignerGridRowActionBehavior = {
  kind: HWY_FAMILY_HOUSEHOLD_CELL_CLICK_KIND,
};

export type HwyFamilyHouseholdQuery = {
  regionId: string;
  familyCode: string;
  provinceTitle?: string;
};

const readTrimmedField = (row: Record<string, unknown>, ...keys: string[]): string => {
  for (const key of keys) {
    const raw = row[key];
    if (raw === null || raw === undefined) {
      continue;
    }
    const text = String(raw).trim();
    if (text.length > 0) {
      return text;
    }
  }
  return '';
};

type HwyFamilyHouseholdResolveColumn = Pick<DesignerDataGridColumn, 'cellFields'>;

const MEMBER_REGION_KEYS = [
  'nakhebinRegionId',
  'nakhebin_region_id',
  'nakhebinLinkRegionId',
  'nakhebin_link_region_id',
  'regionId',
  'region_id',
] as const;

const readFamilyCodeFromRow = (
  row: Record<string, unknown>,
  _columnKey: string,
  _column?: HwyFamilyHouseholdResolveColumn,
): string => resolveHwyMemberDirectoryFamilyCode(row);

const readRegionIdFromRow = (row: Record<string, unknown>, columnKey: string): string => (
  columnKey === 'familyCode'
    ? readTrimmedField(row, 'regionId', 'region_id', ...MEMBER_REGION_KEYS)
    : readTrimmedField(row, ...MEMBER_REGION_KEYS)
);

const readProvinceTitleFromRow = (row: Record<string, unknown>): string => {
  const direct = readTrimmedField(row, 'provinceTitle', 'province_title');
  if (direct) {
    return direct;
  }
  return resolveHwyElectoralProvinceTitle(
    row.electoralDivisionPath ?? row.electoral_division_path,
  );
};

const withProvinceTitle = (
  query: HwyFamilyHouseholdQuery,
  row: Record<string, unknown>,
): HwyFamilyHouseholdQuery => {
  const provinceTitle = readProvinceTitleFromRow(row);
  if (!provinceTitle) {
    return query;
  }
  return { ...query, provinceTitle };
};

const parseNakhebinGetOnePayload = (payload: unknown): Record<string, unknown> | null => {
  if (!payload || typeof payload !== 'object') {
    return null;
  }
  const record = payload as Record<string, unknown>;
  const data = record.data;
  if (data && typeof data === 'object' && !Array.isArray(data)) {
    return data as Record<string, unknown>;
  }
  return record;
};

const fetchNakhebinRowById = async (nakhebinId: string): Promise<Record<string, unknown> | null> => {
  const response = await fetch(`/api/hwy/nakhebin/${encodeURIComponent(nakhebinId)}`, {
    credentials: 'include',
  });
  if (!response.ok) {
    return null;
  }
  const payload = await response.json().catch(() => null);
  return parseNakhebinGetOnePayload(payload);
};

/** Resolve electoral region + family code from a member-directory or nakhebin grid row. */
export const resolveHwyFamilyHouseholdQueryFromRow = (
  row: Record<string, unknown>,
  columnKey: string,
  column?: HwyFamilyHouseholdResolveColumn,
): HwyFamilyHouseholdQuery | null => {
  const familyCode = readFamilyCodeFromRow(row, columnKey, column);
  const regionId = readRegionIdFromRow(row, columnKey);

  if (!regionId || !familyCode) {
    return null;
  }

  return withProvinceTitle({ regionId, familyCode }, row);
};

/** When list rows omit nakhebin region, load it from the nakhebin record. */
export const resolveHwyFamilyHouseholdQueryFromRowAsync = async (
  row: Record<string, unknown>,
  columnKey: string,
  column?: HwyFamilyHouseholdResolveColumn,
): Promise<HwyFamilyHouseholdQuery | null> => {
  const direct = resolveHwyFamilyHouseholdQueryFromRow(row, columnKey, column);
  if (direct) {
    return direct;
  }

  const familyCode = readFamilyCodeFromRow(row, columnKey, column);
  const nakhebinId = readTrimmedField(row, 'nakhebinId', 'nakhebin_id');
  if (!nakhebinId) {
    return null;
  }

  const nakhebinRow = await fetchNakhebinRowById(nakhebinId);
  if (!nakhebinRow) {
    return null;
  }

  const regionId = readRegionIdFromRow(nakhebinRow, 'familyCode');
  const resolvedFamilyCode = familyCode
    || readTrimmedField(nakhebinRow, 'familyCode', 'family_code');

  if (!regionId || !resolvedFamilyCode) {
    return null;
  }

  const mergedRow = { ...row, ...nakhebinRow };
  return withProvinceTitle({ regionId, familyCode: resolvedFamilyCode }, mergedRow);
};

export const documentUsesHwyFamilyHouseholdCellClick = (document: DesignerDocument): boolean => {
  for (const node of Object.values(document.nodes)) {
    if (node.props[DESIGNER_PALETTE_ITEM_ID_PROP] !== APP_TABLE_GRID_PALETTE_ITEM_ID) {
      continue;
    }
    const columns = parseDesignerAppTableGridColumns(node.props.columns);
    if (columns.some((column) => column.cellClickBehavior?.kind === HWY_FAMILY_HOUSEHOLD_CELL_CLICK_KIND)) {
      return true;
    }
  }
  return false;
};

export const gridColumnHasHwyFamilyHouseholdCellClick = (
  column: DesignerDataGridColumn,
): boolean => column.cellClickBehavior?.kind === HWY_FAMILY_HOUSEHOLD_CELL_CLICK_KIND;

const rowHasMemberDirectoryElectoralDivision = (row: Record<string, unknown>): boolean => {
  const raw = row.electoralDivisionPath ?? row.electoral_division_path;
  const { line1, line2 } = splitHwyElectoralDivisionPath(raw);
  return Boolean(line1.trim() || line2.trim());
};

const rowHasMemberDirectoryRegisteredStatus = (row: Record<string, unknown>): boolean => (
  resolveHwyHouseholdRegisteredVisual(
    readTrimmedField(
      row,
      'nakhebinJoinTasjilStateCodeTitle',
      'nakhebin_join_tasjil_state_code_title',
    ),
    readTrimmedField(row, 'nakhebinJoinTasjilStateCode', 'nakhebin_join_tasjil_state_code'),
  ) === 'yes'
);

/** `hwy-members-all` voter-record column — show family link only when مسجل + electoral division are both present. */
export const hwyMemberDirectoryRowShowsFamilyHouseholdLink = (
  row: Record<string, unknown>,
): boolean => rowHasMemberDirectoryRegisteredStatus(row)
  && rowHasMemberDirectoryElectoralDivision(row);

export const rowShowsHwyFamilyHouseholdCellClick = (
  row: Record<string, unknown>,
  column: Pick<DesignerDataGridColumn, 'key' | 'cellClickBehavior'>,
): boolean => {
  if (!gridColumnHasHwyFamilyHouseholdCellClick(column)) {
    return false;
  }
  if (column.key === 'nakhebinId') {
    return hwyMemberDirectoryRowShowsFamilyHouseholdLink(row);
  }
  return true;
};
