const formatInstallError = (error: unknown): string => {
  const parts: string[] = [];
  const push = (value: unknown): void => {
    if (value instanceof Error && value.message.trim()) {
      parts.push(value.message.trim());
    } else if (value && typeof value === 'object' && 'message' in value) {
      const message = String((value as { message: unknown }).message).trim();
      if (message) {
        parts.push(message);
      }
    }
  };

  push(error);
  if (error && typeof error === 'object' && 'original' in error) {
    const original = (error as { original?: unknown }).original;
    push(original);
    if (original && typeof original === 'object' && 'errors' in original) {
      const nested = (original as { errors?: unknown[] }).errors;
      if (Array.isArray(nested)) {
        for (const item of nested) {
          push(item);
        }
      }
    }
  }

  return parts.length > 0 ? [...new Set(parts)].join(' | ') : String(error);
};

/** Imported MembersV2 tables on the AppEndO edge DB — not live legacy SQL. */
const HWY_LEGACY_IMPORT_PARITY_FILES = new Set<string>([
  'hwy_legacy_pipeline_views.sqlserver.sql',
  'hwy_candidate_pipeline_indexes.sqlserver.sql',
  'hwy_candidate_pipeline.sqlserver.sql',
  'hwy_card_flow.sqlserver.sql',
  'hwy_meetings.sqlserver.sql',
]);

const applySqlFile = async (fileName: string): Promise<void> => {
  const sequelize = getControlPlaneSequelize();
  const ddl = readFileSync(path.join(installDir, fileName), 'utf8');
  const batches = ddl
    .split(/^\s*GO\s*$/gim)
    .map((chunk) => chunk.trim())
    .filter(Boolean);
  for (let index = 0; index < batches.length; index += 1) {
    try {
      await sequelize.query(batches[index], { type: QueryTypes.RAW });
    } catch (error: unknown) {
      throw new Error(
        `Hawiety DB install failed in ${fileName} (batch ${index + 1}/${batches.length}): ${formatInstallError(error)}`,
        { cause: error },
      );
    }
  }
};

/** Idempotent install of Hawiety write/read procedures and helper functions. */
export const ensureHwyDbObjects = async (): Promise<void> => {
  if (!isHawietyRuntimeEnabled()) {
    return;
  }
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }
  if (!ensurePromise) {
    ensurePromise = (async () => {
      for (const file of SQL_INSTALL_ORDER) {
        if (HWY_LEGACY_IMPORT_PARITY_FILES.has(file)) {
          if (!(await hwyLegacyImportParityTablesReady())) {
            console.warn(
              `[HWY DB objects] Skipping ${file} — imported HWY_* schema incomplete on control plane (run ETL/import first).`,
            );
            continue;
          }
          try {
            await applySqlFile(file);
          } catch (error: unknown) {
            console.warn(
              `[HWY DB objects] Parity install failed in ${file} (edge schema not fully imported): ${formatInstallError(error)}`,
            );
          }
          continue;
        }
        await applySqlFile(file);
      }
    })().catch((error: unknown) => {
      ensurePromise = null;
      throw error;
    });
  }
  await ensurePromise;
};
