import { QueryTypes } from 'sequelize';

import { buildHwyInstituteLogoApiPath } from '../../../domain/hwy/hwyInstituteLogoPath';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { isHwyInstituteLogoClearRequested } from '../../../domain/hwy/hwyInstituteLogoPayload';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';

const resolveInstitutesTable = (dialect: string): string =>
  dialect === 'mssql' ? 'dbo.hwy_institutes' : 'hwy_institutes';

export type HwyInstituteLogoRecord = {
  content: Buffer;
  contentType: string;
};

export async function loadHwyInstituteLogo(
  instituteId: number,
): Promise<HwyInstituteLogoRecord | null> {
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const table = resolveInstitutesTable(sequelize.getDialect());

  const rows = await sequelize.query<{ logo_content: Buffer | null; logo_content_type: string | null }>(
    `SELECT logo_content, logo_content_type FROM ${table} WHERE id = :instituteId`,
    {
      type: QueryTypes.SELECT,
      replacements: { instituteId },
    },
  );
  const row = rows[0];
  if (!row?.logo_content || !(row.logo_content instanceof Buffer) || row.logo_content.length === 0) {
    return null;
  }
  const contentType = row.logo_content_type?.trim() || 'image/png';
  return { content: row.logo_content, contentType };
}

export async function loadHwyInstituteLogoFlags(
  instituteIds: readonly number[],
): Promise<Set<number>> {
  const ids = [...new Set(instituteIds.filter((id) => Number.isFinite(id) && id > 0))];
  if (ids.length === 0) {
    return new Set();
  }
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const table = resolveInstitutesTable(dialect);
  const lengthPredicate = dialect === 'mssql'
    ? 'DATALENGTH(logo_content) > 0'
    : 'OCTET_LENGTH(logo_content) > 0';
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM ${table} WHERE id IN (:ids) AND logo_content IS NOT NULL AND ${lengthPredicate}`,
    {
      type: QueryTypes.SELECT,
      replacements: { ids },
    },
  );
  return new Set(rows.map((row) => row.id));
}

export async function saveHwyInstituteLogo(
  instituteId: number,
  content: Buffer,
  contentType: string,
): Promise<void> {
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const table = resolveInstitutesTable(dialect);
  const mime = contentType.trim() || 'image/png';
  await sequelize.query(
    `UPDATE ${table}
     SET logo_content = :content,
         logo_content_type = :contentType,
         logo_url = NULL,
         updated_at = ${dialect === 'mssql' ? 'SYSUTCDATETIME()' : 'NOW()'}
     WHERE id = :instituteId`,
    {
      type: QueryTypes.UPDATE,
      replacements: { instituteId, content, contentType: mime },
    },
  );
}

export async function clearHwyInstituteLogo(instituteId: number): Promise<void> {
  await ensureHwyDbObjects();
  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const table = resolveInstitutesTable(dialect);
  await sequelize.query(
    `UPDATE ${table}
     SET logo_content = NULL,
         logo_content_type = NULL,
         logo_url = NULL,
         updated_at = ${dialect === 'mssql' ? 'SYSUTCDATETIME()' : 'NOW()'}
     WHERE id = :instituteId`,
    {
      type: QueryTypes.UPDATE,
      replacements: { instituteId },
    },
  );
}

export function resolveHwyInstituteLogoUrlForClient(
  instituteId: number,
  hasLogo: boolean,
): string | null {
  return hasLogo ? buildHwyInstituteLogoApiPath(instituteId) : null;
}

export async function applyHwyInstituteLogoPayloadFields(
  instituteId: number,
  payload: Record<string, unknown>,
): Promise<void> {
  const clearRequested = isHwyInstituteLogoClearRequested(payload);
  delete payload.logoContentClear;

  const hasBase64Key = 'logoContentBase64' in payload;
  const raw = hasBase64Key ? payload.logoContentBase64 : undefined;
  if (hasBase64Key) {
    delete payload.logoContentBase64;
  }
  const rawType = payload.logoContentType;
  delete payload.logoContentType;

  if (clearRequested) {
    await clearHwyInstituteLogo(instituteId);
    return;
  }

  if (!hasBase64Key) {
    return;
  }

  // Empty hidden input on edit means "unchanged" (preview may come from GET /logo, not base64).
  if (raw == null || raw === '') {
    return;
  }
  const trimmed = String(raw).trim();
  if (!trimmed) {
    return;
  }
  const content = Buffer.from(trimmed, 'base64');
  if (content.length === 0) {
    await clearHwyInstituteLogo(instituteId);
    return;
  }
  const contentType = typeof rawType === 'string' && rawType.trim()
    ? rawType.trim()
    : 'image/png';
  await saveHwyInstituteLogo(instituteId, content, contentType);
}
