export async function ensureMembersUserIdUniqueAllowsMultipleNulls(local: sql.ConnectionPool): Promise<void> {
  await local.request().query(`
    IF EXISTS (SELECT 1 FROM sys.key_constraints WHERE name = N'UQ_hwy_members_user_id' AND parent_object_id = OBJECT_ID(N'dbo.hwy_members'))
      ALTER TABLE dbo.hwy_members DROP CONSTRAINT UQ_hwy_members_user_id;
    IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UQ_hwy_members_user_id' AND object_id = OBJECT_ID(N'dbo.hwy_members'))
      CREATE UNIQUE INDEX UQ_hwy_members_user_id ON dbo.hwy_members (user_id) WHERE user_id IS NOT NULL;
  `);
}

export async function clearSampleHwyTables(local: sql.ConnectionPool): Promise<void> {
  const userRows = (await local.request().query(`
    SELECT DISTINCT user_id AS user_id FROM dbo.hwy_members WHERE user_id IS NOT NULL
  `)).recordset as Array<{ user_id: number }>;
  const linkedUserIds = userRows.map((r) => Number(r.user_id)).filter((id) => id > 0);

  await local.request().query(`
    IF OBJECT_ID(N'dbo.hwy_activity_attendances', N'U') IS NOT NULL DELETE FROM dbo.hwy_activity_attendances;
    IF OBJECT_ID(N'dbo.hwy_course_attendances', N'U') IS NOT NULL DELETE FROM dbo.hwy_course_attendances;
    IF OBJECT_ID(N'dbo.hwy_activity_approval_steps', N'U') IS NOT NULL DELETE FROM dbo.hwy_activity_approval_steps;
    IF OBJECT_ID(N'dbo.hwy_course_approval_steps', N'U') IS NOT NULL DELETE FROM dbo.hwy_course_approval_steps;
    IF OBJECT_ID(N'dbo.hwy_activity_files', N'U') IS NOT NULL DELETE FROM dbo.hwy_activity_files;
    IF OBJECT_ID(N'dbo.hwy_activities', N'U') IS NOT NULL DELETE FROM dbo.hwy_activities;
    IF OBJECT_ID(N'dbo.hwy_courses', N'U') IS NOT NULL DELETE FROM dbo.hwy_courses;
    IF OBJECT_ID(N'dbo.hwy_geo_responsibility_requests', N'U') IS NOT NULL DELETE FROM dbo.hwy_geo_responsibility_requests;
    DELETE FROM dbo.hwy_username_repo;
    DELETE FROM dbo.hwy_member_security_profile;
    DELETE FROM dbo.hwy_member_notes;
    DELETE FROM dbo.hwy_member_files;
    DELETE FROM dbo.hwy_member_institutes;
    DELETE FROM dbo.hwy_member_targhin_requests;
    DELETE FROM dbo.hwy_members;
    DELETE FROM dbo.hwy_nakhebin;
  `);

  for (const batch of chunkIds(linkedUserIds, 200)) {
    if (!batch.length) continue;
    const req = local.request();
    const placeholders: string[] = [];
    batch.forEach((id, i) => {
      const key = `uid${i}`;
      req.input(key, sql.BigInt, id);
      placeholders.push(`@${key}`);
    });
    const inList = placeholders.join(', ');
    await req.query(`
      DELETE FROM dbo.base_user_profiles WHERE user_id IN (${inList});
      DELETE FROM dbo.base_users
      WHERE id IN (${inList})
        AND is_builtin = 0
        AND NOT EXISTS (SELECT 1 FROM dbo.hwy_members m WHERE m.user_id = base_users.id);
    `);
  }

  console.log('cleared hwy import tables (members + nakhebin + satellites); removed', linkedUserIds.length, 'linked platform users');
}

async function fetchMembersForStatus(
  legacy: sql.ConnectionPool,
  statusId: number,
  take: number,
): Promise<LegacyMemberRow[]> {
  const result = await legacy.request()
    .input('status', sql.Int, statusId)
    .input('take', sql.Int, take)
    .query(`
      SELECT TOP (@take)
        ${MEMBER_SELECT}
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE MembershipStatus = @status
        AND ISNULL(DeviceOsTypeId, 0) != 213991
      ORDER BY
        CASE WHEN EXISTS (
          SELECT 1 FROM dbo.HWY_Members_Organizations o WITH (NOLOCK)
          WHERE o.MemberId = HWY_Members.Id
            AND o.OrganizationId IN (${LEGACY_HWY_ORGANIZATION_IDS.join(', ')})
        ) THEN 0 ELSE 1 END,
        CASE WHEN EXISTS (
          SELECT 1 FROM dbo.HWY_Members_SecurityProfile sp WITH (NOLOCK)
          WHERE sp.MemberId = HWY_Members.Id
        ) THEN 0 ELSE 1 END,
        CASE WHEN EXISTS (
          SELECT 1 FROM dbo.HWY_Members_Notes n WITH (NOLOCK)
          WHERE n.MemberId = HWY_Members.Id
        ) THEN 0 ELSE 1 END,
        Id DESC
    `);
  return result.recordset as LegacyMemberRow[];
}

async function fetchMembersPage(
  legacy: sql.ConnectionPool,
  lastId: number,
  take: number,
  rangeMin = memberIdMin,
  rangeMax = memberIdMax,
): Promise<LegacyMemberRow[]> {
  const result = await legacy.request()
    .input('lastId', sql.Int, lastId)
    .input('take', sql.Int, take)
    .input('idMin', sql.Int, rangeMin)
    .input('idMax', sql.Int, rangeMax)
    .query(`
      SELECT TOP (@take)
        ${MEMBER_SELECT}
      FROM dbo.HWY_Members WITH (NOLOCK)
      WHERE Id > @lastId
        AND ISNULL(DeviceOsTypeId, 0) != 213991
        AND (@idMin = 0 OR Id >= @idMin)
        AND (@idMax = 0 OR Id <= @idMax)
      ORDER BY Id
    `);
  return result.recordset as LegacyMemberRow[];
}

