/** Legacy HWY_Nashatat draft default (تسجيل النشاطات). */
export const HWY_ACTIVITY_STATUS_REGISTER = '211311';

/** Legacy initial documentation queue (النشاطات قيد التوثيق الاولي). */
export const HWY_ACTIVITY_STATUS_WAITED_1 = '211312';

/** Legacy final documentation queue (النشاطات قيد التوثيق النهائي). */
export const HWY_ACTIVITY_STATUS_FINAL = '211313';

/** Legacy central activity type root (انشطة مركزية). */
export const HWY_ACTIVITY_CENTRAL_TYPE_CODE = '213915';

/** Legacy course documentation inbox (الدورات قيد التوثيق). */
export const HWY_COURSE_REVIEW_STATUS_CODES = ['215115', '215116', '215117'] as const;

/** Legacy course draft (before send to review). */
export const HWY_COURSE_STATUS_DRAFT = '215114';

/** Legacy course documented / approved. */
export const HWY_COURSE_STATUS_APPROVED = '215116';

/** Legacy activity fully documented. */
export const HWY_ACTIVITY_STATUS_COMPLETED = '211314';

/** Legacy activity rejected (marfoozeh). */
export const HWY_ACTIVITY_STATUS_MARFOOZEH = '211315';

export type HwyActivityWorkflowAction =
  | 'send-to-waited-1'
  | 'send-to-waited-2'
  | 'send-to-final'
  | 'send-to-draft'
  | 'send-to-marfoozeh'
  | 'send-to-un-marfoozeh';

export type HwyCourseWorkflowAction =
  | 'send-to-review'
  | 'mark-as-ok'
  | 'send-to-draft'
  | 'send-to-marfoozeh'
  | 'send-to-un-marfoozeh';

const ACTIVITY_WORKFLOW_TARGETS: Record<HwyActivityWorkflowAction, string> = {
  'send-to-waited-1': HWY_ACTIVITY_STATUS_WAITED_1,
  'send-to-waited-2': HWY_ACTIVITY_STATUS_FINAL,
  'send-to-final': HWY_ACTIVITY_STATUS_COMPLETED,
  'send-to-draft': HWY_ACTIVITY_STATUS_REGISTER,
  'send-to-marfoozeh': HWY_ACTIVITY_STATUS_MARFOOZEH,
  'send-to-un-marfoozeh': HWY_ACTIVITY_STATUS_FINAL,
};

const COURSE_WORKFLOW_TARGETS: Record<HwyCourseWorkflowAction, string> = {
  'send-to-review': '215115',
  'mark-as-ok': HWY_COURSE_STATUS_APPROVED,
  'send-to-draft': HWY_COURSE_STATUS_DRAFT,
  'send-to-marfoozeh': '215117',
  'send-to-un-marfoozeh': '215115',
};

export function resolveHwyActivityWorkflowTargetStatus(action: HwyActivityWorkflowAction): string {
  return ACTIVITY_WORKFLOW_TARGETS[action];
}

export function resolveHwyCourseWorkflowTargetStatus(action: HwyCourseWorkflowAction): string {
  return COURSE_WORKFLOW_TARGETS[action];
}

export type HwyActivitiesAdminQueue = 'register' | 'waited-1' | 'final' | 'central';

export type HwyCoursesAdminQueue = 'list' | 'review';

export function resolveHwyActivitiesAdminStatusFilter(
  queue: HwyActivitiesAdminQueue,
): { statusCode?: string; excludeCentralType?: boolean; centralTypeOnly?: boolean } {
  if (queue === 'register') {
    return { statusCode: HWY_ACTIVITY_STATUS_REGISTER, excludeCentralType: true };
  }
  if (queue === 'waited-1') {
    return { statusCode: HWY_ACTIVITY_STATUS_WAITED_1 };
  }
  if (queue === 'final') {
    return { statusCode: HWY_ACTIVITY_STATUS_FINAL };
  }
  return { centralTypeOnly: true };
}

export function resolveHwyCoursesAdminStatusCodes(queue: HwyCoursesAdminQueue): readonly string[] | null {
  if (queue === 'review') {
    return HWY_COURSE_REVIEW_STATUS_CODES;
  }
  return null;
}

/** Legacy HWY_Dorat_List — all sessions (no status filter); review queue uses {@link HWY_COURSE_REVIEW_STATUS_CODES}. */
export function resolveHwyCoursesAdminListDraftStatus(_queue: HwyCoursesAdminQueue): string | null {
  return null;
}
