import { QueryTypes } from 'sequelize';

import type { HwyMemberDossierInstituteRow } from '../../../domain/hwy/hwyMemberDossierSatellites';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { listHwyMemberInstituteCharacterSelectOptions } from './hwyMemberInstituteCharacterSelectOptions.service';
import { attachBaseInfoTitles } from './hwyMemberDossierSatellites.service';
import { coerceSqlServerBitField } from './coerceSqlServerBitField';

const normalizeInstituteCode = (code: unknown): string => String(code ?? '').trim().toLowerCase();

type MemberInstituteBlockContext = Pick<
  HwyMemberDossierInstituteRow,
  | 'jobTypeCode'
  | 'jobTypeCodeTitle'
  | 'jobPlace'
  | 'mehaniUnionCode'
  | 'mehaniUnionCodeTitle'
  | 'mehaniUnionDegreeCode'
  | 'mehaniUnionDegreeCodeTitle'
  | 'mehaniMembershipExpiresOn'
  | 'educationLevelCode'
  | 'educationLevelCodeTitle'
  | 'educationLevelInCode'
  | 'educationLevelInCodeTitle'
  | 'educationEntryYear'
  | 'educationBranch'
  | 'educationUniversityCode'
  | 'educationUniversityCodeTitle'
  | 'educationUniversityFacultyCode'
  | 'educationUniversityFacultyCodeTitle'
>;

async function loadMemberInstituteBlockContext(
  memberId: number,
  queryLang: string,
): Promise<MemberInstituteBlockContext> {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT TOP (1)
      m.job_type_code AS jobTypeCode,
      m.job_place AS jobPlace,
      m.mehani_union_code AS mehaniUnionCode,
      m.mehani_union_degree_code AS mehaniUnionDegreeCode,
      m.mehani_membership_expires_on AS mehaniMembershipExpiresOn,
      m.education_level_code AS educationLevelCode,
      m.education_level_in_code AS educationLevelInCode,
      m.education_entry_year AS educationEntryYear,
      m.education_branch AS educationBranch,
      m.education_university_code AS educationUniversityCode,
      m.education_university_faculty_code AS educationUniversityFacultyCode
    FROM dbo.hwy_members m
    WHERE m.id = :memberId
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  const record: Record<string, unknown> = { ...(rows[0] ?? {}) };
  await attachBaseInfoTitles(
    [record],
    [
      { codeField: 'jobTypeCode', titleField: 'jobTypeCodeTitle' },
      { codeField: 'mehaniUnionCode', titleField: 'mehaniUnionCodeTitle' },
      { codeField: 'mehaniUnionDegreeCode', titleField: 'mehaniUnionDegreeCodeTitle' },
      { codeField: 'educationLevelCode', titleField: 'educationLevelCodeTitle' },
      { codeField: 'educationLevelInCode', titleField: 'educationLevelInCodeTitle' },
      { codeField: 'educationUniversityCode', titleField: 'educationUniversityCodeTitle' },
      { codeField: 'educationUniversityFacultyCode', titleField: 'educationUniversityFacultyCodeTitle' },
    ],
    queryLang,
  );
  return record as MemberInstituteBlockContext;
}

async function resolveCharacterTitlesByInstitute(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const codes = [...new Set(
    rows
      .map((row) => normalizeInstituteCode(row.instituteCode))
      .filter((code) => code.length > 0),
  )];
  const labelByInstituteAndId = new Map<string, Map<string, string>>();
  await Promise.all(codes.map(async (instituteCode) => {
    const options = await listHwyMemberInstituteCharacterSelectOptions(instituteCode, cultureId);
    if (options.length === 0) {
      return;
    }
    const byId = new Map(options.map((option) => [option.value, option.label]));
    labelByInstituteAndId.set(instituteCode, byId);
  }));

  for (const row of rows) {
    const instituteCode = normalizeInstituteCode(row.instituteCode);
    const characterCode = String(row.characterCode ?? '').trim();
    if (!instituteCode || !characterCode) {
      row.characterCodeTitle = null;
      continue;
    }
    row.characterCodeTitle = labelByInstituteAndId.get(instituteCode)?.get(characterCode) ?? null;
  }
}

function mergeMemberContext(
  row: HwyMemberDossierInstituteRow,
  context: MemberInstituteBlockContext,
): void {
  const code = normalizeInstituteCode(row.instituteCode);
  if (code === 'gov') {
    row.jobTypeCode = context.jobTypeCode;
    row.jobTypeCodeTitle = context.jobTypeCodeTitle;
    row.jobPlace = context.jobPlace;
  }
  if (code === 'mehani') {
    row.mehaniUnionCode = context.mehaniUnionCode;
    row.mehaniUnionCodeTitle = context.mehaniUnionCodeTitle;
    row.mehaniUnionDegreeCode = context.mehaniUnionDegreeCode;
    row.mehaniUnionDegreeCodeTitle = context.mehaniUnionDegreeCodeTitle;
    row.jobTypeCode = context.jobTypeCode;
    row.jobTypeCodeTitle = context.jobTypeCodeTitle;
    row.mehaniMembershipExpiresOn = context.mehaniMembershipExpiresOn;
    row.jobPlace = context.jobPlace;
  }
  if (code === 'hemam') {
    row.educationLevelCode = context.educationLevelCode;
    row.educationLevelCodeTitle = context.educationLevelCodeTitle;
    row.educationLevelInCode = context.educationLevelInCode;
    row.educationLevelInCodeTitle = context.educationLevelInCodeTitle;
    row.educationEntryYear = context.educationEntryYear;
    row.educationBranch = context.educationBranch;
    row.educationUniversityCode = context.educationUniversityCode;
    row.educationUniversityCodeTitle = context.educationUniversityCodeTitle;
    row.educationUniversityFacultyCode = context.educationUniversityFacultyCode;
    row.educationUniversityFacultyCodeTitle = context.educationUniversityFacultyCodeTitle;
  }
}

export async function enrichHwyMemberDossierInstituteSpecificRows(
  memberId: number,
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<HwyMemberDossierInstituteRow[]> {
  const visibleRows = rows.filter((row) =>
    coerceSqlServerBitField(row.showInstituteCharacterInDossier),
  );
  let memberContext: MemberInstituteBlockContext | null = null;
  if (visibleRows.length > 0) {
    await attachBaseInfoTitles(
      visibleRows,
      [{ codeField: 'instituteStateCode', titleField: 'instituteStateCodeTitle' }],
      queryLang,
    );
    await resolveCharacterTitlesByInstitute(visibleRows, queryLang);
    const needsMemberContext = visibleRows.some((row) => {
      const code = normalizeInstituteCode(row.instituteCode);
      return code === 'gov' || code === 'mehani' || code === 'hemam';
    });
    if (needsMemberContext) {
      memberContext = await loadMemberInstituteBlockContext(memberId, queryLang);
    }
  }

  return rows.map((row) => {
    const showInstituteCharacterInDossier = coerceSqlServerBitField(row.showInstituteCharacterInDossier);
    const instituteCode = String(row.instituteCode ?? '').trim() || undefined;
    const normalized: HwyMemberDossierInstituteRow = {
      ...(row as HwyMemberDossierInstituteRow),
      instituteCode,
      showInstituteCharacterInDossier,
    };

    if (!showInstituteCharacterInDossier) {
      stripInstituteSpecificDossierFields(normalized);
      return normalized;
    }

    if (memberContext) {
      mergeMemberContext(normalized, memberContext);
    }

    return normalized;
  });
}

export function stripInstituteSpecificDossierFields(row: HwyMemberDossierInstituteRow): void {
  delete row.characterCode;
  delete row.characterCodeTitle;
  delete row.instituteStateCode;
  delete row.instituteStateCodeTitle;
  delete row.instituteStateNote;
  delete row.instituteStateUpdatedOn;
  delete row.instituteStateUpdatedBy;
  delete row.instituteStateUpdatedByDisplay;
  delete row.currentOrgEmploymentId;
  delete row.currentOrgEmploymentNote;
  delete row.jobTypeCode;
  delete row.jobTypeCodeTitle;
  delete row.jobPlace;
  delete row.mehaniUnionCode;
  delete row.mehaniUnionCodeTitle;
  delete row.mehaniUnionDegreeCode;
  delete row.mehaniUnionDegreeCodeTitle;
  delete row.mehaniMembershipExpiresOn;
  delete row.educationLevelCode;
  delete row.educationLevelCodeTitle;
  delete row.educationLevelInCode;
  delete row.educationLevelInCodeTitle;
  delete row.educationEntryYear;
  delete row.educationBranch;
  delete row.educationUniversityCode;
  delete row.educationUniversityCodeTitle;
  delete row.educationUniversityFacultyCode;
  delete row.educationUniversityFacultyCodeTitle;
}
