/** Strip `base_info` pipe paths (e.g. الأساس | … | العراق) to the last segment for display. */
export const hwyGeoDisplayLeafTitle = (
  value: string | null | undefined,
): string | null => {
  const trimmed = String(value ?? '').trim();
  if (!trimmed) {
    return null;
  }
  if (!trimmed.includes('|')) {
    return trimmed;
  }
  const parts = trimmed.split('|').map((part) => part.trim()).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1]! : trimmed;
};
