import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';

const readStringField = (row: Record<string, unknown>, field: string): string => {
  const snake = field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`);
  const raw = row[field] ?? row[snake];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

/** Resolves Base Info title (and optional ui_color) for a code field on grid rows. */
export const attachBaseInfoCodeTitles = async (
  rows: Record<string, unknown>[],
  queryLang: string,
  codeField: string,
  titleField: string,
  colorField?: string,
): Promise<void> => {
  const codes = [...new Set(
    rows
      .map((row) => readStringField(row, codeField))
      .filter(Boolean),
  )];
  if (codes.length === 0) {
    return;
  }

  const cultureId = resolveBaseInfoCultureId(queryLang);
  const enriched = await listBaseInfoEnrichmentRowsByIds(codes, cultureId);
  const titleById = new Map<string, string>();
  const colorById = new Map<string, string>();
  for (const item of enriched) {
    const id = String(item.id ?? '').trim();
    const title = String(item.title ?? '').trim();
    const color = String(item.ui_color ?? '').trim();
    if (id && title) {
      titleById.set(id, title);
    }
    if (id && color) {
      colorById.set(id, color);
    }
  }

  for (const row of rows) {
    const code = readStringField(row, codeField);
    if (!code) {
      continue;
    }
    if (!readStringField(row, titleField)) {
      row[titleField] = titleById.get(code) ?? code;
    }
    if (colorField && !readStringField(row, colorField) && colorById.has(code)) {
      row[colorField] = colorById.get(code);
    }
  }
};

/** Member rows: `nakhebin_join_tasjil_state_code` from legacy `NakhebJoinTasjilStateId`. */
export const attachMemberTasjilStateTitles = async (
  rows: Record<string, unknown>[],
  lang: string,
): Promise<void> => {
  await attachBaseInfoCodeTitles(
    rows,
    lang,
    'nakhebinJoinTasjilStateCode',
    'nakhebinJoinTasjilStateCodeTitle',
    'nakhebinJoinTasjilStateCodeTitleUiColor',
  );
};

/** Nakhebin rows: `registered_case_code` from legacy `Rigestered_Case_Id`. */
export const attachNakhebinRegisteredCaseTitles = async (
  rows: Record<string, unknown>[],
  lang: string,
): Promise<void> => {
  await attachBaseInfoCodeTitles(
    rows,
    lang,
    'registeredCaseCode',
    'registeredCaseCodeTitle',
    'registeredCaseCodeTitleUiColor',
  );
};
