import { listEdgeApiDefinitions } from '../../services/data-api/edgeApiStore';
import { invalidateDataApiDefinitionCache } from '../../services/data-api/dataApiRuntimePolicy';

/** Edge model for `vw_hwy_members` (member directory list + getOne share one Data API definition). */
const HWY_MEMBER_DIRECTORY_EDGE_MODEL_ID = 'em_5f3a30c99bb3420e';

/** Clears server GET response cache after member writes that bypass Data API finalize hooks. */
export const invalidateHwyMemberDirectoryListCache = async (): Promise<void> => {
  const definitionIds = listEdgeApiDefinitions()
    .filter((definition) => definition.edgeModelId === HWY_MEMBER_DIRECTORY_EDGE_MODEL_ID)
    .map((definition) => definition.id);

  await Promise.all(definitionIds.map((id) => invalidateDataApiDefinitionCache(id)));
};
