export const LEGACY_HWY_ORGANIZATION_IDS = HWY_INSTITUTES_CATALOG.map((row) => row.legacyOrganizationId);

export const LEGACY_ORGANIZATION_ID_TO_HWY_INSTITUTE_ID: Record<number, number> = Object.fromEntries(
  HWY_INSTITUTES_CATALOG.map((row) => [row.legacyOrganizationId, row.id]),
);

export const resolveHwyInstituteIdFromLegacyOrganization = (legacyOrganizationId: number): number | null => (
  LEGACY_ORGANIZATION_ID_TO_HWY_INSTITUTE_ID[legacyOrganizationId] ?? null
);

export type HwyInstituteSeed = Omit<HwyInstituteCatalogEntry, 'legacyOrganizationId'>;

export const HWY_INSTITUTES_SEED_ROWS: HwyInstituteSeed[] = HWY_INSTITUTES_CATALOG.map(
  ({ legacyOrganizationId: _legacy, ...seed }) => seed,
);
