import { QueryTypes, type Sequelize } from 'sequelize';

/** `hwy_ref_members_gender_limits.item_id` for the staff member linked to a platform user. */
export async function loadHwyStaffGenderLimitLegacyIds(
  sequelize: Sequelize,
  userId: number,
): Promise<string[]> {
  if (!Number.isFinite(userId) || userId <= 0) {
    return [];
  }
  if (sequelize.getDialect() !== 'mssql') {
    return [];
  }

  try {
    const rows = await sequelize.query<{ item_id: number | string }>(
      `
        SELECT gl.item_id AS item_id
        FROM dbo.hwy_members m WITH (NOLOCK)
        INNER JOIN dbo.hwy_ref_members_gender_limits gl WITH (NOLOCK)
          ON gl.member_id = m.id
        WHERE m.user_id = :userId
      `,
      {
        replacements: { userId },
        type: QueryTypes.SELECT,
      },
    );
    return [...new Set(rows.map((row) => String(row.item_id ?? '').trim()).filter(Boolean))];
  } catch {
    return [];
  }
}
