import { QueryTypes } from 'sequelize';

import { isHwyLegacyPlatformAdminActorKey } from '../../../domain/hwy/hwyLegacyPlatformAdminActor';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';

let cachedPlatformAdminUserId: number | null = null;

/** Control-plane `base_users.id` for username `admin`. */
export async function resolveHwyPlatformAdminUserId(): Promise<number | null> {
  if (cachedPlatformAdminUserId != null && cachedPlatformAdminUserId > 0) {
    return cachedPlatformAdminUserId;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `
    SELECT TOP 1 id
    FROM dbo.base_users
    WHERE username IN (N'admin', N'ADMIN')
    ORDER BY id ASC
    `,
    { type: QueryTypes.SELECT },
  );
  const id = Number(rows[0]?.id);
  cachedPlatformAdminUserId = Number.isFinite(id) && id > 0 ? id : null;
  return cachedPlatformAdminUserId;
}

/** Maps legacy HWY staff user id strings to `base_users.id` when that PK exists locally. */
export async function resolveHwyLegacyStaffUserId(
  legacyUserIdRaw: string | number | null | undefined,
): Promise<number | null> {
  const trimmed = String(legacyUserIdRaw ?? '').trim();
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.base_users WHERE id = :id`,
    { replacements: { id }, type: QueryTypes.SELECT },
  );
  return rows.length ? id : null;
}

const resolveControlPlaneUserIdByHwyMemberUsername = async (
  membershipUsername: string,
): Promise<number | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ user_id: number | string | null }>(
    `SELECT TOP 1 user_id FROM dbo.hwy_members WHERE username = :username`,
    { replacements: { username: membershipUsername }, type: QueryTypes.SELECT },
  );
  const userId = rows[0]?.user_id != null ? Number(rows[0].user_id) : null;
  if (userId != null && Number.isFinite(userId) && userId > 0) {
    return resolveHwyLegacyStaffUserId(userId);
  }
  return null;
};

/** Legacy targhin `RequestBy` — staff user id, username, or member id (common). */
export async function resolveHwyLegacyTarghinRequestByUserId(
  legacyRequestByRaw: string | number | null | undefined,
): Promise<number | null> {
  const byActor = await resolveHwyLegacyActorUserId(legacyRequestByRaw);
  if (byActor) {
    return byActor;
  }
  const trimmed = String(legacyRequestByRaw ?? '').trim();
  if (!trimmed) {
    return null;
  }
  const byMembershipUsername = await resolveControlPlaneUserIdByHwyMemberUsername(trimmed);
  if (byMembershipUsername) {
    return byMembershipUsername;
  }
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  const memberId = Number(trimmed);
  if (!Number.isFinite(memberId) || memberId <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ user_id: number | string | null }>(
    `SELECT user_id FROM dbo.hwy_members WHERE id = :memberId`,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  const userId = rows[0]?.user_id != null ? Number(rows[0].user_id) : null;
  if (userId != null && Number.isFinite(userId) && userId > 0) {
    const exists = await resolveHwyLegacyStaffUserId(userId);
    return exists;
  }
  return null;
}

/** Legacy HWY actor id (base_users PK) or membership username string. */
export async function resolveHwyLegacyActorUserId(
  legacyActorRaw: string | number | null | undefined,
): Promise<number | null> {
  const trimmed = String(legacyActorRaw ?? '').trim();
  if (!trimmed) {
    return null;
  }
  if (isHwyLegacyPlatformAdminActorKey(trimmed)) {
    return resolveHwyPlatformAdminUserId();
  }
  if (/^\d+$/.test(trimmed)) {
    const byId = await resolveHwyLegacyStaffUserId(trimmed);
    if (byId) {
      return byId;
    }
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `SELECT TOP 1 id FROM dbo.base_users WHERE username = :username`,
    { replacements: { username: trimmed }, type: QueryTypes.SELECT },
  );
  return rows[0]?.id ?? null;
}
