import {
  HWY_ACTIVITY_CENTRAL_TYPE_CODE,
  HWY_ACTIVITY_STATUS_COMPLETED,
} from './hwyCoursesActivitiesCatalog';
import type {
  HwySubmissionMetadataFieldSpec,
  HwySubmissionMetadataSpecResponse,
} from './hwySubmissionMetadata';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

export type HwyActivitySelfAnnouncementPolicyInput = {
  activityTypeCode: string | null;
  statusCode: string | null;
  enableSelfAnnouncement: boolean | null;
  activityDate: string | null;
  nbWindowStartAt: string | null;
  nbWindowEndAt: string | null;
  requireSubmissionDeviceMetadata: boolean | null;
};

const recordDeviceFields: HwySubmissionMetadataFieldSpec[] = [
  { id: 'nbDeviceOs', mode: 'record' },
  { id: 'nbDeviceId', mode: 'record' },
  { id: 'nbDeviceDatetime', mode: 'record' },
];

const requireDeviceFields: HwySubmissionMetadataFieldSpec[] = [
  { id: 'nbDeviceOs', mode: 'require' },
  { id: 'nbDeviceId', mode: 'require' },
  { id: 'nbDeviceDatetime', mode: 'require' },
];

const baseSelfAnnouncementFields: HwySubmissionMetadataFieldSpec[] = [
  { id: 'nbLocationLat', mode: 'require' },
  { id: 'nbLocationLon', mode: 'require' },
  { id: 'selfie', mode: 'require' },
];

export const activityRequiresDeviceMetadataOnSelfie = (
  activity: Pick<HwyActivitySelfAnnouncementPolicyInput, 'activityTypeCode' | 'requireSubmissionDeviceMetadata'>,
): boolean => {
  if (activity.requireSubmissionDeviceMetadata != null) {
    return Boolean(activity.requireSubmissionDeviceMetadata);
  }
  return trim(activity.activityTypeCode) === HWY_ACTIVITY_CENTRAL_TYPE_CODE;
};

export const resolveHwyActivitySelfAnnouncementMetadataPolicy = (
  activity: HwyActivitySelfAnnouncementPolicyInput,
): HwySubmissionMetadataSpecResponse => {
  const deviceFields = activityRequiresDeviceMetadataOnSelfie(activity)
    ? requireDeviceFields
    : recordDeviceFields;
  return {
    fields: [...baseSelfAnnouncementFields, ...deviceFields],
  };
};

export const assertHwyActivitySelfAnnouncementAllowed = (
  activity: HwyActivitySelfAnnouncementPolicyInput,
  now = new Date(),
): void => {
  if (!activity.enableSelfAnnouncement) {
    throw new Error('Self-announcement is not enabled for this activity.');
  }
  if (trim(activity.statusCode) === HWY_ACTIVITY_STATUS_COMPLETED) {
    throw new Error('Self-announcement is closed for this activity.');
  }
  const startRaw = activity.nbWindowStartAt?.trim();
  const endRaw = activity.nbWindowEndAt?.trim();
  if (startRaw) {
    const start = new Date(startRaw);
    if (!Number.isNaN(start.getTime()) && now < start) {
      throw new Error('Self-announcement is not open yet.');
    }
  }
  if (endRaw) {
    const end = new Date(endRaw);
    if (!Number.isNaN(end.getTime()) && now > end) {
      throw new Error('Self-announcement window has ended.');
    }
  }
};
