import { SETTINGS_PATH } from '../../../src/server/config/settingsFile';
import { readControlPlaneDatabaseSettings } from '../../../src/server/db/controlPlaneDatabase';
import { prisma } from '../../../src/server/domain/users/prismaHelpers';

export const HWY_ETL_GEO_MAP_TABLE = 'hwy_etl_geo_map';

export async function ensureGeoMapTable(): Promise<void> {
  const { provider } = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  if (provider === 'sqlserver') {
    await prisma().$executeRawUnsafe(`
      IF OBJECT_ID(N'dbo.${HWY_ETL_GEO_MAP_TABLE}', N'U') IS NULL
      BEGIN
        CREATE TABLE dbo.${HWY_ETL_GEO_MAP_TABLE} (
          legacy_kind            NVARCHAR(32)  NOT NULL,
          legacy_id              BIGINT        NOT NULL,
          legacy_secondary_id    BIGINT        NOT NULL CONSTRAINT DF_hwy_etl_geo_map_sec DEFAULT (0),
          base_info_id           NVARCHAR(128) NOT NULL,
          legacy_hwy_state_id    BIGINT        NULL,
          import_batch           NVARCHAR(64)  NULL,
          CONSTRAINT PK_hwy_etl_geo_map PRIMARY KEY (legacy_kind, legacy_id, legacy_secondary_id)
        );
      END
    `);
    return;
  }

  await prisma().$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS ${HWY_ETL_GEO_MAP_TABLE} (
      legacy_kind            TEXT    NOT NULL,
      legacy_id              BIGINT  NOT NULL,
      legacy_secondary_id    BIGINT  NOT NULL DEFAULT 0,
      base_info_id           TEXT    NOT NULL,
      legacy_hwy_state_id    BIGINT  NULL,
      import_batch           TEXT    NULL,
      PRIMARY KEY (legacy_kind, legacy_id, legacy_secondary_id)
    )
  `);
}

export async function clearGeoMapTable(): Promise<void> {
  await prisma().$executeRawUnsafe(`DELETE FROM ${HWY_ETL_GEO_MAP_TABLE}`);
}
