import { QueryTypes } from 'sequelize';
import type { Sequelize } from 'sequelize';

import {
  HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS,
  HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS,
  mirrorMemberDirectoryListFaceAvatarUrlFields,
  readHwyMemberImageFixThumbRow,
  resolveHwyMemberImageFixListFaceAvatarUrl,
  type HwyMemberImageFixThumbRow,
  type HwyMemberImageFixThumbSlot,
} from '../../../domain/hwy/hwyMemberImageFixCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { loadImageFixTodoFileKindCodes } from './hwyMemberDirectoryListScope.service';
import { resolveHwyMemberFileKindBySlugOrId } from './hwyMemberFileKindResolve.service';

type FileRow = {
  member_id: number | string;
  file_kind_code: string;
  id: number | string;
  is_approved: boolean | number | null;
  has_blob: number;
};

const parseMemberId = (row: Record<string, unknown>): number | null => {
  const raw = row.id ?? row.memberId;
  const id = Number(raw);
  return Number.isFinite(id) && id > 0 ? id : null;
};

export type AttachImageFixRegistrationThumbsOptions = {
  /** Montadhemin-style lists: fill empty list face from registration personal photo. Off on ImageFix (thumbs column only). */
  mirrorRegistrationPersonalPhotoToListFace?: boolean;
};

export async function attachImageFixRegistrationThumbsToMemberDirectoryRows(
  rows: Record<string, unknown>[],
  options: AttachImageFixRegistrationThumbsOptions = {},
): Promise<void> {
  const mirrorRegistrationPersonalPhotoToListFace = options.mirrorRegistrationPersonalPhotoToListFace === true;
  if (!rows.length) {
    return;
  }
  const memberIds = [...new Set(rows.map(parseMemberId).filter((id): id is number => id != null))];
  if (!memberIds.length) {
    return;
  }

  const slugToCode = new Map<string, string>();
  for (const slug of HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS) {
    const resolved = await resolveHwyMemberFileKindBySlugOrId(slug);
    if (resolved?.id) {
      slugToCode.set(slug, resolved.id);
    }
  }
  const kindCodes = [...slugToCode.values()];
  if (!kindCodes.length) {
    return;
  }

  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const filesTable = dialect === 'mssql' ? 'dbo.hwy_member_files' : 'hwy_member_files';
  const blobExpr = dialect === 'mssql'
    ? `(CASE WHEN DATALENGTH(COALESCE(f.content, f.thumbnail_content)) > 0 OR ISNULL(f.size_bytes, 0) > 0 THEN 1 ELSE 0 END)`
    : `(CASE WHEN COALESCE(octet_length(f.content), 0) > 0 OR COALESCE(octet_length(f.thumbnail_content), 0) > 0 OR COALESCE(f.size_bytes, 0) > 0 THEN 1 ELSE 0 END)`;

  const filesByMember = new Map<number, FileRow[]>();
  const batchSize = 400;
  for (let i = 0; i < memberIds.length; i += batchSize) {
    const batch = memberIds.slice(i, i + batchSize);
    const replacements: Record<string, number> = {};
    const placeholders = batch.map((id, idx) => {
      replacements[`mid${idx}`] = id;
      return `:mid${idx}`;
    });
    const kindPlaceholders = kindCodes.map((code, idx) => {
      replacements[`kc${idx}`] = code;
      return `:kc${idx}`;
    });
    const fileRows = await sequelize.query<FileRow>(
      `
      SELECT
        f.member_id,
        f.file_kind_code,
        f.id,
        f.is_approved,
        ${blobExpr} AS has_blob
      FROM ${filesTable} f
      WHERE f.member_id IN (${placeholders.join(', ')})
        AND f.file_kind_code IN (${kindPlaceholders.join(', ')})
      `,
      { replacements, type: QueryTypes.SELECT },
    );
    for (const file of fileRows) {
      const mid = Number(file.member_id);
      if (!Number.isFinite(mid)) {
        continue;
      }
      const bucket = filesByMember.get(mid) ?? [];
      bucket.push(file);
      filesByMember.set(mid, bucket);
    }
  }

  const codeToSlug = new Map<string, string>();
  for (const [slug, code] of slugToCode) {
    codeToSlug.set(code, slug);
  }

  for (const row of rows) {
    const memberId = parseMemberId(row);
    if (memberId == null) {
      continue;
    }
    const memberFiles = filesByMember.get(memberId) ?? [];
    const bySlug = new Map<string, FileRow>();
    for (const file of memberFiles) {
      const slug = codeToSlug.get(String(file.file_kind_code));
      if (slug) {
        bySlug.set(slug, file);
      }
    }
    const slots: HwyMemberImageFixThumbSlot[] = HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS.map((kindSlug) => {
      const file = bySlug.get(kindSlug);
      if (!file) {
        return { kindSlug, hasBlob: false, isApproved: false };
      }
      const fileId = String(file.id);
      return {
        kindSlug,
        fileId,
        previewUrl: `/api/hwy/member-files/${encodeURIComponent(fileId)}/content`,
        isApproved: Number(file.is_approved ?? 0) === 1 || file.is_approved === true,
        hasBlob: Number(file.has_blob) === 1,
      };
    });
    const payload: HwyMemberImageFixThumbRow = { slots };
    row.registrationImageFixThumbs = payload;
    if (mirrorRegistrationPersonalPhotoToListFace) {
      const faceAvatar = resolveHwyMemberImageFixListFaceAvatarUrl(
        row.avatarUrl != null ? String(row.avatarUrl) : row.avatar_url != null ? String(row.avatar_url) : null,
        slots,
      );
      if (faceAvatar) {
        mirrorMemberDirectoryListFaceAvatarUrlFields(row, faceAvatar);
      }
    }
  }
}

const readExistingListFaceAvatarUrl = (row: Record<string, unknown>): string => (
  String(row.avatarUrl ?? row.avatar_url ?? '').trim()
);

/** Apply registration-file list-face URLs onto arbitrary member-face DTOs (phone/targhin queues). */
export async function enrichMemberDirectoryFaceAvatarsByMemberId(
  faces: Array<{ memberId: string | number; avatarUrl?: string | null }>,
): Promise<void> {
  if (!faces.length) {
    return;
  }
  const enrichRows = faces.map((face) => ({
    id: face.memberId,
    avatarUrl: face.avatarUrl ?? null,
  }));
  await enrichMemberRowAvatarsFromRegistrationPhotos(enrichRows);
  for (let i = 0; i < faces.length; i += 1) {
    const url = String(enrichRows[i]?.avatarUrl ?? '').trim();
    if (url) {
      faces[i].avatarUrl = url;
    }
  }
}

/** Segment lists (montadhemin, …): platform `avatarUrl` from SQL, else registration personal photo only — no ImageFix thumb payload. */
export async function enrichMemberRowAvatarsFromRegistrationPhotos(
  rows: Array<{ id: string | number; avatarUrl?: string | null }>,
): Promise<void> {
  if (!rows.length) {
    return;
  }
  const mutable = rows as Array<Record<string, unknown>>;
  const needsEnrich = mutable.filter((row) => !readExistingListFaceAvatarUrl(row));
  if (!needsEnrich.length) {
    return;
  }

  const slugToCode = new Map<string, string>();
  for (const slug of HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS) {
    const resolved = await resolveHwyMemberFileKindBySlugOrId(slug);
    if (resolved?.id?.trim()) {
      slugToCode.set(slug, resolved.id.trim());
    }
  }
  const kindCodes = [...slugToCode.values()];
  if (!kindCodes.length) {
    return;
  }

  const memberIds = [...new Set(needsEnrich.map(parseMemberId).filter((id): id is number => id != null))];
  if (!memberIds.length) {
    return;
  }

  const sequelize = getControlPlaneSequelize();
  const dialect = sequelize.getDialect();
  const filesTable = dialect === 'mssql' ? 'dbo.hwy_member_files' : 'hwy_member_files';
  const blobExpr = dialect === 'mssql'
    ? `(CASE WHEN DATALENGTH(COALESCE(f.content, f.thumbnail_content)) > 0 OR ISNULL(f.size_bytes, 0) > 0 THEN 1 ELSE 0 END)`
    : `(CASE WHEN COALESCE(octet_length(f.content), 0) > 0 OR COALESCE(octet_length(f.thumbnail_content), 0) > 0 OR COALESCE(f.size_bytes, 0) > 0 THEN 1 ELSE 0 END)`;

  const filePickByMember = new Map<number, { priority: number; fileId: string }>();
  const batchSize = 400;
  for (let i = 0; i < memberIds.length; i += batchSize) {
    const batch = memberIds.slice(i, i + batchSize);
    const replacements: Record<string, number | string> = {};
    const placeholders = batch.map((id, idx) => {
      replacements[`mid${idx}`] = id;
      return `:mid${idx}`;
    });
    const kindPlaceholders = kindCodes.map((code, idx) => {
      replacements[`kc${idx}`] = code;
      return `:kc${idx}`;
    });
    const fileRows = await sequelize.query<{
      member_id: number | string;
      id: number | string;
      file_kind_code: string;
      has_blob: number;
    }>(
      `
      SELECT f.member_id, f.id, f.file_kind_code, ${blobExpr} AS has_blob
      FROM ${filesTable} f
      WHERE f.member_id IN (${placeholders.join(', ')})
        AND f.file_kind_code IN (${kindPlaceholders.join(', ')})
      `,
      { replacements, type: QueryTypes.SELECT },
    );
    const codeToSlug = new Map<string, string>();
    for (const [slug, code] of slugToCode) {
      codeToSlug.set(code, slug);
    }
    for (const file of fileRows) {
      if (Number(file.has_blob) !== 1) {
        continue;
      }
      const mid = Number(file.member_id);
      if (!Number.isFinite(mid)) {
        continue;
      }
      const slug = codeToSlug.get(String(file.file_kind_code));
      if (!slug) {
        continue;
      }
      const priority = HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS.indexOf(
        slug as (typeof HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS)[number],
      );
      if (priority < 0) {
        continue;
      }
      const existing = filePickByMember.get(mid);
      if (existing && existing.priority <= priority) {
        continue;
      }
      filePickByMember.set(mid, { priority, fileId: String(file.id) });
    }
  }

  for (let i = 0; i < rows.length; i += 1) {
    const row = mutable[i]!;
    if (readExistingListFaceAvatarUrl(row)) {
      continue;
    }
    const memberId = parseMemberId(row);
    if (memberId == null) {
      continue;
    }
    const pick = filePickByMember.get(memberId);
    if (!pick) {
      continue;
    }
    const fileId = pick.fileId;
    const url = `/api/hwy/member-files/${encodeURIComponent(fileId)}/content`;
    rows[i].avatarUrl = url;
    mirrorMemberDirectoryListFaceAvatarUrlFields(row, url);
  }
}

/** Keep only list-face registration slots on rows (payload-safe for membership queues). */
export const slimRegistrationImageFixThumbsForListFaceOnly = (
  rows: Record<string, unknown>[],
): void => {
  const allowed = new Set<string>(HWY_MEMBER_LIST_FACE_REGISTRATION_KIND_SLUGS);
  for (const row of rows) {
    const thumbRow = readHwyMemberImageFixThumbRow(row);
    if (!thumbRow?.slots.length) {
      delete row.registrationImageFixThumbs;
      continue;
    }
    const slots = thumbRow.slots.filter(
      (slot) => allowed.has(slot.kindSlug) && slot.previewUrl && slot.hasBlob,
    );
    if (!slots.length) {
      delete row.registrationImageFixThumbs;
      continue;
    }
    row.registrationImageFixThumbs = { slots };
  }
};

/** Guard for tests — ensures queue kind codes stay aligned with thumb slugs subset. */
export async function loadImageFixTodoKindCodesForQueue(_sequelize: Sequelize): Promise<string[]> {
  return loadImageFixTodoFileKindCodes();
}
