const EMPTY_PLACEHOLDER = '—';

const normalizeComparable = (value: string): string => value.trim().toLowerCase();

/** Legacy security-clearance «yes» answers (not used for مسجل column; kept for empty-title code fallback). */
const AFFIRMATIVE_CODE_MARKERS = ['allowed', '220.008.001'];

export type HwyHouseholdRegisteredVisual = 'yes' | 'no' | 'empty';

const isUnregisteredTitle = (text: string): boolean => text.includes('غير مسجل');

const isRegisteredTitle = (text: string): boolean => {
  const normalized = normalizeComparable(text);
  if (!normalized || normalized === normalizeComparable(EMPTY_PLACEHOLDER)) {
    return false;
  }
  if (isUnregisteredTitle(text)) {
    return false;
  }
  if (normalized.includes('مسجل بايومتريا') || normalized.includes('مسجل بایومتريا')) {
    return true;
  }
  if (text.includes('مسجل')) {
    return true;
  }
  return false;
};

export const resolveHwyHouseholdRegisteredVisual = (
  title: string | null | undefined,
  code?: string | null,
): HwyHouseholdRegisteredVisual => {
  const text = String(title ?? '').trim();
  if (!text || text === EMPTY_PLACEHOLDER) {
    const codeText = String(code ?? '').trim().toLowerCase();
    if (codeText && AFFIRMATIVE_CODE_MARKERS.some((marker) => codeText.includes(marker))) {
      return 'yes';
    }
    return 'empty';
  }

  if (isRegisteredTitle(text)) {
    return 'yes';
  }

  return 'no';
};
