import { QueryTypes } from 'sequelize';

import { formatHwyGeoElectoralPathForDisplay } from '../../../shared/lib/hwyMemberDirectoryPathDisplay';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { resolveHwyLegacyGeoIdTitlePaths } from './hwyCandidatePipelineResponsibilityPatchDisplay.service';

const readStringField = (row: Record<string, unknown>, key: string): string =>
  String(row[key] ?? '').trim();

/** Resolve member electoral center through region via NakhebJoinEghteraId (legacy join to منطقة). */
export async function attachHwyCandidatePipelineElectoralCenterPaths(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  const memberIds = [...new Set(rows.map((row) => readStringField(row, 'id')).filter(Boolean))];
  const eghteraIdByMemberId = new Map<string, string>();

  for (const row of rows) {
    const memberId = readStringField(row, 'id');
    const inline = readStringField(row, 'nakhebJoinEghteraId')
      || readStringField(row, 'NakhebJoinEghteraId');
    if (memberId && inline) {
      eghteraIdByMemberId.set(memberId, inline);
    }
  }

  const missingMemberIds = memberIds.filter((memberId) => !eghteraIdByMemberId.has(memberId));
  if (missingMemberIds.length > 0) {
    try {
      const sequelize = getControlPlaneSequelize();
      const joinRows = await sequelize.query<{ member_id: string; eghtera_id: string | null }>(
        `SELECT CAST(m.id AS VARCHAR(32)) AS member_id,
                CAST(COALESCE(m.nakheb_join_eghtera_id, M.NakhebJoinEghteraId) AS VARCHAR(32)) AS eghtera_id
         FROM dbo.hwy_members m WITH (NOLOCK)
         LEFT JOIN dbo.HWY_Members M WITH (NOLOCK) ON M.Id = m.id
         WHERE m.id IN (:memberIds)`,
        { replacements: { memberIds: missingMemberIds }, type: QueryTypes.SELECT },
      );
      for (const row of joinRows) {
        const memberId = String(row.member_id ?? '').trim();
        const eghteraId = String(row.eghtera_id ?? '').trim();
        if (memberId && eghteraId) {
          eghteraIdByMemberId.set(memberId, eghteraId);
        }
      }
    } catch {
      // Optional fallback when member join ids are unavailable.
    }
  }

  const eghteraIds = [...new Set(eghteraIdByMemberId.values())];
  const pathByEghteraId = eghteraIds.length > 0
    ? await resolveHwyLegacyGeoIdTitlePaths(eghteraIds, queryLang)
    : new Map<string, string>();

  for (const row of rows) {
    const id = readStringField(row, 'id');
    const eghteraId = eghteraIdByMemberId.get(id);
    const fromJoinRegion = eghteraId ? pathByEghteraId.get(eghteraId)?.trim() : '';

    if (fromJoinRegion) {
      row.electoralDivisionPath = formatHwyGeoElectoralPathForDisplay(fromJoinRegion);
    }
  }
}
