import { GEO_ETL_IRAQ_SHORT_NAME } from '../../../../scripts/hwy-etl/geo/constants';
import {
  HWY_SELF_REGISTRATION_LEGACY_PROVINCE_LIST_PARENT_ID,
  legacyGeoIdFromHwyProvinceShortName,
  type HwySelfRegistrationAddressGeoOption,
} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationAddressGeo';
import { mapBaseInfoRowsForCulture } from '../base-info/baseInfoListMapping';
import { prisma } from '../users/prismaHelpers';
import { listLegacyHwyBaseInformationByParent } from './hwyLegacyBaseInformationReader';

const normalizeCultureId = (cultureId: string | null | undefined): string => {
  const trimmed = String(cultureId ?? '').trim();
  return trimmed || 'iq';
};

const legacyRowsToOptions = (rows: Awaited<ReturnType<typeof listLegacyHwyBaseInformationByParent>>): HwySelfRegistrationAddressGeoOption[] => (
  rows.map((row) => ({
    legacyId: String(row.id),
    label: row.title,
  }))
);

const sortAddressOptions = (options: HwySelfRegistrationAddressGeoOption[]): HwySelfRegistrationAddressGeoOption[] => (
  [...options].sort((a, b) => a.label.localeCompare(b.label, 'ar'))
);

export const listHwySelfRegistrationProvinces = async (
  cultureId: string | null | undefined,
): Promise<HwySelfRegistrationAddressGeoOption[]> => {
  const resolvedCultureId = normalizeCultureId(cultureId);

  const iraq = await prisma().baseInfo.findFirst({
    where: { shortName: GEO_ETL_IRAQ_SHORT_NAME },
    select: { id: true },
  });

  if (iraq) {
    const rows = await prisma().baseInfo.findMany({
      where: {
        parentId: iraq.id,
        shortName: { startsWith: 'hwy-province-' },
        isActive: true,
      },
      orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
      select: {
        id: true,
        parentId: true,
        title: true,
        shortName: true,
        note: true,
        metadata: true,
        value: true,
        isActive: true,
        viewOrder: true,
        uiColor: true,
        uiHtml: true,
      },
    });

    if (rows.length > 0) {
      const mapped = await mapBaseInfoRowsForCulture(rows, resolvedCultureId, (row, context) => ({
        legacyId: legacyGeoIdFromHwyProvinceShortName(row.shortName) ?? '',
        label: context.label,
      }));

      const options = mapped
        .map((item) => ({
          legacyId: String(item.legacyId ?? ''),
          label: String(item.label ?? '').trim(),
        }))
        .filter((item) => item.legacyId && item.label);

      if (options.length > 0) {
        return sortAddressOptions(options);
      }
    }
  }

  const legacy = await listLegacyHwyBaseInformationByParent(
    HWY_SELF_REGISTRATION_LEGACY_PROVINCE_LIST_PARENT_ID,
  );
  return sortAddressOptions(legacyRowsToOptions(legacy));
};

export const listHwySelfRegistrationDistricts = async (
  provinceLegacyId: string | null | undefined,
  _cultureId: string | null | undefined,
): Promise<HwySelfRegistrationAddressGeoOption[]> => {
  const provinceRaw = String(provinceLegacyId ?? '').trim();
  if (!/^\d+$/.test(provinceRaw)) {
    return [];
  }

  const parentId = Number(provinceRaw);
  const legacy = await listLegacyHwyBaseInformationByParent(parentId);
  return sortAddressOptions(legacyRowsToOptions(legacy));
};

export const isHwySelfRegistrationProvinceLegacyId = async (
  provinceLegacyId: string,
): Promise<boolean> => {
  const trimmed = provinceLegacyId.trim();
  if (!trimmed) return false;
  const provinces = await listHwySelfRegistrationProvinces('iq');
  return provinces.some((option) => option.legacyId === trimmed);
};

export const isHwySelfRegistrationDistrictLegacyId = async (
  provinceLegacyId: string,
  districtLegacyId: string,
): Promise<boolean> => {
  const districtTrimmed = districtLegacyId.trim();
  if (!districtTrimmed) return true;
  const districts = await listHwySelfRegistrationDistricts(provinceLegacyId, 'iq');
  return districts.some((option) => option.legacyId === districtTrimmed);
};
