import { findHwyGeoResponsibilityRoleSpecByRoleName } from './hwyGeoResponsibilityCatalog';

const LEGACY_APPEND_ROLE_NOTE = /^Legacy AppEnd role \d+:\s*(.+)$/i;

/** Human label for a platform role (legacy HWY roles store Arabic title in `base_roles.note`). */
export function formatHwyPlatformRoleDisplayLabel(
  roleName: string,
  roleNote: string | null | undefined,
): string {
  const name = String(roleName ?? '').trim();
  const note = String(roleNote ?? '').trim();
  const legacyMatch = note.match(LEGACY_APPEND_ROLE_NOTE);
  if (legacyMatch?.[1]?.trim()) {
    return legacyMatch[1].trim();
  }
  const geoSpec = findHwyGeoResponsibilityRoleSpecByRoleName(name);
  if (geoSpec) {
    return geoSpec.level;
  }
  return name || note;
}

export function sortHwyPlatformRoleDisplayLabels(labels: readonly string[]): string[] {
  const unique = Array.from(new Set(labels.map((label) => label.trim()).filter(Boolean)));
  return unique.sort((left, right) => left.localeCompare(right, undefined, { sensitivity: 'base' }));
}
