const stepById = new Map(HWY_ETL_STEPS.map((step) => [step.id, step]));

export function findHwyEtlStepById(stepId: string): HwyEtlStepDefinition | undefined {
  return stepById.get(stepId);
}

export function resolveHwyEtlPresetSteps(preset: HwyEtlPresetDefinition): HwyEtlStepDefinition[] {
  if (preset.orchestratorStepId) {
    const orchestrator = findHwyEtlStepById(preset.orchestratorStepId);
    return orchestrator ? [orchestrator] : [];
  }
  return preset.stepIds
    .map((id) => findHwyEtlStepById(id))
    .filter((step): step is HwyEtlStepDefinition => Boolean(step));
}

