/**
 * Link sample hwy_members → base_users + base_user_profiles (legacy UserName + Picture_*).
 * READ-ONLY on MembersV2.
 */
import sql from 'mssql';
import { connectMssqlControlPlane } from '../hwy-phase1/hwyDataSource';
import { readLegacyConn } from './legacyConn';
import { HWY_INDIVIDUAL_PERSON_TYPE_CODE, resolveLegacyMemberUsername } from './legacyMaps';
import { resolveSampleVocab } from './resolveSampleVocab';
import {
  bindValuesRow,
  chunkByParamBudget,
  SQL_SERVER_PARAM_BUDGET,
  type BoundParam,
} from './sqlBulkHelpers';

const BATCH = Math.max(20, Number(process.env.HWY_ETL_PLATFORM_USER_BATCH ?? 800) || 800);
/** SQL Server caps bound parameters per request (2100). */
const MAX_MEMBER_ID_IN = Math.min(500, Math.max(50, Number(process.env.HWY_ETL_MAX_MEMBER_ID_IN ?? 180) || 180));
/** Default on: skip legacy profile blobs (much faster). Set HWY_ETL_SKIP_PROFILE_IMAGES=0 to import photos. */
const SKIP_PROFILE_IMAGES = process.env.HWY_ETL_SKIP_PROFILE_IMAGES !== '0';
const DISABLED_HASH = '$2b$10$abcdefghijklmnopqrstuuDISABLEDACCOUNTPLACEHOLDER12';

const syntheticMemberEmail = (memberId: number): string => `member-${memberId}@sample.hawiety.local`;

/** Strip bidi / zero-width chars so duplicate emails match the cache and UNIQUE index. */
const normalizePlatformEmail = (raw: string | null | undefined): string | null => {
  if (raw == null) return null;
  const s = raw.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u2069\uFEFF]/g, '').trim();
  return s || null;
};

const emailCacheKey = (email: string): string => normalizePlatformEmail(email)?.toLowerCase() ?? '';

/** In-memory username/email reservation — avoids per-member SELECT on base_users. */
class PlatformUserLookupCache {
  private readonly usernames = new Map<string, number>();

  private readonly emails = new Set<string>();

  private readonly emailToUserId = new Map<string, number>();

  private readonly userIds = new Set<number>();

  /** One platform user ↔ at most one hwy_member (UQ_hwy_members_user_id). */
  private readonly memberIdByUserId = new Map<number, number>();

  static async load(local: sql.ConnectionPool): Promise<PlatformUserLookupCache> {
    const cache = new PlatformUserLookupCache();
    const linked = (await local.request().query(`
      SELECT id, user_id FROM dbo.hwy_members WHERE user_id IS NOT NULL
    `)).recordset as Array<{ id: number; user_id: number }>;
    for (const row of linked) {
      const memberId = Number(row.id);
      const userId = Number(row.user_id);
      if (memberId > 0 && userId > 0) {
        cache.memberIdByUserId.set(userId, memberId);
      }
    }
    let lastId = 0;
    for (;;) {
      const page = (await local.request()
        .input('lastId', sql.BigInt, lastId)
        .input('take', sql.Int, 10_000)
        .query(`
          SELECT TOP (@take) id, username, email
          FROM dbo.base_users
          WHERE id > @lastId
          ORDER BY id
        `)).recordset as Array<{ id: number; username: string; email: string | null }>;
      if (!page.length) break;
      for (const row of page) {
        cache.ingest(Number(row.id), row.username, row.email);
        lastId = Number(row.id);
      }
    }
    return cache;
  }

  ingest(userId: number, username: string, email: string | null | undefined): void {
    if (userId > 0) this.userIds.add(userId);
    const nameKey = username.trim().toLowerCase();
    if (nameKey) this.usernames.set(nameKey, userId);
    const mail = emailCacheKey(email);
    if (mail) {
      this.emails.add(mail);
      this.emailToUserId.set(mail, userId);
    }
  }

  emailOwner(email: string): number | null {
    const key = emailCacheKey(email);
    if (!key) return null;
    return this.emailToUserId.get(key) ?? null;
  }

  hasUserId(userId: number): boolean {
    return this.userIds.has(userId);
  }

  usernameOwner(username: string): number | null {
    const key = username.trim().toLowerCase();
    if (!key) return null;
    return this.usernames.get(key) ?? null;
  }

  reserveUsername(memberId: number, username: string, reservedUserId: number | null): string {
    const base = username.trim() || `member-${memberId}`;
    let candidate = base;
    for (let attempt = 0; attempt < 6; attempt += 1) {
      const owner = this.usernameOwner(candidate);
      if (owner == null || (reservedUserId != null && owner === reservedUserId)) {
        if (reservedUserId != null) {
          this.usernames.set(candidate.toLowerCase(), reservedUserId);
        }
        return candidate;
      }
      candidate = attempt === 0 ? `${base}_${memberId}` : `${base}_${memberId}_${attempt}`;
    }
    const fallback = `member-${memberId}`;
    if (reservedUserId != null) {
      this.usernames.set(fallback.toLowerCase(), reservedUserId);
    }
    return fallback;
  }

  reserveEmail(memberId: number, email: string): string {
    const synthetic = syntheticMemberEmail(memberId);
    if (email.endsWith('@sample.hawiety.local')) {
      return synthetic;
    }
    const normalized = normalizePlatformEmail(email) ?? email;
    const key = emailCacheKey(normalized);
    if (!key || !this.emails.has(key)) {
      return normalized;
    }
    return synthetic;
  }

  registerUser(userId: number, username: string, email: string | null): void {
    this.ingest(userId, username, email);
  }

  /** False when another member already owns this user_id. */
  canLinkUserToMember(memberId: number, userId: number): boolean {
    if (userId <= 0) return false;
    const owner = this.memberIdByUserId.get(userId);
    return owner == null || owner === memberId;
  }

  reserveMemberUserLink(memberId: number, userId: number): boolean {
    if (!this.canLinkUserToMember(memberId, userId)) return false;
    this.memberIdByUserId.set(userId, memberId);
    return true;
  }

  unreserveMemberUserLink(memberId: number): void {
    for (const [userId, ownerMemberId] of this.memberIdByUserId) {
      if (ownerMemberId === memberId) {
        this.memberIdByUserId.delete(userId);
        return;
      }
    }
  }

  async resolveEmailOwnerDb(local: sql.ConnectionPool, email: string): Promise<number | null> {
    const cached = this.emailOwner(email);
    if (cached != null) return cached;
    const row = await local.request()
      .input('email', sql.NVarChar(1000), email)
      .query('SELECT TOP (1) id FROM dbo.base_users WHERE email = @email');
    if (!row.recordset.length) return null;
    const userId = Number((row.recordset[0] as { id: number }).id);
    if (userId > 0) {
      this.registerUser(userId, '', email);
      return userId;
    }
    return null;
  }
}

const toStr = (v: unknown, max?: number): string | null => {
  if (v == null) return null;
  const s = String(v);
  if (!s.trim()) return null;
  return max && s.length > max ? s.slice(0, max) : s;
};

const SYNTHETIC_USERNAME = /^m(\d+)$/i;

const isSyntheticMigrateUsername = (username: string, memberId: number): boolean => {
  const trimmed = username.trim();
  if (trimmed === String(memberId)) return true;
  const match = SYNTHETIC_USERNAME.exec(trimmed);
  return match != null && Number(match[1]) === memberId;
};

const resolveMemberPlatformUsername = (
  memberId: number,
  legacy: Record<string, unknown>,
  memberUsername: unknown,
  localTrackingCode: unknown,
): string | null => resolveLegacyMemberUsername({
  memberId,
  userName: legacy.UserName ?? memberUsername,
  trackingCode: legacy.TrackingCode ?? localTrackingCode,
});

const PROFILE_MERGE_PARAMS = SKIP_PROFILE_IMAGES ? 13 : 17;

type ProfileUpsertRow = {
  userId: number;
  fn: string | null;
  ln: string | null;
  fan: string | null;
  gfn: string | null;
  nick: string | null;
  nat: string | null;
  by: string | null;
  bm: string | null;
  bd: string | null;
  gen: string | null;
  phone: string | null;
  mime: string | null;
  psize: number | null;
  pbody: Buffer | null;
  pbodyxs: Buffer | null;
};

async function mergeProfilesBulk(
  reqFactory: () => sql.Request,
  rows: ProfileUpsertRow[],
): Promise<void> {
  if (!rows.length) return;
  for (const slice of chunkByParamBudget(rows, PROFILE_MERGE_PARAMS)) {
    const req = reqFactory();
    const valueRows: string[] = [];
    slice.forEach((row, rowIndex) => {
      const params: BoundParam[] = [
        { name: 'uid', type: sql.BigInt, value: row.userId },
        { name: 'fn', type: sql.NVarChar(1000), value: row.fn },
        { name: 'ln', type: sql.NVarChar(1000), value: row.ln },
        { name: 'fan', type: sql.NVarChar(1000), value: row.fan },
        { name: 'gfn', type: sql.NVarChar(1000), value: row.gfn },
        { name: 'nick', type: sql.NVarChar(1000), value: row.nick },
        { name: 'nat', type: sql.NVarChar(1000), value: row.nat },
        { name: 'by', type: sql.NVarChar(1000), value: row.by },
        { name: 'bm', type: sql.NVarChar(1000), value: row.bm },
        { name: 'bd', type: sql.NVarChar(1000), value: row.bd },
        { name: 'gen', type: sql.NVarChar(1000), value: row.gen },
        { name: 'ptype', type: sql.NVarChar(1000), HWY_INDIVIDUAL_PERSON_TYPE_CODE },
        { name: 'phone', type: sql.NVarChar(1000), value: row.phone },
      ];
      if (!SKIP_PROFILE_IMAGES) {
        params.push(
          { name: 'mime', type: sql.NVarChar(1000), value: row.mime },
          { name: 'psize', type: sql.Int, value: row.psize },
          { name: 'pbody', type: sql.VarBinary(sql.MAX), value: row.pbody },
          { name: 'pbodyxs', type: sql.VarBinary(sql.MAX), value: row.pbodyxs },
        );
      }
      valueRows.push(bindValuesRow(req, rowIndex, params));
    });
    const imageUpdate = SKIP_PROFILE_IMAGES
      ? ''
      : `, profile_image_body = CASE WHEN s.pbody IS NULL THEN t.profile_image_body ELSE s.pbody END,
              profile_image_body_xs = CASE WHEN s.pbodyxs IS NULL THEN t.profile_image_body_xs ELSE s.pbodyxs END,
              profile_image_mime = CASE WHEN s.mime IS NULL THEN t.profile_image_mime ELSE s.mime END,
              profile_image_size = CASE WHEN s.psize IS NULL THEN t.profile_image_size ELSE s.psize END`;
    const imageInsertCols = SKIP_PROFILE_IMAGES
      ? ''
      : ', profile_image_body, profile_image_body_xs, profile_image_mime, profile_image_size';
    const imageInsertVals = SKIP_PROFILE_IMAGES
      ? ''
      : ', s.pbody, s.pbodyxs, s.mime, s.psize';
    const valueColumns = SKIP_PROFILE_IMAGES
      ? `user_id, firstname, lastname, fathername, grandfathername, nickname, national_code,
          birth_year, birth_month, birth_day, gender_code, person_type_code, phone`
      : `user_id, firstname, lastname, fathername, grandfathername, nickname, national_code,
          birth_year, birth_month, birth_day, gender_code, person_type_code, phone, mime, psize, pbody, pbodyxs`;
    await req.query(`
      MERGE dbo.base_user_profiles AS t
      USING (
        SELECT * FROM (VALUES ${valueRows.join(',\n')}) AS v(
          ${valueColumns}
        )
      ) AS s ON t.user_id = s.user_id
      WHEN MATCHED THEN UPDATE SET
        firstname = s.firstname, lastname = s.lastname, fathername = s.fathername,
        grandfathername = s.grandfathername, nickname = s.nickname, national_code = s.national_code,
        birth_year = s.birth_year, birth_month = s.birth_month, birth_day = s.birth_day,
        gender_code = s.gender_code, person_type_code = s.person_type_code, phone = s.phone${imageUpdate},
        updated_at = SYSUTCDATETIME()
      WHEN NOT MATCHED THEN INSERT (
        user_id, firstname, lastname, fathername, grandfathername, nickname, national_code,
        birth_year, birth_month, birth_day, gender_code, person_type_code, phone${imageInsertCols},
        created_at, updated_at
      ) VALUES (
        s.user_id, s.firstname, s.lastname, s.fathername, s.grandfathername, s.nickname, s.national_code,
        s.birth_year, s.birth_month, s.birth_day, s.gender_code, s.person_type_code, s.phone${imageInsertVals},
        SYSUTCDATETIME(), SYSUTCDATETIME()
      );
    `);
  }
}

const applyPlatformUsername = async (
  local: sql.ConnectionPool,
  userId: number,
  memberId: number,
  resolved: string | null,
  existingUsername: string | null | undefined,
  lookup?: PlatformUserLookupCache,
): Promise<string> => {
  const current = existingUsername?.trim() ?? '';
  const resolvedTrimmed = resolved?.trim() ?? '';
  if (!resolvedTrimmed) {
    return current;
  }
  if (current && !isSyntheticMigrateUsername(current, memberId)) {
    return current;
  }
  const target = resolvedTrimmed;
  if (!target || target === current) {
    return current || target;
  }
  const takenOwner = lookup?.usernameOwner(target);
  if (takenOwner != null && takenOwner !== userId) {
    return current || target;
  }
  if (!lookup) {
    const taken = await local.request()
      .input('username', sql.NVarChar(1000), target)
      .input('uid', sql.BigInt, userId)
      .query('SELECT id FROM dbo.base_users WHERE username = @username AND id <> @uid');
    if (taken.recordset.length) {
      return current || target;
    }
  }
  await local.request()
    .input('username', sql.NVarChar(1000), target)
    .input('uid', sql.BigInt, userId)
    .query('UPDATE dbo.base_users SET username = @username, updated_at = SYSUTCDATETIME() WHERE id = @uid');
  return target;
};

const PLACEHOLDER_EMAILS = new Set([
  'لا يوجد',
  'none',
  'n/a',
  'na',
  'null',
  '-',
]);

const resolveMemberEmail = (memberId: number, raw: string | null): string => {
  const trimmed = normalizePlatformEmail(raw);
  if (!trimmed || !trimmed.includes('@')) {
    return syntheticMemberEmail(memberId);
  }
  const key = trimmed.toLowerCase();
  if (PLACEHOLDER_EMAILS.has(key) || PLACEHOLDER_EMAILS.has(trimmed)) {
    return syntheticMemberEmail(memberId);
  }
  return trimmed;
};

export async function migrateSamplePlatformUsers(
  memberIds?: number[],
  options?: { closePools?: boolean },
): Promise<{
  linked: number;
  createdUsers: number;
  createdProfiles: number;
}> {
  if (memberIds && memberIds.length > MAX_MEMBER_ID_IN) {
    const totals = { linked: 0, createdUsers: 0, createdProfiles: 0 };
    for (let offset = 0; offset < memberIds.length; offset += MAX_MEMBER_ID_IN) {
      const slice = memberIds.slice(offset, offset + MAX_MEMBER_ID_IN);
      const part = await migrateSamplePlatformUsers(slice, { closePools: false });
      totals.linked += part.linked;
      totals.createdUsers += part.createdUsers;
      totals.createdProfiles += part.createdProfiles;
    }
    return totals;
  }

  const vocab = await resolveSampleVocab();
  const legacy = await new sql.ConnectionPool(readLegacyConn()).connect();
  const local = await connectMssqlControlPlane();
  const lookup = await PlatformUserLookupCache.load(local);
  console.log(
    `[hwy:etl:platform-users] cache loaded | batch=${BATCH} | skipProfileImages=${SKIP_PROFILE_IMAGES}`,
  );

  let linked = 0;
  let createdUsers = 0;
  let createdProfiles = 0;

  const pendingFilter = `
    AND (
      m.user_id IS NULL
      OR NOT EXISTS (SELECT 1 FROM dbo.base_user_profiles p WHERE p.user_id = m.user_id)
    )
  `;

  try {
    const idFilter = memberIds?.length
      ? `AND m.id IN (${memberIds.map((_, i) => `@mid${i}`).join(', ')})`
      : '';
    const countReq = local.request();
    memberIds?.forEach((id, i) => countReq.input(`mid${i}`, sql.BigInt, id));
    const total = Number((await countReq.query(`
      SELECT COUNT(*) c FROM dbo.hwy_members m WHERE 1=1 ${idFilter} ${pendingFilter}
    `)).recordset[0].c);
    console.log(`[hwy:etl:platform-users] pending members: ${total}`);

    const legacyMemberCols = SKIP_PROFILE_IMAGES
      ? 'Id, UserId, UserName, TrackingCode, Email, Phone1, Phone2'
      : 'Id, UserId, UserName, TrackingCode, Email, Phone1, Phone2, Picture_FileBody, Picture_FileBody_xs, Picture_FileMime, Picture_FileSize';

    let lastId = 0;
    let processedInRun = 0;
    while (true) {
      const req = local.request().input('lastId', sql.BigInt, lastId).input('take', sql.Int, BATCH);
      memberIds?.forEach((id, i) => req.input(`mid${i}`, sql.BigInt, id));
      const members = (await req.query(`
        SELECT TOP (@take) m.id, m.user_id, m.first_name, m.family_name, m.father_name, m.grandfather_name,
          m.nickname, m.gender_code, m.birth_year, m.birth_month, m.birth_day, m.national_id,
          m.phone1, m.email, m.username AS member_username,
          CAST(m.id AS NVARCHAR(32)) AS tracking_code
        FROM dbo.hwy_members m
        WHERE m.id > @lastId ${idFilter} ${pendingFilter}
        ORDER BY m.id
      `)).recordset as Array<Record<string, unknown>>;

      if (!members.length) break;

      const tx = new sql.Transaction(local);
      await tx.begin();
      const txReq = () => new sql.Request(tx);

      const ids = members.map((m) => Number(m.id));
      const legReq = legacy.request();
      ids.forEach((id, i) => legReq.input(`lid${i}`, sql.BigInt, id));
      const legacyRows = (await legReq.query(`
        SELECT ${legacyMemberCols}
        FROM dbo.HWY_Members WITH (NOLOCK)
        WHERE Id IN (${ids.map((_, i) => `@lid${i}`).join(', ')})
      `)).recordset as Array<Record<string, unknown>>;
      const leg = new Map(legacyRows.map((r) => [Number(r.Id), r]));

      const memberLinkRows: Array<{ mid: number; uid: number; username: string | null }> = [];
      const profileRows: ProfileUpsertRow[] = [];

      let batchSkipped = 0;
      try {
      for (const m of members) {
        try {
        const mid = Number(m.id);
        const L = leg.get(mid) ?? {};
        let userId = m.user_id != null ? Number(m.user_id) : (L.UserId != null ? Number(L.UserId) : null);

        const resolvedUsername = resolveMemberPlatformUsername(mid, L, m.member_username, m.tracking_code);
        let username = resolvedUsername ?? `member-${mid}`;
        username = lookup.reserveUsername(mid, username, userId);
        let email = resolveMemberEmail(mid, toStr(L.Email ?? m.email, 1000));
        email = lookup.reserveEmail(mid, email);
        const ownerByEmail = lookup.emailOwner(email);
        if (ownerByEmail != null && lookup.canLinkUserToMember(mid, ownerByEmail)) {
          userId = ownerByEmail;
        } else if (ownerByEmail != null) {
          email = syntheticMemberEmail(mid);
          userId = null;
        }

        const ensureUserRow = async (): Promise<void> => {
          if (userId != null && lookup.hasUserId(userId)) {
            username = await applyPlatformUsername(local, userId, mid, resolvedUsername, username, lookup);
            lookup.registerUser(userId, username, email);
            return;
          }
          if (userId != null && !lookup.hasUserId(userId)) {
            username = lookup.reserveUsername(mid, username, userId);
            try {
              await txReq()
                .input('id', sql.BigInt, userId)
                .input('username', sql.NVarChar(1000), username)
                .input('email', sql.NVarChar(1000), email)
                .input('mobile', sql.NVarChar(1000), toStr(L.Phone1 ?? m.phone1, 1000))
                .input('hash', sql.NVarChar(1000), DISABLED_HASH)
                .query(`
                  SET IDENTITY_INSERT dbo.base_users ON;
                  INSERT INTO dbo.base_users (id, username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
                  VALUES (@id, @username, @email, @hash, 0, 0, 0, @mobile, SYSUTCDATETIME(), SYSUTCDATETIME());
                  SET IDENTITY_INSERT dbo.base_users OFF;
                `);
              createdUsers += 1;
              lookup.registerUser(userId, username, email);
              return;
            } catch (err) {
              const msg = err instanceof Error ? err.message : String(err);
              if (!msg.includes('UNIQUE KEY') && !msg.includes('2627')) {
                throw err;
              }
              if (msg.includes('email')) {
                email = syntheticMemberEmail(mid);
                userId = null;
              }
            }
          }
          const ownerByName = lookup.usernameOwner(username);
          if (ownerByName != null && lookup.canLinkUserToMember(mid, ownerByName)) {
            userId = ownerByName;
            username = await applyPlatformUsername(local, userId, mid, resolvedUsername, username, lookup);
            lookup.registerUser(userId, username, email);
            return;
          }
          const ownerByEmailRetry = lookup.emailOwner(email);
          if (ownerByEmailRetry != null && lookup.canLinkUserToMember(mid, ownerByEmailRetry)) {
            userId = ownerByEmailRetry;
            username = await applyPlatformUsername(local, userId, mid, resolvedUsername, username, lookup);
            lookup.registerUser(userId, username, email);
            return;
          }
          username = lookup.reserveUsername(mid, username, null);
          try {
            const ins = await txReq()
              .input('username', sql.NVarChar(1000), username)
              .input('email', sql.NVarChar(1000), email)
              .input('mobile', sql.NVarChar(1000), toStr(L.Phone1 ?? m.phone1, 1000))
              .input('hash', sql.NVarChar(1000), DISABLED_HASH)
              .query(`
                INSERT INTO dbo.base_users (username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
                OUTPUT INSERTED.id
                VALUES (@username, @email, @hash, 0, 0, 0, @mobile, SYSUTCDATETIME(), SYSUTCDATETIME());
              `);
            userId = Number(ins.recordset[0].id);
            createdUsers += 1;
            lookup.registerUser(userId, username, email);
          } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            if (msg.includes('UNIQUE KEY') || msg.includes('2627')) {
              if (msg.includes('email') && !email.endsWith('@sample.hawiety.local')) {
                email = syntheticMemberEmail(mid);
                username = lookup.reserveUsername(mid, username, null);
                const retry = await txReq()
                  .input('username', sql.NVarChar(1000), username)
                  .input('email', sql.NVarChar(1000), email)
                  .input('mobile', sql.NVarChar(1000), toStr(L.Phone1 ?? m.phone1, 1000))
                  .input('hash', sql.NVarChar(1000), DISABLED_HASH)
                  .query(`
                    INSERT INTO dbo.base_users (username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
                    OUTPUT INSERTED.id
                    VALUES (@username, @email, @hash, 0, 0, 0, @mobile, SYSUTCDATETIME(), SYSUTCDATETIME());
                  `);
                userId = Number(retry.recordset[0].id);
                createdUsers += 1;
                lookup.registerUser(userId, username, email);
                return;
              }
              const owner = await lookup.resolveEmailOwnerDb(local, email)
                ?? await lookup.resolveEmailOwnerDb(local, syntheticMemberEmail(mid));
              if (owner != null && lookup.canLinkUserToMember(mid, owner)) {
                userId = owner;
                username = await applyPlatformUsername(local, userId, mid, resolvedUsername, username, lookup);
                lookup.registerUser(userId, username, email);
                return;
              }
              if (owner != null) {
                email = syntheticMemberEmail(mid);
                username = lookup.reserveUsername(mid, `member-${mid}`, null);
                const retry = await txReq()
                  .input('username', sql.NVarChar(1000), username)
                  .input('email', sql.NVarChar(1000), email)
                  .input('mobile', sql.NVarChar(1000), toStr(L.Phone1 ?? m.phone1, 1000))
                  .input('hash', sql.NVarChar(1000), DISABLED_HASH)
                  .query(`
                    INSERT INTO dbo.base_users (username, email, password_hash, is_builtin, locked, login_fail_count, mobile, created_at, updated_at)
                    OUTPUT INSERTED.id
                    VALUES (@username, @email, @hash, 0, 0, 0, @mobile, SYSUTCDATETIME(), SYSUTCDATETIME());
                  `);
                userId = Number(retry.recordset[0].id);
                createdUsers += 1;
                lookup.registerUser(userId, username, email);
                return;
              }
            }
            throw err;
          }
        };

        await ensureUserRow();

        if (userId == null) {
          throw new Error(`platform user missing after ensureUserRow for member ${mid}`);
        }
        if (!lookup.reserveMemberUserLink(mid, userId)) {
          userId = null;
          email = syntheticMemberEmail(mid);
          username = lookup.reserveUsername(mid, `member-${mid}`, null);
          await ensureUserRow();
          if (userId == null || !lookup.reserveMemberUserLink(mid, userId)) {
            throw new Error(`could not allocate exclusive platform user for member ${mid}`);
          }
        }

        memberLinkRows.push({ mid, uid: userId, username: resolvedUsername });

        const genderCode = m.gender_code != null
          ? String(m.gender_code)
          : (L.GenderId != null ? vocab.genderByLegacyId.get(Number(L.GenderId)) ?? null : null);

        const hasPic = !SKIP_PROFILE_IMAGES && L.Picture_FileBody != null;
        profileRows.push({
          userId,
          fn: toStr(m.first_name, 1000),
          ln: toStr(m.family_name, 1000),
          fan: toStr(m.father_name, 1000),
          gfn: toStr(m.grandfather_name, 1000),
          nick: toStr(m.nickname, 1000),
          nat: toStr(m.national_id, 1000),
          by: m.birth_year != null ? String(m.birth_year) : null,
          bm: m.birth_month != null ? String(m.birth_month) : null,
          bd: m.birth_day != null ? String(m.birth_day) : null,
          gen: genderCode,
          phone: toStr(L.Phone1 ?? m.phone1, 1000),
          mime: hasPic ? toStr(L.Picture_FileMime, 1000) : null,
          psize: hasPic ? Number(L.Picture_FileSize) : null,
          pbody: hasPic ? L.Picture_FileBody as Buffer : null,
          pbodyxs: hasPic ? L.Picture_FileBody_xs as Buffer : null,
        });
        linked += 1;
        } catch (memberErr) {
          batchSkipped += 1;
          lookup.unreserveMemberUserLink(Number(m.id));
          console.warn(
            `[hwy:etl:platform-users] skip member ${m.id}:`,
            memberErr instanceof Error ? memberErr.message : memberErr,
          );
        }
      }

      if (batchSkipped > 0) {
        console.warn(`[hwy:etl:platform-users] batch skipped ${batchSkipped} members (continuing)`);
      }

      await mergeProfilesBulk(txReq, profileRows);
      createdProfiles += profileRows.length;

      if (memberLinkRows.length) {
        const byUser = new Map<number, { mid: number; uid: number; username: string | null }>();
        for (const row of memberLinkRows) {
          const prev = byUser.get(row.uid);
          if (prev == null || row.mid < prev.mid) {
            byUser.set(row.uid, row);
          }
        }
        const uniqueLinks = [...byUser.values()];
        const linkChunkSize = Math.floor(SQL_SERVER_PARAM_BUDGET / 3);
        for (let i = 0; i < uniqueLinks.length; i += linkChunkSize) {
          const slice = uniqueLinks.slice(i, i + linkChunkSize);
          const linkReq = txReq();
          const pairs: string[] = [];
          slice.forEach((row, j) => {
            linkReq.input(`lm${j}`, sql.BigInt, row.mid);
            linkReq.input(`lu${j}`, sql.BigInt, row.uid);
            linkReq.input(`lx${j}`, sql.NVarChar(4000), row.username);
            pairs.push(`(@lm${j}, @lu${j}, @lx${j})`);
          });
          await linkReq.query(`
            UPDATE m SET user_id = v.uid, username = v.un, updated_at = SYSUTCDATETIME()
            FROM dbo.hwy_members m
            INNER JOIN (VALUES ${pairs.join(', ')}) AS v(id, uid, un) ON m.id = v.id
          `);
        }
      }

      await tx.commit();
      } catch (batchErr) {
        await tx.rollback();
        throw batchErr;
      }

      lastId = Number(members[members.length - 1].id);
      processedInRun += members.length;
      console.log(
        `[hwy:etl:platform-users] progress: linked ${linked} | batch through id ${lastId} | pending left ~${Math.max(0, total - processedInRun)}`,
      );
    }

    return { linked, createdUsers, createdProfiles };
  } finally {
    if (options?.closePools !== false) {
      await legacy.close();
      await local.close();
    } else {
      await legacy.close();
    }
  }
}
