import sql from 'mssql';
import { createEdgeDbQueryExecutor } from '../../../core/database/EdgeDbRouter';
import { SETTINGS_PATH } from '../../config/settingsFile';
import type { ControlPlaneDbProvider } from '../../db/controlPlaneDatabase';
import { readControlPlaneDatabaseSettings } from '../../db/controlPlaneDatabase';
import { getDataSourcesFromSettings } from '../../db/dataSourcesStore';
import { buildMssqlConfigFromControlPlaneUrl } from '../../db/mssqlControlPlaneConfig';
import { EdgeModelService } from '../../services/data-api/edgeModelService';
import { listEdgeModels } from '../../services/data-api/edgeModelStore';
import { resetEdgeSequelizeFactoryCache } from '../../services/data-api/sequelize/edgeSequelizeFactory';

const NAKHEBIN_EDGE_MODEL_ID = 'em_784d292c4bbcac55';

const applyPhoneColumnDdl = async (pool: sql.ConnectionPool): Promise<void> => {
  await pool.request().query(`
    IF COL_LENGTH(N'dbo.hwy_nakhebin', N'phone1') IS NULL
      ALTER TABLE dbo.hwy_nakhebin ADD phone1 NVARCHAR(4000) NULL;
    IF COL_LENGTH(N'dbo.hwy_nakhebin', N'phone2') IS NULL
      ALTER TABLE dbo.hwy_nakhebin ADD phone2 NVARCHAR(4000) NULL;
  `);
};

const refreshNakhebinEdgeModel = async (): Promise<void> => {
  const getDataSources = () => getDataSourcesFromSettings(SETTINGS_PATH);
  const edgeModelService = new EdgeModelService({
    settingsPath: SETTINGS_PATH,
    edgeDbQuery: createEdgeDbQueryExecutor({ getDataSources }),
    getDataSources,
  });

  const existing = getEdgeModelByIdSafe();
  if (!existing) {
    return;
  }

  await edgeModelService.refreshModel(existing.id);
  await resetEdgeSequelizeFactoryCache();
};

const getEdgeModelByIdSafe = () => {
  const settings = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  const dataSourceId = getDataSourcesFromSettings(SETTINGS_PATH).find((source) => source.type === 'mssql')?.id
    ?? getDataSourcesFromSettings(SETTINGS_PATH)[0]?.id;
  return listEdgeModels().find(
    (model) => model.id === NAKHEBIN_EDGE_MODEL_ID
      || (model.objectName === 'hwy_nakhebin' && (!dataSourceId || model.dataSourceId === dataSourceId)),
  );
};

/** Idempotent DDL + edge model refresh so Data API can read `phone1` / `phone2` on nakhebin list. */
export const ensureHwyNakhebinPhoneSchema = async (
  provider: ControlPlaneDbProvider,
): Promise<void> => {
  if (provider !== 'sqlserver') {
    return;
  }

  const settings = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  const pool = new sql.ConnectionPool(buildMssqlConfigFromControlPlaneUrl(settings.url));
  await pool.connect();
  try {
    await applyPhoneColumnDdl(pool);
  } finally {
    await pool.close();
  }

  await refreshNakhebinEdgeModel();
};
