/** Stable map keys for `hwy_members.id` / nakhebin `member_id` joins in household UI. */
export const normalizeHwyHouseholdMemberId = (value: unknown): string => {
  if (value == null) {
    return '';
  }
  if (typeof value === 'number' && Number.isFinite(value)) {
    return String(Math.trunc(value));
  }
  return String(value).trim();
};

export const buildHwyHouseholdMemberIdInValues = (
  members: ReadonlyArray<{ id?: unknown }>,
): Array<string | number> => {
  const values = new Set<string | number>();
  for (const row of members) {
    const key = normalizeHwyHouseholdMemberId(row.id);
    if (!key) {
      continue;
    }
    values.add(key);
    const numeric = Number(key);
    if (Number.isFinite(numeric)) {
      values.add(numeric);
    }
  }
  return [...values];
};
