export const HWY_BUSINESS_RULES_REFERENCE_DEFAULT_SECTION: HwyBusinessRulesReferenceSectionId =
  'membership-number';

const SECTION_ID_SET = new Set<string>(
  HWY_BUSINESS_RULES_REFERENCE_SECTIONS.map((entry) => entry.id),
);

export function isHwyBusinessRulesReferenceSectionId(
  value: string | null | undefined,
): value is HwyBusinessRulesReferenceSectionId {
  const trimmed = String(value ?? '').trim();
  return trimmed.length > 0 && SECTION_ID_SET.has(trimmed);
}

export function findHwyBusinessRulesReferenceSection(
  sectionId: HwyBusinessRulesReferenceSectionId,
): HwyBusinessRulesReferenceSection | undefined {
  return HWY_BUSINESS_RULES_REFERENCE_SECTIONS.find((entry) => entry.id === sectionId);
}

export function hwyBusinessRulesReferenceSectionTitleKey(
  sectionId: HwyBusinessRulesReferenceSectionId,
): string {
  return `hwy.businessRules.section.${sectionId}.title`;
}

export function hwyBusinessRulesReferenceSectionIntroKey(
  sectionId: HwyBusinessRulesReferenceSectionId,
): string {
  return `hwy.businessRules.section.${sectionId}.intro`;
}

export function hwyBusinessRulesReferenceNavGroupTitleKey(
  groupId: HwyBusinessRulesReferenceNavGroupId,
): string {
  return `hwy.businessRules.nav.group.${groupId}`;
}

export function hwyBusinessRulesReferenceRuleTitleKey(ruleId: string): string {
  return `hwy.businessRules.rule.${ruleId}.title`;
}

export function hwyBusinessRulesReferenceRuleBodyKey(ruleId: string): string {
  return `hwy.businessRules.rule.${ruleId}.body`;
}
