import {
  HWY_SMS_SUBJECT_SELF_REGISTRATION,
  sendSms,
  type SendSmsResult,
} from '../../services/messaging';

export const deliverHwyMemberRegistrationSms = async (input: {
  phone1: string | null | undefined;
  smsMessage: string | null | undefined;
  actor?: string | null;
}): Promise<SendSmsResult | null> => {
  const phone = (input.phone1 ?? '').trim();
  const message = (input.smsMessage ?? '').trim();
  if (!phone || !message) {
    return null;
  }
  return sendSms({
    to: phone,
    messageToSend: message,
    messageToLog: message,
    subjectId: HWY_SMS_SUBJECT_SELF_REGISTRATION,
    actor: input.actor ?? null,
  });
};
