import { QueryTypes } from 'sequelize';

import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

export type StaffCreateReferrerResolution = {
  referrerUsername: string | null;
  referrerRelationId: number | null;
};

const trim = (value: string | null | undefined, max = 500): string | null => {
  if (value == null) return null;
  const s = value.trim();
  if (!s) return null;
  return s.length > max ? s.slice(0, max) : s;
};

/** Legacy HWY_Members_New: linked staff user = employee registrar (no auto referrer). */
export const isHwyStaffRegistrarEmployee = async (actorUserId: number | null): Promise<boolean> => {
  if (actorUserId == null || !Number.isFinite(actorUserId) || actorUserId <= 0) {
    return false;
  }
  if (readControlPlaneProvider() !== 'sqlserver') {
    return false;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `SELECT TOP (1) id FROM dbo.hwy_members WITH (NOLOCK) WHERE user_id = :userId`,
    { replacements: { userId: actorUserId }, type: QueryTypes.SELECT },
  );
  return rows.length > 0;
};

const loadMemberUsernameByUserId = async (userId: number): Promise<string | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ username: string | null }>(
    `SELECT TOP (1) username FROM dbo.hwy_members WITH (NOLOCK) WHERE user_id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  const username = rows[0]?.username;
  return username != null ? String(username).trim() || null : null;
};

export const resolveStaffCreateReferrer = async (input: {
  actorUserId: number | null;
  referrerUsername?: string | null;
  referrerRelationId?: number | null;
}): Promise<StaffCreateReferrerResolution> => {
  const relationRaw = input.referrerRelationId != null ? String(input.referrerRelationId).trim() : '';
  const relationId = relationRaw && /^\d+$/.test(relationRaw) ? Number(relationRaw) : null;

  const requestedUsername = trim(input.referrerUsername);

  const employee = await isHwyStaffRegistrarEmployee(input.actorUserId);
  if (employee) {
    return {
      referrerUsername: requestedUsername,
      referrerRelationId: requestedUsername && relationId ? relationId : null,
    };
  }

  let defaultUsername: string | null = null;
  if (input.actorUserId != null && Number.isFinite(input.actorUserId)) {
    defaultUsername = await loadMemberUsernameByUserId(input.actorUserId);
  }

  const referrerUsername = requestedUsername ?? defaultUsername;
  return {
    referrerUsername,
    referrerRelationId: referrerUsername && relationId ? relationId : null,
  };
};
