async function loadHwyMemberMembershipStatusCodeByPk(memberId: number): Promise<string | null> {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ membership_status_code: string | null }>(
    `SELECT TOP (1) membership_status_code FROM dbo.hwy_members WHERE id = :memberId`,
    {
      replacements: { memberId },
      type: QueryTypes.SELECT,
    },
  );
  const code = rows[0]?.membership_status_code;
  return code?.trim() ? code.trim() : null;
}

export async function assertHwyMemberTarghinRemoveDirectEligibility(memberId: number): Promise<void> {
  await assertHwyMemberMembershipStatusForTarghin(memberId, 'pending_cancellation');
}

async function assertHwyMemberMembershipStatusForTarghin(
  memberId: number,
  expected: 'active' | 'pending_cancellation',
): Promise<void> {
  const ctx = await loadHwyMemberListScopeContext();
  const expectedCode = expected === 'active'
    ? ctx.membershipStatusCodes.active
    : await tryResolveHwyPendingCancellationStatusId();
  if (!expectedCode) {
    throw new Error('Membership status vocabulary is not configured for this operation.');
  }
  const actual = await loadHwyMemberMembershipStatusCodeByPk(memberId);
  if (!actual || actual !== expectedCode) {
    throw new Error(
      expected === 'active'
        ? 'Targhin request is only allowed for active members.'
        : 'Remove targhin is only allowed for targhined members.',
    );
  }
}

const resolveHwyMemberNoteCreatedByUserId = async (
  createdByUserId: number | null,
): Promise<number | null> => {
  if (createdByUserId == null || !Number.isFinite(createdByUserId) || createdByUserId <= 0) {
    return null;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId: createdByUserId }, type: QueryTypes.SELECT },
  );
  return rows.length ? createdByUserId : null;
};

/** Resolves dossier route key (numeric PK or username) to `hwy_members.id`. */
export const resolveHwyMemberPrimaryKey = async (raw: string): Promise<number> => {
  const trimmed = raw.trim();
  if (!trimmed) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  if (/^\d+$/.test(trimmed)) {
    const id = Number(trimmed);
    if (Number.isFinite(id) && id > 0) {
      const byId = await sequelize.query<{ id: number }>(
        `SELECT id FROM dbo.hwy_members WHERE id = :id`,
        { replacements: { id }, type: QueryTypes.SELECT },
      );
      if (byId.length) {
        return byId[0].id;
      }
    }
  }
  const byUsername = await sequelize.query<{ id: number }>(
    `SELECT id FROM dbo.hwy_members WHERE username = :username`,
    { replacements: { username: trimmed }, type: QueryTypes.SELECT },
  );
  if (byUsername.length) {
    return byUsername[0].id;
  }
  const byUserLogin = await sequelize.query<{ id: number }>(
    `
    SELECT TOP 1 m.id
    FROM dbo.hwy_members m
    INNER JOIN dbo.base_users u ON u.id = m.user_id
    WHERE LTRIM(RTRIM(u.username)) = :username
    `,
    { replacements: { username: trimmed }, type: QueryTypes.SELECT },
  );
  if (byUserLogin.length) {
    return byUserLogin[0].id;
  }
  throw new Error('Member not found.');
};

export const attachBaseInfoTitles = async (
  rows: Record<string, unknown>[],
  specs: Array<{ codeField: string; titleField: string }>,
  queryLang: string,
): Promise<void> => {
  const cultureId = resolveBaseInfoCultureId(queryLang);
  const ids = new Set<string>();
  for (const row of rows) {
    for (const spec of specs) {
      const raw = String(row[spec.codeField] ?? '').trim();
      if (raw) {
        ids.add(raw);
      }
    }
  }
  if (ids.size === 0) {
    return;
  }
  const enriched = await listBaseInfoEnrichmentRowsByIds([...ids], cultureId);
  const byId = new Map(enriched.map((item) => [String(item.id ?? '').trim(), item]));
  for (const row of rows) {
    for (const spec of specs) {
      const raw = String(row[spec.codeField] ?? '').trim();
      const match = byId.get(raw);
      const title = String(match?.title ?? match?.title_canonical ?? '').trim();
      if (title) {
        row[spec.titleField] = title;
      }
    }
  }
};

