export async function createHwyMemberTarghinRequest(
  memberIdRaw: string,
  input: CreateHwyMemberDossierTarghinRequestInput,
  createdByUserId: number | null,
): Promise<HwyMemberDossierTarghinRequestRow> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Targhin requests are not available in this environment.');
  }
  await ensureHwyMemberDossierSatellitesSchema();
  await ensureHwyDbObjects();
  const memberId = await resolveHwyMemberPrimaryKey(memberIdRaw);
  await assertHwyMemberMembershipStatusForTarghin(memberId, 'active');
  const requestReasonCode = input.requestReasonCode.trim();
  if (!requestReasonCode) {
    throw new Error('Targhin request reason is required.');
  }
  let reasonRow = await prisma().baseInfo.findFirst({
    where: {
      id: requestReasonCode,
      parentId: HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID,
      isActive: true,
    },
    select: { id: true },
  });
  if (!reasonRow) {
    try {
      const { syncHwyMemberTarghinRequestReasonsFromLegacy } = await import(
        './hwyMemberTarghinRequestReasonsLegacySync'
      );
      await syncHwyMemberTarghinRequestReasonsFromLegacy();
    } catch {
      // Continue — validation below still applies.
    }
    reasonRow = await prisma().baseInfo.findFirst({
      where: {
        id: requestReasonCode,
        parentId: HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID,
        isActive: true,
      },
      select: { id: true },
    });
  }
  if (!reasonRow) {
    throw new Error('Targhin request reason is invalid.');
  }

  const requestNote = input.requestNote.trim();
  if (!requestNote) {
    throw new Error('Request note is required.');
  }
  if (requestNote.length < HWY_MEMBER_TARGHIN_REQUEST_NOTE_MIN_LENGTH) {
    throw new Error(`Request note must be at least ${HWY_MEMBER_TARGHIN_REQUEST_NOTE_MIN_LENGTH} characters.`);
  }
  if (requestNote.length > HWY_MEMBER_TARGHIN_REQUEST_NOTE_MAX_LENGTH) {
    throw new Error(`Request note must be at most ${HWY_MEMBER_TARGHIN_REQUEST_NOTE_MAX_LENGTH} characters.`);
  }

  const createdBy = await resolveHwyMemberNoteCreatedByUserId(createdByUserId);

  try {
    const inserted = await execHwyProcedure<Record<string, unknown>>('hwy_targhin_create_request', {
      member_id: Number(memberId),
      request_reason_code: requestReasonCode,
      request_note: requestNote,
      created_by: createdBy,
    });
    if (!inserted.length) {
      throw new Error('Could not save targhin request.');
    }
    return inserted[0] as HwyMemberDossierTarghinRequestRow;
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('hwy_member_targhin_requests')) {
      throw new Error('Targhin requests table is not installed. Run the Hawiety DDL migration.');
    }
    throw error;
  }
}

export async function createHwyMemberDossierNote(
  memberIdRaw: string,
  input: CreateHwyMemberDossierNoteInput,
  createdByUserId: number | null,
  queryLang = 'ar',
): Promise<HwyMemberDossierNoteRow> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Member notes are not available in this environment.');
  }
  const memberId = await resolveHwyMemberPrimaryKey(memberIdRaw);
  const body = input.body.trim();
  if (!body) {
    throw new Error('Note body is required.');
  }
  const subjectCode = input.subjectCode?.trim() || null;

  await ensureHwyDbObjects();
  const createdBy = await resolveHwyMemberNoteCreatedByUserId(createdByUserId);

  const inserted = await execHwyProcedure<Record<string, unknown>>('hwy_member_note_insert', {
    member_id: Number(memberId),
    body,
    subject_code: subjectCode,
    created_by: createdBy,
  });

  if (!inserted.length) {
    throw new Error('Could not save note.');
  }

  await attachBaseInfoTitles(
    inserted,
    [{ codeField: 'subjectCode', titleField: 'subjectCodeTitle' }],
    queryLang,
  );
  return inserted[0] as HwyMemberDossierNoteRow;
}

const SECURITY_PROFILE_CODE_TITLE_FIELDS = [
  { codeField: 'canGetIdentityCardCode', titleField: 'canGetIdentityCardCodeTitle' },
  { codeField: 'canGetResponsibilityCode', titleField: 'canGetResponsibilityCodeTitle' },
  { codeField: 'canJoinGeneralBodyCode', titleField: 'canJoinGeneralBodyCodeTitle' },
  { codeField: 'allowsResponsibilityCode', titleField: 'allowsResponsibilityCodeTitle' },
] as const;

/** Append-only pipeline opinions (legacy HWY_Members_SecurityProfile parity). */
const SECURITY_PROFILE_HISTORY_SELECT = `
      CAST(sp.id AS VARCHAR(36)) AS id,
      CAST(sp.member_id AS VARCHAR(32)) AS memberId,
      CAST(sp.can_get_identity_card AS VARCHAR(32)) AS canGetIdentityCardCode,
      sp.can_get_identity_card_note AS canGetIdentityCardNote,
      CAST(sp.can_get_masooliat AS VARCHAR(32)) AS canGetResponsibilityCode,
      sp.can_get_masooliat_note AS canGetResponsibilityNote,
      CAST(sp.can_be_member_of_aammeh AS VARCHAR(32)) AS canJoinGeneralBodyCode,
      sp.can_be_member_of_aammeh_note AS canJoinGeneralBodyNote,
      CAST(sp.allows_responsibility AS VARCHAR(32)) AS allowsResponsibilityCode,
      sp.allows_responsibility_note AS allowsResponsibilityNote,
      sp.created_on AS createdAt
`;

const SECURITY_PROFILE_SNAPSHOT_SELECT = `
      CAST(sp.id AS VARCHAR(32)) AS id,
      CAST(sp.member_id AS VARCHAR(32)) AS memberId,
      sp.can_get_identity_card_code AS canGetIdentityCardCode,
      sp.can_get_identity_card_note AS canGetIdentityCardNote,
      sp.can_get_responsibility_code AS canGetResponsibilityCode,
      sp.can_get_responsibility_note AS canGetResponsibilityNote,
      sp.can_join_general_body_code AS canJoinGeneralBodyCode,
      sp.can_join_general_body_note AS canJoinGeneralBodyNote,
      sp.allows_responsibility_code AS allowsResponsibilityCode,
      sp.allows_responsibility_note AS allowsResponsibilityNote,
      sp.created_at AS createdAt
`;

async function readLatestHwyMemberSecurityProfileHistoryRow(
  memberId: number,
  queryLang: string,
): Promise<HwyMemberDossierSecurityProfileRow | null> {
  const sequelize = getControlPlaneSequelize();
  const historyExists = await sequelize.query<{ ok: number }>(
    `SELECT CASE WHEN OBJECT_ID(N'dbo.hwy_member_security_profile_history', N'U') IS NOT NULL THEN 1 ELSE 0 END AS ok`,
    { type: QueryTypes.SELECT },
  );
  if (!historyExists[0]?.ok) {
    return null;
  }
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT TOP (1)
${SECURITY_PROFILE_HISTORY_SELECT}
    FROM dbo.hwy_member_security_profile_history sp WITH (NOLOCK)
    WHERE sp.member_id = :memberId
    ORDER BY sp.created_on DESC
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    return null;
  }
  await attachBaseInfoTitles(rows, [...SECURITY_PROFILE_CODE_TITLE_FIELDS], queryLang);
  return rows[0] as HwyMemberDossierSecurityProfileRow;
}

