export async function readHwyMemberDossierSecurityProfile(
  memberIdRaw: string,
  queryLang = 'ar',
): Promise<HwyMemberDossierSecurityProfileRow | null> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return null;
  }
  const memberId = await resolveHwyMemberPrimaryKey(memberIdRaw);
  const fromHistory = await readLatestHwyMemberSecurityProfileHistoryRow(memberId, queryLang);
  if (fromHistory) {
    return fromHistory;
  }
  return readHwyMemberSecurityProfileSnapshotRow(memberId, queryLang);
}

const SECURITY_PROFILE_SELECT = SECURITY_PROFILE_SNAPSHOT_SELECT;

async function attachSecurityProfileTitles(
  rows: Record<string, unknown>[],
  queryLang: string,
): Promise<void> {
  if (!rows.length) return;
  await attachBaseInfoTitles(
    rows,
    [
      { codeField: 'canGetIdentityCardCode', titleField: 'canGetIdentityCardCodeTitle' },
      { codeField: 'canGetResponsibilityCode', titleField: 'canGetResponsibilityCodeTitle' },
      { codeField: 'canJoinGeneralBodyCode', titleField: 'canJoinGeneralBodyCodeTitle' },
      { codeField: 'allowsResponsibilityCode', titleField: 'allowsResponsibilityCodeTitle' },
    ],
    queryLang,
  );
}

export async function listHwyMemberDossierSecurityProfileHistory(
  memberIdRaw: string,
  queryLang = 'ar',
): Promise<HwyMemberDossierSecurityProfileRow[]> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  const memberId = await resolveHwyMemberPrimaryKey(memberIdRaw);
  const sequelize = getControlPlaneSequelize();
  const historyExists = await sequelize.query<{ ok: number }>(
    `SELECT CASE WHEN OBJECT_ID(N'dbo.hwy_member_security_profile_history', N'U') IS NOT NULL THEN 1 ELSE 0 END AS ok`,
    { type: QueryTypes.SELECT },
  );
  if (historyExists[0]?.ok) {
    const rows = await sequelize.query<Record<string, unknown>>(
      `
    SELECT
${SECURITY_PROFILE_HISTORY_SELECT}
    FROM dbo.hwy_member_security_profile_history sp WITH (NOLOCK)
    WHERE sp.member_id = :memberId
    ORDER BY sp.created_on DESC
    `,
      { replacements: { memberId }, type: QueryTypes.SELECT },
    );
    await attachSecurityProfileTitles(rows, queryLang);
    return rows as HwyMemberDossierSecurityProfileRow[];
  }
  const rows = await sequelize.query<Record<string, unknown>>(
    `
    SELECT
${SECURITY_PROFILE_SELECT}
    FROM dbo.hwy_member_security_profile sp
    WHERE sp.member_id = :memberId
    ORDER BY sp.created_at DESC
    `,
    { replacements: { memberId }, type: QueryTypes.SELECT },
  );
  await attachSecurityProfileTitles(rows, queryLang);
  return rows as HwyMemberDossierSecurityProfileRow[];
}

