import { QueryTypes } from 'sequelize';

import {
  HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT,
  hwyMemberFileUploadReplacesExistingRowForKind,
} from '../../../domain/hwy/hwyMemberDossierFileUploadPolicy';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { resolveHwyMemberFileKindBySlugOrId } from './hwyMemberFileKindResolve.service';

const MAX_MEMBER_FILE_BYTES = 5 * 1024 * 1024;

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

export type UpsertHwyMemberDossierFileInput = {
  memberId: string;
  fileKindCode: string;
  fileName: string;
  mime: string;
  body: Buffer;
  updatedByUserId?: number | null;
};

export async function upsertHwyMemberDossierFile(
  input: UpsertHwyMemberDossierFileInput,
): Promise<{ id: string; created: boolean }> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Member file upload requires SQL Server control plane.');
  }
  await ensureHwyDbObjects();

  const memberId = parseMemberId(input.memberId);
  const fileKindRaw = input.fileKindCode.trim();
  if (!fileKindRaw) {
    throw new Error('File kind is required.');
  }
  if (!input.body?.length) {
    throw new Error('File body is empty.');
  }
  if (input.body.length > MAX_MEMBER_FILE_BYTES) {
    throw new Error('File exceeds the maximum allowed size.');
  }

  const resolvedKind = await resolveHwyMemberFileKindBySlugOrId(fileKindRaw);
  if (!resolvedKind?.id) {
    throw new Error('File kind is invalid.');
  }
  const fileKindCode = resolvedKind.id;
  const otherKind = await resolveHwyMemberFileKindBySlugOrId(HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT);
  const replacesExistingRow = hwyMemberFileUploadReplacesExistingRowForKind({
    kindSlug: resolvedKind.shortName,
    kindSlugOrIdRaw: fileKindRaw,
    resolvedKindId: fileKindCode,
    otherAttachmentKindId: otherKind?.id ?? null,
  });

  const originalFileName = input.fileName.trim().slice(0, 512) || 'upload.bin';
  const mime = input.mime.trim().slice(0, 4000) || 'application/octet-stream';
  const sizeBytes = input.body.length;
  const updatedBy = input.updatedByUserId ?? null;

  const sequelize = getControlPlaneSequelize();
  let existingFileId: number | null = null;

  if (replacesExistingRow) {
    const existing = await sequelize.query<{ id: number | string }>(
      `
      SELECT id FROM dbo.hwy_member_files
      WHERE member_id = :memberId AND file_kind_code = :fileKindCode
      `,
      {
        replacements: { memberId, fileKindCode },
        type: QueryTypes.SELECT,
      },
    );
    const rawId = existing[0]?.id;
    if (rawId != null) {
      existingFileId = Number(rawId);
    }
  }

  const rows = await execHwyProcedure<{ id: string; created: boolean | number }>('hwy_member_file_upsert', {
    member_id: memberId,
    file_kind_code: fileKindCode,
    existing_file_id: existingFileId,
    original_file_name: originalFileName,
    mime,
    size_bytes: sizeBytes,
    content: input.body,
    updated_by: updatedBy,
  });

  const row = rows[0];
  if (!row?.id) {
    throw new Error('Could not save member file.');
  }

  const verify = await sequelize.query<{ contentLen: number | string }>(
    `SELECT DATALENGTH(content) AS contentLen FROM dbo.hwy_member_files WHERE id = :fileId`,
    { replacements: { fileId: Number(row.id) }, type: QueryTypes.SELECT },
  );
  const contentLen = Number(verify[0]?.contentLen ?? 0);
  if (contentLen !== sizeBytes) {
    throw new Error('File content was not persisted correctly.');
  }

  const created = row.created === true || row.created === 1;
  return { id: String(row.id), created };
}

export type PersistHwyMemberFileByKindSlugInput = {
  memberId: number;
  kindSlug: string;
  fileName: string;
  mime: string;
  body: Buffer;
  updatedByUserId?: number | null;
};

/** Used by self-registration submit (same member + kind upsert semantics). */
export async function persistHwyMemberFileByKindSlug(
  input: PersistHwyMemberFileByKindSlugInput,
): Promise<void> {
  if (!input.body?.length) {
    return;
  }
  await upsertHwyMemberDossierFile({
    memberId: String(input.memberId),
    fileKindCode: input.kindSlug,
    fileName: input.fileName,
    mime: input.mime,
    body: input.body,
    updatedByUserId: input.updatedByUserId,
  });
}
