import sql from 'mssql';

export type LegacyHwyBaseInformationRow = {
  id: number;
  title: string;
  viewOrder: number | null;
  isActive: boolean;
  note?: string;
  parentId?: number | null;
};

type LegacyRecord = {
  Id: number;
  Title: string | null;
  ViewOrder: number | null;
  IsActive: boolean | number | null;
  Note?: string | null;
  ParentId?: number | null;
};

const mapLegacyBaseInfoRow = (row: LegacyRecord): LegacyHwyBaseInformationRow => ({
  id: row.Id,
  title: String(row.Title ?? '').trim(),
  viewOrder: row.ViewOrder,
  isActive: row.IsActive === true || row.IsActive === 1,
  note: String(row.Note ?? '').trim() || undefined,
  parentId: row.ParentId == null ? null : Number(row.ParentId),
});

/** Children of a legacy `HWY_BaseInformation` node (e.g. provinces under 10101, districts under province id). */
export const listLegacyHwyBaseInformationByParent = async (
  parentLegacyId: number,
): Promise<LegacyHwyBaseInformationRow[]> => {
  if (!Number.isFinite(parentLegacyId) || parentLegacyId <= 0) {
    return [];
  }

  try {
    const { readLegacyConn, withLegacyReadOnlyIntent } = await import('../../../../scripts/hwy-etl/legacyConn');
    const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();

    try {
      const result = await pool
        .request()
        .input('parentId', sql.Int, parentLegacyId)
        .query(`
          SELECT Id, Title, ViewOrder, IsActive
          FROM dbo.HWY_BaseInformation WITH (NOLOCK)
          WHERE ParentId = @parentId
          ORDER BY ViewOrder, Id
        `);

      return (result.recordset as LegacyRecord[])
        .map((row) => mapLegacyBaseInfoRow({ ...row, ParentId: parentLegacyId }))
        .filter((row) => row.isActive && row.title);
    } finally {
      await pool.close();
    }
  } catch {
    return [];
  }
};

/** Single legacy `HWY_BaseInformation` row (category node or leaf). */
export const getLegacyHwyBaseInformationById = async (
  legacyId: number,
): Promise<LegacyHwyBaseInformationRow | null> => {
  if (!Number.isFinite(legacyId) || legacyId <= 0) {
    return null;
  }

  const queryById = async (includeNote: boolean): Promise<LegacyHwyBaseInformationRow | null> => {
    const { readLegacyConn, withLegacyReadOnlyIntent } = await import('../../../../scripts/hwy-etl/legacyConn');
    const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();

    try {
      const result = await pool
        .request()
        .input('id', sql.Int, legacyId)
        .query(includeNote
          ? `
          SELECT Id, Title, ViewOrder, IsActive, Note, ParentId
          FROM dbo.HWY_BaseInformation WITH (NOLOCK)
          WHERE Id = @id
        `
          : `
          SELECT Id, Title, ViewOrder, IsActive, ParentId
          FROM dbo.HWY_BaseInformation WITH (NOLOCK)
          WHERE Id = @id
        `);

      const row = (result.recordset as LegacyRecord[])[0];
      if (!row) {
        return null;
      }
      return mapLegacyBaseInfoRow(row);
    } finally {
      await pool.close();
    }
  };

  try {
    return await queryById(true);
  } catch {
    try {
      return await queryById(false);
    } catch {
      return null;
    }
  }
};

/** Resolve legacy `HWY_BaseInformation.Title` by primary key (district / subdistrict legacy ids). */
export const getLegacyHwyBaseInformationTitlesByIds = async (
  legacyIds: readonly number[],
): Promise<Map<number, string>> => {
  const unique = [...new Set(legacyIds.filter((id) => Number.isFinite(id) && id > 0))];
  if (unique.length === 0) {
    return new Map();
  }

  try {
    const { readLegacyConn, withLegacyReadOnlyIntent } = await import('../../../../scripts/hwy-etl/legacyConn');
    const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();

    try {
      const request = pool.request();
      const paramNames = unique.map((id, index) => {
        const name = `id${index}`;
        request.input(name, sql.Int, id);
        return `@${name}`;
      });
      const result = await request.query(`
          SELECT Id, Title
          FROM dbo.HWY_BaseInformation WITH (NOLOCK)
          WHERE Id IN (${paramNames.join(', ')})
        `);

      const map = new Map<number, string>();
      for (const row of result.recordset as LegacyRecord[]) {
        const title = String(row.Title ?? '').trim();
        if (title) {
          map.set(row.Id, title);
        }
      }
      return map;
    } finally {
      await pool.close();
    }
  } catch {
    return new Map();
  }
};
