import { applyFieldEnrichments } from '../../services/data-api/dataApiFieldEnrichment';
import { resolvePublishedEdgeModel, resolveFieldEnrichmentDeps } from '../../services/data-api/dataApiPublishedRuntime';
import type { EdgeApiFieldEnrichment } from '../../../shared/api/contracts/data-api';
import { enrichHwyMemberDirectoryListRows } from './hwyMemberDirectoryDetailDisplay';
import { enrichHwyGenderCodeTitles, enrichHwyNakhebinListRows } from './hwyNakhebinRegionDisplay';
import { resolveHwyMemberDirectoryQueryLang } from './hwyMemberDirectoryQueryLang';
import type { HwyFamilyHouseholdQuery } from '../../../domain/hwy/hwyFamilyHousehold';
import { resolveHwyElectoralProvinceTitle } from '../../../shared/lib/hwyMemberDirectoryPathDisplay';
import { attachHwyHouseholdMemberAvatarUrl } from './hwyFamilyHouseholdMemberAvatar';
import { attachMemberTasjilStateTitles } from './hwyFamilyHouseholdMemberCardStatus';
import { attachHouseholdMemberGenderFromLinkedNakhebin } from './hwyFamilyHouseholdMemberGender';
import {
  buildHouseholdMemberDirectoryWhere,
  collectNakhebinLinkedMemberIds,
} from './hwyFamilyHouseholdMemberQuery';

const MEMBER_DIRECTORY_ENRICHMENTS: EdgeApiFieldEnrichment[] = [
  {
    id: 'hwy_enrich_membership_status',
    sourceField: 'membershipStatusCode',
    kind: 'base_info_title',
    joinTableSource: 'base_info',
    langSource: 'fixed:ar',
    attachedFields: [
      { sourceColumn: 'title', outputField: 'membershipStatusCodeTitle' },
      { sourceColumn: 'ui_color', outputField: 'membershipStatusCodeTitleUiColor' },
    ],
  },
  {
    id: 'hwy_enrich_member_gender',
    sourceField: 'genderCode',
    kind: 'base_info_title',
    joinTableSource: 'base_info',
    langSource: 'fixed:ar',
    attachedFields: [
      { sourceColumn: 'title', outputField: 'genderCodeTitle' },
    ],
  },
  {
    id: 'hwy_enrich_tasjil_state',
    sourceField: 'nakhebinJoinTasjilStateCode',
    kind: 'base_info_title',
    joinTableSource: 'base_info',
    langSource: 'fixed:ar',
    attachedFields: [
      { sourceColumn: 'title', outputField: 'nakhebinJoinTasjilStateCodeTitle' },
      { sourceColumn: 'ui_color', outputField: 'nakhebinJoinTasjilStateCodeTitleUiColor' },
    ],
  },
];

const MEMBER_DIRECTORY_MODEL_ID = 'em_5f3a30c99bb3420e';
const NAKHEBIN_MODEL_ID = 'em_784d292c4bbcac55';
const HOUSEHOLD_ROW_LIMIT = 500;

const normalizeRegionId = (value: string): string => value.trim();

const normalizeFamilyCode = (value: string): string => value.trim();

export type HwyFamilyHouseholdMemberRow = Record<string, unknown>;
export type HwyFamilyHouseholdNakhebinRow = Record<string, unknown>;

export type HwyFamilyHouseholdPayload = {
  members: HwyFamilyHouseholdMemberRow[];
  nakhebin: HwyFamilyHouseholdNakhebinRow[];
  meta: {
    regionId: string;
    familyCode: string;
    lang: string;
    provinceTitle: string;
  };
};

export async function loadHwyFamilyHousehold(
  query: HwyFamilyHouseholdQuery,
  req: { query?: Record<string, unknown> },
): Promise<HwyFamilyHouseholdPayload> {
  const regionId = normalizeRegionId(query.regionId);
  const familyCode = normalizeFamilyCode(query.familyCode);
  const lang = resolveHwyMemberDirectoryQueryLang(req.query ?? {}, req);

  const { Model: VwHwyMembers } = await resolvePublishedEdgeModel(MEMBER_DIRECTORY_MODEL_ID);
  const { Model: HwyNakhebin } = await resolvePublishedEdgeModel(NAKHEBIN_MODEL_ID);

  const nakhebinRows = await HwyNakhebin.findAll({
    where: {
      regionId,
      familyCode,
    },
    limit: HOUSEHOLD_ROW_LIMIT,
    order: [['id', 'ASC']],
    raw: true,
  });

  const nakhebinPlain = nakhebinRows as Record<string, unknown>[];
  await enrichHwyNakhebinListRows(nakhebinPlain, lang);

  const linkedMemberIds = collectNakhebinLinkedMemberIds(nakhebinPlain);
  const memberRows = await VwHwyMembers.findAll({
    where: buildHouseholdMemberDirectoryWhere(regionId, familyCode, linkedMemberIds),
    limit: HOUSEHOLD_ROW_LIMIT,
    order: [['displayFullName', 'ASC']],
    raw: true,
  });

  const memberEnrichmentDeps = await resolveFieldEnrichmentDeps(MEMBER_DIRECTORY_MODEL_ID, {
    enrichments: MEMBER_DIRECTORY_ENRICHMENTS,
  });
  const enrichedMembers = await applyFieldEnrichments(
    memberRows as Record<string, unknown>[],
    MEMBER_DIRECTORY_ENRICHMENTS,
    lang,
    memberEnrichmentDeps,
  );
  await enrichHwyGenderCodeTitles(enrichedMembers, lang);
  await enrichHwyMemberDirectoryListRows(enrichedMembers, lang, {
    includeElectoralDivisionPath: true,
    includeListMembershipOnRegistrationFallback: false,
    includeMemberInstitutesSummary: false,
  });

  attachHouseholdMemberGenderFromLinkedNakhebin(enrichedMembers, nakhebinPlain);
  await enrichHwyGenderCodeTitles(enrichedMembers, lang);
  await attachMemberTasjilStateTitles(enrichedMembers, lang);
  for (const member of enrichedMembers) {
    attachHwyHouseholdMemberAvatarUrl(member);
  }

  const provinceTitle = nakhebinPlain
    .map((row) => resolveHwyElectoralProvinceTitle(row.electoralDivisionPath))
    .find((title) => title.length > 0) ?? '';

  return {
    members: enrichedMembers,
    nakhebin: nakhebinPlain,
    meta: { regionId, familyCode, lang, provinceTitle },
  };
}
