import { isHwyMehaniProfessionalBaseInfoPlaceholderShortName } from '../../../domain/hwy/hwyMehaniProfessionalBaseInfoPlaceholders';
import { prisma } from '../users/prismaHelpers';

const activeLeafCache = new Map<string, boolean>();

export const resetHwyMemberMehaniBaseInfoCodeCacheForTests = (): void => {
  activeLeafCache.clear();
};

/** Returns the code when it references an active, non-placeholder `base_info` leaf; otherwise null. */
export const resolveActiveHwyBaseInfoLeafCode = async (
  code: string | null | undefined,
): Promise<string | null> => {
  const trimmed = String(code ?? '').trim();
  if (!trimmed) {
    return null;
  }
  const cached = activeLeafCache.get(trimmed);
  if (cached === true) {
    return trimmed;
  }
  if (cached === false) {
    return null;
  }
  const row = await prisma().baseInfo.findFirst({
    where: { id: trimmed },
    select: { id: true, isActive: true, shortName: true },
  });
  const active = Boolean(
    row?.isActive
    && row.id
    && !isHwyMehaniProfessionalBaseInfoPlaceholderShortName(row.shortName),
  );
  activeLeafCache.set(trimmed, active);
  return active ? trimmed : null;
};
