import { apiGet, resolveApiMutationErrorMessage } from '../../shared/api/client';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';

/** Legacy HWY_BaseInformation parent for phone request reject reasons. */
export const HWY_MEMBER_PHONE_REJECT_REASON_LEGACY_PARENT_ID = 215155;

export type HwyMemberPhoneRejectReasonOption = {
  value: string;
  label: string;
};

export function buildHwyMemberPhoneRejectReasonsPath(cultureOrLang?: string | null): string {
  const lang = resolveHwyMemberDirectoryDetailLang(cultureOrLang);
  return `/api/hwy/phone-requests/reject-reasons?lang=${encodeURIComponent(lang)}`;
}

export async function fetchHwyMemberPhoneRejectReasonOptions(
  cultureOrLang?: string | null,
): Promise<HwyMemberPhoneRejectReasonOption[]> {
  const response = await apiGet<{ success?: boolean; data?: HwyMemberPhoneRejectReasonOption[]; message?: string }>(
    buildHwyMemberPhoneRejectReasonsPath(cultureOrLang),
  );
  const { data: body, response: httpResponse } = response;
  if (!httpResponse.ok || body?.success === false) {
    throw new Error(resolveApiMutationErrorMessage(body, 'Could not load reject reasons.'));
  }
  return body?.data ?? [];
}
