import {
  applyGenderIdentityMaskToMemberRow,
  applyInstituteOwnershipPhoneMaskToMemberRow,
  resolveHwyMemberDirectoryIdentityFieldPolicy,
  type HwyMemberDirectoryIdentityFieldPolicy,
  type HwyMemberIdentityMaskViewer,
} from '../../../domain/hwy/hwyMemberIdentityFieldMask';
import {
  loadHwyMemberIdentityInstitutePhoneMap,
  readMemberIdentityInstitutePhoneContext,
} from './hwyMemberIdentityFieldMaskInstitutes';
import type { Sequelize } from 'sequelize';
import { resolveHwyMemberIdentityMaskViewerForRequest } from './hwyMemberIdentityFieldMaskContext';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

const readMemberGender = (row: Record<string, unknown>): unknown => (
  row.genderCode ?? row.gender_code ?? row.GenderId ?? row.genderId
);

export async function applyHwyMemberIdentityFieldMasksToRows(
  sequelize: Sequelize,
  rows: Record<string, unknown>[],
  viewerOrSession: HwyMemberIdentityMaskViewer | SessionScopeSnapshot | null | undefined,
  options?: { attachIdentityFieldPolicy?: boolean },
): Promise<void> {
  if (rows.length === 0) {
    return;
  }
  const viewer = viewerOrSession && 'genderLimitLegacyIds' in viewerOrSession
    ? viewerOrSession
    : await resolveHwyMemberIdentityMaskViewerForRequest(
      viewerOrSession as SessionScopeSnapshot | null | undefined,
      sequelize,
    );

  const memberIds = rows.map((row) => row.id ?? row.memberId).filter(Boolean);
  const instituteMap = await loadHwyMemberIdentityInstitutePhoneMap(sequelize, memberIds);

  for (const row of rows) {
    const genderMasked = applyGenderIdentityMaskToMemberRow(row, viewer);
    const institute = readMemberIdentityInstitutePhoneContext(instituteMap, row.id ?? row.memberId);
    const institutePhoneMasked = applyInstituteOwnershipPhoneMaskToMemberRow(row, viewer, institute);
    if (institute.orgsMembershipSummary) {
      row.orgsMembershipSummary = institute.orgsMembershipSummary;
    }

    if (options?.attachIdentityFieldPolicy) {
      const policy: HwyMemberDirectoryIdentityFieldPolicy = resolveHwyMemberDirectoryIdentityFieldPolicy({
        viewer,
        memberGenderCode: readMemberGender(row),
        genderMasked,
        institutePhoneMasked,
      });
      row.identityFieldPolicy = policy;
    }
  }
}
