import { QueryTypes } from 'sequelize';

import {
  HWY_ACTIVITY_STATUS_REGISTER,
  HWY_COURSE_STATUS_DRAFT,
} from '../../../domain/hwy/hwyCoursesActivitiesCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyCoursesActivitiesSchema } from './ensureHwyCoursesActivitiesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy courses/activities attendance write requires SQL Server control plane.');
  }
  await ensureHwyCoursesActivitiesSchema();
  await ensureHwyDbObjects();
};

const resolveActorUsername = async (userId: number | null): Promise<string> => {
  if (userId == null || !Number.isFinite(userId) || userId <= 0) {
    return 'admin';
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ username: string }>(
    `SELECT username FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  return trim(rows[0]?.username) || 'admin';
};

const allocateNextAttendanceId = async (
  table: 'hwy_activity_attendances' | 'hwy_course_attendances',
): Promise<number> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ next_id: number | string }>(
    `SELECT ISNULL(MAX(id), 0) + 1 AS next_id FROM dbo.${table} WITH (UPDLOCK, HOLDLOCK)`,
    { type: QueryTypes.SELECT },
  );
  const nextId = Number(rows[0]?.next_id);
  if (!Number.isFinite(nextId) || nextId <= 0) {
    throw new Error('Could not allocate an attendance id.');
  }
  return nextId;
};

export async function addHwyActivityAdminAttendance(input: {
  activityIdRaw: string;
  memberIdRaw: string;
  actorUserId: number | null;
}): Promise<void> {
  await assertSqlServer();
  const activityId = Number(trim(input.activityIdRaw));
  const memberId = Number(trim(input.memberIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Activity not found.');
  }
  if (!Number.isFinite(memberId) || memberId <= 0) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  const activityRows = await sequelize.query<{ status_code: string | null }>(
    `SELECT status_code FROM dbo.hwy_activities WHERE id = :activityId`,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  if (!activityRows.length) {
    throw new Error('Activity not found.');
  }
  if (trim(activityRows[0].status_code) !== HWY_ACTIVITY_STATUS_REGISTER) {
    throw new Error('Attendees can only be changed on draft activities.');
  }
  const actor = await resolveActorUsername(input.actorUserId);
  const id = await allocateNextAttendanceId('hwy_activity_attendances');
  try {
    await execHwyProcedure('hwy_activity_attendance_add', {
      activity_id: activityId,
      member_id: memberId,
      attendance_id: id,
      legacy_created_by: actor,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('55001')) {
      throw new Error('Member is already on this activity.');
    }
    if (message.includes('55000')) {
      throw new Error('Member not found.');
    }
    throw error;
  }
}

export async function removeHwyActivityAdminAttendance(input: {
  activityIdRaw: string;
  attendanceIdRaw: string;
}): Promise<void> {
  await assertSqlServer();
  const activityId = Number(trim(input.activityIdRaw));
  const attendanceId = Number(trim(input.attendanceIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0 || !Number.isFinite(attendanceId) || attendanceId <= 0) {
    throw new Error('Attendance not found.');
  }
  const sequelize = getControlPlaneSequelize();
  const activityRows = await sequelize.query<{ status_code: string | null }>(
    `SELECT status_code FROM dbo.hwy_activities WHERE id = :activityId`,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  if (!activityRows.length) {
    throw new Error('Activity not found.');
  }
  if (trim(activityRows[0].status_code) !== HWY_ACTIVITY_STATUS_REGISTER) {
    throw new Error('Attendees can only be changed on draft activities.');
  }
  await execHwyProcedure('hwy_activity_attendance_remove', {
    activity_id: activityId,
    attendance_id: attendanceId,
  });
}

export async function addHwyCourseAdminAttendance(input: {
  courseIdRaw: string;
  memberIdRaw: string;
  note?: string | null;
  actorUserId: number | null;
}): Promise<void> {
  await assertSqlServer();
  const courseId = Number(trim(input.courseIdRaw));
  const memberId = Number(trim(input.memberIdRaw));
  if (!Number.isFinite(courseId) || courseId <= 0) {
    throw new Error('Course not found.');
  }
  if (!Number.isFinite(memberId) || memberId <= 0) {
    throw new Error('Member id is required.');
  }
  const sequelize = getControlPlaneSequelize();
  const courseRows = await sequelize.query<{ status_code: string | null }>(
    `SELECT status_code FROM dbo.hwy_courses WHERE id = :courseId`,
    { replacements: { courseId }, type: QueryTypes.SELECT },
  );
  if (!courseRows.length) {
    throw new Error('Course not found.');
  }
  if (trim(courseRows[0].status_code) !== HWY_COURSE_STATUS_DRAFT) {
    throw new Error('Attendees can only be changed on draft courses.');
  }
  const actor = await resolveActorUsername(input.actorUserId);
  const id = await allocateNextAttendanceId('hwy_course_attendances');
  const note = trim(input.note).slice(0, 512) || null;
  try {
    await execHwyProcedure('hwy_course_attendance_add', {
      course_id: courseId,
      member_id: memberId,
      attendance_id: id,
      note,
      legacy_created_by: actor,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : '';
    if (message.includes('55101')) {
      throw new Error('Member is already on this course.');
    }
    if (message.includes('55100')) {
      throw new Error('Member not found.');
    }
    throw error;
  }
}

