import type { HwyMemberImageFixThumbKindSlug } from './hwyMemberImageFixCatalog';

/** Legacy `V_List` queue modes on `HWY_Members_List_Imagefix` (`''` = no queue filter). */
export type HwyMemberImageFixListQueue = '' | 'todo' | 'tadghigh';

/** Legacy per-document filter (`IsNull` | `IsNotNull` | `Approved` | `NotNullNotApproved`). */
export type HwyMemberImageFixDocFilterMode =
  | ''
  | 'isNull'
  | 'isNotNull'
  | 'approved'
  | 'notNullNotApproved';

export type HwyMemberImageFixRoledFilter = '' | 'hasRole' | 'noRole';

export type HwyMemberImageFixNakhebCardTypeFilter = '' | 'isNull' | 'isNotNull';

export type HwyMemberImageFixListFilterState = {
  queue: HwyMemberImageFixListQueue;
  roled: HwyMemberImageFixRoledFilter;
  nakhebCardType: HwyMemberImageFixNakhebCardTypeFilter;
  doc: Record<HwyMemberImageFixDocFilterKey, HwyMemberImageFixDocFilterMode>;
};

/** Legacy HTML control ids (row 2 order, RTL). */
export type HwyMemberImageFixDocFilterKey =
  | 'picture'
  | 'nationalCardFront'
  | 'nationalCardBehind'
  | 'nakhebCardFront'
  | 'maskanCard'
  | 'oath';

export const HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS: HwyMemberImageFixDocFilterKey[] = [
  'picture',
  'nationalCardFront',
  'nationalCardBehind',
  'nakhebCardFront',
  'maskanCard',
  'oath',
];

export const HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEY_TO_KIND_SLUG: Record<
  HwyMemberImageFixDocFilterKey,
  HwyMemberImageFixThumbKindSlug
> = {
  picture: 'personal_photo',
  nationalCardFront: 'national_card_front',
  nationalCardBehind: 'national_card_back',
  nakhebCardFront: 'voter_card_front',
  maskanCard: 'residence_card_front',
  oath: 'oath_document',
};

const parseHwyMemberImageFixListQueueValue = (
  raw: unknown,
  fallback: HwyMemberImageFixListQueue,
): HwyMemberImageFixListQueue => {
  if (raw === undefined || raw === null) {
    return fallback;
  }
  const queueRaw = String(raw).trim();
  if (queueRaw === 'tadghigh') {
    return 'tadghigh';
  }
  if (queueRaw === 'todo') {
    return 'todo';
  }
  if (queueRaw === 'all' || queueRaw === '') {
    return '';
  }
  return fallback;
};

export const createDefaultHwyMemberImageFixListFilters = (): HwyMemberImageFixListFilterState => ({
  queue: 'todo',
  roled: '',
  nakhebCardType: '',
  doc: {
    picture: '',
    nationalCardFront: '',
    nationalCardBehind: '',
    nakhebCardFront: '',
    maskanCard: '',
    oath: '',
  },
});

/** Simple search toolbar — no legacy V_* filters applied. */
export const createHwyMemberImageFixListFiltersForSimpleSearch = (): HwyMemberImageFixListFilterState => ({
  queue: '',
  roled: '',
  nakhebCardType: '',
  doc: {
    picture: '',
    nationalCardFront: '',
    nationalCardBehind: '',
    nakhebCardFront: '',
    maskanCard: '',
    oath: '',
  },
});

export const readHwyMemberImageFixListFiltersFromQuery = (
  query: Record<string, unknown>,
): HwyMemberImageFixListFilterState => {
  const defaults = createDefaultHwyMemberImageFixListFilters();
  const queue = Object.prototype.hasOwnProperty.call(query, 'imageFixQueue')
    ? parseHwyMemberImageFixListQueueValue(query.imageFixQueue, defaults.queue)
    : defaults.queue;

  const roledRaw = String(query.imageFixRoled ?? '').trim();
  const roled = roledRaw === 'hasRole' || roledRaw === 'noRole' ? roledRaw : '';

  const nakhebRaw = String(query.imageFixNakhebCardType ?? '').trim();
  const nakhebCardType = nakhebRaw === 'isNull' || nakhebRaw === 'isNotNull' ? nakhebRaw : '';

  const doc = { ...defaults.doc };
  for (const key of HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS) {
    const raw = String(query[`imageFixDoc_${key}`] ?? '').trim();
    if (
      raw === 'isNull'
      || raw === 'isNotNull'
      || raw === 'approved'
      || raw === 'notNullNotApproved'
    ) {
      doc[key] = raw;
    }
  }

  return { queue, roled, nakhebCardType, doc };
};

export const hwyMemberImageFixListFiltersAffectQuery = (
  filters: HwyMemberImageFixListFilterState,
): boolean => {
  if (filters.queue === 'tadghigh' || filters.queue === 'todo') {
    return true;
  }
  if (filters.roled || filters.nakhebCardType) {
    return true;
  }
  return HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS.some((key) => Boolean(filters.doc[key]));
};

export const readHwyMemberImageFixListFiltersFromStore = (
  store: Record<string, unknown> | null | undefined,
): HwyMemberImageFixListFilterState => {
  const defaults = createDefaultHwyMemberImageFixListFilters();
  const toolbar = store?.gridToolbar;
  if (!toolbar || typeof toolbar !== 'object') {
    return defaults;
  }
  const imageFix = (toolbar as Record<string, unknown>).imageFix;
  if (!imageFix || typeof imageFix !== 'object') {
    return defaults;
  }
  const record = imageFix as Record<string, unknown>;
  const queue = parseHwyMemberImageFixListQueueValue(record.queue, defaults.queue);
  const roledRaw = String(record.roled ?? '').trim();
  const roled = roledRaw === 'hasRole' || roledRaw === 'noRole' ? roledRaw : '';
  const nakhebRaw = String(record.nakhebCardType ?? '').trim();
  const nakhebCardType = nakhebRaw === 'isNull' || nakhebRaw === 'isNotNull' ? nakhebRaw : '';
  const docRecord = record.doc && typeof record.doc === 'object'
    ? record.doc as Record<string, unknown>
    : {};
  const doc = { ...defaults.doc };
  for (const key of HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS) {
    const raw = String(docRecord[key] ?? '').trim();
    if (
      raw === 'isNull'
      || raw === 'isNotNull'
      || raw === 'approved'
      || raw === 'notNullNotApproved'
    ) {
      doc[key] = raw;
    }
  }
  return { queue, roled, nakhebCardType, doc };
};

export const buildHwyMemberImageFixListFilterStorePatches = (
  filters: HwyMemberImageFixListFilterState,
): Record<string, unknown> => {
  const patches: Record<string, unknown> = {
    'gridToolbar.imageFix.queue': filters.queue,
    'gridToolbar.imageFix.roled': filters.roled,
    'gridToolbar.imageFix.nakhebCardType': filters.nakhebCardType,
  };
  for (const key of HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS) {
    patches[`gridToolbar.imageFix.doc.${key}`] = filters.doc[key] ?? '';
  }
  return patches;
};

export const patchHwyMemberImageFixListFiltersToStore = (
  patch: (path: string, value: unknown) => void,
  filters: HwyMemberImageFixListFilterState,
): void => {
  for (const [path, value] of Object.entries(buildHwyMemberImageFixListFilterStorePatches(filters))) {
    patch(path, value);
  }
};

export const appendHwyMemberImageFixListFiltersToSearchParams = (
  params: URLSearchParams,
  filters: HwyMemberImageFixListFilterState,
): void => {
  if (filters.queue) {
    params.set('imageFixQueue', filters.queue);
  }
  if (filters.roled) {
    params.set('imageFixRoled', filters.roled);
  }
  if (filters.nakhebCardType) {
    params.set('imageFixNakhebCardType', filters.nakhebCardType);
  }
  for (const key of HWY_MEMBER_IMAGE_FIX_DOC_FILTER_KEYS) {
    const mode = filters.doc[key];
    if (mode) {
      params.set(`imageFixDoc_${key}`, mode);
    }
  }
};
