import { prisma } from '../users/prismaHelpers';

export const HWY_BASE_INFO_ROOT_ID = '220';

const findChildByShortName = async (parentId: string, shortName: string) => (
  prisma().baseInfo.findFirst({
    where: { parentId, shortName },
    select: { id: true, title: true },
  })
);

const findCategoryByTitle = async (title: string) => (
  prisma().baseInfo.findFirst({
    where: {
      parentId: HWY_BASE_INFO_ROOT_ID,
      title,
    },
    select: { id: true },
  })
);

export const resolveHwyBaseInfoItemId = async (
  categoryTitle: string,
  shortName: string,
): Promise<string> => {
  const category = await findCategoryByTitle(categoryTitle);
  if (!category) {
    throw new Error(`Hawiety Base Info category "${categoryTitle}" is missing. Run hwy:phase1 seed.`);
  }
  const item = await findChildByShortName(category.id, shortName);
  if (!item) {
    throw new Error(`Hawiety Base Info item "${shortName}" is missing under "${categoryTitle}".`);
  }
  return item.id;
};

export const resolveHwyBaseInfoItemTitle = async (baseInfoId: string): Promise<string | null> => {
  const row = await prisma().baseInfo.findUnique({
    where: { id: baseInfoId },
    select: { title: true },
  });
  return row?.title?.trim() ?? null;
};
