const resolveHwyMemberSegmentNavDescriptionEn = (def: HwyMemberSegmentListDefinition): string => {
  const override = HWY_MEMBER_SEGMENT_NAV_DESCRIPTION_EN_BY_LEGACY_CODE[def.legacyCode];
  if (override) {
    return override;
  }

  switch (def.scope.type) {
    case 'active_institute': {
      const segment = instituteSegmentFromTitleEn(def.titleEn, 'Registered —');
      return `Search active registered members in ${segment} and open dossiers.`;
    }
    case 'pending_local_institute': {
      const segment = instituteSegmentFromTitleEn(def.titleEn, 'Pending local —');
      return `Review applications awaiting local verification for ${segment} — approve, reject, or open the dossier.`;
    }
    case 'membership_status':
      switch (def.scope.status) {
        case 'pending_call_center':
          return 'Review new membership applications — approve, reject, or open the dossier.';
        case 'pending_local':
          return 'Complete local verification — approve, reject, return to applicant, or open the dossier.';
        case 'active':
          return 'Browse active registered members and open dossiers.';
        case 'rejected_call_center':
          return 'Review call-center rejections — restore to queue or browse decision history.';
        case 'rejected_local':
        case 'rejected_local_verification':
          return 'Review local verification rejections — restore to queue or browse decision history.';
        default:
          break;
      }
      break;
    case 'under_18_active':
      return 'Scout registry for active members under 18 — search and open dossiers.';
    case 'university_outside_hemam':
      return 'University students registered outside Hemam — search and open dossiers.';
    case 'registration_image_fix_todo':
      return 'Review registration uploads and approve or reject profile photos.';
    case 'directory_unrestricted':
      return 'Search the full member directory and open dossiers — every membership status.';
    default:
      break;
  }

  return `Search members on this list and open dossiers — ${def.titleEn}.`;
};

const resolveHwyMemberSegmentNavDescriptionIq = (def: HwyMemberSegmentListDefinition): string => {
  const override = HWY_MEMBER_SEGMENT_NAV_DESCRIPTION_IQ_BY_LEGACY_CODE[def.legacyCode];
  if (override) {
    return override;
  }

  const titleIq = HWY_MEMBER_SEGMENT_NAV_TITLE_IQ_BY_LEGACY_CODE[def.legacyCode] ?? def.titleEn;

  switch (def.scope.type) {
    case 'active_institute': {
      const segment = instituteSegmentFromTitleIq(titleIq, 'اعضاء ');
      return `ابحث في منتظمي ${segment} النشطين وافتح ملفاتهم.`;
    }
    case 'pending_local_institute': {
      const segment = instituteSegmentFromTitleIq(titleIq, 'طلبات ');
      return `راجع طلبات ${segment} بانتظار التوثيق المحلي — اعتماد، رفض، أو فتح الملف.`;
    }
    case 'membership_status':
      switch (def.scope.status) {
        case 'pending_call_center':
          return 'راجع طلبات العضوية الجديدة — اعتماد، رفض، أو فتح الملف.';
        case 'pending_local':
          return 'أكمل التوثيق المحلي — اعتماد، رفض، إرجاع للمتقدّم، أو فتح الملف.';
        case 'active':
          return 'تصفّح المنتظمين النشطين وافتح ملفاتهم.';
        case 'rejected_call_center':
          return `راجع مرفوضات مركز الاتصال — إعادة للطابور أو استعراض قرارات ${titleIq.replace(/^مرفوضات /, '')}.`;
        case 'rejected_local':
        case 'rejected_local_verification':
          return `راجع مرفوضات التوثيق المحلي — إعادة للطابور أو استعراض قرارات ${titleIq.replace(/^مرفوضات /, '')}.`;
        default:
          break;
      }
      break;
    case 'under_18_active':
      return 'سجل الكشافة للمنتظمين دون سن الثامنة عشرة — بحث وفتح الملفات.';
    case 'university_outside_hemam':
      return 'طلاب جامعيون خارج مؤسسة همم — بحث وفتح الملفات.';
    case 'registration_image_fix_todo':
      return 'راجع مرفقات التسجيل واعتمد أو ارفض صور الهوية.';
    case 'directory_unrestricted':
      return 'ابحث في دليل العضوية وافتح الملفات — كل حالات العضو.';
    default:
      break;
  }

  return `ابحث في القائمة وافتح ملفات الأعضاء — ${titleIq}.`;
};

export const buildHwyMemberSegmentNavCultureKeysEn = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const def of HWY_MEMBER_SEGMENT_LIST_DEFINITIONS) {
    keys[`nav.${def.pageName}`] = def.titleEn;
    keys[`nav.${def.pageName}.description`] = resolveHwyMemberSegmentNavDescriptionEn(def);
  }
  return keys;
};

export const buildHwyMemberSegmentNavCultureKeysIq = (): Record<string, string> => {
  const keys: Record<string, string> = {};
  for (const def of HWY_MEMBER_SEGMENT_LIST_DEFINITIONS) {
    const titleIq = HWY_MEMBER_SEGMENT_NAV_TITLE_IQ_BY_LEGACY_CODE[def.legacyCode] ?? def.titleEn;
    keys[`nav.${def.pageName}`] = titleIq;
    keys[`nav.${def.pageName}.description`] = resolveHwyMemberSegmentNavDescriptionIq(def);
  }
  return keys;
};
