import { QueryTypes, type Sequelize } from 'sequelize';
import type { HwyMemberDirectoryPatchInput } from '../../../domain/hwy/hwyMemberDirectoryPatch';

const trimOptional = (value: string | null | undefined, max = 4000): string | null => {
  if (value == null) {
    return null;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  return trimmed.length > max ? trimmed.slice(0, max) : trimmed;
};

/**
 * vw_hwy_members prefers base_user_profiles / base_users over hwy_members columns
 * (see scripts/hwy-phase1/db/install/vw_hwy_members.sqlserver.sql). Member-only UPDATE
 * does not change list/detail read models when user_id is linked.
 */
export async function syncHwyMemberDirectoryPatchToLinkedAccount(
  sequelize: Sequelize,
  userId: number,
  patch: HwyMemberDirectoryPatchInput,
  updatedAt: Date,
): Promise<void> {
  const profileSets: string[] = ['updated_at = :updated_at'];
  const profileReplacements: Record<string, unknown> = {
    user_id: userId,
    updated_at: updatedAt,
  };

  const assignProfile = (
    patchKey: keyof HwyMemberDirectoryPatchInput,
    column: string,
    replKey: string,
    max = 500,
  ) => {
    if (!Object.prototype.hasOwnProperty.call(patch, patchKey)) {
      return;
    }
    profileSets.push(`${column} = :${replKey}`);
    profileReplacements[replKey] = trimOptional(patch[patchKey] as string | null | undefined, max);
  };

  assignProfile('firstname', 'firstname', 'firstname');
  assignProfile('lastname', 'lastname', 'lastname');
  assignProfile('fathername', 'fathername', 'fathername');
  assignProfile('grandfathername', 'grandfathername', 'grandfathername');
  assignProfile('nickname', 'nickname', 'nickname');
  assignProfile('birthYear', 'birth_year', 'birth_year', 4000);
  assignProfile('birthMonth', 'birth_month', 'birth_month', 4000);
  assignProfile('birthDay', 'birth_day', 'birth_day', 4000);
  assignProfile('genderCode', 'gender_code', 'gender_code', 1000);
  assignProfile('phone1', 'phone', 'phone');

  if (profileSets.length > 1) {
    await sequelize.query(
      `UPDATE dbo.base_user_profiles SET ${profileSets.join(', ')} WHERE user_id = :user_id`,
      { replacements: profileReplacements, type: QueryTypes.UPDATE },
    );
  }

  if (Object.prototype.hasOwnProperty.call(patch, 'email')) {
    await sequelize.query(
      `UPDATE dbo.base_users SET email = :email, updated_at = :updated_at WHERE id = :user_id`,
      {
        replacements: {
          user_id: userId,
          email: trimOptional(patch.email, 500),
          updated_at: updatedAt,
        },
        type: QueryTypes.UPDATE,
      },
    );
  }
}

export async function readHwyMemberLinkedUserId(
  sequelize: Sequelize,
  memberId: number,
): Promise<number | null> {
  const rows = await sequelize.query<{ user_id: number | null }>(
    `SELECT user_id FROM dbo.hwy_members WHERE id = :id`,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  const raw = rows[0]?.user_id;
  if (raw == null) {
    return null;
  }
  const userId = Number(raw);
  return Number.isFinite(userId) && userId > 0 ? userId : null;
}
