import type {
  HwyMeetingDefinition,
  HwyMeetingInstanceListResult,
  HwyMeetingInstanceRow,
} from '../../../domain/hwy/hwyMeetings';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { hwyLegacyImportParityReady } from './hwyLegacyImportParityState.service';
import {
  queryLegacyMeetingDefinitions,
  queryLegacyMeetingInstancesCount,
  queryLegacyMeetingInstancesList,
} from './hwyLegacyParityRead.service';
import { assertHwyMeetingsManagementAccess } from './hwyMeetingsAccess.service';

const DEFAULT_PAGE_SIZE = 25;
const MAX_PAGE_SIZE = 100;

const trim = (v: string | null | undefined): string => String(v ?? '').trim();

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy meetings requires SQL Server control plane.');
  }
};

const clampPage = (page: number | undefined, pageSize: number | undefined) => {
  const safePageSize = Math.min(MAX_PAGE_SIZE, Math.max(1, pageSize ?? DEFAULT_PAGE_SIZE));
  const safePage = Math.max(1, page ?? 1);
  return { page: safePage, pageSize: safePageSize, offset: (safePage - 1) * safePageSize };
};

const assertAccess = async (roleNames: readonly string[]): Promise<void> => {
  await assertHwyMeetingsManagementAccess(roleNames);
};

export const listHwyMeetingDefinitions = async (
  roleNames: readonly string[],
): Promise<HwyMeetingDefinition[]> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  if (!(await hwyLegacyImportParityReady())) {
    const legacyRows = await queryLegacyMeetingDefinitions();
    return legacyRows.map((row) => ({
      id: trim(row.id as string),
      title: trim(row.title as string),
      viewOrder: row.viewOrder != null ? Number(row.viewOrder) : null,
    }));
  }
  const rows = await execHwyProcedure<{ id: string; title: string; viewOrder: number | null }>(
    'hwy_meetings_list_definitions',
    {},
  );
  return rows.map((row) => ({
    id: trim(row.id),
    title: trim(row.title),
    viewOrder: row.viewOrder != null ? Number(row.viewOrder) : null,
  }));
};

const mapInstance = (row: Record<string, unknown>): HwyMeetingInstanceRow => ({
  id: trim(row.id as string),
  meetingId: row.meetingId ? trim(row.meetingId as string) : null,
  memberId: row.memberId ? trim(row.memberId as string) : null,
  createdOn: row.createdOn ? trim(row.createdOn as string) : null,
  eventDate: row.eventDate ? trim(row.eventDate as string) : null,
  title: row.title ? trim(row.title as string) : null,
  meetingTitle: row.meetingTitle ? trim(row.meetingTitle as string) : null,
  username: row.username ? trim(row.username as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
  hazerinCount: Number(row.hazerinCount ?? 0),
  membersYetCount: Number(row.membersYetCount ?? 0),
  membersNotCount: Number(row.membersNotCount ?? 0),
});

export const listHwyMeetingInstances = async (
  input: { meetingId?: string; username?: string; page?: number; pageSize?: number },
  roleNames: readonly string[],
): Promise<HwyMeetingInstanceListResult> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  const { page, pageSize, offset } = clampPage(input.page, input.pageSize);
  const meetingId = trim(input.meetingId) ? Number(trim(input.meetingId)) : null;
  const procBase = {
    meeting_id: meetingId,
    username: trim(input.username) || null,
  };
  if (!(await hwyLegacyImportParityReady())) {
    const total = await queryLegacyMeetingInstancesCount(meetingId, procBase.username);
    const legacyRows = await queryLegacyMeetingInstancesList(
      meetingId,
      procBase.username,
      offset,
      pageSize,
    );
    return {
      total,
      page,
      pageSize,
      rows: legacyRows.map(mapInstance),
      parityDataSource: 'legacy-read' as const,
    };
  }
  const countRows = await execHwyProcedure<{ total: number | string }>(
    'hwy_meetings_instances_count',
    procBase,
  );
  const total = Number(countRows[0]?.total ?? 0);
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_meetings_instances_list', {
    ...procBase,
    offset,
    page_size: pageSize,
  });
  return {
    total,
    page,
    pageSize,
    rows: rows.map(mapInstance),
    parityDataSource: 'edge' as const,
  };
};

export const removeHwyMeetingInstance = async (
  instanceId: string,
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  await execHwyProcedure('hwy_meetings_remove_instance', {
    instance_id: Number(trim(instanceId)),
  });
};

export const addHwyMeetingInstance = async (
  input: { meetingId: string; instanceDate: string; actorUsername?: string | null },
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  const meetingId = Number(trim(input.meetingId));
  const instanceDate = trim(input.instanceDate);
  if (!meetingId || !instanceDate) {
    throw new Error('meetingId and instanceDate are required.');
  }
  await execHwyProcedure('hwy_meetings_add_instance', {
    meeting_id: meetingId,
    instance_date: instanceDate,
    actor: trim(input.actorUsername) || null,
  });
};

