export type HwyMeetingMemberRow = {
  id: string;
  meetingId: string | null;
  memberId: string | null;
  isMemberYet: boolean | null;
  isMemberYetUpdatedOn: string | null;
  username: string | null;
  firstName: string | null;
  fatherName: string | null;
  lastName: string | null;
};

export type HwyMeetingAttendanceRow = {
  id: string;
  instanceId: string;
  meetingId: string | null;
  memberId: string | null;
  username: string | null;
  firstName: string | null;
  fatherName: string | null;
  lastName: string | null;
  isMemberYet: boolean | null;
  present: boolean;
};

const mapMeetingMember = (row: Record<string, unknown>): HwyMeetingMemberRow => ({
  id: trim(row.id as string),
  meetingId: row.meetingId ? trim(row.meetingId as string) : null,
  memberId: row.memberId ? trim(row.memberId as string) : null,
  isMemberYet: row.isMemberYet === true || row.isMemberYet === 1,
  isMemberYetUpdatedOn: row.isMemberYetUpdatedOn ? trim(row.isMemberYetUpdatedOn as string) : null,
  username: row.username ? trim(row.username as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
});

const mapAttendance = (row: Record<string, unknown>): HwyMeetingAttendanceRow => ({
  id: trim(row.id as string),
  instanceId: trim(row.instanceId as string),
  meetingId: row.meetingId ? trim(row.meetingId as string) : null,
  memberId: row.memberId ? trim(row.memberId as string) : null,
  username: row.username ? trim(row.username as string) : null,
  firstName: row.firstName ? trim(row.firstName as string) : null,
  fatherName: row.fatherName ? trim(row.fatherName as string) : null,
  lastName: row.lastName ? trim(row.lastName as string) : null,
  isMemberYet: row.isMemberYet === true || row.isMemberYet === 1,
  present: row.present === true || row.present === 1,
});

export const listHwyMeetingMembers = async (
  meetingId: string,
  roleNames: readonly string[],
): Promise<HwyMeetingMemberRow[]> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  const id = Number(trim(meetingId));
  if (!id) throw new Error('meetingId is required.');
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_meetings_members_list', {
    meeting_id: id,
  });
  return rows.map(mapMeetingMember);
};

export const addHwyMeetingMember = async (
  input: { meetingId: string; memberId?: string; username?: string; actorUsername?: string | null },
  roleNames: readonly string[],
): Promise<void> => {
  assertSqlServer();
  await assertAccess(roleNames);
  await ensureHwyDbObjects();
  const meetingId = Number(trim(input.meetingId));
  if (!meetingId) throw new Error('meetingId is required.');
  const memberId = trim(input.memberId) ? Number(trim(input.memberId)) : null;
  const username = trim(input.username) || null;
  if (memberId == null && !username) {
    throw new Error('memberId or username is required.');
  }
  await execHwyProcedure('hwy_meetings_members_add', {
    meeting_id: meetingId,
    member_id: memberId,
    username,
    actor: trim(input.actorUsername) || null,
  });
};

