import sql from 'mssql';

import type { HwyMemberTarghinAdminMemberFace } from '../../../domain/hwy/hwyMemberTarghinAdmin';
import { buildHwyMemberPersonDisplayNameFromParts } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getLegacyHwyReadPool } from './legacyHwyReadPool';

const LEGACY_BATCH = 40;

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

type LegacyMemberRow = {
  UserName: string;
  FirstName: string | null;
  FatherName: string | null;
  GrandFatherName: string | null;
  LastName: string | null;
  Phone1: string | null;
};

const mapLegacyRowToFace = (row: LegacyMemberRow): HwyMemberTarghinAdminMemberFace => {
  const username = trim(row.UserName);
  const displayFullName = buildHwyMemberPersonDisplayNameFromParts({
    firstname: row.FirstName,
    fathername: row.FatherName,
    grandfathername: row.GrandFatherName,
    lastname: row.LastName,
  }) || username;
  return {
    id: username ? `legacy-membership-${username}` : '',
    username: username || null,
    displayFullName,
    genderCode: null,
    avatarUrl: null,
    phone: trim(row.Phone1) || null,
    electoralDivisionPath: null,
  };
};

/** Read-only legacy HWY member faces keyed by membership username (`UserName`). */
export async function loadLegacyHwyMemberFacesByUsernames(
  usernames: readonly string[],
): Promise<Map<string, HwyMemberTarghinAdminMemberFace>> {
  const keys = [...new Set(usernames.map(trim).filter(Boolean))];
  const result = new Map<string, HwyMemberTarghinAdminMemberFace>();
  if (!keys.length) {
    return result;
  }

  try {
    const pool = await getLegacyHwyReadPool();

    for (let offset = 0; offset < keys.length; offset += LEGACY_BATCH) {
      const batch = keys.slice(offset, offset + LEGACY_BATCH);
      const request = pool.request();
      const params = batch.map((username, index) => {
        const param = `u${index}`;
        request.input(param, sql.NVarChar, username);
        return `@${param}`;
      });
      const queryResult = await request.query(`
        SELECT UserName, FirstName, FatherName, GrandFatherName, LastName, Phone1
        FROM dbo.HWY_Members WITH (NOLOCK)
        WHERE UserName IN (${params.join(', ')})
      `);
      for (const row of queryResult.recordset as LegacyMemberRow[]) {
        const username = trim(row.UserName);
        if (!username) {
          continue;
        }
        result.set(username, mapLegacyRowToFace(row));
      }
    }
  } catch {
    return result;
  }

  return result;
}
