import {
  apiGet,
  apiPost,
  resolveApiMutationErrorMessage,
  type ApiRequestResult,
} from '../../shared/api/client';
import type { HwyMemberPhoneRequestKind, HwyMemberPhoneSlot } from './hwyMemberPhoneRequestRules';

export type HwyMemberPhoneAdminQueue = 'pending' | 'approved' | 'rejected' | 'all';

export const HWY_MEMBER_PHONE_ADMIN_QUEUES: HwyMemberPhoneAdminQueue[] = [
  'pending',
  'approved',
  'rejected',
  'all',
];

export function parseHwyMemberPhoneAdminQueue(raw: string | null | undefined): HwyMemberPhoneAdminQueue {
  const value = String(raw ?? '').trim() as HwyMemberPhoneAdminQueue;
  if ((HWY_MEMBER_PHONE_ADMIN_QUEUES as string[]).includes(value)) {
    return value;
  }
  return 'pending';
}

export type HwyMemberPhoneRequestMemberFace = {
  id: string;
  username: string | null;
  displayFullName: string | null;
  phone1: string | null;
  phone2: string | null;
  genderCode?: string | null;
  avatarUrl: string | null;
};

export type HwyMemberPhoneAdminRow = {
  id: string;
  requestKind: HwyMemberPhoneRequestKind;
  memberId: string;
  member: HwyMemberPhoneRequestMemberFace;
  phoneSlot: HwyMemberPhoneSlot | null;
  oldPhone: string | null;
  newPhone: string | null;
  phone1Before: string | null;
  phone2Before: string | null;
  requestNote: string | null;
  requestAt: string;
  requestByUsername: string | null;
  finalResult: boolean | null;
  finalReasonCode: string | null;
  finalReasonTitle?: string | null;
  finalNote: string | null;
  finalAt: string | null;
  finalByUsername: string | null;
};

export type HwyMemberPhoneAdminListResult = {
  rows: HwyMemberPhoneAdminRow[];
  total: number;
  page: number;
  pageSize: number;
};

export type HwyMemberPhonePendingState = {
  changeBySlot: {
    1: HwyMemberPhoneAdminRow | null;
    2: HwyMemberPhoneAdminRow | null;
  };
  swap: HwyMemberPhoneAdminRow | null;
};

export type HwyMemberPhoneDecisionKind = 'approve' | 'reject';

export const HWY_MEMBER_PHONE_REQUESTS_ADMIN_PAGE_KEY = 'hwy-phone-requests';

type HwyPhoneApiEnvelope<T> = {
  success?: boolean;
  data?: T;
  message?: string;
};

const readHwyPhoneApiPayload = <T>(
  result: ApiRequestResult<HwyPhoneApiEnvelope<T>>,
  fallback: string,
): T => {
  const { data: body, response } = result;
  if (!response.ok || body?.success === false) {
    throw new Error(resolveApiMutationErrorMessage(body, fallback));
  }
  if (body?.data === undefined) {
    throw new Error(fallback);
  }
  return body.data;
};

const readOptionalHwyPhoneApiPayload = <T>(
  result: ApiRequestResult<HwyPhoneApiEnvelope<T>>,
  fallback: string,
  whenMissing: T,
): T => {
  const { data: body, response } = result;
  if (!response.ok || body?.success === false) {
    throw new Error(resolveApiMutationErrorMessage(body, fallback));
  }
  return body?.data ?? whenMissing;
};

export function buildHwyMemberPhonePendingPath(memberId: string): string {
  return `/api/hwy/member-directory/${encodeURIComponent(memberId.trim())}/phone-requests/pending`;
}

export function buildHwyMemberPhoneHistoryPath(memberId: string): string {
  return `/api/hwy/member-directory/${encodeURIComponent(memberId.trim())}/phone-requests/history`;
}

export function buildHwyMemberPhoneChangeCreatePath(memberId: string): string {
  return `/api/hwy/member-directory/${encodeURIComponent(memberId.trim())}/phone-requests/change`;
}

export function buildHwyMemberPhoneSwapCreatePath(memberId: string): string {
  return `/api/hwy/member-directory/${encodeURIComponent(memberId.trim())}/phone-requests/swap`;
}

export function buildHwyMemberPhoneAdminListPath(query: {
  queue?: HwyMemberPhoneAdminQueue;
  search?: string;
  page?: number;
  pageSize?: number;
  lang?: string;
}): string {
  const params = new URLSearchParams();
  if (query.queue) {
    params.set('queue', query.queue);
  }
  if (query.search?.trim()) {
    params.set('search', query.search.trim());
  }
  if (query.page) {
    params.set('page', String(query.page));
  }
  if (query.pageSize) {
    params.set('pageSize', String(query.pageSize));
  }
  if (query.lang) {
    params.set('lang', query.lang);
  }
  const qs = params.toString();
  return `/api/hwy/phone-requests${qs ? `?${qs}` : ''}`;
}

export function buildHwyMemberPhoneDecisionPath(requestId: string): string {
  return `/api/hwy/phone-requests/${encodeURIComponent(requestId.trim())}/decision`;
}

export async function fetchHwyMemberPhonePending(memberId: string): Promise<HwyMemberPhonePendingState> {
  const empty: HwyMemberPhonePendingState = { changeBySlot: { 1: null, 2: null }, swap: null };
  const response = await apiGet<HwyPhoneApiEnvelope<HwyMemberPhonePendingState>>(
    buildHwyMemberPhonePendingPath(memberId),
  );
  const data = readOptionalHwyPhoneApiPayload(
    response,
    'Could not load pending phone requests.',
    empty,
  );
  return {
    changeBySlot: {
      1: data.changeBySlot?.[1] ?? null,
      2: data.changeBySlot?.[2] ?? null,
    },
    swap: data.swap ?? null,
  };
}

export async function fetchHwyMemberPhoneHistory(memberId: string): Promise<HwyMemberPhoneAdminRow[]> {
  const response = await apiGet<HwyPhoneApiEnvelope<HwyMemberPhoneAdminRow[]>>(
    buildHwyMemberPhoneHistoryPath(memberId),
  );
  return readOptionalHwyPhoneApiPayload(response, 'Could not load phone request history.', []);
}

export async function createHwyMemberPhoneChangeRequest(
  memberId: string,
  input: { phoneSlot: HwyMemberPhoneSlot; newPhone: string; requestNote?: string },
): Promise<{ appliedDirectly: boolean }> {
  try {
    const response = await apiPost<HwyPhoneApiEnvelope<{ appliedDirectly?: boolean }>>(
      buildHwyMemberPhoneChangeCreatePath(memberId),
      input,
    );
    const data = readHwyPhoneApiPayload(response, 'Could not submit phone change request.');
    return { appliedDirectly: Boolean(data.appliedDirectly) };
  } catch (error) {
    throw error instanceof Error
      ? error
      : new Error(resolveApiMutationErrorMessage(error, 'Could not submit phone change request.'));
  }
}

export async function createHwyMemberPhoneSwapRequest(
  memberId: string,
  input?: { requestNote?: string },
): Promise<{ appliedDirectly: boolean }> {
  try {
    const response = await apiPost<HwyPhoneApiEnvelope<{ appliedDirectly?: boolean }>>(
      buildHwyMemberPhoneSwapCreatePath(memberId),
      input ?? {},
    );
    const data = readHwyPhoneApiPayload(response, 'Could not submit phone swap request.');
    return { appliedDirectly: Boolean(data.appliedDirectly) };
  } catch (error) {
    throw error instanceof Error
      ? error
      : new Error(resolveApiMutationErrorMessage(error, 'Could not submit phone swap request.'));
  }
}

export async function listHwyMemberPhoneAdmin(
  query: {
    queue: HwyMemberPhoneAdminQueue;
    search?: string;
    page?: number;
    pageSize?: number;
  },
  cultureOrLang?: string | null,
): Promise<HwyMemberPhoneAdminListResult> {
  const response = await apiGet<HwyPhoneApiEnvelope<HwyMemberPhoneAdminListResult>>(
    buildHwyMemberPhoneAdminListPath({
      ...query,
      lang: cultureOrLang ?? undefined,
    }),
  );
  return readOptionalHwyPhoneApiPayload(response, 'Could not load phone requests.', {
    rows: [],
    total: 0,
    page: 1,
    pageSize: 25,
  });
}

export async function decideHwyMemberPhoneRequest(input: {
  requestId: string;
  decision: HwyMemberPhoneDecisionKind;
  finalReasonCode?: string;
  finalNote: string;
}): Promise<void> {
  try {
    const response = await apiPost<HwyPhoneApiEnvelope<unknown>>(
      buildHwyMemberPhoneDecisionPath(input.requestId),
      input,
    );
    const { data: body, response: httpResponse } = response;
    if (!httpResponse.ok || body?.success === false) {
      throw new Error(resolveApiMutationErrorMessage(body, 'Could not save phone request decision.'));
    }
  } catch (error) {
    throw error instanceof Error
      ? error
      : new Error(resolveApiMutationErrorMessage(error, 'Could not save phone request decision.'));
  }
}
