import type { HwyEmployeesListResult, HwyEmployeesListRow } from '../../../domain/hwy/hwyEmployeesList';
import type { HwyEmployeesListSearchInput } from '../../../domain/hwy/hwyEmployeesListFilterMapping';
import { buildHwyEmployeesListProcParams } from '../../../domain/hwy/hwyEmployeesListFilterMapping';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { assertHwyEmployeesListAccess } from './hwyEmployeesListAccess.service';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { hwyLegacyImportParityReady } from './hwyLegacyImportParityState.service';
import {
  queryLegacyEmployeesList,
  queryLegacyEmployeesListCount,
} from './hwyEmployeesListLegacyRead.service';
import { enrichHwyMemberDirectoryListRows } from './hwyMemberDirectoryDetailDisplay';
import { invalidateHwyMemberDirectoryListCache } from './hwyMemberDirectoryListCache';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { QueryTypes } from 'sequelize';

const trim = (value: unknown): string => String(value ?? '').trim();

const HWY_EMPLOYEES_LIST_SCOPE = 'HWY_Members_List_AlMontadhemin';

const assertSqlServer = (): void => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy employees list requires SQL Server control plane.');
  }
};

const mapRow = (row: Record<string, unknown>): HwyEmployeesListRow => ({
  id: trim(row.id),
  username: row.username ? trim(row.username) : null,
  userId: row.userId ? trim(row.userId) : null,
  firstName: row.firstName ? trim(row.firstName) : null,
  fatherName: row.fatherName ? trim(row.fatherName) : null,
  grandFatherName: row.grandFatherName ? trim(row.grandFatherName) : null,
  lastName: row.lastName ? trim(row.lastName) : null,
  displayFullName: row.displayFullName ? trim(row.displayFullName) : null,
  avatarUrl: row.avatarUrl ? trim(row.avatarUrl) : null,
  birthYear: row.birthYear != null ? trim(row.birthYear) : null,
  genderCode: row.genderCode ? trim(row.genderCode) : null,
  trackingCode: row.trackingCode ? trim(row.trackingCode) : null,
  phone1: row.phone1 ? trim(row.phone1) : null,
  genderId: row.genderId ? trim(row.genderId) : null,
  genderIdTitle: row.genderIdTitle ? trim(row.genderIdTitle) : null,
  statFieldsCompleted: row.statFieldsCompleted != null ? Number(row.statFieldsCompleted) : null,
  statOath: row.statOath ? trim(row.statOath) : null,
  masooliatRoleOn: row.masooliatRoleOn ? trim(String(row.masooliatRoleOn)) : null,
  rolesLimits: row.rolesLimits ? String(row.rolesLimits) : null,
  areasLimits: row.areasLimits ? String(row.areasLimits) : null,
  genderLimits: row.genderLimits ? String(row.genderLimits) : null,
  orgLimits: row.orgLimits ? String(row.orgLimits) : null,
  uniLimits: row.uniLimits ? String(row.uniLimits) : null,
  jobL1Limits: row.jobL1Limits ? String(row.jobL1Limits) : null,
  ettehadLimits: row.ettehadLimits ? String(row.ettehadLimits) : null,
  nakhebJoinProvinceName: row.nakhebJoinProvinceName ? trim(row.nakhebJoinProvinceName) : null,
  nakhebJoinCircleName: row.nakhebJoinCircleName ? trim(row.nakhebJoinCircleName) : null,
  nakhebJoinTamvinName: row.nakhebJoinTamvinName ? trim(row.nakhebJoinTamvinName) : null,
  nakhebJoinEghteraName: row.nakhebJoinEghteraName ? trim(row.nakhebJoinEghteraName) : null,
  educationLevelIdTitle: row.educationLevelIdTitle ? trim(row.educationLevelIdTitle) : null,
  jobTypeIdTitle: row.jobTypeIdTitle ? trim(row.jobTypeIdTitle) : null,
  membershipOn: row.membershipOn ? trim(row.membershipOn) : null,
  updatedOn: row.updatedOn ? trim(row.updatedOn) : null,
});

const finalizeRows = async (
  rows: HwyEmployeesListRow[],
  queryLang: string,
): Promise<HwyEmployeesListRow[]> => {
  if (rows.length === 0) return rows;
  const asRecords = rows as Record<string, unknown>[];
  await enrichHwyMemberDirectoryListRows(asRecords, queryLang, {
    listScopeLegacy: HWY_EMPLOYEES_LIST_SCOPE,
    includeListFaceAvatarsFromRegistration: true,
    includeListMembershipOnRegistrationFallback: true,
  });
  return asRecords as HwyEmployeesListRow[];
};

export const listHwyEmployees = async (
  input: HwyEmployeesListSearchInput,
  roleNames: readonly string[],
  queryLang: string,
): Promise<HwyEmployeesListResult> => {
  await assertHwyEmployeesListAccess(roleNames);
  const params = buildHwyEmployeesListProcParams(input);
  const page = Math.max(1, input.page ?? 1);
  const pageSize = params.page_size;

  if (!hwyLegacyImportParityReady()) {
    const total = await queryLegacyEmployeesListCount(input);
    const rawRows = await queryLegacyEmployeesList(input);
    const rows = await finalizeRows(rawRows.map(mapRow), queryLang);
    return { total, page, pageSize, rows, parityDataSource: 'legacy-read' };
  }

  assertSqlServer();
  await ensureHwyDbObjects();

  const countRows = await execHwyProcedure<{ total: number }>('hwy_employees_list_count', {
    username: params.username,
    phone: params.phone,
    first_name: params.first_name,
    father_name: params.father_name,
    grandfather_name: params.grandfather_name,
    last_name: params.last_name,
    gender_id: params.gender_id,
    role_id: params.role_id,
    v_province_id: params.v_province_id,
    v_circle_id: params.v_circle_id,
    v_tamvin_id: params.v_tamvin_id,
    v_has_ghasam: params.v_has_ghasam,
    v_area_has_problem: params.v_area_has_problem,
    v_fields_completed: params.v_fields_completed,
  });
  const total = Number(countRows[0]?.total ?? 0);

  const listRows = await execHwyProcedure<Record<string, unknown>>('hwy_employees_list', {
    username: params.username,
    phone: params.phone,
    first_name: params.first_name,
    father_name: params.father_name,
    grandfather_name: params.grandfather_name,
    last_name: params.last_name,
    gender_id: params.gender_id,
    role_id: params.role_id,
    v_province_id: params.v_province_id,
    v_circle_id: params.v_circle_id,
    v_tamvin_id: params.v_tamvin_id,
    v_has_ghasam: params.v_has_ghasam,
    v_area_has_problem: params.v_area_has_problem,
    v_fields_completed: params.v_fields_completed,
    offset: params.offset,
    page_size: params.page_size,
  });

  const rows = await finalizeRows(listRows.map(mapRow), queryLang);
  return { total, page, pageSize, rows, parityDataSource: 'edge' };
};

export const removeHwyEmployeePlatformRoles = async (
  memberId: string,
  roleNames: readonly string[],
): Promise<void> => {
  await assertHwyEmployeesListAccess(roleNames);
  assertSqlServer();
  const sequelize = getControlPlaneSequelize();
  const memberRows = await sequelize.query<{ user_id: number | null }>(
    `SELECT TOP 1 user_id FROM dbo.hwy_members WITH (NOLOCK) WHERE id = :memberId`,
    { replacements: { memberId: trim(memberId) }, type: QueryTypes.SELECT },
  );
  const userId = memberRows[0]?.user_id;
  if (!userId) {
    throw new Error('Member user link was not found.');
  }

  await sequelize.query(
    `DELETE FROM dbo.base_user_roles WHERE user_id = :userId AND role_name LIKE 'HWY_R[_]%' ESCAPE '\\'`,
    { replacements: { userId }, type: QueryTypes.RAW },
  );

  await sequelize.query(
    `IF OBJECT_ID(N'dbo.AppEnd_Users_R_Roles', N'U') IS NOT NULL
     DELETE URR FROM dbo.AppEnd_Users_R_Roles URR
     WHERE URR.UserId = :userId`,
    { replacements: { userId }, type: QueryTypes.RAW },
  );

  await invalidateHwyMemberDirectoryListCache();
};
