import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { resolveHwyBaseInfoItemId } from './hwyBaseInfoRuntime';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { QueryTypes } from 'sequelize';
import { isValidHwySelfRegistrationInstituteCode } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationFieldValidation';

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const resolveInstituteIdByCode = async (instituteCode: string): Promise<number> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `
    SELECT TOP (1) i.id
    FROM dbo.hwy_institutes i
    WHERE LOWER(i.code) = LOWER(:code) AND i.is_active = 1
    `,
    { replacements: { code: instituteCode }, type: QueryTypes.SELECT },
  );
  const id = rows[0]?.id;
  if (id == null || !Number.isFinite(Number(id))) {
    throw new Error('Institute was not found or is inactive.');
  }
  return Number(id);
};

export const assignHwyMemberInstituteByAdmin = async (input: {
  memberIdRaw: string;
  instituteCode: string;
  actorUserId: number | null;
}): Promise<{ memberId: number; instituteId: number }> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Admin institute assign requires SQL Server control plane.');
  }

  const instituteCode = input.instituteCode.trim();
  if (!isValidHwySelfRegistrationInstituteCode(instituteCode)) {
    throw new Error('Institute code must be three digits.');
  }

  const memberId = parseMemberId(input.memberIdRaw);
  const instituteId = await resolveInstituteIdByCode(instituteCode);

  await ensureHwyDbObjects();

  const statusCode = await resolveHwyBaseInfoItemId('Institute Membership Status', 'active');
  const joinPathCode = await resolveHwyBaseInfoItemId('Institute Join Path', 'admin');
  const now = new Date();

  await execHwyProcedure('hwy_member_institute_admin_assign', {
    member_id: memberId,
    institute_id: instituteId,
    status_code: statusCode,
    join_path_code: joinPathCode,
    actor_user_id: input.actorUserId,
    created_at: now,
    updated_at: now,
  });

  await execHwyProcedure('hwy_member_stat_recalc_moassesat_count', {
    member_id: memberId,
  });

  return { memberId, instituteId };
};
