import type { HwyMemberTarghinRequestReasonOption } from '../../../domain/hwy/hwyMemberTarghinRequestReasons';
import {
  HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID,
  mapTarghinReasonNoteToSemanticFields,
} from '../../../domain/hwy/hwyMemberTarghinRequestReasons';
import { mapBaseInfoRowsForCulture, toViewOrderNumber, type BaseInfoDbRow } from '../base-info/baseInfoListMapping';
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { prisma } from '../users/prismaHelpers';
import { resolveHwyMemberDirectoryDetailLang } from '../../../domain/hwy/hwyMemberDirectoryDetail';
import type { LegacyHwyBaseInformationRow } from './hwyLegacyBaseInformationReader';
import {
  listLegacyHwyMemberTarghinRequestReasonRows,
  listStaticHwyMemberTarghinRequestReasonRows,
  syncHwyMemberTarghinRequestReasonsFromLegacy,
} from './hwyMemberTarghinRequestReasonsLegacySync';

const BASE_INFO_ROW_SELECT = {
  id: true,
  parentId: true,
  title: true,
  shortName: true,
  note: true,
  metadata: true,
  value: true,
  isActive: true,
  viewOrder: true,
  uiColor: true,
  uiHtml: true,
} as const;

const mapLegacyTarghinReasonRowsToOptions = (
  legacyRows: LegacyHwyBaseInformationRow[],
): HwyMemberTarghinRequestReasonOption[] => (
  [...legacyRows]
    .sort((a, b) => {
      const orderA = a.viewOrder ?? a.id;
      const orderB = b.viewOrder ?? b.id;
      if (orderA !== orderB) {
        return orderA - orderB;
      }
      return a.id - b.id;
    })
    .map((row) => {
      const value = String(row.id);
      const label = row.title.trim() || value;
      const semantic = mapTarghinReasonNoteToSemanticFields(row.note ?? null, null);
      return {
        value,
        label,
        ...semantic,
      };
    })
    .filter((row) => row.value && row.label)
);

const mapPlatformTarghinReasonRowsToOptions = async (
  rows: BaseInfoDbRow[],
  cultureId: string,
): Promise<HwyMemberTarghinRequestReasonOption[]> => {
  const metadataById = new Map(
    rows.map((row) => [String(row.id ?? ''), String(row.metadata ?? '')]),
  );

  const mapped = await mapBaseInfoRowsForCulture(rows as BaseInfoDbRow[], cultureId, (row, context) => ({
    viewOrder: toViewOrderNumber(row.viewOrder),
    label: context.label,
    id: row.id,
    note: context.resolvedNote,
  }));

  return mapped
    .map((row) => {
      const value = String(row.id ?? '').trim();
      const label = String(row.label ?? '').trim() || value;
      const semantic = mapTarghinReasonNoteToSemanticFields(
        typeof row.note === 'string' ? row.note : null,
        metadataById.get(value) || null,
      );
      return {
        value,
        label,
        ...semantic,
      };
    })
    .filter((row) => row.value && row.label)
    .sort((a, b) => a.label.localeCompare(b.label, 'ar'));
};

const resolveTarghinReasonSourceRows = async (): Promise<LegacyHwyBaseInformationRow[]> => {
  const legacyRows = await listLegacyHwyMemberTarghinRequestReasonRows();
  if (legacyRows.length > 0) {
    return legacyRows;
  }
  return listStaticHwyMemberTarghinRequestReasonRows();
};

export async function listHwyMemberTarghinRequestReasonOptions(
  cultureOrLang?: string | null,
): Promise<HwyMemberTarghinRequestReasonOption[]> {
  const queryLang = resolveHwyMemberDirectoryDetailLang(cultureOrLang);
  const cultureId = resolveBaseInfoCultureId(queryLang);

  const sourceRows = await resolveTarghinReasonSourceRows();
  if (sourceRows.length > 0) {
    try {
      await syncHwyMemberTarghinRequestReasonsFromLegacy();
    } catch {
      // Picker still works from legacy/static rows; sync is for FK inserts.
    }
    return mapLegacyTarghinReasonRowsToOptions(sourceRows);
  }

  const rows = await prisma().baseInfo.findMany({
    where: {
      parentId: HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID,
      isActive: true,
    },
    orderBy: [{ viewOrder: 'asc' }, { id: 'asc' }],
    select: BASE_INFO_ROW_SELECT,
  });

  if (rows.length === 0) {
    return [];
  }

  return mapPlatformTarghinReasonRowsToOptions(rows as BaseInfoDbRow[], cultureId);
}
