/** Legacy `getBaseInformationByParent(...)` roots for institute member character (Edit_By* forms). */
export type HwyMemberInstituteCharacterVocab = {
  instituteCode: string;
  legacyBaseInfoParentId: number;
  /** Control-plane Base Info category (ETL mirror target). */
  platformCategoryTitle: string;
  /** Legacy `HWY_Members` column holding the character base_info id. */
  legacyMemberColumn: 'AshaaerCharacter' | 'NokhabCharacter' | 'ShababCharacter';
  columnLabelTranslationKey: string;
  fieldLabelTranslationKey: string;
  dialogTitleTranslationKey: string;
  emptyCellTranslationKey: string;
};

export const HWY_MEMBER_INSTITUTE_CHARACTER_VOCAB_BY_CODE: Record<string, HwyMemberInstituteCharacterVocab> = {
  ashaaer: {
    instituteCode: 'ashaaer',
    legacyBaseInfoParentId: 214955,
    platformCategoryTitle: 'Hawiety Ashaaer Institute Character',
    legacyMemberColumn: 'AshaaerCharacter',
    columnLabelTranslationKey: 'hwy.members.column.instituteCharacter.ashaaer',
    fieldLabelTranslationKey: 'hwy.listScopedEdit.field.character.ashaaer',
    dialogTitleTranslationKey: 'hwy.listScopedEdit.title.character.ashaaer',
    emptyCellTranslationKey: 'hwy.listScopedEdit.character.empty.ashaaer',
  },
  nokhab: {
    instituteCode: 'nokhab',
    legacyBaseInfoParentId: 215094,
    platformCategoryTitle: 'Hawiety Nokhab Institute Character',
    legacyMemberColumn: 'NokhabCharacter',
    columnLabelTranslationKey: 'hwy.members.column.instituteCharacter.nokhab',
    fieldLabelTranslationKey: 'hwy.listScopedEdit.field.character.nokhab',
    dialogTitleTranslationKey: 'hwy.listScopedEdit.title.character.nokhab',
    emptyCellTranslationKey: 'hwy.listScopedEdit.character.empty.nokhab',
  },
  shabab: {
    instituteCode: 'shabab',
    legacyBaseInfoParentId: 214960,
    platformCategoryTitle: 'Hawiety Shabab Institute Character',
    legacyMemberColumn: 'ShababCharacter',
    columnLabelTranslationKey: 'hwy.members.column.instituteCharacter.shabab',
    fieldLabelTranslationKey: 'hwy.listScopedEdit.field.character.shabab',
    dialogTitleTranslationKey: 'hwy.listScopedEdit.title.character.shabab',
    emptyCellTranslationKey: 'hwy.listScopedEdit.character.empty.shabab',
  },
};

export const resolveHwyMemberInstituteCharacterVocab = (
  instituteCode: string | null | undefined,
): HwyMemberInstituteCharacterVocab | null => {
  const trimmed = String(instituteCode ?? '').trim();
  if (!trimmed) {
    return null;
  }
  return HWY_MEMBER_INSTITUTE_CHARACTER_VOCAB_BY_CODE[trimmed] ?? null;
};
