import type { SelfRegistrationSubmitInput } from './selfRegistration.service';
import { submitHwySelfRegistration } from './selfRegistration.service';
import { ensureHwyRegistrationChannelStudioStaff } from './ensureHwyRegistrationChannelStudioStaff';
import { ensureHwySelfRegistrationBaseInfo } from './ensureHwySelfRegistrationBaseInfo';
import { resolveStaffCreateReferrer } from './hwyStaffMemberCreateReferrer.service';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { QueryTypes } from 'sequelize';
import { isValidHwySelfRegistrationInstituteCode } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationFieldValidation';

const trim = (value: string | null | undefined, max = 32): string | null => {
  if (value == null) return null;
  const s = value.trim();
  if (!s) return null;
  return s.length > max ? s.slice(0, max) : s;
};

const resolveInstituteIdByCode = async (instituteCode: string): Promise<number | null> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number }>(
    `
    SELECT TOP (1) i.id
    FROM dbo.hwy_institutes i
    WHERE LOWER(i.code) = LOWER(:code) AND i.is_active = 1
    `,
    { replacements: { code: instituteCode }, type: QueryTypes.SELECT },
  );
  const id = rows[0]?.id;
  return id != null && Number.isFinite(Number(id)) ? Number(id) : null;
};

export type StaffMemberCreateInput = Omit<SelfRegistrationSubmitInput, 'channel'> & {
  adminInstituteCode?: string | null;
};

export const submitHwyStaffMemberCreate = async (input: {
  actorUserId: number | null;
  body: StaffMemberCreateInput;
}) => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hawiety staff member create requires SQL Server control plane.');
  }

  await ensureHwySelfRegistrationBaseInfo();
  await ensureHwyRegistrationChannelStudioStaff();

  const relationRaw = input.body.referrerRelationId != null
    ? String(input.body.referrerRelationId).trim()
    : '';
  const referrerRelationId = relationRaw && /^\d+$/.test(relationRaw)
    ? Number(relationRaw)
    : null;

  const referrer = await resolveStaffCreateReferrer({
    actorUserId: input.actorUserId,
    referrerUsername: input.body.referrerUsername,
    referrerRelationId,
  });

  const adminInstituteCode = trim(input.body.adminInstituteCode);
  if (adminInstituteCode && !isValidHwySelfRegistrationInstituteCode(adminInstituteCode)) {
    throw new Error('Admin institute code must be three digits when provided.');
  }
  const adminInstituteId = adminInstituteCode
    ? await resolveInstituteIdByCode(adminInstituteCode)
    : null;
  if (adminInstituteCode && adminInstituteId == null) {
    throw new Error('Admin institute was not found or is inactive.');
  }

  return submitHwySelfRegistration(
    {
      ...input.body,
      channel: 'studio_staff',
      referrerUsername: referrer.referrerUsername,
      referrerRelationId: referrer.referrerRelationId != null
        ? String(referrer.referrerRelationId)
        : null,
    },
    {
      actorUserId: input.actorUserId,
      adminInstituteId,
    },
  );
};
