import { randomUUID } from 'node:crypto';
import { QueryTypes } from 'sequelize';

import type { HwyActivityWorkflowAction, HwyCourseWorkflowAction } from '../../../domain/hwy/hwyCoursesActivitiesCatalog';
import {
  HWY_ACTIVITY_STATUS_REGISTER,
  HWY_ACTIVITY_STATUS_WAITED_1,
  HWY_ACTIVITY_STATUS_FINAL,
  HWY_COURSE_STATUS_DRAFT,
  resolveHwyActivityWorkflowTargetStatus,
  resolveHwyCourseWorkflowTargetStatus,
} from '../../../domain/hwy/hwyCoursesActivitiesCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyCoursesActivitiesSchema } from './ensureHwyCoursesActivitiesSchema';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { readHwyActivityAdminDetail, readHwyCourseAdminDetail } from './hwyCoursesActivitiesAdmin.service';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hwy courses/activities workflow requires SQL Server control plane.');
  }
  await ensureHwyCoursesActivitiesSchema();
  await ensureHwyDbObjects();
};

const resolveActorUsername = async (userId: number | null): Promise<string> => {
  if (userId == null || !Number.isFinite(userId) || userId <= 0) {
    return 'admin';
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ username: string }>(
    `SELECT username FROM dbo.base_users WHERE id = :userId`,
    { replacements: { userId }, type: QueryTypes.SELECT },
  );
  return trim(rows[0]?.username) || 'admin';
};

const readActivityStatus = async (activityId: number): Promise<{
  statusCode: string | null;
  memberCount: number;
  fileCount: number;
}> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    status_code: string | null;
    member_count: number | string;
    file_count: number | string;
  }>(
    `
    SELECT
      a.status_code,
      (SELECT COUNT(*) FROM dbo.hwy_activity_attendances att WHERE att.activity_id = a.id) AS member_count,
      (SELECT COUNT(*) FROM dbo.hwy_activity_files f WHERE f.activity_id = a.id) AS file_count
    FROM dbo.hwy_activities a
    WHERE a.id = :activityId
    `,
    { replacements: { activityId }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    throw new Error('Activity not found.');
  }
  const row = rows[0];
  return {
    statusCode: trim(row.status_code) || null,
    memberCount: Number(row.member_count) || 0,
    fileCount: Number(row.file_count) || 0,
  };
};

const readCourseStatus = async (courseId: number): Promise<{ statusCode: string | null; memberCount: number }> => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{
    status_code: string | null;
    member_count: number | string;
  }>(
    `
    SELECT
      c.status_code,
      (SELECT COUNT(*) FROM dbo.hwy_course_attendances att WHERE att.course_id = c.id) AS member_count
    FROM dbo.hwy_courses c
    WHERE c.id = :courseId
    `,
    { replacements: { courseId }, type: QueryTypes.SELECT },
  );
  if (!rows.length) {
    throw new Error('Course not found.');
  }
  return {
    statusCode: trim(rows[0].status_code) || null,
    memberCount: Number(rows[0].member_count) || 0,
  };
};

const assertActivityTransition = (
  action: HwyActivityWorkflowAction,
  currentStatus: string | null,
  counts: { memberCount: number; fileCount: number },
): void => {
  const status = currentStatus ?? '';
  if (action === 'send-to-waited-1') {
    if (status !== HWY_ACTIVITY_STATUS_REGISTER) {
      throw new Error('Activity is not in registration status.');
    }
    if (counts.fileCount <= 0) {
      throw new Error('Cannot submit an activity without at least one image on file.');
    }
    if (counts.fileCount > 4) {
      throw new Error('Cannot submit an activity with more than four images.');
    }
    return;
  }
  if (action === 'send-to-waited-2') {
    if (status !== HWY_ACTIVITY_STATUS_WAITED_1) {
      throw new Error('Activity is not in initial documentation status.');
    }
    return;
  }
  if (action === 'send-to-final') {
    if (status !== HWY_ACTIVITY_STATUS_FINAL) {
      throw new Error('Activity is not in final documentation status.');
    }
    return;
  }
  if (action === 'send-to-draft') {
    if (status !== HWY_ACTIVITY_STATUS_WAITED_1 && status !== HWY_ACTIVITY_STATUS_FINAL) {
      throw new Error('Activity cannot be returned to registration from this status.');
    }
    return;
  }
  if (action === 'send-to-marfoozeh') {
    if (status !== HWY_ACTIVITY_STATUS_FINAL) {
      throw new Error('Activity cannot be rejected from this status.');
    }
    return;
  }
  if (action === 'send-to-un-marfoozeh') {
    if (status !== '211315') {
      throw new Error('Activity is not in rejected status.');
    }
  }
};

const assertCourseTransition = (
  action: HwyCourseWorkflowAction,
  currentStatus: string | null,
  memberCount: number,
): void => {
  const status = currentStatus ?? '';
  if (action === 'send-to-review') {
    if (status !== HWY_COURSE_STATUS_DRAFT) {
      throw new Error('Course is not in draft status.');
    }
    if (memberCount <= 1) {
      throw new Error('Course needs more than one attendee before sending to documentation.');
    }
    return;
  }
  if (action === 'mark-as-ok' || action === 'send-to-draft' || action === 'send-to-marfoozeh') {
    if (status !== '215115') {
      throw new Error('Course is not in documentation review status.');
    }
    return;
  }
  if (action === 'send-to-un-marfoozeh') {
    if (status !== '215117') {
      throw new Error('Course is not in rejected status.');
    }
  }
};

export async function applyHwyActivityWorkflowAction(input: {
  activityIdRaw: string;
  action: HwyActivityWorkflowAction;
  note?: string | null;
  actorUserId: number | null;
  queryLang?: string;
}): Promise<Awaited<ReturnType<typeof readHwyActivityAdminDetail>>> {
  await assertSqlServer();
  const activityId = Number(trim(input.activityIdRaw));
  if (!Number.isFinite(activityId) || activityId <= 0) {
    throw new Error('Activity not found.');
  }
  const snapshot = await readActivityStatus(activityId);
  assertActivityTransition(input.action, snapshot.statusCode, snapshot);

  const targetStatus = resolveHwyActivityWorkflowTargetStatus(input.action);
  const note = trim(input.note).slice(0, 512);
  const actorUsername = await resolveActorUsername(input.actorUserId);
  const sequelize = getControlPlaneSequelize();
  const stepId = randomUUID();

  await execHwyProcedure('hwy_activity_apply_workflow', {
    activity_id: activityId,
    target_status_code: targetStatus,
    note: note || null,
    actor_username: actorUsername,
    step_id: stepId,
  });

  return readHwyActivityAdminDetail(String(activityId), input.queryLang ?? 'iq');
}

export async function applyHwyCourseWorkflowAction(input: {
  courseIdRaw: string;
  action: HwyCourseWorkflowAction;
  note?: string | null;
  actorUserId: number | null;
  queryLang?: string;
}): Promise<Awaited<ReturnType<typeof readHwyCourseAdminDetail>>> {
  await assertSqlServer();
  const courseId = Number(trim(input.courseIdRaw));
  if (!Number.isFinite(courseId) || courseId <= 0) {
    throw new Error('Course not found.');
  }
  const snapshot = await readCourseStatus(courseId);
  assertCourseTransition(input.action, snapshot.statusCode, snapshot.memberCount);

  const targetStatus = resolveHwyCourseWorkflowTargetStatus(input.action);
  const note = trim(input.note).slice(0, 1000);
  const actorUsername = await resolveActorUsername(input.actorUserId);
  const sequelize = getControlPlaneSequelize();
  const stepId = randomUUID();

  await execHwyProcedure('hwy_course_apply_workflow', {
    course_id: courseId,
    target_status_code: targetStatus,
    note: note || null,
    actor_username: actorUsername,
    step_id: stepId,
  });

  return readHwyCourseAdminDetail(String(courseId), input.queryLang ?? 'iq');
}
