import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { resolveHwyGeoResponsibilityAvatarUrl } from '../../../domain/hwy/hwyGeoResponsibilityMemberDisplay';
import type { HwyMemberListFace } from '../../../domain/hwy/hwyMemberListFace';

const trim = (value: string | null | undefined): string => String(value ?? '').trim();

export const mapHwyMemberListFaceFromVmFields = (input: {
  id: string | number | null | undefined;
  username?: string | null;
  displayFullName?: string | null;
  genderCode?: string | null;
  avatarUrl?: string | null;
  userId?: number | string | null;
  hasProfileImage?: boolean | number | null;
  phone?: string | null;
  electoralDivisionPath?: string | null;
}): HwyMemberListFace | null => {
  const id = trim(input.id != null ? String(input.id) : '');
  if (!id) {
    return null;
  }
  const userId = input.userId != null ? Number(input.userId) : null;
  return {
    id,
    username: trim(input.username) || null,
    displayFullName: formatHwyMemberPersonDisplayName(trim(input.displayFullName)) || null,
    genderCode: trim(input.genderCode) || null,
    avatarUrl: resolveHwyGeoResponsibilityAvatarUrl({
      avatarUrl: trim(input.avatarUrl) || null,
      userId: Number.isFinite(userId) ? userId : null,
      hasProfileImage: input.hasProfileImage === true || input.hasProfileImage === 1,
    }),
    phone: trim(input.phone) || null,
    electoralDivisionPath: trim(input.electoralDivisionPath) || null,
  };
};
