/**
 * Hawiety package Base Info catalog (opt-in). Not part of controlPlaneSeed.
 */

export type HwyBaseInfoItemSeed = {
  title: string;
  shortName: string;
  lucideIcon?: string;
  viewOrder: number;
  value: number;
  /** Platform `is_active`; defaults true. Tasjil states mirror legacy `IsActive`. */
  isActive?: boolean;
};

export type HwyBaseInfoCategorySeed = {
  title: string;
  viewOrder: number;
  value: number;
  items: HwyBaseInfoItemSeed[];
};

const item = (
  title: string,
  shortName: string,
  viewOrder: number,
  lucideIcon?: string,
  isActive = true,
): HwyBaseInfoItemSeed => ({
  title,
  shortName,
  viewOrder,
  value: viewOrder,
  lucideIcon,
  isActive,
});

