import sql from 'mssql';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { nextChangeHistoryCursor } from '../../../domain/hwy/hwyEtlSyncChanges';
import {
  parseSyncLookbackHours,
  resolveSyncMemberUpdatedSince,
  shouldRunSyncDomainModules,
  syncPlanInputFromRunOptions,
  type HwyEtlSyncPlanInput,
} from '../../../domain/hwy/hwyEtlSyncEnv';
import type { HwyEtlRunOptions, HwyEtlSyncPlanPayload } from '../../../shared/api/contracts/hwy/etlConsole';
import { SETTINGS_PATH } from '../../config/settingsFile';
import { ensureControlPlaneInitialized } from '../../db/controlPlaneInit';
import { readHwyEtlSyncStateSummary, resolveHwyEtlSyncStateFilePath } from '../../../domain/hwy/hwyEtlSyncStateSummary';
import { readLegacyConn, withLegacyReadOnlyIntent } from '../../../../scripts/hwy-etl/legacyConn';
import {
  filterIdsExistingInHwyMembers,
  localMaxHwyMemberId,
  queryChangeHistoryMemberIdsSince,
  queryLegacyMemberIdsUpdatedSince,
} from '../../../../scripts/hwy-etl/memberLegacyQueries';
import { legacyMaxImportMemberId } from '../../../../scripts/hwy-etl/sample-import';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../..');

export async function computeHwyEtlSyncPlan(
  runOptions: HwyEtlRunOptions = {},
): Promise<HwyEtlSyncPlanPayload> {
  const input: HwyEtlSyncPlanInput = syncPlanInputFromRunOptions(runOptions);
  const lookbackHours = parseSyncLookbackHours(input.lookbackHours);

  await ensureControlPlaneInitialized(SETTINGS_PATH, { pushSchema: false, seedSampleData: false });

  const statePath = resolveHwyEtlSyncStateFilePath(repoRoot);
  const state = readHwyEtlSyncStateSummary(repoRoot);
  const localMax = await localMaxHwyMemberId();

  if (localMax === 0) {
    return {
      ready: false,
      message: 'No local members — run Full run once before Sync changes.',
      localMaxMemberId: 0,
      lookbackHours,
      updatedSinceIso: null,
      lastChangeHistoryId: state.lastChangeHistoryId,
      legacyUpdatedMemberCount: 0,
      changeHistoryMemberCount: 0,
      targetMemberCount: 0,
      estimatedNewMembers: 0,
      runDomainModules: false,
      steps: [],
    };
  }

  const updatedSince = resolveSyncMemberUpdatedSince({
    lastLegacyMemberUpdatedOn: state.lastLegacyMemberUpdatedOn,
    lookbackHours,
    explicitUpdatedSinceIso: input.explicitUpdatedSinceIso,
    forceLookback: lookbackHours > 0,
  });

  const changeAfterId = nextChangeHistoryCursor(state.lastChangeHistoryId);

  let legacyUpdatedIds: number[] = [];
  let changeHistoryMemberIds: number[] = [];
  let legacyMaxId = localMax;
  let estimatedNewMembers = 0;

  const legacy = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();
  try {
    const scanUpdatedOn = Boolean(state.lastLegacyMemberUpdatedOn)
      || lookbackHours > 0
      || Boolean(input.explicitUpdatedSinceIso?.trim());
    if (scanUpdatedOn) {
      legacyUpdatedIds = await queryLegacyMemberIdsUpdatedSince(legacy, updatedSince, localMax);
    }
    changeHistoryMemberIds = await queryChangeHistoryMemberIdsSince(legacy, changeAfterId);
    legacyMaxId = await legacyMaxImportMemberId();
    estimatedNewMembers = Math.max(0, legacyMaxId - localMax);
  } finally {
    await legacy.close();
  }

  const changeHistoryLocal = await filterIdsExistingInHwyMembers(changeHistoryMemberIds);
  const targetMemberIds = [...new Set([...legacyUpdatedIds, ...changeHistoryLocal])].sort((a, b) => a - b);

  const env = runOptions.env ?? {};
  const runDomain = shouldRunSyncDomainModules({
    env,
    targetMemberCount: targetMemberIds.length,
    newMemberCount: estimatedNewMembers,
  });

  const steps: string[] = ['New members (if any)'];
  if (targetMemberIds.length) steps.push('Changed members (upsert)');
  steps.push('Change history (append)');
  if (targetMemberIds.length || estimatedNewMembers > 0) {
    steps.push('Member satellites (targeted)');
  } else {
    steps.push('Member satellites (skipped — no touched members)');
  }
  if (runDomain) {
    steps.push('Targhin, geo responsibility, courses, username repair');
  } else {
    steps.push('Domain modules (skipped — fast path)');
  }

  return {
    ready: true,
    message: 'Plan computed from legacy OBI (read-only) and local watermarks.',
    statePath,
    localMaxMemberId: localMax,
    lookbackHours,
    updatedSinceIso: updatedSince.toISOString(),
    lastChangeHistoryId: state.lastChangeHistoryId,
    legacyUpdatedMemberCount: legacyUpdatedIds.length,
    changeHistoryMemberCount: changeHistoryLocal.length,
    targetMemberCount: targetMemberIds.length,
    estimatedNewMembers,
    runDomainModules: runDomain,
    steps,
  };
}
