import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyMembersSelfRegistrationSchema } from './ensureHwyMembersSelfRegistrationSchema';
import { ensureHwySelfRegistrationBaseInfo } from './ensureHwySelfRegistrationBaseInfo';
import {
  resolveHwyBaseInfoItemId,
  resolveHwyBaseInfoItemTitle,
} from './hwyBaseInfoRuntime';
import {
  resolveHwySelfRegistrationEducationLevelCode,
  resolveHwySelfRegistrationJobTypeCode,
} from './hwyPublicEducationJobVocab.service';
import { resolveHwyLegacyGenderBaseInfoId } from './hwyLegacyVocabMaps';
import {
  isValidHwySelfRegistrationBirthYear,
  isValidHwySelfRegistrationEmail,
  isValidHwySelfRegistrationInstituteCode,
  isValidHwySelfRegistrationNationalId,
  isValidHwySelfRegistrationOptionalYear,
  isValidHwySelfRegistrationPhone,
  isValidHwySelfRegistrationReferrerUsername,
} from '../../../domain/hwy/selfRegistration/hwySelfRegistrationFieldValidation';
import { sanitizeHwySelfRegistrationPhoneInput } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationPhone';
import {
  isHwySelfRegistrationDistrictLegacyId,
  isHwySelfRegistrationProvinceLegacyId,
} from './hwyPublicAddressGeo.service';
import type { HwySelfRegistrationSubmitAttachment } from '../../../domain/hwy/selfRegistration/hwySelfRegistrationAttachmentFields';
import { persistHwyMemberFileByKindSlug } from './hwyMemberDossierFileUpsert.service';
