import { execHwyProcedure } from './hwyExecDbObject';
import { runHwyMemberAfterCreateHook } from './hwyMemberDomainWriteExtras.service';

export type SelfRegistrationSubmitInput = {
  channel: HwyRegistrationChannelShortName;
  firstName: string;
  fatherName: string;
  grandfatherName?: string | null;
  familyName: string;
  birthYear?: string | null;
  birthMonth?: string | null;
  birthDay?: string | null;
  phone1: string;
  phone2?: string | null;
  email?: string | null;
  nationalId?: string | null;
  genderCode?: string | null;
  addrProvinceId?: string | null;
  addrDistrictId?: string | null;
  addrQuarterName?: string | null;
  addrQuarterNo?: string | null;
  addrAlleyNo?: string | null;
  addrHouseNo?: string | null;
  addrNearestLandmark?: string | null;
  educationLevelCode?: string | null;
  educationSchool?: string | null;
  educationBranch?: string | null;
  educationEntryYear?: string | null;
  educationEndYear?: string | null;
  jobTypeCode?: string | null;
  jobPlace?: string | null;
  referrerInstituteCode?: string | null;
  referrerUsername?: string | null;
  referrerRelationId?: string | null;
  note?: string | null;
  attachments?: HwySelfRegistrationSubmitAttachment[];
};

export type SelfRegistrationSubmitResult = {
  memberId: number;
  trackingCode: string;
  registrationChannel: HwyRegistrationChannelShortName;
};

export type SelfRegistrationSubmitContext = {
  actorUserId?: number | null;
  /** When set, links member to this institute as active admin join (member_accepted = 1). */
  adminInstituteId?: number | null;
};

const trim = (value: string | null | undefined, max = 4000): string | null => {
  if (value == null) return null;
  const s = value.trim();
  if (!s) return null;
  return s.length > max ? s.slice(0, max) : s;
};

const normalizePhone = (value: string): string => sanitizeHwySelfRegistrationPhoneInput(value);

export const submitHwySelfRegistration = async (
  input: SelfRegistrationSubmitInput,
  context: SelfRegistrationSubmitContext = {},
): Promise<SelfRegistrationSubmitResult> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hawiety self-registration requires SQL Server control plane with hwy_* tables.');
  }

  const firstName = trim(input.firstName, 500);
  const fatherName = trim(input.fatherName, 500);
  const familyName = trim(input.familyName, 500);
  const phone1 = normalizePhone(input.phone1);
  if (!firstName || !fatherName || !familyName || !phone1) {
    throw new Error('Required member identity and phone fields are missing.');
  }
  if (!isValidHwySelfRegistrationPhone(phone1)) {
    throw new Error('Phone 1 must be 11 digits starting with 07.');
  }
  const phone2Raw = input.phone2 ? normalizePhone(input.phone2) : '';
  if (phone2Raw && !isValidHwySelfRegistrationPhone(phone2Raw)) {
    throw new Error('Phone 2 must be 11 digits starting with 07 when provided.');
  }

  const birthYear = trim(input.birthYear, 32);
  if (birthYear && !isValidHwySelfRegistrationBirthYear(birthYear)) {
    throw new Error('Birth year must be four digits between 1919 and the current year.');
  }

  const nationalId = trim(input.nationalId, 128);
  if (nationalId && !isValidHwySelfRegistrationNationalId(nationalId)) {
    throw new Error('National ID must be 12 digits when provided.');
  }

  const addrProvinceId = trim(input.addrProvinceId, 128);
  if (!addrProvinceId) {
    throw new Error('Province is required.');
  }
  if (!/^\d+$/.test(addrProvinceId)) {
    throw new Error('Province is invalid.');
  }
  if (!(await isHwySelfRegistrationProvinceLegacyId(addrProvinceId))) {
    throw new Error('Province is invalid.');
  }

  const addrDistrictForValidation = trim(input.addrDistrictId, 32);
  if (addrDistrictForValidation) {
    if (!/^\d+$/.test(addrDistrictForValidation)) {
      throw new Error('District is invalid.');
    }
    if (!(await isHwySelfRegistrationDistrictLegacyId(addrProvinceId, addrDistrictForValidation))) {
      throw new Error('District is not valid for the selected province.');
    }
  }

  const email = trim(input.email, 500);
  if (email && !isValidHwySelfRegistrationEmail(email)) {
    throw new Error('Email format is invalid.');
  }

  const educationEntryYear = trim(input.educationEntryYear, 32);
  const educationEndYear = trim(input.educationEndYear, 32);
  if (educationEntryYear && !isValidHwySelfRegistrationOptionalYear(educationEntryYear)) {
    throw new Error('Education entry year is invalid.');
  }
  if (educationEndYear && !isValidHwySelfRegistrationOptionalYear(educationEndYear)) {
    throw new Error('Education end year is invalid.');
  }

  const referrerUsername = trim(input.referrerUsername, 500);
  if (referrerUsername && !isValidHwySelfRegistrationReferrerUsername(referrerUsername)) {
    throw new Error('Referrer id must be six digits when provided.');
  }

  const referrerRelationRaw = trim(input.referrerRelationId, 32);
  let referrerRelationId: number | null = null;
  if (referrerRelationRaw) {
    if (!/^\d+$/.test(referrerRelationRaw)) {
      throw new Error('Referrer relation is invalid.');
    }
    referrerRelationId = Number(referrerRelationRaw);
    if (!Number.isFinite(referrerRelationId) || referrerRelationId <= 0) {
      throw new Error('Referrer relation is invalid.');
    }
  }
  if (referrerUsername && !referrerRelationId) {
    throw new Error('Referrer relation is required when referrer id is provided.');
  }
  if (!referrerUsername && referrerRelationId) {
    throw new Error('Referrer relation must be cleared when referrer id is empty.');
  }

  const referrerInstituteCode = trim(input.referrerInstituteCode, 32);
  if (referrerInstituteCode && !isValidHwySelfRegistrationInstituteCode(referrerInstituteCode)) {
    throw new Error('Institute referral code must be three digits when provided.');
  }

  await ensureHwyMembersSelfRegistrationSchema();
  await ensureHwySelfRegistrationBaseInfo();
  await ensureHwyDbObjects();

  const pendingStatusId = await resolveHwyBaseInfoItemId('Membership Status', 'pending_call_center');
  const registrationChannelId = await resolveHwyBaseInfoItemId('Registration Channel', input.channel);
  const joinPathSelfRegId = await resolveHwyBaseInfoItemId('Institute Join Path', 'self_registration');
  const joinPathAdminId = await resolveHwyBaseInfoItemId('Institute Join Path', 'admin');
  const instituteStatusPendingId = await resolveHwyBaseInfoItemId('Institute Membership Status', 'pending_invite');
  const instituteStatusActiveId = await resolveHwyBaseInfoItemId('Institute Membership Status', 'active');

  const genderCode = input.genderCode
    ? resolveHwyLegacyGenderBaseInfoId(input.genderCode)
    : null;

  const educationLevelCode = await resolveHwySelfRegistrationEducationLevelCode(input.educationLevelCode);
  const jobTypeCode = await resolveHwySelfRegistrationJobTypeCode(input.jobTypeCode);

  const adminInstituteId = context.adminInstituteId ?? null;
  const instituteId = adminInstituteId ?? await resolveHwySelfRegistrationInstituteId({
    channel: input.channel,
    referrerInstituteCode: input.referrerInstituteCode,
  });

  const instituteUsesAdminLink = adminInstituteId != null && instituteId === adminInstituteId;
  const instituteStatusCode = instituteId != null
    ? (instituteUsesAdminLink ? instituteStatusActiveId : instituteStatusPendingId)
    : null;
  const joinPathCode = instituteId != null
    ? (instituteUsesAdminLink ? joinPathAdminId : joinPathSelfRegId)
    : null;
  const instituteMemberAccepted = instituteUsesAdminLink ? 1 : 0;

  const now = new Date();
  const addrDistrictRaw = trim(input.addrDistrictId, 32);
  const addrDistrictId = addrDistrictRaw && /^\d+$/.test(addrDistrictRaw)
    ? Number(addrDistrictRaw)
    : null;

  const created = await execHwyProcedure<{ memberId: number | string; trackingCode: string }>(
    'hwy_self_registration_create_member',
    {
      first_name: firstName,
      father_name: fatherName,
      grandfather_name: trim(input.grandfatherName, 500),
      family_name: familyName,
      birth_year: trim(input.birthYear, 32),
      birth_month: trim(input.birthMonth, 32),
      birth_day: trim(input.birthDay, 32),
      phone1,
      phone2: phone2Raw || null,
      email: trim(input.email, 500),
      national_id: trim(input.nationalId, 128),
      gender_code: genderCode,
      addr_province_id: trim(input.addrProvinceId, 128),
      addr_district_id: addrDistrictId,
      addr_quarter_name: trim(input.addrQuarterName, 4000),
      addr_quarter_no: trim(input.addrQuarterNo, 128),
      addr_alley_no: trim(input.addrAlleyNo, 128),
      addr_house_no: trim(input.addrHouseNo, 128),
      addr_nearest_landmark: trim(input.addrNearestLandmark, 4000),
      education_level_code: educationLevelCode,
      education_school: trim(input.educationSchool, 4000),
      education_branch: trim(input.educationBranch, 4000),
      education_entry_year: trim(input.educationEntryYear, 32),
      education_end_year: trim(input.educationEndYear, 32),
      job_type_code: jobTypeCode,
      job_place: trim(input.jobPlace, 4000),
      referrer_username: trim(input.referrerUsername, 500),
      referrer_relation_id: referrerRelationId,
      membership_status_code: pendingStatusId,
      registration_channel_code: registrationChannelId,
      note: trim(input.note, 8000),
      institute_id: instituteId,
      institute_status_code: instituteStatusCode,
      join_path_code: joinPathCode,
      institute_member_accepted: instituteMemberAccepted,
      created_at: now,
      updated_at: now,
    },
  );
  const memberId = Number(created[0]?.memberId);
  if (!Number.isFinite(memberId) || memberId <= 0) {
    throw new Error('Could not create member.');
  }
  const result = {
    memberId,
    trackingCode: String(created[0]?.trackingCode ?? memberId),
    registrationChannel: input.channel,
  };

  for (const attachment of input.attachments ?? []) {
    await persistHwyMemberFileByKindSlug({
      memberId: result.memberId,
      kindSlug: attachment.kindSlug,
      fileName: attachment.fileName,
      mime: attachment.mime,
      body: attachment.body,
    });
  }

  await runHwyMemberAfterCreateHook({
    memberId,
    actorUserId: context.actorUserId ?? null,
  });

  return result;
};

export const trackHwySelfRegistration = async (
  trackingCodeRaw: string,
): Promise<{ status: 'found'; message: string } | { status: 'invalid' }> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Hawiety registration tracking requires SQL Server control plane.');
  }
  const trackingCode = trackingCodeRaw.trim();
  if (!trackingCode) {
    return { status: 'invalid' };
  }

  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ membership_status_code: string | null }>(
    `
    SELECT TOP (1) m.membership_status_code
    FROM dbo.hwy_members m
    WHERE CAST(m.id AS NVARCHAR(32)) = :code
       OR (TRY_CAST(:code AS BIGINT) IS NOT NULL AND m.id = TRY_CAST(:code AS BIGINT))
    `,
    {
      replacements: { code: trackingCode },
      type: QueryTypes.SELECT,
    },
  );

  const statusCode = rows[0]?.membership_status_code;
  if (!statusCode) {
    return { status: 'invalid' };
  }

  const title = await resolveHwyBaseInfoItemTitle(statusCode);
  return {
    status: 'found',
    message: title ?? statusCode,
  };
};
