import {
  findHwyMemberSegmentListByPageName,
  type HwyMemberSegmentListDefinition,
} from './hwyMemberSegmentListCatalog';

/** Legacy AppEnd controller + method pair (`hasAccessAction(controller, method)`). */
export type HwyLegacyControllerAction = {
  controller:
    | 'HWY_Members'
    | 'HWY_Members_CardPrintingHistory'
    | 'HWY_Members_SecurityProfile'
    | 'HWY_BaseInformation'
    | 'HWY_Nakhebin'
    | 'HWY_Dorat'
    | 'HWY_Nashatat';
  method: string;
};

export const legacyHwyActionKey = (action: HwyLegacyControllerAction): string => (
  `${action.controller}::${action.method}`
);

/** Stable platform `base_roles.name` for a legacy AppEnd role row. */
export const legacyHwyRoleIdToPlatformRoleName = (legacyRoleId: number): string => (
  `HWY_R_${legacyRoleId}`
);

