export const resolveHwyMemberSegmentLegacyReadAction = (
  definition: HwyMemberSegmentListDefinition,
): HwyLegacyControllerAction => {
  const method = MEMBERS_LIST_LEGACY_READ_METHOD[definition.legacyCode];
  if (!method) {
    throw new Error(`Missing legacy read method for ${definition.legacyCode}`);
  }
  return { controller: 'HWY_Members', method };
};

export const HWY_MEMBER_DIRECTORY_PAGE_LEGACY_READ: HwyLegacyControllerAction = {
  controller: 'HWY_Members',
  method: 'Read_List_All',
};

export const HWY_NAKHEBIN_PAGE_LEGACY_READ: HwyLegacyControllerAction = {
  controller: 'HWY_Nakhebin',
  method: 'Read_List',
};

export const HWY_ORG_MEMBERSHIP_TRANSFER_PAGE_LEGACY_READ: HwyLegacyControllerAction = {
  controller: 'HWY_Members',
  method: 'Read_List_All_OrgMembership',
};

export const resolveHwyMemberListPageLegacyReadAction = (
  pageKey: string,
): HwyLegacyControllerAction | null => {
  if (pageKey === 'hwy-employees-list') {
    return { controller: 'HWY_Members', method: 'Read_Employees' };
  }
  if (pageKey === 'hwy-members-all') {
    return HWY_MEMBER_DIRECTORY_PAGE_LEGACY_READ;
  }
  if (pageKey === 'hwy-org-membership-transfer') {
    return HWY_ORG_MEMBERSHIP_TRANSFER_PAGE_LEGACY_READ;
  }
  if (pageKey === 'hwy-nakhebin') {
    return HWY_NAKHEBIN_PAGE_LEGACY_READ;
  }
  const segment = findHwyMemberSegmentListByPageName(pageKey);
  if (segment) {
    return resolveHwyMemberSegmentLegacyReadAction(segment);
  }
  return null;
};

/** Nav / route auth: ADMIN plus legacy-mapped roles when ETL has run. */
export const buildHwyMemberListRouteAllowRoles = (
  legacyRoleNames: ReadonlyArray<string>,
): string[] => {
  const merged = new Set<string>(['ADMIN', ...legacyRoleNames]);
  return [...merged];
};
