import { HWY_ACTIVITY_STATUS_REGISTER, HWY_COURSE_STATUS_DRAFT } from '../../../domain/hwy/hwyCoursesActivitiesCatalog';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { readControlPlaneProvider } from '../users/prismaHelpers';

const parsePositiveInt = (raw: string, label: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error(`${label} is invalid.`);
  }
  const value = Number(trimmed);
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${label} is invalid.`);
  }
  return value;
};

export const cleanupHwyDraftedCourses = async (): Promise<{ deletedCourses: number }> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Course cleanup requires SQL Server control plane.');
  }
  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<{ deletedCourses: number | string }>('hwy_courses_cleanup_drafted', {
    draft_status_code: HWY_COURSE_STATUS_DRAFT,
  });
  return { deletedCourses: Number(rows[0]?.deletedCourses ?? 0) };
};

