export const copyHwyCourseAttendances = async (input: {
  sourceCourseIdRaw: string;
  targetCourseIdRaw: string;
  actorUserId: number | null;
}): Promise<{ copiedCount: number }> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Copy course participants requires SQL Server control plane.');
  }
  const sourceCourseId = parsePositiveInt(input.sourceCourseIdRaw, 'Source course id');
  const targetCourseId = parsePositiveInt(input.targetCourseIdRaw, 'Target course id');
  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<{ copiedCount: number | string }>('hwy_course_copy_attendances', {
    source_course_id: sourceCourseId,
    target_course_id: targetCourseId,
    actor_user_id: input.actorUserId,
  });
  return { copiedCount: Number(rows[0]?.copiedCount ?? 0) };
};
