export type HwyGeoResponsibilityNominationMemberFilters = {
  membershipNumber?: string;
  firstName?: string;
  fatherName?: string;
  grandfatherName?: string;
  familyName?: string;
};

const trim = (value: string | undefined | null): string => String(value ?? '').trim();

export const appendHwyGeoResponsibilityNominationMemberFilterSql = (
  filters: HwyGeoResponsibilityNominationMemberFilters | undefined,
  replacements: Record<string, unknown>,
): string => {
  if (!filters) {
    return '';
  }
  const parts: string[] = [];
  const assignLike = (param: string, column: string, value: string) => {
    if (!value) {
      return;
    }
    parts.push(`${column} LIKE :${param}`);
    replacements[param] = `%${value}%`;
  };
  const assignEq = (param: string, column: string, value: string) => {
    if (!value) {
      return;
    }
    parts.push(`${column} = :${param}`);
    replacements[param] = value;
  };

  assignEq('filterMembershipNumber', 'm.username', trim(filters.membershipNumber));
  assignLike('filterFirstName', 'm.first_name', trim(filters.firstName));
  assignLike('filterFatherName', 'm.father_name', trim(filters.fatherName));
  assignLike('filterGrandfatherName', 'm.grandfather_name', trim(filters.grandfatherName));
  assignLike('filterFamilyName', 'm.family_name', trim(filters.familyName));

  if (parts.length === 0) {
    return '';
  }
  return ` AND (${parts.join(' AND ')})`;
};

/** Params for dbo.hwy_geo_responsibility_nomination_candidates_* procs. */
export const hwyGeoResponsibilityNominationMemberFilterProcParams = (
  filters: HwyGeoResponsibilityNominationMemberFilters | undefined,
): {
  filter_membership_number: string | null;
  filter_first_name_like: string | null;
  filter_father_name_like: string | null;
  filter_grandfather_name_like: string | null;
  filter_family_name_like: string | null;
} => {
  const like = (value: string | undefined): string | null => {
    const trimmed = trim(value);
    return trimmed ? `%${trimmed}%` : null;
  };
  return {
    filter_membership_number: trim(filters?.membershipNumber) || null,
    filter_first_name_like: like(filters?.firstName),
    filter_father_name_like: like(filters?.fatherName),
    filter_grandfather_name_like: like(filters?.grandfatherName),
    filter_family_name_like: like(filters?.familyName),
  };
};
