import { Op } from 'sequelize';
import { normalizeHwyHouseholdMemberId } from '../../../domain/hwy/hwyFamilyHouseholdMemberId';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { attachHwyHouseholdMemberAvatarUrl } from '../../../domain/hwy/hwyFamilyHouseholdMemberAvatar';
import { resolvePublishedEdgeModel } from '../../services/data-api/dataApiPublishedRuntime';
import { resolveHwyAllocatedMembershipUsername } from '../../../domain/hwy/hwyMembershipUsername';
import { collectNakhebinLinkedMemberIds } from './hwyFamilyHouseholdMemberQuery';

const MEMBER_DIRECTORY_MODEL_ID = 'em_5f3a30c99bb3420e';

const readTrimmed = (row: Record<string, unknown>, ...keys: string[]): string => {
  for (const key of keys) {
    const raw = row[key];
    if (raw == null) {
      continue;
    }
    const text = String(raw).trim();
    if (text.length > 0) {
      return text;
    }
  }
  return '';
};

const resolveMemberLinkUsername = (member: Record<string, unknown>): string => {
  const memberId = readTrimmed(member, 'id');
  const allocated = resolveHwyAllocatedMembershipUsername(readTrimmed(member, 'username'), memberId || null);
  if (allocated) {
    return allocated;
  }
  return readTrimmed(member, 'trackingCode');
};

export const applyNakhebinLinkedMemberDisplayFields = (
  row: Record<string, unknown>,
  member: Record<string, unknown> | undefined,
): void => {
  delete row.memberLinkAvatarUrl;
  delete row.memberLinkUsername;
  delete row.memberLinkGenderCode;
  delete row.memberLinkDisplayName;

  const memberId = normalizeHwyHouseholdMemberId(row.memberId ?? row.member_id);
  if (!memberId) {
    return;
  }

  if (!member) {
    return;
  }

  const memberRow = { ...member };
  attachHwyHouseholdMemberAvatarUrl(memberRow);

  const avatarUrl = readTrimmed(memberRow, 'avatarUrl', 'avatar_url');
  if (avatarUrl) {
    row.memberLinkAvatarUrl = avatarUrl;
  }

  const username = resolveMemberLinkUsername(memberRow);
  if (username) {
    row.memberLinkUsername = username;
  }

  const genderCode = readTrimmed(memberRow, 'genderCode', 'gender_code');
  if (genderCode) {
    row.memberLinkGenderCode = genderCode;
  }

  const displayName = formatHwyMemberPersonDisplayName(
    readTrimmed(memberRow, 'displayFullName', 'display_full_name'),
  );
  if (displayName) {
    row.memberLinkDisplayName = displayName;
  }
};

/** Nakhebin list: avatar + username + id for linked `member_id`. */
export async function attachNakhebinLinkedMemberDisplay(
  rows: Record<string, unknown>[],
): Promise<void> {
  if (rows.length === 0) {
    return;
  }

  const linkedIds = collectNakhebinLinkedMemberIds(rows);
  if (linkedIds.length === 0) {
    for (const row of rows) {
      applyNakhebinLinkedMemberDisplayFields(row, undefined);
    }
    return;
  }

  const { Model: VwHwyMembers } = await resolvePublishedEdgeModel(MEMBER_DIRECTORY_MODEL_ID);
  const memberRows = await VwHwyMembers.findAll({
    where: { id: { [Op.in]: linkedIds } },
    attributes: [
      'id',
      'username',
      'trackingCode',
      'userId',
      'avatarUrl',
      'hasProfileImage',
      'profileImageSize',
      'genderCode',
      'displayFullName',
    ],
    raw: true,
  });

  const memberById = new Map<string, Record<string, unknown>>();
  for (const member of memberRows as Record<string, unknown>[]) {
    const key = normalizeHwyHouseholdMemberId(member.id);
    if (key) {
      memberById.set(key, member);
    }
  }

  for (const row of rows) {
    const memberId = normalizeHwyHouseholdMemberId(row.memberId ?? row.member_id);
    applyNakhebinLinkedMemberDisplayFields(row, memberById.get(memberId));
  }
}
