import { QueryTypes } from 'sequelize';

import {
  HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS,
  type HwyMemberImageFixThumbKindSlug,
} from '../../../domain/hwy/hwyMemberImageFixCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { resolveHwyMemberFileKindBySlugOrId } from './hwyMemberFileKindResolve.service';

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const parseFileId = (raw: string | null | undefined): number | null => {
  const trimmed = String(raw ?? '').trim();
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    return null;
  }
  return id;
};

const assertRegistrationSlotSlug = (
  slug: string,
): HwyMemberImageFixThumbKindSlug => {
  if (!(HWY_MEMBER_IMAGE_FIX_LIST_THUMB_KIND_SLUGS as readonly string[]).includes(slug)) {
    throw new Error('Registration slot is invalid.');
  }
  return slug as HwyMemberImageFixThumbKindSlug;
};

async function resolveKindCode(slug: HwyMemberImageFixThumbKindSlug): Promise<string> {
  const resolved = await resolveHwyMemberFileKindBySlugOrId(slug);
  const id = resolved?.id?.trim();
  if (!id) {
    throw new Error('Registration file kind is not configured.');
  }
  return id;
}

type FileRow = { id: number; fileKindCode: string };

async function loadMemberFileById(
  memberId: number,
  fileId: number,
): Promise<FileRow | null> {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<FileRow>(
    `
    SELECT
      CAST(f.id AS BIGINT) AS id,
      CAST(f.file_kind_code AS NVARCHAR(32)) AS fileKindCode
    FROM dbo.hwy_member_files f
    WHERE f.member_id = :memberId
      AND f.id = :fileId
    `,
    {
      replacements: { memberId, fileId },
      type: QueryTypes.SELECT,
    },
  );
  const row = rows[0];
  if (!row?.id) {
    return null;
  }
  return { id: Number(row.id), fileKindCode: String(row.fileKindCode).trim() };
}

async function updateFileKind(
  memberId: number,
  fileId: number,
  fileKindCode: string,
  updatedByUserId: number | null,
  transaction: import('sequelize').Transaction,
): Promise<void> {
  const sequelize = getControlPlaneSequelize();
  await sequelize.query(
    `
    UPDATE dbo.hwy_member_files
    SET file_kind_code = :fileKindCode,
        updated_by = :updatedBy,
        updated_at = SYSUTCDATETIME()
    WHERE id = :fileId AND member_id = :memberId
    `,
    {
      replacements: {
        fileKindCode,
        updatedBy: updatedByUserId,
        fileId,
        memberId,
      },
      transaction,
    },
  );
}

/**
 * Legacy ImageFix drag-drop: move into empty slot or swap blobs between two slots
 * by reassigning `file_kind_code` (registration rows are not deletable).
 */
export async function moveHwyMemberImageFixRegistrationFileSlot(input: {
  memberId: string;
  sourceKindSlug: string;
  targetKindSlug: string;
  sourceFileId: string;
  targetFileId?: string | null;
  updatedByUserId?: number | null;
}): Promise<void> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Member file move requires SQL Server control plane.');
  }

  assertRegistrationSlotSlug(input.sourceKindSlug.trim());
  assertRegistrationSlotSlug(input.targetKindSlug.trim());
  if (input.sourceKindSlug.trim() === input.targetKindSlug.trim()) {
    return;
  }

  const sourceFileId = parseFileId(input.sourceFileId);
  if (!sourceFileId) {
    throw new Error('Source file id is invalid.');
  }

  await ensureHwyDbObjects();
  const memberId = parseMemberId(input.memberId);
  const targetKindCode = await resolveKindCode(
    assertRegistrationSlotSlug(input.targetKindSlug.trim()),
  );

  const sourceFile = await loadMemberFileById(memberId, sourceFileId);
  if (!sourceFile) {
    throw new Error('Source file was not found for this member.');
  }

  const targetFileIdParsed = parseFileId(input.targetFileId);
  const targetFile = targetFileIdParsed
    ? await loadMemberFileById(memberId, targetFileIdParsed)
    : null;

  const sequelize = getControlPlaneSequelize();
  const updatedBy = input.updatedByUserId ?? null;
  const sourceKindCode = sourceFile.fileKindCode;

  await sequelize.transaction(async (transaction) => {
    if (!targetFile) {
      await updateFileKind(memberId, sourceFile.id, targetKindCode, updatedBy, transaction);
      return;
    }

    await updateFileKind(memberId, sourceFile.id, targetKindCode, updatedBy, transaction);
    await updateFileKind(memberId, targetFile.id, sourceKindCode, updatedBy, transaction);
  });
}
