import { apiGet, resolveApiMutationErrorMessage } from '../../shared/api/client';
import { resolveHwyMemberDirectoryDetailLang } from './hwyMemberDirectoryDetail';

/** Legacy approve decision reasons (`getBaseInformationByParent(212130)`). */
export const HWY_MEMBER_TARGHIN_APPROVE_FINAL_REASON_LEGACY_PARENT_ID = '212130';

/** Legacy reject decision reasons (`getBaseInformationByParent(212170)`). */
export const HWY_MEMBER_TARGHIN_REJECT_FINAL_REASON_LEGACY_PARENT_ID = '212170';

export type HwyMemberTarghinDecisionKind = 'approve' | 'reject';

export type HwyMemberTarghinFinalReasonOption = {
  value: string;
  label: string;
};

export type HwyMemberTarghinFinalReasonOptionsResponse = {
  success?: boolean;
  data?: HwyMemberTarghinFinalReasonOption[];
};

export const resolveHwyMemberTarghinFinalReasonLegacyParentId = (
  decision: HwyMemberTarghinDecisionKind,
): string => (
  decision === 'approve'
    ? HWY_MEMBER_TARGHIN_APPROVE_FINAL_REASON_LEGACY_PARENT_ID
    : HWY_MEMBER_TARGHIN_REJECT_FINAL_REASON_LEGACY_PARENT_ID
);

export function buildHwyMemberTarghinFinalReasonOptionsPath(
  decision: HwyMemberTarghinDecisionKind,
  cultureId?: string | null,
): string {
  const lang = resolveHwyMemberDirectoryDetailLang(cultureId);
  return `/api/hwy/targhin-requests/final-reasons?decision=${encodeURIComponent(decision)}&lang=${encodeURIComponent(lang)}`;
}

export async function fetchHwyMemberTarghinFinalReasonOptions(
  decision: HwyMemberTarghinDecisionKind,
  cultureId?: string | null,
): Promise<HwyMemberTarghinFinalReasonOption[]> {
  const { data, response } = await apiGet<HwyMemberTarghinFinalReasonOptionsResponse>(
    buildHwyMemberTarghinFinalReasonOptionsPath(decision, cultureId),
  );
  if (!response.ok || !data?.success) {
    throw new Error(
      resolveApiMutationErrorMessage(data, `Could not load targhin decision reasons. (HTTP ${response.status})`),
    );
  }
  return data.data ?? [];
}
