import type { Sequelize } from 'sequelize';
import { QueryTypes } from 'sequelize';

import {
  splitHwyMembershipDecisionNoteBody,
} from '../../../domain/hwy/hwyMembershipDecisionNoteBody';
import {
  isHwyMemberRejectionListLegacyScope,
  type HwyMemberRejectionListLegacyScope,
} from '../../../domain/hwy/hwyMemberRejectionListParity';
import { attachLegacyRejectionListStatusFields } from './hwyMemberRejectionListLegacyStatusParity.service';

type RawMemberNoteRow = {
  member_id: string;
  body: string;
  subject_short_name: string | null;
  overall_rn: number;
  subject_rn: number;
};

type UpdaterRow = {
  member_id: string;
  display_name: string | null;
  login: string | null;
  phone: string | null;
  staff_member_id: string | null;
  membership_status_updated_on: Date | string | null;
  member_note: string | null;
};

type CpLegacyRejectedByRow = {
  member_id: string;
  updated_by_username: string | null;
  staff_member_id: string | null;
  display_name: string | null;
  phone: string | null;
};

const trimRejectedByField = (value: string | null | undefined): string => String(value ?? '').trim();

const mergeRejectedByFieldsOntoRow = (
  row: Record<string, unknown>,
  source: {
    display_name?: string | null;
    login?: string | null;
    phone?: string | null;
    staff_member_id?: string | null;
  },
): void => {
  const display = trimRejectedByField(source.display_name);
  const login = trimRejectedByField(source.login);
  const phone = trimRejectedByField(source.phone);
  const staffMemberId = trimRejectedByField(source.staff_member_id);

  if (!trimRejectedByField(String(row.membershipStatusUpdatedByDisplayName ?? '')) && display) {
    row.membershipStatusUpdatedByDisplayName = display;
  } else if (!trimRejectedByField(String(row.membershipStatusUpdatedByDisplayName ?? '')) && login) {
    row.membershipStatusUpdatedByDisplayName = login;
  }
  if (!trimRejectedByField(String(row.membershipStatusUpdatedByLogin ?? '')) && login) {
    row.membershipStatusUpdatedByLogin = login;
  }
  if (!trimRejectedByField(String(row.membershipStatusUpdatedByPhone ?? '')) && phone) {
    row.membershipStatusUpdatedByPhone = phone;
  }
  if (!trimRejectedByField(String(row.membershipStatusUpdatedByStaffMemberId ?? '')) && staffMemberId) {
    row.membershipStatusUpdatedByStaffMemberId = staffMemberId;
  }
};

async function queryCpLegacyHwMembersRejectedByFields(
  sequelize: Sequelize,
  memberIds: string[],
): Promise<Map<string, CpLegacyRejectedByRow>> {
  const result = new Map<string, CpLegacyRejectedByRow>();
  if (memberIds.length === 0) {
    return result;
  }
  const { controlPlaneHasLegacyHwyMembersTable } = await import(
    './hwyGeoResponsibilityLegacyCenterStats.service'
  );
  if (!(await controlPlaneHasLegacyHwyMembersTable())) {
    return result;
  }
  try {
    const rows = await sequelize.query<CpLegacyRejectedByRow>(
      `
      SELECT
        CAST(leg.Id AS VARCHAR(32)) AS member_id,
        NULLIF(LTRIM(RTRIM(COALESCE(
          CAST(leg.membership_status_updated_by AS NVARCHAR(4000)),
          CAST(staff_u.username AS NVARCHAR(4000)),
          CAST(staff_by_user.username AS NVARCHAR(4000)),
          N''
        ))), N'') AS updated_by_username,
        CAST(COALESCE(staff_u.id, staff_by_user.id) AS VARCHAR(32)) AS staff_member_id,
        NULLIF(LTRIM(RTRIM(CONCAT_WS(N' ',
          NULLIF(LTRIM(RTRIM(COALESCE(staff_u.first_name, staff_by_user.first_name, N''))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(staff_u.father_name, staff_by_user.father_name, N''))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(staff_u.grandfather_name, staff_by_user.grandfather_name, N''))), N''),
          NULLIF(LTRIM(RTRIM(COALESCE(staff_u.family_name, staff_by_user.family_name, N''))), N'')
        ))), N'') AS display_name,
        NULLIF(LTRIM(RTRIM(COALESCE(staff_u.phone1, staff_by_user.phone1, N''))), N'') AS phone
      FROM dbo.HWY_Members leg WITH (NOLOCK)
      LEFT JOIN dbo.hwy_members staff_u WITH (NOLOCK)
        ON staff_u.username = NULLIF(LTRIM(RTRIM(CAST(leg.membership_status_updated_by AS NVARCHAR(4000)))), N'')
        OR CAST(staff_u.id AS VARCHAR(32)) = NULLIF(LTRIM(RTRIM(CAST(leg.membership_status_updated_by AS NVARCHAR(4000)))), N'')
      LEFT JOIN dbo.base_users bu WITH (NOLOCK)
        ON bu.id = TRY_CAST(leg.membership_status_updated_by AS BIGINT)
      LEFT JOIN dbo.hwy_members staff_by_user WITH (NOLOCK)
        ON staff_by_user.user_id = bu.id
      WHERE leg.Id IN (:memberIds)
        AND (
          NULLIF(LTRIM(RTRIM(CAST(leg.membership_status_updated_by AS NVARCHAR(4000)))), N'') IS NOT NULL
          OR staff_u.id IS NOT NULL
          OR staff_by_user.id IS NOT NULL
        )
      `,
      {
        replacements: { memberIds },
        type: QueryTypes.SELECT,
      },
    );
    for (const row of rows) {
      const memberId = trimRejectedByField(row.member_id);
      if (memberId) {
        result.set(memberId, row);
      }
    }
    return result;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.warn('[hwy-member-rejection-list] CP HWY_Members rejected-by read failed.', message);
    return result;
  }
}

type MemberNoteBucket = {
  latestOverall: string;
  callCenter: string;
  statusDecision: string;
  statusDecisionPrevious: string;
};

const REGION_RETURN_BADGE = 'معاد من مسؤول المنطقة';

const STATUS_DECISION_SUBJECTS = ['local_verification', 'membership'] as const;

const readMemberId = (row: Record<string, unknown>): string => {
  const raw = row.id ?? row.memberId;
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

const readNoteBody = (body: string | null | undefined): string => String(body ?? '').trim();

const applyParsedDecisionNotes = (
  row: Record<string, unknown>,
  notes: { latest: string; previous: string },
): void => {
  const latestParsed = splitHwyMembershipDecisionNoteBody(notes.latest);
  const previousParsed = splitHwyMembershipDecisionNoteBody(notes.previous);

  if (latestParsed.reasonTitle) {
    row.membershipStatusDecisionReasonTitle = latestParsed.reasonTitle;
    row.membershipStatusDecisionNote = latestParsed.note || notes.latest;
  } else if (notes.latest) {
    row.membershipStatusDecisionNote = latestParsed.note;
  }

  if (notes.previous) {
    const previousText = previousParsed.note || notes.previous;
    if (previousText && previousText !== row.membershipStatusDecisionNote) {
      row.membershipStatusDecisionPreviousNote = previousText;
      if (previousParsed.reasonTitle && !row.membershipStatusDecisionReasonTitle) {
        row.membershipStatusDecisionReasonTitle = previousParsed.reasonTitle;
      }
    }
  }

  const combined = `${String(row.membershipStatusDecisionReasonTitle ?? '')} ${String(row.membershipStatusDecisionNote ?? '')} ${String(row.membershipStatusDecisionPreviousNote ?? '')}`;
  if (combined.includes('مسؤول المنطقة') || combined.includes('معاد من')) {
    row.membershipStatusReturnedFromRegionBadge = REGION_RETURN_BADGE;
  }
};

const buildMemberNoteBuckets = (noteRows: RawMemberNoteRow[]): Map<string, MemberNoteBucket> => {
  const byMember = new Map<string, {
    overall: string[];
    bySubject: Map<string, string[]>;
  }>();

  for (const note of noteRows) {
    const memberId = String(note.member_id ?? '').trim();
    const body = readNoteBody(note.body);
    if (!memberId || !body) {
      continue;
    }
    const bucket = byMember.get(memberId) ?? { overall: [], bySubject: new Map() };
    if (note.overall_rn === 1 && !bucket.overall.includes(body)) {
      bucket.overall.push(body);
    }
    const subject = String(note.subject_short_name ?? '').trim() || 'unknown';
    const subjectList = bucket.bySubject.get(subject) ?? [];
    if (!subjectList.includes(body)) {
      subjectList.push(body);
    }
    bucket.bySubject.set(subject, subjectList);
    byMember.set(memberId, bucket);
  }

  const result = new Map<string, MemberNoteBucket>();
  for (const [memberId, bucket] of byMember) {
    const callCenter = readNoteBody(bucket.bySubject.get('call_center')?.[0]);
    let statusDecision = '';
    let statusDecisionPrevious = '';
    for (const subject of STATUS_DECISION_SUBJECTS) {
      const list = bucket.bySubject.get(subject) ?? [];
      if (list[0]) {
        statusDecision = list[0];
        statusDecisionPrevious = list[1] ?? '';
        break;
      }
    }
    if (!statusDecision) {
      statusDecision = readNoteBody(bucket.overall[0]);
      statusDecisionPrevious = readNoteBody(bucket.overall[1]);
    }
    result.set(memberId, {
      latestOverall: readNoteBody(bucket.overall[0]),
      callCenter,
      statusDecision,
      statusDecisionPrevious,
    });
  }
  return result;
};

const MEMBER_NOTES_PARITY_SQL = `
  WITH candidate AS (
    SELECT
      CAST(n.member_id AS VARCHAR(32)) AS member_id,
      CAST(n.body AS NVARCHAR(MAX)) AS body,
      n.created_at,
      subj.short_name AS subject_short_name
    FROM dbo.hwy_member_notes n
    LEFT JOIN dbo.base_info subj ON subj.id = n.subject_code
    WHERE n.member_id IN (:memberIds)
      AND NULLIF(LTRIM(RTRIM(CAST(n.body AS NVARCHAR(MAX)))), N'') IS NOT NULL
  ),
  ranked AS (
    SELECT
      member_id,
      body,
      subject_short_name,
      ROW_NUMBER() OVER (
        PARTITION BY member_id
        ORDER BY created_at DESC
      ) AS overall_rn,
      ROW_NUMBER() OVER (
        PARTITION BY member_id, COALESCE(subject_short_name, N'')
        ORDER BY created_at DESC
      ) AS subject_rn
    FROM candidate
  )
  SELECT member_id, body, subject_short_name, overall_rn, subject_rn
  FROM ranked
  WHERE overall_rn <= 12 OR subject_rn <= 4
`;

export async function attachHwyMemberRejectionListParityFields(
  sequelize: Sequelize,
  rows: Record<string, unknown>[],
  listScopeLegacy: string | null | undefined,
): Promise<void> {
  if (!isHwyMemberRejectionListLegacyScope(listScopeLegacy) || rows.length === 0) {
    return;
  }

  const memberIds = [...new Set(rows.map(readMemberId).filter(Boolean))];
  if (memberIds.length === 0) {
    return;
  }

  const noteRows = await sequelize.query<RawMemberNoteRow>(
    MEMBER_NOTES_PARITY_SQL,
    {
      replacements: { memberIds },
      type: QueryTypes.SELECT,
    },
  );

  const noteBuckets = buildMemberNoteBuckets(noteRows);

  const updaterRows = await sequelize.query<UpdaterRow>(
    `
    SELECT
      CAST(m.id AS VARCHAR(32)) AS member_id,
      NULLIF(LTRIM(RTRIM(CONCAT_WS(N' ',
        NULLIF(LTRIM(RTRIM(COALESCE(p.firstname, N''))), N''),
        NULLIF(LTRIM(RTRIM(COALESCE(p.fathername, N''))), N''),
        NULLIF(LTRIM(RTRIM(COALESCE(p.grandfathername, N''))), N''),
        NULLIF(LTRIM(RTRIM(COALESCE(p.lastname, N''))), N'')
      ))), N'') AS display_name,
      NULLIF(LTRIM(RTRIM(u.username)), N'') AS login,
      NULLIF(LTRIM(RTRIM(COALESCE(p.phone, N''))), N'') AS phone,
      CAST(staff.id AS VARCHAR(32)) AS staff_member_id,
      m.membership_status_updated_on,
      NULLIF(LTRIM(RTRIM(CAST(m.note AS NVARCHAR(MAX)))), N'') AS member_note
    FROM dbo.hwy_members m
    LEFT JOIN dbo.base_users u ON u.id = m.membership_status_updated_by
    LEFT JOIN dbo.base_user_profiles p ON p.user_id = u.id
    OUTER APPLY (
      SELECT TOP (1) hm.id
      FROM dbo.hwy_members hm
      WHERE hm.user_id = u.id
      ORDER BY hm.id DESC
    ) staff
    WHERE m.id IN (:memberIds)
    `,
    {
      replacements: { memberIds },
      type: QueryTypes.SELECT,
    },
  );

  const updatersByMember = new Map<string, UpdaterRow>();
  for (const row of updaterRows) {
    const memberId = String(row.member_id ?? '').trim();
    if (memberId) {
      updatersByMember.set(memberId, row);
    }
  }

  const cpLegacyRejectedByByMember = await queryCpLegacyHwMembersRejectedByFields(sequelize, memberIds);

  for (const row of rows) {
    const memberId = readMemberId(row);
    if (!memberId) {
      continue;
    }

    const bucket = noteBuckets.get(memberId);
    if (bucket?.statusDecision || bucket?.statusDecisionPrevious) {
      applyParsedDecisionNotes(row, {
        latest: bucket.statusDecision,
        previous: bucket.statusDecisionPrevious,
      });
    }

    const updater = updatersByMember.get(memberId);
    if (!String(row.membershipStatusUpdatedOn ?? '').trim() && updater?.membership_status_updated_on) {
      row.membershipStatusUpdatedOn = updater.membership_status_updated_on;
    }

    const hasDecisionText = Boolean(
      String(row.membershipStatusDecisionNote ?? '').trim()
      || String(row.membershipStatusDecisionReasonTitle ?? '').trim(),
    );
    const fallbackNote = String(updater?.member_note ?? '').trim();
    if (!hasDecisionText && fallbackNote) {
      applyParsedDecisionNotes(row, { latest: fallbackNote, previous: '' });
    }

    if (bucket?.callCenter) {
      row.membershipStatusNoteByCallCenter = bucket.callCenter;
    }
    if (bucket?.latestOverall) {
      row.membershipLatestNote = bucket.latestOverall;
    }

    mergeRejectedByFieldsOntoRow(row, {
      display_name: updater?.display_name,
      login: updater?.login,
      phone: updater?.phone,
      staff_member_id: updater?.staff_member_id,
    });

    const cpLegacyRejectedBy = cpLegacyRejectedByByMember.get(memberId);
    if (cpLegacyRejectedBy) {
      mergeRejectedByFieldsOntoRow(row, {
        display_name: cpLegacyRejectedBy.display_name,
        login: cpLegacyRejectedBy.updated_by_username,
        phone: cpLegacyRejectedBy.phone,
        staff_member_id: cpLegacyRejectedBy.staff_member_id,
      });
    }
  }

  await attachLegacyRejectionListStatusFields(
    rows,
    listScopeLegacy as HwyMemberRejectionListLegacyScope,
  );

  for (const row of rows) {
    const hasRejectedBy = Boolean(
      trimRejectedByField(String(row.membershipStatusUpdatedByDisplayName ?? ''))
      || trimRejectedByField(String(row.membershipStatusUpdatedByLogin ?? '')),
    );
    if (!hasRejectedBy) {
      continue;
    }
    for (const field of [
      'membershipStatusUpdatedByDisplayName',
      'membershipStatusUpdatedByLogin',
      'membershipStatusUpdatedByPhone',
      'membershipStatusUpdatedByStaffMemberId',
      'membershipStatusUpdatedByRoles',
    ] as const) {
      const value = row[field];
      if (value !== undefined && value !== null && String(value).trim()) {
        const snake = field.replace(/([A-Z])/g, '_$1').toLowerCase();
        if (row[snake] === undefined) {
          row[snake] = value;
        }
      }
    }
  }
}
