import { QueryTypes } from 'sequelize';

import { HWY_MEMBER_EDGE_PARITY_TABLES } from '../../../domain/hwy/hwyLegacyEdgeParityTableNames';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

const cardFlowSteps = HWY_MEMBER_EDGE_PARITY_TABLES.cardPrintingFlowSteps.edge;
const securityStatuses = HWY_MEMBER_EDGE_PARITY_TABLES.securityStatuses.edge;

const parityTablesSql = `
  SELECT CASE
    WHEN OBJECT_ID(N'dbo.HWY_Members', N'U') IS NULL THEN 0
    WHEN OBJECT_ID(N'dbo.${cardFlowSteps}', N'U') IS NULL THEN 0
    WHEN OBJECT_ID(N'dbo.${securityStatuses}', N'U') IS NULL THEN 0
    WHEN COL_LENGTH(N'dbo.HWY_Members', N'Picture_FileBody_xs') IS NULL THEN 0
    ELSE 1
  END AS ok
`;

/** Enough imported HWY_* on edge to install parity views/procs (install gate). */
export const hwyLegacyImportParityTablesReady = async (): Promise<boolean> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return false;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ ok: number }>(parityTablesSql, { type: QueryTypes.SELECT });
  return Number(rows[0]?.ok) === 1;
};

/** Edge DB can serve parity lists via dbo.hwy_* procs (post-install). */
export const hwyLegacyImportParityReady = async (): Promise<boolean> => {
  if (!(await hwyLegacyImportParityTablesReady())) {
    return false;
  }
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ ok: number }>(
    `
    SELECT CASE
      WHEN OBJECT_ID(N'dbo.vw_hwy_candidate_pipeline_security', N'V') IS NULL THEN 0
      ELSE 1
    END AS ok
    `,
    { type: QueryTypes.SELECT },
  );
  return Number(rows[0]?.ok) === 1;
};
