import { resolveBaseInfoCultureId } from '../../shared/lib/baseInfoCultureTranslations';
import {
  HWY_ACTIVITY_STATUS_SEED_ROWS,
  HWY_COURSE_STATUS_SEED_ROWS,
} from './hwyCoursesActivitiesStatusCatalog';

const IQ_TITLE_BY_CODE = new Map<string, string>(
  [...HWY_ACTIVITY_STATUS_SEED_ROWS, ...HWY_COURSE_STATUS_SEED_ROWS].map((row) => [row.id, row.iqTitle]),
);

const CANONICAL_TITLE_BY_CODE = new Map<string, string>(
  [...HWY_ACTIVITY_STATUS_SEED_ROWS, ...HWY_COURSE_STATUS_SEED_ROWS].map((row) => [row.id, row.canonicalTitle]),
);

const LEGACY_STATUS_CODE_BY_CANONICAL = new Map<string, string>(
  [...HWY_ACTIVITY_STATUS_SEED_ROWS, ...HWY_COURSE_STATUS_SEED_ROWS].map((row) => [
    row.canonicalTitle.trim().toLowerCase(),
    row.id,
  ]),
);

const normalizeLegacyStatusCode = (
  statusCode: string | null | undefined,
  baseInfoTitle?: string | null,
): string => {
  const raw = String(statusCode ?? '').trim();
  if (raw && IQ_TITLE_BY_CODE.has(raw)) {
    return raw;
  }
  const fromRaw = LEGACY_STATUS_CODE_BY_CANONICAL.get(raw.toLowerCase());
  if (fromRaw) {
    return fromRaw;
  }
  const enriched = String(baseInfoTitle ?? '').trim();
  const fromTitle = LEGACY_STATUS_CODE_BY_CANONICAL.get(enriched.toLowerCase());
  if (fromTitle) {
    return fromTitle;
  }
  return raw;
};

/** Legacy `StatusId_Title` parity for Dorat/Nashatat admin grids (Arabic on iq). */
export function resolveHwyCoursesActivitiesStatusLocalizedTitle(
  statusCode: string | null | undefined,
  cultureOrLang: string,
  baseInfoTitle?: string | null,
): string | undefined {
  const code = normalizeLegacyStatusCode(statusCode, baseInfoTitle);
  const enriched = String(baseInfoTitle ?? '').trim();

  if (!code && !enriched) {
    return undefined;
  }

  const cultureId = resolveBaseInfoCultureId(cultureOrLang);
  const iqTitle = code ? IQ_TITLE_BY_CODE.get(code) : undefined;
  const canonical = code ? CANONICAL_TITLE_BY_CODE.get(code) : undefined;

  // Legacy HWY_BaseInformation titles are Arabic; only `us` shows English canonical labels.
  if (iqTitle && cultureId !== 'us') {
    return iqTitle;
  }

  if (enriched && enriched !== code) {
    return enriched;
  }

  if (canonical) {
    return canonical;
  }

  return iqTitle || enriched || undefined;
}
