/**
 * Install dbo.vw_hwy_members + edge model (read-only list projection).
 *
 *   npm run hwy:member-view
 */
import { readFileSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { createEdgeDbQueryExecutor } from '../../src/core/database/EdgeDbRouter';
import { SETTINGS_PATH } from '../../src/server/config/settingsFile';
import { getDataSourcesFromSettings } from '../../src/server/db/dataSourcesStore';
import { ensureControlPlaneInitialized, resetControlPlaneInitState } from '../../src/server/db/controlPlaneInit';
import { closePrismaControlPlane } from '../../src/server/db/prismaControlPlane';
import { EdgeModelService } from '../../src/server/services/data-api/edgeModelService';
import { listEdgeModels } from '../../src/server/services/data-api/edgeModelStore';
import sql from 'mssql';
import { readControlPlaneDatabaseSettings } from '../../src/server/db/controlPlaneDatabase';
import { buildMssqlConfigFromControlPlaneUrl } from '../../src/server/db/mssqlControlPlaneConfig';
import { resolveHwyDefaultDataSource } from './hwyDataSource';

export const HWY_MEMBER_VIEW_OBJECT = 'vw_hwy_members';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const viewSqlPath = path.join(scriptDir, 'db', 'install', 'vw_hwy_members.sqlserver.sql');
const titlePathColumnSqlPath = path.join(scriptDir, 'db', 'install', 'base_info_title_path.sqlserver.sql');
const geoFunctionsSqlPath = path.join(scriptDir, 'db', 'install', 'hwy_geo_sql_functions.sqlserver.sql');

const runSqlBatches = async (filePath: string): Promise<void> => {
  const ddl = readFileSync(filePath, 'utf8');
  const batches = ddl.split(/^\s*GO\s*$/gim).map((b) => b.trim()).filter(Boolean);
  const settings = readControlPlaneDatabaseSettings(SETTINGS_PATH);
  const pool = await new sql.ConnectionPool(buildMssqlConfigFromControlPlaneUrl(settings.url)).connect();
  try {
    for (const batch of batches) {
      await pool.request().query(batch);
    }
  } finally {
    await pool.close();
  }
};

const runViewSql = async (): Promise<void> => {
  const { kind } = resolveHwyDefaultDataSource();
  if (kind !== 'sqlserver') {
    throw new Error('vw_hwy_members currently requires SQL Server (same as control plane).');
  }
  await runSqlBatches(titlePathColumnSqlPath);
  await runSqlBatches(geoFunctionsSqlPath);
  await runSqlBatches(viewSqlPath);
};

const ensureEdgeModel = async (): Promise<string> => {
  const { source } = resolveHwyDefaultDataSource();
  const getDataSources = () => getDataSourcesFromSettings(SETTINGS_PATH);
  const edgeModelService = new EdgeModelService({
    settingsPath: SETTINGS_PATH,
    edgeDbQuery: createEdgeDbQueryExecutor({ getDataSources }),
    getDataSources,
  });

  const existing = listEdgeModels().find(
    (m) => m.dataSourceId === source.id && m.objectName === HWY_MEMBER_VIEW_OBJECT,
  );
  if (existing) {
    const refreshed = await edgeModelService.refreshModel(existing.id);
    console.log(`  edge model refreshed: ${HWY_MEMBER_VIEW_OBJECT} (${refreshed.id})`);
    return refreshed.id;
  }
  const imported = await edgeModelService.importModel({
    dataSourceId: source.id,
    objectName: HWY_MEMBER_VIEW_OBJECT,
    objectType: 'VIEW',
  });
  console.log(`  edge model imported: ${HWY_MEMBER_VIEW_OBJECT} (${imported.id})`);
  return imported.id;
};

export const runInstallHwyMemberView = async (): Promise<void> => {
  await runViewSql();
  await ensureEdgeModel();
};

const main = async (): Promise<void> => {
  resetControlPlaneInitState();
  await ensureControlPlaneInitialized(SETTINGS_PATH, { pushSchema: false });
  console.log('[HWY] Installing vw_hwy_members…');
  await runInstallHwyMemberView();
  console.log('[HWY] Member view ready.');
};

const isDirectRun = process.argv[1]?.includes('install-hwy-member-view');
if (isDirectRun) {
  main()
    .catch((e) => {
      console.error(e);
      process.exitCode = 1;
    })
    .finally(() => closePrismaControlPlane());
}
