/** Read EXEC result columns regardless of SQL Server / driver casing. */
export function readHwyProcedureRowValue(
  row: Record<string, unknown>,
  field: string,
): unknown {
  const direct = row[field];
  if (direct !== undefined && direct !== null) {
    return direct;
  }
  const target = field.toLowerCase();
  for (const [key, value] of Object.entries(row)) {
    if (value !== undefined && value !== null && key.toLowerCase() === target) {
      return value;
    }
  }
  return undefined;
}

export function readHwyProcedureRowUserId(
  row: Record<string, unknown>,
  ...fields: string[]
): number | null {
  for (const field of fields) {
    const raw = readHwyProcedureRowValue(row, field);
    if (raw === undefined || raw === null || String(raw).trim() === '') {
      continue;
    }
    const parsed = typeof raw === 'bigint' ? Number(raw) : Number(raw);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed;
    }
  }
  return null;
}
