import type {
  HwyMemberSimilarMembersAnchor,
  HwyMemberSimilarMembersFilter,
  HwyMemberSimilarMemberRow,
  HwyMemberSimilarMembersPayload,
} from '../../../domain/hwy/hwyMemberSimilarMembers';
import {
  HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER,
  normalizeHwySimilarMemberPhone,
  parseHwyMemberSimilarMembersFilter,
} from '../../../domain/hwy/hwyMemberSimilarMembers';

export { parseHwyMemberSimilarMembersFilter };
import { resolveBaseInfoCultureId } from '../../../shared/lib/baseInfoCultureTranslations';
import { attachListAddrProvinceTitles } from './hwyMemberDirectoryDetailDisplay';
import { attachImageFixRegistrationThumbsToMemberDirectoryRows } from './hwyMemberDirectoryListImageFixThumbs';
import { listBaseInfoEnrichmentRowsByIds } from '../base-info/treeRepository';
import { readControlPlaneProvider } from '../users/prismaHelpers';
import { ensureHwyDbObjects } from './ensureHwyDbObjects';
import { execHwyProcedure } from './hwyExecDbObject';
import { formatHwyMemberPersonDisplayName } from '../../../domain/hwy/hwyMemberPersonDisplayName';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';

const SIMILAR_MEMBER_LIMIT = 100;

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const readRowString = (row: Record<string, unknown>, key: string): string => {
  const raw = row[key];
  if (raw === null || raw === undefined) {
    return '';
  }
  return String(raw).trim();
};

const maskSimilarMemberRows = async (
  rows: Record<string, unknown>[],
  session: SessionScopeSnapshot | null | undefined,
): Promise<void> => {
  if (rows.length === 0) {
    return;
  }
  const sequelize = getControlPlaneSequelize();
  await applyHwyMemberIdentityFieldMasksToRows(sequelize, rows, session ?? null);
};

/** List face parity: platform avatar URL, else registration personal photo (`HWY_Members_List_Imagefix`). */
const enrichSimilarMemberRowFaces = async (rows: Record<string, unknown>[]): Promise<void> => {
  if (rows.length === 0) {
    return;
  }
  await attachImageFixRegistrationThumbsToMemberDirectoryRows(rows);
};

const finalizeSimilarMemberRows = async (
  rows: Record<string, unknown>[],
  queryLang: string,
  session: SessionScopeSnapshot | null | undefined,
): Promise<HwyMemberSimilarMemberRow[]> => {
  await maskSimilarMemberRows(rows, session);
  await enrichSimilarMemberRowFaces(rows);
  await attachListAddrProvinceTitles(rows, queryLang);
  return rows.map(mapSimilarRow);
};

const mapSimilarRow = (row: Record<string, unknown>): HwyMemberSimilarMemberRow => ({
  id: readRowString(row, 'id'),
  username: readRowString(row, 'username') || undefined,
  displayFullName: formatHwyMemberPersonDisplayName(readRowString(row, 'displayFullName')) || undefined,
  birthYear: readRowString(row, 'birthYear') || undefined,
  phone1: readRowString(row, 'phone1') || undefined,
  phone2: readRowString(row, 'phone2') || undefined,
  membershipStatusCode: readRowString(row, 'membershipStatusCode') || undefined,
  avatarUrl: readRowString(row, 'avatarUrl') || undefined,
  nakhebinId: readRowString(row, 'nakhebinId') || undefined,
  familyCode: readRowString(row, 'familyCode') || undefined,
  membershipOn: readRowString(row, 'membershipOn') || undefined,
  electoralDivisionPath: readRowString(row, 'electoralDivisionPath') || undefined,
  addrProvinceId: readRowString(row, 'addrProvinceId') || undefined,
  addrProvinceTitle: readRowString(row, 'addrProvinceTitle') || undefined,
});

const enrichMembershipStatusTitles = async (
  rows: HwyMemberSimilarMemberRow[],
  cultureId: string,
): Promise<void> => {
  const ids = new Set<string>();
  for (const row of rows) {
    const code = row.membershipStatusCode?.trim();
    if (code) {
      ids.add(code);
    }
  }
  if (ids.size === 0) {
    return;
  }
  const enriched = await listBaseInfoEnrichmentRowsByIds([...ids], cultureId);
  const byId = new Map(enriched.map((item) => [String(item.id ?? '').trim(), item]));
  for (const row of rows) {
    const code = row.membershipStatusCode?.trim();
    if (!code) {
      continue;
    }
    const match = byId.get(code);
    const title = String(match?.title ?? match?.title_canonical ?? '').trim();
    const uiColor = String(match?.ui_color ?? '').trim();
    if (title) {
      row.membershipStatusCodeTitle = title;
    }
    if (uiColor) {
      row.membershipStatusCodeTitleUiColor = uiColor;
    }
  }
};

const loadAnchorMember = async (
  memberId: number,
  queryLang: string,
): Promise<HwyMemberSimilarMembersAnchor | null> => {
  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_member_similar_anchor', {
    member_id: memberId,
  });
  if (!rows.length) {
    return null;
  }
  const row = rows[0];
  await attachListAddrProvinceTitles([row], queryLang);
  return {
    memberId: readRowString(row, 'memberId'),
    phone1: readRowString(row, 'phone1') || undefined,
    phone2: readRowString(row, 'phone2') || undefined,
    firstname: readRowString(row, 'firstname') || undefined,
    fathername: readRowString(row, 'fathername') || undefined,
    grandfathername: readRowString(row, 'grandfathername') || undefined,
    lastname: readRowString(row, 'lastname') || undefined,
    birthYear: readRowString(row, 'birthYear') || undefined,
    displayFullName: formatHwyMemberPersonDisplayName(readRowString(row, 'displayFullName')) || undefined,
    username: readRowString(row, 'username') || undefined,
    provinceTitle: readRowString(row, 'addrProvinceTitle') || undefined,
  };
};

const listSimilarByNames = async (
  memberId: number,
  anchor: HwyMemberSimilarMembersAnchor,
  queryLang: string,
  session: SessionScopeSnapshot | null | undefined,
): Promise<HwyMemberSimilarMemberRow[]> => {
  const firstname = anchor.firstname?.trim() ?? '';
  const fathername = anchor.fathername?.trim() ?? '';
  const grandfathername = anchor.grandfathername?.trim() ?? '';
  if (!firstname && !fathername && !grandfathername) {
    return [];
  }

  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_member_similar_by_names', {
    member_id: memberId,
    firstname,
    fathername,
    grandfathername,
    row_limit: SIMILAR_MEMBER_LIMIT,
  });
  return finalizeSimilarMemberRows(rows, queryLang, session);
};

const listSimilarByFilter = async (
  memberId: number,
  anchor: HwyMemberSimilarMembersAnchor,
  filter: HwyMemberSimilarMembersFilter,
  queryLang: string,
  session: SessionScopeSnapshot | null | undefined,
): Promise<HwyMemberSimilarMemberRow[]> => {
  const phoneDigits = filter.matchPhone1 ? normalizeHwySimilarMemberPhone(anchor.phone1) : '';
  if (filter.matchPhone1 && !phoneDigits) {
    return [];
  }

  await ensureHwyDbObjects();
  const rows = await execHwyProcedure<Record<string, unknown>>('hwy_member_similar_by_filter', {
    member_id: memberId,
    match_first_name: filter.matchFirstName,
    match_father_name: filter.matchFatherName,
    match_grandfather_name: filter.matchGrandfatherName,
    match_birth_year: filter.matchBirthYear,
    match_phone1: filter.matchPhone1,
    firstname: anchor.firstname?.trim() ?? '',
    fathername: anchor.fathername?.trim() ?? '',
    grandfathername: anchor.grandfathername?.trim() ?? '',
    birth_year: anchor.birthYear?.trim() ?? '',
    phone_digits: phoneDigits,
    row_limit: SIMILAR_MEMBER_LIMIT,
  });
  return finalizeSimilarMemberRows(rows, queryLang, session);
};

export async function listHwyMemberSimilarMembers(
  memberIdRaw: string,
  filterInput: HwyMemberSimilarMembersFilter | null | undefined,
  queryLang = 'ar',
  session: SessionScopeSnapshot | null | undefined = null,
): Promise<HwyMemberSimilarMembersPayload> {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Similar members are not available in this environment.');
  }
  const memberId = parseMemberId(memberIdRaw);
  const appliedFilter = filterInput ?? HWY_MEMBER_SIMILAR_MEMBERS_DEFAULT_FILTER;

  const anchor = await loadAnchorMember(memberId, queryLang);
  if (!anchor) {
    throw new Error('Member not found.');
  }

  const cultureId = resolveBaseInfoCultureId(queryLang);
  const [byName, byFilter] = await Promise.all([
    listSimilarByNames(memberId, anchor, queryLang, session),
    listSimilarByFilter(memberId, anchor, appliedFilter, queryLang, session),
  ]);

  await enrichMembershipStatusTitles(byName, cultureId);
  await enrichMembershipStatusTitles(byFilter, cultureId);

  return {
    anchor,
    byName,
    byFilter,
    appliedFilter,
  };
}
