export type HwyEmployeesListSearchInput = {
  username?: string;
  phone?: string;
  firstName?: string;
  fatherName?: string;
  grandFatherName?: string;
  lastName?: string;
  genderId?: string;
  roleId?: string;
  vProvinceId?: string;
  vCircleId?: string;
  vTamvinId?: string;
  vHasGhasam?: string;
  vAreaHasProblem?: string;
  vFieldsCompleted?: string;
  page?: number;
  pageSize?: number;
};

export type HwyEmployeesListProcParams = {
  username: string | null;
  phone: string | null;
  first_name: string | null;
  father_name: string | null;
  grandfather_name: string | null;
  last_name: string | null;
  gender_id: string | null;
  role_id: string | null;
  v_province_id: number;
  v_circle_id: number;
  v_tamvin_id: number;
  v_has_ghasam: string;
  v_area_has_problem: string;
  v_fields_completed: string;
  offset: number;
  page_size: number;
};

const trimOrNull = (value: string | undefined): string | null => {
  const trimmed = String(value ?? '').trim();
  return trimmed.length > 0 ? trimmed : null;
};

const parseGeoFilterId = (value: string | undefined): number => {
  const trimmed = String(value ?? '').trim();
  if (!trimmed || trimmed === '-1') return -1;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : -1;
};

const parseTriState = (value: string | undefined, defaultValue = '-1'): string => {
  const trimmed = String(value ?? '').trim();
  if (!trimmed) return defaultValue;
  if (trimmed === '-1' || trimmed === '0' || trimmed === '1') return trimmed;
  return defaultValue;
};

/** Maps Studio list filters to edge proc parameters (legacy Read_Employees parity). */
export const buildHwyEmployeesListProcParams = (
  input: HwyEmployeesListSearchInput,
): HwyEmployeesListProcParams => {
  const pageSize = Math.min(100, Math.max(1, input.pageSize ?? 25));
  const page = Math.max(1, input.page ?? 1);
  return {
    username: trimOrNull(input.username),
    phone: trimOrNull(input.phone),
    first_name: trimOrNull(input.firstName),
    father_name: trimOrNull(input.fatherName),
    grandfather_name: trimOrNull(input.grandFatherName),
    last_name: trimOrNull(input.lastName),
    gender_id: trimOrNull(input.genderId),
    role_id: trimOrNull(input.roleId),
    v_province_id: parseGeoFilterId(input.vProvinceId),
    v_circle_id: parseGeoFilterId(input.vCircleId),
    v_tamvin_id: parseGeoFilterId(input.vTamvinId),
    v_has_ghasam: parseTriState(input.vHasGhasam),
    v_area_has_problem: parseTriState(input.vAreaHasProblem),
    v_fields_completed: parseTriState(input.vFieldsCompleted),
    offset: (page - 1) * pageSize,
    page_size: pageSize,
  };
};

export const buildHwyEmployeesListLegacyWhereSql = (
  params: Pick<
    HwyEmployeesListProcParams,
    | 'username'
    | 'phone'
    | 'first_name'
    | 'father_name'
    | 'grandfather_name'
    | 'last_name'
    | 'gender_id'
    | 'role_id'
    | 'v_province_id'
    | 'v_circle_id'
    | 'v_tamvin_id'
    | 'v_has_ghasam'
    | 'v_area_has_problem'
    | 'v_fields_completed'
  >,
  alias = 'M',
): string => {
  const esc = (value: string): string => value.replace(/'/g, "''");
  let w = '';

  if (params.username) w += ` AND ${alias}.UserName LIKE '%${esc(params.username)}%'`;
  if (params.phone) w += ` AND ${alias}.Phone1 LIKE '%${esc(params.phone)}%'`;
  if (params.first_name) w += ` AND ${alias}.FirstName LIKE '%${esc(params.first_name)}%'`;
  if (params.father_name) w += ` AND ${alias}.FatherName LIKE '%${esc(params.father_name)}%'`;
  if (params.grandfather_name) w += ` AND ${alias}.GrandFatherName LIKE '%${esc(params.grandfather_name)}%'`;
  if (params.last_name) w += ` AND ${alias}.LastName LIKE '%${esc(params.last_name)}%'`;
  if (params.gender_id) w += ` AND CAST(${alias}.GenderId AS VARCHAR(32))='${esc(params.gender_id)}'`;
  if (params.role_id) {
    w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.UserId AND CAST(URR.RoleId AS VARCHAR(32))='${esc(params.role_id)}')`;
  }
  if (params.v_province_id !== -1) {
    w += ` AND (${alias}.AreaLimitProvinceId=${params.v_province_id} OR ${params.v_province_id} IN (SELECT ItemId FROM dbo.HWY_Members_AreaLimits WITH (NOLOCK) WHERE MemberId=${alias}.Id))`;
  }
  if (params.v_circle_id !== -1) {
    w += ` AND (${alias}.AreaLimitCircleId=${params.v_circle_id} OR ${params.v_circle_id} IN (SELECT ItemId FROM dbo.HWY_Members_AreaLimits WITH (NOLOCK) WHERE MemberId=${alias}.Id))`;
  }
  if (params.v_tamvin_id !== -1) {
    w += ` AND (${alias}.AreaLimitTamvinId=${params.v_tamvin_id} OR ${params.v_tamvin_id} IN (SELECT ItemId FROM dbo.HWY_Members_AreaLimits WITH (NOLOCK) WHERE MemberId=${alias}.Id))`;
  }
  if (params.v_has_ghasam === '0') w += ` AND ${alias}.Oath_FileBody IS NULL`;
  else if (params.v_has_ghasam === '1') w += ` AND ${alias}.Oath_FileBody IS NOT NULL`;
  if (params.v_area_has_problem === '1') {
    w += ` AND ISNULL(${alias}.AreaLimitId,0)<>111321 AND (SELECT TOP 1 AL.ItemId FROM dbo.HWY_Members_AreaLimits AL WITH (NOLOCK) WHERE AL.MemberId=${alias}.Id) IS NULL`;
  }
  if (params.v_fields_completed === '1') w += ` AND ISNULL(${alias}.Stat_FieldsCompleted,0)=100`;
  else if (params.v_fields_completed === '0') w += ` AND ISNULL(${alias}.Stat_FieldsCompleted,0)<100`;

  return w;
};
