import type { HwyMemberRegistrationFileKindSlug } from '../hwyMemberFileKindCatalog';
import { HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT } from '../hwyMemberFileKindCatalog';
/** Multipart field names on public self-registration submit. */
export const HWY_SELF_REGISTRATION_ATTACHMENT_FIELD_NAMES = [
  'personalPhoto',
  'nationalCardFront',
  'nationalCardBack',
  'voterCard',
  'residenceCard',
  'mehaniLicenseFile',
] as const;

export type HwySelfRegistrationAttachmentFieldName =
  (typeof HWY_SELF_REGISTRATION_ATTACHMENT_FIELD_NAMES)[number];

const FIELD_TO_KIND_SLUG: Record<
  HwySelfRegistrationAttachmentFieldName,
  HwyMemberRegistrationFileKindSlug | typeof HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT
> = {
  personalPhoto: 'personal_photo',
  nationalCardFront: 'national_card_front',
  nationalCardBack: 'national_card_back',
  voterCard: 'voter_card_front',
  residenceCard: 'residence_card_front',
  mehaniLicenseFile: HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT,
};

export function resolveHwySelfRegistrationAttachmentKindSlug(
  fieldName: string,
): HwyMemberRegistrationFileKindSlug | typeof HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT | null {
  const key = fieldName.trim() as HwySelfRegistrationAttachmentFieldName;
  return FIELD_TO_KIND_SLUG[key] ?? null;
}

export type HwySelfRegistrationSubmitAttachment = {
  kindSlug: HwyMemberRegistrationFileKindSlug | typeof HWY_MEMBER_FILE_KIND_OTHER_ATTACHMENT;
  fileName: string;
  mime: string;
  body: Buffer;
};

export function appendHwySelfRegistrationAttachmentsToFormData(
  formData: FormData,
  files: Partial<Record<HwySelfRegistrationAttachmentFieldName, File[]>>,
): void {
  for (const field of HWY_SELF_REGISTRATION_ATTACHMENT_FIELD_NAMES) {
    const file = files[field]?.[0];
    if (file) {
      formData.append(field, file, file.name);
    }
  }
}
