import { QueryTypes } from 'sequelize';
import type { HwyMemberDirectoryIdentityFieldPolicy } from '../../../domain/hwy/hwyMemberIdentityFieldMask';
import { isHwyMemberDossierProfilePhotoKindSlug } from '../../../domain/hwy/hwyMemberFileKindCatalog';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { applyHwyMemberIdentityFieldMasksToRows } from './applyHwyMemberIdentityFieldMasks';
import type { SessionScopeSnapshot } from '../../services/record-policy/sessionScope.service';
import { resolveHwyMemberFileKindBySlugOrId } from './hwyMemberFileKindResolve.service';

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

/** Loads legacy identity mask policy for one member (same rules as dossier getOne / PATCH). */
export async function loadHwyMemberDirectoryIdentityFieldPolicyForMember(
  memberIdRaw: string | number,
  session: SessionScopeSnapshot | null | undefined,
): Promise<HwyMemberDirectoryIdentityFieldPolicy | undefined> {
  const memberId = typeof memberIdRaw === 'number' ? memberIdRaw : parseMemberId(memberIdRaw);
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `
      SELECT id, gender_code, first_name, phone1, phone2
      FROM dbo.hwy_members
      WHERE id = :id
    `,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  if (!rows[0]) {
    throw new Error('Member not found.');
  }
  const policyRow: Record<string, unknown> = {
    ...rows[0],
    id: memberId,
    genderCode: rows[0].gender_code,
    firstname: rows[0].first_name,
  };
  await applyHwyMemberIdentityFieldMasksToRows(sequelize, [policyRow], session ?? null, {
    attachIdentityFieldPolicy: true,
  });
  return policyRow.identityFieldPolicy as HwyMemberDirectoryIdentityFieldPolicy | undefined;
}

export async function assertHwyMemberDossierFileUploadAllowed(input: {
  memberId: string;
  fileKindCode: string;
  session: SessionScopeSnapshot | null | undefined;
}): Promise<void> {
  const resolvedKind = await resolveHwyMemberFileKindBySlugOrId(input.fileKindCode.trim());
  const slug = resolvedKind?.shortName?.trim() ?? input.fileKindCode.trim();
  if (!isHwyMemberDossierProfilePhotoKindSlug(slug)) {
    return;
  }
  const policy = await loadHwyMemberDirectoryIdentityFieldPolicyForMember(input.memberId, input.session);
  if (policy?.personalPhotoReadOnly) {
    throw new Error('Forbidden.');
  }
}
