import sql from 'mssql';
import { readLegacyConn, withLegacyReadOnlyIntent } from '../../../../scripts/hwy-etl/legacyConn';
import { HWY_MEMBER_TARGHIN_REQUEST_REASON_STATIC_CATALOG } from '../../../domain/hwy/hwyMemberTarghinRequestReasonCatalog';
import { HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID } from '../../../domain/hwy/hwyMemberTarghinRequestReasons';
import { prisma } from '../users/prismaHelpers';
import {
  getLegacyHwyBaseInformationById,
  type LegacyHwyBaseInformationRow,
} from './hwyLegacyBaseInformationReader';

type LegacyTarghinReasonRecord = {
  Id: number;
  Title: string | null;
  ViewOrder: number | null;
  IsActive: boolean | number | null;
  Note?: string | null;
  ParentId?: number | null;
};

const LEGACY_PARENT_ID = Number(HWY_MEMBER_TARGHIN_REQUEST_REASON_LEGACY_PARENT_ID);

export const listStaticHwyMemberTarghinRequestReasonRows = (): LegacyHwyBaseInformationRow[] => (
  HWY_MEMBER_TARGHIN_REQUEST_REASON_STATIC_CATALOG.map((row) => ({
    id: row.legacyId,
    title: row.title,
    viewOrder: row.viewOrder,
    isActive: true,
    parentId: LEGACY_PARENT_ID,
  }))
);

export const listLegacyHwyMemberTarghinRequestReasonRows = async (
  parentLegacyId: number = LEGACY_PARENT_ID,
): Promise<LegacyHwyBaseInformationRow[]> => {
  try {
    const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();

    try {
      const result = await pool
        .request()
        .input('parentId', sql.Int, parentLegacyId)
        .query(`
          SELECT Id, Title, ViewOrder, IsActive, Note, ParentId
          FROM dbo.HWY_BaseInformation WITH (NOLOCK)
          WHERE ParentId = @parentId
          ORDER BY ViewOrder, Id
        `);

      return (result.recordset as LegacyTarghinReasonRecord[])
        .map((row) => ({
          id: row.Id,
          title: String(row.Title ?? '').trim(),
          viewOrder: row.ViewOrder,
          isActive: row.IsActive === true || row.IsActive === 1,
          note: String(row.Note ?? '').trim() || undefined,
          parentId: row.ParentId == null ? parentLegacyId : Number(row.ParentId),
        }))
        .filter((row) => row.isActive && row.title);
    } finally {
      await pool.close();
    }
  } catch {
    try {
      const pool = await new sql.ConnectionPool(withLegacyReadOnlyIntent(readLegacyConn())).connect();
      try {
        const result = await pool
          .request()
          .input('parentId', sql.Int, parentLegacyId)
          .query(`
            SELECT Id, Title, ViewOrder, IsActive
            FROM dbo.HWY_BaseInformation WITH (NOLOCK)
            WHERE ParentId = @parentId
            ORDER BY ViewOrder, Id
          `);
        return (result.recordset as LegacyTarghinReasonRecord[])
          .map((row) => ({
            id: row.Id,
            title: String(row.Title ?? '').trim(),
            viewOrder: row.ViewOrder,
            isActive: row.IsActive === true || row.IsActive === 1,
            parentId: parentLegacyId,
          }))
          .filter((row) => row.isActive && row.title);
      } finally {
        await pool.close();
      }
    } catch {
      return [];
    }
  }
};

const upsertLegacyBaseInfoNode = async (legacy: LegacyHwyBaseInformationRow): Promise<void> => {
  const id = String(legacy.id);
  const parentId = legacy.parentId != null && legacy.parentId > 0 ? String(legacy.parentId) : null;
  const viewOrder = legacy.viewOrder ?? legacy.id;
  const note = legacy.note?.trim() || null;

  await prisma().baseInfo.upsert({
    where: { id },
    update: {
      parentId,
      title: legacy.title,
      note,
      viewOrder,
      value: viewOrder,
      isActive: legacy.isActive,
      updatedBy: null,
    },
    create: {
      id,
      parentId,
      title: legacy.title,
      note,
      viewOrder,
      value: viewOrder,
      isActive: legacy.isActive,
      createdBy: null,
      updatedBy: null,
    },
  });
};

const ensureLegacyBaseInfoChain = async (legacyId: number): Promise<void> => {
  const existing = await prisma().baseInfo.findUnique({
    where: { id: String(legacyId) },
    select: { id: true },
  });
  if (existing) {
    return;
  }

  const legacy = await getLegacyHwyBaseInformationById(legacyId);
  if (!legacy?.title) {
    return;
  }

  if (legacy.parentId != null && legacy.parentId > 0) {
    await ensureLegacyBaseInfoChain(legacy.parentId);
  }

  await upsertLegacyBaseInfoNode(legacy);
};

export const syncHwyMemberTarghinBaseInfoByLegacyParentId = async (
  parentLegacyId: number,
  staticFallback?: () => LegacyHwyBaseInformationRow[],
): Promise<number> => {
  if (!Number.isFinite(parentLegacyId) || parentLegacyId <= 0) {
    return 0;
  }

  await ensureLegacyBaseInfoChain(parentLegacyId);

  let legacyChildren = await listLegacyHwyMemberTarghinRequestReasonRows(parentLegacyId);
  if (legacyChildren.length === 0 && staticFallback) {
    legacyChildren = staticFallback();
  }
  if (legacyChildren.length === 0) {
    return 0;
  }

  let synced = 0;
  for (const row of legacyChildren) {
    if (!row.isActive || !row.title) {
      continue;
    }
    await upsertLegacyBaseInfoNode({
      ...row,
      parentId: parentLegacyId,
    });
    synced += 1;
  }

  return synced;
};

/**
 * Mirror legacy `getBaseInformationByParent(212110)` into control-plane `base_info`
 * so targhin reason pickers and FK inserts work without a separate ETL step.
 */
export const syncHwyMemberTarghinRequestReasonsFromLegacy = async (): Promise<number> => (
  syncHwyMemberTarghinBaseInfoByLegacyParentId(
    LEGACY_PARENT_ID,
    listStaticHwyMemberTarghinRequestReasonRows,
  )
);
