export const resolveHwyMemberDirectoryListFaceColumnWidthForScope = (
  listScopeLegacy: string | null | undefined,
): { width: string; cellClass: string } => {
  if (String(listScopeLegacy ?? '').trim() === HWY_MEMBER_REJECTION_LIST_LEGACY_SCOPES.localManage) {
    return {
      width: HWY_MEMBER_REJECTED_LOCAL_MANAGE_FACE_COLUMN_WIDTH,
      cellClass: HWY_MEMBER_REJECTED_LOCAL_MANAGE_FACE_COLUMN_CELL_CLASS,
    };
  }
  return {
    width: HWY_MEMBER_DIRECTORY_LIST_FACE_COLUMN_WIDTH,
    cellClass: HWY_MEMBER_DIRECTORY_LIST_FACE_COLUMN_CELL_CLASS,
  };
};
