/** `hwy-members-all` member-directory grid (not queue / nakhebin list). */
export const isHwyMemberDirectoryListFaceColumn = (
  column: DesignerDataGridColumn,
): boolean => column.cellKind === 'hwy-member-face';

/** Waited / rejected / segment member-directory lists (face column, not nakhebin roll). */
export const isHwyMemberDirectorySegmentListGrid = (
  columns: ReadonlyArray<DesignerDataGridColumn>,
): boolean => (
  columns.some(isHwyMemberDirectoryListFaceColumn)
  && !isHwyNakhebinListGrid(columns)
);

export const isHwyMembersAllListGrid = (
  columns: ReadonlyArray<DesignerDataGridColumn>,
): boolean => columns.some((column) => column.key === 'nakhebinId')
  && columns.some((column) => isHwyMemberDirectoryListFaceColumn(column));

/** `hwy-nakhebin` voter roll list grid. */
export const isHwyNakhebinListGrid = (
  columns: ReadonlyArray<DesignerDataGridColumn>,
): boolean => columns.some((column) => column.key === 'firstName'
    && column.cellFields?.primaryField === 'voterNameLine1')
  && !columns.some((column) => column.key === 'displayFullName');

export const HWY_NAKHEBIN_LIST_VOTED_COLUMN_KEYS = new Set([
  'votedOn2021',
  'votedOn2023',
  'votedOn2025',
]);

/** Voted-year boolean columns on `hwy-nakhebin` — `5.5rem` (88px) − 10px; all three identical. */
export const HWY_NAKHEBIN_LIST_VOTED_COLUMN_WIDTH = '78px';

export const HWY_NAKHEBIN_LIST_VOTED_COLUMN_HEADER_CLASS =
  'text-center [&>div]:justify-center whitespace-nowrap text-xs';

/** Marker class — `resolveAppTableGridCellClipAlign` centers flex content for voted columns. */
export const HWY_NAKHEBIN_LIST_VOTED_COLUMN_CELL_CLASS =
  'text-center nakhebin-voted-grid-cell';

export const applyHwyNakhebinListVotedColumnCenter = (
  column: DesignerDataGridColumn,
  columns: ReadonlyArray<DesignerDataGridColumn>,
): DesignerDataGridColumn => {
  if (!isHwyNakhebinListGrid(columns) || !HWY_NAKHEBIN_LIST_VOTED_COLUMN_KEYS.has(column.key)) {
    return column;
  }
  return {
    ...column,
    width: HWY_NAKHEBIN_LIST_VOTED_COLUMN_WIDTH,
    headerClassName: HWY_NAKHEBIN_LIST_VOTED_COLUMN_HEADER_CLASS,
    cellClassName: HWY_NAKHEBIN_LIST_VOTED_COLUMN_CELL_CLASS,
  };
};

/** Voter name + region path — multi-line; use grid wrap (not clip truncate). */
export const enforceHwyNakhebinListWrapTextColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
  isNakhebinList: boolean,
): AppTableGridColumnDef<TRow> => {
  if (!isNakhebinList || (column.id !== 'firstName' && column.id !== 'electoralDivisionPath')) {
    return column;
  }
  return { ...column, wrap: true };
};

export const enforceHwyNakhebinListVotedColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
  isNakhebinList: boolean,
): AppTableGridColumnDef<TRow> => {
  if (!isNakhebinList || !HWY_NAKHEBIN_LIST_VOTED_COLUMN_KEYS.has(column.id)) {
    return column;
  }
  const width = HWY_NAKHEBIN_LIST_VOTED_COLUMN_WIDTH;
  return {
    ...column,
    width,
    minWidth: width,
    maxWidth: width,
  };
};

/** Member directory + nakhebin list person-name account columns (two-line name display). */
export const isHwyMemberNakhebinListNameColumn = (
  column: DesignerDataGridColumn,
): boolean => {
  if (isHwyMemberDirectoryListFaceColumn(column)) {
    return false;
  }
  if (column.cellKind !== 'account') {
    return false;
  }
  if (column.key === 'displayFullName') {
    return column.cellFields?.primaryField === 'displayFullName';
  }
  if (column.key === 'firstName') {
    return column.cellFields?.primaryField === 'voterNameLine1';
  }
  return false;
};

export const applyHwyMemberDirectoryListFaceColumnWidth = (
  column: DesignerDataGridColumn,
  listScopeLegacy?: string | null,
): DesignerDataGridColumn => {
  if (!isHwyMemberDirectoryListFaceColumn(column)) {
    return column;
  }
  const { width, cellClass } = resolveHwyMemberDirectoryListFaceColumnWidthForScope(listScopeLegacy);
  return {
    ...column,
    width,
    cellClassName: cn(column.cellClassName, cellClass),
  };
};

export const applyHwyMemberNakhebinListNameColumnWidth = (
  column: DesignerDataGridColumn,
): DesignerDataGridColumn => {
  if (!isHwyMemberNakhebinListNameColumn(column)) {
    return column;
  }
  return {
    ...column,
    width: HWY_MEMBER_NAKHEBIN_LIST_NAME_COLUMN_WIDTH,
    cellClassName: HWY_MEMBER_NAKHEBIN_LIST_NAME_COLUMN_CELL_CLASS,
  };
};

export const enforceHwyMemberDirectoryListFaceColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
  context?: {
    isMemberDirectoryFaceGrid?: boolean;
    listScopeLegacy?: string | null;
  },
): AppTableGridColumnDef<TRow> => {
  if (column.id !== 'displayFullName') {
    return column;
  }
  const { width, cellClass } = resolveHwyMemberDirectoryListFaceColumnWidthForScope(
    context?.listScopeLegacy,
  );
  const legacyFaceWidths = new Set([
    '223px',
    '253px',
    '243px',
    HWY_MEMBER_DIRECTORY_LIST_FACE_COLUMN_WIDTH,
    HWY_MEMBER_REJECTED_LOCAL_MANAGE_FACE_COLUMN_WIDTH,
  ]);
  const shouldLockFaceWidth = context?.isMemberDirectoryFaceGrid
    || legacyFaceWidths.has(String(column.width ?? ''));
  if (!shouldLockFaceWidth) {
    return column;
  }
  return {
    ...column,
    width,
    minWidth: width,
    maxWidth: width,
    wrap: true,
    cellClassName: cn(column.cellClassName, cellClass),
  };
};

export const enforceHwyMemberNakhebinListNameColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
): AppTableGridColumnDef<TRow> => {
  const isNameColumn = column.id === 'displayFullName'
    || (column.id === 'firstName' && column.cellClassName?.includes('leading-snug'));
  if (!isNameColumn || column.width === HWY_MEMBER_DIRECTORY_LIST_FACE_COLUMN_WIDTH) {
    return column;
  }
  const width = HWY_MEMBER_NAKHEBIN_LIST_NAME_COLUMN_WIDTH;
  const cellClassName = (column.cellClassName ?? '')
    .replace(/max-w-\[14rem\]/g, 'max-w-[154px]')
    .replace(/max-w-\[144px\]/g, 'max-w-[154px]')
    .trim();
  return {
    ...column,
    width,
    minWidth: width,
    maxWidth: width,
    cellClassName: cellClassName.includes('max-w-[154px]')
      ? cellClassName
      : HWY_MEMBER_NAKHEBIN_LIST_NAME_COLUMN_CELL_CLASS,
  };
};

