/** Vertical center in tall member rows — `resolveAppTableGridCellClipAlign` flexes inner content. */
export const HWY_MEMBER_DIRECTORY_ELECTORAL_COLUMN_CELL_CLASS = 'hwy-electoral-division-grid-cell align-middle';

const memberDirectoryColumnKey = (column: { key?: string; id?: string }): string =>
  String(column.key ?? column.id ?? '').trim();

/** Member-directory grids: المركز الانتخابي is always the third column (after face + phone). */
export const reorderHwyMemberDirectoryElectoralColumnThird = <T extends { key?: string; id?: string }>(
  columns: T[],
): T[] => {
  const electoralIdx = columns.findIndex((column) => memberDirectoryColumnKey(column) === 'electoralDivisionPath');
  if (electoralIdx < 0) {
    return columns;
  }
  const phoneIdx = columns.findIndex((column) => memberDirectoryColumnKey(column) === 'phone1');
  const targetIdx = phoneIdx >= 0 ? phoneIdx + 1 : 2;
  if (electoralIdx === targetIdx) {
    return columns;
  }
  const next = [...columns];
  const [electoral] = next.splice(electoralIdx, 1);
  const insertAt = electoralIdx < targetIdx ? targetIdx - 1 : targetIdx;
  next.splice(insertAt, 0, electoral!);
  return next;
};

export const applyHwyMemberDirectoryElectoralColumnCellAlign = (
  column: DesignerDataGridColumn,
): DesignerDataGridColumn => {
  if (column.key !== 'electoralDivisionPath') {
    return column;
  }
  const existing = column.cellClassName ?? '';
  if (existing.includes('hwy-electoral-division-grid-cell')) {
    return column;
  }
  return {
    ...column,
    cellClassName: `${existing} ${HWY_MEMBER_DIRECTORY_ELECTORAL_COLUMN_CELL_CLASS}`.trim(),
  };
};

export const isHwyMemberDirectoryElectoralStyleGridColumnId = (columnId: string): boolean => (
  columnId === 'electoralDivisionPath' || columnId === 'patch'
);

/** Electoral path on member-directory queue / segment lists — multi-line, stable min width in RTL split headers. */
export const enforceHwyMemberDirectoryElectoralColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
  isMemberDirectorySegmentList: boolean,
): AppTableGridColumnDef<TRow> => {
  if (!isHwyMemberDirectoryElectoralStyleGridColumnId(String(column.id))) {
    return column;
  }
  const minWidth = isMemberDirectorySegmentList ? '11rem' : undefined;
  return {
    ...column,
    wrap: true,
    ...(minWidth ? { minWidth } : {}),
    cellClassName: cn(column.cellClassName, HWY_MEMBER_DIRECTORY_ELECTORAL_COLUMN_CELL_CLASS),
  };
};

const HWY_MEMBER_DIRECTORY_SEGMENT_LIST_RTL_COLUMN_IDS = new Set([
  'displayFullName',
  'electoralDivisionPath',
  'patch',
]);

/** Explicit RTL on member + region columns when shell is RTL (split-header parity). */
export const enforceHwyMemberDirectorySegmentListRtlColumnGridDef = <TRow>(
  column: AppTableGridColumnDef<TRow>,
  isMemberDirectorySegmentList: boolean,
  shellIsRtl: boolean,
): AppTableGridColumnDef<TRow> => {
  if (
    !isMemberDirectorySegmentList
    || !shellIsRtl
    || !HWY_MEMBER_DIRECTORY_SEGMENT_LIST_RTL_COLUMN_IDS.has(column.id)
  ) {
    return column;
  }
  return {
    ...column,
    textDirection: 'rtl',
    wrap: column.id === 'displayFullName' ? true : column.wrap ?? true,
    headerClassName: cn(
      column.headerClassName,
      'text-start [&>div]:justify-start',
    ),
    cellClassName: cn(
      column.cellClassName,
      'text-start',
      column.id === 'electoralDivisionPath' ? 'align-middle' : 'align-top',
      column.id === 'electoralDivisionPath' ? HWY_MEMBER_DIRECTORY_ELECTORAL_COLUMN_CELL_CLASS : '',
    ),
  };
};

