/** Legacy `HWY_BaseInformation.Id` for Iraqi governorates (محافظة) under parent 10101. */
export const HWY_SELF_REGISTRATION_LEGACY_PROVINCE_LIST_PARENT_ID = 10101;

const HWY_PROVINCE_SHORT_NAME = /^hwy-province-(\d+)$/i;

export type HwySelfRegistrationAddressGeoOption = {
  /** Legacy `HWY_BaseInformation.Id` — stored in `addr_province_id` / `addr_district_id`. */
  legacyId: string;
  label: string;
};

/** Legacy id for Baghdad (بغداد) — stable dev/QA default when lists load. */
export const HWY_SELF_REGISTRATION_DEFAULT_PROVINCE_LEGACY_ID = '10102';

export const isHwySelfRegistrationProvinceInOptions = (
  provinceLegacyId: string,
  options: ReadonlyArray<Pick<HwySelfRegistrationAddressGeoOption, 'legacyId'>>,
): boolean => {
  const trimmed = provinceLegacyId.trim();
  if (!trimmed) {
    return false;
  }
  if (options.length === 0) {
    return /^\d+$/.test(trimmed);
  }
  return options.some((option) => option.legacyId === trimmed);
};

export const isHwySelfRegistrationDistrictInOptions = (
  districtLegacyId: string,
  options: ReadonlyArray<Pick<HwySelfRegistrationAddressGeoOption, 'legacyId'>>,
): boolean => {
  const trimmed = districtLegacyId.trim();
  if (!trimmed) {
    return true;
  }
  if (options.length === 0) {
    return /^\d+$/.test(trimmed);
  }
  return options.some((option) => option.legacyId === trimmed);
};

export const legacyGeoIdFromHwyProvinceShortName = (
  shortName: string | null | undefined,
): string | null => {
  const match = HWY_PROVINCE_SHORT_NAME.exec(String(shortName ?? '').trim());
  return match?.[1] ?? null;
};
