import { QueryTypes } from 'sequelize';

import {
  formatHwyPlatformRoleDisplayLabel,
  sortHwyPlatformRoleDisplayLabels,
} from '../../../domain/hwy/hwyPlatformRoleDisplay';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { fromUserId, prisma, toUserId } from '../users/prismaHelpers';

const parseMemberId = (raw: string | null | undefined): number | null => {
  const trimmed = String(raw ?? '').trim();
  if (!/^\d+$/.test(trimmed)) {
    return null;
  }
  const id = Number(trimmed);
  return Number.isFinite(id) && id > 0 ? id : null;
};

export async function listHwyMemberIdsByUserIds(
  userIds: readonly number[],
): Promise<Map<number, number>> {
  const uniqueUserIds = Array.from(new Set(
    userIds.filter((id) => Number.isFinite(id) && id > 0),
  ));
  const result = new Map<number, number>();
  if (uniqueUserIds.length === 0) {
    return result;
  }

  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number | string; user_id: number | string | null }>(
    `SELECT id, user_id
     FROM dbo.hwy_members
     WHERE user_id IN (:userIds)`,
    { replacements: { userIds: uniqueUserIds }, type: QueryTypes.SELECT },
  );

  for (const row of rows) {
    const memberId = Number(row.id);
    const userId = Number(row.user_id);
    if (Number.isFinite(memberId) && memberId > 0 && Number.isFinite(userId) && userId > 0) {
      result.set(userId, memberId);
    }
  }
  return result;
}

export async function listPlatformUserIdsByHwyMemberIds(
  memberIds: readonly number[],
): Promise<Map<number, number>> {
  const uniqueMemberIds = Array.from(new Set(
    memberIds.filter((id) => Number.isFinite(id) && id > 0),
  ));
  const result = new Map<number, number>();
  if (uniqueMemberIds.length === 0) {
    return result;
  }

  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: number | string; user_id: number | string | null }>(
    `SELECT id, user_id
     FROM dbo.hwy_members
     WHERE id IN (:memberIds)
       AND user_id IS NOT NULL`,
    { replacements: { memberIds: uniqueMemberIds }, type: QueryTypes.SELECT },
  );

  for (const row of rows) {
    const memberId = Number(row.id);
    const userId = Number(row.user_id);
    if (Number.isFinite(memberId) && memberId > 0 && Number.isFinite(userId) && userId > 0) {
      result.set(memberId, userId);
    }
  }
  return result;
}

export async function listHwyMemberTarghinExecutorRoleTitlesByUserId(
  userIds: readonly number[],
): Promise<Map<number, string[]>> {
  const uniqueUserIds = Array.from(new Set(
    userIds.filter((id) => Number.isFinite(id) && id > 0),
  ));
  const result = new Map<number, string[]>();
  if (uniqueUserIds.length === 0) {
    return result;
  }

  const roleRows = await prisma().baseUserRole.findMany({
    where: { userId: { in: uniqueUserIds.map((id) => toUserId(id)) } },
    select: {
      userId: true,
      roleName: true,
      role: { select: { note: true } },
    },
    orderBy: [{ userId: 'asc' }, { roleName: 'asc' }],
  });

  const labelsByUserId = new Map<number, string[]>();
  for (const row of roleRows) {
    const userId = fromUserId(row.userId);
    const label = formatHwyPlatformRoleDisplayLabel(row.roleName, row.role.note);
    const bucket = labelsByUserId.get(userId) ?? [];
    bucket.push(label);
    labelsByUserId.set(userId, bucket);
  }

  for (const [userId, labels] of labelsByUserId) {
    result.set(userId, sortHwyPlatformRoleDisplayLabels(labels));
  }
  return result;
}

export async function listHwyMemberTarghinExecutorRoleTitlesByMemberId(
  memberIds: readonly number[],
): Promise<Map<number, string[]>> {
  const userIdByMemberId = await listPlatformUserIdsByHwyMemberIds(memberIds);
  const roleTitlesByUserId = await listHwyMemberTarghinExecutorRoleTitlesByUserId(
    [...userIdByMemberId.values()],
  );
  const result = new Map<number, string[]>();
  for (const [memberId, userId] of userIdByMemberId) {
    result.set(memberId, roleTitlesByUserId.get(userId) ?? []);
  }
  return result;
}

export function parseHwyTarghinExecutorMemberId(
  executorMemberId: string | null | undefined,
): number | null {
  return parseMemberId(executorMemberId);
}
