import type { HwyMembershipStatusIdMap } from '../../../domain/hwy/hwyMembershipDecision';
import { tryFindHwyBaseInfoItemIdByShortName } from './hwyBaseInfoVocabIds';
import { loadHwyMemberListScopeContext } from './hwyMemberDirectoryListScope.service';

let cachedClientStatusMap: HwyMembershipStatusIdMap | null = null;

/** Membership status ids for dossier UI (includes optional targhin status when seeded). */
export const loadHwyMembershipStatusIdMapForClient = async (): Promise<HwyMembershipStatusIdMap> => {
  if (cachedClientStatusMap) {
    return cachedClientStatusMap;
  }
  const ctx = await loadHwyMemberListScopeContext();
  const pendingCancellation = await tryFindHwyBaseInfoItemIdByShortName(
    'Membership Status',
    'pending_cancellation',
  );
  cachedClientStatusMap = {
    ...ctx.membershipStatusCodes,
    ...(pendingCancellation ? { pending_cancellation: pendingCancellation } : {}),
  };
  return cachedClientStatusMap;
};

export const tryResolveHwyPendingCancellationStatusId = async (): Promise<string | null> => (
  tryFindHwyBaseInfoItemIdByShortName('Membership Status', 'pending_cancellation')
);
