import type { DesignerDataGridColumn } from '../component-designer/designerDataGridColumns';
import type { HwyMemberSegmentListDefinition } from './hwyMemberSegmentListCatalog';

/** Sidebar: immediately before voter roll (legacy menu). */
export const HWY_MEMBER_QUICK_SEARCH_NAV_ORDER = 899;

export const HWY_MEMBER_QUICK_SEARCH_NAV_SEPARATOR_BEFORE = true;

/** Legacy list scope (`HWY_Members_List_AlMontadhemin_SingleView` → `Read_List_SingleView`). Unrestricted directory. */
export const HWY_MEMBER_QUICK_SEARCH_LEGACY_LIST_SCOPE = 'HWY_Members_List_AlMontadhemin_SingleView' as const;

export const HWY_MEMBER_QUICK_SEARCH_PAGE_NAME = 'hwy-members-quick-search' as const;

export const isHwyMemberQuickSearchListScope = (
  listScopeLegacy: string | null | undefined,
): boolean => listScopeLegacy?.trim() === HWY_MEMBER_QUICK_SEARCH_LEGACY_LIST_SCOPE;

/** Quick search grid — server and client cap result rows (no paging footer). */
export const HWY_MEMBER_QUICK_SEARCH_LIST_PAGE_SIZE = 5;

const QUICK_SEARCH_REMOVED_ROLE_COLUMN_KEYS = new Set([
  'singleViewHasPlatformRole',
  'singleViewHasHawietyRole',
  'singleViewHasStudioRole',
]);

/** Dropped from quick-search grid (legacy parity trimmed). */
export const shouldHideHwyMemberQuickSearchGridColumn = (
  column: Pick<DesignerDataGridColumn, 'key' | 'cellKind'>,
): boolean => {
  if (QUICK_SEARCH_REMOVED_ROLE_COLUMN_KEYS.has(column.key)) {
    return true;
  }
  if (column.key === 'phone1' || column.key === 'nakhebinId') {
    return true;
  }
  if (column.key.startsWith('stat')) {
    return true;
  }
  if (column.key === 'displayFullName' && column.cellKind === 'account') {
    return true;
  }
  return false;
};

export const HWY_MEMBER_QUICK_SEARCH_DEFINITION: HwyMemberSegmentListDefinition = {
  legacyCode: HWY_MEMBER_QUICK_SEARCH_LEGACY_LIST_SCOPE,
  pageName: HWY_MEMBER_QUICK_SEARCH_PAGE_NAME,
  routeSegment: 'members-quick-search',
  titleEn: 'Quick member search',
  listDefCode: null,
  scope: { type: 'directory_unrestricted' },
  extraColumns: [],
  navOrder: HWY_MEMBER_QUICK_SEARCH_NAV_ORDER,
  separatorBefore: HWY_MEMBER_QUICK_SEARCH_NAV_SEPARATOR_BEFORE,
};
