import { resolveHwyBaseInfoItemTitle } from './hwyBaseInfoRuntime';
import { hashPassword } from '../../utils/bcryptAsync';

const NOTE_MAX = 4000;

const trimRequired = (value: string | null | undefined, max = NOTE_MAX): string => {
  const s = String(value ?? '').trim();
  if (!s) {
    throw new Error('Decision note is required.');
  }
  return s.length > max ? s.slice(0, max) : s;
};

const trimOptional = (value: string | null | undefined, max = NOTE_MAX): string => {
  const s = String(value ?? '').trim();
  if (!s) {
    return '';
  }
  return s.length > max ? s.slice(0, max) : s;
};

const LEGACY_LOCAL_REJECTION_BANK_NOTE_MIN = 20;

const parseTosighConfirmCode = (raw: string | null | undefined): number => {
  const s = String(raw ?? '').trim();
  if (!/^\d{1,6}$/.test(s)) {
    throw new Error('Tosigh confirmation code is required.');
  }
  const code = Number(s);
  if (!Number.isFinite(code) || code <= 0) {
    throw new Error('Tosigh confirmation code is invalid.');
  }
  return code;
};

const parseMemberId = (raw: string): number => {
  const trimmed = raw.trim();
  if (!/^\d+$/.test(trimmed)) {
    throw new Error('Member id is invalid.');
  }
  const id = Number(trimmed);
  if (!Number.isFinite(id) || id <= 0) {
    throw new Error('Member id is invalid.');
  }
  return id;
};

const assertSqlServer = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    throw new Error('Membership decisions require SQL Server control plane.');
  }
  await ensureHwyDbObjects();
};

const formatDecisionNote = async (
  decisionReasonCode: string | null | undefined,
  decisionNote: string,
): Promise<string> => {
  const reasonCode = String(decisionReasonCode ?? '').trim();
  if (!reasonCode) {
    return decisionNote;
  }
  const reasonTitle = await resolveHwyBaseInfoItemTitle(reasonCode);
  const prefix = reasonTitle?.trim() ? `${reasonTitle.trim()}: ` : '';
  return `${prefix}${decisionNote}`.slice(0, NOTE_MAX);
};

const readHistorySnapshot = async (memberId: number) => {
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<Record<string, unknown>>(
    `SELECT ${HWY_MEMBER_HISTORY_SNAPSHOT_SQL} FROM dbo.hwy_members WHERE id = :id`,
    { replacements: { id: memberId }, type: QueryTypes.SELECT },
  );
  return rows[0] ? hwyMemberRowToHistorySnapshot(rows[0]) : null;
};

const buildMemberActivationPassword = (): string => String(10_000 + crypto.randomInt(90_000));

const parseClearReferrer = (raw: boolean | null | undefined): boolean | null => {
  if (raw === true) {
    return true;
  }
  if (raw === false) {
    return false;
  }
  return null;
};

const runDecision = async (input: {
  memberId: number;
  stage: 'call_center' | 'local';
  action: string;
  decisionReasonCode: string | null;
  decisionNote: string;
  actorUserId: number | null;
  tosighConfirmCode?: number | null;
  clearReferrer?: boolean | null;
  replaceReferrerUsername?: string | null;
  replaceReferrerRelationId?: number | null;
}): Promise<{ memberId: string; membershipStatusCode: string; assignedUsername?: string }> => {
  const beforeSnapshot = await readHistorySnapshot(input.memberId);
  const note = await formatDecisionNote(input.decisionReasonCode, input.decisionNote);
  const procArgs: Record<string, unknown> = {
    member_id: input.memberId,
    action: input.action,
    decision_reason_code: input.decisionReasonCode,
    decision_note: note,
    actor_user_id: input.actorUserId,
  };
  if (input.stage === 'local' && input.action === 'approve') {
    procArgs.password_hash = await hashPassword(buildMemberActivationPassword());
    procArgs.tosigh_confirm_code = input.tosighConfirmCode ?? null;
  }
  if (input.stage === 'call_center') {
    const clearReferrer = parseClearReferrer(input.clearReferrer);
    procArgs.clear_referrer = clearReferrer === null ? null : (clearReferrer ? 1 : 0);
    const replaceUsername = String(input.replaceReferrerUsername ?? '').trim();
    if (replaceUsername) {
      procArgs.replace_referrer_username = replaceUsername;
      procArgs.replace_referrer_relation_id = input.replaceReferrerRelationId ?? null;
    }
  }
  const rows = input.stage === 'call_center'
    ? await execHwyProcedure<{ memberId: string; membershipStatusCode: string }>(
      'hwy_membership_apply_call_center_decision',
      procArgs,
    )
    : await execHwyProcedure<{ memberId: string; membershipStatusCode: string; assignedUsername?: string | null }>(
      'hwy_membership_apply_local_decision',
      procArgs,
    );
  const row = rows[0];
  if (!row?.memberId) {
    throw new Error('Could not save membership decision.');
  }
  const afterSnapshot = await readHistorySnapshot(input.memberId);
  if (beforeSnapshot && afterSnapshot) {
    await emitHwyMemberDirectoryPatchHistory({
      memberId: input.memberId,
      before: beforeSnapshot,
      after: afterSnapshot,
      actorUserId: input.actorUserId,
    });
  }
  await invalidateHwyMemberDirectoryListCache();
  const assignedUsername = 'assignedUsername' in row
    ? String(row.assignedUsername ?? '').trim() || undefined
    : undefined;
  return {
    memberId: String(row.memberId),
    membershipStatusCode: String(row.membershipStatusCode ?? ''),
    ...(assignedUsername ? { assignedUsername } : {}),
  };
};

export const applyHwyMembershipCallCenterDecision = async (input: {
  memberIdRaw: string;
  action: HwyMembershipCallCenterAction;
  decisionReasonCode?: string | null;
  decisionNote: string;
  actorUserId: number | null;
  clearReferrer?: boolean | null;
  replaceReferrerUsername?: string | null;
  replaceReferrerRelationId?: number | null;
}): Promise<{ memberId: string; membershipStatusCode: string }> => {
  await assertSqlServer();
  const memberId = parseMemberId(input.memberIdRaw);
  const noteRequired = input.action !== 'unreject';
  const decisionNote = noteRequired
    ? trimRequired(input.decisionNote)
    : trimOptional(input.decisionNote);
  const reasonRequired = input.action === 'reject';
  const decisionReasonCode = String(input.decisionReasonCode ?? '').trim() || null;
  if (reasonRequired && !decisionReasonCode) {
    throw new Error('Decision reason is required for rejection.');
  }
  try {
    return await runDecision({
      memberId,
      stage: 'call_center',
      action: input.action,
      decisionReasonCode,
      decisionNote,
      actorUserId: input.actorUserId,
      clearReferrer: input.clearReferrer,
      replaceReferrerUsername: input.replaceReferrerUsername,
      replaceReferrerRelationId: input.replaceReferrerRelationId,
    });
  } catch (error) {
    throw mapMembershipProcError(error);
  }
};

export const applyHwyMembershipLocalDecision = async (input: {
  memberIdRaw: string;
  action: HwyMembershipLocalAction;
  decisionReasonCode?: string | null;
  decisionNote: string;
  actorUserId: number | null;
  tosighConfirmCodeRaw?: string | null;
}): Promise<{ memberId: string; membershipStatusCode: string }> => {
  await assertSqlServer();
  const memberId = parseMemberId(input.memberIdRaw);
  const reasonRequired = input.action === 'reject_final'
    || input.action === 'reject_returnable'
    || input.action === 'reject_verification_bank'
    || input.action === 'unreject';
  const noteRequired = input.action !== 'approve';
  let decisionNote = noteRequired
    ? trimRequired(input.decisionNote)
    : trimOptional(input.decisionNote);
  const decisionReasonCode = String(input.decisionReasonCode ?? '').trim() || null;
  if (reasonRequired && !decisionReasonCode) {
    throw new Error('Decision reason is required for rejection.');
  }
  if (input.action === 'reject_verification_bank' && decisionNote.length < LEGACY_LOCAL_REJECTION_BANK_NOTE_MIN) {
    throw new Error(`Decision note must be at least ${LEGACY_LOCAL_REJECTION_BANK_NOTE_MIN} characters.`);
  }
  const tosighConfirmCode = input.action === 'approve'
    ? parseTosighConfirmCode(input.tosighConfirmCodeRaw)
    : null;
  try {
    return await runDecision({
      memberId,
      stage: 'local',
      action: input.action,
      decisionReasonCode,
      decisionNote,
      actorUserId: input.actorUserId,
      tosighConfirmCode,
    });
  } catch (error) {
    throw mapMembershipProcError(error);
  }
};

const mapMembershipProcError = (error: unknown): Error => {
  const message = error instanceof Error ? error.message : String(error);
  if (message.includes('57000') || message.includes('57100') || message.includes('not found')) {
    return new Error('Member not found.');
  }
  if (message.includes('57001') || message.includes('57101') || message.includes('not pending')) {
    return new Error('Member is not in the expected membership queue.');
  }
  if (message.includes('57002') || message.includes('57102') || message.includes('reason is required')) {
    return new Error('Decision reason is required for rejection.');
  }
  if (message.includes('57003') || message.includes('57103') || message.includes('rejected queue')) {
    return new Error('Member is not in the expected rejected queue.');
  }
  if (message.includes('57106') || message.includes('Password hash is required')) {
    return new Error('Could not activate member account (missing credentials).');
  }
  if (message.includes('57107') || message.includes('No membership numbers available')) {
    return new Error('No membership numbers are available. Add numbers to the username repo and retry.');
  }
  if (message.includes('57108') || message.includes('claimed by another transaction')) {
    return new Error('Membership number allocation conflict. Retry the decision.');
  }
  if (message.includes('57109') || message.includes('Tosigh confirmation code')) {
    return new Error('Tosigh confirmation code is invalid.');
  }
  if (message.includes('57110') || message.includes('returnable local rejected')) {
    return new Error('Member is not in returnable local rejected queue.');
  }
  if (message.includes('57006') || message.includes('requires a nakhebin link')) {
    return new Error('Call center approval requires a voter roll link.');
  }
  return error instanceof Error ? error : new Error(message);
};

const REASON_CATEGORY: Record<HwyMembershipStage, Record<HwyMembershipDecisionKind, string>> = {
  call_center: {
    approve: 'Membership Call Center Approve Reason',
    reject: 'Membership Call Center Reject Reason',
    unreject: 'Membership Call Center Approve Reason',
  },
  local: {
    approve: 'Membership Local Approve Reason',
    reject: 'Membership Local Reject Reason',
    unreject: 'Membership Local Queue Return Reason',
  },
};

export const listHwyMembershipDecisionReasonOptions = async (input: {
  stage: HwyMembershipStage;
  decision: HwyMembershipDecisionKind;
  cultureId: string;
}): Promise<Array<{ value: string; label: string; shortName: string | null }>> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return [];
  }
  const categoryTitle = REASON_CATEGORY[input.stage][input.decision];
  const sequelize = getControlPlaneSequelize();
  const rows = await sequelize.query<{ id: string; title: string; shortName: string | null }>(
    `
    SELECT
      CAST(bi.id AS VARCHAR(64)) AS id,
      bi.title AS title,
      bi.short_name AS shortName
    FROM dbo.base_info bi
    INNER JOIN dbo.base_info cat ON cat.id = bi.parent_id
    WHERE cat.title = :categoryTitle AND bi.is_active = 1
    ORDER BY bi.view_order, bi.id
    `,
    { replacements: { categoryTitle }, type: QueryTypes.SELECT },
  );
  const cultureId = resolveBaseInfoCultureId(input.cultureId);
  const bundle = buildMergedCultureBundle(cultureId);
  const mapped = rows.map((row) => {
    const canonical = row.title?.trim() || '';
    const shortName = row.shortName?.trim() || null;
    const bundleLabel = resolveBaseInfoFieldFromBundle({
      cultureId,
      baseInfoId: String(row.id),
      field: 'title',
      canonical,
      bundle,
    }).trim();
    const label = resolveHwyMembershipDecisionReasonDisplayLabel({
      cultureId: input.cultureId,
      label: bundleLabel || canonical || String(row.id),
      shortName,
      translate: (key) => bundle[key]?.trim() ?? key,
    });
    return {
      value: String(row.id),
      label,
      shortName,
    };
  });
  return mapped.filter((row) => row.value && row.label);
};
