import { QueryTypes } from 'sequelize';
import { getControlPlaneSequelize } from '../../db/controlPlaneSequelize';
import { readControlPlaneProvider } from '../users/prismaHelpers';

let ensurePromise: Promise<void> | null = null;

const applyTarghinRequestsTableDdl = async (): Promise<void> => {
  const sequelize = getControlPlaneSequelize();

  await sequelize.query(
    `
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NULL
    BEGIN
      CREATE TABLE dbo.hwy_member_targhin_requests (
        id                   BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY,
        member_id            BIGINT NOT NULL,
        request_reason_code  NVARCHAR(64) NULL,
        request_note         NVARCHAR(1024) NULL,
        status_code          NVARCHAR(64) NOT NULL CONSTRAINT DF_hwy_member_targhin_requests_status DEFAULT N'pending',
        created_by           BIGINT NULL,
        created_at           DATETIME2 NOT NULL CONSTRAINT DF_hwy_member_targhin_requests_created_at DEFAULT SYSUTCDATETIME(),
        CONSTRAINT FK_hwy_member_targhin_requests_member_id FOREIGN KEY (member_id) REFERENCES dbo.hwy_members(id) ON DELETE CASCADE,
        CONSTRAINT FK_hwy_member_targhin_requests_created_by FOREIGN KEY (created_by) REFERENCES dbo.base_users(id)
      );
      CREATE INDEX IX_hwy_member_targhin_requests_member ON dbo.hwy_member_targhin_requests (member_id, created_at DESC);
    END
    `,
    { type: QueryTypes.RAW },
  );

  await sequelize.query(
    `
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'request_reason_code') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD request_reason_code NVARCHAR(64) NULL;
    END
    `,
    { type: QueryTypes.RAW },
  );

  try {
    await sequelize.query(
      `
      IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_hwy_member_targhin_requests_reason_code'
        )
      BEGIN
        ALTER TABLE dbo.hwy_member_targhin_requests WITH NOCHECK
          ADD CONSTRAINT FK_hwy_member_targhin_requests_reason_code
          FOREIGN KEY (request_reason_code) REFERENCES dbo.base_info(id);
      END
      `,
      { type: QueryTypes.RAW },
    );
  } catch {
    // Optional FK — dossier change log does not require it.
  }

  await sequelize.query(
    `
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'legacy_targhin_history_id') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD legacy_targhin_history_id UNIQUEIDENTIFIER NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'final_reason_code') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD final_reason_code NVARCHAR(64) NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'final_note') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD final_note NVARCHAR(1024) NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'final_by') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD final_by BIGINT NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'final_at') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD final_at DATETIME2 NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'request_by_legacy') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD request_by_legacy NVARCHAR(256) NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND COL_LENGTH(N'dbo.hwy_member_targhin_requests', N'final_by_legacy') IS NULL
    BEGIN
      ALTER TABLE dbo.hwy_member_targhin_requests ADD final_by_legacy NVARCHAR(256) NULL;
    END
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM sys.indexes
        WHERE name = N'IX_hwy_member_targhin_requests_status_created'
          AND object_id = OBJECT_ID(N'dbo.hwy_member_targhin_requests')
      )
    BEGIN
      CREATE INDEX IX_hwy_member_targhin_requests_status_created
        ON dbo.hwy_member_targhin_requests (status_code, created_at DESC);
    END
    `,
    { type: QueryTypes.RAW },
  );

  try {
    await sequelize.query(
      `
      IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_hwy_member_targhin_requests_final_by'
        )
      BEGIN
        ALTER TABLE dbo.hwy_member_targhin_requests WITH NOCHECK
          ADD CONSTRAINT FK_hwy_member_targhin_requests_final_by
          FOREIGN KEY (final_by) REFERENCES dbo.base_users(id);
      END
      IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_hwy_member_targhin_requests_final_reason_code'
        )
      BEGIN
        ALTER TABLE dbo.hwy_member_targhin_requests WITH NOCHECK
          ADD CONSTRAINT FK_hwy_member_targhin_requests_final_reason_code
          FOREIGN KEY (final_reason_code) REFERENCES dbo.base_info(id);
      END
      `,
      { type: QueryTypes.RAW },
    );
  } catch {
    // Optional FKs for ETL rows with unresolved vocab.
  }

  await sequelize.query(
    `
    IF OBJECT_ID(N'dbo.hwy_member_targhin_requests', N'U') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM sys.indexes
        WHERE name = N'UX_hwy_member_targhin_requests_legacy_history_id'
          AND object_id = OBJECT_ID(N'dbo.hwy_member_targhin_requests')
      )
    BEGIN
      CREATE UNIQUE INDEX UX_hwy_member_targhin_requests_legacy_history_id
        ON dbo.hwy_member_targhin_requests (legacy_targhin_history_id)
        WHERE legacy_targhin_history_id IS NOT NULL;
    END
    `,
    { type: QueryTypes.RAW },
  );

  await sequelize.query(
    `
    IF OBJECT_ID(N'dbo.hwy_member_targhin_nego_notes', N'U') IS NULL
    BEGIN
      CREATE TABLE dbo.hwy_member_targhin_nego_notes (
        id                   BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY,
        member_id            BIGINT NOT NULL,
        note                 NVARCHAR(4000) NOT NULL,
        created_by_legacy    NVARCHAR(64) NOT NULL,
        created_by_user_id   BIGINT NULL,
        created_at           DATETIME2 NOT NULL CONSTRAINT DF_hwy_member_targhin_nego_notes_created_at DEFAULT SYSUTCDATETIME(),
        legacy_nego_note_id  INT NULL,
        CONSTRAINT FK_hwy_member_targhin_nego_notes_member_id FOREIGN KEY (member_id) REFERENCES dbo.hwy_members(id) ON DELETE CASCADE
      );
      CREATE INDEX IX_hwy_member_targhin_nego_notes_member
        ON dbo.hwy_member_targhin_nego_notes (member_id, created_at DESC, id DESC);
    END
    `,
    { type: QueryTypes.RAW },
  );
};

/** Idempotent DDL for dossier satellite tables (targhin requests, …). */
export const ensureHwyMemberDossierSatellitesSchema = async (): Promise<void> => {
  if (readControlPlaneProvider() !== 'sqlserver') {
    return;
  }

  if (!ensurePromise) {
    ensurePromise = applyTarghinRequestsTableDdl().catch((error: unknown) => {
      ensurePromise = null;
      throw error;
    });
  }

  await ensurePromise;
};
