import type { ConnectionPool } from 'mssql';
import { findHwyBaseInfoItemId } from '../hwy-phase1/seed/seedHwyBaseInfo';
import {
  buildClearanceAnswerByLegacyIdMap,
  buildNakhebinLinkTypeByLegacyIdMap,
  buildTasjilStateByLegacyIdMap,
} from './hwyEtlBaseVocab';
import {
  LEGACY_GENDER_TO_PLATFORM_ID,
  LEGACY_MEMBERSHIP_STATUS_TO_SHORT,
} from './legacyMaps';
import { LEGACY_DEVICE_OS_TYPE_ID_TO_REGISTRATION_CHANNEL } from '../../src/domain/hwy/hwyRegistrationChannel';

export type SampleVocab = {
  membershipStatusByLegacyId: Map<number, string>;
  genderByLegacyId: Map<number, string>;
  clearanceAnswerByLegacyId: Map<number, string>;
  tasjilStateByLegacyId: Map<number, string>;
  nakhebinLinkTypeByLegacyId: Map<number, string>;
  instituteStatus: {
    active: string;
    pendingInvite: string;
  };
  joinPath: {
    invite: string;
    admin: string;
    selfRegistration: string;
  };
  fileKind: {
    personalPhoto: string;
    nationalCardFront: string;
    nationalCardBack: string;
    voterCardFront: string;
    residenceCardFront: string;
    oathDocument: string;
    secondNationalityDocument: string;
    otherAttachment: string;
  };
  noteSubject: {
    general: string;
    membership: string;
    callCenter: string;
  };
  securityClearance: {
    allowed: string;
    denied: string;
    underReview: string;
    conditional: string;
  };
  registrationChannelByLegacyDeviceOsId: Map<number, string>;
};

export const resolveSampleVocab = async (legacy?: ConnectionPool): Promise<SampleVocab> => {
  const membershipStatusByLegacyId = new Map<number, string>();
  for (const [legacyId, shortName] of Object.entries(LEGACY_MEMBERSHIP_STATUS_TO_SHORT)) {
    const code = await findHwyBaseInfoItemId('Membership Status', shortName);
    membershipStatusByLegacyId.set(Number(legacyId), code);
  }

  const clearanceAnswerByLegacyId = await buildClearanceAnswerByLegacyIdMap(legacy);
  const tasjilStateByLegacyId = await buildTasjilStateByLegacyIdMap(legacy);
  const nakhebinLinkTypeByLegacyId = await buildNakhebinLinkTypeByLegacyIdMap(legacy);

  const genderByLegacyId = new Map<number, string>(
    Object.entries(LEGACY_GENDER_TO_PLATFORM_ID).map(([k, v]) => [Number(k), v]),
  );

  const registrationChannelByLegacyDeviceOsId = new Map<number, string>();
  for (const [legacyId, shortName] of Object.entries(LEGACY_DEVICE_OS_TYPE_ID_TO_REGISTRATION_CHANNEL)) {
    const code = await findHwyBaseInfoItemId('Registration Channel', shortName);
    registrationChannelByLegacyDeviceOsId.set(Number(legacyId), code);
  }

  const [
    instituteActive,
    institutePending,
    joinInvite,
    joinAdmin,
    joinSelf,
    photoKind,
    cardFrontKind,
    cardBackKind,
    voterCardKind,
    residenceCardKind,
    oathDocumentKind,
    secondNationalityKind,
    otherAttachmentKind,
    noteGeneral,
    noteMembership,
    noteCallCenter,
    secAllowed,
    secDenied,
    secReview,
    secConditional,
  ] = await Promise.all([
    findHwyBaseInfoItemId('Institute Membership Status', 'active'),
    findHwyBaseInfoItemId('Institute Membership Status', 'pending_invite'),
    findHwyBaseInfoItemId('Institute Join Path', 'invite'),
    findHwyBaseInfoItemId('Institute Join Path', 'admin'),
    findHwyBaseInfoItemId('Institute Join Path', 'self_registration'),
    findHwyBaseInfoItemId('Member File Kind', 'personal_photo'),
    findHwyBaseInfoItemId('Member File Kind', 'national_card_front'),
    findHwyBaseInfoItemId('Member File Kind', 'national_card_back'),
    findHwyBaseInfoItemId('Member File Kind', 'voter_card_front'),
    findHwyBaseInfoItemId('Member File Kind', 'residence_card_front'),
    findHwyBaseInfoItemId('Member File Kind', 'oath_document'),
    findHwyBaseInfoItemId('Member File Kind', 'second_nationality_document'),
    findHwyBaseInfoItemId('Member File Kind', 'other_attachment'),
    findHwyBaseInfoItemId('Member Note Subject', 'general'),
    findHwyBaseInfoItemId('Member Note Subject', 'membership'),
    findHwyBaseInfoItemId('Member Note Subject', 'call_center'),
    findHwyBaseInfoItemId('Security Clearance Answer', 'allowed'),
    findHwyBaseInfoItemId('Security Clearance Answer', 'denied'),
    findHwyBaseInfoItemId('Security Clearance Answer', 'under_review'),
    findHwyBaseInfoItemId('Security Clearance Answer', 'conditional'),
  ]);

  return {
    membershipStatusByLegacyId,
    genderByLegacyId,
    clearanceAnswerByLegacyId,
    tasjilStateByLegacyId,
    nakhebinLinkTypeByLegacyId,
    instituteStatus: { active: instituteActive, pendingInvite: institutePending },
    joinPath: { invite: joinInvite, admin: joinAdmin, selfRegistration: joinSelf },
    fileKind: {
      personalPhoto: photoKind,
      nationalCardFront: cardFrontKind,
      nationalCardBack: cardBackKind,
      voterCardFront: voterCardKind,
      residenceCardFront: residenceCardKind,
      oathDocument: oathDocumentKind,
      secondNationalityDocument: secondNationalityKind,
      otherAttachment: otherAttachmentKind,
    },
    noteSubject: {
      general: noteGeneral,
      membership: noteMembership,
      callCenter: noteCallCenter,
    },
    securityClearance: {
      allowed: secAllowed,
      denied: secDenied,
      underReview: secReview,
      conditional: secConditional,
    },
    registrationChannelByLegacyDeviceOsId,
  };
};
