import { HWY_MEMBER_SEGMENT_LIST_DEFINITIONS } from './hwyMemberSegmentListCatalog';
import { resolveHwyMemberListInstituteId } from './hwyMemberInstituteCodes';
import { hwyMontadheminInstituteFilterOptionLabelKey } from './hwyMontadheminInstituteFilterLabels';

export type HwyMontadheminInstituteFilterOption = {
  value: string;
  labelKey: string;
  labelFallback: string;
};

/** Registered-members list — institute multi-filter (legacy toolbar parity). */
export const buildHwyMontadheminInstituteFilterSelectOptions = (): HwyMontadheminInstituteFilterOption[] => (
  HWY_MEMBER_SEGMENT_LIST_DEFINITIONS
    .filter((def) => def.scope.type === 'active_institute')
    .map((def) => {
      const instituteCode = def.scope.type === 'active_institute' ? def.scope.instituteCode : '';
      const instituteId = resolveHwyMemberListInstituteId(instituteCode);
      if (!instituteId) {
        return null;
      }
      return {
        value: String(instituteId),
        labelKey: hwyMontadheminInstituteFilterOptionLabelKey(instituteCode),
        labelFallback: def.titleEn.replace(/^Registered — /, ''),
      };
    })
    .filter((item): item is HwyMontadheminInstituteFilterOption => item != null)
);

export const HWY_MONTADHEMIN_INSTITUTE_FILTER_STORE_PATH = 'gridToolbar.filters.montadheminInstituteId';
export const HWY_MONTADHEMIN_INSTITUTE_MATCH_STORE_PATH = 'gridToolbar.filters.montadheminInstituteIdMatch';
