/** Legacy membership status — no longer used in lists or ETL. */
export const HWY_DEPRECATED_MEMBERSHIP_STATUS_SHORT_NAMES = ['pre_call_center'] as const;

export const isDeprecatedHwyMembershipStatusShortName = (
  shortName: string | null | undefined,
): boolean => {
  const normalized = shortName?.trim() ?? '';
  return (HWY_DEPRECATED_MEMBERSHIP_STATUS_SHORT_NAMES as readonly string[]).includes(normalized);
};
