export type HwyMemberDossierLabels = Record<HwyMemberDossierLabelKey, string>;

const EN_BY_PROP = buildHwyMemberDossierUiKeysEn();

function resolveDossierLabel(
  t: TranslationFn | undefined,
  cultureKey: string,
  englishFallback: string,
): string {
  if (!t) {
    return englishFallback;
  }
  const translated = t(cultureKey, { missing: 'silent' });
  return translated !== cultureKey && translated.trim() !== '' ? translated : englishFallback;
}

export function resolveHwyMemberDossierBackChrome(
  returnList: string | null,
  labels: HwyMemberDossierLabels,
): Pick<HwyMemberDossierLabels, 'backAria' | 'backTitle' | 'backToList'> {
  if (returnList === 'members-targhin') {
    return {
      backAria: labels.backToTarghinMembersAria,
      backTitle: labels.backToTarghinMembersTitle,
      backToList: labels.backToTarghinMembersList,
    };
  }
  return {
    backAria: labels.backAria,
    backTitle: labels.backTitle,
    backToList: labels.backToList,
  };
}

export function resolveHwyMemberDossierLabels(t?: TranslationFn): HwyMemberDossierLabels {
  const labels = {} as HwyMemberDossierLabels;
  (Object.keys(HWY_MEMBER_DOSSIER_LABEL_KEYS) as HwyMemberDossierLabelKey[]).forEach((prop) => {
    const key = HWY_MEMBER_DOSSIER_LABEL_KEYS[prop];
    const fallback = EN_BY_PROP[key] ?? key;
    labels[prop] = resolveDossierLabel(t, key, fallback);
  });
  return labels;
}

export type DossierVoteKind = 'voted' | 'notVoted' | 'unknown';

const DOSSIER_VOTE_PARTICIPATED_TOKENS = new Set([
  '1',
  'true',
  'yes',
  'y',
  'voted',
  'participated',
  'نعم',
  'صوت',
  'صوّت',
  'شارك',
  'شرکت',
  'شرکت کرده',
  'رأی داده',
]);

const DOSSIER_VOTE_NOT_PARTICIPATED_TOKENS = new Set([
  '0',
  'false',
  'no',
  'n',
  'did not vote',
  'did not participate',
  'not voted',
  'لا',
  'لم يصوت',
  'لم يصوّت',
  'لم يشارك',
  'شرکت نکرده',
  'رأی نداده',
]);

const normalizeDossierVoteToken = (value: unknown): string => (
  String(value).trim().replace(/\s+/g, ' ')
);

const DOSSIER_VOTE_EMPTY_TOKENS = new Set(['-', '—', '--']);

export function resolveDossierVoteKind(value: unknown): DossierVoteKind {
  if (value === null || value === undefined || value === '') {
    return 'unknown';
  }
  const trimmedToken = normalizeDossierVoteToken(value);
  if (DOSSIER_VOTE_EMPTY_TOKENS.has(trimmedToken)) {
    return 'unknown';
  }
  if (value === true || value === 1 || value === '1' || value === 'true') {
    return 'voted';
  }
  if (value === false || value === 0 || value === '0' || value === 'false') {
    return 'notVoted';
  }
  const token = normalizeDossierVoteToken(value);
  const lowered = token.toLowerCase();
  if (DOSSIER_VOTE_PARTICIPATED_TOKENS.has(token) || DOSSIER_VOTE_PARTICIPATED_TOKENS.has(lowered)) {
    return 'voted';
  }
  if (DOSSIER_VOTE_NOT_PARTICIPATED_TOKENS.has(token) || DOSSIER_VOTE_NOT_PARTICIPATED_TOKENS.has(lowered)) {
    return 'notVoted';
  }
  return 'unknown';
}

export function resolveDossierVoteLabel(
  value: unknown,
  labels: Pick<HwyMemberDossierLabels, 'voteVoted' | 'voteNotVoted' | 'voteNotRecorded' | 'emptyValue'>,
): string {
  const kind = resolveDossierVoteKind(value);
  if (kind === 'voted') {
    return labels.voteVoted;
  }
  if (kind === 'notVoted') {
    return labels.voteNotVoted;
  }
  return labels.voteNotRecorded;
}

/** Short label beside the participation icon (uses em dash when data is missing). */
export function resolveDossierVoteDisplayLabel(
  value: unknown,
  labels: Pick<HwyMemberDossierLabels, 'voteVoted' | 'voteNotVoted' | 'emptyValue'>,
): string {
  const kind = resolveDossierVoteKind(value);
  if (kind === 'voted') {
    return labels.voteVoted;
  }
  if (kind === 'notVoted') {
    return labels.voteNotVoted;
  }
  return labels.emptyValue;
}

export function formatDossierDisplayScalar(
  value: unknown,
  labels: Pick<HwyMemberDossierLabels, 'valueYes' | 'valueNo' | 'emptyValue'>,
): string {
  if (value === null || value === undefined) {
    return labels.emptyValue;
  }
  if (typeof value === 'boolean') {
    return value ? labels.valueYes : labels.valueNo;
  }
  const text = String(value).trim();
  return text.length > 0 ? text : labels.emptyValue;
}
