/** Discriminator on `hwy_geo_responsibility_requests` — nomination vs official removal. */
export const HWY_GEO_RESPONSIBILITY_REQUEST_KINDS = [
  'nomination',
  'official_removal',
] as const;

export type HwyGeoResponsibilityRequestKind =
  (typeof HWY_GEO_RESPONSIBILITY_REQUEST_KINDS)[number];

export const HWY_GEO_RESPONSIBILITY_REQUEST_KIND_NOMINATION: HwyGeoResponsibilityRequestKind =
  'nomination';

export const HWY_GEO_RESPONSIBILITY_REQUEST_KIND_OFFICIAL_REMOVAL: HwyGeoResponsibilityRequestKind =
  'official_removal';

export const isHwyGeoResponsibilityRequestKind = (
  value: string,
): value is HwyGeoResponsibilityRequestKind => (
  (HWY_GEO_RESPONSIBILITY_REQUEST_KINDS as readonly string[]).includes(value)
);

export const isHwyGeoResponsibilityOfficialRemovalRequestKind = (
  kind: string | null | undefined,
): boolean => kind === HWY_GEO_RESPONSIBILITY_REQUEST_KIND_OFFICIAL_REMOVAL;

/** Approved rows that still hold the patch assignment (excludes approved removal decisions). */
export const hwyGeoResponsibilitySqlActiveNominationAssignment = (tableAlias: string): string =>
  `${tableAlias}.request_kind = N'${HWY_GEO_RESPONSIBILITY_REQUEST_KIND_NOMINATION}'`;
