const trim = (value: string | null | undefined): string => String(value ?? '').trim();

/** Allocated Hawiety membership / login number (username repo). */
export const HWY_ALLOCATED_MEMBERSHIP_USERNAME_LEN = 6;

export const HWY_ALLOCATED_MEMBERSHIP_USERNAME_PATTERN = /^\d{6}$/;

export const isHwyAllocatedMembershipUsernameFormat = (value: string): boolean => (
  HWY_ALLOCATED_MEMBERSHIP_USERNAME_PATTERN.test(trim(value))
);

/** True when value is tracking / ETL placeholder (member pk), not allocated legacy UserName. */
export const isHwyMembershipUsernamePlaceholder = (
  value: string,
  memberId: string | number | null | undefined,
): boolean => {
  const username = trim(value);
  if (!username) {
    return false;
  }
  const memberKey = trim(memberId != null ? String(memberId) : '');
  if (memberKey && username === memberKey) {
    return true;
  }
  const match = /^m(\d+)$/i.exec(username);
  if (memberKey && match && trim(match[1]) === memberKey) {
    return true;
  }
  const hwyMatch = /^hwy-m-(\d+)$/i.exec(username);
  if (memberKey && hwyMatch && trim(hwyMatch[1]) === memberKey) {
    return true;
  }
  return false;
};

/** Allocated membership UserName only — never member Id / m{id} placeholders. */
export const resolveHwyAllocatedMembershipUsername = (
  rawUsername: string | null | undefined,
  memberId: string | number | null | undefined,
): string | null => {
  const username = trim(rawUsername);
  if (!username || isHwyMembershipUsernamePlaceholder(username, memberId)) {
    return null;
  }
  if (!isHwyAllocatedMembershipUsernameFormat(username)) {
    return null;
  }
  return username;
};

const MEMBER_ROW_USERNAME_KEYS = [
  'username',
  'userUsername',
  'user_username',
] as const;

/** Best allocated username on a member-directory row (list / dossier / geo face). */
export const resolveHwyMemberRowAllocatedUsername = (
  row: Record<string, unknown>,
  memberId?: string | number | null | undefined,
): string | null => {
  const id = memberId ?? row.id ?? row.memberId ?? row.member_id;
  for (const key of MEMBER_ROW_USERNAME_KEYS) {
    const raw = row[key];
    const allocated = resolveHwyAllocatedMembershipUsername(
      raw == null ? '' : String(raw),
      id,
    );
    if (allocated) {
      return allocated;
    }
  }
  return null;
};

const MEMBER_DIRECTORY_USERNAME_ROW_KEYS = [
  'username',
  'userUsername',
  'user_username',
] as const;

/** Remove SQL/ETL noise so legacy + CP attach can fill allocated six-digit usernames. */
export const clearNonAllocatedHwyMemberDirectoryUsernameFields = (
  rows: Record<string, unknown>[],
): void => {
  for (const row of rows) {
    const memberId = row.id ?? row.memberId ?? row.member_id;
    for (const key of MEMBER_DIRECTORY_USERNAME_ROW_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(row, key)) {
        continue;
      }
      const raw = row[key];
      if (raw == null || raw === '') {
        continue;
      }
      if (!resolveHwyAllocatedMembershipUsername(String(raw), memberId)) {
        row[key] = '';
      }
    }
  }
};

/** Keep only allocated six-digit username on list rows (face caption contract). */
export const normalizeHwyMemberDirectoryRowsForFaceCaption = (
  rows: Record<string, unknown>[],
): void => {
  for (const row of rows) {
    const memberId = row.id ?? row.memberId ?? row.member_id;
    const allocated = resolveHwyMemberRowAllocatedUsername(row, memberId);
    if (allocated) {
      row.username = allocated;
      continue;
    }
    if (Object.prototype.hasOwnProperty.call(row, 'username')) {
      row.username = '';
    }
  }
};
