/**
 * Keep in sync with scripts/hwy-phase1/db/install/hwy_candidate_pipeline.sqlserver.sql
 * and hwy_card_flow.sqlserver.sql where-clause functions (legacy read-only fallback only).
 */

import type { HwyCandidatePipelineStage } from '../../../domain/hwy/hwyCandidatePipelineCatalog';
import type { HwyCardFlowStep } from '../../../domain/hwy/hwyCardFlowCatalog';

const esc = (value: string): string => value.replace(/'/g, "''");

export type HwyCandidatePipelineWhereInput = {
  stage: HwyCandidatePipelineStage;
  listType?: string | null;
  roleId?: string | null;
  isApproved?: string | null;
  approveState?: string | null;
  passedOrNot?: string | null;
  interviewApproveState?: string | null;
  scopeUnrestricted: boolean;
  nakhebProvinceId?: number | null;
  nakhebCircleId?: number | null;
  nakhebTamvinId?: number | null;
  dateStart?: string | null;
  dateEnd?: string | null;
  username?: string | null;
  phone?: string | null;
  genderId?: string | null;
  actorUserName?: string | null;
  areaLimitId?: number | null;
  geoLimitsCsv?: string | null;
};

export const buildHwyCandidatePipelineWhereSql = (
  input: HwyCandidatePipelineWhereInput,
  alias = 'V',
): string => {
  let w = '';
  const st = input.stage;
  let lt = input.listType?.trim() || null;
  const rid = input.roleId?.trim() || null;

  if (st === 'security') {
    if (!lt) lt = 'WaitForInitialVoteMembers';
    if (lt === 'WaitForInitialVoteMembers') {
      w += ` AND ((SELECT COUNT(*) FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id)=0 OR (SELECT TOP 1 SP.can_get_masooliat FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211753)`;
    } else if (lt === 'RejectedMembers') {
      w += ` AND (SELECT TOP 1 SP.can_get_masooliat FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211752`;
    } else if (lt === 'AcceptedMembers') {
      w += ` AND (SELECT TOP 1 SP.can_get_masooliat FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
    }
    const isApproved = input.isApproved?.trim();
    if (isApproved && /^-?\d+$/.test(isApproved)) {
      w += ` AND ${alias}.IsApproved=${isApproved}`;
    }
    if (rid) {
      w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.user_id AND URR.RoleId=${rid})`;
    }
  } else if (st === 'interview') {
    if (!lt) lt = 'NotInterviewed';
    if (lt === 'NotInterviewed') w += ` AND ${alias}.InterviewOn IS NULL`;
    else if (lt === 'Interviewed') w += ` AND ${alias}.InterviewOn IS NOT NULL`;
    const ias = input.interviewApproveState?.trim();
    if (ias && ias !== 'All') {
      w += ` AND ${alias}.InterviewFinalResult='${esc(ias)}'`;
    }
    const approveState = input.approveState?.trim();
    if (approveState && approveState !== '-1') {
      w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.user_id AND URR.RoleId=${alias}.RoleId AND URR.RoleId IN (1000004,1000005) AND URR.Approved=${approveState})`;
    }
    if (rid) w += ` AND ${alias}.RoleId=${rid}`;
  } else if (st === 'courses') {
    if (!lt) lt = 'NotPassed';
    if (lt === 'NotPassed') w += ` AND COALESCE(${alias}.PassedNecessaryDorat, 0)=0`;
    else if (lt === 'Passed') w += ` AND COALESCE(${alias}.PassedNecessaryDorat, 0)=1`;
    if (rid) {
      w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.user_id AND URR.RoleId=${rid})`;
    }
    const approveState = input.approveState?.trim();
    if (approveState && approveState !== '-1') {
      w += ` AND (SELECT TOP 1 URR.Approved FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.RoleId IN (1000004,1000005) AND URR.UserId=${alias}.UserId)=${approveState}`;
    }
  } else if (st === 'install') {
    w += ` AND ${alias}.SecurityStatus=211751`;
    let pon = input.passedOrNot?.trim() || '-1';
    if (pon !== '-1') w += ` AND ${alias}.NecessaryDoratPassed=${pon}`;
    if (rid) {
      w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.user_id AND URR.RoleId=${rid})`;
    }
  }

  const tarshihProv = `(SELECT TOP 1 A.HWY_StateId FROM dbo.hwy_member_area_limits AL WITH (NOLOCK) LEFT JOIN dbo.HWY_VW_H_AllArea A ON A.AreaId=AL.item_id WHERE AL.member_id=${alias}.id AND AL.approved=1 ORDER BY AL.id DESC)`;
  const tarshihCircle = `(SELECT TOP 1 A.CircleId FROM dbo.hwy_member_area_limits AL WITH (NOLOCK) LEFT JOIN dbo.HWY_VW_H_AllArea A ON A.AreaId=AL.item_id WHERE AL.member_id=${alias}.id AND AL.approved=1 ORDER BY AL.id DESC)`;
  const tarshihTamvin = `(SELECT TOP 1 A.TamvinId FROM dbo.hwy_member_area_limits AL WITH (NOLOCK) LEFT JOIN dbo.HWY_VW_H_AllArea A ON A.AreaId=AL.item_id WHERE AL.member_id=${alias}.id AND AL.approved=1 ORDER BY AL.id DESC)`;

  if (input.nakhebProvinceId != null) {
    w += st === 'interview' || st === 'courses' || st === 'install'
      ? ` AND ${tarshihProv}=${input.nakhebProvinceId}`
      : ` AND ${alias}.NakhebJoinProvinceId=${input.nakhebProvinceId}`;
  }
  if (input.nakhebCircleId != null) {
    w += st === 'interview' || st === 'courses' || st === 'install'
      ? ` AND ${tarshihCircle}=${input.nakhebCircleId}`
      : ` AND ${alias}.NakhebJoinCircleId=${input.nakhebCircleId}`;
  }
  if (input.nakhebTamvinId != null) {
    w += st === 'interview' || st === 'courses' || st === 'install'
      ? ` AND ${tarshihTamvin}=${input.nakhebTamvinId}`
      : ` AND ${alias}.NakhebJoinTamvinId=${input.nakhebTamvinId}`;
  }

  const dateStart = input.dateStart?.trim();
  if (dateStart) w += ` AND ${alias}.DateOfTarshih >= '${esc(dateStart)} 00:00'`;
  const dateEnd = input.dateEnd?.trim();
  if (dateEnd) w += ` AND ${alias}.DateOfTarshih <= '${esc(dateEnd)} 23:59'`;

  const username = input.username?.trim();
  if (username) w += ` AND ${alias}.UserName LIKE '%' + '${esc(username)}' + '%'`;
  const phone = input.phone?.trim();
  if (phone) w += ` AND ${alias}.Phone1 LIKE '%' + '${esc(phone)}' + '%'`;
  const genderId = input.genderId?.trim();
  if (genderId) w += ` AND ${alias}.GenderId=${genderId}`;

  const actor = input.actorUserName?.trim();
  if (actor && st === 'security') {
    if (actor.endsWith(',0')) {
      w += ` AND ${alias}.MoarasshehOfTarshih='${esc(actor.slice(0, -2))}'`;
    } else if (actor.endsWith(',1')) {
      w += ` AND ${alias}.ApprovedBy='${esc(actor.slice(0, -2))}'`;
    } else {
      w += ` AND (${alias}.MoarasshehOfTarshih LIKE '%' + '${esc(actor)}' + '%' OR ${alias}.ApprovedBy LIKE '%' + '${esc(actor)}' + '%')`;
    }
  }

  if (!input.scopeUnrestricted && input.areaLimitId != null && input.geoLimitsCsv?.trim()) {
    const geoCsv = input.geoLimitsCsv.trim();
    if (input.areaLimitId === 111321) {
      /* no geo filter */
    } else {
      let geo = ' AND (1=0';
      if (input.areaLimitId === 111322) {
        geo += st === 'interview' || st === 'courses' || st === 'install'
          ? ` OR ${tarshihProv} IN (${geoCsv})`
          : ` OR ${alias}.NakhebJoinProvinceId IN (${geoCsv})`;
      } else if (input.areaLimitId === 111325) {
        geo += st === 'interview' || st === 'courses' || st === 'install'
          ? ` OR ${tarshihCircle} IN (${geoCsv})`
          : ` OR ${alias}.NakhebJoinCircleId IN (${geoCsv})`;
      } else if (input.areaLimitId === 111323) {
        geo += st === 'interview' || st === 'courses' || st === 'install'
          ? ` OR ${tarshihTamvin} IN (${geoCsv})`
          : ` OR ${alias}.NakhebJoinTamvinId IN (${geoCsv})`;
      } else if (input.areaLimitId === 111324) {
        geo += ` OR ${alias}.NakhebJoinEghteraId IN (${geoCsv})`;
      }
      if (geo !== ' AND (1=0') w += `${geo})`;
    }
  }

  return w;
};

const cardFlowGeoOr = (
  alias: string,
  areaLimitId: number | null | undefined,
  geoLimitsCsv: string | null | undefined,
): string => {
  if (areaLimitId == null || !geoLimitsCsv?.trim()) return '';
  if (areaLimitId === 111321) return '';
  let geo = ' AND (1=0';
  if (areaLimitId === 111322) geo += ` OR ${alias}.nakheb_join_province_id IN (${geoLimitsCsv.trim()})`;
  else if (areaLimitId === 111325) geo += ` OR ${alias}.nakheb_join_circle_id IN (${geoLimitsCsv.trim()})`;
  else if (areaLimitId === 111323) geo += ` OR ${alias}.nakheb_join_tamvin_id IN (${geoLimitsCsv.trim()})`;
  else if (areaLimitId === 111324) geo += ` OR ${alias}.nakheb_join_eghtera_id IN (${geoLimitsCsv.trim()})`;
  return `${geo})`;
};

export type HwyCardFlowWhereInput = {
  step: HwyCardFlowStep;
  listType?: string | null;
  visibility?: string | null;
  roleId?: string | null;
  username?: string | null;
  phone?: string | null;
  scopeUnrestricted: boolean;
  areaLimitId?: number | null;
  geoLimitsCsv?: string | null;
  nakhebProvinceId?: number | null;
  nakhebCircleId?: number | null;
  nakhebTamvinId?: number | null;
};

export const buildHwyCardFlowWhereSql = (input: HwyCardFlowWhereInput, alias = 'M'): string => {
  let w = '';
  const st = input.step;
  let lt = input.listType?.trim() || null;
  const rid = input.roleId?.trim() || null;
  const latest = `(SELECT TOP 1 FS.step_id FROM dbo.hwy_member_card_printing_flow_steps FS WITH (NOLOCK) WHERE FS.member_id=${alias}.id ORDER BY FS.step_on DESC, FS.id DESC)`;

  w += ` AND ISNULL(${alias}.device_os_type_legacy_id,0)<>213991`;

  if (st === 'start') {
    if (!lt || lt.startsWith('CanStart')) {
      w += ` AND ${alias}.card_flow_last_status_id IS NULL AND ISNULL(${alias}.stat_fields_completed,0)=100`;
    } else if (lt.startsWith('Started')) {
      w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL`;
    } else {
      w += ` AND ${alias}.card_flow_last_status_id IS NULL`;
    }
  } else if (st === 'security') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.hwy_member_card_printing_flow_steps CPF WITH (NOLOCK) WHERE CPF.member_id=${alias}.id)`;
    if (!lt || lt === 'WaitForInitialVoteMembers') {
      w += ` AND ((SELECT COUNT(*) FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id)=0 OR (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211753)`;
    } else if (lt === 'RejectedMembers') {
      w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211752`;
    } else if (lt === 'AcceptedMembers') {
      w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
    }
  } else if (st === 'central') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL AND ${latest} IN (213876,213931)`;
    w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
  } else if (st === 'province') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL AND ${latest}=213888`;
    w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
  } else if (st === 'print') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL AND ${latest} IN (213877,213878)`;
    w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
  } else if (st === 'province-delivery') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL AND ${latest} IN (213879,213935)`;
    w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
  } else if (st === 'member-delivery') {
    w += ` AND ${alias}.card_flow_last_status_id IS NOT NULL`;
    w += ` AND (SELECT TOP 1 SP.can_get_identity_card FROM dbo.hwy_member_security_profile_history SP WITH (NOLOCK) WHERE SP.member_id=${alias}.id ORDER BY SP.created_on DESC)=211751`;
    if (lt) w += ` AND ${latest}=${lt}`;
    else w += ` AND ${latest}=213880`;
  }

  const visibility = input.visibility?.trim();
  if (visibility === 'visible') w += ` AND ISNULL(${alias}.card_flow_visibility,1)=1`;
  if (visibility === 'invisible') w += ` AND ISNULL(${alias}.card_flow_visibility,1)=0`;

  if (rid) {
    w += ` AND EXISTS (SELECT 1 FROM dbo.AppEnd_Users_R_Roles URR WITH (NOLOCK) WHERE URR.UserId=${alias}.user_id AND URR.RoleId=${rid})`;
  }
  if (input.nakhebProvinceId != null) w += ` AND ${alias}.nakheb_join_province_id=${input.nakhebProvinceId}`;
  if (input.nakhebCircleId != null) w += ` AND ${alias}.nakheb_join_circle_id=${input.nakhebCircleId}`;
  if (input.nakhebTamvinId != null) w += ` AND ${alias}.nakheb_join_tamvin_id=${input.nakhebTamvinId}`;

  const username = input.username?.trim();
  if (username) w += ` AND ${alias}.username LIKE '%' + '${esc(username)}' + '%'`;
  const phone = input.phone?.trim();
  if (phone) w += ` AND ${alias}.phone1 LIKE '%' + '${esc(phone)}' + '%'`;

  if (!input.scopeUnrestricted) {
    w += cardFlowGeoOr(alias, input.areaLimitId, input.geoLimitsCsv);
  }

  return w;
};
